def _merge_style_payload(target: dict[str, Any], source: Mapping[str, Any], *, override_state: bool = False) -> None:
    for key, value in source.items():
        if key == "state" and isinstance(value, Mapping):
            state = dict(target.get("state") if isinstance(target.get("state"), Mapping) else {})
            if override_state:
                _merge_state_payload_with_override(state, value)
            else:
                _merge_state_payload(state, value)
            target["state"] = state
        elif key in {"surface", "surface_overrides"} and isinstance(value, Mapping):
            surface = dict(target.get("surface_overrides") if isinstance(target.get("surface_overrides"), Mapping) else {})
            _merge_surface_overrides(surface, value)
            target["surface_overrides"] = surface
        elif key == "semantic_tags":
            tags = _string_list(target.get("semantic_tags") or target.get("tags"))
            tags.extend(_string_list(value))
            target["semantic_tags"] = _dedupe(tags)
        elif key == "material_bindings" and key not in target:
            target[key] = deepcopy(value)
        elif key not in target:
            target[key] = deepcopy(value)


def _merge_state_payload_with_override(target: dict[str, Any], source: Mapping[str, Any]) -> None:
    for key, value in source.items():
        if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
            continue
        normalized = _surface_value(value)
        if isinstance(normalized, dict) and isinstance(target.get(key), dict):
            merged = dict(target[key])
            merged.update(normalized)
            target[key] = merged
        elif isinstance(normalized, list) and isinstance(target.get(key), list):
            target[key] = _dedupe([str(item) for item in [*target[key], *normalized]])
        elif isinstance(normalized, str | int | float | bool | list | dict) or normalized is None:
            target[key] = normalized


def _merge_state_payload(target: dict[str, Any], source: Mapping[str, Any]) -> None:
    for key, value in source.items():
        if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
            continue
        normalized = _surface_value(value)
        if isinstance(normalized, dict) and isinstance(target.get(key), dict):
            merged = dict(target[key])
            merged.update(normalized)
            target[key] = merged
        elif isinstance(normalized, list) and isinstance(target.get(key), list):
            target[key] = _dedupe([str(item) for item in [*target[key], *normalized]])
        elif key not in target and (isinstance(normalized, str | int | float | bool | list | dict) or normalized is None):
            target[key] = normalized


def _lower_regions(scene: Mapping[str, Any]) -> list[dict[str, Any]]:
    regions: list[dict[str, Any]] = []
    raw_regions = _mapping_list(scene.get("regions"))
    if not raw_regions:
        raw_regions = [
            {
                "name": "region_main",
                "type": "interior",
                "values": {
                    "name": "Main Region",
                    "purpose": "primary authored scene space",
                    "mood": "neutral",
                    "bounds": {"center": [0, 0, 0], "size": [24, 8, 24]},
                },
            }
        ]
    for index, region in enumerate(raw_regions):
        values = _values(region)
        region_id = _prefixed_id("region", region.get("name"), f"region_{index}")
        region_type = _enum(_string(region.get("type")) or values.get("type"), _REGION_TYPES, default="interior")
        bounds = _bounds(values, default_center=[index * 24.0, 0.0, 0.0])
        regions.append(
            {
                "_source_name": str(region.get("name") or region_id),
                "region_id": region_id,
                "name": _string(values.get("name"), default=_display_name(region_id)),
                "type": region_type,
                "purpose": _string(values.get("purpose"), default=f"{region_type} scene region"),
                "mood": _string(values.get("mood"), default="neutral"),
                "bounds": bounds,
                "semantic_tags": _string_list(values.get("semantic_tags") or values.get("tags")),
            }
        )
    return regions


def _expanded_scene(scene: Mapping[str, Any], regions: Sequence[Mapping[str, Any]]) -> dict[str, list[Mapping[str, Any]]]:
    expansion: dict[str, list[Mapping[str, Any]]] = {
        "objects": list(_mapping_list(scene.get("objects"))),
        "sockets": list(_mapping_list(scene.get("sockets"))),
        "attachments": list(_mapping_list(scene.get("attachments"))),
        "relationships": list(_mapping_list(scene.get("relationships"))),
    }
    modules = _scene_modules_by_name(scene)
    variant_families = _scene_variant_families_by_name(scene)
    biomes = _scene_biomes_by_name(scene)
    placement_zones = _placement_zones_by_name(scene, regions)
    for environment in _mapping_list(scene.get("environments")):
        environment_objects, environment_sockets, environment_attachments, environment_relationships = _expand_environment_node(
            environment,
            biomes,
            placement_zones,
            regions,
        )
        expansion["objects"].extend(environment_objects)
        expansion["sockets"].extend(environment_sockets)
        expansion["attachments"].extend(environment_attachments)
        expansion["relationships"].extend(environment_relationships)
    for kit in _mapping_list(scene.get("kits")):
        kit_objects, kit_sockets, kit_attachments = _expand_kit_node(
            kit,
            modules,
            variant_families,
            placement_zones,
        )
        expansion["objects"].extend(kit_objects)
        expansion["sockets"].extend(kit_sockets)
        expansion["attachments"].extend(kit_attachments)
    for generator in _mapping_list(scene.get("generators")):
        generator_objects, generator_sockets, generator_attachments = _expand_generator_node(
            generator,
            modules,
            variant_families,
            placement_zones,
        )
        expansion["objects"].extend(generator_objects)
        expansion["sockets"].extend(generator_sockets)
        expansion["attachments"].extend(generator_attachments)
    for scatter in _mapping_list(scene.get("scatters")):
        scatter_objects, scatter_sockets, scatter_attachments = _expand_scatter_node(
            scatter,
            modules,
            variant_families,
            placement_zones,
            biomes,
        )
        expansion["objects"].extend(scatter_objects)
        expansion["sockets"].extend(scatter_sockets)
        expansion["attachments"].extend(scatter_attachments)
    for array in _mapping_list(scene.get("arrays")):
        expansion["objects"].extend(_expand_array_node(array))
    macro_objects, macro_relationships = _expand_scene_macro_objects(expansion["objects"])
    expansion["objects"] = macro_objects
    expansion["relationships"].extend(macro_relationships)
    return expansion


def _scene_modules_by_name(scene: Mapping[str, Any]) -> dict[str, Mapping[str, Any]]:
    modules: dict[str, Mapping[str, Any]] = {}
    for module in _mapping_list(scene.get("modules")):
        name = _string(module.get("name"))
        if name:
            modules[name] = module
    return modules


def _scene_variant_families_by_name(scene: Mapping[str, Any]) -> dict[str, Mapping[str, Any]]:
    families: dict[str, Mapping[str, Any]] = {}
    for family in _mapping_list(scene.get("variant_families")):
        name = _string(family.get("name"))
        if name:
            families[name] = family
    return families


def _scene_biomes_by_name(scene: Mapping[str, Any]) -> dict[str, Mapping[str, Any]]:
    biomes: dict[str, Mapping[str, Any]] = {}
    for biome in _mapping_list(scene.get("biomes")):
        name = _string(biome.get("name"))
        if name:
            biomes[name] = biome
    return biomes


def _placement_zones_by_name(
    scene: Mapping[str, Any],
    regions: Sequence[Mapping[str, Any]],
) -> dict[str, Mapping[str, Any]]:
    region_by_ref: dict[str, Mapping[str, Any]] = {}
    for region in regions:
        for ref in (
            region.get("_source_name"),
            region.get("region_id"),
            _snake_id(region.get("name"), ""),
        ):
            text = _string(ref)
            if text:
                region_by_ref[text] = region
    default_region = regions[0] if regions else {}
    zones: dict[str, Mapping[str, Any]] = {}
    for index, zone in enumerate(_mapping_list(scene.get("placement_zones"))):
        values = _values(zone)
        region_ref = _string(values.get("region") or values.get("in") or values.get("on"))
        region = region_by_ref.get(region_ref, default_region)
        bounds = region.get("bounds") if isinstance(region.get("bounds"), Mapping) else {}
        center = _vector3(values.get("center") or values.get("position") or _nested(values, "bounds", "center") or _nested(bounds, "center"), [0.0, 0.0, 0.0])
        size = _vector3(values.get("size") or _nested(values, "bounds", "size") or _nested(bounds, "size"), [12.0, 12.0, 4.0])
        zone_name = _snake_id(zone.get("name"), f"placement_zone_{index}")
        zone_type = _snake_id(zone.get("type") or values.get("type") or values.get("kind") or values.get("surface"), "grid")
        zones[zone_name] = {
            "name": zone_name,
            "type": zone_type,
            "region": _string(region.get("region_id")),
            "center": center,
            "size": size,
            "side": _snake_id(values.get("side") or values.get("wall") or values.get("edge"), "center"),
            "surface": _snake_id(values.get("surface") or zone_type, zone_type),
            "axis": _snake_id(values.get("axis"), "x"),
            "rows": _positive_int(values.get("rows"), default=0),
            "columns": _positive_int(values.get("columns") or values.get("cols"), default=0),
            "spacing": _number(values.get("spacing"), default=0.0),
            "elevation": _number(values.get("elevation") or values.get("height"), default=0.0),
            "margin": _number(values.get("margin") or values.get("setback"), default=0.0),
            "facing": _snake_id(values.get("facing") or values.get("face"), "inward"),
            "align": _snake_id(values.get("align") or values.get("alignment"), "center"),
        }
    return zones


def _expand_kit_node(
    kit: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
    variant_families: Mapping[str, Mapping[str, Any]],
    placement_zones: Mapping[str, Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    kit_name = _snake_id(kit.get("name"), "kit")
    kit_values = deepcopy(_values(kit))
    objects: list[Mapping[str, Any]] = []
    sockets: list[Mapping[str, Any]] = []
    attachments: list[Mapping[str, Any]] = []
    generated_by_part: dict[str, list[str]] = {}
    grammar_key = _procedural_kit_grammar_key(kit, kit_values)
    if grammar_key:
        grammar_objects, grammar_sockets, grammar_attachments, grammar_generated = _expand_procedural_kit_grammar(
            kit_name=kit_name,
            kit=kit,
            kit_values=kit_values,
            grammar_key=grammar_key,
            modules=modules,
            variant_families=variant_families,
            placement_zones=placement_zones,
        )
        objects.extend(grammar_objects)
        sockets.extend(grammar_sockets)
        attachments.extend(grammar_attachments)
        for key, names in grammar_generated.items():
            generated_by_part.setdefault(key, []).extend(names)
    raw_parts = _mapping_list(kit_values.get("_parts"))
    if not raw_parts:
        raw_parts = _parts_from_module_refs(kit, kit_values, modules)
    sequence_index = 0
    for part_index, raw_part in enumerate(raw_parts):
        part_objects = _expand_kit_part(
            kit_name=kit_name,
            kit=kit,
            kit_values=kit_values,
            raw_part=raw_part,
            part_index=part_index,
            sequence_start=sequence_index,
            modules=modules,
        )
        objects.extend(part_objects)
        names = [_string(item.get("name")) for item in part_objects]
        part_name = _string(raw_part.get("name"), default=f"part_{part_index}")
        generated_by_part[part_name] = [name for name in names if name]
        module_ref = _module_ref_for_part(raw_part, kit_values, kit)
        if module_ref:
            generated_by_part.setdefault(module_ref, []).extend(name for name in names if name)
        sequence_index += len(part_objects)
    sockets.extend(_expand_kit_sockets(kit, kit_values, generated_by_part, objects))
    attachments.extend(_expand_kit_attachments(kit, kit_values, generated_by_part))
    return objects, sockets, attachments


def _procedural_kit_grammar_key(kit: Mapping[str, Any], kit_values: Mapping[str, Any]) -> str:
    candidates: list[str] = []
    for key in ("kit_grammar", "grammar", "kind", "type", "archetype", "object_archetype", "kit_style", "visual_system"):
        candidates.extend(_string_list(kit_values.get(key)))
    candidates.extend(_string_list(kit.get("from")))
    candidates.extend(_string_list(kit.get("name")))
    for value in candidates:
        text = _snake_id(value, "")
        if not text:
            continue
        if text in _PROCEDURAL_KIT_GRAMMARS:
            return text
        alias = _PROCEDURAL_KIT_GRAMMAR_ALIASES.get(text)
        if alias:
            return alias
        for token, mapped in _PROCEDURAL_KIT_GRAMMAR_ALIASES.items():
            if token in text:
                return mapped
        for token in _PROCEDURAL_KIT_GRAMMARS:
            if token in text:
                return token
    return ""


def _expand_procedural_kit_grammar(
    *,
    kit_name: str,
    kit: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    grammar_key: str,
    modules: Mapping[str, Mapping[str, Any]],
    variant_families: Mapping[str, Mapping[str, Any]],
    placement_zones: Mapping[str, Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]], list[Mapping[str, Any]], dict[str, list[str]]]:
    grammar = _PROCEDURAL_KIT_GRAMMARS.get(grammar_key, {})
    objects: list[Mapping[str, Any]] = []
    sockets: list[Mapping[str, Any]] = []
    attachments: list[Mapping[str, Any]] = []
    generated_by_key: dict[str, list[str]] = {}

    core = _procedural_kit_core_object(kit_name, kit, kit_values, grammar_key, grammar)
    objects.append(core)
    core_name = _string(core.get("name"))
    generated_by_key["core"] = [core_name]
    generated_by_key[grammar_key] = [core_name]

    anchor_names: list[str] = [core_name]
    for index, spec in enumerate(_mapping_list(list(grammar.get("generators", ())))):
        generator = _procedural_kit_generator_node(
            kit_name=kit_name,
            kit=kit,
            kit_values=kit_values,
            grammar_key=grammar_key,
            grammar=grammar,
            spec=spec,
            index=index,
        )
        generator_objects, generator_sockets, generator_attachments = _expand_generator_node(
            generator,
            modules,
            variant_families,
            placement_zones,
        )
        objects.extend(generator_objects)
        sockets.extend(generator_sockets)
        attachments.extend(generator_attachments)
        names = [_string(obj.get("name")) for obj in generator_objects if _string(obj.get("name"))]
        suffix = _snake_id(spec.get("suffix") or spec.get("family"), f"generator_{index}")
        generated_by_key.setdefault(suffix, []).extend(names)
        family = _snake_id(spec.get("family"), "")
        if family:
            generated_by_key.setdefault(family, []).extend(names)
        anchor = _procedural_kit_generator_anchor_name(generator, spec)
        if anchor and anchor in names:
            anchor_names.append(anchor)

    attachments.extend(_procedural_kit_system_attachments(kit_name, grammar_key, anchor_names))
    return objects, sockets, attachments, generated_by_key


def _procedural_kit_core_object(
    kit_name: str,
    kit: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    grammar_key: str,
    grammar: Mapping[str, Any],
) -> Mapping[str, Any]:
    core_family = _snake_id(kit_values.get("core_family") or grammar.get("core_family"), "procedural_setpiece")
    core_archetype = _snake_id(kit_values.get("object_archetype") or kit_values.get("archetype") or grammar.get("core_archetype"), grammar_key)
    values = _procedural_kit_inherited_values(kit_values)
    values.update(
        {
            "lathe_asset": core_family,
            "source_family": core_family,
            "source_kit": kit_name,
            "variant": f"{grammar_key}_core",
        }
    )
    state = dict(values.get("state") if isinstance(values.get("state"), Mapping) else {})
    state.update(
        {
            "procedural_kit": grammar_key,
            "kit_grammar": grammar_key,
            "object_archetype": core_archetype,
            "generated_kit_core": True,
        }
    )
    for count_key, family_key in (
        ("weapon_count", "weapon"),
        ("tool_count", "tool"),
        ("boat_count", "boat"),
        ("vehicle_count", "vehicle"),
        ("machine_count", "machine"),
        ("furniture_count", "furniture"),
        ("room_count", "interior"),
        ("road_count", "road"),
        ("building_count", "building"),
        ("access_count", "access"),
        ("infrastructure_count", "infrastructure"),
    ):
        count = _positive_int(kit_values.get(count_key), default=0)
        if count:
            state[count_key] = count
            state[f"{family_key}_slot_count"] = count
    state.setdefault("assembly_mode", "site_plan" if core_family == "procedural_city_block" else "room_layout" if core_family == "procedural_interior" else "machine_line")
    state.setdefault("assembly_family", "kit")
    state.setdefault("assembly_count", max(1, len(_mapping_list(list(grammar.get("generators", ()))))))
    state.setdefault("composition_sockets", [f"{grammar_key}_core", "kit_link", "service_mount"])
    values["state"] = state
    tags = _string_list(values.get("semantic_tags") or values.get("tags"))
    tags.extend(_string_list(grammar.get("tags")))
    tags.extend(["generated", "procedural_kit_core", f"kit:{kit_name}", f"kit_grammar:{grammar_key}"])
    values["semantic_tags"] = _dedupe(tags)
    return {
        "node_type": "scene_object",
        "name": f"{kit_name}_{grammar_key}_core",
        "role": grammar.get("role") or kit.get("role") or "environment_structure",
        "from": core_family,
        "values": values,
    }


def _procedural_kit_generator_node(
    *,
    kit_name: str,
    kit: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    grammar_key: str,
    grammar: Mapping[str, Any],
    spec: Mapping[str, Any],
    index: int,
) -> Mapping[str, Any]:
    suffix = _snake_id(spec.get("suffix") or spec.get("family"), f"generator_{index}")
    family = _snake_id(spec.get("family"), "object")
    assembly = _snake_id(spec.get("assembly"), _assembly_default_mode(family, {grammar_key, suffix, family}))
    values = _procedural_kit_inherited_values(kit_values)
    values.update(
        {
            "family": family,
            "count": _procedural_kit_generator_count(kit_values, spec, default=_positive_int(spec.get("default_count"), default=1)),
            "assembly": assembly,
            "auto_assemble": True,
            "source_kit": kit_name,
            "kit_grammar": grammar_key,
            "procedural_kit": grammar_key,
            "kit_generator": suffix,
        }
    )
    spec_values = spec.get("values") if isinstance(spec.get("values"), Mapping) else {}
    values.update(deepcopy(dict(spec_values)))
    for key in (
        "placement_zone",
        "zone",
        "assembly_spacing",
        "assembly_columns",
        "assembly_rows",
        "assembly_target",
        "assembly_parent",
        "anchor_object",
        "assembly_anchor",
    ):
        if key in kit_values and key not in values:
            values[key] = deepcopy(kit_values[key])
    tags = _string_list(values.get("semantic_tags") or values.get("tags"))
    tags.extend(["procedural_kit_member", f"kit:{kit_name}", f"kit_grammar:{grammar_key}", f"kit_generator:{suffix}"])
    values["semantic_tags"] = _dedupe(tags)
    return {
        "node_type": "scene_generator",
        "name": f"{kit_name}_{suffix}",
        "role": spec.get("role") or grammar.get("role") or kit.get("role", ""),
        "from": spec.get("from") or family,
        "values": values,
    }


def _procedural_kit_inherited_values(kit_values: Mapping[str, Any]) -> dict[str, Any]:
    values: dict[str, Any] = {}
    for key in (
        "region",
        "placement_zone",
        "zone",
        "style_pack",
        "visual_system",
        "kit_style",
        "theme_pack",
        "surface",
        "surface_overrides",
        "material",
        "material_bindings",
        "transform",
        "position",
        "rotation",
        "scale",
    ):
        if key in kit_values:
            values[key] = deepcopy(kit_values[key])
    state = kit_values.get("state") if isinstance(kit_values.get("state"), Mapping) else {}
    if isinstance(state, Mapping):
        values["state"] = deepcopy(dict(state))
    return values


def _procedural_kit_generator_count(kit_values: Mapping[str, Any], spec: Mapping[str, Any], *, default: int) -> int:
    for key in _string_list(spec.get("count_keys")):
        value = kit_values.get(key)
        if value is not None:
            return max(1, min(256, _positive_int(value, default=default)))
    if "count" in kit_values and _truthy(spec.get("use_kit_count")):
        return max(1, min(256, _positive_int(kit_values.get("count"), default=default)))
    return max(1, min(256, default))


def _procedural_kit_generator_anchor_name(generator: Mapping[str, Any], spec: Mapping[str, Any]) -> str:
    values = _values(generator)
    family = _snake_id(values.get("family") or spec.get("family"), "")
    assembly = _snake_id(values.get("assembly") or spec.get("assembly"), _assembly_default_mode(family, {family}))
    if assembly in _AUTO_ASSEMBLY_CHAIN_MODES:
        return ""
    return f"{_snake_id(generator.get('name'), 'generator')}_{assembly}_anchor"


def _procedural_kit_system_attachments(
    kit_name: str,
    grammar_key: str,
    anchor_names: Sequence[str],
) -> list[Mapping[str, Any]]:
    anchors = [name for name in _dedupe([str(name) for name in anchor_names if name])]
    if len(anchors) < 2:
        return []
    core = anchors[0]
    attachments: list[Mapping[str, Any]] = []
    for index, anchor in enumerate(anchors[1:]):
        attachments.append(
            {
                "node_type": "scene_attachment",
                "name": f"{kit_name}_{grammar_key}_kit_link_{index + 1:02d}",
                "type": "connect",
                "values": {
                    "from": anchor,
                    "to": core,
                    "socket": "kit_link",
                    "mode": "connect",
                    "assembly": "kit_system",
                    "kit": kit_name,
                    "kit_grammar": grammar_key,
                },
            }
        )
    return attachments


def _parts_from_module_refs(
    kit: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    refs = _kit_module_refs(kit, kit_values)
    parts: list[Mapping[str, Any]] = []
    for ref in refs:
        module = modules.get(ref, {})
        parts.append(
            {
                "node_type": "scene_kit_part",
                "name": ref,
                "role": module.get("role") or kit.get("role", ""),
                "from": module.get("from") or kit.get("from", ""),
                "values": {"module": ref, "_construct": "part"},
            }
        )
    return parts


def _kit_module_refs(kit: Mapping[str, Any], kit_values: Mapping[str, Any]) -> list[str]:
    for key in ("modules", "use", "module"):
        refs = _string_list(kit_values.get(key))
        if refs:
            return [_snake_id(ref, "module") for ref in refs]
    source = _string(kit.get("from"))
    return [_snake_id(source, "module")] if source else []


def _expand_kit_part(
    *,
    kit_name: str,
    kit: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    raw_part: Mapping[str, Any],
    part_index: int,
    sequence_start: int,
    modules: Mapping[str, Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    part_name = _snake_id(raw_part.get("name"), f"part_{part_index}")
    module_ref = _module_ref_for_part(raw_part, kit_values, kit)
    module = modules.get(module_ref, {}) if module_ref else {}
    module_values = deepcopy(_values(module))
    part_values = deepcopy(_values(raw_part))
    count_default = _positive_int(kit_values.get("count") or _nested(kit_values, "repeat", "count"), default=1) if len(_mapping_list(kit_values.get("_parts"))) <= 1 else 1
    count = max(1, min(256, _positive_int(part_values.get("count") or _nested(part_values, "repeat", "count"), default=count_default)))
    objects: list[Mapping[str, Any]] = []
    for repeat_index in range(count):
        values = _merge_kit_part_values(module_values, kit_values, part_values)
        transform = _kit_part_transform(kit_values, part_values, sequence_start + repeat_index, count)
        values["transform"] = transform
        state = dict(values.get("state", {})) if isinstance(values.get("state"), Mapping) else {}
        state.update(
            {
                "kit": kit_name,
                "kit_part": part_name,
                "kit_index": repeat_index,
                "kit_count": count,
                "kit_sequence_index": sequence_start + repeat_index,
            }
        )
        if module_ref:
            state["kit_module"] = module_ref
        _merge_inline_interface_state(state, values)
        values["state"] = state
        tags = _string_list(values.get("semantic_tags") or values.get("tags"))
        tags.extend(["modular", "kit_part", f"kit:{kit_name}", f"kit_part:{part_name}"])
        if module_ref:
            tags.append(f"module:{module_ref}")
        values["semantic_tags"] = _dedupe(tags)
        values["source_kit"] = kit_name
        values.pop("count", None)
        values.pop("spacing", None)
        values.pop("start", None)
        values.pop("layout", None)
        object_name = f"{kit_name}_{part_name}_{repeat_index + 1:02d}" if count > 1 else f"{kit_name}_{part_name}"
        objects.append(
            {
                "node_type": "scene_object",
                "name": object_name,
                "role": raw_part.get("role") or module.get("role") or kit.get("role", ""),
                "from": raw_part.get("from") or module.get("from") or kit.get("from", ""),
                "values": values,
            }
        )
    return objects


def _module_ref_for_part(raw_part: Mapping[str, Any], kit_values: Mapping[str, Any], kit: Mapping[str, Any]) -> str:
    part_values = _values(raw_part)
    for value in (part_values.get("module"), part_values.get("use"), raw_part.get("from")):
        refs = _string_list(value)
        if refs:
            return _snake_id(refs[0], "module")
    refs = _kit_module_refs(kit, kit_values)
    return refs[0] if len(refs) == 1 else ""


def _merge_kit_part_values(
    module_values: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    part_values: Mapping[str, Any],
) -> dict[str, Any]:
    values = deepcopy(dict(module_values))
    kit_defaults = kit_values.get("defaults") if isinstance(kit_values.get("defaults"), Mapping) else {}
    if isinstance(kit_defaults, Mapping):
        values.update(deepcopy(dict(kit_defaults)))
    values.update(deepcopy(dict(part_values)))
    for private_key in ("_parts", "_sockets", "_attachments", "defaults", "modules", "module", "use"):
        values.pop(private_key, None)
    return values


def _kit_part_transform(
    kit_values: Mapping[str, Any],
    part_values: Mapping[str, Any],
    index: int,
    count: int,
) -> dict[str, list[float]]:
    kit_base = _vector3(kit_values.get("position") or kit_values.get("start") or _nested(kit_values, "transform", "position"), [0.0, 0.0, 0.0])
    part_base = _vector3(part_values.get("position") or _nested(part_values, "transform", "position"), [0.0, 0.0, 0.0])
    rotation = _vector3(part_values.get("rotation") or _nested(part_values, "transform", "rotation"), [0.0, 0.0, 0.0])
    scale = _vector3(part_values.get("scale") or _nested(part_values, "transform", "scale"), [1.0, 1.0, 1.0])
    layout = _snake_id(part_values.get("layout") or kit_values.get("layout") or _nested(kit_values, "repeat", "layout"), "linear")
    if layout in {"radial", "circle", "ring"}:
        radius = _number(part_values.get("radius") or kit_values.get("radius") or _nested(kit_values, "repeat", "radius"), default=4.0)
        angle_offset = _number(kit_values.get("angle_offset") or _nested(kit_values, "repeat", "angle_offset"), default=0.0)
        angle = angle_offset + (360.0 * index / max(1, count))
        radians = math.radians(angle)
        position = [
            round(kit_base[0] + part_base[0] + math.cos(radians) * radius, 6),
            round(kit_base[1] + part_base[1] + math.sin(radians) * radius, 6),
            round(kit_base[2] + part_base[2], 6),
        ]
        rotation[2] = round(rotation[2] + angle, 6)
    else:
        axis = _string(part_values.get("axis") or kit_values.get("axis") or _nested(kit_values, "repeat", "axis"), default="x").lower()
        spacing = _number(part_values.get("spacing") or kit_values.get("spacing") or _nested(kit_values, "repeat", "spacing"), default=2.0)
        axis_index = {"x": 0, "y": 1, "z": 2}.get(axis, 0)
        position = [round(kit_base[i] + part_base[i], 6) for i in range(3)]
        position[axis_index] = round(position[axis_index] + spacing * index, 6)
    return {"position": position, "rotation": rotation, "scale": scale}


def _merge_inline_interface_state(state: dict[str, Any], values: Mapping[str, Any]) -> None:
    for source_key, target_key in (
        ("sockets", "composition_sockets"),
        ("module_sockets", "composition_sockets"),
        ("anchors", "composition_anchors"),
        ("module_anchors", "composition_anchors"),
        ("pivots", "composition_pivots"),
        ("module_pivots", "composition_pivots"),
    ):
        entries = _string_list(values.get(source_key))
        if entries:
            _append_state_items(state, target_key, [_snake_id(entry, "interface") for entry in entries])


def _expand_kit_sockets(
    kit: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    generated_by_part: Mapping[str, list[str]],
    objects: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    sockets: list[Mapping[str, Any]] = []
    fallback_targets = [_string(obj.get("name")) for obj in objects if _string(obj.get("name"))]
    for index, socket in enumerate(_mapping_list(kit_values.get("_sockets"))):
        values = deepcopy(dict(_values(socket)))
        target_ref = _string(_composition_target(values, "on", "object", "target", "to", "parent"))
        targets = generated_by_part.get(target_ref, []) if target_ref else fallback_targets[:1]
        if not targets and target_ref:
            targets = [target_ref]
        for target_index, target in enumerate(targets):
            expanded_values = deepcopy(values)
            expanded_values["on"] = target
            sockets.append(
                {
                    "node_type": "scene_socket",
                    "name": f"{kit.get('name')}_{socket.get('name')}_{target_index + 1:02d}",
                    "type": socket.get("type", ""),
                    "values": expanded_values,
                }
            )
    return sockets


def _expand_kit_attachments(
    kit: Mapping[str, Any],
    kit_values: Mapping[str, Any],
    generated_by_part: Mapping[str, list[str]],
) -> list[Mapping[str, Any]]:
    attachments: list[Mapping[str, Any]] = []
    for index, attachment in enumerate(_mapping_list(kit_values.get("_attachments"))):
        values = deepcopy(dict(_values(attachment)))
        source_ref = _string(_composition_target(values, "from", "source", "child", "object"))
        target_ref = _string(_composition_target(values, "to", "target", "parent", "on"))
        sources = generated_by_part.get(source_ref, [source_ref] if source_ref else [])
        targets = generated_by_part.get(target_ref, [target_ref] if target_ref else [])
        if not sources or not targets:
            continue
        for attach_index, source in enumerate(sources):
            if source_ref == target_ref and len(targets) > 1:
                target = targets[(attach_index + 1) % len(targets)]
            else:
                target = targets[attach_index] if attach_index < len(targets) else targets[0]
            expanded_values = deepcopy(values)
            expanded_values["from"] = source
            expanded_values["to"] = target
            attachments.append(
                {
                    "node_type": "scene_attachment",
                    "name": f"{kit.get('name')}_{attachment.get('name')}_{attach_index + 1:02d}",
                    "type": attachment.get("type", ""),
                    "values": expanded_values,
                }
            )
    return attachments


def _expand_generator_node(
    generator: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
    variant_families: Mapping[str, Mapping[str, Any]],
    placement_zones: Mapping[str, Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    generator_name = _snake_id(generator.get("name"), "generator")
    generator_values = deepcopy(_values(generator))
    family_ref = _snake_id(
        generator_values.get("family")
        or generator_values.get("variant_family")
        or generator_values.get("grammar")
        or generator.get("from"),
        "",
    )
    family = variant_families.get(family_ref, {}) if family_ref else {}
    family_values = deepcopy(_values(family))
    options = _generator_options(generator, generator_values, family, family_values, modules)
    if not options:
        return [], [], []
    count = max(1, min(1024, _positive_int(generator_values.get("count") or family_values.get("count"), default=len(options))))
    strategy = _snake_id(
        generator_values.get("select")
        or generator_values.get("strategy")
        or family_values.get("select")
        or family_values.get("strategy"),
        "cycle",
    )
    constraints = _generator_constraints(generator_values, family_values)
    placement_zone = _generator_placement_zone(generator_values, family_values, placement_zones)
    selected_options: list[Mapping[str, Any]] = []
    for index in range(count):
        selected_options.append(
            _select_generator_option(
                options,
                index,
                strategy,
                constraints=constraints,
                selected=selected_options,
                count=count,
            )
        )
    objects: list[Mapping[str, Any]] = []
    generated_by_key: dict[str, list[str]] = {"all": []}
    for index, option in enumerate(selected_options):
        obj = _generator_object(
            generator=generator,
            generator_name=generator_name,
            generator_values=generator_values,
            family_ref=family_ref,
            family_values=family_values,
            option=option,
            modules=modules,
            index=index,
            count=count,
            strategy=strategy,
            constraints=constraints,
            placement_zone=placement_zone,
        )
        objects.append(obj)
        object_name = _string(obj.get("name"))
        generated_by_key["all"].append(object_name)
        for key in _generator_option_keys(option, family_ref):
            generated_by_key.setdefault(key, []).append(object_name)
    variant_objects = list(objects)
    assembly_objects, assembly_sockets, assembly_attachments = _auto_generator_assembly(
        generator_name,
        generator_values,
        family_ref,
        family_values,
        variant_objects,
    )
    objects.extend(assembly_objects)
    sockets = [
        *_expand_generator_sockets(generator, generator_values, family, family_values, generated_by_key, objects),
        *assembly_sockets,
    ]
    attachments = [
        *_expand_generator_attachments(generator, generator_values, family, family_values, generated_by_key),
        *assembly_attachments,
        *_auto_generator_attachments(generator_name, generator_values, variant_objects),
    ]
    return objects, sockets, attachments


def _expand_environment_node(
    environment: Mapping[str, Any],
    biomes: Mapping[str, Mapping[str, Any]],
    placement_zones: Mapping[str, Mapping[str, Any]],
    regions: Sequence[Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]], list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    environment_name = _snake_id(environment.get("name"), "environment")
    environment_values = deepcopy(_values(environment))
    biome_ref = _snake_id(
        environment_values.get("biome")
        or environment_values.get("environment")
        or environment_values.get("habitat")
        or environment.get("from"),
        "",
    )
    biome = biomes.get(biome_ref, {}) if biome_ref else {}
    biome_values = deepcopy(_values(biome))
    placement_zone = _generator_placement_zone(environment_values, biome_values, placement_zones)
    if not placement_zone:
        placement_zone = _environment_region_zone(environment_values, regions)
    feature_specs = _environment_feature_specs(environment_values, biome_values)
    if not feature_specs:
        return [], [], [], []
    summary = _environment_feature_summary(feature_specs)
    objects: list[Mapping[str, Any]] = []
    generated_by_key: dict[str, list[str]] = {"all": []}
    global_index = 0
    total_count = sum(spec["count"] for spec in feature_specs)
    for spec in feature_specs:
        for feature_index in range(spec["count"]):
            obj = _environment_feature_object(
                environment=environment,
                environment_name=environment_name,
                environment_values=environment_values,
                biome_ref=biome_ref,
                biome_values=biome_values,
                spec=spec,
                feature_index=feature_index,
                global_index=global_index,
                total_count=total_count,
                placement_zone=placement_zone,
                summary=summary,
            )
            objects.append(obj)
            object_name = _string(obj.get("name"))
            if object_name:
                generated_by_key["all"].append(object_name)
                generated_by_key.setdefault(environment_name, []).append(object_name)
                generated_by_key.setdefault(_snake_id(spec["kind"], "feature"), []).append(object_name)
                if biome_ref:
                    generated_by_key.setdefault(biome_ref, []).append(object_name)
            global_index += 1
    sockets = _expand_environment_sockets(environment, environment_values, biome, biome_values, generated_by_key, objects)
    attachments = _expand_environment_attachments(environment, environment_values, biome, biome_values, generated_by_key)
    relationships = _environment_relationships(environment_name, objects)
    return objects, sockets, attachments, relationships


def _environment_region_zone(
    environment_values: Mapping[str, Any],
    regions: Sequence[Mapping[str, Any]],
) -> Mapping[str, Any]:
    region_ref = _snake_id(environment_values.get("region") or environment_values.get("in") or environment_values.get("on"), "")
    region = {}
    for candidate in regions:
        refs = {
            _snake_id(candidate.get("_source_name"), ""),
            _snake_id(candidate.get("region_id"), ""),
            _snake_id(candidate.get("name"), ""),
        }
        if region_ref and region_ref in refs:
            region = candidate
            break
    if not region and regions:
        region = regions[0]
    bounds = region.get("bounds") if isinstance(region.get("bounds"), Mapping) else {}
    return {
        "name": _snake_id(environment_values.get("placement_zone") or environment_values.get("zone") or region_ref, "environment_zone"),
        "type": _snake_id(environment_values.get("placement_kind") or environment_values.get("placement_type"), "terrain"),
        "region": _string(region.get("region_id")),
        "center": _vector3(environment_values.get("center") or _nested(bounds, "center"), [0.0, 0.0, 0.0]),
        "size": _vector3(environment_values.get("size") or _nested(bounds, "size"), [24.0, 24.0, 4.0]),
        "surface": _snake_id(environment_values.get("surface"), "terrain"),
        "axis": _snake_id(environment_values.get("axis"), "x"),
        "side": _snake_id(environment_values.get("side") or environment_values.get("edge"), "center"),
        "rows": _positive_int(environment_values.get("rows"), default=0),
        "columns": _positive_int(environment_values.get("columns") or environment_values.get("cols"), default=0),
        "spacing": _number(environment_values.get("spacing"), default=0.0),
        "elevation": _number(environment_values.get("elevation") or environment_values.get("height"), default=0.0),
        "margin": _number(environment_values.get("margin") or environment_values.get("setback"), default=0.0),
        "facing": _snake_id(environment_values.get("facing"), "inward"),
        "align": _snake_id(environment_values.get("align") or environment_values.get("alignment"), "center"),
    }


def _environment_feature_specs(
    environment_values: Mapping[str, Any],
    biome_values: Mapping[str, Any],
) -> list[dict[str, Any]]:
    features = {_snake_id(item, "") for item in _string_list(environment_values.get("features") or biome_values.get("features"))}
    specs: list[dict[str, Any]] = []
    if not _disabled(environment_values.get("terrain")):
        specs.append(
            {
                "kind": "terrain_patch",
                "count": _environment_count_for(
                    environment_values,
                    biome_values,
                    features,
                    "terrain_patch",
                    "terrain_patches",
                    "patch",
                    "patches",
                    default=1,
                ),
            }
        )
    for kind, aliases in (
        ("ridge", ("ridge", "ridges", "ridge_count")),
        ("cliff", ("cliff", "cliffs", "cliff_count")),
        ("clearing", ("clearing", "clearings", "clearing_count")),
        ("platform", ("platform", "platforms", "platform_count")),
        ("water", ("water", "pond", "ponds", "water_count")),
        ("path", ("path", "paths", "trail", "trails", "road", "roads", "path_count")),
        ("road_edge", ("road_edge", "road_edges", "edge_path", "edge_paths", "road_edge_count")),
    ):
        count = _environment_count_for(environment_values, biome_values, features, *aliases, default=0)
        if count > 0:
            specs.append({"kind": kind, "count": count})
    landmarks = _string_list(environment_values.get("landmarks") or biome_values.get("landmarks"))
    if not landmarks and "landmark" in features:
        landmarks = ["landmark"]
    for landmark in landmarks[:128]:
        specs.append({"kind": "landmark", "count": 1, "asset": _snake_id(landmark, "landmark")})
    return [spec for spec in specs if spec["count"] > 0]


def _environment_count_for(
    environment_values: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    features: set[str],
    *aliases: str,
    default: int,
) -> int:
    for source in (environment_values, biome_values):
        for alias in aliases:
            if alias in source:
                return max(0, min(1024, _positive_int(source.get(alias), default=default)))
    alias_tokens = {_snake_id(alias, "") for alias in aliases}
    return 1 if features & alias_tokens else default


def _disabled(value: Any) -> bool:
    if isinstance(value, bool):
        return not value
    if isinstance(value, str):
        return value.lower() in {"0", "false", "off", "none", "no", "disabled"}
    return False


def _environment_feature_summary(feature_specs: Sequence[Mapping[str, Any]]) -> dict[str, int]:
    summary: dict[str, int] = {}
    for spec in feature_specs:
        key = f"{_snake_id(spec.get('kind'), 'feature')}_count"
        summary[key] = summary.get(key, 0) + _positive_int(spec.get("count"), default=0)
    summary["environment_feature_kind_count"] = len(feature_specs)
    summary["environment_total_feature_count"] = sum(summary[key] for key in summary if key.endswith("_count") and key != "environment_feature_kind_count")
    return summary


def _environment_feature_object(
    *,
    environment: Mapping[str, Any],
    environment_name: str,
    environment_values: Mapping[str, Any],
    biome_ref: str,
    biome_values: Mapping[str, Any],
    spec: Mapping[str, Any],
    feature_index: int,
    global_index: int,
    total_count: int,
    placement_zone: Mapping[str, Any],
    summary: Mapping[str, int],
) -> Mapping[str, Any]:
    kind = _snake_id(spec.get("kind"), "terrain_patch")
    construct = _environment_feature_construct(kind)
    values = _merge_environment_values(biome_values, environment_values)
    asset_ref = _snake_id(spec.get("asset"), "")
    construct_spec = _WORLD_PIECE_CONSTRUCTS.get(construct, {})
    values["_construct"] = construct
    values["lathe_asset"] = asset_ref or construct_spec.get("lathe_asset") or _snake_id(environment.get("from"), "") or kind
    source_family = construct_spec.get("source_family") or values.get("source_family")
    if source_family:
        values["source_family"] = source_family
    values["source_kit"] = biome_ref or environment_name
    values["variant"] = kind if not asset_ref else asset_ref
    values["transform"] = _environment_feature_transform(environment_values, biome_values, kind, feature_index, _positive_int(spec.get("count"), default=1), placement_zone)
    density = _number(environment_values.get("density") or biome_values.get("density"), default=0.0)
    state = dict(values.get("state", {})) if isinstance(values.get("state"), Mapping) else {}
    state.update(
        {
            "environment": environment_name,
            "environment_index": global_index,
            "environment_count": total_count,
            "environment_feature": kind,
            "environment_feature_index": feature_index,
            "environment_feature_count": _positive_int(spec.get("count"), default=1),
            "environment_pattern": _scatter_pattern(environment_values, biome_values),
            "environment_seed": _scatter_seed(environment_values, biome_values),
            "biome": biome_ref,
            "biome_density": round(density, 6),
            "landform": kind,
        }
    )
    for key, value in summary.items():
        state[key] = value
    if placement_zone:
        state.update(_placement_state(placement_zone, global_index, max(1, total_count)))
    values["state"] = state
    tags = _string_list(values.get("semantic_tags") or values.get("tags"))
    tags.extend(["generated", "environment_system", "world_structure", f"environment:{environment_name}", f"landform:{kind}"])
    if biome_ref:
        tags.append(f"biome:{biome_ref}")
    if construct != "object":
        tags.append(construct)
    values["semantic_tags"] = _dedupe(tags)
    for private_key in (
        "_options",
        "_sockets",
        "_attachments",
        "_constraints",
        "features",
        "landmarks",
        "terrain",
        "terrain_patch",
        "terrain_patches",
        "patch",
        "patches",
        "ridge",
        "ridges",
        "ridge_count",
        "cliff",
        "cliffs",
        "cliff_count",
        "clearing",
        "clearings",
        "clearing_count",
        "platform",
        "platforms",
        "platform_count",
        "water",
        "water_count",
        "path",
        "paths",
        "trail",
        "trails",
        "road",
        "roads",
        "path_count",
        "road_edge",
        "road_edges",
        "road_edge_count",
        "biome",
        "environment",
        "habitat",
        "density",
        "placement",
        "placement_zone",
        "zone",
        "pattern",
        "scatter_pattern",
        "layout",
        "jitter",
        "radius",
        "scale_min",
        "scale_max",
        "scale_jitter",
        "yaw_jitter",
        "rotation_jitter",
        "random_yaw",
    ):
        values.pop(private_key, None)
    object_name = f"{environment_name}_{kind}_{feature_index + 1:02d}" if _positive_int(spec.get("count"), default=1) > 1 else f"{environment_name}_{kind}"
    if asset_ref and kind == "landmark":
        object_name = f"{environment_name}_{asset_ref}_{feature_index + 1:02d}"
    return {
        "node_type": "scene_object",
        "name": object_name,
        "role": environment.get("role") or _environment_feature_role(kind),
        "from": asset_ref or construct_spec.get("lathe_asset") or environment.get("from", ""),
        "values": values,
    }


def _merge_environment_values(
    biome_values: Mapping[str, Any],
    environment_values: Mapping[str, Any],
) -> dict[str, Any]:
    values: dict[str, Any] = {}
    for source in (biome_values.get("defaults"), environment_values.get("defaults")):
        if isinstance(source, Mapping):
            values.update(deepcopy(dict(source)))
    for source in (biome_values, environment_values):
        values.update(deepcopy({key: value for key, value in source.items() if not str(key).startswith("_")}))
    return values


def _environment_feature_construct(kind: str) -> str:
    if kind in {"path", "trail", "road", "road_edge", "street_edge"}:
        return "road"
    if kind in {"bridge"}:
        return "bridge"
    if kind in {"landmark", "prop", "monument"}:
        return "object"
    return "terrain"


def _environment_feature_role(kind: str) -> str:
    if kind in {"path", "trail", "road", "road_edge"}:
        return "navigation"
    if kind in {"landmark", "platform"}:
        return "environment_structure"
    return "environment_structure"


def _environment_feature_transform(
    environment_values: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    kind: str,
    index: int,
    count: int,
    placement_zone: Mapping[str, Any],
) -> dict[str, list[float]]:
    center = _vector3(placement_zone.get("center"), [0.0, 0.0, 0.0])
    size = _vector3(placement_zone.get("size"), [24.0, 24.0, 4.0])
    margin = _number(placement_zone.get("margin"), default=0.0)
    elevation = _number(placement_zone.get("elevation"), default=0.0)
    seed = _scatter_seed(environment_values, biome_values)
    rotation = _vector3(environment_values.get("rotation") or _nested(environment_values, "transform", "rotation"), [0.0, 0.0, 0.0])
    if kind in {"path", "road", "trail", "road_edge"}:
        zone = dict(placement_zone)
        zone["axis"] = _snake_id(environment_values.get("axis") or zone.get("axis"), "x")
        position, yaw = _line_position(zone, center, size, index, count, margin, elevation)
        rotation[2] = round(rotation[2] + yaw, 6)
        width = _number(environment_values.get("road_width") or environment_values.get("path_width") or biome_values.get("path_width"), default=1.6 if kind != "road_edge" else 0.5)
        length = max(0.1, float(size[0] if zone["axis"] != "y" else size[1]) - margin * 2.0)
        scale = [round(width, 6), round(length, 6), 0.08]
    elif kind in {"ridge", "cliff"}:
        zone = dict(placement_zone)
        zone["axis"] = _snake_id(environment_values.get("ridge_axis") or zone.get("axis"), "x")
        position, yaw = _line_position(zone, center, size, index, count, margin, elevation)
        rotation[2] = round(rotation[2] + yaw, 6)
        length = max(0.1, float(size[0] if zone["axis"] != "y" else size[1]) * 0.6)
        height = _number(environment_values.get("ridge_height") or environment_values.get("cliff_height") or biome_values.get("ridge_height"), default=0.8 if kind == "ridge" else 1.6)
        scale = [0.8, round(length, 6), round(height, 6)]
    elif kind in {"clearing", "platform", "water", "landmark"}:
        position = _environment_random_position(center, size, seed, kind, index, margin, elevation)
        radius = _number(environment_values.get(f"{kind}_radius") or environment_values.get("radius") or biome_values.get("radius"), default=3.0 if kind != "landmark" else 1.0)
        height = 0.05 if kind in {"clearing", "water"} else 0.25 if kind == "platform" else 1.0
        scale = [round(radius * 2.0, 6), round(radius * 2.0, 6), round(height, 6)]
        if kind == "landmark":
            scale = _vector3(environment_values.get("landmark_scale") or environment_values.get("scale"), [1.0, 1.0, 1.0])
    else:
        position = _grid_position(placement_zone, center, size, index, count, z_value=center[2] - size[2] * 0.5 + elevation)
        columns = max(1, _positive_int(placement_zone.get("columns"), default=math.ceil(count**0.5)))
        rows = max(1, _positive_int(placement_zone.get("rows"), default=math.ceil(count / columns)))
        scale = [round(max(0.1, size[0] / columns), 6), round(max(0.1, size[1] / rows), 6), round(max(0.05, size[2] * 0.08), 6)]
    jitter = _number(environment_values.get("jitter") or biome_values.get("jitter"), default=0.0)
    if jitter > 0 and kind not in {"terrain_patch"}:
        position[0] = round(position[0] + (_stable_unit(seed, kind, index, "jx") * 2.0 - 1.0) * jitter, 6)
        position[1] = round(position[1] + (_stable_unit(seed, kind, index, "jy") * 2.0 - 1.0) * jitter, 6)
    yaw_jitter = _number(environment_values.get("yaw_jitter") or biome_values.get("yaw_jitter"), default=0.0)
    if yaw_jitter > 0:
        rotation[2] = round(rotation[2] + (_stable_unit(seed, kind, index, "yaw") * 2.0 - 1.0) * yaw_jitter, 6)
    return {
        "position": [round(float(value), 6) for value in position],
        "rotation": [round(float(value), 6) for value in rotation],
        "scale": [round(float(value), 6) for value in scale],
    }


def _environment_random_position(
    center: Sequence[float],
    size: Sequence[float],
    seed: str,
    kind: str,
    index: int,
    margin: float,
    elevation: float,
) -> list[float]:
    usable_x = max(0.1, float(size[0]) - margin * 2.0)
    usable_y = max(0.1, float(size[1]) - margin * 2.0)
    x = center[0] - usable_x * 0.5 + usable_x * _stable_unit(seed, kind, index, "x")
    y = center[1] - usable_y * 0.5 + usable_y * _stable_unit(seed, kind, index, "y")
    return [round(x, 6), round(y, 6), round(center[2] - size[2] * 0.5 + elevation, 6)]


def _expand_environment_sockets(
    environment: Mapping[str, Any],
    environment_values: Mapping[str, Any],
    biome: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    generated_by_key: Mapping[str, list[str]],
    objects: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    socket_nodes = [*_mapping_list(biome_values.get("_sockets")), *_mapping_list(environment_values.get("_sockets"))]
    pseudo = {"name": environment.get("name") or biome.get("name")}
    return _expand_kit_sockets(pseudo, {"_sockets": socket_nodes}, generated_by_key, objects)


def _expand_environment_attachments(
    environment: Mapping[str, Any],
    environment_values: Mapping[str, Any],
    biome: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    generated_by_key: Mapping[str, list[str]],
) -> list[Mapping[str, Any]]:
    attachment_nodes = [*_mapping_list(biome_values.get("_attachments")), *_mapping_list(environment_values.get("_attachments"))]
    pseudo = {"name": environment.get("name") or biome.get("name")}
    return _expand_kit_attachments(pseudo, {"_attachments": attachment_nodes}, generated_by_key)


def _environment_relationships(
    environment_name: str,
    objects: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    names = [_string(obj.get("name")) for obj in objects if _string(obj.get("name"))]
    if len(names) < 2:
        return []
    root = next((name for name in names if "_terrain_patch" in name), names[0])
    relationships: list[Mapping[str, Any]] = []
    for index, name in enumerate(names):
        if name == root:
            continue
        relation = "routes_to" if any(token in name for token in ("path", "road", "trail")) else "contains"
        relationships.append(
            {
                "node_type": "scene_relationship",
                "name": f"{environment_name}_contains_{index + 1:02d}",
                "type": relation,
                "values": {
                    "from": root,
                    "to": name,
                    "type": relation,
                    "description": f"environment {environment_name} connects terrain feature {name}",
                },
            }
        )
    return relationships


def _expand_scatter_node(
    scatter: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
    variant_families: Mapping[str, Mapping[str, Any]],
    placement_zones: Mapping[str, Mapping[str, Any]],
    biomes: Mapping[str, Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    scatter_name = _snake_id(scatter.get("name"), "scatter")
    scatter_values = deepcopy(_values(scatter))
    biome_ref = _snake_id(scatter_values.get("biome") or scatter_values.get("environment") or scatter_values.get("habitat"), "")
    biome = biomes.get(biome_ref, {}) if biome_ref else {}
    biome_values = deepcopy(_values(biome))
    family_ref = _snake_id(
        scatter_values.get("family")
        or scatter_values.get("variant_family")
        or scatter_values.get("grammar")
        or scatter_values.get("variants"),
        "",
    )
    family = variant_families.get(family_ref, {}) if family_ref else {}
    family_values = deepcopy(_values(family))
    options = _scatter_options(scatter, scatter_values, biome, biome_values, family, family_values, modules)
    if not options:
        return [], [], []
    placement_zone = _generator_placement_zone(scatter_values, biome_values, placement_zones)
    count = _scatter_count(scatter_values, biome_values, placement_zone, option_count=len(options))
    strategy = _snake_id(
        scatter_values.get("select")
        or scatter_values.get("strategy")
        or biome_values.get("select")
        or biome_values.get("strategy")
        or family_values.get("select")
        or family_values.get("strategy"),
        "weighted_cycle",
    )
    constraints = [
        *_generator_constraints(scatter_values, biome_values),
        *_generator_constraints({}, family_values),
    ]
    selected_options: list[Mapping[str, Any]] = []
    for index in range(count):
        selected_options.append(
            _select_generator_option(
                options,
                index,
                strategy,
                constraints=constraints,
                selected=selected_options,
                count=count,
            )
        )
    objects: list[Mapping[str, Any]] = []
    generated_by_key: dict[str, list[str]] = {"all": []}
    for index, option in enumerate(selected_options):
        obj = _scatter_object(
            scatter=scatter,
            scatter_name=scatter_name,
            scatter_values=scatter_values,
            biome_ref=biome_ref,
            biome_values=biome_values,
            family_ref=family_ref,
            family_values=family_values,
            option=option,
            modules=modules,
            index=index,
            count=count,
            strategy=strategy,
            constraints=constraints,
            placement_zone=placement_zone,
        )
        objects.append(obj)
        object_name = _string(obj.get("name"))
        generated_by_key["all"].append(object_name)
        for key in _generator_option_keys(option, family_ref or biome_ref):
            generated_by_key.setdefault(key, []).append(object_name)
        generated_by_key.setdefault(scatter_name, []).append(object_name)
        if biome_ref:
            generated_by_key.setdefault(biome_ref, []).append(object_name)
    sockets = _expand_scatter_sockets(scatter, scatter_values, biome, biome_values, family, family_values, generated_by_key, objects)
    attachments = [
        *_expand_scatter_attachments(scatter, scatter_values, biome, biome_values, family, family_values, generated_by_key),
        *_auto_generator_attachments(scatter_name, scatter_values, objects),
    ]
    return objects, sockets, attachments


def _scatter_options(
    scatter: Mapping[str, Any],
    scatter_values: Mapping[str, Any],
    biome: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    options: list[dict[str, Any]] = []
    seen: set[str] = set()
    for source_family, source_values in ((biome, biome_values), (family, family_values)):
        for option in _generator_options(scatter, scatter_values, source_family, source_values, modules):
            key = _snake_id(option.get("name") or option.get("module") or option.get("from"), "option")
            if key in seen:
                continue
            seen.add(key)
            options.append(option)
    if options:
        return options
    refs = _scatter_pool_refs(scatter_values, biome_values)
    weights = _number_list(scatter_values.get("weights") or biome_values.get("weights"))
    for index, ref in enumerate(refs):
        module = modules.get(ref, {})
        module_values = deepcopy(_values(module)) if module else {}
        options.append(
            {
                "name": ref,
                "role": module.get("role") or scatter.get("role", ""),
                "from": module.get("from") or ref,
                "values": _generator_selection_values(module_values, {"module": ref, "lathe_asset": module.get("from") or ref}),
                "module": ref if ref in modules else "",
                "weight": _positive_int(weights[index] if index < len(weights) else 1, default=1),
            }
        )
    if options:
        return options
    source = _snake_id(scatter.get("from"), "")
    fallback = source or _snake_id(scatter.get("name"), "scatter_prop")
    module = modules.get(fallback, {})
    return [
        {
            "name": fallback,
            "role": module.get("role") or scatter.get("role", ""),
            "from": module.get("from") or source or fallback,
            "values": _generator_selection_values(_values(module), {"module": fallback, "lathe_asset": module.get("from") or source or fallback}),
            "module": fallback if fallback in modules else "",
            "weight": 1,
        }
    ]


def _scatter_pool_refs(scatter_values: Mapping[str, Any], biome_values: Mapping[str, Any]) -> list[str]:
    for source in (scatter_values, biome_values):
        for key in ("pool", "props", "objects", "modules", "use", "vegetation", "rocks", "clutter", "dressing"):
            refs = _string_list(source.get(key))
            if refs:
                return [_snake_id(ref, "scatter_prop") for ref in refs]
    return []


def _scatter_count(
    scatter_values: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    placement_zone: Mapping[str, Any],
    *,
    option_count: int,
) -> int:
    explicit = scatter_values.get("count") or _nested(scatter_values, "repeat", "count")
    if explicit is not None and explicit != "":
        return max(1, min(2048, _positive_int(explicit, default=max(1, option_count))))
    density = _number(scatter_values.get("density") or biome_values.get("density"), default=0.0)
    if density > 0:
        if placement_zone:
            size = _vector3(placement_zone.get("size"), [12.0, 12.0, 4.0])
            area = max(1.0, abs(size[0] * size[1]))
            return max(1, min(2048, int(round(area * density / 8.0))))
        return max(1, min(2048, int(round(density * 24.0))))
    return max(1, min(2048, option_count))


def _scatter_object(
    *,
    scatter: Mapping[str, Any],
    scatter_name: str,
    scatter_values: Mapping[str, Any],
    biome_ref: str,
    biome_values: Mapping[str, Any],
    family_ref: str,
    family_values: Mapping[str, Any],
    option: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
    index: int,
    count: int,
    strategy: str,
    constraints: Sequence[Mapping[str, Any]],
    placement_zone: Mapping[str, Any],
) -> Mapping[str, Any]:
    option_name = _snake_id(option.get("name"), f"scatter_prop_{index}")
    module_ref = _snake_id(option.get("module"), "")
    module = modules.get(module_ref, {}) if module_ref else {}
    module_values = deepcopy(_values(module))
    option_values = deepcopy(dict(option.get("values") if isinstance(option.get("values"), Mapping) else {}))
    values = _merge_scatter_values(module_values, biome_values, family_values, scatter_values, option_values)
    values.setdefault("lathe_asset", option.get("from") or module.get("from") or option_name)
    values.setdefault("source_kit", biome_ref or family_ref or scatter_name)
    values["variant"] = option_name
    transform = _scatter_transform(scatter_values, biome_values, values, index, count, placement_zone)
    values["transform"] = transform
    state = dict(values.get("state", {})) if isinstance(values.get("state"), Mapping) else {}
    density = _number(scatter_values.get("density") or biome_values.get("density"), default=0.0)
    state.update(
        {
            "scatter": scatter_name,
            "scatter_index": index,
            "scatter_count": count,
            "scatter_pattern": _scatter_pattern(scatter_values, biome_values),
            "scatter_seed": _scatter_seed(scatter_values, biome_values),
            "biome": biome_ref,
            "biome_density": round(density, 6),
            "variant_option": option_name,
            "selection_strategy": strategy,
            "selection_constraint_count": len(constraints),
        }
    )
    if placement_zone:
        state.update(_placement_state(placement_zone, index, count))
    if family_ref:
        state["variant_family"] = family_ref
    if module_ref:
        state["kit_module"] = module_ref
    compatibility = _string_list(values.get("compatibility") or biome_values.get("compatibility") or scatter_values.get("compatibility"))
    if compatibility:
        state["compatibility"] = [_snake_id(item, "compat") for item in compatibility]
    _merge_inline_interface_state(state, values)
    values["state"] = state
    tags = _string_list(values.get("semantic_tags") or values.get("tags"))
    tags.extend(["generated", "scatter_instance", "environment_dressing", f"scatter:{scatter_name}", f"variant:{option_name}"])
    if biome_ref:
        tags.append(f"biome:{biome_ref}")
    if family_ref:
        tags.append(f"variant_family:{family_ref}")
    if module_ref:
        tags.append(f"module:{module_ref}")
    values["semantic_tags"] = _dedupe(tags)
    for private_key in (
        "_options",
        "_sockets",
        "_attachments",
        "_constraints",
        "pool",
        "props",
        "objects",
        "modules",
        "module",
        "use",
        "vegetation",
        "rocks",
        "clutter",
        "dressing",
        "weights",
        "defaults",
        "select",
        "strategy",
        "count",
        "density",
        "placement",
        "placement_zone",
        "zone",
        "pattern",
        "scatter_pattern",
        "jitter",
        "radius",
        "scale_min",
        "scale_max",
        "scale_jitter",
        "yaw_jitter",
        "rotation_jitter",
        "random_yaw",
        "biome",
        "environment",
        "habitat",
        "family",
        "variant_family",
        "grammar",
        "variants",
    ):
        values.pop(private_key, None)
    return {
        "node_type": "scene_object",
        "name": f"{scatter_name}_{option_name}_{index + 1:03d}",
        "role": option.get("role") or module.get("role") or scatter.get("role", "") or "dressing_prop",
        "from": option.get("from") or module.get("from") or scatter.get("from", ""),
        "values": values,
    }


def _merge_scatter_values(
    module_values: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    scatter_values: Mapping[str, Any],
    option_values: Mapping[str, Any],
) -> dict[str, Any]:
    values = deepcopy(dict(module_values))
    for source in (biome_values.get("defaults"), family_values.get("defaults"), scatter_values.get("defaults")):
        if isinstance(source, Mapping):
            values.update(deepcopy(dict(source)))
    for source in (biome_values, family_values, scatter_values, option_values):
        values.update(deepcopy({key: value for key, value in source.items() if not str(key).startswith("_")}))
    return values


def _scatter_transform(
    scatter_values: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    part_values: Mapping[str, Any],
    index: int,
    count: int,
    placement_zone: Mapping[str, Any],
) -> dict[str, list[float]]:
    transform = _generator_transform(scatter_values, part_values, index, count, placement_zone)
    pattern = _scatter_pattern(scatter_values, biome_values)
    seed = _scatter_seed(scatter_values, biome_values)
    position = list(transform.get("position", [0.0, 0.0, 0.0]))
    rotation = list(transform.get("rotation", [0.0, 0.0, 0.0]))
    scale = list(transform.get("scale", [1.0, 1.0, 1.0]))
    center = _vector3(placement_zone.get("center"), [0.0, 0.0, 0.0]) if placement_zone else _vector3(scatter_values.get("center") or scatter_values.get("position"), [0.0, 0.0, 0.0])
    if pattern in {"cluster", "clump", "patch"}:
        radius = _number(scatter_values.get("radius") or biome_values.get("radius"), default=4.0)
        angle = _stable_unit(seed, "angle", index) * math.tau
        distance = radius * (_stable_unit(seed, "distance", index) ** 0.5)
        position[0] = round(center[0] + math.cos(angle) * distance, 6)
        position[1] = round(center[1] + math.sin(angle) * distance, 6)
    elif pattern in {"ring", "radial", "circle"}:
        radius = _number(scatter_values.get("radius") or biome_values.get("radius"), default=4.0)
        angle_offset = _number(scatter_values.get("angle_offset") or biome_values.get("angle_offset"), default=0.0)
        angle_degrees = angle_offset + (360.0 * index / max(1, count))
        radians = math.radians(angle_degrees)
        position[0] = round(center[0] + math.cos(radians) * radius, 6)
        position[1] = round(center[1] + math.sin(radians) * radius, 6)
        rotation[2] = round(rotation[2] + angle_degrees, 6)
    jitter = _number(scatter_values.get("jitter") or biome_values.get("jitter"), default=0.0)
    if jitter > 0:
        position[0] = round(position[0] + (_stable_unit(seed, "jx", index) * 2.0 - 1.0) * jitter, 6)
        position[1] = round(position[1] + (_stable_unit(seed, "jy", index) * 2.0 - 1.0) * jitter, 6)
    scale_min = _number(scatter_values.get("scale_min") or biome_values.get("scale_min"), default=1.0)
    scale_max = _number(scatter_values.get("scale_max") or biome_values.get("scale_max"), default=scale_min)
    scale_jitter = _number(scatter_values.get("scale_jitter") or biome_values.get("scale_jitter"), default=0.0)
    if scale_jitter > 0:
        scale_min = max(0.01, 1.0 - scale_jitter)
        scale_max = max(scale_min, 1.0 + scale_jitter)
    if scale_min != 1.0 or scale_max != 1.0:
        factor = scale_min + (scale_max - scale_min) * _stable_unit(seed, "scale", index)
        scale = [round(float(value) * factor, 6) for value in scale]
    yaw_jitter = _number(scatter_values.get("yaw_jitter") or scatter_values.get("rotation_jitter") or biome_values.get("yaw_jitter") or biome_values.get("rotation_jitter"), default=0.0)
    if _truthy(scatter_values.get("random_yaw") or biome_values.get("random_yaw")):
        yaw_jitter = max(yaw_jitter, 180.0)
    if pattern in {"natural", "random", "jittered", "cluster", "clump", "patch"}:
        yaw_jitter = max(yaw_jitter, 180.0)
    if yaw_jitter > 0:
        rotation[2] = round(rotation[2] + (_stable_unit(seed, "yaw", index) * 2.0 - 1.0) * yaw_jitter, 6)
    return {
        "position": [round(float(value), 6) for value in position],
        "rotation": [round(float(value), 6) for value in rotation],
        "scale": [round(float(value), 6) for value in scale],
    }


def _scatter_pattern(scatter_values: Mapping[str, Any], biome_values: Mapping[str, Any]) -> str:
    return _snake_id(
        scatter_values.get("pattern")
        or scatter_values.get("scatter_pattern")
        or scatter_values.get("layout")
        or biome_values.get("pattern")
        or biome_values.get("scatter_pattern")
        or biome_values.get("layout"),
        "grid",
    )


def _scatter_seed(scatter_values: Mapping[str, Any], biome_values: Mapping[str, Any]) -> str:
    return _string(scatter_values.get("seed") or biome_values.get("seed"), default="0")


def _stable_unit(*parts: Any) -> float:
    text = "|".join(str(part) for part in parts)
    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
    return int(digest[:12], 16) / float(0xFFFFFFFFFFFF)


def _expand_scatter_sockets(
    scatter: Mapping[str, Any],
    scatter_values: Mapping[str, Any],
    biome: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    generated_by_key: Mapping[str, list[str]],
    objects: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    socket_nodes = [
        *_mapping_list(biome_values.get("_sockets")),
        *_mapping_list(family_values.get("_sockets")),
        *_mapping_list(scatter_values.get("_sockets")),
    ]
    pseudo = {"name": scatter.get("name") or biome.get("name") or family.get("name")}
    return _expand_kit_sockets(pseudo, {"_sockets": socket_nodes}, generated_by_key, objects)


def _expand_scatter_attachments(
    scatter: Mapping[str, Any],
    scatter_values: Mapping[str, Any],
    biome: Mapping[str, Any],
    biome_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    generated_by_key: Mapping[str, list[str]],
) -> list[Mapping[str, Any]]:
    attachment_nodes = [
        *_mapping_list(biome_values.get("_attachments")),
        *_mapping_list(family_values.get("_attachments")),
        *_mapping_list(scatter_values.get("_attachments")),
    ]
    pseudo = {"name": scatter.get("name") or biome.get("name") or family.get("name")}
    return _expand_kit_attachments(pseudo, {"_attachments": attachment_nodes}, generated_by_key)


def _generator_options(
    generator: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    options: list[dict[str, Any]] = []
    weights = _number_list(generator_values.get("weights") or family_values.get("weights"))
    raw_options = _mapping_list(family_values.get("_options"))
    for index, option in enumerate(raw_options):
        option_values = deepcopy(dict(_values(option)))
        module_ref = _generator_module_ref(option, option_values, generator_values, family_values)
        module_values = deepcopy(_values(modules.get(module_ref, {}))) if module_ref else {}
        options.append(
            {
                "name": _snake_id(option.get("name"), f"option_{index}"),
                "role": option.get("role", ""),
                "from": option.get("from", ""),
                "values": _generator_selection_values(module_values, option_values),
                "module": module_ref,
                "weight": _positive_int(option_values.get("weight") or (weights[index] if index < len(weights) else 1), default=1),
            }
        )
    pool_refs = _generator_pool_refs(generator_values, family_values)
    for index, ref in enumerate(pool_refs):
        if _auto_variant_pool_key(ref) and ref not in modules:
            continue
        if any(option["name"] == ref for option in options):
            continue
        module = modules.get(ref, {})
        options.append(
            {
                "name": ref,
                "role": module.get("role") or generator.get("role") or family.get("role", ""),
                "from": module.get("from") or ref,
                "values": _generator_selection_values(_values(module), {"module": ref}),
                "module": ref,
                "weight": _positive_int(weights[index] if index < len(weights) else 1, default=1),
            }
        )
    auto_options = _auto_generator_options(generator, generator_values, family, family_values, pool_refs, weights)
    include_auto = _truthy(generator_values.get("include_auto") or family_values.get("include_auto") or generator_values.get("auto_options") or family_values.get("auto_options"))
    if auto_options and (include_auto or not options):
        existing = {str(option.get("name")) for option in options}
        options.extend(option for option in auto_options if str(option.get("name")) not in existing)
    return options


def _generator_selection_values(module_values: Mapping[str, Any], option_values: Mapping[str, Any]) -> dict[str, Any]:
    values = deepcopy(dict(module_values))
    values.update(deepcopy(dict(option_values)))
    return values


def _auto_generator_options(
    generator: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    pool_refs: Sequence[str],
    weights: Sequence[int],
) -> list[dict[str, Any]]:
    pool_keys = _auto_variant_pool_keys(generator, generator_values, family, family_values, pool_refs)
    options: list[dict[str, Any]] = []
    weight_index = 0
    for pool_key in pool_keys:
        for preset in _AUTO_VARIANT_POOLS.get(pool_key, ()):
            values = deepcopy(dict(preset.get("values") if isinstance(preset.get("values"), Mapping) else {}))
            state = dict(values.get("state") if isinstance(values.get("state"), Mapping) else {})
            state.setdefault("auto_variant_pool", pool_key)
            state.setdefault("auto_variant_family", _snake_id(family.get("name") or family_values.get("family") or pool_key, pool_key))
            values["state"] = state
            values.setdefault("variant_family_kind", pool_key)
            values.setdefault("auto_variant_family", pool_key)
            options.append(
                {
                    "name": _snake_id(preset.get("name"), f"{pool_key}_option_{len(options)}"),
                    "role": preset.get("role") or generator.get("role") or family.get("role", ""),
                    "from": preset.get("from") or generator.get("from") or family.get("from", ""),
                    "values": values,
                    "module": "",
                    "weight": _positive_int(
                        weights[weight_index] if weight_index < len(weights) else preset.get("weight"),
                        default=1,
                    ),
                }
            )
            weight_index += 1
    return options


def _auto_variant_pool_keys(
    generator: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    pool_refs: Sequence[str],
) -> list[str]:
    keys: list[str] = []
    for ref in pool_refs:
        key = _auto_variant_pool_key(ref)
        if key:
            keys.append(key)
    for source in (family_values, generator_values):
        for field in (
            "family",
            "families",
            "asset_family",
            "asset_families",
            "kind",
            "type",
            "source_family",
            "procedural_family",
            "pool_family",
            "pool_kind",
            "archetype",
            "object_archetype",
            "setpiece",
            "loadout",
            "family_loadout",
            "visual_system",
            "kit_style",
            "theme_pack",
        ):
            for value in _string_list(source.get(field)):
                key = _auto_variant_pool_key(value)
                if key:
                    keys.append(key)
    for value in (family.get("name"), family.get("from"), generator.get("name"), generator.get("from")):
        key = _auto_variant_pool_key(value)
        if key:
            keys.append(key)
    return _dedupe(keys)


def _auto_variant_pool_key(value: Any) -> str:
    text = _snake_id(value, "")
    if not text:
        return ""
    candidates = [text, *_string_list(text.replace("_", " "))]
    candidates.extend(part for part in text.split("_") if part)
    for candidate in candidates:
        if candidate in _AUTO_VARIANT_POOLS:
            return candidate
        alias = _AUTO_VARIANT_ALIASES.get(candidate)
        if alias:
            return alias
    for token, alias in _AUTO_VARIANT_ALIASES.items():
        if token in text:
            return alias
    for token in _AUTO_VARIANT_POOLS:
        if token in text:
            return token
    return ""


def _generator_pool_refs(generator_values: Mapping[str, Any], family_values: Mapping[str, Any]) -> list[str]:
    for source in (generator_values, family_values):
        for key in ("pool", "parts", "modules", "use", "options"):
            refs = _string_list(source.get(key))
            if refs:
                return [_snake_id(ref, "option") for ref in refs]
    return []


def _generator_module_ref(
    option: Mapping[str, Any],
    option_values: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
) -> str:
    for value in (
        option_values.get("module"),
        option_values.get("use"),
        option.get("from"),
        generator_values.get("module"),
        family_values.get("module"),
    ):
        refs = _string_list(value)
        if refs:
            return _snake_id(refs[0], "module")
    return ""


def _select_generator_option(
    options: Sequence[Mapping[str, Any]],
    index: int,
    strategy: str,
    *,
    constraints: Sequence[Mapping[str, Any]],
    selected: Sequence[Mapping[str, Any]],
    count: int,
) -> Mapping[str, Any]:
    if not options:
        return {}
    weighted: list[Mapping[str, Any]] = []
    for option in options:
        weight = _positive_int(option.get("weight"), default=1)
        weighted.extend([option] * max(1, min(weight, 64)))
    pool = weighted if "weight" in strategy and weighted else list(options)
    if pool:
        offset = index % len(pool)
        rotated = [*pool[offset:], *pool[:offset]]
        for candidate in rotated:
            if _option_satisfies_constraints(candidate, index, count, selected, constraints):
                return candidate
    if strategy in {"mirror", "ping_pong", "palindrome"} and len(pool) > 1:
        period = len(pool) * 2 - 2
        pos = index % period
        return pool[pos if pos < len(pool) else period - pos]
    if strategy in {"reverse", "reverse_cycle"}:
        return pool[-1 - (index % len(pool))]
    return pool[index % len(pool)]


def _generator_constraints(generator_values: Mapping[str, Any], family_values: Mapping[str, Any]) -> list[dict[str, Any]]:
    constraints: list[dict[str, Any]] = []
    for raw in [*_mapping_list(family_values.get("_constraints")), *_mapping_list(generator_values.get("_constraints"))]:
        values = dict(_values(raw))
        constraints.append(
            {
                "name": _snake_id(raw.get("name"), "constraint"),
                "type": _snake_id(raw.get("type") or values.get("type"), "selection"),
                "values": values,
            }
        )
    for source_name, source in (("family", family_values), ("generator", generator_values)):
        inline: dict[str, Any] = {}
        for key in (
            "requires",
            "requires_any",
            "requires_all",
            "requires_socket",
            "requires_compatibility",
            "requires_family",
            "family",
            "requires_loadout",
            "loadout",
            "requires_style",
            "style",
            "requires_tag",
            "tag",
            "connects_to",
            "forbid",
            "forbidden",
            "forbid_adjacent",
            "avoid_repeat",
            "start_with",
            "end_with",
            "every",
        ):
            if key in source:
                inline[key] = source[key]
        if inline:
            constraints.append({"name": f"{source_name}_inline", "type": "selection", "values": inline})
    return constraints


def _generator_placement_zone(
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    placement_zones: Mapping[str, Mapping[str, Any]],
) -> Mapping[str, Any]:
    ref = _snake_id(
        generator_values.get("placement_zone")
        or generator_values.get("zone")
        or _nested(generator_values, "placement", "zone")
        or family_values.get("placement_zone")
        or family_values.get("zone"),
        "",
    )
    zone = dict(placement_zones.get(ref, {})) if ref else {}
    inline = generator_values.get("placement") if isinstance(generator_values.get("placement"), Mapping) else {}
    for source in (family_values, generator_values, inline if isinstance(inline, Mapping) else {}):
        for key, value in source.items():
            if key in {
                "placement_kind",
                "placement_type",
                "surface",
                "side",
                "wall",
                "edge",
                "axis",
                "rows",
                "columns",
                "cols",
                "spacing",
                "elevation",
                "margin",
                "setback",
                "facing",
                "align",
                "alignment",
            }:
                zone[key] = value
    if not zone and inline:
        center = _vector3(inline.get("center") or inline.get("position"), [0.0, 0.0, 0.0])
        size = _vector3(inline.get("size"), [12.0, 12.0, 4.0])
        zone = {"name": "inline_placement", "type": _snake_id(inline.get("type") or inline.get("kind"), "grid"), "center": center, "size": size}
    if zone:
        zone.setdefault("name", ref or "inline_placement")
        zone["type"] = _snake_id(zone.get("placement_kind") or zone.get("placement_type") or zone.get("type"), "grid")
        zone["side"] = _snake_id(zone.get("side") or zone.get("wall") or zone.get("edge"), "center")
        zone["surface"] = _snake_id(zone.get("surface") or zone.get("type"), "grid")
        zone["axis"] = _snake_id(zone.get("axis"), "x")
        zone["rows"] = _positive_int(zone.get("rows"), default=0)
        zone["columns"] = _positive_int(zone.get("columns") or zone.get("cols"), default=0)
        zone["spacing"] = _number(zone.get("spacing"), default=0.0)
        zone["elevation"] = _number(zone.get("elevation"), default=0.0)
        zone["margin"] = _number(zone.get("margin") or zone.get("setback"), default=0.0)
        zone["facing"] = _snake_id(zone.get("facing"), "inward")
        zone["align"] = _snake_id(zone.get("align") or zone.get("alignment"), "center")
    return zone


def _option_satisfies_constraints(
    option: Mapping[str, Any],
    index: int,
    count: int,
    selected: Sequence[Mapping[str, Any]],
    constraints: Sequence[Mapping[str, Any]],
) -> bool:
    return all(
        _option_satisfies_constraint(option, index, count, selected, constraint)
        for constraint in constraints
        if _constraint_applies(index, count, constraint)
    )


def _constraint_applies(index: int, count: int, constraint: Mapping[str, Any]) -> bool:
    values = constraint.get("values") if isinstance(constraint.get("values"), Mapping) else {}
    if not isinstance(values, Mapping):
        return False
    slot = values.get("index", values.get("at", values.get("slot")))
    if isinstance(slot, str):
        slot_name = _snake_id(slot, "")
        if slot_name in {"first", "start"}:
            return index == 0
        if slot_name in {"last", "end"}:
            return index == count - 1
    elif isinstance(slot, int | float) and not isinstance(slot, bool):
        return index == int(slot)
    every = _positive_int(values.get("every"), default=0)
    if every and index % every != 0:
        return False
    start = values.get("from_index", values.get("start_index"))
    if isinstance(start, int | float) and not isinstance(start, bool) and index < int(start):
        return False
    end = values.get("to_index", values.get("end_index"))
    if isinstance(end, int | float) and not isinstance(end, bool) and index > int(end):
        return False
    return True


def _option_satisfies_constraint(
    option: Mapping[str, Any],
    index: int,
    count: int,
    selected: Sequence[Mapping[str, Any]],
    constraint: Mapping[str, Any],
) -> bool:
    values = constraint.get("values") if isinstance(constraint.get("values"), Mapping) else {}
    if not isinstance(values, Mapping):
        return True
    tokens = _option_tokens(option)
    sockets = _option_socket_tokens(option)
    if index == 0 and not _tokens_match(tokens, _constraint_tokens(values, "start_with", "starts_with")):
        return False
    if index == count - 1 and not _tokens_match(tokens, _constraint_tokens(values, "end_with", "ends_with")):
        return False
    required_all = _constraint_tokens(values, "requires_all", "must_have_all")
    if required_all and not set(required_all).issubset(tokens | sockets):
        return False
    token_space = tokens | sockets
    for typed_keys in (
        ("requires_family", "family"),
        ("requires_loadout", "loadout"),
        ("requires_style", "style"),
        ("requires_tag", "tag"),
    ):
        required_typed = _constraint_tokens(values, *typed_keys)
        if required_typed and not (token_space & set(required_typed)):
            return False
    required_any = _constraint_tokens(values, "requires", "require", "requires_any", "must_have", "match")
    if required_any and not ((tokens | sockets) & set(required_any)):
        return False
    compat = _constraint_tokens(values, "requires_compatibility", "compatibility", "connects_to", "for_connection", "target")
    if compat and not (tokens & set(compat)):
        return False
    required_sockets = _constraint_tokens(values, "requires_socket", "socket", "provides_socket")
    if required_sockets and not (sockets & set(required_sockets)):
        return False
    forbidden = _constraint_tokens(values, "forbid", "forbidden", "deny", "exclude")
    if forbidden and ((tokens | sockets) & set(forbidden)):
        return False
    if _truthy(values.get("avoid_repeat")) and selected and _option_identity(option) == _option_identity(selected[-1]):
        return False
    adjacent_tokens = set(_constraint_tokens(values, "forbid_adjacent", "not_adjacent_to", "avoid_adjacent"))
    if adjacent_tokens and selected:
        previous_tokens = _option_tokens(selected[-1]) | _option_socket_tokens(selected[-1])
        if (previous_tokens & adjacent_tokens) and ((tokens | sockets) & adjacent_tokens):
            return False
    return True


def _constraint_tokens(values: Mapping[str, Any], *keys: str) -> list[str]:
    for key in keys:
        tokens = [_snake_id(item, "token") for item in _string_list(values.get(key))]
        if tokens:
            return tokens
    return []


def _tokens_match(tokens: set[str], required: Sequence[str]) -> bool:
    return not required or bool(tokens & set(required))


def _option_tokens(option: Mapping[str, Any]) -> set[str]:
    values = option.get("values") if isinstance(option.get("values"), Mapping) else {}
    tokens = {
        _snake_id(option.get("name"), ""),
        _snake_id(option.get("module"), ""),
        _snake_id(option.get("role"), ""),
        _snake_id(option.get("from"), ""),
    }
    if isinstance(values, Mapping):
        state = values.get("state") if isinstance(values.get("state"), Mapping) else {}
        for key in ("compatibility", "tags", "semantic_tags", "provides", "provides_tags", "requires", "style"):
            tokens.update(_snake_id(item, "token") for item in _string_list(values.get(key)))
        for key in (
            "kind",
            "type",
            "source_family",
            "source_kit",
            "lathe_asset",
            "asset",
            "variant_family_kind",
            "auto_variant_family",
            "archetype",
            "object_archetype",
            "loadout",
            "family_loadout",
            "vehicle_loadout",
            "boat_loadout",
            "vessel_loadout",
            "weapon_loadout",
            "tool_loadout",
            "style_pack",
            "visual_system",
        ):
            text = _snake_id(values.get(key), "")
            if text:
                tokens.add(text)
                tokens.update(part for part in text.split("_") if part)
            if isinstance(state, Mapping):
                state_text = _snake_id(state.get(key), "")
                if state_text:
                    tokens.add(state_text)
                    tokens.update(part for part in state_text.split("_") if part)
    return {token for token in tokens if token}


def _option_socket_tokens(option: Mapping[str, Any]) -> set[str]:
    values = option.get("values") if isinstance(option.get("values"), Mapping) else {}
    sockets: set[str] = set()
    if isinstance(values, Mapping):
        for key in ("sockets", "module_sockets", "composition_sockets", "anchors", "module_anchors"):
            sockets.update(_snake_id(item, "socket") for item in _string_list(values.get(key)))
    return {socket for socket in sockets if socket}


def _option_identity(option: Mapping[str, Any]) -> str:
    return _snake_id(option.get("name") or option.get("module"), "option")


def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.lower() in {"1", "true", "yes", "on", "avoid", "no_repeat"}
    return bool(value)


def _generator_transform(
    generator_values: Mapping[str, Any],
    part_values: Mapping[str, Any],
    index: int,
    count: int,
    placement_zone: Mapping[str, Any],
) -> dict[str, list[float]]:
    if not placement_zone:
        return _kit_part_transform(generator_values, part_values, index, count)
    zone_type = _snake_id(placement_zone.get("type"), "grid")
    center = _vector3(placement_zone.get("center"), [0.0, 0.0, 0.0])
    size = _vector3(placement_zone.get("size"), [12.0, 12.0, 4.0])
    base = _kit_part_transform(generator_values, part_values, index, count)
    rotation = list(base.get("rotation", [0.0, 0.0, 0.0]))
    scale = list(base.get("scale", [1.0, 1.0, 1.0]))
    margin = _number(placement_zone.get("margin"), default=0.0)
    elevation = _number(placement_zone.get("elevation"), default=0.0)
    if zone_type in {"frontage", "road_frontage", "facade", "wall", "interior_wall", "edge"}:
        position, yaw = _frontage_position(placement_zone, center, size, index, count, margin, elevation)
        rotation[2] = round(rotation[2] + yaw, 6)
    elif zone_type in {"ceiling", "ceiling_grid"}:
        position = _grid_position(placement_zone, center, size, index, count, z_value=center[2] + size[2] * 0.5 - elevation)
    elif zone_type in {"floor", "floor_grid", "terrain", "terrain_patch", "ground", "grid", "zone"}:
        position = _grid_position(placement_zone, center, size, index, count, z_value=center[2] - size[2] * 0.5 + elevation)
    elif zone_type in {"line", "path", "road_edge"}:
        position, yaw = _line_position(placement_zone, center, size, index, count, margin, elevation)
        rotation[2] = round(rotation[2] + yaw, 6)
    else:
        position = _grid_position(placement_zone, center, size, index, count, z_value=center[2] + elevation)
    part_offset = _vector3(part_values.get("offset") or _nested(part_values, "placement", "offset"), [0.0, 0.0, 0.0])
    return {
        "position": [round(position[i] + part_offset[i], 6) for i in range(3)],
        "rotation": [round(float(value), 6) for value in rotation],
        "scale": [round(float(value), 6) for value in scale],
    }


def _frontage_position(
    zone: Mapping[str, Any],
    center: Sequence[float],
    size: Sequence[float],
    index: int,
    count: int,
    margin: float,
    elevation: float,
) -> tuple[list[float], float]:
    side = _snake_id(zone.get("side"), "north")
    usable_x = max(0.1, float(size[0]) - margin * 2.0)
    usable_y = max(0.1, float(size[1]) - margin * 2.0)
    t = (index + 0.5) / max(1, count)
    if side in {"east", "right"}:
        return [center[0] + size[0] * 0.5 - margin, center[1] - usable_y * 0.5 + usable_y * t, center[2] + elevation], 180.0
    if side in {"west", "left"}:
        return [center[0] - size[0] * 0.5 + margin, center[1] - usable_y * 0.5 + usable_y * t, center[2] + elevation], 0.0
    if side in {"south", "bottom"}:
        return [center[0] - usable_x * 0.5 + usable_x * t, center[1] - size[1] * 0.5 + margin, center[2] + elevation], 90.0
    return [center[0] - usable_x * 0.5 + usable_x * t, center[1] + size[1] * 0.5 - margin, center[2] + elevation], -90.0


def _line_position(
    zone: Mapping[str, Any],
    center: Sequence[float],
    size: Sequence[float],
    index: int,
    count: int,
    margin: float,
    elevation: float,
) -> tuple[list[float], float]:
    axis = _snake_id(zone.get("axis"), "x")
    t = (index + 0.5) / max(1, count)
    if axis == "y":
        usable = max(0.1, float(size[1]) - margin * 2.0)
        return [center[0], center[1] - usable * 0.5 + usable * t, center[2] + elevation], 90.0
    usable = max(0.1, float(size[0]) - margin * 2.0)
    return [center[0] - usable * 0.5 + usable * t, center[1], center[2] + elevation], 0.0


def _grid_position(
    zone: Mapping[str, Any],
    center: Sequence[float],
    size: Sequence[float],
    index: int,
    count: int,
    *,
    z_value: float,
) -> list[float]:
    columns = _positive_int(zone.get("columns"), default=0)
    if not columns:
        columns = max(1, math.ceil(count**0.5))
    rows = _positive_int(zone.get("rows"), default=0)
    if not rows:
        rows = max(1, math.ceil(count / max(1, columns)))
    col = index % max(1, columns)
    row = index // max(1, columns)
    x = center[0] - size[0] * 0.5 + size[0] * ((col + 0.5) / max(1, columns))
    y = center[1] - size[1] * 0.5 + size[1] * ((row + 0.5) / max(1, rows))
    return [round(x, 6), round(y, 6), round(z_value, 6)]


def _placement_state(zone: Mapping[str, Any], index: int, count: int) -> dict[str, Any]:
    state = {
        "placement_zone": _snake_id(zone.get("name"), "placement_zone"),
        "placement_kind": _snake_id(zone.get("type"), "grid"),
        "placement_surface": _snake_id(zone.get("surface"), "surface"),
        "placement_side": _snake_id(zone.get("side"), "center"),
        "placement_index": index,
        "placement_count": count,
    }
    for key in ("region", "rows", "columns", "spacing", "elevation", "margin", "facing", "align"):
        value = zone.get(key)
        if isinstance(value, str | int | float | bool) and value not in {"", None}:
            state[f"placement_{key}"] = value
    return state


def _generator_object(
    *,
    generator: Mapping[str, Any],
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_ref: str,
    family_values: Mapping[str, Any],
    option: Mapping[str, Any],
    modules: Mapping[str, Mapping[str, Any]],
    index: int,
    count: int,
    strategy: str,
    constraints: Sequence[Mapping[str, Any]],
    placement_zone: Mapping[str, Any],
) -> Mapping[str, Any]:
    option_name = _snake_id(option.get("name"), f"option_{index}")
    module_ref = _snake_id(option.get("module"), "")
    module = modules.get(module_ref, {}) if module_ref else {}
    module_values = deepcopy(_values(module))
    option_values = deepcopy(dict(option.get("values") if isinstance(option.get("values"), Mapping) else {}))
    values = _merge_generator_values(module_values, family_values, generator_values, option_values)
    transform = _generator_transform(generator_values, values, index, count, placement_zone)
    values["transform"] = transform
    state = dict(values.get("state", {})) if isinstance(values.get("state"), Mapping) else {}
    state.update(
        {
            "generator": generator_name,
            "generator_index": index,
            "generator_count": count,
            "variant_option": option_name,
            "selection_strategy": strategy,
            "selection_constraint_count": len(constraints),
        }
    )
    constraint_names = [_snake_id(item.get("name"), "constraint") for item in constraints if isinstance(item, Mapping)]
    if constraint_names:
        state["selection_constraints"] = _dedupe(constraint_names)
    if placement_zone:
        state.update(_placement_state(placement_zone, index, count))
    if family_ref:
        state["variant_family"] = family_ref
    if module_ref:
        state["kit_module"] = module_ref
    compatibility = _string_list(values.get("compatibility") or family_values.get("compatibility") or generator_values.get("compatibility"))
    if compatibility:
        state["compatibility"] = [_snake_id(item, "compat") for item in compatibility]
    _merge_inline_interface_state(state, values)
    values["state"] = state
    tags = _string_list(values.get("semantic_tags") or values.get("tags"))
    tags.extend(["generated", "variant_instance", f"generator:{generator_name}", f"variant:{option_name}"])
    if family_ref:
        tags.append(f"variant_family:{family_ref}")
    if module_ref:
        tags.append(f"module:{module_ref}")
    values["semantic_tags"] = _dedupe(tags)
    values["source_kit"] = family_ref or generator_name
    values["variant"] = option_name
    for private_key in (
        "_options",
        "_sockets",
        "_attachments",
        "pool",
        "parts",
        "modules",
        "module",
        "use",
        "weights",
        "defaults",
        "select",
        "strategy",
    ):
        values.pop(private_key, None)
    return {
        "node_type": "scene_object",
        "name": f"{generator_name}_{option_name}_{index + 1:02d}",
        "role": option.get("role") or module.get("role") or generator.get("role", ""),
        "from": option.get("from") or module.get("from") or generator.get("from", ""),
        "values": values,
    }


def _merge_generator_values(
    module_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    option_values: Mapping[str, Any],
) -> dict[str, Any]:
    values = deepcopy(dict(module_values))
    for source in (family_values.get("defaults"), generator_values.get("defaults")):
        if isinstance(source, Mapping):
            values.update(deepcopy(dict(source)))
    for source in (family_values, generator_values):
        for key, value in _generator_direct_defaults(source).items():
            values.setdefault(key, value)
    values.update(deepcopy(dict(option_values)))
    values.update({key: deepcopy(value) for key, value in generator_values.items() if key in {"surface", "surface_overrides", "material", "material_bindings"}})
    return values


def _generator_direct_defaults(source: Mapping[str, Any]) -> dict[str, Any]:
    defaults: dict[str, Any] = {}
    for key, value in source.items():
        if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
            continue
        if key.startswith("_") or key in _GENERATOR_VALUE_RESERVED_KEYS or key in _SURFACE_OVERRIDE_KEYS:
            continue
        normalized = _surface_value(value)
        if isinstance(normalized, str | int | float | bool | list | dict) or normalized is None:
            defaults[key] = normalized
    return defaults


def _generator_option_keys(option: Mapping[str, Any], family_ref: str) -> list[str]:
    keys = ["all"]
    for value in (option.get("name"), option.get("module"), family_ref):
        text = _snake_id(value, "")
        if text:
            keys.append(text)
    return _dedupe(keys)


def _expand_generator_sockets(
    generator: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    generated_by_key: Mapping[str, list[str]],
    objects: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    socket_nodes = [*_mapping_list(family_values.get("_sockets")), *_mapping_list(generator_values.get("_sockets"))]
    pseudo = {"name": generator.get("name")}
    return _expand_kit_sockets(pseudo, {"_sockets": socket_nodes}, generated_by_key, objects)


def _expand_generator_attachments(
    generator: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    family: Mapping[str, Any],
    family_values: Mapping[str, Any],
    generated_by_key: Mapping[str, list[str]],
) -> list[Mapping[str, Any]]:
    attachment_nodes = [*_mapping_list(family_values.get("_attachments")), *_mapping_list(generator_values.get("_attachments"))]
    pseudo = {"name": generator.get("name")}
    return _expand_kit_attachments(pseudo, {"_attachments": attachment_nodes}, generated_by_key)


def _auto_generator_assembly(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_ref: str,
    family_values: Mapping[str, Any],
    objects: Sequence[Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    names = [_string(obj.get("name")) for obj in objects if _string(obj.get("name"))]
    if not names:
        return [], [], []
    family_kind = _generator_assembly_family(generator_name, generator_values, family_ref, family_values, objects)
    mode = _generator_assembly_mode(generator_name, generator_values, family_ref, family_values, family_kind, objects)
    if not mode:
        return [], [], []

    profile = _assembly_profile(mode, family_kind)
    _mark_generator_assembly_objects(objects, generator_name, mode, family_kind)
    if mode in _AUTO_ASSEMBLY_CHAIN_MODES or profile.get("chain_only"):
        return [], [], _assembly_chain_attachments(generator_name, generator_values, family_values, mode, family_kind, objects, profile)

    target_ref = _assembly_target_ref(generator_values, family_values)
    anchor_objects: list[Mapping[str, Any]] = []
    if not target_ref and _assembly_anchor_enabled(generator_values, family_values, default=True):
        anchor = _assembly_anchor_object(
            generator_name,
            generator_values,
            family_ref,
            family_values,
            mode,
            family_kind,
            profile,
            len(names),
        )
        anchor_objects.append(anchor)
        target_ref = _string(anchor.get("name"))
    if not target_ref:
        return [], [], _assembly_chain_attachments(generator_name, generator_values, family_values, mode, family_kind, objects, profile)

    sockets = _assembly_anchor_sockets(
        generator_name,
        generator_values,
        family_values,
        mode,
        family_kind,
        profile,
        target_ref,
        objects,
    )
    attachments = _assembly_anchor_attachments(
        generator_name,
        generator_values,
        family_values,
        mode,
        family_kind,
        profile,
        target_ref,
        objects,
        sockets,
    )
    if _truthy(generator_values.get("chain") or generator_values.get("connect_generated")):
        attachments.extend(
            _assembly_chain_attachments(generator_name, generator_values, family_values, mode, family_kind, objects, profile)
        )
    return anchor_objects, sockets, attachments


def _generator_assembly_family(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_ref: str,
    family_values: Mapping[str, Any],
    objects: Sequence[Mapping[str, Any]],
) -> str:
    scores: dict[str, int] = {}
    for value in (
        family_ref,
        generator_name,
        generator_values.get("family"),
        generator_values.get("variant_family"),
        generator_values.get("source_family"),
        generator_values.get("procedural_family"),
        generator_values.get("pool"),
        family_values.get("family"),
        family_values.get("source_family"),
        family_values.get("procedural_family"),
        family_values.get("pool"),
    ):
        for item in _string_list(value):
            key = _auto_variant_pool_key(item)
            if key:
                scores[key] = scores.get(key, 0) + 4
    for obj in objects:
        for token in _object_tokens(obj):
            key = _auto_variant_pool_key(token)
            if key:
                scores[key] = scores.get(key, 0) + 1
    if not scores:
        return "object"
    priority = {name: index for index, name in enumerate(_AUTO_VARIANT_POOLS)}
    return sorted(scores, key=lambda key: (-scores[key], priority.get(key, 999), key))[0]


def _generator_assembly_mode(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_ref: str,
    family_values: Mapping[str, Any],
    family_kind: str,
    objects: Sequence[Mapping[str, Any]],
) -> str:
    tokens = _assembly_tokens(generator_name, generator_values, family_ref, family_values, objects)
    for source in (generator_values, family_values):
        for key in ("assembly", "assembly_mode", "assembly_kind", "assembly_layout"):
            if key not in source:
                continue
            value = source.get(key)
            if isinstance(value, bool):
                return _assembly_default_mode(family_kind, tokens) if value else ""
            mode = _assembly_mode_from_text(value)
            return _assembly_mode_for_family(mode, family_kind, tokens) or _assembly_default_mode(family_kind, tokens)
    name_mode = _assembly_mode_from_text(generator_name) or _assembly_mode_from_text(family_ref)
    if name_mode:
        return _assembly_mode_for_family(name_mode, family_kind, tokens)
    if _truthy(generator_values.get("auto_assemble") or generator_values.get("auto_assembly") or family_values.get("auto_assemble") or family_values.get("auto_assembly")):
        return _assembly_default_mode(family_kind, tokens)
    return ""


def _assembly_mode_for_family(mode: str, family_kind: str, tokens: set[str]) -> str:
    if mode == "docking_bay" and family_kind == "vehicle" and tokens & {"fleet", "vehicle", "rover", "drone", "car"}:
        return "parking"
    if mode in {"parking", "hangar"} and family_kind == "boat":
        return "docking_bay"
    if mode == "rack" and family_kind in {"interior", "furniture"}:
        return "room_layout"
    if mode == "site_plan" and family_kind in {"road", "access", "infrastructure"}:
        return _assembly_default_mode(family_kind, tokens)
    return mode


def _assembly_mode_from_text(value: Any) -> str:
    text = _snake_id(value, "")
    if not text:
        return ""
    if text in _AUTO_ASSEMBLY_PROFILES or text in _AUTO_ASSEMBLY_CHAIN_MODES:
        return text
    alias = _AUTO_ASSEMBLY_ALIASES.get(text)
    if alias:
        return alias
    for part in text.split("_"):
        alias = _AUTO_ASSEMBLY_ALIASES.get(part)
        if alias:
            return alias
    for token, mode in _AUTO_ASSEMBLY_ALIASES.items():
        if token in text:
            return mode
    for mode in [*_AUTO_ASSEMBLY_PROFILES, *_AUTO_ASSEMBLY_CHAIN_MODES]:
        if mode in text:
            return mode
    return ""


def _assembly_default_mode(family_kind: str, tokens: set[str]) -> str:
    if tokens & {"rack", "armory", "weapon_rack", "tool_rack"}:
        return "rack"
    if tokens & {"dock", "docking", "harbor", "harbour", "mooring", "pier"}:
        return "docking_bay"
    if tokens & {"hangar", "flight_deck", "landing_pad"}:
        return "hangar"
    if tokens & {"parking", "garage", "service_yard", "vehicle_yard"}:
        return "parking"
    if tokens & {"room", "interior_layout", "furniture_layout"}:
        return "room_layout"
    if tokens & {"assembly_line", "factory_line", "production_line"}:
        return "machine_line"
    if tokens & {"district", "city", "site_plan", "lot_plan"}:
        return "site_plan"
    if family_kind == "boat":
        return "docking_bay"
    if family_kind == "weapon":
        return "rack"
    if family_kind == "vehicle":
        return "hangar" if tokens & {"air", "aircraft", "vtol", "drone", "rotor"} else "parking"
    if family_kind in {"interior", "furniture"}:
        return "room_layout"
    if family_kind == "machine":
        return "machine_line"
    if family_kind == "building":
        return "site_plan"
    if family_kind == "foliage":
        return "terrain_cluster"
    if family_kind == "road":
        return "route_network"
    if family_kind == "access":
        return "access_chain"
    if family_kind == "infrastructure":
        return "utility_run"
    return "site_plan"


def _assembly_tokens(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_ref: str,
    family_values: Mapping[str, Any],
    objects: Sequence[Mapping[str, Any]],
) -> set[str]:
    tokens: set[str] = set()
    for value in (generator_name, family_ref, generator_values.get("name"), family_values.get("name")):
        text = _snake_id(value, "")
        if text:
            tokens.add(text)
            tokens.update(part for part in text.split("_") if part)
    for source in (generator_values, family_values):
        for key in (
            "family",
            "source_family",
            "procedural_family",
            "pool",
            "archetype",
            "object_archetype",
            "loadout",
            "family_loadout",
            "vehicle_loadout",
            "boat_loadout",
            "vessel_loadout",
            "weapon_loadout",
            "tool_loadout",
            "style_pack",
            "visual_system",
            "semantic_tags",
            "tags",
            "compatibility",
        ):
            for item in _string_list(source.get(key)):
                text = _snake_id(item, "")
                if text:
                    tokens.add(text)
                    tokens.update(part for part in text.split("_") if part)
    for obj in objects:
        tokens.update(_object_tokens(obj))
    return {token for token in tokens if token}


def _assembly_profile(mode: str, family_kind: str) -> dict[str, Any]:
    if mode in _AUTO_ASSEMBLY_PROFILES:
        return deepcopy(_AUTO_ASSEMBLY_PROFILES[mode])
    if mode in _AUTO_ASSEMBLY_CHAIN_MODES:
        return {
            "chain_only": True,
            "attachment_mode": "connect" if family_kind in {"road", "access", "infrastructure"} else "snap",
            "chain_socket": _assembly_chain_socket(family_kind),
        }
    if family_kind == "boat":
        return deepcopy(_AUTO_ASSEMBLY_PROFILES["docking_bay"])
    if family_kind == "weapon":
        return deepcopy(_AUTO_ASSEMBLY_PROFILES["rack"])
    if family_kind == "vehicle":
        return deepcopy(_AUTO_ASSEMBLY_PROFILES["parking"])
    if family_kind in {"interior", "furniture"}:
        return deepcopy(_AUTO_ASSEMBLY_PROFILES["room_layout"])
    if family_kind == "machine":
        return deepcopy(_AUTO_ASSEMBLY_PROFILES["machine_line"])
    if family_kind == "foliage":
        return deepcopy(_AUTO_ASSEMBLY_PROFILES["terrain_cluster"])
    return deepcopy(_AUTO_ASSEMBLY_PROFILES["site_plan"])


def _assembly_target_ref(generator_values: Mapping[str, Any], family_values: Mapping[str, Any]) -> str:
    for source in (generator_values, family_values):
        for key in ("assembly_target", "assembly_parent", "assembly_attach_to", "attach_to", "anchor"):
            value = source.get(key)
            if isinstance(value, str) and value.strip():
                target = _snake_id(value, "")
                if target and target not in {"false", "none", "off", "no"}:
                    return target
    return ""


def _assembly_anchor_enabled(generator_values: Mapping[str, Any], family_values: Mapping[str, Any], *, default: bool) -> bool:
    for source in (generator_values, family_values):
        for key in ("anchor_object", "assembly_anchor"):
            if key not in source:
                continue
            value = source.get(key)
            if isinstance(value, bool):
                return value
            if isinstance(value, str):
                text = value.strip().lower()
                if text in {"0", "false", "no", "off", "none"}:
                    return False
                if text in {"1", "true", "yes", "on", "anchor"}:
                    return True
    return default


def _assembly_anchor_object(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_ref: str,
    family_values: Mapping[str, Any],
    mode: str,
    family_kind: str,
    profile: Mapping[str, Any],
    count: int,
) -> Mapping[str, Any]:
    anchor_name = _snake_id(
        generator_values.get("anchor_name") or family_values.get("anchor_name") or f"{generator_name}_{mode}_anchor",
        f"{generator_name}_assembly_anchor",
    )
    anchor_asset = _snake_id(
        generator_values.get("anchor_asset")
        or generator_values.get("assembly_asset")
        or family_values.get("anchor_asset")
        or family_values.get("assembly_asset")
        or profile.get("anchor_asset"),
        "procedural_infrastructure",
    )
    source_family = _snake_id(
        generator_values.get("anchor_source_family")
        or generator_values.get("assembly_source_family")
        or family_values.get("anchor_source_family")
        or family_values.get("assembly_source_family")
        or profile.get("source_family")
        or anchor_asset,
        anchor_asset,
    )
    values: dict[str, Any] = {
        "lathe_asset": anchor_asset,
        "source_family": source_family,
        "source_kit": family_ref or generator_name,
        "variant": f"{mode}_anchor",
    }
    for key in ("region", "material", "material_bindings", "surface", "surface_overrides"):
        if key in generator_values:
            values[key] = deepcopy(generator_values[key])
        elif key in family_values:
            values[key] = deepcopy(family_values[key])
    for payload in (
        profile.get("defaults"),
        family_values.get("anchor_defaults"),
        family_values.get("assembly_anchor_defaults"),
        generator_values.get("anchor_defaults"),
        generator_values.get("assembly_anchor_defaults"),
    ):
        if isinstance(payload, Mapping):
            _merge_anchor_payload(values, payload)
    transform = _assembly_anchor_transform(generator_values, family_values)
    if transform:
        values["transform"] = transform

    state = _state(values.get("state"))
    state.update(
        {
            "generator": generator_name,
            "generated_assembly": True,
            "assembly_anchor": True,
            "assembly_mode": mode,
            "assembly_family": family_kind,
            "assembly_count": count,
        }
    )
    for key in ("service_type", "room_role", "district_anchor", "terrain_anchor"):
        if key in profile:
            state[key] = deepcopy(profile[key])
    target_sockets = [_snake_id(item, "socket") for item in _string_list(profile.get("target_sockets"))]
    if target_sockets:
        state["assembly_sockets"] = target_sockets
    values["state"] = state
    tags = _string_list(values.get("semantic_tags") or values.get("tags"))
    tags.extend(_string_list(profile.get("tags")))
    tags.extend(["generated", "assembly_anchor", f"generator:{generator_name}", f"assembly:{mode}", f"assembly_family:{family_kind}"])
    values["semantic_tags"] = _dedupe(tags)
    return {
        "node_type": "scene_object",
        "name": anchor_name,
        "role": profile.get("role") or "environment_structure",
        "from": anchor_asset,
        "values": values,
    }


def _merge_anchor_payload(values: dict[str, Any], payload: Mapping[str, Any]) -> None:
    for key, value in payload.items():
        if key == "state" and isinstance(value, Mapping):
            state = _state(values.get("state"))
            state.update(_state(value))
            values["state"] = state
        elif isinstance(key, str) and _IDENTIFIER_RE.match(key):
            values[key] = deepcopy(value)


def _assembly_anchor_transform(
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
) -> dict[str, list[float]]:
    raw_transform = generator_values.get("assembly_transform") or family_values.get("assembly_transform")
    if isinstance(raw_transform, Mapping):
        return _transform(raw_transform)
    raw_position = (
        generator_values.get("anchor_position")
        or generator_values.get("assembly_position")
        or family_values.get("anchor_position")
        or family_values.get("assembly_position")
    )
    if raw_position is not None:
        return {"position": _vector3(raw_position, [0.0, 0.0, 0.0]), "rotation": [0.0, 0.0, 0.0], "scale": [1.0, 1.0, 1.0]}
    return {}


def _assembly_anchor_sockets(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    mode: str,
    family_kind: str,
    profile: Mapping[str, Any],
    target_ref: str,
    objects: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    target_sockets = _assembly_socket_sequence(generator_values, family_values, profile)
    accepts_default = [_snake_id(item, "item") for item in _string_list(profile.get("accepts"))]
    sockets: list[Mapping[str, Any]] = []
    for index, obj in enumerate(objects):
        target_socket = _assembly_target_socket(index, target_sockets)
        slot_id = f"{mode}_{target_socket}_{index + 1:02d}"
        accepts = _dedupe([*accepts_default, family_kind, *_object_family_accepts(obj)])
        sockets.append(
            {
                "node_type": "scene_socket",
                "name": f"{generator_name}_{slot_id}",
                "type": profile.get("socket_kind") or target_socket,
                "values": {
                    "on": target_ref,
                    "id": slot_id,
                    "kind": target_socket,
                    "socket_type": profile.get("socket_kind") or target_socket,
                    "interface": slot_id,
                    "accepts": accepts,
                    "position": _assembly_slot_position(generator_values, family_values, mode, index, len(objects)),
                    "normal": [0.0, 0.0, 1.0],
                },
            }
        )
    return sockets


def _assembly_anchor_attachments(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    mode: str,
    family_kind: str,
    profile: Mapping[str, Any],
    target_ref: str,
    objects: Sequence[Mapping[str, Any]],
    sockets: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    attach_mode = _snake_id(
        generator_values.get("assembly_attach_mode")
        or generator_values.get("attach_mode")
        or family_values.get("assembly_attach_mode")
        or profile.get("attachment_mode"),
        "snap",
    )
    attachments: list[Mapping[str, Any]] = []
    for index, obj in enumerate(objects):
        object_name = _string(obj.get("name"))
        if not object_name:
            continue
        socket_values = _values(sockets[index]) if index < len(sockets) else {}
        slot_id = _snake_id(socket_values.get("id"), f"assembly_slot_{index + 1:02d}")
        child_socket = _assembly_child_socket(obj, generator_values, family_values, profile)
        values: dict[str, Any] = {
            "from": object_name,
            "to": target_ref,
            "socket": slot_id,
            "target_socket": slot_id,
            "mode": attach_mode,
            "assembly": mode,
            "assembly_family": family_kind,
            "assembly_index": index,
        }
        if child_socket:
            values["child_socket"] = child_socket
        attachments.append(
            {
                "node_type": "scene_attachment",
                "name": f"{generator_name}_{mode}_attach_{index + 1:02d}",
                "type": attach_mode,
                "values": values,
            }
        )
    return attachments


def _assembly_chain_attachments(
    generator_name: str,
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    mode: str,
    family_kind: str,
    objects: Sequence[Mapping[str, Any]],
    profile: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    names = [_string(obj.get("name")) for obj in objects if _string(obj.get("name"))]
    if len(names) < 2:
        return []
    pairs = list(zip(names, names[1:]))
    if mode in {"loop", "ring"}:
        pairs.append((names[-1], names[0]))
    attach_mode = _snake_id(
        generator_values.get("assembly_attach_mode")
        or generator_values.get("attach_mode")
        or family_values.get("assembly_attach_mode")
        or profile.get("attachment_mode"),
        "connect" if family_kind in {"road", "access", "infrastructure"} else "snap",
    )
    socket_name = _snake_id(
        generator_values.get("chain_socket")
        or generator_values.get("assembly_socket")
        or family_values.get("chain_socket")
        or profile.get("chain_socket"),
        _assembly_chain_socket(family_kind),
    )
    attachments: list[Mapping[str, Any]] = []
    for index, (source, target) in enumerate(pairs):
        attachments.append(
            {
                "node_type": "scene_attachment",
                "name": f"{generator_name}_{mode}_chain_{index + 1:02d}",
                "type": attach_mode,
                "values": {
                    "from": source,
                    "to": target,
                    "socket": socket_name,
                    "mode": attach_mode,
                    "assembly": mode,
                    "assembly_family": family_kind,
                    "sequence_index": index,
                },
            }
        )
    return attachments


def _mark_generator_assembly_objects(
    objects: Sequence[Mapping[str, Any]],
    generator_name: str,
    mode: str,
    family_kind: str,
) -> None:
    for index, obj in enumerate(objects):
        values = obj.get("values")
        if not isinstance(values, dict):
            continue
        state = _state(values.get("state"))
        state.update(
            {
                "assembly_mode": mode,
                "assembly_family": family_kind,
                "assembly_group": generator_name,
                "assembly_index": index,
                "generated_assembly_member": True,
            }
        )
        values["state"] = state
        tags = _string_list(values.get("semantic_tags") or values.get("tags"))
        tags.extend([f"assembly:{mode}", f"assembly_family:{family_kind}", f"assembly_group:{generator_name}"])
        values["semantic_tags"] = _dedupe(tags)


def _assembly_socket_sequence(
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    profile: Mapping[str, Any],
) -> list[str]:
    for source in (generator_values, family_values):
        for key in ("assembly_sockets", "socket_sequence", "target_sockets", "assembly_socket", "target_socket", "socket"):
            sockets = [_snake_id(item, "socket") for item in _string_list(source.get(key))]
            if sockets:
                return _dedupe(sockets)
    sockets = [_snake_id(item, "socket") for item in _string_list(profile.get("target_sockets"))]
    return _dedupe(sockets) or ["socket"]


def _assembly_target_socket(index: int, target_sockets: Sequence[str]) -> str:
    if not target_sockets:
        return "socket"
    return target_sockets[index % len(target_sockets)]


def _assembly_child_socket(
    obj: Mapping[str, Any],
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    profile: Mapping[str, Any],
) -> str:
    for source in (generator_values, family_values):
        child_socket = _snake_id(source.get("child_socket"), "")
        if child_socket:
            return child_socket
    available = _object_socket_tokens(obj)
    for socket in [_snake_id(item, "socket") for item in _string_list(profile.get("child_sockets"))]:
        if socket in available:
            return socket
    return sorted(available)[0] if available else ""


def _assembly_slot_position(
    generator_values: Mapping[str, Any],
    family_values: Mapping[str, Any],
    mode: str,
    index: int,
    count: int,
) -> list[float]:
    spacing = _number(generator_values.get("assembly_spacing") or family_values.get("assembly_spacing"), default=2.4)
    columns = _positive_int(generator_values.get("assembly_columns") or family_values.get("assembly_columns"), default=0)
    if not columns:
        columns = max(1, math.ceil(count**0.5))
    rows = _positive_int(generator_values.get("assembly_rows") or family_values.get("assembly_rows"), default=0)
    if not rows:
        rows = max(1, math.ceil(count / columns))
    col = index % columns
    row = index // columns
    x = (col - (columns - 1) * 0.5) * spacing
    y = (row - (rows - 1) * 0.5) * spacing
    z = 0.0
    if mode == "rack":
        y = 0.0
        z = (row - (rows - 1) * 0.5) * max(0.4, spacing * 0.35)
    if mode == "docking_bay":
        x = (col - (columns - 1) * 0.5) * max(spacing, 3.2)
    return [round(x, 6), round(y, 6), round(z, 6)]


def _assembly_chain_socket(family_kind: str) -> str:
    return {
        "road": "road_end",
        "access": "walkway_end",
        "infrastructure": "pipe_end",
        "boat": "mooring",
        "vehicle": "convoy_link",
        "machine": "conveyor_end",
        "building": "entry_door",
        "interior": "entry",
    }.get(family_kind, "assembly_link")


def _object_family_accepts(obj: Mapping[str, Any]) -> list[str]:
    accepts: list[str] = []
    for token in _object_tokens(obj):
        key = _auto_variant_pool_key(token)
        if key:
            accepts.append(key)
    return _dedupe(accepts)


def _object_tokens(obj: Mapping[str, Any]) -> set[str]:
    values = _values(obj)
    state = values.get("state") if isinstance(values.get("state"), Mapping) else {}
    tokens: set[str] = set()
    for value in (obj.get("name"), obj.get("role"), obj.get("from")):
        text = _snake_id(value, "")
        if text:
            tokens.add(text)
            tokens.update(part for part in text.split("_") if part)
    for source in (values, state if isinstance(state, Mapping) else {}):
        for key in (
            "kind",
            "type",
            "source_family",
            "source_kit",
            "lathe_asset",
            "asset",
            "variant",
            "variant_family",
            "archetype",
            "object_archetype",
            "loadout",
            "family_loadout",
            "vehicle_loadout",
            "boat_loadout",
            "vessel_loadout",
            "weapon_loadout",
            "tool_loadout",
            "style_pack",
            "visual_system",
            "compatibility",
            "semantic_tags",
            "tags",
        ):
            for item in _string_list(source.get(key)):
                text = _snake_id(item, "")
                if text:
                    tokens.add(text)
                    tokens.update(part for part in text.split("_") if part)
    return {token for token in tokens if token}


def _object_socket_tokens(obj: Mapping[str, Any]) -> set[str]:
    values = _values(obj)
    state = values.get("state") if isinstance(values.get("state"), Mapping) else {}
    sockets: set[str] = set()
    for source in (values, state if isinstance(state, Mapping) else {}):
        for key in ("sockets", "module_sockets", "composition_sockets", "anchors", "module_anchors", "composition_anchors"):
            sockets.update(_snake_id(item, "socket") for item in _string_list(source.get(key)))
    return {socket for socket in sockets if socket}


def _auto_generator_attachments(
    generator_name: str,
    generator_values: Mapping[str, Any],
    objects: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    mode = _snake_id(generator_values.get("attach") or generator_values.get("connect") or generator_values.get("connection"), "")
    if mode not in {"chain", "loop", "ring", "sequence"}:
        return []
    names = [_string(obj.get("name")) for obj in objects if _string(obj.get("name"))]
    if len(names) < 2:
        return []
    pairs = list(zip(names, names[1:]))
    if mode in {"loop", "ring"}:
        pairs.append((names[-1], names[0]))
    attach_mode = _snake_id(generator_values.get("attach_mode") or generator_values.get("mode"), "snap")
    socket_name = _snake_id(generator_values.get("socket") or generator_values.get("target_socket"), "socket")
    attachments: list[Mapping[str, Any]] = []
    for index, (source, target) in enumerate(pairs):
        attachments.append(
            {
                "node_type": "scene_attachment",
                "name": f"{generator_name}_auto_attach_{index + 1:02d}",
                "type": attach_mode,
                "values": {"from": source, "to": target, "socket": socket_name, "mode": attach_mode},
            }
        )
    return attachments


def _number_list(value: Any) -> list[int]:
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        return [_positive_int(item, default=1) for item in value]
    if isinstance(value, int | float) and not isinstance(value, bool):
        return [_positive_int(value, default=1)]
    return []


def _expand_array_node(array: Mapping[str, Any]) -> list[dict[str, Any]]:
    values = deepcopy(_values(array))
    count = max(1, min(512, _positive_int(values.get("count") or _nested(values, "repeat", "count"), default=1)))
    axis = _string(values.get("axis") or _nested(values, "repeat", "axis"), default="x").lower()
    spacing = float(_number(values.get("spacing") or _nested(values, "repeat", "spacing"), default=2.0))
    start = _vector3(values.get("start") or values.get("origin") or _nested(values, "transform", "position"), [0.0, 0.0, 0.0])
    axis_index = {"x": 0, "y": 1, "z": 2}.get(axis, 0)
    out: list[dict[str, Any]] = []
    for index in range(count):
        item_values = deepcopy(values)
        item_values.pop("count", None)
        item_values.pop("spacing", None)
        item_values.pop("axis", None)
        item_values.pop("start", None)
        position = list(start)
        position[axis_index] = float(position[axis_index]) + spacing * index
        transform = dict(item_values.get("transform", {})) if isinstance(item_values.get("transform"), Mapping) else {}
        transform["position"] = position
        item_values["transform"] = transform
        state = dict(item_values.get("state", {})) if isinstance(item_values.get("state"), Mapping) else {}
        state["array_index"] = index
        state["array_count"] = count
        item_values["state"] = state
        tags = _string_list(item_values.get("semantic_tags") or item_values.get("tags"))
        tags.extend([f"array:{array.get('name')}", "instanced"])
        item_values["semantic_tags"] = _dedupe(tags)
        out.append(
            {
                "node_type": "scene_object",
                "name": f"{array.get('name')}_{index + 1:02d}",
                "role": array.get("role", ""),
                "from": array.get("from", ""),
                "values": item_values,
            }
        )
    return out


