def _expand_presentation_rig_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "presentation_rig")
    center = _macro_center(values)
    shot_count = max(1, min(16, _positive_int(values.get("shots") or values.get("shot_count"), default=3)))
    core_name = f"{name}_presentation_rig_core"
    core_values = _macro_child_values(
        values,
        construct="presentation_rig",
        position=center,
        scale=[max(1.0, _number(values.get("width"), default=2.2)), max(0.8, _number(values.get("depth"), default=1.6)), 0.20],
        state={
            "presentation_rig": name,
            "presentation_rig_count": 1,
            "shot_count": shot_count,
            "camera_count": shot_count + 1,
            "orbit_camera_count": 1,
            "inspection_camera_count": 1,
            "composition_guide_count": 1,
            "object_archetype": "presentation_rig",
            "setpiece_layout": "cinematic_rig",
        },
        tags=["presentation_rig", "camera", "cinematic", "macro_generated"],
    )
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, "presentation_rig", core_values, role="environment_structure", source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    sequence_values = deepcopy(values)
    sequence_values["position"] = [center[0], center[1] + 0.9, center[2] + 0.04]
    sequence_values["shots"] = [f"shot_{index + 1}" for index in range(shot_count)]
    sequence_node = {"node_type": "scene_object", "name": f"{name}_sequence", "role": "environment_structure", "from": node.get("from"), "values": sequence_values}
    sequence_objects, sequence_relationships = _expand_shot_sequence_macro(sequence_node)
    objects.extend(sequence_objects)
    relationships.extend(sequence_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_sequence_shot_sequence_core", "contains", f"Presentation rig {name} contains a shot sequence."))
    orbit_values = deepcopy(values)
    orbit_values["position"] = [center[0] - 0.9, center[1] - 0.8, center[2] + 0.04]
    orbit_node = {"node_type": "scene_object", "name": f"{name}_orbit", "role": "light_fixture", "from": node.get("from"), "values": orbit_values}
    orbit_objects, orbit_relationships = _expand_camera_mode_macro(orbit_node, construct="orbit_camera")
    objects.extend(orbit_objects)
    relationships.extend(orbit_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_orbit_orbit_camera_core", "supports", f"Presentation rig {name} adds orbit camera."))
    guide_values = deepcopy(values)
    guide_values["position"] = [center[0] + 0.9, center[1] - 0.8, center[2] + 0.04]
    guide_node = {"node_type": "scene_object", "name": f"{name}_composition", "role": "narrative_clue", "from": node.get("from"), "values": guide_values}
    guide_objects, guide_relationships = _expand_composition_guide_macro(guide_node)
    objects.extend(guide_objects)
    relationships.extend(guide_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_composition_composition_guide_core", "supports", f"Presentation rig {name} adds composition guide."))
    return objects, relationships


_AUDIO_CORE_SUFFIXES = {
    "ambient_bed": "ambient_core",
    "sound_zone": "sound_zone_core",
    "reverb_space": "reverb_core",
    "acoustic_occluder": "occluder_core",
    "sound_propagation": "propagation_core",
    "music_state": "music_state_core",
    "music_transition": "music_transition_core",
    "stinger": "stinger_core",
    "foley_emitter": "foley_core",
    "audio_bus": "audio_bus_core",
    "listener_zone": "listener_core",
    "acoustic_material": "acoustic_material_core",
}

_AUDIO_MACRO_ROLES = {
    "ambient_bed": "environment_structure",
    "sound_zone": "environment_structure",
    "reverb_space": "environment_structure",
    "acoustic_occluder": "architecture",
    "sound_propagation": "environment_structure",
    "music_state": "narrative_clue",
    "music_transition": "narrative_clue",
    "stinger": "narrative_clue",
    "foley_emitter": "narrative_clue",
    "audio_bus": "environment_structure",
    "listener_zone": "environment_structure",
    "acoustic_material": "dressing_prop",
}

_AUDIO_KIND_KEYS = {
    "ambient_bed": ("ambient_type", "ambience", "soundscape", "type"),
    "sound_zone": ("sound_type", "zone_type", "type"),
    "reverb_space": ("reverb_type", "room_type", "type"),
    "acoustic_occluder": ("occluder_type", "material", "type"),
    "sound_propagation": ("propagation_type", "model", "type"),
    "music_state": ("music_layer", "music_type", "state", "type"),
    "music_transition": ("transition_type", "type"),
    "stinger": ("stinger_type", "cue", "type"),
    "foley_emitter": ("foley_type", "event", "type"),
    "audio_bus": ("bus", "bus_name", "mix", "type"),
    "listener_zone": ("listener_mode", "mode", "type"),
    "acoustic_material": ("acoustic_profile", "material", "type"),
}

_AUDIO_KIND_DEFAULTS = {
    "ambient_bed": "ambience",
    "sound_zone": "sound_zone",
    "reverb_space": "room_reverb",
    "acoustic_occluder": "occluder",
    "sound_propagation": "raycast",
    "music_state": "music",
    "music_transition": "crossfade",
    "stinger": "stinger",
    "foley_emitter": "foley",
    "audio_bus": "world",
    "listener_zone": "default_listener",
    "acoustic_material": "neutral",
}


def _audio_kind(values: Mapping[str, Any], construct: str) -> str:
    return _surface_marker_value(values, *_AUDIO_KIND_KEYS.get(construct, ("type",)), fallback=_AUDIO_KIND_DEFAULTS.get(construct, construct))


def _audio_core_name(name: str, construct: str) -> str:
    return f"{name}_{_AUDIO_CORE_SUFFIXES.get(construct, 'audio_core')}"


def _audio_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    radius = max(0.1, _number(values.get("radius") or values.get("audible_radius"), default=1.0))
    if construct == "ambient_bed":
        return [max(1.0, _number(values.get("width") or values.get("radius"), default=3.0)), max(1.0, _number(values.get("depth") or values.get("radius"), default=2.5)), 0.10]
    if construct in {"sound_zone", "listener_zone"}:
        return [max(0.35, radius), max(0.35, radius), max(0.08, _number(values.get("height"), default=0.16))]
    if construct == "reverb_space":
        return [max(0.6, _number(values.get("width") or values.get("room_size"), default=2.0)), max(0.6, _number(values.get("depth") or values.get("room_size"), default=1.6)), max(0.2, _number(values.get("height"), default=0.8))]
    if construct == "acoustic_occluder":
        return [max(0.3, _number(values.get("width"), default=1.6)), max(0.04, _number(values.get("depth"), default=0.08)), max(0.25, _number(values.get("height"), default=0.9))]
    if construct == "sound_propagation":
        return [max(1.0, _number(values.get("width") or values.get("max_distance"), default=3.0)), 0.08, 0.08]
    if construct in {"music_state", "music_transition", "stinger"}:
        return [0.45, 0.28, 0.10]
    if construct == "foley_emitter":
        return [0.30, 0.30, 0.12]
    if construct == "audio_bus":
        return [0.75, 0.24, 0.12]
    if construct == "acoustic_material":
        return [0.36, 0.20, 0.08]
    return [0.5, 0.5, 0.12]


def _audio_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    state: dict[str, Any] = {
        construct: name,
        "audio_construct": construct,
        "audio_kind": kind,
        f"{construct}_count": 1,
        "audio_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "audio_acoustic_system",
    }
    if construct in {"ambient_bed", "sound_zone", "stinger", "foley_emitter", "sound_propagation"}:
        state["sound_count"] = 1
    if construct == "ambient_bed":
        layers = _gameplay_name_list(values, ("layers", "ambient_layers", "beds"), default=[kind])
        state.update(
            {
                "ambient_type": kind,
                "layers": layers,
                "loop": not _disabled(values.get("loop", True)),
                "volume": _number(values.get("volume"), default=0.75),
                "radius": _number(values.get("radius"), default=14.0),
                "bus": _surface_marker_value(values, "bus", fallback="ambience"),
            }
        )
    elif construct == "sound_zone":
        state.update(
            {
                "sound_type": kind,
                "radius": _number(values.get("radius") or values.get("audible_radius"), default=8.0),
                "attenuation": _surface_marker_value(values, "attenuation", "falloff", fallback="inverse"),
                "volume": _number(values.get("volume"), default=1.0),
                "occlusion": _number(values.get("occlusion"), default=0.0),
                "priority": _number(values.get("priority"), default=1.0),
                "bus": _surface_marker_value(values, "bus", fallback="world"),
            }
        )
    elif construct == "reverb_space":
        state.update(
            {
                "reverb_type": kind,
                "reverb_time": _number(values.get("reverb_time") or values.get("decay"), default=1.2),
                "damping": _number(values.get("damping"), default=0.35),
                "wet_level": _number(values.get("wet_level") or values.get("wet"), default=0.5),
                "room_size": _number(values.get("room_size"), default=1.0),
                "absorption": _number(values.get("absorption"), default=0.25),
            }
        )
    elif construct == "acoustic_occluder":
        state.update(
            {
                "occluder_type": kind,
                "material": _surface_marker_value(values, "material", fallback=kind),
                "acoustic_profile": _surface_marker_value(values, "acoustic_profile", "profile", fallback=kind),
                "occlusion": _number(values.get("occlusion"), default=0.65),
                "transmission": _number(values.get("transmission"), default=0.18),
                "absorption": _number(values.get("absorption"), default=0.35),
            }
        )
    elif construct == "sound_propagation":
        state.update(
            {
                "propagation_type": kind,
                "max_distance": _number(values.get("max_distance") or values.get("radius"), default=30.0),
                "ray_count": max(1, min(128, _positive_int(values.get("ray_count") or values.get("rays"), default=8))),
                "attenuation": _surface_marker_value(values, "attenuation", "falloff", fallback="linear"),
                "occlusion": _number(values.get("occlusion"), default=0.25),
            }
        )
    elif construct == "music_state":
        state.update(
            {
                "music_layer": _surface_marker_value(values, "music_layer", "layer", fallback=kind),
                "intensity": _number(values.get("intensity"), default=0.5),
                "tempo": _number(values.get("tempo") or values.get("bpm"), default=100.0),
                "mood": _surface_marker_value(values, "mood", fallback="neutral"),
                "key": _string(values.get("key"), default=""),
                "loop": not _disabled(values.get("loop", True)),
                "bus": _surface_marker_value(values, "bus", fallback="music"),
            }
        )
    elif construct == "music_transition":
        state.update(
            {
                "transition_type": kind,
                "from_state": _snake_id(values.get("from_state") or values.get("from") or "previous", "previous"),
                "to_state": _snake_id(values.get("to_state") or values.get("to") or "next", "next"),
                "fade": _number(values.get("fade") or values.get("duration"), default=1.0),
                "trigger": _surface_marker_value(values, "trigger", fallback="state_change"),
                "stinger": _surface_marker_value(values, "stinger", fallback=""),
            }
        )
    elif construct == "stinger":
        state.update(
            {
                "stinger_type": kind,
                "trigger": _surface_marker_value(values, "trigger", fallback="event"),
                "volume": _number(values.get("volume"), default=1.0),
                "cooldown": _number(values.get("cooldown"), default=0.0),
                "bus": _surface_marker_value(values, "bus", fallback="music"),
            }
        )
    elif construct == "foley_emitter":
        state.update(
            {
                "foley_type": kind,
                "event": _surface_marker_value(values, "event", fallback=kind),
                "material": _surface_marker_value(values, "material", fallback="default"),
                "rate": _number(values.get("rate"), default=1.0),
                "randomization": _number(values.get("randomization"), default=0.2),
                "bus": _surface_marker_value(values, "bus", fallback="foley"),
            }
        )
    elif construct == "audio_bus":
        state.update(
            {
                "bus": _surface_marker_value(values, "bus", "bus_name", fallback=kind),
                "volume": _number(values.get("volume"), default=1.0),
                "ducking": _number(values.get("ducking"), default=0.0),
                "sends": _gameplay_name_list(values, ("sends", "send_buses"), default=[]),
                "listeners": _gameplay_name_list(values, ("listeners", "listener_zones"), default=[]),
            }
        )
    elif construct == "listener_zone":
        state.update(
            {
                "listener_mode": kind,
                "priority": _number(values.get("priority"), default=1.0),
                "radius": _number(values.get("radius") or values.get("blend_radius"), default=4.0),
                "blend_radius": _number(values.get("blend_radius") or values.get("radius"), default=2.0),
                "reverb_send": _number(values.get("reverb_send"), default=0.0),
            }
        )
    elif construct == "acoustic_material":
        state.update(
            {
                "material": _surface_marker_value(values, "material", fallback=kind),
                "acoustic_profile": _surface_marker_value(values, "acoustic_profile", "profile", fallback=kind),
                "absorption": _number(values.get("absorption"), default=0.3),
                "reflection": _number(values.get("reflection"), default=0.45),
                "transmission": _number(values.get("transmission"), default=0.15),
                "roughness": _number(values.get("roughness"), default=0.5),
            }
        )
    return state


def _expand_audio_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _audio_kind(values, construct)
    role = _AUDIO_MACRO_ROLES.get(construct, "environment_structure")
    core_name = _audio_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_audio_scale(values, construct),
        state=_audio_state(values, construct, name, kind),
        tags=[construct, kind, "audio", "acoustic", "macro_generated"],
    )
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=role, source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    if construct == "ambient_bed" and not _any_disabled(values, "sound_zones", "zones"):
        layers = _gameplay_name_list(values, ("layers", "ambient_layers", "beds"), default=[kind])
        for index, layer in enumerate(layers[:8]):
            layer_values = deepcopy(values)
            layer_values["sound_type"] = layer
            layer_values["radius"] = _number(values.get("radius"), default=14.0) * (0.8 + index * 0.08)
            layer_values["volume"] = _number(values.get("volume"), default=0.75) / max(1.0, len(layers) ** 0.5)
            layer_values["position"] = [center[0] + (index - (len(layers) - 1) / 2.0) * 0.42, center[1], center[2] + 0.08]
            layer_values["listener_zone"] = False
            layer_node = {"node_type": "scene_object", "name": f"{name}_{layer}_zone", "role": "environment_structure", "from": node.get("from"), "values": layer_values}
            layer_objects, layer_relationships = _expand_audio_macro(layer_node, construct="sound_zone")
            objects.extend(layer_objects)
            relationships.extend(layer_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{layer}_zone_sound_zone_core", "contains", f"Ambient bed {name} layers sound zone {layer}."))
    elif construct == "sound_zone" and not _any_disabled(values, "listener_zone", "listener"):
        listener_values = deepcopy(values)
        listener_values["listener_mode"] = _surface_marker_value(values, "listener_mode", fallback="zone_blend")
        listener_values["position"] = [center[0], center[1], center[2] + 0.05]
        listener_values["radius"] = max(0.5, _number(values.get("radius"), default=8.0) * 0.55)
        listener_node = {"node_type": "scene_object", "name": f"{name}_listener", "role": "environment_structure", "from": node.get("from"), "values": listener_values}
        listener_objects, listener_relationships = _expand_audio_macro(listener_node, construct="listener_zone")
        objects.extend(listener_objects)
        relationships.extend(listener_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_listener_listener_core", "supports", f"Sound zone {name} defines listener blend behavior."))
    elif construct == "reverb_space" and not _any_disabled(values, "acoustic_material", "material_response"):
        material_values = deepcopy(values)
        material_values["position"] = [center[0], center[1], center[2] + 0.09]
        material_values["acoustic_profile"] = _surface_marker_value(values, "acoustic_profile", "material", fallback=kind)
        material_node = {"node_type": "scene_object", "name": f"{name}_material", "role": "dressing_prop", "from": node.get("from"), "values": material_values}
        material_objects, material_relationships = _expand_audio_macro(material_node, construct="acoustic_material")
        objects.extend(material_objects)
        relationships.extend(material_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_material_acoustic_material_core", "supports", f"Reverb space {name} uses acoustic material response."))
    elif construct == "sound_propagation" and not _any_disabled(values, "probes", "sample_points"):
        probe_count = max(1, min(16, _positive_int(values.get("probe_count") or values.get("sample_points") or values.get("ray_count"), default=4)))
        max_distance = _number(values.get("max_distance") or values.get("radius"), default=30.0)
        for index in range(probe_count):
            offset = (index - (probe_count - 1) / 2.0) * max(0.25, min(1.5, max_distance / max(8.0, probe_count * 2.0)))
            probe_name = f"{name}_probe_{index + 1:02d}"
            probe_values = _macro_child_values(
                values,
                construct="listener_zone",
                position=[center[0] + offset, center[1], center[2] + 0.04],
                scale=[0.18, 0.18, 0.08],
                state={"sound_propagation": name, "probe_index": index + 1, "listener_zone_count": 1, "max_distance": max_distance},
                tags=["sound_probe", "propagation", "audio", "macro_generated"],
            )
            objects.append(_macro_scene_object(probe_name, "listener_zone", probe_values, role="environment_structure", source=node.get("from")))
            relationships.append(_macro_relationship(name, core_name, probe_name, "supports", f"Sound propagation {name} samples probe {index + 1}."))
    elif construct == "music_transition" and not _any_disabled(values, "music_states", "state_nodes"):
        from_state = _snake_id(values.get("from_state") or values.get("from") or "previous", "previous")
        to_state = _snake_id(values.get("to_state") or values.get("to") or "next", "next")
        for index, state_name in enumerate((from_state, to_state)):
            state_values = deepcopy(values)
            state_values["music_layer"] = state_name
            state_values["position"] = [center[0] + (-0.35 if index == 0 else 0.35), center[1], center[2] + 0.04]
            state_node = {"node_type": "scene_object", "name": f"{name}_{state_name}", "role": "narrative_clue", "from": node.get("from"), "values": state_values}
            state_objects, state_relationships = _expand_audio_macro(state_node, construct="music_state")
            objects.extend(state_objects)
            relationships.extend(state_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{state_name}_music_state_core", "routes_to", f"Music transition {name} references music state {state_name}."))
    elif construct in {"stinger", "foley_emitter"} and not _any_disabled(values, "sound_cue", "cue"):
        cue_values = deepcopy(values)
        cue_values["sound_type"] = kind
        cue_values["loop"] = False
        cue_values["position"] = [center[0], center[1], center[2] + 0.05]
        cue_node = {"node_type": "scene_object", "name": f"{name}_cue", "role": "narrative_clue", "from": node.get("from"), "values": cue_values}
        cue_objects, cue_relationships = _expand_sound_cue_macro(cue_node)
        objects.extend(cue_objects)
        relationships.extend(cue_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_cue_sound_core", "supports", f"{construct.replace('_', ' ').title()} {name} emits a sound cue."))
    elif construct == "audio_bus" and not _any_disabled(values, "listener_zones", "listeners"):
        listeners = _gameplay_name_list(values, ("listeners", "listener_zones"), default=[])
        for index, listener in enumerate(listeners[:8]):
            listener_values = deepcopy(values)
            listener_values["listener_mode"] = listener
            listener_values["position"] = [center[0] + (index - (len(listeners) - 1) / 2.0) * 0.34, center[1], center[2] + 0.04]
            listener_node = {"node_type": "scene_object", "name": f"{name}_{listener}_listener", "role": "environment_structure", "from": node.get("from"), "values": listener_values}
            listener_objects, listener_relationships = _expand_audio_macro(listener_node, construct="listener_zone")
            objects.extend(listener_objects)
            relationships.extend(listener_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{listener}_listener_listener_core", "supports", f"Audio bus {name} feeds listener zone {listener}."))

    return objects, relationships


