def _interaction_kind(values: Mapping[str, Any], construct: str) -> str:
    return _surface_marker_value(values, *_INTERACTION_KIND_KEYS.get(construct, ("type",)), fallback=_INTERACTION_KIND_DEFAULTS.get(construct, construct))


def _interaction_action(values: Mapping[str, Any], construct: str) -> str:
    return _snake_id(values.get("action") or values.get("interaction") or values.get("interaction_type") or _INTERACTION_DEFAULT_ACTIONS.get(construct), "interact")


def _interaction_core_name(name: str, construct: str) -> str:
    return f"{name}_{_INTERACTION_CORE_SUFFIXES.get(construct, 'interaction_core')}"


def _interaction_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    radius = max(0.1, _number(values.get("radius") or values.get("range"), default=0.8))
    if construct == "interaction_zone":
        return [max(0.6, radius), max(0.6, radius), max(0.12, _number(values.get("height"), default=0.20))]
    if construct == "interaction_prompt":
        return [0.42, 0.08, 0.18]
    if construct in {"terminal", "control_panel", "diegetic_hud"}:
        return [max(0.45, _number(values.get("width"), default=0.9)), max(0.06, _number(values.get("depth"), default=0.12)), max(0.25, _number(values.get("height"), default=0.55))]
    if construct in {"switch", "lever", "button", "door_lock"}:
        return [0.18, 0.10, 0.22]
    if construct == "pickup":
        return [0.26, 0.26, 0.18]
    if construct in {"inspect_point", "quest_marker", "map_marker", "ui_anchor"}:
        return [0.28, 0.08, 0.28]
    if construct == "signage":
        return [max(0.5, _number(values.get("width"), default=1.1)), 0.06, max(0.22, _number(values.get("height"), default=0.38))]
    return [0.34, 0.18, 0.16]


def _interaction_prompt(values: Mapping[str, Any], construct: str, action: str) -> str:
    if values.get("prompt"):
        return _string(values.get("prompt"))
    label = _string(values.get("label"), default="")
    if label:
        return label
    defaults = {
        "pickup": "Pick up",
        "inspect_point": "Inspect",
        "terminal": "Use terminal",
        "control_panel": "Use panel",
        "switch": "Toggle",
        "lever": "Pull",
        "button": "Press",
        "door_lock": "Unlock",
        "quest_marker": "Track objective",
        "signage": "Read",
        "map_marker": "Track marker",
    }
    return defaults.get(construct, action.replace("_", " ").title())


def _interaction_state(values: Mapping[str, Any], construct: str, name: str, kind: str, action: str) -> dict[str, Any]:
    target = _snake_id(values.get("target") or values.get("target_object") or values.get("attached_to"), "")
    state: dict[str, Any] = {
        construct: name,
        "interaction_construct": construct,
        "interaction_kind": kind,
        "interaction_type": action,
        "action": action,
        f"{construct}_count": 1,
        "interaction_count": 1,
        "prompt": _interaction_prompt(values, construct, action),
        "label": _string(values.get("label"), default=name.replace("_", " ").title()),
        "icon": _surface_marker_value(values, "icon", fallback=action),
        "target": target,
        "requires": _string(values.get("requires"), default=""),
        "reveals": _string(values.get("reveals"), default=""),
        "radius": _number(values.get("radius") or values.get("range"), default=2.0),
        "enabled": not _disabled(values.get("enabled", True)),
        "one_shot": not _disabled(values.get("one_shot", False)),
        "priority": _number(values.get("priority"), default=1.0),
        "object_archetype": construct,
        "setpiece_layout": "interaction_ui_system",
    }
    if construct in {"affordance", "usable", "pickup", "terminal", "control_panel", "switch", "lever", "button", "door_lock"}:
        state.update(
            {
                "hold_time": _number(values.get("hold_time"), default=0.0),
                "cooldown_seconds": _number(values.get("cooldown") or values.get("cooldown_seconds"), default=0.0),
                "charges": _positive_int(values.get("charges") or values.get("uses"), default=1),
            }
        )
    if construct == "pickup":
        state.update(
            {
                "item_type": kind,
                "items": _gameplay_name_list(values, ("items", "item", "rewards"), default=[kind]),
                "stack_count": _positive_int(values.get("stack_count") or values.get("count"), default=1),
            }
        )
    elif construct == "inspect_point":
        state.update(
            {
                "inspect_type": kind,
                "display_text": _string(values.get("display_text") or values.get("text") or values.get("description"), default=""),
                "reveals": _string(values.get("reveals") or values.get("lore"), default=""),
            }
        )
    elif construct in {"terminal", "control_panel"}:
        state.update(
            {
                "panel_mode": kind,
                "channel": _surface_marker_value(values, "channel", "bus", fallback="world"),
                "screen_count": max(1, min(12, _positive_int(values.get("screens") or values.get("screen_count"), default=1))),
                "control_count": max(0, min(24, _positive_int(values.get("controls") or values.get("control_count") or values.get("buttons"), default=3 if construct == "control_panel" else 1))),
            }
        )
    elif construct in {"switch", "lever", "button"}:
        state.update(
            {
                "control_type": kind,
                "channel": _surface_marker_value(values, "channel", "bus", fallback="world"),
                "value": _string(values.get("value"), default="on"),
                "toggles": _gameplay_name_list(values, ("toggles", "targets", "target"), default=[]),
            }
        )
    elif construct == "door_lock":
        state.update(
            {
                "lock_type": kind,
                "locked": not _disabled(values.get("locked", True)),
                "key_item": _surface_marker_value(values, "key_item", "key", "requires", fallback="key"),
                "fail_prompt": _string(values.get("fail_prompt"), default="Locked"),
            }
        )
    elif construct == "quest_marker":
        state.update(
            {
                "quest": _snake_id(values.get("quest") or values.get("quest_id"), name),
                "objective": _snake_id(values.get("objective") or values.get("objective_id"), kind),
                "marker_type": kind,
                "visibility": _surface_marker_value(values, "visibility", fallback="when_tracked"),
            }
        )
    elif construct == "signage":
        state.update(
            {
                "signage_count": 1,
                "display_text": _string(values.get("display_text") or values.get("text"), default=name.replace("_", " ").title()),
                "marker_type": kind,
                "visibility": _surface_marker_value(values, "visibility", fallback="always"),
            }
        )
    elif construct == "map_marker":
        state.update(
            {
                "marker_type": kind,
                "objective": _snake_id(values.get("objective") or values.get("target") or name, name),
                "visibility": _surface_marker_value(values, "visibility", fallback="map"),
                "route_hint": _surface_marker_value(values, "route_hint", "hint", fallback="direct"),
            }
        )
    elif construct in {"diegetic_hud", "ui_anchor", "interaction_prompt"}:
        state.update(
            {
                "display_text": _string(values.get("display_text") or values.get("text"), default=state["prompt"]),
                "screen_space": not _disabled(values.get("screen_space", construct == "diegetic_hud")),
                "world_space": not _disabled(values.get("world_space", True)),
                "visibility": _surface_marker_value(values, "visibility", fallback="contextual"),
            }
        )
    return state


def _interaction_affordance(values: Mapping[str, Any], action: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": action}
    if values.get("requires"):
        affordance["requires"] = _string(values.get("requires"))
    if values.get("reveals"):
        affordance["reveals"] = _string(values.get("reveals"))
    return affordance


def _expand_interaction_ui_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _interaction_kind(values, construct)
    action = _interaction_action(values, construct)
    role = _INTERACTION_MACRO_ROLES.get(construct, "interactive")
    core_name = _interaction_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_interaction_scale(values, construct),
        state=_interaction_state(values, construct, name, kind, action),
        tags=[construct, kind, "interaction", "diegetic_ui", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(values.get("affordance") or action, "interact"): _interaction_affordance(values, action)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=role, source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    if construct in {"interaction_zone", "affordance", "usable", "pickup", "terminal", "control_panel", "switch", "lever", "button", "door_lock"} and not _any_disabled(values, "prompt", "interaction_prompt"):
        prompt_values = deepcopy(values)
        prompt_values["position"] = [center[0], center[1], center[2] + 0.28]
        prompt_values["target"] = core_name
        prompt_values["action"] = "show_prompt"
        prompt_node = {"node_type": "scene_object", "name": f"{name}_prompt", "role": "narrative_clue", "from": node.get("from"), "values": prompt_values}
        prompt_objects, prompt_relationships = _expand_interaction_ui_macro(prompt_node, construct="interaction_prompt")
        objects.extend(prompt_objects)
        relationships.extend(prompt_relationships)
        relationships.append(_macro_relationship(name, f"{name}_prompt_prompt_core", core_name, "reveals", f"Prompt for interaction {name} reveals usable target."))

    if construct in {"terminal", "control_panel"} and not _any_disabled(values, "controls", "buttons"):
        controls = _gameplay_name_list(values, ("controls", "buttons", "actions"), default=["activate", "cycle", "reset"] if construct == "control_panel" else ["open"])
        for index, control in enumerate(controls[:12]):
            control_construct = "button" if index % 3 != 1 else "switch"
            control_values = deepcopy(values)
            control_values["position"] = [center[0] + (index - (len(controls) - 1) / 2.0) * 0.24, center[1] - 0.12, center[2] + 0.04]
            control_values["action"] = _snake_id(control, "control")
            control_values["label"] = control.replace("_", " ").title()
            control_values["target"] = core_name
            control_values["prompt"] = f"{control_values['label']}"
            control_node = {"node_type": "scene_object", "name": f"{name}_{control}", "role": "interactive", "from": node.get("from"), "values": control_values}
            control_objects, control_relationships = _expand_interaction_ui_macro(control_node, construct=control_construct)
            objects.extend(control_objects)
            relationships.extend(control_relationships)
            relationships.append(_macro_relationship(name, core_name, _interaction_core_name(f"{name}_{control}", control_construct), "contains", f"{construct.replace('_', ' ').title()} {name} contains control {control}."))

    if construct == "door_lock" and not _any_disabled(values, "lock_control", "control"):
        control_values = deepcopy(values)
        control_values["position"] = [center[0] + 0.28, center[1], center[2] + 0.02]
        control_values["action"] = "unlock"
        control_values["target"] = core_name
        control_values["prompt"] = _string(values.get("prompt"), default="Unlock")
        control_node = {"node_type": "scene_object", "name": f"{name}_unlock_button", "role": "interactive", "from": node.get("from"), "values": control_values}
        control_objects, control_relationships = _expand_interaction_ui_macro(control_node, construct="button")
        objects.extend(control_objects)
        relationships.extend(control_relationships)
        relationships.append(_macro_relationship(name, _interaction_core_name(f"{name}_unlock_button", "button"), core_name, "opens_to", f"Door lock {name} opens through its generated control."))

    if construct == "pickup" and not _any_disabled(values, "inspect", "inspect_point"):
        inspect_values = deepcopy(values)
        inspect_values["position"] = [center[0], center[1] + 0.26, center[2] + 0.08]
        inspect_values["target"] = core_name
        inspect_values["prompt"] = _string(values.get("inspect_prompt"), default="Inspect")
        inspect_node = {"node_type": "scene_object", "name": f"{name}_inspect", "role": "narrative_clue", "from": node.get("from"), "values": inspect_values}
        inspect_objects, inspect_relationships = _expand_interaction_ui_macro(inspect_node, construct="inspect_point")
        objects.extend(inspect_objects)
        relationships.extend(inspect_relationships)
        relationships.append(_macro_relationship(name, f"{name}_inspect_inspect_core", core_name, "reveals", f"Pickup {name} has an inspection point."))

    if construct == "quest_marker" and not _any_disabled(values, "map_marker", "map"):
        marker_values = deepcopy(values)
        marker_values["position"] = [center[0], center[1] + 0.36, center[2] + 0.04]
        marker_values["target"] = core_name
        marker_node = {"node_type": "scene_object", "name": f"{name}_map", "role": "navigation", "from": node.get("from"), "values": marker_values}
        marker_objects, marker_relationships = _expand_interaction_ui_macro(marker_node, construct="map_marker")
        objects.extend(marker_objects)
        relationships.extend(marker_relationships)
        relationships.append(_macro_relationship(name, f"{name}_map_map_marker_core", core_name, "routes_to", f"Quest marker {name} routes to its world objective."))

    if construct in {"quest_marker", "map_marker", "signage", "inspect_point"} and not _any_disabled(values, "ui_anchor", "hud"):
        anchor_values = deepcopy(values)
        anchor_values["position"] = [center[0], center[1], center[2] + 0.22]
        anchor_values["target"] = core_name
        anchor_values["prompt"] = _interaction_prompt(values, construct, action)
        anchor_node = {"node_type": "scene_object", "name": f"{name}_ui", "role": "narrative_clue", "from": node.get("from"), "values": anchor_values}
        anchor_objects, anchor_relationships = _expand_interaction_ui_macro(anchor_node, construct="ui_anchor")
        objects.extend(anchor_objects)
        relationships.extend(anchor_relationships)
        relationships.append(_macro_relationship(name, f"{name}_ui_ui_anchor_core", core_name, "framed_by", f"{construct.replace('_', ' ').title()} {name} has a diegetic UI anchor."))

    if construct == "diegetic_hud" and not _any_disabled(values, "anchors", "ui_anchors"):
        anchors = _gameplay_name_list(values, ("anchors", "ui_anchors", "widgets"), default=["health", "objective", "status"])
        for index, anchor in enumerate(anchors[:16]):
            anchor_values = deepcopy(values)
            anchor_values["position"] = [center[0] + (index - (len(anchors) - 1) / 2.0) * 0.32, center[1], center[2] + 0.08]
            anchor_values["anchor_type"] = anchor
            anchor_values["label"] = anchor.replace("_", " ").title()
            anchor_values["target"] = core_name
            anchor_node = {"node_type": "scene_object", "name": f"{name}_{anchor}", "role": "narrative_clue", "from": node.get("from"), "values": anchor_values}
            anchor_objects, anchor_relationships = _expand_interaction_ui_macro(anchor_node, construct="ui_anchor")
            objects.extend(anchor_objects)
            relationships.extend(anchor_relationships)
            relationships.append(_macro_relationship(name, core_name, _interaction_core_name(f"{name}_{anchor}", "ui_anchor"), "contains", f"Diegetic HUD {name} contains UI anchor {anchor}."))

    return objects, relationships


def _expand_physics_body_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "physics_body")
    center = _macro_center(values)
    body_kind = _snake_id(values.get("body_type") or values.get("physics_type") or values.get("type"), "dynamic")
    collider_count = max(1, min(16, _positive_int(values.get("colliders") or values.get("collider_count"), default=1)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_physics_body_core"
    core_values = _macro_child_values(
        values,
        construct="physics_body",
        position=center,
        scale=[
            max(0.2, _number(values.get("width") or values.get("radius"), default=1.2)),
            max(0.2, _number(values.get("depth") or values.get("radius"), default=1.2)),
            max(0.1, _number(values.get("height"), default=0.6)),
        ],
        state={
            "physics_body": name,
            "body_type": body_kind,
            "mass": _number(values.get("mass"), default=1.0),
            "collision_shape": _snake_id(values.get("collision_shape") or values.get("shape"), "box"),
            "collider_count": collider_count,
            "gravity_scale": _number(values.get("gravity") or values.get("gravity_scale"), default=1.0),
            "linear_damping": _number(values.get("damping") or values.get("linear_damping"), default=0.05),
            "friction": _number(values.get("friction"), default=0.5),
            "restitution": _number(values.get("restitution") or values.get("bounce"), default=0.0),
            "collision_layer": _snake_id(values.get("layer") or values.get("collision_layer"), "world"),
            "infrastructure_type": "physics_body",
            "module_socket_count": max(1, collider_count),
            "support_count": collider_count,
        },
        tags=["physics_body", body_kind, "physics", "macro_generated"],
    )
    core_values["affordances"] = {"apply_force": {"action": "apply_force", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "physics_body", core_values, role="interactive", source=node.get("from")))

    for index in range(collider_count):
        collider_name = f"{name}_collider_{index + 1:02d}"
        collider_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (collider_count - 1) / 2.0) * 0.6, center[1] + 0.75, center[2] + 0.04],
            scale=[0.35, 0.35, 0.14],
            state={"physics_body": name, "collider_index": index, "collision_shape": core_values["state"]["collision_shape"], "interaction_type": "physics_contact"},
            tags=["physics_collider", body_kind, "physics", "macro_generated"],
        )
        collider_values["affordances"] = {"contact": {"action": "physics_contact"}}
        objects.append(_macro_scene_object(collider_name, "interactable", collider_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, collider_name, "contains", f"Physics body {name} contains collider {index + 1}."))
    return objects, relationships


def _expand_physics_joint_macro(
    node: Mapping[str, Any],
    *,
    construct: str,
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    joint_kind = "hinge" if construct == "hinge_joint" else _snake_id(values.get("joint_type") or values.get("type"), "fixed")
    bodies = _gameplay_name_list(values, ("bodies", "body_refs", "targets"), default=[])
    if not bodies:
        bodies = [_snake_id(values.get("body_a") or values.get("from_body"), "body_a"), _snake_id(values.get("body_b") or values.get("to_body"), "body_b")]
    anchor_count = max(2, min(8, _positive_int(values.get("anchors") or values.get("anchor_count"), default=len(bodies))))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_{construct}_core"
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=[max(0.25, _number(values.get("width"), default=0.9)), max(0.25, _number(values.get("depth"), default=0.7)), 0.20],
        state={
            construct: name,
            "joint_type": joint_kind,
            "bodies": bodies,
            "body_count": len(bodies),
            "anchor_count": anchor_count,
            "axis": _snake_id(values.get("axis"), "z"),
            "limit_min": _number(values.get("limit_min") or values.get("min"), default=-90.0 if joint_kind == "hinge" else 0.0),
            "limit_max": _number(values.get("limit_max") or values.get("max"), default=90.0 if joint_kind == "hinge" else 0.0),
            "motor_speed": _number(values.get("motor_speed") or values.get("speed"), default=0.0),
            "break_force": _number(values.get("break_force") or values.get("strength"), default=0.0),
            "infrastructure_type": "physics_joint",
            "module_socket_count": anchor_count,
        },
        tags=[construct, joint_kind, "physics", "macro_generated"],
    )
    core_values["affordances"] = {"solve_joint": {"action": "solve_physics_joint"}}
    objects.append(_macro_scene_object(core_name, construct, core_values, role="interactive", source=node.get("from")))

    for index in range(anchor_count):
        anchor_name = f"{name}_anchor_{index + 1:02d}"
        anchor_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (anchor_count - 1) / 2.0) * 0.45, center[1] + 0.65, center[2] + 0.04],
            scale=[0.25, 0.25, 0.10],
            state={"physics_joint": name, "joint_type": joint_kind, "anchor_index": index, "body_ref": bodies[index % len(bodies)], "interaction_type": "joint_anchor"},
            tags=["joint_anchor", joint_kind, "physics", "macro_generated"],
        )
        objects.append(_macro_scene_object(anchor_name, "interactable", anchor_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, anchor_name, "contains", f"Joint {name} contains anchor {index + 1}."))

    if construct == "hinge_joint" and not _any_disabled(values, "moving_part", "motor"):
        part_values = deepcopy(values)
        part_values["position"] = [center[0], center[1] - 0.8, center[2] + 0.04]
        part_values["movement"] = "rotate"
        part_values["axis"] = _snake_id(values.get("axis"), "z")
        part_values["angle"] = core_values["state"]["limit_max"]
        part_node = {"node_type": "scene_object", "name": f"{name}_hinged_part", "role": "interactive", "from": node.get("from"), "values": part_values}
        part_objects, part_relationships = _expand_moving_part_macro(part_node)
        objects.extend(part_objects)
        relationships.extend(part_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_hinged_part_moving_part_core", "supports", f"Hinge joint {name} drives a moving part."))
    return objects, relationships


