def _expand_debris_field_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "debris_field")
    center = _macro_center(values)
    debris_kind = _snake_id(values.get("debris_type") or values.get("material") or values.get("type"), "fragments")
    count = max(1, min(256, _positive_int(values.get("pieces") or values.get("debris_count") or values.get("count"), default=12)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_debris_core"
    core_values = _macro_child_values(
        values,
        construct="debris_field",
        position=center,
        scale=[max(1.0, _number(values.get("width") or values.get("radius"), default=4.0)), max(1.0, _number(values.get("depth") or values.get("radius"), default=3.0)), 0.18],
        state={
            "debris_field": name,
            "debris_type": debris_kind,
            "debris_count": count,
            "spread_radius": _number(values.get("radius") or values.get("spread_radius"), default=3.0),
            "lifetime_seconds": _number(values.get("lifetime") or values.get("lifetime_seconds"), default=0.0),
            "physics_body_count": max(1, min(32, count)),
            "object_archetype": "debris_field",
            "setpiece_layout": "debris_scatter",
            "prop_count": max(1, min(64, count)),
        },
        tags=["debris_field", debris_kind, "destruction", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "debris_field", core_values, role="environment_structure", source=node.get("from")))

    for index in range(min(count, 24)):
        angle = math.tau * index / max(1, min(count, 24))
        shard_name = f"{name}_shard_{index + 1:02d}"
        shard_values = _macro_child_values(
            values,
            construct="physics_body",
            position=[center[0] + math.cos(angle) * 1.4, center[1] + math.sin(angle) * 1.0, center[2] + 0.04],
            scale=[0.22, 0.16, 0.10],
            state={"debris_field": name, "debris_index": index, "body_type": "dynamic", "mass": 0.15, "collision_shape": "fragment"},
            tags=["debris_shard", debris_kind, "physics_body", "macro_generated"],
        )
        objects.append(_macro_scene_object(shard_name, "physics_body", shard_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, shard_name, "contains", f"Debris field {name} contains shard {index + 1}."))
    return objects, relationships


def _expand_breakable_part_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "breakable_part")
    center = _macro_center(values)
    material = _snake_id(values.get("material") or values.get("break_material") or values.get("type"), "generic")
    damage_states = _gameplay_name_list(values, ("damage_states", "states"), default=["intact", "damaged", "destroyed"])
    debris_count = max(0, min(128, _positive_int(values.get("debris") or values.get("debris_count"), default=12)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_breakable_core"
    core_values = _macro_child_values(
        values,
        construct="breakable_part",
        position=center,
        scale=[max(0.5, _number(values.get("width"), default=1.8)), max(0.5, _number(values.get("depth"), default=1.2)), max(0.15, _number(values.get("height"), default=0.45))],
        state={
            "breakable_part": name,
            "break_material": material,
            "health": _number(values.get("health"), default=100.0),
            "break_threshold": _number(values.get("threshold") or values.get("break_threshold"), default=0.0),
            "fracture_pattern": _snake_id(values.get("fracture") or values.get("fracture_pattern"), "chunks"),
            "damage_state_count": len(damage_states),
            "debris_count": debris_count,
            "physics_body_count": 1,
            "object_archetype": "breakable_part",
            "setpiece_layout": "destructible",
            "state_count": len(damage_states),
            "event_count": 1,
        },
        tags=["breakable_part", material, "destruction", "macro_generated"],
    )
    core_values["affordances"] = {"damage": {"action": "apply_damage", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "breakable_part", core_values, role="interactive", source=node.get("from")))

    body_values = deepcopy(values)
    body_values["position"] = [center[0], center[1] + 0.9, center[2] + 0.04]
    body_values["body_type"] = _snake_id(values.get("body_type"), "dynamic")
    body_node = {"node_type": "scene_object", "name": f"{name}_body", "role": "interactive", "from": node.get("from"), "values": body_values}
    body_objects, body_relationships = _expand_physics_body_macro(body_node)
    objects.extend(body_objects)
    relationships.extend(body_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_body_physics_body_core", "contains", f"Breakable part {name} owns a physics body."))

    for index, state in enumerate(damage_states):
        damage_values = deepcopy(values)
        damage_values["position"] = [center[0] + (index - (len(damage_states) - 1) / 2.0) * 0.9, center[1] - 0.9, center[2] + 0.04]
        damage_values["state"] = state
        damage_values["damage_level"] = index / max(1, len(damage_states) - 1)
        damage_node = {"node_type": "scene_object", "name": f"{name}_{state}", "role": "narrative_clue", "from": node.get("from"), "values": damage_values}
        damage_objects, damage_relationships = _expand_damage_state_macro(damage_node)
        objects.extend(damage_objects)
        relationships.extend(damage_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{state}_damage_state_core", "contains", f"Breakable part {name} contains damage state {state}."))

    if debris_count and not _any_disabled(values, "debris", "debris_field"):
        debris_values = deepcopy(values)
        debris_values["position"] = [center[0], center[1] + 1.8, center[2] + 0.04]
        debris_values["debris_count"] = debris_count
        debris_values["debris_type"] = material
        debris_node = {"node_type": "scene_object", "name": f"{name}_debris", "role": "environment_structure", "from": node.get("from"), "values": debris_values}
        debris_objects, debris_relationships = _expand_debris_field_macro(debris_node)
        objects.extend(debris_objects)
        relationships.extend(debris_relationships)
        relationships.append(_macro_relationship(name, f"{name}_debris_debris_core", core_name, "reveals", f"Breakable part {name} reveals debris when destroyed."))

    if not _any_disabled(values, "event", "destruction_event"):
        event_values = deepcopy(values)
        event_values["position"] = [center[0], center[1] - 1.8, center[2] + 0.04]
        event_values["targets"] = []
        event_node = {"node_type": "scene_object", "name": f"{name}_destroyed", "role": "interactive", "from": node.get("from"), "values": event_values}
        event_objects, event_relationships = _expand_destruction_event_macro(event_node)
        objects.extend(event_objects)
        relationships.extend(event_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_destroyed_destruction_event_core", "reveals", f"Breakable part {name} emits destruction event."))
    return objects, relationships


def _expand_rope_or_cable_macro(
    node: Mapping[str, Any],
    *,
    construct: str,
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    segment_count = max(2, min(96, _positive_int(values.get("segments") or values.get("segment_count"), default=8)))
    slack = _number(values.get("slack"), default=0.15 if construct == "rope" else 0.04)
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_{construct}_core"
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=[max(0.5, _number(values.get("length"), default=4.0)), max(0.05, _number(values.get("thickness") or values.get("radius"), default=0.08)), 0.08],
        state={
            construct: name,
            "segment_count": segment_count,
            "slack": slack,
            "tension": _number(values.get("tension"), default=1.0 - min(0.8, slack)),
            "break_force": _number(values.get("break_force") or values.get("strength"), default=100.0),
            "start_anchor": _string(values.get("start") or values.get("from"), default=""),
            "end_anchor": _string(values.get("end") or values.get("to"), default=""),
            "infrastructure_type": construct,
            "cable_count": 1 if construct == "cable" else 0,
            "conduit_count": 1 if construct == "cable" else 0,
            "support_count": max(2, min(12, segment_count)),
        },
        tags=[construct, "flexible", "physics", "macro_generated"],
    )
    core_values["affordances"] = {"tension": {"action": "solve_tension"}}
    objects.append(_macro_scene_object(core_name, construct, core_values, role="navigation" if construct == "rope" else "environment_structure", source=node.get("from")))

    previous = ""
    for index in range(min(segment_count, 24)):
        segment_name = f"{name}_segment_{index + 1:02d}"
        y_offset = math.sin((index / max(1, segment_count - 1)) * math.pi) * -slack
        segment_values = _macro_child_values(
            values,
            construct="physics_body",
            position=[center[0] + (index - (segment_count - 1) / 2.0) * 0.32, center[1] + y_offset, center[2] + 0.03],
            scale=[0.18, 0.06, 0.06],
            state={"rope": name if construct == "rope" else "", "cable": name if construct == "cable" else "", "segment_index": index, "body_type": "dynamic", "mass": 0.05, "collision_shape": "capsule"},
            tags=[f"{construct}_segment", "physics_body", "flexible", "macro_generated"],
        )
        objects.append(_macro_scene_object(segment_name, "physics_body", segment_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, segment_name, "contains", f"{construct} {name} contains segment {index + 1}."))
        if previous:
            joint_values = deepcopy(values)
            joint_values["position"] = [center[0] + (index - (segment_count - 1) / 2.0 - 0.5) * 0.32, center[1] + y_offset, center[2] + 0.04]
            joint_values["joint_type"] = "rope_link" if construct == "rope" else "cable_link"
            joint_values["bodies"] = [previous, segment_name]
            joint_node = {"node_type": "scene_object", "name": f"{name}_link_{index:02d}", "role": "interactive", "from": node.get("from"), "values": joint_values}
            joint_objects, joint_relationships = _expand_physics_joint_macro(joint_node, construct="physics_joint")
            objects.extend(joint_objects)
            relationships.extend(joint_relationships)
            relationships.append(_macro_relationship(name, previous, segment_name, "attached_to", f"{construct} segment chain connects {previous} to {segment_name}."))
        previous = segment_name
    return objects, relationships


def _expand_cloth_flag_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
