def _expand_destruction_event_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "destruction_event")
    center = _macro_center(values)
    event_kind = _snake_id(values.get("event_type") or values.get("type"), "destroyed")
    targets = _gameplay_name_list(values, ("targets", "breakables", "objects"), default=[])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_destruction_event_core"
    core_values = _macro_child_values(
        values,
        construct="destruction_event",
        position=center,
        scale=[max(1.0, _number(values.get("width"), default=2.4)), max(0.8, _number(values.get("depth"), default=1.6)), 0.26],
        state={
            "destruction_event": name,
            "event_type": event_kind,
            "targets": targets,
            "target_count": len(targets),
            "damage": _number(values.get("damage"), default=100.0),
            "impulse": _number(values.get("impulse") or values.get("force"), default=0.0),
            "spawn_debris": not _disabled(values.get("debris", True)),
            "object_archetype": "destruction_event",
            "setpiece_layout": "destruction_burst",
            "event_count": 1,
            "debris_count": _positive_int(values.get("debris_count") or values.get("debris"), default=8),
            "vfx_count": 1,
            "sound_count": 1,
        },
        tags=["destruction_event", event_kind, "destruction", "macro_generated"],
    )
    core_values["affordances"] = {"detonate": {"action": "trigger_destruction", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "destruction_event", core_values, role="interactive", source=node.get("from")))

    if not _any_disabled(values, "debris", "debris_field"):
        debris_values = deepcopy(values)
        debris_values["position"] = [center[0] + 1.4, center[1], center[2] + 0.04]
        debris_values["debris_count"] = core_values["state"]["debris_count"]
        debris_node = {"node_type": "scene_object", "name": f"{name}_debris", "role": "environment_structure", "from": node.get("from"), "values": debris_values}
        debris_objects, debris_relationships = _expand_debris_field_macro(debris_node)
        objects.extend(debris_objects)
        relationships.extend(debris_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_debris_debris_core", "reveals", f"Destruction event {name} reveals debris."))

    if not _any_disabled(values, "force", "force_field"):
        force_values = deepcopy(values)
        force_values["position"] = [center[0] - 1.4, center[1], center[2] + 0.04]
        force_values["field_type"] = "impulse"
        force_values["force"] = core_values["state"]["impulse"] or core_values["state"]["damage"]
        force_node = {"node_type": "scene_object", "name": f"{name}_impulse", "role": "light_fixture", "from": node.get("from"), "values": force_values}
        force_objects, force_relationships = _expand_force_field_macro(force_node)
        objects.extend(force_objects)
        relationships.extend(force_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_impulse_force_field_core", "supports", f"Destruction event {name} applies impulse field."))

    if not _any_disabled(values, "vfx", "effect"):
        vfx_values = deepcopy(values)
        vfx_values["position"] = [center[0], center[1] + 1.1, center[2] + 0.04]
        vfx_values["effect_type"] = _snake_id(values.get("effect") or "debris_burst", "debris_burst")
        vfx_node = {"node_type": "scene_object", "name": f"{name}_burst", "role": "light_fixture", "from": node.get("from"), "values": vfx_values}
        vfx_objects, vfx_relationships = _expand_vfx_emitter_macro(vfx_node)
        objects.extend(vfx_objects)
        relationships.extend(vfx_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_burst_vfx_core", "reveals", f"Destruction event {name} triggers VFX."))

    if not _any_disabled(values, "sound", "audio"):
        sound_values = deepcopy(values)
        sound_values["position"] = [center[0], center[1] - 1.1, center[2] + 0.04]
        sound_values["sound_type"] = _snake_id(values.get("sound") or "impact_break", "impact_break")
        sound_node = {"node_type": "scene_object", "name": f"{name}_sound", "role": "narrative_clue", "from": node.get("from"), "values": sound_values}
        sound_objects, sound_relationships = _expand_sound_cue_macro(sound_node)
        objects.extend(sound_objects)
        relationships.extend(sound_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_sound_sound_core", "reveals", f"Destruction event {name} triggers sound."))
    return objects, relationships


def _expand_timeline_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "timeline")
    center = _macro_center(values)
    beats = _gameplay_name_list(values, ("clips", "actions", "beats", "steps"), default=["start", "loop", "end"])
    duration = _number(values.get("duration") or values.get("duration_seconds"), default=max(1.0, len(beats) * 1.0))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_timeline_core"
    core_values = _macro_child_values(
        values,
        construct="timeline",
        position=center,
        scale=[max(1.2, _number(values.get("width"), default=max(3.0, len(beats) * 1.2))), max(0.8, _number(values.get("depth"), default=1.2)), 0.22],
        state={
            "timeline": name,
            "timeline_type": _snake_id(values.get("timeline_type") or values.get("type"), "animation"),
            "duration_seconds": duration,
            "beat_count": len(beats),
            "loop": not _disabled(values.get("loop", False)),
            "start_event": _string(values.get("start_event") or values.get("starts_on"), default=""),
            "end_event": _string(values.get("end_event") or values.get("ends_on"), default=""),
            "object_archetype": "timeline",
            "setpiece_layout": "action_timeline",
            "structure_count": 1,
            "event_count": max(1, len(beats)),
            "state_count": max(2, len(beats)),
        },
        tags=["timeline", "animation", "action", "macro_generated"],
    )
    if core_values["state"]["start_event"]:
        core_values["affordances"] = {"start": {"action": "start_timeline", "requires": core_values["state"]["start_event"]}}
    objects.append(_macro_scene_object(core_name, "timeline", core_values, role="environment_structure", source=node.get("from")))

    previous_core = ""
    for index, beat in enumerate(beats):
        clip_values = deepcopy(values)
        clip_values["position"] = [center[0] + (index - (len(beats) - 1) / 2.0) * 1.4, center[1] + 1.1, center[2] + 0.04]
        clip_values["clip_type"] = beat
        clip_values["duration"] = duration / max(1, len(beats))
        clip_values["order"] = index + 1
        clip_values.setdefault("poses", ["start", "end"])
        clip_node = {"node_type": "scene_object", "name": f"{name}_{index + 1:02d}_{beat}_clip", "role": "narrative_clue", "from": node.get("from"), "values": clip_values}
        clip_objects, clip_relationships = _expand_animation_clip_macro(clip_node)
        objects.extend(clip_objects)
        relationships.extend(clip_relationships)
        clip_core = f"{name}_{index + 1:02d}_{beat}_clip_clip_core"
        relationships.append(_macro_relationship(name, core_name, clip_core, "contains", f"Timeline {name} contains clip {beat}."))
        if previous_core:
            relationships.append(_macro_relationship(name, previous_core, clip_core, "routes_to", f"Timeline {name} routes from previous clip to {beat}."))
        previous_core = clip_core

    return objects, relationships


def _expand_sequencer_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "sequencer")
    center = _macro_center(values)
    steps = _gameplay_name_list(values, ("steps", "actions", "sequence"), default=["prepare", "play", "finish"])
    events = _gameplay_name_list(values, ("events", "emits"), default=[])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_sequencer_core"
    core_values = _macro_child_values(
        values,
        construct="sequencer",
        position=center,
        scale=[max(1.5, _number(values.get("width"), default=max(3.0, len(steps) * 1.1))), max(0.8, _number(values.get("depth"), default=1.4)), 0.24],
        state={
            "sequencer": name,
            "sequence_type": _snake_id(values.get("sequence_type") or values.get("type"), "event_action"),
            "step_count": len(steps),
            "events": events,
            "event_count": len(events),
            "blocking": not _disabled(values.get("blocking", True)),
            "loop": not _disabled(values.get("loop", False)),
            "object_archetype": "sequencer",
            "setpiece_layout": "action_sequence",
            "state_count": max(2, len(steps)),
            "event_count": max(1, len(events) or len(steps)),
        },
        tags=["sequencer", "animation", "action", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "sequencer", core_values, role="interactive", source=node.get("from")))

    previous_core = ""
    for index, step in enumerate(steps):
        action_values = deepcopy(values)
        action_values["position"] = [center[0] + (index - (len(steps) - 1) / 2.0) * 1.2, center[1] + 1.0, center[2] + 0.04]
        action_values["action_type"] = step
        action_values["order"] = index + 1
        action_values["sound"] = False
        action_values["vfx"] = False
        action_node = {"node_type": "scene_object", "name": f"{name}_{index + 1:02d}_{step}_action", "role": "interactive", "from": node.get("from"), "values": action_values}
        action_objects, action_relationships = _expand_action_macro(action_node)
        objects.extend(action_objects)
        relationships.extend(action_relationships)
        action_core = f"{name}_{index + 1:02d}_{step}_action_action_core"
        relationships.append(_macro_relationship(name, core_name, action_core, "contains", f"Sequencer {name} contains action step {step}."))
        if previous_core:
            relationships.append(_macro_relationship(name, previous_core, action_core, "routes_to", f"Sequencer {name} advances to action {step}."))
        previous_core = action_core

    if events:
        emitter_values = deepcopy(values)
        emitter_values["position"] = [center[0], center[1] - 1.0, center[2] + 0.04]
        emitter_values["events"] = events
        emitter_values["emitter_type"] = "sequencer"
        emitter_node = {"node_type": "scene_object", "name": f"{name}_events", "role": "interactive", "from": node.get("from"), "values": emitter_values}
        emitter_objects, emitter_relationships = _expand_event_emitter_macro(emitter_node)
        objects.extend(emitter_objects)
        relationships.extend(emitter_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_events_emitter_core", "reveals", f"Sequencer {name} emits sequence events."))
    return objects, relationships


