def _expand_action_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "action")
    center = _macro_center(values)
    action_kind = _snake_id(values.get("action_type") or values.get("type") or values.get("verb"), "activate")
    target = _string(values.get("target") or values.get("actor") or values.get("object"), default="")
    events = _gameplay_name_list(values, ("events", "emits", "on_complete"), default=[])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_action_core"
    core_values = _macro_child_values(
        values,
        construct="action",
        position=center,
        scale=[max(0.5, _number(values.get("width"), default=1.2)), max(0.5, _number(values.get("depth"), default=0.9)), 0.20],
        state={
            "action": name,
            "action_type": action_kind,
            "target": target,
            "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=1.0),
            "requires": _string(values.get("requires"), default=""),
            "events": events,
            "event_count": len(events),
            "interruptible": not _disabled(values.get("interruptible", True)),
            "interaction_type": action_kind,
            "infrastructure_type": "action_node",
            "prop_count": 1,
        },
        tags=["action", action_kind, "animation", "macro_generated"],
    )
    core_values["affordances"] = {"play": {"action": f"play_{action_kind}", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "action", core_values, role="interactive", source=node.get("from")))

    if action_kind in {"open", "close", "raise", "lower", "slide", "rotate", "extend", "retract"} and not _any_disabled(values, "moving_part", "part"):
        part_values = deepcopy(values)
        part_values["position"] = [center[0] + 1.0, center[1], center[2] + 0.04]
        part_values["movement"] = action_kind
        part_node = {"node_type": "scene_object", "name": f"{name}_{action_kind}_part", "role": "interactive", "from": node.get("from"), "values": part_values}
        part_objects, part_relationships = _expand_moving_part_macro(part_node)
        objects.extend(part_objects)
        relationships.extend(part_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{action_kind}_part_moving_part_core", "reveals", f"Action {name} drives moving part."))

    if not _any_disabled(values, "vfx", "effect"):
        vfx_values = deepcopy(values)
        vfx_values["position"] = [center[0], center[1] + 0.8, center[2] + 0.04]
        vfx_values["effect_type"] = _snake_id(values.get("vfx") or values.get("effect") or action_kind, action_kind)
        vfx_node = {"node_type": "scene_object", "name": f"{name}_vfx", "role": "light_fixture", "from": node.get("from"), "values": vfx_values}
        vfx_objects, vfx_relationships = _expand_vfx_emitter_macro(vfx_node)
        objects.extend(vfx_objects)
        relationships.extend(vfx_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_vfx_vfx_core", "reveals", f"Action {name} triggers VFX."))

    if not _any_disabled(values, "sound", "audio"):
        sound_values = deepcopy(values)
        sound_values["position"] = [center[0], center[1] - 0.8, center[2] + 0.04]
        sound_values["sound_type"] = _snake_id(values.get("sound") or values.get("audio") or action_kind, action_kind)
        sound_node = {"node_type": "scene_object", "name": f"{name}_sound", "role": "narrative_clue", "from": node.get("from"), "values": sound_values}
        sound_objects, sound_relationships = _expand_sound_cue_macro(sound_node)
        objects.extend(sound_objects)
        relationships.extend(sound_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_sound_sound_core", "reveals", f"Action {name} triggers sound."))

    if events:
        emitter_values = deepcopy(values)
        emitter_values["position"] = [center[0] - 1.0, center[1], center[2] + 0.04]
        emitter_values["events"] = events
        emitter_values["emitter_type"] = "action"
        emitter_node = {"node_type": "scene_object", "name": f"{name}_events", "role": "interactive", "from": node.get("from"), "values": emitter_values}
        emitter_objects, emitter_relationships = _expand_event_emitter_macro(emitter_node)
        objects.extend(emitter_objects)
        relationships.extend(emitter_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_events_emitter_core", "reveals", f"Action {name} emits completion events."))
    return objects, relationships


