def _expand_motion_path_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "motion_path")
    center = _macro_center(values)
    labels = _gameplay_label_list(values, ("waypoint_names", "points", "anchors"))
    if not labels:
        labels = _gameplay_name_list(values, ("waypoints", "keyframes"), default=["start", "end"])
    waypoint_count = max(2, min(64, len(labels)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_motion_path_core"
    core_values = _macro_child_values(
        values,
        construct="motion_path",
        position=center,
        scale=[max(1.0, _number(values.get("width") or values.get("path_width"), default=max(2.0, waypoint_count * 0.9))), max(0.5, _number(values.get("depth") or values.get("path_depth"), default=1.0)), 0.12],
        state={
            "motion_path": name,
            "path_type": _snake_id(values.get("path_type") or values.get("interpolation") or values.get("type"), "linear"),
            "waypoint_count": waypoint_count,
            "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=1.0),
            "loop": not _disabled(values.get("loop", False)),
            "road_segment_count": max(1, waypoint_count - 1),
            "branch_count": 0,
        },
        tags=["motion_path", "animation", "path", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "motion_path", core_values, role="navigation", source=node.get("from")))

    token = hashlib.sha256(name.encode("utf-8")).hexdigest()[:6]
    waypoint_names: list[str] = []
    for index, label in enumerate(labels[:waypoint_count]):
        x = center[0] + (index - (waypoint_count - 1) / 2.0) * 0.9
        waypoint_name = f"{name[:32].rstrip('_')}_{token}_wp{index + 1:02d}_{label}"[:60].rstrip("_")
        waypoint_names.append(waypoint_name)
        waypoint_values = _macro_child_values(
            values,
            construct="interactable",
            position=[x, center[1] + 0.8, center[2] + 0.03],
            scale=[0.28, 0.28, 0.10],
            state={"motion_path": name, "waypoint": label, "waypoint_index": index, "interaction_type": "motion_waypoint"},
            tags=["motion_waypoint", label, "animation", "macro_generated"],
        )
        waypoint_values["affordances"] = {"arrive": {"action": "motion_arrive"}}
        objects.append(_macro_scene_object(waypoint_name, "interactable", waypoint_values, role="navigation", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, waypoint_name, "routes_to", f"Motion path {name} routes to waypoint {label}."))
    for index, waypoint_name in enumerate(waypoint_names[:-1]):
        relationships.append(_macro_relationship(name, waypoint_name, waypoint_names[index + 1], "routes_to", f"Motion waypoint {waypoint_name} routes onward."))
    return objects, relationships


def _expand_moving_part_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "moving_part")
    center = _macro_center(values)
    movement = _snake_id(values.get("movement") or values.get("motion") or values.get("movement_type") or values.get("type"), "slide")
    axis = _snake_id(values.get("axis"), "x")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_moving_part_core"
    core_values = _macro_child_values(
        values,
        construct="moving_part",
        position=center,
        scale=[max(0.5, _number(values.get("width"), default=1.4)), max(0.2, _number(values.get("depth"), default=0.4)), max(0.1, _number(values.get("height"), default=0.18))],
        state={
            "moving_part": name,
            "movement_type": movement,
            "axis": axis,
            "distance": _number(values.get("distance") or values.get("travel"), default=1.0),
            "angle_degrees": _number(values.get("angle") or values.get("angle_degrees"), default=90.0 if movement in {"rotate", "swing"} else 0.0),
            "speed": _number(values.get("speed"), default=1.0),
            "rest_state": _snake_id(values.get("rest_state") or values.get("from_state"), "closed"),
            "active_state": _snake_id(values.get("active_state") or values.get("to_state"), "open"),
            "infrastructure_type": "moving_part",
            "access_count": 1,
            "module_socket_count": 1,
        },
        tags=["moving_part", movement, axis, "animation", "macro_generated"],
    )
    core_values["affordances"] = {"move": {"action": f"{movement}_part", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "moving_part", core_values, role="interactive", source=node.get("from")))

    if not _any_disabled(values, "path", "motion_path"):
        path_values = deepcopy(values)
        path_values["position"] = [center[0], center[1] + 0.9, center[2] + 0.03]
        path_values.setdefault("waypoints", ["rest", "active"])
        path_node = {"node_type": "scene_object", "name": f"{name}_path", "role": "navigation", "from": node.get("from"), "values": path_values}
        path_objects, path_relationships = _expand_motion_path_macro(path_node)
        objects.extend(path_objects)
        relationships.extend(path_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_path_motion_path_core", "routes_to", f"Moving part {name} follows a motion path."))
    return objects, relationships


def _expand_door_or_gate_action_macro(
    node: Mapping[str, Any],
    *,
    construct: str,
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    action_kind = _snake_id(values.get("action_type") or values.get("type") or values.get("movement"), "open")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_{construct}_core"
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=[max(1.0, _number(values.get("width"), default=2.0)), max(0.4, _number(values.get("depth"), default=0.7)), max(0.2, _number(values.get("height"), default=0.24))],
        state={
            construct: name,
            "action_type": action_kind,
            "access_type": construct,
            "requires": _string(values.get("requires"), default=""),
            "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=1.2),
            "safety_gate_count": 1,
            "walkway_count": 1,
            "guardrail_count": 2 if construct == "gate_action" else 0,
        },
        tags=[construct, action_kind, "access", "animation", "macro_generated"],
    )
    core_values["affordances"] = {action_kind: {"action": f"{action_kind}_{construct.removesuffix('_action')}", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, construct, core_values, role="navigation", source=node.get("from")))

    part_values = deepcopy(values)
    part_values["position"] = [center[0], center[1] + 0.85, center[2] + 0.04]
    part_values["movement"] = _snake_id(values.get("movement") or ("swing" if construct == "door_action" else "slide"), "slide")
    part_values["from_state"] = _snake_id(values.get("from_state"), "closed")
    part_values["to_state"] = _snake_id(values.get("to_state"), "open")
    part_node = {"node_type": "scene_object", "name": f"{name}_panel", "role": "interactive", "from": node.get("from"), "values": part_values}
    part_objects, part_relationships = _expand_moving_part_macro(part_node)
    objects.extend(part_objects)
    relationships.extend(part_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_panel_moving_part_core", "contains", f"{construct} {name} contains animated panel."))

    if not _any_disabled(values, "sound", "audio"):
        sound_values = deepcopy(values)
        sound_values["position"] = [center[0] - 0.9, center[1] - 0.75, center[2] + 0.04]
        sound_values["sound_type"] = _snake_id(values.get("sound") or action_kind, action_kind)
        sound_node = {"node_type": "scene_object", "name": f"{name}_sound", "role": "narrative_clue", "from": node.get("from"), "values": sound_values}
        sound_objects, sound_relationships = _expand_sound_cue_macro(sound_node)
        objects.extend(sound_objects)
        relationships.extend(sound_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_sound_sound_core", "reveals", f"{construct} {name} triggers sound."))
    return objects, relationships


def _expand_machine_cycle_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "machine_cycle")
    center = _macro_center(values)
    phases = _gameplay_name_list(values, ("phases", "steps", "actions"), default=["start", "operate", "reset"])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_machine_cycle_core"
    core_values = _macro_child_values(
        values,
        construct="machine_cycle",
        position=center,
        scale=[max(1.4, _number(values.get("width"), default=2.6)), max(1.0, _number(values.get("depth"), default=1.6)), max(0.3, _number(values.get("height"), default=0.5))],
        state={
            "machine_cycle": name,
            "machine_type": _snake_id(values.get("machine_type") or values.get("type"), "animated_machine"),
            "phase_count": len(phases),
            "phases": phases,
            "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=max(1.0, len(phases))),
            "loop": not _disabled(values.get("loop", True)),
            "conveyor_count": _positive_int(values.get("conveyors"), default=1),
            "gear_count": _positive_int(values.get("gears"), default=max(1, len(phases))),
            "piston_count": _positive_int(values.get("pistons"), default=max(1, len(phases) - 1)),
        },
        tags=["machine_cycle", "machine", "animation", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "machine_cycle", core_values, role="interactive", source=node.get("from")))

    timeline_values = deepcopy(values)
    timeline_values["position"] = [center[0], center[1] + 1.6, center[2] + 0.04]
    timeline_values["beats"] = phases
    timeline_values["duration"] = core_values["state"]["duration_seconds"]
    timeline_node = {"node_type": "scene_object", "name": f"{name}_timeline", "role": "environment_structure", "from": node.get("from"), "values": timeline_values}
    timeline_objects, timeline_relationships = _expand_timeline_macro(timeline_node)
    objects.extend(timeline_objects)
    relationships.extend(timeline_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_timeline_timeline_core", "contains", f"Machine cycle {name} contains animation timeline."))

    for index, phase in enumerate(phases):
        part_values = deepcopy(values)
        part_values["position"] = [center[0] + (index - (len(phases) - 1) / 2.0) * 0.9, center[1] - 0.9, center[2] + 0.04]
        part_values["movement"] = "rotate" if index % 2 == 0 else "slide"
        part_values["axis"] = "z" if index % 2 == 0 else "x"
        part_node = {"node_type": "scene_object", "name": f"{name}_{phase}_part", "role": "interactive", "from": node.get("from"), "values": part_values}
        part_objects, part_relationships = _expand_moving_part_macro(part_node)
        objects.extend(part_objects)
        relationships.extend(part_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{phase}_part_moving_part_core", "supports", f"Machine phase {phase} drives a moving part."))
    return objects, relationships


