def _expand_event_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "event")
    center = _macro_center(values)
    event_kind = _snake_id(values.get("event_type") or values.get("type") or values.get("signal"), "custom")
    channels = _gameplay_name_list(values, ("channels", "channel", "bus"), default=["world"])
    payload_keys = _gameplay_name_list(values, ("payload", "payload_keys", "fields"), default=[])
    targets = _gameplay_name_list(values, ("targets", "to", "reveals", "effects"), default=[])
    requires = _gameplay_name_list(values, ("requires", "conditions", "gates"), default=[])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_event_core"
    core_values = _macro_child_values(
        values,
        construct="event",
        position=center,
        scale=[max(0.5, _number(values.get("width"), default=1.2)), max(0.5, _number(values.get("depth"), default=0.9)), 0.20],
        state={
            "event": name,
            "event_type": event_kind,
            "channels": channels,
            "channel_count": len(channels),
            "payload_keys": payload_keys,
            "target_count": len(targets),
            "condition_count": len(requires),
            "repeatable": not _disabled(values.get("repeatable", True)),
            "cooldown_seconds": _number(values.get("cooldown") or values.get("cooldown_seconds"), default=0.0),
            "priority": _positive_int(values.get("priority"), default=1),
            "infrastructure_type": "event_signal",
            "prop_count": max(1, len(channels)),
        },
        tags=["event", event_kind, "stateful", "simulation", "macro_generated"],
    )
    core_values["affordances"] = {"emit": {"action": "emit_event", "requires": ",".join(requires)}}
    objects.append(_macro_scene_object(core_name, "event", core_values, role="narrative_clue", source=node.get("from")))

    for index, channel in enumerate(channels):
        channel_name = f"{name[:42].rstrip('_')}_channel_{index + 1:02d}_{channel}"[:60].rstrip("_")
        channel_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (len(channels) - 1) / 2.0) * 0.9, center[1] + 0.8, center[2] + 0.04],
            scale=[0.38, 0.38, 0.14],
            state={"event": name, "channel": channel, "event_type": event_kind, "interaction_type": "listen_event"},
            tags=["event_channel", channel, event_kind, "stateful", "macro_generated"],
        )
        channel_values["affordances"] = {"listen": {"action": "listen_event"}}
        objects.append(_macro_scene_object(channel_name, "interactable", channel_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, channel_name, "contains", f"Event {name} publishes channel {channel}."))

    return objects, relationships


