def _expand_timer_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "timer")
    center = _macro_center(values)
    timer_kind = _snake_id(values.get("timer_type") or values.get("type"), "countdown")
    events = _gameplay_name_list(values, ("events", "on_complete", "emits"), default=[f"{name}_complete"])
    tick_count = max(0, min(64, _positive_int(values.get("ticks") or values.get("tick_count"), default=3)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_timer_core"
    core_values = _macro_child_values(
        values,
        construct="timer",
        position=center,
        scale=[max(0.6, _number(values.get("width"), default=1.4)), max(0.6, _number(values.get("depth"), default=1.0)), 0.24],
        state={
            "timer": name,
            "timer_type": timer_kind,
            "duration_seconds": _number(values.get("duration") or values.get("seconds") or values.get("duration_seconds"), default=30.0),
            "tick_count": tick_count,
            "events": events,
            "loop": not _disabled(values.get("loop", False)),
            "start_condition": _string(values.get("start") or values.get("starts_when"), default=""),
            "infrastructure_type": "timer_relay",
            "sensor_count": max(1, tick_count),
        },
        tags=["timer", timer_kind, "stateful", "macro_generated"],
    )
    core_values["affordances"] = {"start_timer": {"action": "start_timer", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "timer", core_values, role="interactive", source=node.get("from")))

    for index in range(tick_count):
        tick_name = f"{name}_tick_{index + 1:02d}"
        tick_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (tick_count - 1) / 2.0) * 0.7, center[1] + 0.85, center[2] + 0.04],
            scale=[0.30, 0.30, 0.12],
            state={"timer": name, "tick_index": index + 1, "interaction_type": "timer_tick"},
            tags=["timer_tick", timer_kind, "stateful", "macro_generated"],
        )
        tick_values["affordances"] = {"tick": {"action": "timer_tick"}}
        objects.append(_macro_scene_object(tick_name, "interactable", tick_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, tick_name, "contains", f"Timer {name} contains tick marker {index + 1}."))

    emitter_values = deepcopy(values)
    emitter_values["position"] = [center[0], center[1] - 0.9, center[2] + 0.04]
    emitter_values["events"] = events
    emitter_values["emitter_type"] = "timer"
    emitter_node = {"node_type": "scene_object", "name": f"{name}_complete_emitter", "role": "interactive", "from": node.get("from"), "values": emitter_values}
    emitter_objects, emitter_relationships = _expand_event_emitter_macro(emitter_node)
    objects.extend(emitter_objects)
    relationships.extend(emitter_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_complete_emitter_emitter_core", "reveals", f"Timer {name} emits completion events."))
    return objects, relationships


def _expand_scene_state_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "scene_state")
    center = _macro_center(values)
    state_key = _snake_id(values.get("state_key") or values.get("key") or values.get("state"), name)
    state_value = _snake_id(values.get("value") or values.get("state_value") or values.get("mode"), "active")
    core_name = f"{name}_scene_state_core"
    core_values = _macro_child_values(
        values,
        construct="scene_state",
        position=center,
        scale=[max(0.5, _number(values.get("width"), default=1.0)), max(0.5, _number(values.get("depth"), default=0.8)), 0.18],
        state={
            "scene_state": name,
            "state_key": state_key,
            "state_value": state_value,
            "initial": not _disabled(values.get("initial", False)),
            "persistent": not _disabled(values.get("persistent", True)),
            "affected_refs": _gameplay_name_list(values, ("affects", "targets", "objects"), default=[]),
            "infrastructure_type": "state_marker",
            "prop_count": 1,
        },
        tags=["scene_state", state_key, state_value, "stateful", "macro_generated"],
    )
    core_values["affordances"] = {"inspect_state": {"action": "inspect_state"}}
    return [_macro_scene_object(core_name, "scene_state", core_values, role="narrative_clue", source=node.get("from"))], []


def _expand_state_transition_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "state_transition")
    center = _macro_center(values)
    from_state = _snake_id(values.get("from_state") or values.get("from") or values.get("source_state"), "inactive")
    to_state = _snake_id(values.get("to_state") or values.get("to") or values.get("target_state"), "active")
    event_ref = _string(values.get("event") or values.get("on") or values.get("when"), default="")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_transition_core"
    core_values = _macro_child_values(
        values,
        construct="state_transition",
        position=center,
        scale=[max(0.6, _number(values.get("width"), default=1.4)), max(0.35, _number(values.get("depth"), default=0.7)), 0.20],
        state={
            "state_transition": name,
            "from_state": from_state,
            "to_state": to_state,
            "event": event_ref,
            "condition": _string(values.get("condition") or values.get("requires"), default=""),
            "priority": _positive_int(values.get("priority"), default=1),
            "one_shot": _disabled(values.get("repeatable", True)),
            "infrastructure_type": "state_transition",
            "junction_box_count": 1,
        },
        tags=["state_transition", from_state, to_state, "stateful", "macro_generated"],
    )
    core_values["affordances"] = {"transition": {"action": "apply_state_transition", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "state_transition", core_values, role="interactive", source=node.get("from")))

    for label, offset in ((from_state, -0.9), (to_state, 0.9)):
        state_values = deepcopy(values)
        state_values["position"] = [center[0] + offset, center[1], center[2] + 0.03]
        state_values["state_key"] = _snake_id(values.get("state_key") or values.get("machine") or name, name)
        state_values["value"] = label
        state_node = {"node_type": "scene_object", "name": f"{name}_{label}_state", "role": "narrative_clue", "from": node.get("from"), "values": state_values}
        state_objects, state_relationships = _expand_scene_state_macro(state_node)
        objects.extend(state_objects)
        relationships.extend(state_relationships)
    relationships.append(_macro_relationship(name, f"{name}_{from_state}_state_scene_state_core", core_name, "routes_to", f"Transition {name} starts at state {from_state}."))
    relationships.append(_macro_relationship(name, core_name, f"{name}_{to_state}_state_scene_state_core", "routes_to", f"Transition {name} moves to state {to_state}."))
    if event_ref.endswith("_core"):
        relationships.append(_macro_relationship(name, core_name, event_ref, "depends_on", f"Transition {name} depends on event {event_ref}."))
    return objects, relationships


def _expand_state_machine_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "state_machine")
    center = _macro_center(values)
    states = _gameplay_name_list(values, ("states", "modes"), default=["inactive", "active", "complete"])
    events = _gameplay_name_list(values, ("events", "event_names", "signals"), default=[])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_state_machine_core"
    core_values = _macro_child_values(
        values,
        construct="state_machine",
        position=center,
        scale=[max(2.0, _number(values.get("width"), default=max(4.0, len(states) * 1.4))), max(1.2, _number(values.get("depth"), default=2.0)), 0.28],
        state={
            "state_machine": name,
            "machine_type": _snake_id(values.get("machine_type") or values.get("type"), "finite_state"),
            "states": states,
            "state_count": len(states),
            "events": events,
            "initial_state": _snake_id(values.get("initial") or values.get("initial_state"), states[0]),
            "terminal_state": _snake_id(values.get("terminal") or values.get("terminal_state"), states[-1]),
            "object_archetype": "state_machine",
            "setpiece_layout": "state_logic",
            "structure_count": max(1, len(states)),
            "road_segment_count": max(1, len(states) - 1),
            "prop_count": max(1, len(events)),
        },
        tags=["state_machine", "stateful", "logic", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "state_machine", core_values, role="environment_structure", source=node.get("from")))

    state_core_names: list[str] = []
    for index, state in enumerate(states):
        state_values = deepcopy(values)
        state_values["position"] = [center[0] + (index - (len(states) - 1) / 2.0) * 1.5, center[1] + 1.2, center[2] + 0.04]
        state_values["state_key"] = name
        state_values["value"] = state
        state_values["initial"] = state == core_values["state"]["initial_state"]
        state_node = {"node_type": "scene_object", "name": f"{name}_{state}", "role": "narrative_clue", "from": node.get("from"), "values": state_values}
        state_objects, state_relationships = _expand_scene_state_macro(state_node)
        objects.extend(state_objects)
        relationships.extend(state_relationships)
        state_core = f"{name}_{state}_scene_state_core"
        state_core_names.append(state_core)
        relationships.append(_macro_relationship(name, core_name, state_core, "contains", f"State machine {name} contains state {state}."))

    for index in range(max(0, len(states) - 1)):
        transition_values = deepcopy(values)
        transition_values["position"] = [center[0] + (index - (len(states) - 2) / 2.0) * 1.5, center[1] - 0.6, center[2] + 0.04]
        transition_values["from_state"] = states[index]
        transition_values["to_state"] = states[index + 1]
        transition_values["event"] = events[index % len(events)] if events else f"{states[index]}_to_{states[index + 1]}"
        transition_values["state_key"] = name
        transition_node = {"node_type": "scene_object", "name": f"{name}_{states[index]}_to_{states[index + 1]}", "role": "interactive", "from": node.get("from"), "values": transition_values}
        transition_objects, transition_relationships = _expand_state_transition_macro(transition_node)
        objects.extend(transition_objects)
        relationships.extend(transition_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{states[index]}_to_{states[index + 1]}_transition_core", "contains", f"State machine {name} contains transition {index + 1}."))
    return objects, relationships


def _expand_conditional_spawn_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "conditional_spawn")
    center = _macro_center(values)
    actors = _gameplay_name_list(values, ("actors", "actor_types", "species", "npc_types"), default=["npc"])
    condition = _string(values.get("condition") or values.get("requires") or values.get("when"), default="")
    events = _gameplay_name_list(values, ("events", "on_spawn", "emits"), default=[f"{name}_spawned"])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_spawn_rule_core"
    core_values = _macro_child_values(
        values,
        construct="conditional_spawn",
        position=center,
        scale=[max(1.2, _number(values.get("width"), default=4.0)), max(1.0, _number(values.get("depth"), default=3.0)), 0.26],
        state={
            "conditional_spawn": name,
            "condition": condition,
            "actors": actors,
            "actor_count": len(actors),
            "spawn_count": max(1, min(64, _positive_int(values.get("spawns") or values.get("spawn_count"), default=len(actors)))),
            "respawn_seconds": _number(values.get("respawn") or values.get("respawn_seconds"), default=0.0),
            "events": events,
            "object_archetype": "spawn_rule",
            "setpiece_layout": "conditional_spawn",
            "spawn_point_count": max(1, len(actors)),
            "prop_count": max(1, len(actors)),
        },
        tags=["conditional_spawn", "spawn_rule", "stateful", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "conditional_spawn", core_values, role="interactive", source=node.get("from")))

    trigger_values = deepcopy(values)
    trigger_values["position"] = [center[0] - 1.8, center[1], center[2] + 0.04]
    trigger_values["events"] = events
    trigger_values["requires"] = condition
    trigger_values["trigger_type"] = _snake_id(values.get("trigger_type") or "condition_met", "condition_met")
    trigger_node = {"node_type": "scene_object", "name": f"{name}_trigger", "role": "interactive", "from": node.get("from"), "values": trigger_values}
    trigger_objects, trigger_relationships = _expand_trigger_volume_macro(trigger_node)
    objects.extend(trigger_objects)
    relationships.extend(trigger_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_trigger_trigger_core", "depends_on", f"Conditional spawn {name} depends on trigger."))

    encounter_values = deepcopy(values)
    encounter_values["position"] = [center[0] + 1.8, center[1], center[2] + 0.04]
    encounter_values["encounter_type"] = "conditional_spawn"
    encounter_values["actor_types"] = actors
    encounter_values["spawns"] = core_values["state"]["spawn_count"]
    encounter_values["cover"] = _positive_int(values.get("cover"), default=0)
    encounter_values["loot"] = False
    encounter_node = {"node_type": "scene_object", "name": f"{name}_encounter", "role": "interactive", "from": node.get("from"), "values": encounter_values}
    encounter_objects, encounter_relationships = _expand_encounter_macro(encounter_node)
    objects.extend(encounter_objects)
    relationships.extend(encounter_relationships)
    relationships.append(_macro_relationship(name, f"{name}_encounter_encounter_core", core_name, "reveals", f"Conditional spawn {name} reveals encounter."))
    return objects, relationships


def _expand_alert_network_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "alert_network")
    center = _macro_center(values)
    alert_kind = _snake_id(values.get("alert_type") or values.get("type"), "security")
    sensors = max(1, min(48, _positive_int(values.get("sensors") or values.get("sensor_count"), default=3)))
    responders = max(0, min(16, _positive_int(values.get("responders") or values.get("response_count"), default=1)))
    faction = _snake_id(values.get("faction") or _nested(values, "state", "faction"), "neutral")
    events = _gameplay_name_list(values, ("events", "alerts", "signals"), default=[f"{name}_alert"])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_alert_core"
    core_values = _macro_child_values(
        values,
        construct="alert_network",
        position=center,
        scale=[max(2.0, _number(values.get("width"), default=8.0)), max(2.0, _number(values.get("depth"), default=6.0)), 0.30],
        state={
            "alert_network": name,
            "alert_type": alert_kind,
            "faction": faction,
            "sensor_count": sensors,
            "responder_count": responders,
            "events": events,
            "propagation": _snake_id(values.get("propagation") or values.get("mode"), "broadcast"),
            "alert_radius": _number(values.get("radius") or values.get("alert_radius"), default=24.0),
            "object_archetype": "alert_network",
            "setpiece_layout": "alert_grid",
            "structure_count": 1,
            "prop_count": sensors,
            "road_segment_count": max(1, sensors - 1),
        },
        tags=["alert_network", alert_kind, faction, "stateful", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "alert_network", core_values, role="environment_structure", source=node.get("from")))

    for index in range(sensors):
        sensor_values = deepcopy(values)
        angle = math.tau * index / max(1, sensors)
        sensor_values["position"] = [center[0] + math.cos(angle) * 2.8, center[1] + math.sin(angle) * 2.2, center[2] + 0.04]
        sensor_values["events"] = events
        sensor_values["trigger_type"] = "alert_sensor"
        sensor_values["filters"] = _gameplay_name_list(values, ("filters", "targets"), default=["intruder"])
        sensor_node = {"node_type": "scene_object", "name": f"{name}_sensor_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": sensor_values}
        sensor_objects, sensor_relationships = _expand_trigger_volume_macro(sensor_node)
        objects.extend(sensor_objects)
        relationships.extend(sensor_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_sensor_{index + 1:02d}_trigger_core", "contains", f"Alert network {name} contains sensor {index + 1}."))

    for index in range(responders):
        encounter_values = deepcopy(values)
        encounter_values["position"] = [center[0], center[1] + 3.0 + index * 1.0, center[2] + 0.05]
        encounter_values["encounter_type"] = "alert_response"
        encounter_values["actor_types"] = _gameplay_name_list(values, ("responders_types", "actor_types", "guards"), default=["guard"])
        encounter_values["spawns"] = _positive_int(values.get("response_spawns") or values.get("spawns"), default=2)
        encounter_values["faction"] = faction
        encounter_values["loot"] = False
        encounter_node = {"node_type": "scene_object", "name": f"{name}_response_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": encounter_values}
        encounter_objects, encounter_relationships = _expand_encounter_macro(encounter_node)
        objects.extend(encounter_objects)
        relationships.extend(encounter_relationships)
        relationships.append(_macro_relationship(name, f"{name}_response_{index + 1:02d}_encounter_core", core_name, "supports", f"Alert response supports network {name}."))
    return objects, relationships


def _expand_scene_mutation_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "scene_mutation")
    center = _macro_center(values)
    mutation_kind = _snake_id(values.get("mutation_type") or values.get("type") or values.get("action"), "toggle")
    targets = _gameplay_name_list(values, ("targets", "affects", "objects"), default=[])
    condition = _string(values.get("condition") or values.get("requires") or values.get("when"), default="")
    events = _gameplay_name_list(values, ("events", "on_apply", "emits"), default=[f"{name}_applied"])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_mutation_core"
    core_values = _macro_child_values(
        values,
        construct="scene_mutation",
        position=center,
        scale=[max(1.0, _number(values.get("width"), default=2.4)), max(0.8, _number(values.get("depth"), default=1.6)), 0.26],
        state={
            "scene_mutation": name,
            "mutation_type": mutation_kind,
            "targets": targets,
            "target_count": len(targets),
            "condition": condition,
            "events": events,
            "apply_mode": _snake_id(values.get("apply_mode") or values.get("mode"), "immediate"),
            "object_archetype": "scene_mutation",
            "setpiece_layout": "state_change",
            "structure_count": 1,
            "prop_count": max(1, len(targets)),
        },
        tags=["scene_mutation", mutation_kind, "stateful", "macro_generated"],
    )
    core_values["affordances"] = {"apply": {"action": f"apply_{mutation_kind}", "requires": condition}}
    objects.append(_macro_scene_object(core_name, "scene_mutation", core_values, role="environment_structure", source=node.get("from")))

    before_values = deepcopy(values)
    before_values["position"] = [center[0] - 0.9, center[1] + 0.9, center[2] + 0.04]
    before_values["state_key"] = name
    before_values["value"] = _snake_id(values.get("from_state") or values.get("before"), "before")
    before_node = {"node_type": "scene_object", "name": f"{name}_before", "role": "narrative_clue", "from": node.get("from"), "values": before_values}
    after_values = deepcopy(values)
    after_values["position"] = [center[0] + 0.9, center[1] + 0.9, center[2] + 0.04]
    after_values["state_key"] = name
    after_values["value"] = _snake_id(values.get("to_state") or values.get("after"), "after")
    after_node = {"node_type": "scene_object", "name": f"{name}_after", "role": "narrative_clue", "from": node.get("from"), "values": after_values}
    for state_node in (before_node, after_node):
        state_objects, state_relationships = _expand_scene_state_macro(state_node)
        objects.extend(state_objects)
        relationships.extend(state_relationships)
    relationships.append(_macro_relationship(name, f"{name}_before_scene_state_core", core_name, "routes_to", f"Mutation {name} starts from before state."))
    relationships.append(_macro_relationship(name, core_name, f"{name}_after_scene_state_core", "routes_to", f"Mutation {name} applies after state."))

    emitter_values = deepcopy(values)
    emitter_values["position"] = [center[0], center[1] - 0.9, center[2] + 0.04]
    emitter_values["events"] = events
    emitter_values["emitter_type"] = "scene_mutation"
    emitter_node = {"node_type": "scene_object", "name": f"{name}_emitter", "role": "interactive", "from": node.get("from"), "values": emitter_values}
    emitter_objects, emitter_relationships = _expand_event_emitter_macro(emitter_node)
    objects.extend(emitter_objects)
    relationships.extend(emitter_relationships)
    relationships.append(_macro_relationship(name, core_name, f"{name}_emitter_emitter_core", "reveals", f"Mutation {name} emits apply events."))
    return objects, relationships


def _expand_actor_macro(
    node: Mapping[str, Any],
    *,
    construct: str,
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    actor_kind = _snake_id(
        values.get("actor_type")
        or values.get(f"{construct}_type")
        or values.get("profession")
        or values.get("job")
        or values.get("role"),
        construct,
    )
    faction = _snake_id(values.get("faction") or _nested(values, "state", "faction"), "neutral")
    behavior = _snake_id(values.get("behavior") or values.get("behavior_profile") or values.get("personality"), "ambient")
    core_name = f"{name}_{construct}_core"
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []

    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=[
            max(0.25, _number(values.get("width") or values.get("radius"), default=0.72)),
            max(0.25, _number(values.get("depth") or values.get("radius"), default=0.72)),
            max(0.35, _number(values.get("height"), default=1.75)),
        ],
        state={
            "actor": name,
            construct: name,
            "actor_type": actor_kind,
            "behavior_profile": behavior,
            "faction": faction,
            "disposition": _snake_id(values.get("disposition") or values.get("attitude"), "neutral"),
            "home": _string(values.get("home") or values.get("home_region"), default=""),
            "schedule": _string(values.get("schedule_ref") or values.get("schedule"), default=""),
            "patrol_route": _string(values.get("patrol_route") or values.get("route"), default=""),
            "dialogue_tree": _string(values.get("dialogue_tree") or values.get("dialogue"), default=""),
            "inventory_loadout": _string(values.get("inventory_loadout") or values.get("loadout"), default=""),
            "spawn_state": _snake_id(values.get("spawn_state") or values.get("state"), "available"),
            "sense_radius": _number(values.get("sense_radius") or values.get("awareness"), default=8.0),
            "movement_speed": _number(values.get("speed") or values.get("movement_speed"), default=1.0),
            "object_archetype": "actor",
            "setpiece_layout": "actor_anchor",
            "structure_count": 1,
            "road_segment_count": 0,
            "infrastructure_count": 0,
            "prop_count": 1,
            "child_socket_count": 0,
        },
        tags=[construct, "actor", actor_kind, faction, behavior, "behavior", "macro_generated"],
    )
    affordances: dict[str, Any] = {
        "observe": {"action": "observe_actor"},
        "interact": {"action": _snake_id(values.get("interaction") or "interact_actor", "interact_actor")},
    }
    dialogue_ref = _string(values.get("dialogue_tree") or values.get("dialogue"), default="")
    if dialogue_ref and not _disabled(values.get("dialogue")):
        affordances["talk"] = {"action": "start_dialogue", "reveals": dialogue_ref}
    loadout_ref = _string(values.get("inventory_loadout") or values.get("loadout"), default="")
    if loadout_ref and not _disabled(values.get("inventory")):
        affordances["inspect_loadout"] = {"action": "inspect_inventory", "reveals": loadout_ref}
    core_values["affordances"] = affordances
    objects.append(_macro_scene_object(core_name, construct, core_values, role="interactive", source=node.get("from")))

    home = _string(values.get("home") or values.get("home_region"), default="")
    if home:
        relationships.append(_macro_relationship(name, core_name, home, "attached_to", f"Actor {name} belongs to home anchor {home}."))
    faction_ref = _string(values.get("faction_behavior") or values.get("faction_ref"), default="")
    if faction_ref:
        relationships.append(_macro_relationship(name, core_name, faction_ref, "depends_on", f"Actor {name} follows faction behavior {faction_ref}."))

    schedule_enabled = not _any_disabled(values, "schedule", "routine", "activities")
    if schedule_enabled:
        schedule_values = deepcopy(values)
        schedule_values["position"] = [center[0] + 1.4, center[1] + 0.9, center[2] + 0.04]
        schedule_values["actor"] = core_name
        schedule_values.setdefault("activities", _actor_default_activities(actor_kind))
        schedule_node = {"node_type": "scene_object", "name": f"{name}_schedule", "role": "narrative_clue", "from": node.get("from"), "values": schedule_values}
        schedule_objects, schedule_relationships = _expand_schedule_macro(schedule_node)
        objects.extend(schedule_objects)
        relationships.extend(schedule_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_schedule_schedule_core", "depends_on", f"Actor {name} follows a schedule."))

    patrol_requested = any(key in values for key in ("patrol", "patrol_route", "waypoints", "patrol_points", "route"))
    patrol_default = actor_kind in {"guard", "soldier", "scout", "patrol", "sentinel", "ranger"}
    if (patrol_requested or patrol_default) and not _any_disabled(values, "patrol", "patrol_route", "waypoints"):
        patrol_values = deepcopy(values)
        patrol_values["position"] = [center[0], center[1] + 2.0, center[2] + 0.03]
        patrol_values["actor"] = core_name
        patrol_values.setdefault("route_type", "patrol")
        patrol_node = {"node_type": "scene_object", "name": f"{name}_patrol", "role": "navigation", "from": node.get("from"), "values": patrol_values}
        patrol_objects, patrol_relationships = _expand_patrol_route_macro(patrol_node)
        objects.extend(patrol_objects)
        relationships.extend(patrol_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_patrol_patrol_core", "routes_to", f"Actor {name} uses patrol route."))

    dialogue_requested = any(key in values for key in ("dialogue", "dialogue_tree", "topics", "lines", "responses"))
    dialogue_default = actor_kind in {"civilian", "vendor", "quest_giver", "guide", "merchant", "informant"}
    if (dialogue_requested or dialogue_default) and not _any_disabled(values, "dialogue", "dialogue_tree"):
        dialogue_values = deepcopy(values)
        dialogue_values["position"] = [center[0] - 1.2, center[1] + 0.9, center[2] + 0.04]
        dialogue_values["speaker"] = core_name
        dialogue_node = {"node_type": "scene_object", "name": f"{name}_dialogue", "role": "narrative_clue", "from": node.get("from"), "values": dialogue_values}
        dialogue_objects, dialogue_relationships = _expand_dialogue_tree_macro(dialogue_node)
        objects.extend(dialogue_objects)
        relationships.extend(dialogue_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_dialogue_dialogue_core", "reveals", f"Actor {name} exposes dialogue."))

    inventory_requested = any(key in values for key in ("inventory", "inventory_loadout", "loadout", "items", "equipment"))
    inventory_default = actor_kind in {"guard", "soldier", "vendor", "merchant", "mechanic", "scavenger"}
    if (inventory_requested or inventory_default) and not _any_disabled(values, "inventory", "inventory_loadout", "loadout"):
        inventory_values = deepcopy(values)
        inventory_values["position"] = [center[0] - 1.2, center[1] - 0.9, center[2] + 0.04]
        inventory_values["actor"] = core_name
        inventory_node = {"node_type": "scene_object", "name": f"{name}_loadout", "role": "interactive", "from": node.get("from"), "values": inventory_values}
        inventory_objects, inventory_relationships = _expand_inventory_loadout_macro(inventory_node)
        objects.extend(inventory_objects)
        relationships.extend(inventory_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_loadout_inventory_core", "contains", f"Actor {name} owns loadout."))

    return objects, relationships


def _expand_crowd_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "crowd")
    center = _macro_center(values)
    crowd_kind = _snake_id(values.get("crowd_type") or values.get("type") or values.get("role"), "ambient")
    count = max(1, min(96, _positive_int(values.get("agents") or values.get("npcs") or values.get("count"), default=6)))
    roles = _gameplay_name_list(values, ("roles", "actor_types", "npc_types"), default=_crowd_default_roles(crowd_kind))
    faction = _snake_id(values.get("faction") or _nested(values, "state", "faction"), "neutral")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_crowd_core"
    core_values = _macro_child_values(
        values,
        construct="crowd",
        position=center,
        scale=[
            max(1.2, _number(values.get("width"), default=max(4.0, count * 0.75))),
            max(1.2, _number(values.get("depth"), default=max(3.0, count * 0.50))),
            0.35,
        ],
        state={
            "crowd": name,
            "crowd_type": crowd_kind,
            "actor_count": count,
            "roles": roles,
            "faction": faction,
            "formation": _snake_id(values.get("formation") or values.get("layout"), "cluster"),
            "behavior_profile": _snake_id(values.get("behavior") or values.get("behavior_profile"), "ambient"),
            "object_archetype": "actor_group",
            "setpiece_layout": "crowd_cluster",
            "structure_count": 1,
            "prop_count": max(1, min(24, count)),
            "child_socket_count": 0,
        },
        tags=["crowd", crowd_kind, faction, "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "crowd", core_values, role="interactive", source=node.get("from")))

    columns = max(1, min(8, math.ceil(count**0.5)))
    rows = max(1, math.ceil(count / columns))
    spacing_x = max(0.7, _number(values.get("spacing_x") or values.get("spacing"), default=1.1))
    spacing_y = max(0.7, _number(values.get("spacing_y") or values.get("spacing"), default=1.1))
    for index in range(count):
        column = index % columns
        row = index // columns
        actor_values = deepcopy(values)
        actor_values["position"] = [
            center[0] + (column - (columns - 1) / 2.0) * spacing_x,
            center[1] + (row - (rows - 1) / 2.0) * spacing_y,
            center[2] + 0.06,
        ]
        actor_values["actor_type"] = roles[index % len(roles)]
        actor_values["faction"] = faction
        actor_values.setdefault("schedule", False)
        actor_values.setdefault("dialogue", False)
        actor_values.setdefault("inventory", False)
        actor_node = {"node_type": "scene_object", "name": f"{name}_actor_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": actor_values}
        actor_objects, actor_relationships = _expand_actor_macro(actor_node, construct="npc")
        objects.extend(actor_objects)
        relationships.extend(actor_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_actor_{index + 1:02d}_npc_core", "contains", f"Crowd {name} contains actor {index + 1}."))

    if not _any_disabled(values, "schedule", "routine"):
        schedule_values = deepcopy(values)
        schedule_values["position"] = [center[0], center[1] - spacing_y * (rows + 1), center[2] + 0.04]
        schedule_values["actor"] = core_name
        schedule_values.setdefault("activities", _crowd_default_activities(crowd_kind))
        schedule_node = {"node_type": "scene_object", "name": f"{name}_crowd_schedule", "role": "narrative_clue", "from": node.get("from"), "values": schedule_values}
        schedule_objects, schedule_relationships = _expand_schedule_macro(schedule_node)
        objects.extend(schedule_objects)
        relationships.extend(schedule_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_crowd_schedule_schedule_core", "depends_on", f"Crowd {name} follows a shared routine."))

    return objects, relationships


def _expand_schedule_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "schedule")
    center = _macro_center(values)
    activities = _gameplay_name_list(values, ("activities", "routine", "actions", "beats"), default=["idle", "work", "rest"])
    anchors = _gameplay_label_list(values, ("anchors", "locations", "places", "activity_locations"))
    if not anchors:
        anchors = activities
    time_windows = _string_list(values.get("times") or values.get("time_windows") or values.get("hours"))
    actor = _string(values.get("actor") or values.get("owner"), default="")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_schedule_core"
    core_values = _macro_child_values(
        values,
        construct="schedule",
        position=center,
        scale=[max(0.8, _number(values.get("width"), default=2.0)), max(0.6, _number(values.get("depth"), default=1.2)), 0.24],
        state={
            "schedule": name,
            "schedule_type": _snake_id(values.get("schedule_type") or values.get("type"), "routine"),
            "actor": actor,
            "activity_count": len(activities),
            "loop": not _disabled(values.get("loop", True)),
            "time_model": _snake_id(values.get("time_model") or values.get("clock"), "daily"),
            "duration_minutes": _number(values.get("duration") or values.get("duration_minutes"), default=1440.0),
            "infrastructure_type": "schedule_board",
            "prop_count": max(1, min(12, len(activities))),
        },
        tags=["schedule", "routine", "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "schedule", core_values, role="narrative_clue", source=node.get("from")))
    if actor:
        relationships.append(_macro_relationship(name, actor, core_name, "depends_on", f"Actor {actor} depends on schedule {name}."))

    previous_anchor = ""
    for index, activity in enumerate(activities):
        anchor_label = anchors[index % len(anchors)]
        anchor_name = f"{name}_{index + 1:02d}_{activity}_anchor"[:60].rstrip("_")
        anchor_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (len(activities) - 1) / 2.0) * 1.35, center[1] + 1.1, center[2] + 0.04],
            scale=[0.55, 0.55, 0.18],
            state={
                "schedule": name,
                "activity": activity,
                "location": anchor_label,
                "activity_index": index,
                "time_window": time_windows[index % len(time_windows)] if time_windows else "",
                "interaction_type": "start_activity",
            },
            tags=["schedule_activity", activity, anchor_label, "behavior", "macro_generated"],
        )
        anchor_values["affordances"] = {"start_activity": {"action": "start_activity", "requires": _string(values.get("requires"), default="")}}
        objects.append(_macro_scene_object(anchor_name, "interactable", anchor_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, anchor_name, "contains", f"Schedule {name} contains activity {activity}."))
        if previous_anchor:
            relationships.append(_macro_relationship(name, previous_anchor, anchor_name, "routes_to", f"Activity {previous_anchor} routes to {anchor_name}."))
        previous_anchor = anchor_name
    return objects, relationships


def _expand_patrol_route_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "patrol_route")
    center = _macro_center(values)
    labels = _gameplay_label_list(values, ("waypoint_names", "waypoint_labels", "points", "patrol_points"))
    if not labels and not isinstance(values.get("waypoints"), int | float):
        labels = _gameplay_label_list(values, ("waypoints",))
    waypoint_count = len(labels) if labels else max(2, min(32, _positive_int(values.get("waypoints") or values.get("waypoint_count"), default=4)))
    if not labels:
        labels = [f"waypoint_{index + 1:02d}" for index in range(waypoint_count)]
    actor = _string(values.get("actor") or values.get("owner"), default="")
    faction = _snake_id(values.get("faction") or _nested(values, "state", "faction"), "neutral")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_patrol_core"
    core_values = _macro_child_values(
        values,
        construct="patrol_route",
        position=center,
        scale=[max(2.0, _number(values.get("width") or values.get("route_width"), default=max(3.0, waypoint_count * 1.2))), max(0.8, _number(values.get("depth") or values.get("route_depth"), default=2.0)), 0.18],
        state={
            "patrol_route": name,
            "route_type": _snake_id(values.get("route_type") or values.get("patrol_type") or values.get("type"), "patrol"),
            "actor": actor,
            "faction": faction,
            "waypoint_count": waypoint_count,
            "loop": not _disabled(values.get("loop", True)),
            "speed": _number(values.get("speed") or values.get("movement_speed"), default=1.0),
            "detection_radius": _number(values.get("detection_radius") or values.get("awareness"), default=8.0),
            "road_segment_count": max(1, waypoint_count - 1),
            "branch_count": 0,
            "path_count": waypoint_count,
        },
        tags=["patrol_route", faction, "navigation", "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "patrol_route", core_values, role="navigation", source=node.get("from")))
    if actor:
        relationships.append(_macro_relationship(name, actor, core_name, "routes_to", f"Actor {actor} follows patrol route {name}."))

    waypoint_names: list[str] = []
    route_token = hashlib.sha256(name.encode("utf-8")).hexdigest()[:6]
    for index, label in enumerate(labels[:waypoint_count]):
        angle = (math.tau * index) / max(1, waypoint_count)
        waypoint_name = f"{name[:32].rstrip('_')}_{route_token}_wp{index + 1:02d}_{label}"[:60].rstrip("_")
        waypoint_names.append(waypoint_name)
        waypoint_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + math.cos(angle) * 2.2, center[1] + math.sin(angle) * 1.5, center[2] + 0.04],
            scale=[0.45, 0.45, 0.16],
            state={
                "patrol_route": name,
                "waypoint": label,
                "waypoint_index": index,
                "wait_seconds": _number(values.get("wait") or values.get("wait_seconds"), default=2.0),
                "interaction_type": "patrol_waypoint",
            },
            tags=["patrol_waypoint", label, faction, "behavior", "macro_generated"],
        )
        waypoint_values["affordances"] = {"arrive": {"action": "patrol_arrive"}}
        objects.append(_macro_scene_object(waypoint_name, "interactable", waypoint_values, role="navigation", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, waypoint_name, "routes_to", f"Patrol route {name} routes to waypoint {label}."))

    for index, waypoint_name in enumerate(waypoint_names):
        if index + 1 < len(waypoint_names):
            relationships.append(_macro_relationship(name, waypoint_name, waypoint_names[index + 1], "routes_to", f"Patrol waypoint {waypoint_name} routes onward."))
        elif not _disabled(values.get("loop", True)) and waypoint_names:
            relationships.append(_macro_relationship(name, waypoint_name, waypoint_names[0], "routes_to", f"Patrol route {name} loops to start."))
    return objects, relationships


def _expand_dialogue_tree_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "dialogue_tree")
    center = _macro_center(values)
    topics = _gameplay_name_list(values, ("topics", "nodes", "lines", "responses"), default=["greeting", "ask", "farewell"])
    speaker = _string(values.get("speaker") or values.get("actor") or values.get("npc"), default="")
    reveals = _string(values.get("reveals") or values.get("quest") or values.get("objective"), default="")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_dialogue_core"
    core_values = _macro_child_values(
        values,
        construct="dialogue_tree",
        position=center,
        scale=[max(0.8, _number(values.get("width"), default=1.8)), max(0.8, _number(values.get("depth"), default=1.2)), 0.25],
        state={
            "dialogue_tree": name,
            "speaker": speaker,
            "topic_count": len(topics),
            "conversation_type": _snake_id(values.get("conversation_type") or values.get("type"), "branching"),
            "tone": _snake_id(values.get("tone") or values.get("mood"), "neutral"),
            "reveals": reveals,
            "infrastructure_type": "dialogue_terminal",
            "prop_count": max(1, min(12, len(topics))),
        },
        tags=["dialogue_tree", "conversation", "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "dialogue_tree", core_values, role="narrative_clue", source=node.get("from")))
    if speaker:
        relationships.append(_macro_relationship(name, speaker, core_name, "reveals", f"Speaker {speaker} exposes dialogue tree {name}."))
    if reveals:
        relationships.append(_macro_relationship(name, core_name, reveals, "reveals", f"Dialogue tree {name} can reveal {reveals}."))

    for index, topic in enumerate(topics):
        topic_name = f"{name}_{index + 1:02d}_{topic}_reply"[:60].rstrip("_")
        topic_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (len(topics) - 1) / 2.0) * 1.05, center[1] + 1.0, center[2] + 0.04],
            scale=[0.5, 0.5, 0.16],
            state={
                "dialogue_tree": name,
                "topic": topic,
                "topic_index": index,
                "speaker": speaker,
                "interaction_type": "choose_dialogue",
            },
            tags=["dialogue_topic", topic, "conversation", "macro_generated"],
        )
        affordance: dict[str, Any] = {"action": "choose_dialogue"}
        if reveals:
            affordance["reveals"] = reveals
        if values.get("requires"):
            affordance["requires"] = _string(values.get("requires"))
        topic_values["affordances"] = {"choose": affordance}
        objects.append(_macro_scene_object(topic_name, "interactable", topic_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, topic_name, "contains", f"Dialogue tree {name} contains topic {topic}."))
    return objects, relationships


def _expand_inventory_loadout_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "inventory_loadout")
    center = _macro_center(values)
    items = _gameplay_name_list(values, ("items", "equipment", "loadout", "gear"), default=["utility_item"])
    actor = _string(values.get("actor") or values.get("owner"), default="")
    inventory_kind = _snake_id(values.get("inventory_type") or values.get("loadout_type") or values.get("type"), "personal")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_inventory_core"
    core_values = _macro_child_values(
        values,
        construct="inventory_loadout",
        position=center,
        scale=[max(0.8, _number(values.get("width"), default=1.4)), max(0.6, _number(values.get("depth"), default=1.0)), 0.22],
        state={
            "inventory_loadout": name,
            "inventory_type": inventory_kind,
            "actor": actor,
            "item_count": len(items),
            "capacity": max(len(items), _positive_int(values.get("capacity") or values.get("slots"), default=len(items))),
            "currency": _positive_int(values.get("currency") or values.get("credits"), default=0),
            "tradeable": not _disabled(values.get("tradeable", False)),
            "infrastructure_type": "inventory_cache",
            "prop_count": max(1, min(24, len(items))),
        },
        tags=["inventory_loadout", inventory_kind, "loadout", "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "inventory_loadout", core_values, role="interactive", source=node.get("from")))
    if actor:
        relationships.append(_macro_relationship(name, actor, core_name, "contains", f"Actor {actor} owns inventory {name}."))

    for index, item in enumerate(items):
        item_name = f"{name}_{index + 1:02d}_{item}"[:60].rstrip("_")
        item_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (len(items) - 1) / 2.0) * 0.85, center[1] + 0.9, center[2] + 0.04],
            scale=[0.42, 0.42, 0.16],
            state={
                "inventory_loadout": name,
                "item": item,
                "slot": index,
                "quantity": _positive_int(values.get("quantity") or values.get("stack"), default=1),
                "equipped": index == 0 and not _disabled(values.get("equip_first", True)),
                "interaction_type": _snake_id(values.get("item_action") or ("trade" if not _disabled(values.get("tradeable", False)) else "equip"), "equip"),
            },
            tags=["inventory_item", item, inventory_kind, "macro_generated"],
        )
        item_values["affordances"] = {"use_item": {"action": _snake_id(values.get("item_action") or "use_item", "use_item")}}
        objects.append(_macro_scene_object(item_name, "interactable", item_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, item_name, "contains", f"Inventory {name} contains item {item}."))
    return objects, relationships


def _expand_spawn_ecology_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "spawn_ecology")
    center = _macro_center(values)
    ecology_kind = _snake_id(values.get("ecology_type") or values.get("habitat") or values.get("type"), "ambient")
    species = _gameplay_name_list(values, ("species", "actors", "npc_types", "creatures"), default=["wildlife"])
    nest_count = max(1, min(32, _positive_int(values.get("nests") or values.get("spawn_points") or values.get("spawn_count"), default=len(species))))
    population = max(1, min(32, _positive_int(values.get("population") or values.get("population_per_nest"), default=3)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_ecology_core"
    core_values = _macro_child_values(
        values,
        construct="spawn_ecology",
        position=center,
        scale=[max(3.0, _number(values.get("width"), default=10.0)), max(3.0, _number(values.get("depth"), default=8.0)), 0.28],
        state={
            "spawn_ecology": name,
            "ecology_type": ecology_kind,
            "species": species,
            "species_count": len(species),
            "spawn_point_count": nest_count,
            "population_per_spawn": population,
            "respawn_seconds": _number(values.get("respawn") or values.get("respawn_seconds"), default=90.0),
            "time_window": _snake_id(values.get("time_window") or values.get("day_phase"), "any"),
            "object_archetype": "ecology",
            "setpiece_layout": "spawn_ecology",
            "structure_count": 1,
            "foliage_cluster_count": max(1, min(8, len(species))),
            "prop_count": max(1, min(24, nest_count)),
        },
        tags=["spawn_ecology", ecology_kind, "ecology", "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "spawn_ecology", core_values, role="environment_structure", source=node.get("from")))

    if not _any_disabled(values, "habitat", "terrain"):
        habitat_values = _macro_child_values(
            values,
            construct="terrain",
            position=[center[0], center[1], center[2] - 0.05],
            scale=[max(3.0, _number(values.get("width"), default=10.0)), max(3.0, _number(values.get("depth"), default=8.0)), 0.08],
            state={"spawn_ecology": name, "landform": ecology_kind, "foliage_cluster_count": max(1, len(species)), "clearing_count": nest_count},
            tags=["spawn_habitat", ecology_kind, "terrain", "macro_generated"],
        )
        objects.append(_macro_scene_object(f"{name}_habitat", "terrain", habitat_values, role="environment_structure", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, f"{name}_habitat", "contains", f"Spawn ecology {name} contains habitat."))

    for index in range(nest_count):
        actor_type = species[index % len(species)]
        encounter_values = deepcopy(values)
        angle = math.tau * index / max(1, nest_count)
        encounter_values["position"] = [center[0] + math.cos(angle) * 3.0, center[1] + math.sin(angle) * 2.4, center[2] + 0.04]
        encounter_values["encounter_type"] = "spawn"
        encounter_values["actor_types"] = [actor_type]
        encounter_values["spawns"] = population
        encounter_values["cover"] = 1
        encounter_values["loot"] = False
        encounter_values["patrols"] = False
        encounter_node = {"node_type": "scene_object", "name": f"{name}_{actor_type}_spawn_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": encounter_values}
        encounter_objects, encounter_relationships = _expand_encounter_macro(encounter_node)
        objects.extend(encounter_objects)
        relationships.extend(encounter_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{actor_type}_spawn_{index + 1:02d}_encounter_core", "contains", f"Ecology {name} contains {actor_type} spawn."))
    return objects, relationships


_ECOLOGY_CORE_SUFFIXES = {
    "biome_system": "biome_system_core",
    "habitat_zone": "habitat_zone_core",
    "species_population": "species_population_core",
    "food_web": "food_web_core",
    "predator_prey_link": "predator_prey_link_core",
    "migration_route": "migration_route_core",
    "nesting_site": "nesting_site_core",
    "resource_patch": "resource_patch_core",
    "resource_regeneration": "resource_regeneration_core",
    "growth_cycle": "growth_cycle_core",
    "weather_ecology_link": "weather_ecology_link_core",
    "ecological_pressure": "ecological_pressure_core",
}

_ECOLOGY_ROLES = {
    "biome_system": "environment_structure",
    "habitat_zone": "environment_structure",
    "species_population": "interactive",
    "food_web": "environment_structure",
    "predator_prey_link": "narrative_clue",
    "migration_route": "navigation",
    "nesting_site": "environment_structure",
    "resource_patch": "environment_structure",
    "resource_regeneration": "environment_structure",
    "growth_cycle": "narrative_clue",
    "weather_ecology_link": "environment_structure",
    "ecological_pressure": "environment_structure",
}

_ECOLOGY_KIND_KEYS = {
    "biome_system": ("biome_type", "ecology_type", "biome", "type"),
    "habitat_zone": ("habitat", "habitat_type", "zone_type", "type"),
    "species_population": ("species_type", "species", "creature", "type"),
    "food_web": ("web_type", "ecology_type", "type"),
    "predator_prey_link": ("link_type", "interaction_type", "type"),
    "migration_route": ("route_type", "migration_type", "type"),
    "nesting_site": ("nest_type", "site_type", "type"),
    "resource_patch": ("resource_type", "resource", "type"),
    "resource_regeneration": ("resource_type", "resource", "type"),
    "growth_cycle": ("cycle_type", "season", "type"),
    "weather_ecology_link": ("weather_type", "weather", "type"),
    "ecological_pressure": ("pressure_type", "pressure", "type"),
}

_ECOLOGY_KIND_DEFAULTS = {
    "biome_system": "temperate",
    "habitat_zone": "habitat",
    "species_population": "wildlife",
    "food_web": "balanced",
    "predator_prey_link": "predation",
    "migration_route": "seasonal",
    "nesting_site": "nest",
    "resource_patch": "forage",
    "resource_regeneration": "renewable",
    "growth_cycle": "seasonal",
    "weather_ecology_link": "rain",
    "ecological_pressure": "scarcity",
}

_ECOLOGY_ACTIONS = {
    "biome_system": "simulate_biome_system",
    "habitat_zone": "sample_habitat_zone",
    "species_population": "simulate_species_population",
    "food_web": "solve_food_web",
    "predator_prey_link": "evaluate_predator_prey_link",
    "migration_route": "advance_migration_route",
    "nesting_site": "spawn_from_nesting_site",
    "resource_patch": "sample_resource_patch",
    "resource_regeneration": "regenerate_resource_patch",
    "growth_cycle": "advance_growth_cycle",
    "weather_ecology_link": "apply_weather_ecology_link",
    "ecological_pressure": "sample_ecological_pressure",
}


def _ecology_kind(values: Mapping[str, Any], construct: str) -> str:
    return _surface_marker_value(values, *_ECOLOGY_KIND_KEYS.get(construct, ("type",)), fallback=_ECOLOGY_KIND_DEFAULTS.get(construct, construct))


def _ecology_core_name(name: str, construct: str) -> str:
    return f"{name}_{_ECOLOGY_CORE_SUFFIXES.get(construct, 'ecology_core')}"


def _ecology_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "biome_system":
        return [max(3.0, _number(values.get("width"), default=5.5)), max(2.0, _number(values.get("depth"), default=4.0)), 0.24]
    if construct == "habitat_zone":
        return [max(1.2, _number(values.get("width"), default=2.4)), max(1.0, _number(values.get("depth"), default=1.8)), 0.14]
    if construct == "migration_route":
        return [max(1.8, _number(values.get("length") or values.get("width"), default=3.6)), 0.18, 0.10]
    if construct in {"food_web", "ecological_pressure"}:
        return [1.25, 0.85, 0.16]
    if construct in {"species_population", "nesting_site", "resource_patch"}:
        return [0.74, 0.52, 0.16]
    return [0.44, 0.28, 0.12]


def _ecology_species(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("species", "fauna", "creatures", "actors", "populations"), default=["grazer", "predator", "pollinator"])


def _ecology_habitats(values: Mapping[str, Any], biome_kind: str) -> list[str]:
    authored = _gameplay_name_list(values, ("habitats", "habitat_zones", "zones", "landforms"), default=[])
    if authored:
        return authored[:16]
    presets = {
        "alpine": ["ridge", "scree", "snowmelt"],
        "coastal": ["dune", "tidal_flat", "salt_marsh"],
        "desert": ["dune", "oasis", "rock_shelf"],
        "forest": ["canopy", "understory", "clearing"],
        "jungle": ["canopy", "wet_floor", "riverbank"],
        "swamp": ["marsh", "bog", "waterline"],
        "temperate": ["woodland", "meadow", "stream"],
        "tundra": ["lichen_field", "ice_edge", "wind_scour"],
        "volcanic": ["ash_field", "lava_edge", "warm_spring"],
    }
    return presets.get(biome_kind, ["shelter", "forage", "waterline"])


def _ecology_resources(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("resources", "resource_patches", "food_sources", "flora"), default=["water", "forage", "shelter"])


def _ecology_predators(values: Mapping[str, Any]) -> list[str]:
    species = _ecology_species(values)
    return _gameplay_name_list(values, ("predators", "hunters"), default=[species[-1] if species else "predator"])


def _ecology_prey(values: Mapping[str, Any]) -> list[str]:
    species = _ecology_species(values)
    default = species[:-1] if len(species) > 1 else ["prey"]
    return _gameplay_name_list(values, ("prey", "prey_species", "grazers"), default=default)


def _ecology_growth_stages(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("growth_stages", "stages", "cycle_stages"), default=["seed", "growth", "fruit", "dormant"])


def _ecology_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    state: dict[str, Any] = {
        construct: name,
        "ecology_construct": construct,
        "ecology_kind": kind,
        "action": _snake_id(values.get("action") or _ECOLOGY_ACTIONS.get(construct), "simulate_ecology"),
        f"{construct}_count": 1,
        "ecology_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "living_biome_system",
        "enabled": not _disabled(values.get("enabled", True)),
        "stability": _number(values.get("stability"), default=0.65),
        "biodiversity": _number(values.get("biodiversity"), default=0.55),
        "pressure": _number(values.get("pressure"), default=0.25),
    }
    if construct == "biome_system":
        habitats = _ecology_habitats(values, kind)
        species = _ecology_species(values)
        resources = _ecology_resources(values)
        state.update(
            {
                "biome_type": kind,
                "habitats": habitats,
                "species": species,
                "resources": resources,
                "habitat_zone_count": len(habitats),
                "species_population_count": len(species),
                "food_web_count": 1,
                "predator_prey_link_count": max(1, len(_ecology_predators(values)) * max(1, len(_ecology_prey(values)))),
                "migration_route_count": max(1, min(len(habitats), len(species))),
                "nesting_site_count": len(species),
                "resource_patch_count": len(resources),
                "resource_regeneration_count": len(resources),
                "growth_cycle_count": len(resources),
                "weather_ecology_link_count": 1,
                "ecological_pressure_count": 1,
                "spawn_ecology_count": 1,
            }
        )
    elif construct == "habitat_zone":
        species = _ecology_species(values)
        resources = _ecology_resources(values)
        state.update(
            {
                "habitat": kind,
                "species": species,
                "resources": resources,
                "species_count": len(species),
                "resource_patch_count": len(resources),
                "nesting_site_count": max(1, min(8, len(species))),
                "migration_route_count": 1,
                "coverage": _number(values.get("coverage"), default=0.75),
                "carrying_capacity": _positive_int(values.get("carrying_capacity") or values.get("capacity"), default=120),
            }
        )
    elif construct == "species_population":
        prey = _ecology_prey(values)
        state.update(
            {
                "species_type": kind,
                "species": kind,
                "population": _positive_int(values.get("population") or values.get("count"), default=32),
                "carrying_capacity": _positive_int(values.get("carrying_capacity") or values.get("capacity"), default=96),
                "birth_rate": _number(values.get("birth_rate"), default=0.12),
                "mortality_rate": _number(values.get("mortality_rate"), default=0.05),
                "diet": _surface_marker_value(values, "diet", fallback="omnivore"),
                "prey": prey,
                "predator_prey_link_count": len(prey),
                "nesting_site_count": 1,
                "migration_route_count": 1,
                "growth_cycle_count": 1,
            }
        )
    elif construct == "food_web":
        predators = _ecology_predators(values)
        prey = _ecology_prey(values)
        producers = _gameplay_name_list(values, ("producers", "flora"), default=["grass", "fungus"])
        state.update({"web_type": kind, "predators": predators, "prey": prey, "producers": producers, "predator_count": len(predators), "prey_count": len(prey), "producer_count": len(producers), "food_web_link_count": max(1, len(predators) * max(1, len(prey)))})
    elif construct == "predator_prey_link":
        state.update({"link_type": kind, "predator": _surface_marker_value(values, "predator", fallback=_ecology_predators(values)[0]), "prey": _surface_marker_value(values, "prey", fallback=_ecology_prey(values)[0]), "predation_pressure": _number(values.get("predation_pressure") or values.get("intensity"), default=0.45), "world_metric_count": 1})
    elif construct == "migration_route":
        state.update({"migration_type": kind, "route_count": 1, "waypoint_count": max(2, min(32, _positive_int(values.get("waypoints") or values.get("waypoint_count"), default=4))), "migration_season": _surface_marker_value(values, "migration_season", "season", fallback="seasonal"), "from_habitat": _surface_marker_value(values, "from_habitat", "start", fallback="source_habitat"), "to_habitat": _surface_marker_value(values, "to_habitat", "end", fallback="target_habitat")})
    elif construct == "nesting_site":
        state.update({"nest_type": kind, "species": _surface_marker_value(values, "species", fallback=kind), "nest_count": 1, "capacity": _positive_int(values.get("capacity") or values.get("population"), default=12), "spawn_point_count": _positive_int(values.get("spawn_points"), default=1), "respawn_seconds": _number(values.get("respawn") or values.get("respawn_seconds"), default=120.0)})
    elif construct == "resource_patch":
        state.update({"resource_type": kind, "quantity": _number(values.get("quantity"), default=1.0), "richness": _number(values.get("richness"), default=0.65), "resource_patch_count": 1, "resource_regeneration_count": 1, "resource_flow_count": 1})
    elif construct == "resource_regeneration":
        state.update({"resource_type": kind, "regeneration_rate": _number(values.get("regeneration_rate") or values.get("rate"), default=0.08), "interval_seconds": _number(values.get("interval_seconds") or values.get("interval"), default=30.0), "resource_regeneration_count": 1, "growth_cycle_count": 1, "world_metric_count": 1})
    elif construct == "growth_cycle":
        stages = _ecology_growth_stages(values)
        state.update({"cycle_type": kind, "growth_stages": stages, "stage_count": len(stages), "cycle_duration": _number(values.get("cycle_duration") or values.get("duration"), default=360.0), "season": _surface_marker_value(values, "season", fallback=kind), "world_metric_count": 1})
    elif construct == "weather_ecology_link":
        state.update({"weather_type": kind, "affects": _gameplay_name_list(values, ("affects", "targets", "species"), default=["growth", "migration"]), "weather_sensitivity": _number(values.get("weather_sensitivity") or values.get("sensitivity"), default=0.5), "modifier": _number(values.get("modifier"), default=1.0), "weather_system_count": 1, "world_metric_count": 1})
    elif construct == "ecological_pressure":
        sources = _gameplay_name_list(values, ("pressure_sources", "sources", "causes"), default=[kind])
        targets = _gameplay_name_list(values, ("targets", "species", "habitats"), default=["habitat"])
        state.update({"pressure_type": kind, "pressure_sources": sources, "targets": targets, "intensity": _number(values.get("intensity") or values.get("pressure"), default=0.5), "hazard_field_count": 1, "world_metric_count": 1})
    return state


def _ecology_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _ECOLOGY_ACTIONS.get(construct), "simulate_ecology")}
    target = _surface_marker_value(values, "target", "species", "habitat", "resource", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _expand_ecology_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _ecology_kind(values, construct)
    core_name = _ecology_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_ecology_scale(values, construct),
        state=_ecology_state(values, construct, name, kind),
        tags=[construct, kind, "ecology", "biome", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_ECOLOGY_ACTIONS.get(construct), "simulate_ecology"): _ecology_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_ECOLOGY_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    if construct == "biome_system":
        habitats = _ecology_habitats(values, kind)[:16]
        species = _ecology_species(values)[:24]
        resources = _ecology_resources(values)[:16]
        for index, habitat in enumerate(habitats):
            child_values = deepcopy(values)
            child_values["habitat"] = habitat
            child_values["position"] = [center[0] + (index - (len(habitats) - 1) / 2.0) * 0.86, center[1] + 1.15, center[2] + 0.04]
            child_node = {"node_type": "scene_object", "name": f"{name}_{habitat}_habitat", "role": "environment_structure", "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_ecology_macro(child_node, construct="habitat_zone")
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_{habitat}_habitat", "habitat_zone"), "contains", f"Biome {name} contains habitat {habitat}."))

        for index, species_name in enumerate(species):
            species_values = deepcopy(values)
            species_values["species_type"] = species_name
            species_values["species"] = species_name
            species_values["habitat"] = habitats[index % len(habitats)] if habitats else kind
            species_values["position"] = [center[0] + (index - (len(species) - 1) / 2.0) * 0.52, center[1], center[2] + 0.06]
            species_node = {"node_type": "scene_object", "name": f"{name}_{species_name}_population", "role": "interactive", "from": node.get("from"), "values": species_values}
            species_objects, species_relationships = _expand_ecology_macro(species_node, construct="species_population")
            objects.extend(species_objects)
            relationships.extend(species_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_{species_name}_population", "species_population"), "contains", f"Biome {name} contains species population {species_name}."))

        if not _any_disabled(values, "food_web", "web"):
            web_values = deepcopy(values)
            web_values["position"] = [center[0], center[1] - 1.05, center[2] + 0.04]
            web_node = {"node_type": "scene_object", "name": f"{name}_food_web", "role": "environment_structure", "from": node.get("from"), "values": web_values}
            web_objects, web_relationships = _expand_ecology_macro(web_node, construct="food_web")
            objects.extend(web_objects)
            relationships.extend(web_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_food_web", "food_web"), "contains", f"Biome {name} contains a food web."))

        for index, resource in enumerate(resources):
            patch_values = deepcopy(values)
            patch_values["resource_type"] = resource
            patch_values["position"] = [center[0] + (index - (len(resources) - 1) / 2.0) * 0.64, center[1] - 1.82, center[2] + 0.04]
            patch_node = {"node_type": "scene_object", "name": f"{name}_{resource}_patch", "role": "environment_structure", "from": node.get("from"), "values": patch_values}
            patch_objects, patch_relationships = _expand_ecology_macro(patch_node, construct="resource_patch")
            objects.extend(patch_objects)
            relationships.extend(patch_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_{resource}_patch", "resource_patch"), "supports", f"Biome {name} regenerates resource {resource}."))

        for child_construct, child_name, x_offset in (("weather_ecology_link", f"{name}_weather_link", -1.1), ("ecological_pressure", f"{name}_pressure", 1.1)):
            if _any_disabled(values, child_construct, child_construct.removeprefix("ecological_")):
                continue
            child_values = deepcopy(values)
            child_values["position"] = [center[0] + x_offset, center[1] - 2.45, center[2] + 0.04]
            child_node = {"node_type": "scene_object", "name": child_name, "role": _ECOLOGY_ROLES[child_construct], "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_ecology_macro(child_node, construct=child_construct)
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(child_name, child_construct), "supports", f"Biome {name} includes {child_construct}."))

    elif construct == "habitat_zone":
        resources = _ecology_resources(values)[:12]
        species = _ecology_species(values)[:12]
        for index, resource in enumerate(resources):
            patch_values = deepcopy(values)
            patch_values["resource_type"] = resource
            patch_values["position"] = [center[0] + (index - (len(resources) - 1) / 2.0) * 0.42, center[1] + 0.62, center[2] + 0.04]
            patch_node = {"node_type": "scene_object", "name": f"{name}_{resource}_patch", "role": "environment_structure", "from": node.get("from"), "values": patch_values}
            patch_objects, patch_relationships = _expand_ecology_macro(patch_node, construct="resource_patch")
            objects.extend(patch_objects)
            relationships.extend(patch_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_{resource}_patch", "resource_patch"), "contains", f"Habitat {name} contains resource patch {resource}."))
        for index, species_name in enumerate(species[:8]):
            nest_values = deepcopy(values)
            nest_values["species"] = species_name
            nest_values["position"] = [center[0] + (index - (min(len(species), 8) - 1) / 2.0) * 0.42, center[1] - 0.62, center[2] + 0.04]
            nest_node = {"node_type": "scene_object", "name": f"{name}_{species_name}_nest", "role": "environment_structure", "from": node.get("from"), "values": nest_values}
            nest_objects, nest_relationships = _expand_ecology_macro(nest_node, construct="nesting_site")
            objects.extend(nest_objects)
            relationships.extend(nest_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_{species_name}_nest", "nesting_site"), "contains", f"Habitat {name} contains nesting site for {species_name}."))
        if not _any_disabled(values, "migration_route", "migration"):
            route_values = deepcopy(values)
            route_values["position"] = [center[0], center[1], center[2] + 0.08]
            route_node = {"node_type": "scene_object", "name": f"{name}_migration", "role": "navigation", "from": node.get("from"), "values": route_values}
            route_objects, route_relationships = _expand_ecology_macro(route_node, construct="migration_route")
            objects.extend(route_objects)
            relationships.extend(route_relationships)
            relationships.append(_macro_relationship(name, _ecology_core_name(f"{name}_migration", "migration_route"), core_name, "routes_to", f"Migration route crosses habitat {name}."))

    elif construct == "species_population":
        for child_construct, suffix, x_offset in (("growth_cycle", "growth", -0.48), ("nesting_site", "nest", 0.0), ("migration_route", "migration", 0.48)):
            if _any_disabled(values, child_construct, suffix):
                continue
            child_values = deepcopy(values)
            child_values["position"] = [center[0] + x_offset, center[1] + 0.54, center[2] + 0.04]
            child_node = {"node_type": "scene_object", "name": f"{name}_{suffix}", "role": _ECOLOGY_ROLES[child_construct], "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_ecology_macro(child_node, construct=child_construct)
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_{suffix}", child_construct), "supports", f"Species population {name} uses {child_construct}."))

    elif construct == "food_web":
        predators = _ecology_predators(values)[:12]
        prey = _ecology_prey(values)[:12]
        link_index = 0
        for predator in predators:
            for prey_name in prey:
                link_index += 1
                link_values = deepcopy(values)
                link_values["predator"] = predator
                link_values["prey"] = prey_name
                link_values["position"] = [center[0] + (link_index - (len(predators) * len(prey) + 1) / 2.0) * 0.36, center[1] + 0.55, center[2] + 0.04]
                link_node = {"node_type": "scene_object", "name": f"{name}_{predator}_{prey_name}_link", "role": "narrative_clue", "from": node.get("from"), "values": link_values}
                link_objects, link_relationships = _expand_ecology_macro(link_node, construct="predator_prey_link")
                objects.extend(link_objects)
                relationships.extend(link_relationships)
                relationships.append(_macro_relationship(name, core_name, _ecology_core_name(f"{name}_{predator}_{prey_name}_link", "predator_prey_link"), "contains", f"Food web {name} links {predator} to {prey_name}."))

    elif construct == "predator_prey_link" and not _any_disabled(values, "world_metric", "metric"):
        metric_values = deepcopy(values)
        metric_values["metric"] = "predation_pressure"
        metric_values["metric_value"] = values.get("predation_pressure") or values.get("intensity")
        metric_values["position"] = [center[0], center[1] + 0.42, center[2] + 0.04]
        metric_node = {"node_type": "scene_object", "name": f"{name}_pressure_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
        metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
        objects.extend(metric_objects)
        relationships.extend(metric_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_pressure_metric", "world_metric"), "reveals", f"Predator prey link {name} exposes predation pressure."))

    elif construct == "migration_route":
        waypoint_count = max(2, min(32, _positive_int(values.get("waypoints") or values.get("waypoint_count"), default=4)))
        length = max(1.0, _number(values.get("length") or values.get("width"), default=3.6))
        previous = ""
        for index in range(waypoint_count):
            waypoint_name = f"{name}_waypoint_{index + 1:02d}"
            waypoint_values = _macro_child_values(
                values,
                construct="route",
                position=[center[0] + (index - (waypoint_count - 1) / 2.0) * length / max(1, waypoint_count - 1), center[1], center[2] + 0.04],
                scale=[0.16, 0.16, 0.08],
                state={"migration_route": name, "waypoint_index": index + 1, "waypoint_count": waypoint_count},
                tags=["migration_waypoint", kind, "ecology", "macro_generated"],
            )
            objects.append(_macro_scene_object(waypoint_name, "route", waypoint_values, role="navigation", source=node.get("from")))
            relationships.append(_macro_relationship(name, core_name, waypoint_name, "contains", f"Migration route {name} contains waypoint {index + 1}."))
            if previous:
                relationships.append(_macro_relationship(name, previous, waypoint_name, "routes_to", f"Migration route {name} advances to waypoint {index + 1}."))
            previous = waypoint_name

    elif construct == "nesting_site" and not _any_disabled(values, "spawn_ecology", "spawns"):
        spawn_values = deepcopy(values)
        spawn_values["species"] = [_surface_marker_value(values, "species", fallback=kind)]
        spawn_values["spawn_points"] = _positive_int(values.get("spawn_points"), default=1)
        spawn_values["position"] = [center[0], center[1] + 0.48, center[2] + 0.04]
        spawn_node = {"node_type": "scene_object", "name": f"{name}_spawns", "role": "interactive", "from": node.get("from"), "values": spawn_values}
        spawn_objects, spawn_relationships = _expand_spawn_ecology_macro(spawn_node)
        objects.extend(spawn_objects)
        relationships.extend(spawn_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_spawns_ecology_core", "supports", f"Nesting site {name} feeds spawn ecology."))

    elif construct == "resource_patch":
        if not _any_disabled(values, "resource_regeneration", "regeneration"):
            regen_values = deepcopy(values)
            regen_values["resource_type"] = kind
            regen_values["position"] = [center[0] - 0.32, center[1] + 0.46, center[2] + 0.04]
            regen_node = {"node_type": "scene_object", "name": f"{name}_regeneration", "role": "environment_structure", "from": node.get("from"), "values": regen_values}
            regen_objects, regen_relationships = _expand_ecology_macro(regen_node, construct="resource_regeneration")
            objects.extend(regen_objects)
            relationships.extend(regen_relationships)
            relationships.append(_macro_relationship(name, _ecology_core_name(f"{name}_regeneration", "resource_regeneration"), core_name, "supports", f"Resource patch {name} regenerates over time."))
        if not _any_disabled(values, "resource_flow", "flow"):
            flow_values = deepcopy(values)
            flow_values["resource_type"] = kind
            flow_values["position"] = [center[0] + 0.32, center[1] + 0.46, center[2] + 0.04]
            flow_node = {"node_type": "scene_object", "name": f"{name}_flow", "role": "environment_structure", "from": node.get("from"), "values": flow_values}
            flow_objects, flow_relationships = _expand_simulation_macro(flow_node, construct="resource_flow")
            objects.extend(flow_objects)
            relationships.extend(flow_relationships)
            relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_flow", "resource_flow"), "routes_to", f"Resource patch {name} feeds resource flow."))

    elif construct == "resource_regeneration":
        if not _any_disabled(values, "growth_cycle", "cycle"):
            growth_values = deepcopy(values)
            growth_values["position"] = [center[0] - 0.32, center[1] + 0.42, center[2] + 0.04]
            growth_node = {"node_type": "scene_object", "name": f"{name}_growth", "role": "narrative_clue", "from": node.get("from"), "values": growth_values}
            growth_objects, growth_relationships = _expand_ecology_macro(growth_node, construct="growth_cycle")
            objects.extend(growth_objects)
            relationships.extend(growth_relationships)
            relationships.append(_macro_relationship(name, _ecology_core_name(f"{name}_growth", "growth_cycle"), core_name, "supports", f"Growth cycle drives regeneration {name}."))
        if not _any_disabled(values, "world_metric", "metric"):
            metric_values = deepcopy(values)
            metric_values["metric"] = "regeneration_rate"
            metric_values["metric_value"] = values.get("regeneration_rate") or values.get("rate")
            metric_values["position"] = [center[0] + 0.32, center[1] + 0.42, center[2] + 0.04]
            metric_node = {"node_type": "scene_object", "name": f"{name}_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
            metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
            objects.extend(metric_objects)
            relationships.extend(metric_relationships)
            relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_metric", "world_metric"), "reveals", f"Resource regeneration {name} exposes a metric."))

    elif construct == "growth_cycle" and not _any_disabled(values, "world_metric", "metric"):
        metric_values = deepcopy(values)
        metric_values["metric"] = "growth_stage"
        metric_values["metric_value"] = values.get("stage_index") or 0.0
        metric_values["position"] = [center[0], center[1] + 0.38, center[2] + 0.04]
        metric_node = {"node_type": "scene_object", "name": f"{name}_stage_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
        metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
        objects.extend(metric_objects)
        relationships.extend(metric_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_stage_metric", "world_metric"), "reveals", f"Growth cycle {name} exposes stage metric."))

    elif construct == "weather_ecology_link":
        if not _any_disabled(values, "weather_system", "weather"):
            weather_values = deepcopy(values)
            weather_values["weather_type"] = kind
            weather_values["position"] = [center[0] - 0.36, center[1] + 0.42, center[2] + 0.04]
            weather_node = {"node_type": "scene_object", "name": f"{name}_weather", "role": "environment_structure", "from": node.get("from"), "values": weather_values}
            weather_objects, weather_relationships = _expand_weather_system_macro(weather_node)
            objects.extend(weather_objects)
            relationships.extend(weather_relationships)
            relationships.append(_macro_relationship(name, f"{name}_weather_weather_core", core_name, "supports", f"Weather system drives ecology link {name}."))
        metric_values = deepcopy(values)
        metric_values["metric"] = "weather_sensitivity"
        metric_values["metric_value"] = values.get("weather_sensitivity") or values.get("sensitivity")
        metric_values["position"] = [center[0] + 0.36, center[1] + 0.42, center[2] + 0.04]
        metric_node = {"node_type": "scene_object", "name": f"{name}_sensitivity_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
        metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
        objects.extend(metric_objects)
        relationships.extend(metric_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_sensitivity_metric", "world_metric"), "reveals", f"Weather ecology link {name} exposes sensitivity."))

    elif construct == "ecological_pressure":
        hazard_values = deepcopy(values)
        hazard_values["hazard_type"] = kind
        hazard_values["position"] = [center[0] - 0.36, center[1] + 0.42, center[2] + 0.04]
        hazard_node = {"node_type": "scene_object", "name": f"{name}_hazard", "role": "environment_structure", "from": node.get("from"), "values": hazard_values}
        hazard_objects, hazard_relationships = _expand_simulation_macro(hazard_node, construct="hazard_field")
        objects.extend(hazard_objects)
        relationships.extend(hazard_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_hazard", "hazard_field"), "reveals", f"Ecological pressure {name} creates a hazard field."))
        metric_values = deepcopy(values)
        metric_values["metric"] = "ecological_pressure"
        metric_values["metric_value"] = values.get("intensity") or values.get("pressure")
        metric_values["position"] = [center[0] + 0.36, center[1] + 0.42, center[2] + 0.04]
        metric_node = {"node_type": "scene_object", "name": f"{name}_pressure_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
        metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
        objects.extend(metric_objects)
        relationships.extend(metric_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_pressure_metric", "world_metric"), "reveals", f"Ecological pressure {name} exposes pressure metric."))

    return objects, relationships


