def _logistics_kind(values: Mapping[str, Any], construct: str) -> str:
    return _surface_marker_value(values, *_LOGISTICS_KIND_KEYS.get(construct, ("type",)), fallback=_LOGISTICS_KIND_DEFAULTS.get(construct, construct))


def _logistics_core_name(name: str, construct: str) -> str:
    return f"{name}_{_LOGISTICS_CORE_SUFFIXES.get(construct, 'logistics_core')}"


def _logistics_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "supply_chain":
        return [max(2.8, _number(values.get("width"), default=5.4)), max(1.8, _number(values.get("depth"), default=3.2)), 0.22]
    if construct in {"logistics_hub", "storage_depot", "market_node"}:
        return [1.0, 0.66, 0.18]
    if construct in {"supply_route", "transport_leg"}:
        return [max(1.6, _number(values.get("length") or values.get("width"), default=3.2)), 0.16, 0.10]
    if construct in {"processing_stage", "refinery_stage", "workshop_stage", "assembly_stage"}:
        return [0.72, 0.44, 0.20]
    return [0.42, 0.26, 0.12]


def _logistics_goods(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("goods", "resources", "items", "products"), default=["ore", "wood", "food"])


def _logistics_inputs(values: Mapping[str, Any], kind: str) -> list[str]:
    return _gameplay_name_list(values, ("inputs", "input_goods", "raw_materials"), default=[kind])


def _logistics_outputs(values: Mapping[str, Any], kind: str) -> list[str]:
    return _gameplay_name_list(values, ("outputs", "output_goods", "products"), default=[f"processed_{kind}"])


def _logistics_stages(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("stages", "processors", "processing_stages"), default=["refine", "craft", "assemble"])


def _logistics_stage_construct(stage: str) -> str:
    return _LOGISTICS_STAGE_CONSTRUCTS.get(_snake_id(stage, "process"), "processing_stage")


def _logistics_markets(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("markets", "market_nodes", "buyers"), default=["local_market"])


def _logistics_sinks(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("sinks", "demand_sinks", "consumers"), default=["settlement"])


def _logistics_routes(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("routes", "supply_routes", "transport_routes"), default=["main_route"])


def _logistics_modes(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("transport_modes", "modes", "mode"), default=["cart", "truck"])


def _logistics_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    throughput = _number(values.get("throughput") or values.get("throughput_rate") or values.get("rate"), default=1.0)
    capacity = _number(values.get("capacity"), default=10.0)
    state: dict[str, Any] = {
        construct: name,
        "logistics_construct": construct,
        "logistics_kind": kind,
        "action": _snake_id(values.get("action") or _LOGISTICS_ACTIONS.get(construct), "run_logistics"),
        f"{construct}_count": 1,
        "logistics_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "resource_logistics_chain",
        "enabled": not _disabled(values.get("enabled", True)),
        "throughput": throughput,
        "capacity": capacity,
        "latency": _number(values.get("latency"), default=1.0),
        "loss_rate": _number(values.get("loss_rate"), default=0.02),
    }
    if construct == "supply_chain":
        goods = _logistics_goods(values)
        stages = _logistics_stages(values)
        markets = _logistics_markets(values)
        sinks = _logistics_sinks(values)
        routes = _logistics_routes(values)
        state.update(
            {
                "chain_type": kind,
                "goods": goods,
                "stages": stages,
                "markets": markets,
                "sinks": sinks,
                "routes": routes,
                "good_count": len(goods),
                "logistics_hub_count": max(1, _positive_int(values.get("hubs") or values.get("hub_count"), default=1)),
                "storage_depot_count": max(1, _positive_int(values.get("depots") or values.get("storage_depots"), default=max(1, len(goods)))),
                "processing_stage_count": len(stages),
                "market_node_count": len(markets),
                "demand_sink_count": len(sinks),
                "supply_route_count": len(routes),
                "bottleneck_count": 1,
                "throughput_rule_count": 1,
                "failure_mode_count": 1,
                "resource_flow_count": max(1, len(goods)),
            }
        )
    elif construct in {"logistics_hub", "storage_depot"}:
        goods = _logistics_goods(values)
        state.update({"goods": goods, "storage_depot_count": 1 if construct == "storage_depot" else max(1, len(goods)), "stockpile_count": len(goods), "input_buffer_count": 1, "output_buffer_count": 1, "supply_route_count": 1})
    elif construct == "stockpile":
        state.update({"resource_type": kind, "inventory": _number(values.get("inventory"), default=capacity * 0.5), "stockpile_count": 1, "world_metric_count": 1, "throughput_rule_count": 1})
    elif construct in {"input_buffer", "output_buffer"}:
        state.update({"resource_type": kind, "buffer_type": "input" if construct == "input_buffer" else "output", "buffer_count": 1, "fill_level": _number(values.get("fill_level") or values.get("inventory"), default=capacity * 0.4), "throughput_rule_count": 1})
    elif construct in {"processing_stage", "refinery_stage", "workshop_stage", "assembly_stage"}:
        inputs = _logistics_inputs(values, kind)
        outputs = _logistics_outputs(values, kind)
        state.update({"stage_type": kind, "inputs": inputs, "outputs": outputs, "input_count": len(inputs), "output_count": len(outputs), "input_buffer_count": len(inputs), "output_buffer_count": len(outputs), "throughput_rule_count": 1, "failure_mode_count": 1, "batch_size": _positive_int(values.get("batch_size"), default=1), "recipe": _surface_marker_value(values, "recipe", fallback=kind)})
    elif construct == "market_node":
        goods = _logistics_goods(values)
        state.update({"market_type": kind, "goods": goods, "good_count": len(goods), "demand_sink_count": 1, "storage_depot_count": 1, "price": _number(values.get("price"), default=1.0), "stockpile_count": len(goods)})
    elif construct == "demand_sink":
        state.update({"demand_type": kind, "demand": _number(values.get("demand"), default=1.0), "priority": _number(values.get("priority"), default=1.0), "world_metric_count": 1, "scarcity_loop_count": 1})
    elif construct in {"supply_route", "transport_leg"}:
        modes = _logistics_modes(values)
        state.update({"route_type": kind, "transport_modes": modes, "mode_count": len(modes), "transport_leg_count": len(modes) if construct == "supply_route" else 1, "source_nodes": _gameplay_name_list(values, ("source_nodes", "sources", "from_nodes"), default=["source"]), "sink_nodes": _gameplay_name_list(values, ("sink_nodes", "sinks", "to_nodes"), default=["sink"]), "resource_flow_count": 1, "bottleneck_count": 1})
    elif construct == "bottleneck":
        state.update({"bottleneck_type": kind, "limit": _number(values.get("limit"), default=throughput), "severity": _number(values.get("severity"), default=0.45), "throughput_rule_count": 1, "world_metric_count": 1, "failure_mode_count": 1})
    elif construct == "throughput_rule":
        state.update({"rule_type": kind, "throughput_rate": throughput, "max_capacity": capacity, "minimum_input": _number(values.get("minimum_input"), default=1.0), "world_metric_count": 1})
    elif construct == "failure_mode":
        state.update({"failure_type": kind, "failure_rate": _number(values.get("failure_rate"), default=0.08), "recovery_time": _number(values.get("recovery_time"), default=30.0), "severity": _number(values.get("severity"), default=0.4), "world_metric_count": 1, "event_count": 1})
    return state


def _logistics_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _LOGISTICS_ACTIONS.get(construct), "run_logistics")}
    target = _surface_marker_value(values, "target", "resource", "good", "route", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _expand_logistics_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _logistics_kind(values, construct)
    core_name = _logistics_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_logistics_scale(values, construct),
        state=_logistics_state(values, construct, name, kind),
        tags=[construct, kind, "logistics", "production", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_LOGISTICS_ACTIONS.get(construct), "run_logistics"): _logistics_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_LOGISTICS_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    if construct == "supply_chain":
        goods = _logistics_goods(values)[:16]
        for index, good in enumerate(goods):
            depot_values = deepcopy(values)
            depot_values["resource_type"] = good
            depot_values["goods"] = [good]
            depot_values["position"] = [center[0] + (index - (len(goods) - 1) / 2.0) * 0.62, center[1] + 1.15, center[2] + 0.04]
            depot_node = {"node_type": "scene_object", "name": f"{name}_{good}_depot", "role": "environment_structure", "from": node.get("from"), "values": depot_values}
            depot_objects, depot_relationships = _expand_logistics_macro(depot_node, construct="storage_depot")
            objects.extend(depot_objects)
            relationships.extend(depot_relationships)
            relationships.append(_macro_relationship(name, core_name, _logistics_core_name(f"{name}_{good}_depot", "storage_depot"), "contains", f"Supply chain {name} stores {good}."))

        stages = _logistics_stages(values)[:16]
        previous_stage = ""
        for index, stage in enumerate(stages):
            stage_construct = _logistics_stage_construct(stage)
            stage_values = deepcopy(values)
            stage_values["stage_type"] = stage
            stage_values["process"] = stage
            stage_values["position"] = [center[0] + (index - (len(stages) - 1) / 2.0) * 0.76, center[1], center[2] + 0.06]
            stage_node = {"node_type": "scene_object", "name": f"{name}_{stage}_stage", "role": "interactive", "from": node.get("from"), "values": stage_values}
            stage_objects, stage_relationships = _expand_logistics_macro(stage_node, construct=stage_construct)
            objects.extend(stage_objects)
            relationships.extend(stage_relationships)
            stage_core = _logistics_core_name(f"{name}_{stage}_stage", stage_construct)
            relationships.append(_macro_relationship(name, core_name, stage_core, "contains", f"Supply chain {name} contains stage {stage}."))
            if previous_stage:
                relationships.append(_macro_relationship(name, previous_stage, stage_core, "routes_to", f"Supply chain {name} advances to stage {stage}."))
            previous_stage = stage_core

        for index, market in enumerate(_logistics_markets(values)[:12]):
            market_values = deepcopy(values)
            market_values["market_type"] = market
            market_values["position"] = [center[0] + (index - (len(_logistics_markets(values)[:12]) - 1) / 2.0) * 0.64, center[1] - 0.95, center[2] + 0.04]
            market_node = {"node_type": "scene_object", "name": f"{name}_{market}_market", "role": "interactive", "from": node.get("from"), "values": market_values}
            market_objects, market_relationships = _expand_logistics_macro(market_node, construct="market_node")
            objects.extend(market_objects)
            relationships.extend(market_relationships)
            relationships.append(_macro_relationship(name, core_name, _logistics_core_name(f"{name}_{market}_market", "market_node"), "routes_to", f"Supply chain {name} feeds market {market}."))

        for child_construct, suffix, x_offset in (("supply_route", "route", -0.65), ("bottleneck", "bottleneck", 0.0), ("failure_mode", "failure", 0.65)):
            if _any_disabled(values, child_construct, suffix):
                continue
            child_values = deepcopy(values)
            child_values["position"] = [center[0] + x_offset, center[1] - 1.72, center[2] + 0.04]
            child_node = {"node_type": "scene_object", "name": f"{name}_{suffix}", "role": _LOGISTICS_ROLES[child_construct], "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_logistics_macro(child_node, construct=child_construct)
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, core_name, _logistics_core_name(f"{name}_{suffix}", child_construct), "supports", f"Supply chain {name} includes {suffix}."))

    elif construct == "logistics_hub":
        for child_construct, suffix, x_offset in (("storage_depot", "depot", -0.45), ("input_buffer", "input", 0.0), ("output_buffer", "output", 0.45)):
            child_values = deepcopy(values)
            child_values["position"] = [center[0] + x_offset, center[1] + 0.52, center[2] + 0.04]
            child_node = {"node_type": "scene_object", "name": f"{name}_{suffix}", "role": _LOGISTICS_ROLES[child_construct], "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_logistics_macro(child_node, construct=child_construct)
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, core_name, _logistics_core_name(f"{name}_{suffix}", child_construct), "contains", f"Logistics hub {name} contains {suffix}."))

    elif construct == "storage_depot":
        goods = _logistics_goods(values)[:16]
        for index, good in enumerate(goods):
            stock_values = deepcopy(values)
            stock_values["resource_type"] = good
            stock_values["position"] = [center[0] + (index - (len(goods) - 1) / 2.0) * 0.36, center[1] + 0.46, center[2] + 0.04]
            stock_node = {"node_type": "scene_object", "name": f"{name}_{good}_stockpile", "role": "environment_structure", "from": node.get("from"), "values": stock_values}
            stock_objects, stock_relationships = _expand_logistics_macro(stock_node, construct="stockpile")
            objects.extend(stock_objects)
            relationships.extend(stock_relationships)
            relationships.append(_macro_relationship(name, core_name, _logistics_core_name(f"{name}_{good}_stockpile", "stockpile"), "contains", f"Storage depot {name} contains stockpile {good}."))
        rule_values = deepcopy(values)
        rule_values["position"] = [center[0], center[1] - 0.46, center[2] + 0.04]
        rule_node = {"node_type": "scene_object", "name": f"{name}_throughput", "role": "narrative_clue", "from": node.get("from"), "values": rule_values}
        rule_objects, rule_relationships = _expand_logistics_macro(rule_node, construct="throughput_rule")
        objects.extend(rule_objects)
        relationships.extend(rule_relationships)
        relationships.append(_macro_relationship(name, _logistics_core_name(f"{name}_throughput", "throughput_rule"), core_name, "supports", f"Throughput rule controls depot {name}."))

    elif construct in {"stockpile", "input_buffer", "output_buffer", "throughput_rule", "demand_sink", "bottleneck", "failure_mode"}:
        metric_name = {
            "stockpile": "inventory",
            "input_buffer": "input_fill",
            "output_buffer": "output_fill",
            "throughput_rule": "throughput",
            "demand_sink": "demand",
            "bottleneck": "bottleneck",
            "failure_mode": "failure_rate",
        }[construct]
        metric_values = deepcopy(values)
        metric_values["metric"] = metric_name
        metric_values["metric_value"] = values.get(metric_name) or values.get("throughput") or values.get("failure_rate")
        metric_values["position"] = [center[0], center[1] + 0.38, center[2] + 0.04]
        metric_node = {"node_type": "scene_object", "name": f"{name}_{metric_name}_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
        metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
        objects.extend(metric_objects)
        relationships.extend(metric_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_{metric_name}_metric", "world_metric"), "reveals", f"{construct} {name} exposes {metric_name}."))
        if construct == "bottleneck" and not _any_disabled(values, "throughput_rule", "rule"):
            rule_values = deepcopy(values)
            rule_values["position"] = [center[0], center[1] - 0.38, center[2] + 0.04]
            rule_node = {"node_type": "scene_object", "name": f"{name}_throughput", "role": "narrative_clue", "from": node.get("from"), "values": rule_values}
            rule_objects, rule_relationships = _expand_logistics_macro(rule_node, construct="throughput_rule")
            objects.extend(rule_objects)
            relationships.extend(rule_relationships)
            relationships.append(_macro_relationship(name, _logistics_core_name(f"{name}_throughput", "throughput_rule"), core_name, "supports", f"Throughput rule describes bottleneck {name}."))

    elif construct in {"processing_stage", "refinery_stage", "workshop_stage", "assembly_stage"}:
        inputs = _logistics_inputs(values, kind)[:12]
        outputs = _logistics_outputs(values, kind)[:12]
        for index, good in enumerate(inputs):
            buffer_values = deepcopy(values)
            buffer_values["resource_type"] = good
            buffer_values["position"] = [center[0] + (index - (len(inputs) - 1) / 2.0) * 0.34, center[1] + 0.48, center[2] + 0.04]
            buffer_node = {"node_type": "scene_object", "name": f"{name}_{good}_input", "role": "environment_structure", "from": node.get("from"), "values": buffer_values}
            buffer_objects, buffer_relationships = _expand_logistics_macro(buffer_node, construct="input_buffer")
            objects.extend(buffer_objects)
            relationships.extend(buffer_relationships)
            relationships.append(_macro_relationship(name, _logistics_core_name(f"{name}_{good}_input", "input_buffer"), core_name, "routes_to", f"{construct} {name} consumes {good}."))
        for index, good in enumerate(outputs):
            buffer_values = deepcopy(values)
            buffer_values["resource_type"] = good
            buffer_values["position"] = [center[0] + (index - (len(outputs) - 1) / 2.0) * 0.34, center[1] - 0.48, center[2] + 0.04]
            buffer_node = {"node_type": "scene_object", "name": f"{name}_{good}_output", "role": "environment_structure", "from": node.get("from"), "values": buffer_values}
            buffer_objects, buffer_relationships = _expand_logistics_macro(buffer_node, construct="output_buffer")
            objects.extend(buffer_objects)
            relationships.extend(buffer_relationships)
            relationships.append(_macro_relationship(name, core_name, _logistics_core_name(f"{name}_{good}_output", "output_buffer"), "routes_to", f"{construct} {name} produces {good}."))
        for child_construct, suffix, x_offset in (("throughput_rule", "throughput", -0.32), ("failure_mode", "failure", 0.32)):
            if _any_disabled(values, child_construct, suffix):
                continue
            child_values = deepcopy(values)
            child_values["position"] = [center[0] + x_offset, center[1], center[2] + 0.08]
            child_node = {"node_type": "scene_object", "name": f"{name}_{suffix}", "role": "narrative_clue", "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_logistics_macro(child_node, construct=child_construct)
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, _logistics_core_name(f"{name}_{suffix}", child_construct), core_name, "supports", f"{construct} {name} uses {suffix}."))

    elif construct == "market_node":
        demand_values = deepcopy(values)
        demand_values["position"] = [center[0] - 0.32, center[1] + 0.42, center[2] + 0.04]
        demand_node = {"node_type": "scene_object", "name": f"{name}_demand", "role": "environment_structure", "from": node.get("from"), "values": demand_values}
        demand_objects, demand_relationships = _expand_logistics_macro(demand_node, construct="demand_sink")
        objects.extend(demand_objects)
        relationships.extend(demand_relationships)
        relationships.append(_macro_relationship(name, core_name, _logistics_core_name(f"{name}_demand", "demand_sink"), "supports", f"Market node {name} feeds demand sink."))
        stock_values = deepcopy(values)
        stock_values["position"] = [center[0] + 0.32, center[1] + 0.42, center[2] + 0.04]
        stock_node = {"node_type": "scene_object", "name": f"{name}_stock", "role": "environment_structure", "from": node.get("from"), "values": stock_values}
        stock_objects, stock_relationships = _expand_logistics_macro(stock_node, construct="stockpile")
        objects.extend(stock_objects)
        relationships.extend(stock_relationships)
        relationships.append(_macro_relationship(name, _logistics_core_name(f"{name}_stock", "stockpile"), core_name, "routes_to", f"Market node {name} draws from stock."))

    elif construct == "supply_route":
        modes = _logistics_modes(values)[:12]
        previous = ""
        for index, mode in enumerate(modes):
            leg_values = deepcopy(values)
            leg_values["mode"] = mode
            leg_values["position"] = [center[0] + (index - (len(modes) - 1) / 2.0) * 0.46, center[1] + 0.38, center[2] + 0.04]
            leg_node = {"node_type": "scene_object", "name": f"{name}_{mode}_leg", "role": "navigation", "from": node.get("from"), "values": leg_values}
            leg_objects, leg_relationships = _expand_logistics_macro(leg_node, construct="transport_leg")
            objects.extend(leg_objects)
            relationships.extend(leg_relationships)
            leg_core = _logistics_core_name(f"{name}_{mode}_leg", "transport_leg")
            relationships.append(_macro_relationship(name, core_name, leg_core, "contains", f"Supply route {name} includes {mode} transport."))
            if previous:
                relationships.append(_macro_relationship(name, previous, leg_core, "routes_to", f"Supply route {name} hands off to {mode}."))
            previous = leg_core
        flow_values = deepcopy(values)
        flow_values["resource_type"] = kind
        flow_values["position"] = [center[0], center[1] - 0.42, center[2] + 0.04]
        flow_node = {"node_type": "scene_object", "name": f"{name}_flow", "role": "environment_structure", "from": node.get("from"), "values": flow_values}
        flow_objects, flow_relationships = _expand_simulation_macro(flow_node, construct="resource_flow")
        objects.extend(flow_objects)
        relationships.extend(flow_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_flow", "resource_flow"), "routes_to", f"Supply route {name} carries resource flow."))

    elif construct == "transport_leg":
        flow_values = deepcopy(values)
        flow_values["resource_type"] = kind
        flow_values["position"] = [center[0], center[1] + 0.36, center[2] + 0.04]
        flow_node = {"node_type": "scene_object", "name": f"{name}_flow", "role": "environment_structure", "from": node.get("from"), "values": flow_values}
        flow_objects, flow_relationships = _expand_simulation_macro(flow_node, construct="resource_flow")
        objects.extend(flow_objects)
        relationships.extend(flow_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_flow", "resource_flow"), "routes_to", f"Transport leg {name} carries flow."))

    return objects, relationships


