def _production_strategy_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _PRODUCTION_STRATEGY_KIND_DEFAULTS.get(construct, construct)
    for key in _PRODUCTION_STRATEGY_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or (isinstance(raw, str) and not raw.strip()):
            continue
        return _snake_id(raw, fallback)
    return fallback


def _production_strategy_core_name(name: str, construct: str) -> str:
    return f"{name}_{_PRODUCTION_STRATEGY_CORE_SUFFIXES.get(construct, 'production_strategy_core')}"


def _production_strategy_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "production_strategy":
        return [max(2.6, _number(values.get("width"), default=5.0)), max(1.7, _number(values.get("depth"), default=3.0)), 0.24]
    if construct in {"strategic_reserve", "mobilization_order", "wartime_production", "peacetime_production"}:
        return [1.1, 0.72, 0.20]
    if construct in {"sabotage_target", "maintenance_plan"}:
        return [0.78, 0.48, 0.18]
    return [0.48, 0.30, 0.12]


def _production_strategy_priorities(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("priorities", "production_priorities", "priority", "strategic_priorities"), default=["food", "fuel", "munitions"])


def _production_strategy_goods(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("goods", "reserve_goods", "resources", "outputs", "quotas"), default=["food", "fuel", "materials"])


def _production_strategy_modes(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("production_modes", "modes", "mode"), default=["peacetime", "wartime"])


def _production_strategy_targets(values: Mapping[str, Any], construct: str) -> list[str]:
    keys_by_construct = {
        "trade_embargo": ("embargo_targets", "targets", "factions", "partners"),
        "sabotage_target": ("sabotage_targets", "targets", "facilities"),
        "maintenance_plan": ("maintenance_targets", "targets", "facilities"),
        "repair_schedule": ("maintenance_targets", "repair_targets", "targets", "facilities"),
        "procurement_contract": ("procurement_sources", "contracts", "suppliers", "sources"),
    }
    defaults = {
        "trade_embargo": ["rival_faction"],
        "sabotage_target": ["bottleneck"],
        "maintenance_plan": ["production_line"],
        "repair_schedule": ["production_line"],
        "procurement_contract": ["supplier"],
    }
    return _gameplay_name_list(values, keys_by_construct.get(construct, ("targets", "target")), default=defaults.get(construct, []))


def _production_strategy_enabled(value: Any, *, default: bool = False) -> bool:
    if value is None:
        return default
    if _disabled(value):
        return False
    if isinstance(value, bool):
        return value
    if isinstance(value, int | float):
        return float(value) > 0
    if isinstance(value, str):
        return bool(value.strip())
    return bool(value)


def _production_strategy_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    priorities = _production_strategy_priorities(values)
    goods = _production_strategy_goods(values)
    modes = _production_strategy_modes(values)
    targets = _production_strategy_targets(values, construct)
    reserve_ratio = _number(values.get("reserve_ratio") or values.get("reserve"), default=0.25)
    readiness = _number(values.get("readiness") or values.get("readiness_level"), default=0.55)
    mobilization_level = _number(values.get("mobilization_level") or values.get("mobilization"), default=0.0)
    rationing_enabled = _production_strategy_enabled(values.get("rationing"), default=False) or _positive_int(values.get("rationing_policy_count") or values.get("rationing_count"), default=0) > 0
    state: dict[str, Any] = {
        construct: name,
        "production_strategy_construct": construct,
        "production_strategy_kind": kind,
        "strategy_kind": kind,
        "action": _snake_id(values.get("action") or _PRODUCTION_STRATEGY_ACTIONS.get(construct), "run_production_strategy"),
        f"{construct}_count": 1,
        "strategy_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "faction_production_strategy",
        "enabled": not _disabled(values.get("enabled", True)),
        "priorities": priorities,
        "goods": goods,
        "production_modes": modes,
        "targets": targets,
        "readiness": readiness,
        "readiness_threshold": _number(values.get("readiness_threshold"), default=0.7),
        "reserve_ratio": reserve_ratio,
        "ration_rate": _number(values.get("ration_rate"), default=0.35),
        "mobilization_level": mobilization_level,
        "repair_interval": _number(values.get("repair_interval"), default=24.0),
    }
    if construct == "production_strategy":
        embargo_targets = _gameplay_name_list(values, ("embargo_targets", "embargoes"), default=[])
        if not embargo_targets and _positive_int(values.get("trade_embargo_count") or values.get("embargo_count"), default=0):
            embargo_targets = ["rival_faction"]
        state.update(
            {
                "production_strategy_count": 1,
                "production_priority_count": len(priorities),
                "quota_rule_count": len(goods),
                "allocation_rule_count": len(goods),
                "strategic_reserve_count": 0 if _any_disabled(values, "strategic_reserve", "reserve") else 1,
                "rationing_policy_count": 1 if rationing_enabled else 0,
                "maintenance_plan_count": 0 if _any_disabled(values, "maintenance", "maintenance_plan") else 1,
                "production_mode_count": len(modes),
                "mobilization_order_count": 1 if mobilization_level > 0 or _production_strategy_enabled(values.get("mobilization"), default=False) else 0,
                "trade_embargo_count": len(embargo_targets),
            }
        )
    elif construct == "production_priority":
        state.update({"priority": kind, "quota_rule_count": 1, "allocation_rule_count": 1, "supply_chain_count": 0 if _any_disabled(values, "supply_chain", "chain") else 1})
    elif construct == "quota_rule":
        state.update({"quota": _number(values.get("quota") or values.get("quota_amount"), default=100.0), "throughput_rule_count": 1, "world_metric_count": 1})
    elif construct == "allocation_rule":
        state.update({"allocation": _number(values.get("allocation") or values.get("allocation_ratio"), default=0.5), "resource_flow_count": 1, "world_metric_count": 1})
    elif construct == "rationing_policy":
        state.update({"rationing": True, "scarcity_loop_count": 1, "quota_rule_count": 1, "world_metric_count": 1})
    elif construct == "strategic_reserve":
        state.update({"reserve_goods": goods, "stockpile_count": len(goods), "readiness_level_count": 1})
    elif construct == "trade_embargo":
        state.update({"embargo_targets": targets, "bottleneck_count": 1, "diplomacy_state_count": 1, "world_metric_count": 1})
    elif construct == "sabotage_target":
        state.update({"sabotage_targets": targets, "failure_mode_count": 1, "bottleneck_count": 1})
    elif construct == "maintenance_plan":
        state.update({"maintenance_targets": targets, "repair_schedule_count": 1, "failure_mode_count": 1, "throughput_rule_count": 1})
    elif construct == "repair_schedule":
        state.update({"repair_target": kind, "world_metric_count": 1})
    elif construct == "mobilization_order":
        state.update({"war_state": _surface_marker_value(values, "war_state", fallback="mobilizing"), "wartime_production_count": 1, "readiness_level_count": 1})
    elif construct == "production_mode":
        mode = _snake_id(kind, "peacetime")
        state.update({"mode": mode, "wartime_production_count": 1 if any(token in mode for token in ("war", "military", "urgent", "emergency")) else 0, "peacetime_production_count": 0 if any(token in mode for token in ("war", "military", "urgent", "emergency")) else 1})
    elif construct == "wartime_production":
        state.update({"war_state": kind, "strategic_reserve_count": 1, "quota_rule_count": len(goods), "sabotage_target_count": 1, "readiness_level_count": 1})
    elif construct == "peacetime_production":
        state.update({"peace_focus": kind, "market_node_count": 1, "maintenance_plan_count": 1, "procurement_contract_count": 1})
    elif construct == "procurement_contract":
        state.update({"procurement_sources": targets, "market_node_count": 1, "resource_claim_count": 1, "demand_sink_count": 1})
    elif construct == "readiness_level":
        state.update({"readiness_level": readiness, "world_metric_count": 1})
    return state


def _production_strategy_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _PRODUCTION_STRATEGY_ACTIONS.get(construct), "run_production_strategy")}
    target = _surface_marker_value(values, "target", "resource", "good", "faction", "facility", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _production_strategy_child_core_name(name: str, construct: str) -> str:
    if construct in _PRODUCTION_STRATEGY_CORE_SUFFIXES:
        return _production_strategy_core_name(name, construct)
    if construct in _LOGISTICS_CORE_SUFFIXES:
        return _logistics_core_name(name, construct)
    if construct in _CULTURE_CORE_SUFFIXES:
        return _culture_core_name(name, construct)
    if construct in _CIVIL_ECOLOGY_CORE_SUFFIXES:
        return _civil_ecology_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return name


def _expand_production_strategy_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _PRODUCTION_STRATEGY_CORE_SUFFIXES:
        return _expand_production_strategy_macro(node, construct=construct)
    if construct in _LOGISTICS_CORE_SUFFIXES:
        return _expand_logistics_macro(node, construct=construct)
    if construct in _CULTURE_CORE_SUFFIXES:
        return _expand_culture_macro(node, construct=construct)
    if construct in _CIVIL_ECOLOGY_CORE_SUFFIXES:
        return _expand_civil_ecology_macro(node, construct=construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _expand_simulation_macro(node, construct=construct)
    return [node], []


def _expand_production_strategy_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _production_strategy_kind(values, construct)
    core_name = _production_strategy_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_production_strategy_scale(values, construct),
        state=_production_strategy_state(values, construct, name, kind),
        tags=[construct, kind, "production_strategy", "faction", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_PRODUCTION_STRATEGY_ACTIONS.get(construct), "run_production_strategy"): _production_strategy_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_PRODUCTION_STRATEGY_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    def add_child(
        child_construct: str,
        suffix: str,
        updates: Mapping[str, Any],
        position: Sequence[float],
        *,
        relation: str = "supports",
        description: str | None = None,
    ) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["position"] = list(position)
        child_node = {
            "node_type": "scene_object",
            "name": child_name,
            "role": _PRODUCTION_STRATEGY_ROLES.get(child_construct, _LOGISTICS_ROLES.get(child_construct, "environment_structure")),
            "from": node.get("from"),
            "values": child_values,
        }
        child_objects, child_relationships = _expand_production_strategy_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        child_core = _production_strategy_child_core_name(child_name, child_construct)
        relationships.append(_macro_relationship(name, core_name, child_core, relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    if construct == "production_strategy":
        priorities = _production_strategy_priorities(values)[:16]
        for index, priority in enumerate(priorities):
            add_child(
                "production_priority",
                f"{priority}_priority",
                {"priority": priority, "goods": [priority]},
                [center[0] + (index - (len(priorities) - 1) / 2.0) * 0.60, center[1] + 1.10, center[2] + 0.05],
                relation="prioritizes",
                description=f"Production strategy {name} prioritizes {priority}.",
            )
        goods = _production_strategy_goods(values)[:16]
        for index, good in enumerate(goods):
            x = center[0] + (index - (len(goods) - 1) / 2.0) * 0.54
            add_child("quota_rule", f"{good}_quota", {"quota": values.get("quota") or values.get("quota_amount"), "good": good, "resource_type": good}, [x, center[1] + 0.40, center[2] + 0.05], relation="constrains", description=f"Production strategy {name} assigns a quota for {good}.")
            add_child("allocation_rule", f"{good}_allocation", {"allocation": values.get("allocation") or values.get("allocation_ratio"), "good": good, "resource_type": good}, [x, center[1] - 0.18, center[2] + 0.05], relation="routes_to", description=f"Production strategy {name} allocates {good}.")
        if not _any_disabled(values, "strategic_reserve", "reserve"):
            add_child("strategic_reserve", "reserve", {"reserve_goods": goods, "goods": goods}, [center[0] - 0.62, center[1] - 0.90, center[2] + 0.05], relation="stores", description=f"Production strategy {name} maintains a strategic reserve.")
        if _production_strategy_enabled(values.get("rationing"), default=False) or _positive_int(values.get("rationing_policy_count") or values.get("rationing_count"), default=0):
            add_child("rationing_policy", "rationing", {"goods": goods, "resource_type": goods[0] if goods else kind}, [center[0], center[1] - 0.90, center[2] + 0.05], relation="constrains", description=f"Production strategy {name} applies rationing.")
        if not _any_disabled(values, "maintenance", "maintenance_plan"):
            add_child("maintenance_plan", "maintenance", {"maintenance_targets": _production_strategy_targets(values, "maintenance_plan")}, [center[0] + 0.62, center[1] - 0.90, center[2] + 0.05], relation="maintains", description=f"Production strategy {name} schedules production maintenance.")
        modes = _production_strategy_modes(values)[:8]
        for index, mode in enumerate(modes):
            add_child("production_mode", f"{mode}_mode", {"mode": mode, "production_mode": mode}, [center[0] + (index - (len(modes) - 1) / 2.0) * 0.52, center[1] - 1.48, center[2] + 0.05], relation="switches_to", description=f"Production strategy {name} can switch to {mode} mode.")
        if _number(values.get("mobilization_level") or values.get("mobilization"), default=0.0) > 0:
            add_child("mobilization_order", "mobilization", {"mobilization_level": values.get("mobilization_level") or values.get("mobilization")}, [center[0] - 0.42, center[1] - 2.04, center[2] + 0.05], relation="escalates", description=f"Production strategy {name} can mobilize industry.")
        embargo_targets = _gameplay_name_list(values, ("embargo_targets", "embargoes"), default=[])
        if not embargo_targets and _positive_int(values.get("trade_embargo_count") or values.get("embargo_count"), default=0):
            embargo_targets = ["rival_faction"]
        for index, target in enumerate(embargo_targets[:8]):
            add_child("trade_embargo", f"{target}_embargo", {"target": target, "embargo": target, "embargo_targets": [target]}, [center[0] + 0.42 + index * 0.34, center[1] - 2.04, center[2] + 0.05], relation="blocks", description=f"Production strategy {name} embargoes {target}.")

    elif construct == "production_priority":
        add_child("quota_rule", f"{kind}_quota", {"good": kind, "resource_type": kind}, [center[0] - 0.30, center[1] + 0.40, center[2] + 0.04], relation="constrains", description=f"Production priority {name} sets quota for {kind}.")
        add_child("allocation_rule", f"{kind}_allocation", {"good": kind, "resource_type": kind}, [center[0] + 0.30, center[1] + 0.40, center[2] + 0.04], relation="routes_to", description=f"Production priority {name} allocates {kind}.")
        if not _any_disabled(values, "supply_chain", "chain"):
            add_child("supply_chain", "supply_chain", {"goods": _production_strategy_goods(values), "chain_type": kind}, [center[0], center[1] - 0.46, center[2] + 0.04], relation="feeds", description=f"Production priority {name} feeds a supply chain.")

    elif construct == "quota_rule":
        add_child("throughput_rule", "throughput", {"resource_type": kind, "rule_type": kind}, [center[0] - 0.28, center[1] + 0.36, center[2] + 0.04], relation="constrains", description=f"Quota rule {name} constrains throughput.")
        add_child("world_metric", "quota_metric", {"metric": "quota", "metric_value": values.get("quota") or values.get("quota_amount") or 100.0}, [center[0] + 0.28, center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"Quota rule {name} exposes quota state.")

    elif construct == "allocation_rule":
        add_child("resource_flow", "allocation_flow", {"resource_type": kind, "flow_type": kind}, [center[0] - 0.28, center[1] + 0.36, center[2] + 0.04], relation="routes_to", description=f"Allocation rule {name} creates resource flow.")
        add_child("world_metric", "allocation_metric", {"metric": "allocation", "metric_value": values.get("allocation") or values.get("allocation_ratio") or 0.5}, [center[0] + 0.28, center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"Allocation rule {name} exposes allocation state.")

    elif construct == "rationing_policy":
        add_child("scarcity_loop", "scarcity", {"resource_type": kind, "scarcity": values.get("scarcity") or values.get("deficit") or 0.35}, [center[0] - 0.34, center[1] + 0.42, center[2] + 0.04], relation="responds_to", description=f"Rationing policy {name} responds to scarcity.")
        add_child("quota_rule", "ration_quota", {"resource_type": kind, "quota": values.get("quota") or values.get("ration_rate") or 0.35}, [center[0] + 0.00, center[1] + 0.42, center[2] + 0.04], relation="constrains", description=f"Rationing policy {name} enforces ration quota.")
        add_child("world_metric", "ration_metric", {"metric": "ration_rate", "metric_value": values.get("ration_rate") or 0.35}, [center[0] + 0.34, center[1] + 0.42, center[2] + 0.04], relation="reveals", description=f"Rationing policy {name} exposes ration rate.")

    elif construct == "strategic_reserve":
        goods = _production_strategy_goods(values)[:16]
        for index, good in enumerate(goods):
            add_child("stockpile", f"{good}_stockpile", {"resource_type": good, "goods": [good]}, [center[0] + (index - (len(goods) - 1) / 2.0) * 0.36, center[1] + 0.44, center[2] + 0.04], relation="stores", description=f"Strategic reserve {name} stores {good}.")
        add_child("readiness_level", "readiness", {"readiness": values.get("readiness") or values.get("reserve_ratio") or 0.55}, [center[0], center[1] - 0.42, center[2] + 0.04], relation="reveals", description=f"Strategic reserve {name} contributes readiness.")

    elif construct == "trade_embargo":
        add_child("bottleneck", "embargo_bottleneck", {"bottleneck_type": kind, "severity": values.get("severity") or 0.6}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="blocks", description=f"Trade embargo {name} creates a bottleneck.")
        if not _any_disabled(values, "diplomacy_state", "diplomacy"):
            add_child("diplomacy_state", "diplomacy", {"diplomacy": "embargo", "stance": "hostile", "faction": kind}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="signals", description=f"Trade embargo {name} changes diplomacy.")
        else:
            add_child("world_metric", "embargo_metric", {"metric": "embargo", "metric_value": values.get("severity") or 0.6}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Trade embargo {name} exposes embargo pressure.")

    elif construct == "sabotage_target":
        add_child("failure_mode", "sabotage_failure", {"failure_type": kind, "failure_rate": values.get("failure_rate") or values.get("severity") or 0.35}, [center[0] - 0.28, center[1] + 0.36, center[2] + 0.04], relation="threatens", description=f"Sabotage target {name} creates a failure mode.")
        add_child("bottleneck", "sabotage_bottleneck", {"bottleneck_type": kind, "severity": values.get("severity") or 0.5}, [center[0] + 0.28, center[1] + 0.36, center[2] + 0.04], relation="blocks", description=f"Sabotage target {name} can bottleneck production.")

    elif construct == "maintenance_plan":
        add_child("repair_schedule", "repair_schedule", {"repair": kind, "repair_interval": values.get("repair_interval") or 24.0}, [center[0] - 0.36, center[1] + 0.40, center[2] + 0.04], relation="schedules", description=f"Maintenance plan {name} schedules repairs.")
        add_child("failure_mode", "prevented_failure", {"failure_type": kind, "failure_rate": values.get("failure_rate") or 0.08}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="prevents", description=f"Maintenance plan {name} mitigates failure.")
        add_child("throughput_rule", "maintenance_throughput", {"rule_type": kind, "throughput": values.get("throughput") or 1.0}, [center[0] + 0.36, center[1] + 0.40, center[2] + 0.04], relation="stabilizes", description=f"Maintenance plan {name} stabilizes throughput.")

    elif construct == "repair_schedule":
        add_child("world_metric", "repair_metric", {"metric": "repair_interval", "metric_value": values.get("repair_interval") or 24.0}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Repair schedule {name} exposes repair timing.")

    elif construct == "mobilization_order":
        add_child("wartime_production", "wartime", {"war_state": values.get("war_state") or "mobilized", "mobilization_level": values.get("mobilization_level") or 1.0}, [center[0] - 0.30, center[1] + 0.42, center[2] + 0.04], relation="escalates", description=f"Mobilization order {name} starts wartime production.")
        add_child("readiness_level", "readiness", {"readiness": values.get("readiness") or values.get("mobilization_level") or 0.8}, [center[0] + 0.30, center[1] + 0.42, center[2] + 0.04], relation="reveals", description=f"Mobilization order {name} raises readiness.")

    elif construct == "production_mode":
        mode = _snake_id(kind, "peacetime")
        if any(token in mode for token in ("war", "military", "urgent", "emergency")):
            add_child("wartime_production", "wartime", {"war_state": mode}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="switches_to", description=f"Production mode {name} switches to wartime production.")
        else:
            add_child("peacetime_production", "peacetime", {"peace_focus": mode}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="switches_to", description=f"Production mode {name} switches to peacetime production.")

    elif construct == "wartime_production":
        add_child("strategic_reserve", "reserve", {"goods": _production_strategy_goods(values), "reserve_ratio": values.get("reserve_ratio") or 0.45}, [center[0] - 0.42, center[1] + 0.44, center[2] + 0.04], relation="stores", description=f"Wartime production {name} expands reserves.")
        add_child("quota_rule", "war_quota", {"quota": values.get("quota") or 150.0, "resource_type": kind}, [center[0] + 0.00, center[1] + 0.44, center[2] + 0.04], relation="constrains", description=f"Wartime production {name} raises quotas.")
        add_child("sabotage_target", "sabotage_risk", {"sabotage_target": kind, "severity": values.get("sabotage_risk") or 0.5}, [center[0] + 0.42, center[1] + 0.44, center[2] + 0.04], relation="risks", description=f"Wartime production {name} exposes sabotage targets.")
        add_child("readiness_level", "readiness", {"readiness": values.get("readiness") or 0.8}, [center[0], center[1] - 0.42, center[2] + 0.04], relation="reveals", description=f"Wartime production {name} exposes readiness.")

    elif construct == "peacetime_production":
        add_child("market_node", "market", {"market_type": kind, "goods": _production_strategy_goods(values)}, [center[0] - 0.36, center[1] + 0.42, center[2] + 0.04], relation="feeds", description=f"Peacetime production {name} feeds a market.")
        add_child("maintenance_plan", "maintenance", {"maintenance": kind}, [center[0], center[1] + 0.42, center[2] + 0.04], relation="maintains", description=f"Peacetime production {name} keeps maintenance active.")
        add_child("procurement_contract", "procurement", {"contract": kind}, [center[0] + 0.36, center[1] + 0.42, center[2] + 0.04], relation="procures", description=f"Peacetime production {name} procures inputs.")

    elif construct == "procurement_contract":
        add_child("market_node", "supplier_market", {"market_type": kind, "goods": _production_strategy_goods(values)}, [center[0] - 0.36, center[1] + 0.42, center[2] + 0.04], relation="buys_from", description=f"Procurement contract {name} buys through a market.")
        add_child("resource_claim", "resource_claim", {"resource_type": kind, "land_owner": values.get("faction") or values.get("buyer") or name}, [center[0], center[1] + 0.42, center[2] + 0.04], relation="claims", description=f"Procurement contract {name} creates a resource claim.")
        add_child("demand_sink", "demand", {"demand_type": kind, "goods": _production_strategy_goods(values)}, [center[0] + 0.36, center[1] + 0.42, center[2] + 0.04], relation="demands", description=f"Procurement contract {name} creates a demand sink.")

    elif construct == "readiness_level":
        add_child("world_metric", "readiness_metric", {"metric": "readiness", "metric_value": values.get("readiness") or values.get("readiness_level") or 0.55}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Readiness level {name} exposes readiness.")

    return objects, relationships


