def _conflict_diplomacy_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _CONFLICT_DIPLOMACY_KIND_DEFAULTS.get(construct, construct)
    for key in _CONFLICT_DIPLOMACY_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _conflict_diplomacy_core_name(name: str, construct: str) -> str:
    return f"{name}_{_CONFLICT_DIPLOMACY_CORE_SUFFIXES.get(construct, 'conflict_core')}"


def _conflict_diplomacy_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "conflict_system":
        return [max(2.8, _number(values.get("width"), default=5.6)), max(1.9, _number(values.get("depth"), default=3.4)), 0.26]
    if construct in {"war_plan", "battlefront", "alliance", "disaster_response"}:
        return [1.10, 0.72, 0.20]
    if construct in {"negotiation_channel", "espionage_cell", "covert_operation"}:
        return [0.72, 0.46, 0.16]
    return [0.48, 0.30, 0.12]


def _conflict_factions(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("factions", "belligerents", "rivals", "sides"), default=["faction_a", "faction_b"])


def _conflict_allies(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("allies", "partners", "coalition"), default=[])


def _conflict_objectives(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("objectives", "strategic_objectives", "goals"), default=["secure_resource", "hold_front", "negotiate"])


def _conflict_fronts(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("fronts", "battlefronts", "theaters", "zones"), default=["border"])


def _conflict_terms(values: Mapping[str, Any], construct: str) -> list[str]:
    keys_by_construct = {
        "treaty": ("treaty_terms", "terms", "clauses"),
        "ceasefire": ("ceasefire_terms", "terms", "conditions"),
        "diplomatic_demand": ("diplomatic_demands", "demands", "terms"),
        "negotiation_channel": ("negotiation_terms", "terms", "agenda"),
        "escalation_ladder": ("escalation_steps", "steps", "phases"),
    }
    defaults = {
        "treaty": ["border", "trade", "reparations"],
        "ceasefire": ["hold_fire", "open_channel"],
        "diplomatic_demand": ["concession"],
        "negotiation_channel": ["ceasefire", "trade", "claims"],
        "escalation_ladder": ["warning", "sanction", "mobilization"],
    }
    return _gameplay_name_list(values, keys_by_construct.get(construct, ("terms",)), default=defaults.get(construct, []))


def _conflict_targets(values: Mapping[str, Any], construct: str) -> list[str]:
    keys_by_construct = {
        "sanction": ("sanction_targets", "targets", "rivals", "factions"),
        "espionage_cell": ("intelligence_targets", "targets", "rivals", "facilities"),
        "covert_operation": ("operations", "targets", "sabotage_targets", "facilities"),
        "disaster_response": ("disaster_zones", "zones", "regions", "targets"),
        "emergency_order": ("response_teams", "teams", "targets", "zones"),
        "rival_claim": ("resource_claims", "claims", "resources", "territories"),
    }
    defaults = {
        "sanction": ["rival_faction"],
        "espionage_cell": ["rival_command"],
        "covert_operation": ["supply_bottleneck"],
        "disaster_response": ["impact_zone"],
        "emergency_order": ["response_team"],
        "rival_claim": ["contested_resource"],
    }
    return _gameplay_name_list(values, keys_by_construct.get(construct, ("targets", "target")), default=defaults.get(construct, []))


def _conflict_diplomacy_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    factions = _conflict_factions(values)
    objectives = _conflict_objectives(values)
    fronts = _conflict_fronts(values)
    terms = _conflict_terms(values, construct)
    targets = _conflict_targets(values, construct)
    escalation = _number(values.get("escalation_level") or values.get("escalation"), default=0.45)
    emergency = _number(values.get("emergency_level") or values.get("severity"), default=0.4)
    state: dict[str, Any] = {
        construct: name,
        "conflict_construct": construct,
        "conflict_kind": kind,
        "action": _snake_id(values.get("action") or _CONFLICT_DIPLOMACY_ACTIONS.get(construct), "run_conflict"),
        f"{construct}_count": 1,
        "conflict_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "strategic_conflict_diplomacy",
        "enabled": not _disabled(values.get("enabled", True)),
        "factions": factions,
        "objectives": objectives,
        "fronts": fronts,
        "terms": terms,
        "targets": targets,
        "escalation_level": escalation,
        "emergency_level": emergency,
        "deescalation": _number(values.get("deescalation"), default=0.2),
        "casus_belli": _surface_marker_value(values, "casus_belli", "claim", fallback=kind),
    }
    if construct == "conflict_system":
        state.update(
            {
                "faction_pressure_count": len(factions),
                "strategic_objective_count": len(objectives),
                "battlefront_count": len(fronts),
                "escalation_ladder_count": 0 if _any_disabled(values, "escalation_ladder", "escalation") else 1,
                "negotiation_channel_count": 0 if _any_disabled(values, "negotiation", "negotiation_channel") else 1,
                "sanction_count": len(_conflict_targets(values, "sanction")) if _positive_int(values.get("sanction_count") or values.get("sanctions_count"), default=0) else 0,
                "espionage_cell_count": 1 if _positive_int(values.get("espionage_cell_count") or values.get("espionage_count"), default=0) else 0,
                "disaster_response_count": 1 if "disaster_type" in values or _positive_int(values.get("disaster_response_count") or values.get("disaster_count"), default=0) else 0,
                "treaty_count": 1 if _positive_int(values.get("treaty_count"), default=0) or values.get("treaty_terms") else 0,
                "ceasefire_count": 1 if _positive_int(values.get("ceasefire_count"), default=0) or values.get("ceasefire_terms") else 0,
                "alliance_count": len(_conflict_allies(values)),
            }
        )
    elif construct == "strategic_objective":
        state.update({"objective": kind, "war_plan_count": 1, "production_strategy_count": 1, "world_metric_count": 1})
    elif construct == "war_plan":
        state.update({"battlefront_count": len(fronts), "mobilization_order_count": 1, "supply_route_count": len(fronts), "sabotage_target_count": 1, "readiness_level_count": 1})
    elif construct == "battlefront":
        state.update({"front": kind, "territory_influence_count": 1, "faction_pressure_count": len(factions), "supply_route_count": 1, "hazard_field_count": 1})
    elif construct == "escalation_ladder":
        state.update({"escalation_steps": terms, "diplomatic_demand_count": len(terms), "sanction_count": 1, "world_metric_count": 1, "war_plan_count": 1 if escalation >= 0.75 else 0})
    elif construct in {"treaty", "ceasefire"}:
        state.update({"terms": terms, "diplomacy_state_count": 1, "trade_policy_count": 1, "world_metric_count": 1, "negotiation_channel_count": 1})
    elif construct == "alliance":
        state.update({"allies": _conflict_allies(values), "diplomacy_state_count": 1, "supply_chain_count": 1, "readiness_level_count": 1})
    elif construct == "rival_claim":
        state.update({"resource_claim_count": len(targets), "territory_influence_count": 1, "diplomatic_demand_count": 1})
    elif construct == "diplomatic_demand":
        state.update({"negotiation_channel_count": 1, "sanction_count": 1 if escalation > 0.55 else 0, "world_metric_count": 1})
    elif construct == "negotiation_channel":
        state.update({"diplomacy_state_count": 1, "social_relation_count": max(1, len(factions)), "world_metric_count": 1})
    elif construct == "sanction":
        state.update({"sanction_targets": targets, "trade_embargo_count": len(targets), "bottleneck_count": 1, "world_metric_count": 1})
    elif construct == "espionage_cell":
        state.update({"intelligence_targets": targets, "covert_operation_count": max(1, len(targets)), "sensor_grid_count": 1, "sabotage_target_count": 1})
    elif construct == "covert_operation":
        state.update({"operations": targets, "sabotage_target_count": 1, "failure_mode_count": 1, "world_metric_count": 1})
    elif construct == "disaster_response":
        state.update({"disaster_type": kind, "emergency_order_count": 1, "supply_chain_count": 1, "resource_flow_count": 1, "readiness_level_count": 1})
    elif construct == "emergency_order":
        state.update({"policy_rule_count": 1, "mobilization_order_count": 1 if emergency >= 0.55 else 0, "rationing_policy_count": 1 if emergency >= 0.35 else 0, "world_metric_count": 1})
    return state


def _conflict_diplomacy_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _CONFLICT_DIPLOMACY_ACTIONS.get(construct), "run_conflict")}
    target = _surface_marker_value(values, "target", "faction", "rival", "front", "resource", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _conflict_child_core_name(name: str, construct: str) -> str:
    if construct in _CONFLICT_DIPLOMACY_CORE_SUFFIXES:
        return _conflict_diplomacy_core_name(name, construct)
    return _production_strategy_child_core_name(name, construct)


def _expand_conflict_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _CONFLICT_DIPLOMACY_CORE_SUFFIXES:
        return _expand_conflict_diplomacy_macro(node, construct=construct)
    return _expand_production_strategy_child_macro(node, construct)


def _expand_conflict_diplomacy_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _conflict_diplomacy_kind(values, construct)
    core_name = _conflict_diplomacy_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_conflict_diplomacy_scale(values, construct),
        state=_conflict_diplomacy_state(values, construct, name, kind),
        tags=[construct, kind, "conflict", "diplomacy", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_CONFLICT_DIPLOMACY_ACTIONS.get(construct), "run_conflict"): _conflict_diplomacy_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_CONFLICT_DIPLOMACY_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    def add_child(
        child_construct: str,
        suffix: str,
        updates: Mapping[str, Any],
        position: Sequence[float],
        *,
        relation: str = "supports",
        description: str | None = None,
    ) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["position"] = list(position)
        child_node = {
            "node_type": "scene_object",
            "name": child_name,
            "role": _CONFLICT_DIPLOMACY_ROLES.get(child_construct, _PRODUCTION_STRATEGY_ROLES.get(child_construct, _LOGISTICS_ROLES.get(child_construct, "environment_structure"))),
            "from": node.get("from"),
            "values": child_values,
        }
        child_objects, child_relationships = _expand_conflict_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _conflict_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    if construct == "conflict_system":
        factions = _conflict_factions(values)[:12]
        for index, faction in enumerate(factions):
            add_child("faction_pressure", f"{faction}_pressure", {"faction": faction, "pressure_type": kind}, [center[0] + (index - (len(factions) - 1) / 2.0) * 0.46, center[1] + 1.26, center[2] + 0.05], relation="pressures", description=f"Conflict system {name} tracks pressure from {faction}.")
        objectives = _conflict_objectives(values)[:12]
        for index, objective in enumerate(objectives):
            add_child("strategic_objective", f"{objective}_objective", {"objective": objective, "strategic_goal": objective}, [center[0] + (index - (len(objectives) - 1) / 2.0) * 0.58, center[1] + 0.54, center[2] + 0.05], relation="prioritizes", description=f"Conflict system {name} contains strategic objective {objective}.")
        fronts = _conflict_fronts(values)[:12]
        for index, front in enumerate(fronts):
            add_child("battlefront", f"{front}_front", {"front": front, "battlefront": front}, [center[0] + (index - (len(fronts) - 1) / 2.0) * 0.62, center[1] - 0.20, center[2] + 0.05], relation="contains", description=f"Conflict system {name} contains battlefront {front}.")
        if not _any_disabled(values, "escalation_ladder", "escalation"):
            add_child("escalation_ladder", "escalation", {"escalation": kind}, [center[0] - 0.68, center[1] - 0.98, center[2] + 0.05], relation="escalates", description=f"Conflict system {name} manages escalation.")
        if not _any_disabled(values, "negotiation", "negotiation_channel"):
            add_child("negotiation_channel", "negotiation", {"negotiation": kind}, [center[0], center[1] - 0.98, center[2] + 0.05], relation="deescalates", description=f"Conflict system {name} keeps negotiation open.")
        if values.get("treaty_terms") or _positive_int(values.get("treaty_count"), default=0):
            add_child("treaty", "treaty", {"treaty_terms": _conflict_terms(values, "treaty")}, [center[0] + 0.68, center[1] - 0.98, center[2] + 0.05], relation="settles", description=f"Conflict system {name} can settle through treaty.")
        if values.get("ceasefire_terms") or _positive_int(values.get("ceasefire_count"), default=0):
            add_child("ceasefire", "ceasefire", {"ceasefire_terms": _conflict_terms(values, "ceasefire")}, [center[0] - 0.36, center[1] - 1.58, center[2] + 0.05], relation="pauses", description=f"Conflict system {name} can pause with ceasefire.")
        for index, ally in enumerate(_conflict_allies(values)[:8]):
            add_child("alliance", f"{ally}_alliance", {"allies": [ally], "alliance": ally}, [center[0] + 0.36 + index * 0.30, center[1] - 1.58, center[2] + 0.05], relation="supports", description=f"Conflict system {name} includes alliance {ally}.")
        if _positive_int(values.get("sanction_count") or values.get("sanctions_count"), default=0):
            for index, target in enumerate(_conflict_targets(values, "sanction")[:8]):
                add_child("sanction", f"{target}_sanction", {"target": target, "sanction_targets": [target]}, [center[0] + (index - 0.5) * 0.36, center[1] - 2.12, center[2] + 0.05], relation="pressures", description=f"Conflict system {name} sanctions {target}.")
        if _positive_int(values.get("espionage_cell_count") or values.get("espionage_count"), default=0):
            add_child("espionage_cell", "espionage", {"intelligence_targets": _conflict_targets(values, "espionage_cell")}, [center[0] - 0.48, center[1] - 2.70, center[2] + 0.05], relation="observes", description=f"Conflict system {name} runs espionage.")
        if values.get("disaster_type") or _positive_int(values.get("disaster_response_count") or values.get("disaster_count"), default=0):
            add_child("disaster_response", "disaster_response", {"disaster_type": values.get("disaster_type") or "conflict_relief"}, [center[0] + 0.48, center[1] - 2.70, center[2] + 0.05], relation="responds_to", description=f"Conflict system {name} includes disaster response.")

    elif construct == "strategic_objective":
        add_child("war_plan", "war_plan", {"plan": kind, "objectives": [kind]}, [center[0] - 0.34, center[1] + 0.42, center[2] + 0.04], relation="drives", description=f"Strategic objective {name} drives a war plan.")
        add_child("production_strategy", "production_strategy", {"strategic_goal": kind, "priorities": [kind]}, [center[0], center[1] + 0.42, center[2] + 0.04], relation="requires", description=f"Strategic objective {name} requires production strategy.")
        add_child("world_metric", "objective_metric", {"metric": "objective_progress", "metric_value": values.get("progress") or values.get("priority") or 0.5}, [center[0] + 0.34, center[1] + 0.42, center[2] + 0.04], relation="reveals", description=f"Strategic objective {name} exposes progress.")

    elif construct == "war_plan":
        fronts = _conflict_fronts(values)[:8]
        for index, front in enumerate(fronts):
            add_child("battlefront", f"{front}_front", {"front": front, "battlefront": front}, [center[0] + (index - (len(fronts) - 1) / 2.0) * 0.54, center[1] + 0.50, center[2] + 0.04], relation="contains", description=f"War plan {name} contains battlefront {front}.")
        add_child("mobilization_order", "mobilization", {"mobilization_level": values.get("mobilization_level") or 0.75}, [center[0] - 0.42, center[1] - 0.32, center[2] + 0.04], relation="mobilizes", description=f"War plan {name} mobilizes production.")
        add_child("supply_route", "campaign_route", {"route_type": kind, "goods": values.get("goods") or ["supplies"]}, [center[0], center[1] - 0.32, center[2] + 0.04], relation="routes_to", description=f"War plan {name} creates campaign supply route.")
        add_child("sabotage_target", "sabotage_target", {"sabotage_target": kind, "severity": values.get("sabotage_risk") or 0.45}, [center[0] + 0.42, center[1] - 0.32, center[2] + 0.04], relation="risks", description=f"War plan {name} exposes sabotage targets.")
        add_child("readiness_level", "readiness", {"readiness": values.get("readiness") or 0.72}, [center[0], center[1] - 0.86, center[2] + 0.04], relation="reveals", description=f"War plan {name} tracks readiness.")

    elif construct == "battlefront":
        add_child("territory_influence", "territory", {"territory": kind}, [center[0] - 0.42, center[1] + 0.42, center[2] + 0.04], relation="contests", description=f"Battlefront {name} contests territory.")
        add_child("faction_pressure", "pressure", {"pressure_type": kind}, [center[0], center[1] + 0.42, center[2] + 0.04], relation="pressures", description=f"Battlefront {name} creates faction pressure.")
        add_child("supply_route", "supply_route", {"route_type": kind}, [center[0] + 0.42, center[1] + 0.42, center[2] + 0.04], relation="routes_to", description=f"Battlefront {name} needs supply.")
        add_child("hazard_field", "hazard", {"hazard_type": "battlefront", "hazard_level": values.get("hazard_level") or values.get("escalation_level") or 0.5}, [center[0], center[1] - 0.36, center[2] + 0.04], relation="reveals", description=f"Battlefront {name} creates hazard.")

    elif construct == "escalation_ladder":
        steps = _conflict_terms(values, "escalation_ladder")[:10]
        for index, step in enumerate(steps):
            add_child("diplomatic_demand", f"{step}_demand", {"demand": step}, [center[0] + (index - (len(steps) - 1) / 2.0) * 0.42, center[1] + 0.44, center[2] + 0.04], relation="escalates_to", description=f"Escalation ladder {name} includes {step}.")
        add_child("sanction", "sanction", {"sanction": kind}, [center[0] - 0.26, center[1] - 0.38, center[2] + 0.04], relation="pressures", description=f"Escalation ladder {name} can trigger sanction.")
        add_child("world_metric", "escalation_metric", {"metric": "escalation_level", "metric_value": values.get("escalation_level") or values.get("escalation") or 0.45}, [center[0] + 0.26, center[1] - 0.38, center[2] + 0.04], relation="reveals", description=f"Escalation ladder {name} exposes escalation.")
        if _number(values.get("escalation_level") or values.get("escalation"), default=0.45) >= 0.75:
            add_child("war_plan", "war_plan", {"plan": kind}, [center[0], center[1] - 0.86, center[2] + 0.04], relation="escalates", description=f"Escalation ladder {name} can trigger war plan.")

    elif construct == "treaty":
        add_child("diplomacy_state", "diplomacy", {"diplomacy": "treaty", "stance": kind}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="sets", description=f"Treaty {name} sets diplomacy state.")
        add_child("trade_policy", "trade_policy", {"trade_type": kind, "policy": "treaty_trade"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="opens", description=f"Treaty {name} changes trade policy.")
        add_child("world_metric", "stability_metric", {"metric": "treaty_stability", "metric_value": values.get("stability") or 0.65}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="reveals", description=f"Treaty {name} exposes stability.")

    elif construct == "ceasefire":
        add_child("treaty", "ceasefire_terms", {"treaty_type": "ceasefire", "treaty_terms": _conflict_terms(values, "ceasefire")}, [center[0] - 0.30, center[1] + 0.40, center[2] + 0.04], relation="formalizes", description=f"Ceasefire {name} formalizes terms.")
        add_child("negotiation_channel", "channel", {"negotiation": "ceasefire"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="opens", description=f"Ceasefire {name} opens negotiation.")
        add_child("world_metric", "ceasefire_metric", {"metric": "ceasefire_integrity", "metric_value": values.get("integrity") or 0.7}, [center[0] + 0.30, center[1] + 0.40, center[2] + 0.04], relation="reveals", description=f"Ceasefire {name} exposes integrity.")

    elif construct == "alliance":
        add_child("diplomacy_state", "diplomacy", {"diplomacy": "alliance", "stance": kind}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="binds", description=f"Alliance {name} binds factions.")
        add_child("supply_chain", "shared_supply", {"goods": values.get("goods") or ["supplies"], "chain_type": "alliance_support"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="shares", description=f"Alliance {name} shares supply.")
        add_child("readiness_level", "readiness", {"readiness": values.get("readiness") or 0.68}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="reveals", description=f"Alliance {name} exposes coalition readiness.")

    elif construct == "rival_claim":
        targets = _conflict_targets(values, "rival_claim")[:8]
        for index, target in enumerate(targets):
            add_child("resource_claim", f"{target}_claim", {"resource_type": target, "land_owner": values.get("faction") or name}, [center[0] + (index - (len(targets) - 1) / 2.0) * 0.36, center[1] + 0.42, center[2] + 0.04], relation="claims", description=f"Rival claim {name} contests {target}.")
        add_child("territory_influence", "territory", {"territory": kind}, [center[0] - 0.26, center[1] - 0.36, center[2] + 0.04], relation="contests", description=f"Rival claim {name} changes territory influence.")
        add_child("diplomatic_demand", "demand", {"demand": kind}, [center[0] + 0.26, center[1] - 0.36, center[2] + 0.04], relation="pressures", description=f"Rival claim {name} becomes a diplomatic demand.")

    elif construct == "diplomatic_demand":
        add_child("negotiation_channel", "channel", {"negotiation": kind}, [center[0] - 0.26, center[1] + 0.38, center[2] + 0.04], relation="opens", description=f"Diplomatic demand {name} opens negotiation.")
        add_child("world_metric", "demand_metric", {"metric": "demand_pressure", "metric_value": values.get("pressure") or values.get("escalation_level") or 0.45}, [center[0] + 0.26, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Diplomatic demand {name} exposes pressure.")
        if _number(values.get("escalation_level") or values.get("pressure"), default=0.45) > 0.55:
            add_child("sanction", "sanction", {"sanction": kind}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="pressures", description=f"Diplomatic demand {name} can escalate to sanction.")

    elif construct == "negotiation_channel":
        add_child("diplomacy_state", "diplomacy", {"diplomacy": "negotiation", "stance": kind}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="sets", description=f"Negotiation channel {name} sets diplomacy state.")
        add_child("social_relation", "relation", {"relation_type": kind, "relationship": "negotiation"}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="connects", description=f"Negotiation channel {name} connects faction relations.")
        add_child("world_metric", "negotiation_metric", {"metric": "negotiation_progress", "metric_value": values.get("progress") or 0.5}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Negotiation channel {name} exposes progress.")

    elif construct == "sanction":
        targets = _conflict_targets(values, "sanction")[:8]
        for index, target in enumerate(targets):
            add_child("trade_embargo", f"{target}_embargo", {"target": target, "embargo_targets": [target]}, [center[0] + (index - (len(targets) - 1) / 2.0) * 0.34, center[1] + 0.40, center[2] + 0.04], relation="blocks", description=f"Sanction {name} embargoes {target}.")
        add_child("bottleneck", "economic_bottleneck", {"bottleneck_type": kind, "severity": values.get("severity") or 0.5}, [center[0] - 0.24, center[1] - 0.34, center[2] + 0.04], relation="blocks", description=f"Sanction {name} creates economic bottleneck.")
        add_child("world_metric", "sanction_metric", {"metric": "sanction_pressure", "metric_value": values.get("pressure") or values.get("severity") or 0.5}, [center[0] + 0.24, center[1] - 0.34, center[2] + 0.04], relation="reveals", description=f"Sanction {name} exposes pressure.")

    elif construct == "espionage_cell":
        targets = _conflict_targets(values, "espionage_cell")[:8]
        for index, target in enumerate(targets):
            add_child("covert_operation", f"{target}_operation", {"operation": target, "operations": [target]}, [center[0] + (index - (len(targets) - 1) / 2.0) * 0.38, center[1] + 0.42, center[2] + 0.04], relation="runs", description=f"Espionage cell {name} runs operation against {target}.")
        add_child("sensor_grid", "intelligence_grid", {"sensor_type": "intelligence", "coverage": values.get("coverage") or 0.65}, [center[0] - 0.26, center[1] - 0.36, center[2] + 0.04], relation="observes", description=f"Espionage cell {name} operates an intelligence grid.")
        add_child("sabotage_target", "sabotage_target", {"sabotage_target": kind}, [center[0] + 0.26, center[1] - 0.36, center[2] + 0.04], relation="targets", description=f"Espionage cell {name} identifies sabotage target.")

    elif construct == "covert_operation":
        add_child("sabotage_target", "sabotage", {"sabotage_target": kind, "severity": values.get("severity") or 0.45}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="targets", description=f"Covert operation {name} targets sabotage.")
        add_child("failure_mode", "failure", {"failure_type": kind, "failure_rate": values.get("failure_rate") or 0.2}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="causes", description=f"Covert operation {name} can cause failure.")
        add_child("world_metric", "operation_metric", {"metric": "operation_risk", "metric_value": values.get("risk") or 0.45}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Covert operation {name} exposes risk.")

    elif construct == "disaster_response":
        add_child("emergency_order", "emergency_order", {"emergency_level": values.get("emergency_level") or values.get("severity") or 0.55}, [center[0] - 0.36, center[1] + 0.42, center[2] + 0.04], relation="orders", description=f"Disaster response {name} issues emergency order.")
        add_child("supply_chain", "relief_supply", {"goods": values.get("goods") or ["medicine", "food", "fuel"], "chain_type": "relief"}, [center[0], center[1] + 0.42, center[2] + 0.04], relation="routes_to", description=f"Disaster response {name} creates relief supply.")
        add_child("resource_flow", "relief_flow", {"resource_type": kind, "flow_type": "relief"}, [center[0] + 0.36, center[1] + 0.42, center[2] + 0.04], relation="routes_to", description=f"Disaster response {name} routes relief flow.")
        add_child("readiness_level", "readiness", {"readiness": values.get("readiness") or 0.6}, [center[0], center[1] - 0.36, center[2] + 0.04], relation="reveals", description=f"Disaster response {name} tracks readiness.")

    elif construct == "emergency_order":
        add_child("policy_rule", "policy", {"policy": kind}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="enacts", description=f"Emergency order {name} enacts policy.")
        if _number(values.get("emergency_level") or values.get("severity"), default=0.4) >= 0.55:
            add_child("mobilization_order", "mobilization", {"mobilization_level": values.get("emergency_level") or 0.65}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="mobilizes", description=f"Emergency order {name} mobilizes response.")
        else:
            add_child("rationing_policy", "rationing", {"rationing": True, "ration_rate": values.get("ration_rate") or 0.3}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="constrains", description=f"Emergency order {name} enables rationing.")
        add_child("world_metric", "emergency_metric", {"metric": "emergency_level", "metric_value": values.get("emergency_level") or values.get("severity") or 0.4}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Emergency order {name} exposes emergency level.")

    return objects, relationships


