def _operational_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _OPERATIONAL_KIND_DEFAULTS.get(construct, construct)
    for key in _OPERATIONAL_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _operational_core_name(name: str, construct: str) -> str:
    return f"{name}_{_OPERATIONAL_CORE_SUFFIXES.get(construct, 'operational_core')}"


def _operational_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "operational_plan":
        return [max(2.8, _number(values.get("width"), default=5.0)), max(1.8, _number(values.get("depth"), default=3.0)), 0.24]
    if construct in {"order_queue", "construction_queue", "crew_roster"}:
        return [1.08, 0.66, 0.18]
    if construct in {"patrol_order", "convoy_order", "convoy_route"}:
        return [1.35, 0.18, 0.10]
    return [0.48, 0.30, 0.12]


def _operational_orders(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("orders", "world_orders", "tasks"), default=["patrol", "convoy", "repair"])


def _operational_tasks(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("tasks", "assignments", "work_items"), default=["stage", "execute", "report"])


def _operational_crews(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("crews", "teams", "assignees"), default=["crew_alpha"])


def _operational_routes(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("routes", "convoys", "patrols"), default=["main_route"])


def _operational_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    orders = _operational_orders(values)
    tasks = _operational_tasks(values)
    crews = _operational_crews(values)
    routes = _operational_routes(values)
    progress = _number(values.get("progress") or values.get("completion"), default=0.0)
    state: dict[str, Any] = {
        construct: name,
        "operational_construct": construct,
        "operational_kind": kind,
        "action": _snake_id(values.get("action") or _OPERATIONAL_ACTIONS.get(construct), "run_operational"),
        f"{construct}_count": 1,
        "operational_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "operational_execution",
        "enabled": not _disabled(values.get("enabled", True)),
        "orders": orders,
        "tasks": tasks,
        "crews": crews,
        "routes": routes,
        "priority_level": _number(values.get("priority_level") or values.get("priority"), default=0.5),
        "progress": progress,
        "completion": progress,
        "crew_size": _positive_int(values.get("crew_size"), default=4),
        "deadline": _number(values.get("deadline"), default=0.0),
        "duration": _number(values.get("duration"), default=1.0),
        "queue_policy": _surface_marker_value(values, "queue_policy", fallback="priority"),
    }
    if construct == "operational_plan":
        state.update({"order_queue_count": 1, "world_order_count": len(orders), "scheduled_action_count": 1, "crew_roster_count": 1, "mission_order_count": 1})
    elif construct == "order_queue":
        state.update({"world_order_count": len(orders), "scheduled_action_count": len(orders), "world_metric_count": 1})
    elif construct == "world_order":
        state.update({"scheduled_action_count": 1, "task_assignment_count": 1, "scene_state_count": 1, "world_metric_count": 1})
    elif construct == "patrol_order":
        state.update({"patrol_route_count": 1, "schedule_count": 1, "task_assignment_count": 1, "world_metric_count": 1})
    elif construct == "convoy_order":
        state.update({"convoy_route_count": 1, "supply_chain_count": 1, "task_assignment_count": 1, "world_metric_count": 1})
    elif construct == "construction_order":
        state.update({"construction_queue_count": 1, "crew_roster_count": 1, "resource_flow_count": 1, "world_metric_count": 1})
    elif construct == "repair_order":
        state.update({"repair_crew_count": 1, "maintenance_plan_count": 1, "repair_schedule_count": 1, "world_metric_count": 1})
    elif construct == "relief_order":
        state.update({"relief_team_count": 1, "relief_order_count": 1, "supply_chain_count": 1, "resource_flow_count": 1, "world_metric_count": 1})
    elif construct == "mission_order":
        state.update({"mission_count": 1, "objective_count": len(tasks), "task_assignment_count": len(tasks), "scheduled_action_count": 1})
    elif construct == "scheduled_action":
        state.update({"timer_count": 1, "action_count": 1, "scene_state_count": 1})
    elif construct == "task_assignment":
        state.update({"crew_roster_count": 1, "world_metric_count": 1})
    elif construct == "crew_roster":
        state.update({"crew_count": len(crews), "population_group_count": len(crews), "labor_system_count": 1})
    elif construct == "convoy_route":
        state.update({"supply_route_count": 1, "transport_leg_count": len(routes), "resource_flow_count": 1})
    elif construct == "construction_queue":
        state.update({"construction_order_count": len(tasks), "resource_flow_count": 1, "throughput_rule_count": 1})
    elif construct == "repair_crew":
        state.update({"repair_order_count": 1, "repair_schedule_count": 1, "maintenance_plan_count": 1})
    elif construct == "relief_team":
        state.update({"relief_order_count": 1, "disaster_response_count": 1, "supply_chain_count": 1})
    return state


def _operational_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _OPERATIONAL_ACTIONS.get(construct), "run_operational")}
    target = _surface_marker_value(values, "target", "order", "task", "route", "crew", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _operational_child_core_name(name: str, construct: str) -> str:
    if construct in _OPERATIONAL_CORE_SUFFIXES:
        return _operational_core_name(name, construct)
    if construct == "schedule":
        return f"{name}_schedule_core"
    if construct == "patrol_route":
        return f"{name}_patrol_core"
    if construct == "timer":
        return f"{name}_timer_core"
    if construct == "action":
        return f"{name}_action_core"
    if construct == "scene_state":
        return f"{name}_scene_state_core"
    if construct == "mission":
        return f"{name}_mission_core"
    if construct == "objective":
        return f"{name}_objective_core"
    return _faction_ai_child_core_name(name, construct)


def _expand_operational_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _OPERATIONAL_CORE_SUFFIXES:
        return _expand_operational_execution_macro(node, construct=construct)
    if construct == "schedule":
        return _expand_schedule_macro(node)
    if construct == "patrol_route":
        return _expand_patrol_route_macro(node)
    if construct == "timer":
        return _expand_timer_macro(node)
    if construct == "action":
        return _expand_action_macro(node)
    if construct == "scene_state":
        return _expand_scene_state_macro(node)
    if construct in {"mission", "objective"}:
        return _expand_mission_rule_macro(node, construct=construct)
    return _expand_faction_ai_child_macro(node, construct)


def _expand_operational_execution_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _operational_kind(values, construct)
    depth = max(0, int(_number(values.get("_operational_depth"), default=0.0)))
    core_name = _operational_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_operational_scale(values, construct),
        state=_operational_state(values, construct, name, kind),
        tags=[construct, kind, "operational_execution", "orders", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_OPERATIONAL_ACTIONS.get(construct), "run_operational"): _operational_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_OPERATIONAL_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "supports", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_operational_depth"] = depth + 1
        child_values["position"] = list(position)
        child_node = {"node_type": "scene_object", "name": child_name, "role": _OPERATIONAL_ROLES.get(child_construct, _FACTION_AI_ROLES.get(child_construct, "environment_structure")), "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_operational_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _operational_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    if construct == "operational_plan":
        add_child("order_queue", "queue", {"orders": _operational_orders(values)}, [center[0] - 0.58, center[1] + 0.86, center[2] + 0.05], relation="queues", description=f"Operational plan {name} queues orders.")
        add_child("crew_roster", "crews", {"crews": _operational_crews(values)}, [center[0], center[1] + 0.86, center[2] + 0.05], relation="assigns", description=f"Operational plan {name} assigns crews.")
        add_child("scheduled_action", "schedule", {"schedule": values.get("schedule") or "next_tick"}, [center[0] + 0.58, center[1] + 0.86, center[2] + 0.05], relation="schedules", description=f"Operational plan {name} schedules execution.")
        for index, order in enumerate(_operational_orders(values)[:8]):
            add_child("world_order", f"{order}_order", {"order": order, "task": order}, [center[0] + (index - 3.5) * 0.32, center[1] + 0.18, center[2] + 0.05], relation="contains", description=f"Operational plan {name} contains order {order}.")
        add_child("mission_order", "mission", {"mission": kind, "tasks": _operational_tasks(values)}, [center[0], center[1] - 0.62, center[2] + 0.05], relation="drives", description=f"Operational plan {name} drives mission execution.")

    elif construct == "order_queue":
        for index, order in enumerate(_operational_orders(values)[:10]):
            child_construct = {"patrol": "patrol_order", "convoy": "convoy_order", "construct": "construction_order", "construction": "construction_order", "repair": "repair_order", "relief": "relief_order", "mission": "mission_order"}.get(order, "world_order")
            add_child(child_construct, order, {"order": order, "task": order}, [center[0] + (index - 4.5) * 0.32, center[1] + 0.42, center[2] + 0.04], relation="queues", description=f"Order queue {name} queues {order}.")
        add_child("world_metric", "queue_metric", {"metric": "queue_depth", "metric_value": len(_operational_orders(values))}, [center[0], center[1] - 0.36, center[2] + 0.04], relation="reveals", description=f"Order queue {name} exposes queue depth.")

    elif construct == "world_order":
        add_child("scheduled_action", "schedule", {"action": kind}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="schedules", description=f"World order {name} schedules action.")
        add_child("task_assignment", "task", {"task": kind}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="assigns", description=f"World order {name} assigns task.")
        add_child("scene_state", "state", {"state": kind, "state_value": "ordered"}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="mutates", description=f"World order {name} changes scene state.")

    elif construct == "patrol_order":
        add_child("patrol_route", "route", {"route": kind, "patrol_route": kind}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="routes_to", description=f"Patrol order {name} creates patrol route.")
        add_child("schedule", "schedule", {"schedule": values.get("schedule") or "patrol_shift"}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="schedules", description=f"Patrol order {name} schedules patrol.")
        add_child("task_assignment", "assignment", {"task": "patrol"}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="assigns", description=f"Patrol order {name} assigns patrol task.")

    elif construct == "convoy_order":
        add_child("convoy_route", "route", {"route": kind}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="routes_to", description=f"Convoy order {name} creates convoy route.")
        add_child("supply_chain", "supply", {"chain_type": kind, "goods": values.get("supplies") or values.get("goods") or ["supplies"]}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="feeds", description=f"Convoy order {name} feeds supply chain.")
        add_child("task_assignment", "assignment", {"task": "convoy"}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="assigns", description=f"Convoy order {name} assigns convoy task.")

    elif construct == "construction_order":
        add_child("construction_queue", "queue", {"tasks": _operational_tasks(values)}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="queues", description=f"Construction order {name} queues construction.")
        add_child("crew_roster", "crew", {"crews": _operational_crews(values)}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="assigns", description=f"Construction order {name} assigns crew.")
        add_child("resource_flow", "materials", {"resource_type": "materials"}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="routes_to", description=f"Construction order {name} routes materials.")

    elif construct == "repair_order":
        add_child("repair_crew", "crew", {"repair": kind}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="dispatches", description=f"Repair order {name} dispatches repair crew.")
        add_child("maintenance_plan", "maintenance", {"maintenance": kind}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="maintains", description=f"Repair order {name} links maintenance plan.")
        add_child("repair_schedule", "schedule", {"repair": kind}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="schedules", description=f"Repair order {name} schedules repairs.")

    elif construct == "relief_order":
        add_child("relief_team", "team", {"relief": kind}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="dispatches", description=f"Relief order {name} dispatches relief team.")
        add_child("supply_chain", "relief_supply", {"chain_type": "relief", "goods": values.get("supplies") or ["food", "medicine"]}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="feeds", description=f"Relief order {name} creates relief supply.")
        add_child("resource_flow", "relief_flow", {"resource_type": kind}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="routes_to", description=f"Relief order {name} routes relief flow.")

    elif construct == "mission_order":
        add_child("mission", "mission", {"mission_type": kind, "objective_steps": _operational_tasks(values)}, [center[0] - 0.30, center[1] + 0.40, center[2] + 0.04], relation="starts", description=f"Mission order {name} starts mission.")
        for index, task in enumerate(_operational_tasks(values)[:6]):
            add_child("task_assignment", f"{task}_assignment", {"task": task}, [center[0] + (index - 2.5) * 0.28, center[1] - 0.10, center[2] + 0.04], relation="assigns", description=f"Mission order {name} assigns {task}.")
        add_child("scheduled_action", "schedule", {"action": kind}, [center[0] + 0.30, center[1] + 0.40, center[2] + 0.04], relation="schedules", description=f"Mission order {name} schedules mission.")

    elif construct == "scheduled_action":
        add_child("timer", "timer", {"duration": values.get("duration") or 1.0}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="triggers", description=f"Scheduled action {name} uses timer.")
        add_child("action", "action", {"action": kind}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="runs", description=f"Scheduled action {name} runs action.")
        add_child("scene_state", "state", {"state": kind, "state_value": "scheduled"}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="mutates", description=f"Scheduled action {name} updates state.")

    elif construct == "task_assignment":
        add_child("crew_roster", "crew", {"crews": _operational_crews(values)}, [center[0] - 0.24, center[1] + 0.36, center[2] + 0.04], relation="assigns", description=f"Task assignment {name} assigns crew.")
        add_child("world_metric", "assignment_metric", {"metric": "task_progress", "metric_value": values.get("progress") or 0.0}, [center[0] + 0.24, center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"Task assignment {name} exposes task progress.")

    elif construct == "crew_roster":
        crews = _operational_crews(values)[:10]
        for index, crew in enumerate(crews):
            add_child("population_group", f"{crew}_group", {"group_type": crew, "role": crew}, [center[0] + (index - (len(crews) - 1) / 2.0) * 0.32, center[1] + 0.38, center[2] + 0.04], relation="contains", description=f"Crew roster {name} contains {crew}.")
        add_child("labor_system", "labor", {"labor_type": kind, "jobs": crews}, [center[0], center[1] - 0.36, center[2] + 0.04], relation="assigns", description=f"Crew roster {name} assigns labor.")

    elif construct == "convoy_route":
        add_child("supply_route", "supply_route", {"route_type": kind}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="routes_to", description=f"Convoy route {name} maps supply route.")
        add_child("transport_leg", "transport_leg", {"mode": values.get("mode") or "convoy"}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="contains", description=f"Convoy route {name} contains transport leg.")
        add_child("resource_flow", "flow", {"resource_type": values.get("resource") or "supplies"}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="routes_to", description=f"Convoy route {name} carries resource flow.")

    elif construct == "construction_queue":
        for index, task in enumerate(_operational_tasks(values)[:8]):
            add_child("construction_order", f"{task}_order", {"worksite": task, "task": task}, [center[0] + (index - 3.5) * 0.30, center[1] + 0.38, center[2] + 0.04], relation="queues", description=f"Construction queue {name} queues {task}.")
        add_child("throughput_rule", "throughput", {"rule_type": kind}, [center[0], center[1] - 0.36, center[2] + 0.04], relation="constrains", description=f"Construction queue {name} controls throughput.")

    elif construct == "repair_crew":
        add_child("repair_schedule", "schedule", {"repair": kind}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="schedules", description=f"Repair crew {name} follows repair schedule.")
        add_child("maintenance_plan", "maintenance", {"maintenance": kind}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="maintains", description=f"Repair crew {name} supports maintenance.")
        add_child("task_assignment", "assignment", {"task": "repair"}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="assigns", description=f"Repair crew {name} receives assignment.")

    elif construct == "relief_team":
        add_child("disaster_response", "response", {"disaster_type": kind}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="responds_to", description=f"Relief team {name} supports disaster response.")
        add_child("relief_order", "relief_order", {"relief": kind}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="executes", description=f"Relief team {name} executes relief order.")
        add_child("supply_chain", "relief_supply", {"chain_type": "relief", "goods": values.get("supplies") or ["relief"]}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="feeds", description=f"Relief team {name} consumes relief supply.")

    return objects, relationships


