def _evolution_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _EVOLUTION_KIND_DEFAULTS.get(construct, construct)
    for key in _EVOLUTION_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _evolution_core_name(name: str, construct: str) -> str:
    return f"{name}_{_EVOLUTION_CORE_SUFFIXES.get(construct, 'evolution_core')}"


def _evolution_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "settlement_evolution":
        return [max(3.2, _number(values.get("width"), default=6.0)), max(2.4, _number(values.get("depth"), default=4.0)), 0.24]
    if construct in {"expansion_zone", "district_upgrade", "renovation_project"}:
        return [1.50, 0.96, 0.18]
    if construct in {"growth_phase", "construction_stage", "upgrade_plan", "worksite"}:
        return [1.08, 0.66, 0.18]
    if construct == "material_delivery":
        return [1.35, 0.18, 0.10]
    return [0.52, 0.34, 0.12]


def _evolution_phases(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("phases", "growth_phases", "stages"), default=["survey", "foundation", "buildout"])


def _evolution_zones(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("zones", "expansion_zones", "districts"), default=["new_quarter"])


def _evolution_projects(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("projects", "upgrades", "buildings"), default=["housing", "utilities"])


def _evolution_materials(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("materials", "materials_required", "construction_materials", "resources_required", "supplies"), default=["timber", "stone", "fixtures"])


def _evolution_crews(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("staff_roles", "crews", "teams", "workers"), default=["builders", "inspectors"])


def _evolution_occupants(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("occupants", "occupancy", "population_groups"), default=["residents"])


def _evolution_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    phases = _evolution_phases(values)
    zones = _evolution_zones(values)
    projects = _evolution_projects(values)
    materials = _evolution_materials(values)
    crews = _evolution_crews(values)
    occupants = _evolution_occupants(values)
    progress = _number(values.get("build_progress") or values.get("progress") or values.get("completion"), default=0.0)
    damage_level = _number(values.get("damage_level") or values.get("damage"), default=0.0)
    state: dict[str, Any] = {
        construct: name,
        "evolution_construct": construct,
        "evolution_kind": kind,
        "action": _snake_id(values.get("action") or _EVOLUTION_ACTIONS.get(construct), "advance_evolution"),
        f"{construct}_count": 1,
        "evolution_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "settlement_evolution",
        "enabled": not _disabled(values.get("enabled", True)),
        "phases": phases,
        "growth_phases": phases,
        "zones": zones,
        "expansion_zones": zones,
        "projects": projects,
        "upgrades": projects,
        "materials": materials,
        "materials_required": materials,
        "construction_materials": materials,
        "staff_roles": crews,
        "crews": crews,
        "occupants": occupants,
        "occupancy": occupants,
        "capacity": _positive_int(values.get("capacity"), default=max(1, len(occupants)) * 12),
        "damage_level": damage_level,
        "repair_priority": _number(values.get("repair_priority") or values.get("priority"), default=0.5),
        "permit_state": _surface_marker_value(values, "permit_state", fallback="submitted"),
        "inspection_state": _surface_marker_value(values, "inspection_state", fallback="pending"),
        "build_progress": progress,
        "progress": progress,
        "upgrade_level": _positive_int(values.get("upgrade_level"), default=1),
        "construction_style": _surface_marker_value(values, "construction_style", "style", fallback="practical"),
        "renovation_theme": _surface_marker_value(values, "renovation_theme", "theme", fallback=kind),
        "demolition_reason": _surface_marker_value(values, "demolition_reason", "reason", fallback="obsolete"),
    }
    if construct == "settlement_evolution":
        state.update({
            "growth_phase_count": len(phases),
            "expansion_zone_count": len(zones),
            "construction_stage_count": len(phases),
            "upgrade_plan_count": 1,
            "material_delivery_count": 1,
            "staffing_plan_count": 1,
            "occupancy_plan_count": 1,
            "damage_repair_plan_count": 1 if damage_level > 0 else 0,
        })
    elif construct == "growth_phase":
        state.update({"construction_stage_count": 1, "scheduled_action_count": 1, "world_metric_count": 1})
    elif construct == "expansion_zone":
        state.update({"district_count": 1, "district_upgrade_count": 1, "construction_order_count": 1, "resource_flow_count": 1})
    elif construct == "construction_stage":
        state.update({"worksite_count": 1, "material_delivery_count": 1, "task_assignment_count": 1, "scheduled_action_count": 1})
    elif construct == "upgrade_plan":
        state.update({"district_upgrade_count": 1, "building_upgrade_count": 1, "infrastructure_upgrade_count": 1})
    elif construct == "district_upgrade":
        state.update({"construction_queue_count": 1, "infrastructure_upgrade_count": 1, "world_metric_count": 1})
    elif construct == "building_upgrade":
        state.update({"construction_order_count": 1, "occupancy_plan_count": 1, "world_metric_count": 1})
    elif construct == "infrastructure_upgrade":
        state.update({"construction_order_count": 1, "resource_flow_count": 1, "service_network_count": 1})
    elif construct == "material_delivery":
        state.update({"convoy_order_count": 1, "resource_flow_count": 1, "stockpile_count": 1})
    elif construct == "staffing_plan":
        state.update({"crew_roster_count": 1, "labor_system_count": 1, "task_assignment_count": 1})
    elif construct == "occupancy_plan":
        state.update({"population_group_count": len(occupants), "room_cluster_count": 1, "world_metric_count": 1})
    elif construct == "worksite":
        state.update({"construction_order_count": 1, "crew_roster_count": 1, "hazard_field_count": 1})
    elif construct == "build_permit":
        state.update({"policy_rule_count": 1, "scheduled_action_count": 1, "world_metric_count": 1})
    elif construct == "damage_repair_plan":
        state.update({"repair_order_count": 1, "repair_crew_count": 1, "damage_state_count": 1})
    elif construct == "demolition_plan":
        state.update({"scheduled_action_count": 1, "debris_field_count": 1, "construction_queue_count": 1})
    elif construct == "renovation_project":
        state.update({"building_upgrade_count": 1, "material_delivery_count": 1, "occupancy_plan_count": 1})
    return state


def _evolution_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _EVOLUTION_ACTIONS.get(construct), "advance_evolution")}
    target = _surface_marker_value(values, "target", "district", "building", "worksite", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _evolution_child_core_name(name: str, construct: str) -> str:
    if construct in _EVOLUTION_CORE_SUFFIXES:
        return _evolution_core_name(name, construct)
    if construct == "district":
        return f"{name}_district_core"
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_evolution_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _EVOLUTION_CORE_SUFFIXES:
        return _expand_settlement_evolution_macro(node, construct=construct)
    if construct in _OPERATIONAL_CORE_SUFFIXES:
        return _expand_operational_execution_macro(node, construct=construct)
    if construct == "district":
        return _expand_district_macro(node)
    if construct == "room_cluster":
        return _expand_room_cluster_macro(node)
    if construct == "service_network":
        return _expand_service_network_macro(node)
    if construct in {"resource_flow", "world_metric", "hazard_field"}:
        return _expand_simulation_macro(node, construct=construct)
    if construct in {"stockpile", "supply_chain", "supply_route", "transport_leg"}:
        return _expand_logistics_macro(node, construct=construct)
    if construct in {"policy_rule", "labor_system", "population_group"}:
        return _expand_culture_macro(node, construct=construct)
    if construct in {"maintenance_plan", "repair_schedule"}:
        return _expand_production_strategy_macro(node, construct=construct)
    if construct == "damage_state":
        return _expand_damage_state_macro(node)
    if construct == "debris_field":
        return _expand_debris_field_macro(node)
    if construct == "scheduled_action":
        return _expand_operational_execution_macro(node, construct=construct)
    if construct == "task_assignment":
        return _expand_operational_execution_macro(node, construct=construct)
    if construct == "scene_state":
        return _expand_scene_state_macro(node)
    return _expand_operational_child_macro(node, construct)


def _expand_settlement_evolution_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _evolution_kind(values, construct)
    depth = max(0, int(_number(values.get("_evolution_depth"), default=0.0)))
    core_name = _evolution_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_evolution_scale(values, construct),
        state=_evolution_state(values, construct, name, kind),
        tags=[construct, kind, "settlement_evolution", "construction", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_EVOLUTION_ACTIONS.get(construct), "advance_evolution"): _evolution_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_EVOLUTION_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "supports", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_evolution_depth"] = depth + 1
        if child_construct in _OPERATIONAL_CORE_SUFFIXES:
            child_values["_operational_depth"] = max(2, int(_number(child_values.get("_operational_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _EVOLUTION_ROLES.get(child_construct, _OPERATIONAL_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_evolution_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _evolution_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    if construct == "settlement_evolution":
        phases = _evolution_phases(values)
        zones = _evolution_zones(values)
        for index, phase in enumerate(phases[:8]):
            add_child("growth_phase", phase, {"phase": phase, "build_progress": (index + 1) / max(1, len(phases))}, [center[0] + (index - (len(phases) - 1) / 2.0) * 0.44, center[1] + 0.96, center[2] + 0.05], relation="phases", description=f"Settlement evolution {name} includes growth phase {phase}.")
        for index, zone in enumerate(zones[:8]):
            add_child("expansion_zone", zone, {"zone": zone, "district": zone}, [center[0] + (index - (len(zones) - 1) / 2.0) * 0.52, center[1] + 0.24, center[2] + 0.05], relation="expands_into", description=f"Settlement evolution {name} opens expansion zone {zone}.")
        add_child("upgrade_plan", "upgrades", {"projects": _evolution_projects(values)}, [center[0] - 0.72, center[1] - 0.62, center[2] + 0.05], relation="upgrades", description=f"Settlement evolution {name} coordinates upgrades.")
        add_child("material_delivery", "materials", {"materials": _evolution_materials(values)}, [center[0] - 0.24, center[1] - 0.62, center[2] + 0.05], relation="supplies", description=f"Settlement evolution {name} routes construction materials.")
        add_child("staffing_plan", "staffing", {"staff_roles": _evolution_crews(values)}, [center[0] + 0.24, center[1] - 0.62, center[2] + 0.05], relation="staffs", description=f"Settlement evolution {name} assigns staffing.")
        add_child("occupancy_plan", "occupancy", {"occupants": _evolution_occupants(values)}, [center[0] + 0.72, center[1] - 0.62, center[2] + 0.05], relation="inhabits", description=f"Settlement evolution {name} plans occupancy.")
        if _number(values.get("damage_level") or values.get("damage"), default=0.0) > 0 and not _any_disabled(values, "repair", "damage_repair"):
            add_child("damage_repair_plan", "repair", {"repair_priority": values.get("repair_priority") or values.get("priority") or 0.75}, [center[0], center[1] - 1.04, center[2] + 0.05], relation="repairs", description=f"Settlement evolution {name} includes damage repair.")

    elif construct == "growth_phase":
        phase = kind
        add_child("construction_stage", "stage", {"stage": phase}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="contains", description=f"Growth phase {name} contains construction stage.")
        add_child("scheduled_action", "schedule", {"action": phase, "schedule": values.get("schedule") or "phase_tick"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="schedules", description=f"Growth phase {name} schedules phase work.")
        add_child("world_metric", "progress_metric", {"metric": "phase_progress", "metric_value": values.get("build_progress") or values.get("progress") or 0.0}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="reveals", description=f"Growth phase {name} exposes phase progress.")

    elif construct == "expansion_zone":
        add_child("district", "district", {"district_type": kind, "districts": [kind]}, [center[0] - 0.34, center[1] + 0.42, center[2] + 0.04], relation="contains", description=f"Expansion zone {name} creates district scaffold.")
        add_child("district_upgrade", "upgrade", {"district": kind, "upgrade": values.get("upgrade") or "capacity"}, [center[0], center[1] + 0.42, center[2] + 0.04], relation="upgrades", description=f"Expansion zone {name} applies district upgrade.")
        add_child("construction_order", "order", {"worksite": kind, "task": "zone_buildout"}, [center[0] + 0.34, center[1] + 0.42, center[2] + 0.04], relation="orders", description=f"Expansion zone {name} creates construction order.")
        add_child("resource_flow", "flow", {"resource_type": values.get("resource") or "materials"}, [center[0], center[1] - 0.32, center[2] + 0.04], relation="feeds", description=f"Expansion zone {name} receives resource flow.")

    elif construct == "construction_stage":
        add_child("worksite", "worksite", {"worksite": kind}, [center[0] - 0.36, center[1] + 0.40, center[2] + 0.04], relation="hosts", description=f"Construction stage {name} opens worksite.")
        add_child("material_delivery", "delivery", {"materials": _evolution_materials(values)}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="supplies", description=f"Construction stage {name} requests material delivery.")
        add_child("task_assignment", "assignment", {"task": kind, "crews": _evolution_crews(values)}, [center[0] + 0.36, center[1] + 0.40, center[2] + 0.04], relation="assigns", description=f"Construction stage {name} assigns tasks.")
        add_child("scheduled_action", "schedule", {"action": kind}, [center[0], center[1] - 0.32, center[2] + 0.04], relation="schedules", description=f"Construction stage {name} schedules work.")

    elif construct == "upgrade_plan":
        add_child("district_upgrade", "district", {"district": values.get("district") or "core"}, [center[0] - 0.38, center[1] + 0.40, center[2] + 0.04], relation="upgrades", description=f"Upgrade plan {name} upgrades district.")
        add_child("building_upgrade", "building", {"building": values.get("building") or "anchor"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="upgrades", description=f"Upgrade plan {name} upgrades building.")
        add_child("infrastructure_upgrade", "infrastructure", {"service": values.get("service") or "utilities"}, [center[0] + 0.38, center[1] + 0.40, center[2] + 0.04], relation="upgrades", description=f"Upgrade plan {name} upgrades infrastructure.")

    elif construct == "district_upgrade":
        add_child("construction_queue", "queue", {"tasks": _evolution_projects(values)}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="queues", description=f"District upgrade {name} queues construction.")
        add_child("infrastructure_upgrade", "service", {"service": values.get("service") or "utilities"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="services", description=f"District upgrade {name} upgrades infrastructure.")
        add_child("world_metric", "upgrade_metric", {"metric": "district_upgrade_level", "metric_value": values.get("upgrade_level") or 1}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="reveals", description=f"District upgrade {name} exposes upgrade level.")

    elif construct == "building_upgrade":
        add_child("construction_order", "order", {"worksite": kind, "task": "building_upgrade"}, [center[0] - 0.30, center[1] + 0.40, center[2] + 0.04], relation="orders", description=f"Building upgrade {name} creates construction order.")
        add_child("occupancy_plan", "occupancy", {"occupants": _evolution_occupants(values)}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="supports", description=f"Building upgrade {name} updates occupancy.")
        add_child("world_metric", "upgrade_metric", {"metric": "building_upgrade_level", "metric_value": values.get("upgrade_level") or 1}, [center[0] + 0.30, center[1] + 0.40, center[2] + 0.04], relation="reveals", description=f"Building upgrade {name} exposes upgrade level.")

    elif construct == "infrastructure_upgrade":
        add_child("construction_order", "order", {"worksite": kind, "task": "infrastructure_upgrade"}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="orders", description=f"Infrastructure upgrade {name} creates construction order.")
        add_child("resource_flow", "flow", {"resource_type": values.get("resource") or "service_parts"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="feeds", description=f"Infrastructure upgrade {name} receives resource flow.")
        add_child("service_network", "service", {"services": values.get("services") or [kind]}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="connects", description=f"Infrastructure upgrade {name} creates service network.")

    elif construct == "material_delivery":
        add_child("convoy_order", "convoy", {"materials": _evolution_materials(values), "goods": _evolution_materials(values)}, [center[0] - 0.34, center[1] + 0.36, center[2] + 0.04], relation="routes_to", description=f"Material delivery {name} creates convoy order.")
        add_child("resource_flow", "flow", {"resource_type": kind}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="carries", description=f"Material delivery {name} carries resource flow.")
        add_child("stockpile", "stockpile", {"goods": _evolution_materials(values), "capacity": values.get("capacity") or 12}, [center[0] + 0.34, center[1] + 0.36, center[2] + 0.04], relation="fills", description=f"Material delivery {name} fills stockpile.")

    elif construct == "staffing_plan":
        add_child("crew_roster", "crew", {"crews": _evolution_crews(values)}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="assigns", description=f"Staffing plan {name} assigns crew roster.")
        add_child("labor_system", "labor", {"jobs": _evolution_crews(values), "labor_type": kind}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="staffs", description=f"Staffing plan {name} defines labor.")
        add_child("task_assignment", "assignment", {"task": kind, "crews": _evolution_crews(values)}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="assigns", description=f"Staffing plan {name} assigns tasks.")

    elif construct == "occupancy_plan":
        occupants = _evolution_occupants(values)[:8]
        for index, occupant in enumerate(occupants):
            add_child("population_group", occupant, {"group_type": occupant, "role": occupant}, [center[0] + (index - (len(occupants) - 1) / 2.0) * 0.32, center[1] + 0.40, center[2] + 0.04], relation="houses", description=f"Occupancy plan {name} houses {occupant}.")
        add_child("room_cluster", "rooms", {"rooms": values.get("rooms") or max(1, len(occupants))}, [center[0] - 0.24, center[1] - 0.34, center[2] + 0.04], relation="uses", description=f"Occupancy plan {name} allocates rooms.")
        add_child("world_metric", "capacity_metric", {"metric": "occupancy_capacity", "metric_value": values.get("capacity") or len(occupants) * 12}, [center[0] + 0.24, center[1] - 0.34, center[2] + 0.04], relation="reveals", description=f"Occupancy plan {name} exposes capacity.")

    elif construct == "worksite":
        add_child("construction_order", "order", {"worksite": kind, "task": kind}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="orders", description=f"Worksite {name} creates construction order.")
        add_child("crew_roster", "crew", {"crews": _evolution_crews(values)}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="assigns", description=f"Worksite {name} assigns crew.")
        add_child("hazard_field", "hazards", {"hazard_type": values.get("hazard") or "construction"}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="marks", description=f"Worksite {name} marks construction hazards.")

    elif construct == "build_permit":
        add_child("policy_rule", "policy", {"policy": kind, "permit_state": values.get("permit_state") or "submitted"}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="authorizes", description=f"Build permit {name} defines policy rule.")
        add_child("scheduled_action", "inspection", {"action": "inspection", "schedule": values.get("inspection_state") or "pending"}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="schedules", description=f"Build permit {name} schedules inspection.")
        add_child("world_metric", "permit_metric", {"metric": "permit_progress", "metric_value": values.get("build_progress") or values.get("progress") or 0.0}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Build permit {name} exposes permit progress.")

    elif construct == "damage_repair_plan":
        add_child("repair_order", "repair_order", {"repair": kind, "priority": values.get("repair_priority") or values.get("priority") or 0.75}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="orders", description=f"Damage repair plan {name} creates repair order.")
        add_child("repair_crew", "crew", {"repair": kind, "crews": _evolution_crews(values)}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="dispatches", description=f"Damage repair plan {name} dispatches repair crew.")
        add_child("damage_state", "damage", {"damage_kind": kind, "damage_level": values.get("damage_level") or values.get("damage") or 0.5}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="repairs", description=f"Damage repair plan {name} tracks damage state.")

    elif construct == "demolition_plan":
        add_child("scheduled_action", "schedule", {"action": "demolition", "schedule": values.get("schedule") or "demolition_window"}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="schedules", description=f"Demolition plan {name} schedules demolition.")
        add_child("debris_field", "debris", {"debris_kind": kind, "debris_count": values.get("debris_count") or 6}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="creates", description=f"Demolition plan {name} creates debris field.")
        add_child("construction_queue", "clearance", {"tasks": ["isolate", "demolish", "clear"]}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="queues", description=f"Demolition plan {name} queues clearance.")

    elif construct == "renovation_project":
        add_child("building_upgrade", "building", {"renovation_theme": values.get("renovation_theme") or kind}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="upgrades", description=f"Renovation project {name} upgrades building.")
        add_child("material_delivery", "materials", {"materials": _evolution_materials(values)}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="supplies", description=f"Renovation project {name} delivers materials.")
        add_child("occupancy_plan", "occupancy", {"occupants": _evolution_occupants(values)}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="rehouses", description=f"Renovation project {name} plans occupancy.")

    return objects, relationships


