def _city_plan_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _CITY_PLAN_KIND_DEFAULTS.get(construct, construct)
    for key in _CITY_PLAN_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _city_plan_core_name(name: str, construct: str) -> str:
    return f"{name}_{_CITY_PLAN_CORE_SUFFIXES.get(construct, 'city_plan_core')}"


def _city_plan_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "city_plan":
        return [max(3.8, _number(values.get("width"), default=7.0)), max(2.8, _number(values.get("depth"), default=5.0)), 0.22]
    if construct == "district_site_plan":
        return [max(2.4, _number(values.get("district_width") or values.get("width"), default=4.2)), max(1.8, _number(values.get("district_depth") or values.get("depth"), default=3.2)), 0.20]
    if construct in {"parcel_grid", "block_plan", "zoning_district", "public_space_plan", "landscape_zone"}:
        return [1.42, 0.92, 0.16]
    if construct in {"street_hierarchy", "utility_corridor", "street_crossing", "traffic_flow", "service_flow"}:
        return [1.48, 0.20, 0.10]
    if construct in {"perimeter_plan", "security_gate"}:
        return [1.70, 0.22, 0.14]
    if construct == "growth_boundary":
        return [1.70, 0.18, 0.12]
    return [0.54, 0.34, 0.12]


def _city_zones(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("zones", "zoning_districts", "districts"), default=["residential", "commerce", "civic"])


def _city_parcels(values: Mapping[str, Any]) -> list[str]:
    explicit = _gameplay_name_list(values, ("parcels", "lots", "land_parcels"), default=[])
    if explicit:
        return explicit
    count = max(1, min(12, _positive_int(values.get("parcel_count") or values.get("lots"), default=4)))
    return [f"parcel_{index + 1:02d}" for index in range(count)]


def _city_blocks(values: Mapping[str, Any]) -> list[str]:
    explicit = _gameplay_name_list(values, ("blocks", "city_blocks"), default=[])
    if explicit:
        return explicit
    count = max(1, min(10, _positive_int(values.get("block_count") or values.get("blocks"), default=2)))
    return [f"block_{index + 1:02d}" for index in range(count)]


def _city_streets(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("street_levels", "road_types", "roads", "streets"), default=["arterial", "collector", "local"])


def _city_services(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("services", "civic_services", "utilities"), default=["water", "transit", "safety"])


def _city_dependencies(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("dependencies", "dependency_rules", "district_dependencies"), default=["housing_jobs", "services_growth"])


def _city_public_spaces(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("public_spaces", "parks", "plazas"), default=["central_park"])


def _district_compounds(values: Mapping[str, Any]) -> list[str]:
    explicit = _gameplay_name_list(values, ("district_compounds", "site_compounds", "compounds", "sites"), default=[])
    if explicit:
        return explicit[:12]
    count = max(1, min(12, _positive_int(values.get("compound_count") or values.get("site_compound_count"), default=2)))
    defaults = ["anchor_site", "support_site", "service_site", "civic_site", "market_site", "yard_site"]
    return defaults[:count]


def _district_crossings(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("street_crossings", "crossings", "crosswalks"), default=["main_crossing", "service_crossing"])


def _district_security_gates(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("security_gates", "gates", "access_points"), default=["front_gate", "service_gate"])


def _district_landscape_zones(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("landscape_zones", "landscape", "green_zones"), default=["shade_court", "stormwater_strip"])


def _district_traffic_routes(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("traffic_routes", "traffic_flows", "routes"), default=["visitor_loop", "dropoff_lane"])


def _district_service_routes(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("service_routes", "service_flows", "utility_routes"), default=["rear_service", "utility_spine"])


def _city_plan_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    zones = _city_zones(values)
    parcels = _city_parcels(values)
    blocks = _city_blocks(values)
    streets = _city_streets(values)
    services = _city_services(values)
    dependencies = _city_dependencies(values)
    public_spaces = _city_public_spaces(values)
    compounds = _district_compounds(values)
    crossings = _district_crossings(values)
    security_gates = _district_security_gates(values)
    landscape_zones = _district_landscape_zones(values)
    traffic_routes = _district_traffic_routes(values)
    service_routes = _district_service_routes(values)
    pressure_level = _number(values.get("pressure_level") or values.get("development_pressure"), default=0.5)
    district_controls = {
        "district_site_plan_count": 1 if construct == "district_site_plan" else 0,
        "site_compound_count": len(compounds) if construct == "district_site_plan" else 0,
        "block_plan_count": len(blocks) if construct == "district_site_plan" else 0,
        "street_crossing_count": len(crossings) if construct in {"district_site_plan", "street_crossing"} else 0,
        "perimeter_plan_count": 1 if construct in {"district_site_plan", "perimeter_plan"} else 0,
        "security_gate_count": len(security_gates) if construct in {"district_site_plan", "perimeter_plan", "security_gate"} else 0,
        "landscape_zone_count": len(landscape_zones) if construct in {"district_site_plan", "landscape_zone"} else 0,
        "traffic_flow_count": len(traffic_routes) if construct in {"district_site_plan", "traffic_flow", "street_crossing"} else 0,
        "service_flow_count": len(service_routes) if construct in {"district_site_plan", "service_flow"} else 0,
        "crosswalk_count": len(crossings) if construct in {"district_site_plan", "street_crossing"} else 0,
        "perimeter_count": max(4, len(security_gates) * 2) if construct in {"district_site_plan", "perimeter_plan"} else 0,
        "gate_count": len(security_gates) if construct in {"district_site_plan", "perimeter_plan", "security_gate"} else 0,
    }
    state: dict[str, Any] = {
        construct: name,
        "city_planning_construct": construct,
        "city_planning_kind": kind,
        "action": _snake_id(values.get("action") or _CITY_PLAN_ACTIONS.get(construct), "compose_city_plan"),
        f"{construct}_count": 1,
        "city_planning_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "city_planning",
        "enabled": not _disabled(values.get("enabled", True)),
        "zones": zones,
        "zoning_districts": zones,
        "zoning": _surface_marker_value(values, "zoning", fallback=kind),
        "density": _number(values.get("density"), default=0.55),
        "allowed_uses": _gameplay_name_list(values, ("allowed_uses", "uses"), default=zones),
        "parcel_count": len(parcels),
        "parcels": parcels,
        "lots": parcels,
        "subdivision_pattern": _surface_marker_value(values, "subdivision_pattern", fallback="walkable"),
        "block_count": len(blocks),
        "blocks": blocks,
        "city_blocks": blocks,
        "street_levels": streets,
        "road_types": streets,
        "transit_modes": _gameplay_name_list(values, ("transit_modes", "modes"), default=["walk", "bus"]),
        "services": services,
        "civic_services": services,
        "coverage_radius": _number(values.get("coverage_radius"), default=0.8),
        "coverage_threshold": _number(values.get("coverage_threshold"), default=0.72),
        "utilities": _gameplay_name_list(values, ("utilities", "corridors"), default=["water", "power"]),
        "corridors": _gameplay_name_list(values, ("corridors", "utility_corridors"), default=["main_spine"]),
        "public_spaces": public_spaces,
        "parks": public_spaces,
        "boundary_type": _surface_marker_value(values, "boundary_type", fallback="growth_boundary"),
        "growth_limit": _number(values.get("growth_limit"), default=1.0),
        "dependencies": dependencies,
        "dependency_rules": dependencies,
        "pressure_sources": _gameplay_name_list(values, ("pressure_sources", "drivers"), default=["population", "jobs"]),
        "pressure_level": pressure_level,
        "district_site_profile": kind if construct in _CITY_PLAN_CORE_SUFFIXES else "",
        "district_compounds": compounds,
        "district_blocks": blocks,
        "street_crossings": crossings,
        "perimeter_segments": [f"perimeter_{index + 1:02d}" for index in range(max(1, district_controls["perimeter_count"]))],
        "security_gates": security_gates,
        "landscape_zones": landscape_zones,
        "traffic_routes": traffic_routes,
        "service_routes": service_routes,
        "district_site_controls": district_controls,
    }
    if construct == "city_plan":
        state.update({
            "zoning_rule_count": 1,
            "zoning_district_count": len(zones),
            "parcel_grid_count": 1,
            "block_plan_count": len(blocks),
            "street_hierarchy_count": 1,
            "civic_service_plan_count": 1,
            "growth_boundary_count": 1,
            "district_dependency_count": len(dependencies),
            "development_pressure_count": 1,
        })
    elif construct == "zoning_rule":
        state.update({"policy_rule_count": 1, "zoning_district_count": len(zones), "world_metric_count": 1})
    elif construct == "zoning_district":
        state.update({"district_count": 1, "zoning_rule_count": 1, "development_pressure_count": 1})
    elif construct == "parcel_grid":
        state.update({"land_parcel_count": len(parcels), "parcel_subdivision_count": 1, "street_grid_count": 1})
    elif construct == "land_parcel":
        state.update({"build_permit_count": 1, "zoning_rule_count": 1, "development_pressure_count": 1})
    elif construct == "parcel_subdivision":
        state.update({"land_parcel_count": len(parcels), "block_plan_count": 1, "street_hierarchy_count": 1})
    elif construct == "block_plan":
        state.update({"parcel_grid_count": 1, "street_hierarchy_count": 1, "public_space_plan_count": 1, "service_coverage_count": 1})
    elif construct == "street_hierarchy":
        state.update({"street_grid_count": 1, "road_intersection_count": 1, "transit_node_count": 1})
    elif construct == "transit_node":
        state.update({"service_coverage_count": 1, "world_metric_count": 1})
    elif construct == "civic_service_plan":
        state.update({"service_coverage_count": len(services), "utility_corridor_count": 1, "staffing_plan_count": 1, "world_metric_count": 1})
    elif construct == "service_coverage":
        state.update({"service_network_count": 1, "resource_flow_count": 1, "world_metric_count": 1})
    elif construct == "utility_corridor":
        state.update({"service_network_count": 1, "resource_flow_count": 1, "street_hierarchy_count": 1})
    elif construct == "district_site_plan":
        state.update({
            **district_controls,
            "block_plan_count": len(blocks),
            "street_hierarchy_count": 1,
            "utility_corridor_count": 1,
            "site_compound_count": len(compounds),
            "public_space_plan_count": len(landscape_zones),
            "maintenance_access_count": len(service_routes),
            "access_sequence_count": 1,
            "public_entry_count": max(1, len(crossings)),
            "service_entry_count": max(1, len(service_routes)),
            "threshold_transition_count": max(1, len(crossings)),
            "entry_lobby_count": 1,
            "access_checkpoint_count": max(1, len(security_gates)),
            "loading_path_count": max(1, len(service_routes)),
            "wayfinding_node_count": max(1, len(compounds)),
        })
    elif construct == "street_crossing":
        state.update({**district_controls, "street_crossing_count": 1, "road_intersection_count": 1, "pedestrian_path_count": 1, "crosswalk_count": max(1, len(crossings)), "traffic_flow_count": 1})
    elif construct == "perimeter_plan":
        state.update({**district_controls, "perimeter_plan_count": 1, "perimeter_count": max(4, district_controls["perimeter_count"]), "security_gate_count": len(security_gates), "maintenance_access_count": 1})
    elif construct == "security_gate":
        state.update({**district_controls, "security_gate_count": 1, "traversal_gate_count": 1, "maintenance_access_count": 1, "control_panel_count": 1, "alarm_grid_count": 1})
    elif construct == "landscape_zone":
        state.update({**district_controls, "landscape_zone_count": 1, "public_space_plan_count": 1, "green_infrastructure_count": 1, "stormwater_system_count": 1, "material_zone_count": 1})
    elif construct == "traffic_flow":
        state.update({**district_controls, "traffic_flow_count": 1, "street_hierarchy_count": 1, "road_intersection_count": 1, "world_metric_count": 1})
    elif construct == "service_flow":
        state.update({**district_controls, "service_flow_count": 1, "utility_corridor_count": 1, "service_connection_count": len(service_routes), "maintenance_access_count": 1, "resource_flow_count": 1})
    elif construct == "public_space_plan":
        state.update({"district_count": 1, "service_coverage_count": 1, "world_metric_count": 1})
    elif construct == "growth_boundary":
        state.update({"zoning_rule_count": 1, "settlement_pressure_count": 1, "world_metric_count": 1})
    elif construct == "district_dependency":
        state.update({"service_coverage_count": 1, "resource_flow_count": 1, "world_metric_count": 1})
    elif construct == "development_pressure":
        state.update({"settlement_pressure_count": 1, "build_permit_count": 1, "world_metric_count": 1})
    return state


def _city_plan_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _CITY_PLAN_ACTIONS.get(construct), "compose_city_plan")}
    target = _surface_marker_value(values, "target", "district", "parcel", "service", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _city_child_core_name(name: str, construct: str) -> str:
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _city_plan_core_name(name, construct)
    if construct in _SITE_COMPOUND_CORE_SUFFIXES:
        return _site_compound_core_name(name, construct)
    if construct in _RESILIENCE_CORE_SUFFIXES:
        return _resilience_core_name(name, construct)
    if construct in _ACCESS_TRANSITION_CORE_SUFFIXES:
        return _access_transition_core_name(name, construct)
    if construct in _INTERACTION_CORE_SUFFIXES:
        return _interaction_core_name(name, construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _footprint_packing_core_name(name, construct)
    if construct in _EVOLUTION_CORE_SUFFIXES:
        return _evolution_child_core_name(name, construct)
    if construct == "district":
        return f"{name}_district_core"
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_city_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _SURFACE_AUTHORING_MACROS:
        return _expand_surface_authoring_macro(node, construct)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _expand_city_planning_macro(node, construct=construct)
    if construct in _SITE_COMPOUND_CORE_SUFFIXES:
        return _expand_site_compound_macro(node, construct=construct)
    if construct in _RESILIENCE_CORE_SUFFIXES:
        return _expand_resilience_macro(node, construct=construct)
    if construct in _ACCESS_TRANSITION_CORE_SUFFIXES:
        return _expand_access_transition_macro(node, construct=construct)
    if construct in _INTERACTION_CORE_SUFFIXES:
        return _expand_interaction_ui_macro(node, construct=construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _expand_footprint_packing_macro(node, construct=construct)
    if construct in _EVOLUTION_CORE_SUFFIXES:
        return _expand_settlement_evolution_macro(node, construct=construct)
    if construct in _OPERATIONAL_CORE_SUFFIXES:
        return _expand_operational_execution_macro(node, construct=construct)
    if construct == "district":
        return _expand_district_macro(node)
    if construct == "street_grid":
        return _expand_street_grid_macro(node)
    if construct == "road_intersection":
        return _expand_road_intersection_macro(node)
    if construct == "service_network":
        return _expand_service_network_macro(node)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in {"resource_flow", "world_metric", "faction_pressure"}:
        return _expand_simulation_macro(node, construct=construct)
    if construct == "settlement_pressure":
        return _expand_civil_ecology_macro(node, construct=construct)
    if construct in {"policy_rule", "population_group", "labor_system"}:
        return _expand_culture_macro(node, construct=construct)
    if construct == "traversal_gate":
        return _expand_traversal_gate_macro(node)
    return _expand_evolution_child_macro(node, construct)


def _expand_city_planning_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _city_plan_kind(values, construct)
    depth = max(0, int(_number(values.get("_city_plan_depth"), default=0.0)))
    core_name = _city_plan_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_city_plan_scale(values, construct),
        state=_city_plan_state(values, construct, name, kind),
        tags=[construct, kind, "city_planning", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_CITY_PLAN_ACTIONS.get(construct), "compose_city_plan"): _city_plan_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_CITY_PLAN_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "supports", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_city_plan_depth"] = depth + 1
        if child_construct in _EVOLUTION_CORE_SUFFIXES:
            child_values["_evolution_depth"] = max(2, int(_number(child_values.get("_evolution_depth"), default=0.0)))
        if child_construct in _OPERATIONAL_CORE_SUFFIXES:
            child_values["_operational_depth"] = max(2, int(_number(child_values.get("_operational_depth"), default=0.0)))
        if child_construct in _ACCESS_TRANSITION_CORE_SUFFIXES:
            child_values["_access_transition_depth"] = max(1, int(_number(child_values.get("_access_transition_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _CITY_PLAN_ROLES.get(child_construct, _SITE_COMPOUND_ROLES.get(child_construct, _RESILIENCE_ROLES.get(child_construct, _ACCESS_TRANSITION_ROLES.get(child_construct, _INTERACTION_MACRO_ROLES.get(child_construct, _EVOLUTION_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_city_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _city_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    if construct == "city_plan":
        zones = _city_zones(values)
        blocks = _city_blocks(values)
        dependencies = _city_dependencies(values)
        add_child("zoning_rule", "zoning", {"zones": zones, "allowed_uses": zones}, [center[0] - 0.84, center[1] + 1.04, center[2] + 0.05], relation="defines", description=f"City plan {name} defines zoning rules.")
        for index, zone in enumerate(zones[:8]):
            add_child("zoning_district", zone, {"district": zone, "zoning": zone}, [center[0] + (index - (len(zones) - 1) / 2.0) * 0.46, center[1] + 0.48, center[2] + 0.05], relation="zones", description=f"City plan {name} contains zoning district {zone}.")
        add_child("parcel_grid", "parcels", {"parcels": _city_parcels(values)}, [center[0], center[1] + 1.04, center[2] + 0.05], relation="subdivides", description=f"City plan {name} lays out parcels.")
        add_child("street_hierarchy", "streets", {"street_levels": _city_streets(values)}, [center[0] + 0.84, center[1] + 1.04, center[2] + 0.05], relation="connects", description=f"City plan {name} defines street hierarchy.")
        for index, block in enumerate(blocks[:6]):
            add_child("block_plan", block, {"block": block}, [center[0] + (index - (len(blocks) - 1) / 2.0) * 0.54, center[1] - 0.04, center[2] + 0.05], relation="blocks", description=f"City plan {name} includes block plan {block}.")
        add_child("civic_service_plan", "services", {"services": _city_services(values)}, [center[0] - 0.58, center[1] - 0.76, center[2] + 0.05], relation="services", description=f"City plan {name} plans civic services.")
        add_child("growth_boundary", "boundary", {"boundary_type": values.get("boundary_type") or "growth_edge"}, [center[0], center[1] - 0.76, center[2] + 0.05], relation="bounds", description=f"City plan {name} sets growth boundary.")
        add_child("development_pressure", "pressure", {"pressure_sources": values.get("pressure_sources") or ["population", "jobs"]}, [center[0] + 0.58, center[1] - 0.76, center[2] + 0.05], relation="responds_to", description=f"City plan {name} tracks development pressure.")
        for index, dependency in enumerate(dependencies[:6]):
            add_child("district_dependency", dependency, {"dependency": dependency}, [center[0] + (index - (len(dependencies) - 1) / 2.0) * 0.48, center[1] - 1.18, center[2] + 0.05], relation="depends_on", description=f"City plan {name} links dependency {dependency}.")

    elif construct == "zoning_rule":
        add_child("policy_rule", "policy", {"policy": kind, "allowed_uses": values.get("allowed_uses") or _city_zones(values)}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="codifies", description=f"Zoning rule {name} creates policy rule.")
        add_child("zoning_district", "district", {"district": kind, "zoning": kind}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="applies_to", description=f"Zoning rule {name} applies to district.")
        add_child("world_metric", "density_metric", {"metric": "allowed_density", "metric_value": values.get("density") or 0.55}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Zoning rule {name} exposes allowed density.")

    elif construct == "zoning_district":
        add_child("district", "district", {"district_type": kind}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="contains", description=f"Zoning district {name} creates district.")
        add_child("zoning_rule", "rule", {"zoning": kind}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="governed_by", description=f"Zoning district {name} uses zoning rule.")
        add_child("development_pressure", "pressure", {"pressure": kind}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="tracks", description=f"Zoning district {name} tracks development pressure.")

    elif construct == "parcel_grid":
        parcels = _city_parcels(values)
        for index, parcel in enumerate(parcels[:10]):
            add_child("land_parcel", parcel, {"parcel": parcel, "lot": parcel}, [center[0] + (index - (len(parcels[:10]) - 1) / 2.0) * 0.30, center[1] + 0.42, center[2] + 0.04], relation="contains", description=f"Parcel grid {name} contains land parcel {parcel}.")
        add_child("parcel_subdivision", "subdivision", {"parcels": parcels}, [center[0] - 0.28, center[1] - 0.34, center[2] + 0.04], relation="subdivides", description=f"Parcel grid {name} defines subdivision.")
        add_child("street_grid", "street_grid", {"segments": max(1, len(parcels) // 2)}, [center[0] + 0.28, center[1] - 0.34, center[2] + 0.04], relation="fronts", description=f"Parcel grid {name} fronts street grid.")

    elif construct == "land_parcel":
        add_child("build_permit", "permit", {"permit_state": values.get("permit_state") or "eligible"}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="permits", description=f"Land parcel {name} has build permit.")
        add_child("zoning_rule", "zoning", {"zoning": kind}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="governed_by", description=f"Land parcel {name} follows zoning.")
        add_child("development_pressure", "pressure", {"pressure": kind}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="tracks", description=f"Land parcel {name} tracks pressure.")

    elif construct == "parcel_subdivision":
        parcels = _city_parcels(values)
        for index, parcel in enumerate(parcels[:8]):
            add_child("land_parcel", parcel, {"parcel": parcel}, [center[0] + (index - (len(parcels[:8]) - 1) / 2.0) * 0.30, center[1] + 0.38, center[2] + 0.04], relation="creates", description=f"Parcel subdivision {name} creates parcel {parcel}.")
        add_child("block_plan", "block", {"block": values.get("block") or "subdivision_block"}, [center[0] - 0.24, center[1] - 0.34, center[2] + 0.04], relation="forms", description=f"Parcel subdivision {name} forms block plan.")
        add_child("street_hierarchy", "street_access", {"street_levels": _city_streets(values)}, [center[0] + 0.24, center[1] - 0.34, center[2] + 0.04], relation="connects", description=f"Parcel subdivision {name} creates street access.")

    elif construct == "block_plan":
        add_child("parcel_grid", "parcels", {"parcels": _city_parcels(values)}, [center[0] - 0.42, center[1] + 0.40, center[2] + 0.04], relation="contains", description=f"Block plan {name} contains parcel grid.")
        add_child("street_hierarchy", "streets", {"street_levels": _city_streets(values)}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="fronts", description=f"Block plan {name} fronts street hierarchy.")
        add_child("public_space_plan", "public_space", {"public_spaces": _city_public_spaces(values)}, [center[0] + 0.42, center[1] + 0.40, center[2] + 0.04], relation="reserves", description=f"Block plan {name} reserves public space.")
        add_child("service_coverage", "coverage", {"services": _city_services(values)}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="served_by", description=f"Block plan {name} has service coverage.")

    elif construct == "street_hierarchy":
        add_child("street_grid", "grid", {"segments": max(1, len(_city_streets(values))), "hierarchy": kind}, [center[0] - 0.36, center[1] + 0.36, center[2] + 0.04], relation="lays_out", description=f"Street hierarchy {name} lays out street grid.")
        add_child("road_intersection", "junction", {"junction_type": kind}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="intersects", description=f"Street hierarchy {name} places junction.")
        add_child("transit_node", "transit", {"transit": values.get("transit") or "stop"}, [center[0] + 0.36, center[1] + 0.36, center[2] + 0.04], relation="serves", description=f"Street hierarchy {name} places transit node.")

    elif construct == "transit_node":
        add_child("service_coverage", "coverage", {"service": kind, "coverage_radius": values.get("coverage_radius") or 0.8}, [center[0] - 0.24, center[1] + 0.34, center[2] + 0.04], relation="covers", description=f"Transit node {name} creates service coverage.")
        add_child("world_metric", "access_metric", {"metric": "accessibility", "metric_value": values.get("coverage_threshold") or 0.72}, [center[0] + 0.24, center[1] + 0.34, center[2] + 0.04], relation="reveals", description=f"Transit node {name} exposes accessibility.")

    elif construct == "civic_service_plan":
        services = _city_services(values)
        for index, service in enumerate(services[:8]):
            add_child("service_coverage", service, {"service": service}, [center[0] + (index - (len(services) - 1) / 2.0) * 0.32, center[1] + 0.40, center[2] + 0.04], relation="covers", description=f"Civic service plan {name} covers {service}.")
        add_child("utility_corridor", "utilities", {"utilities": values.get("utilities") or services}, [center[0] - 0.32, center[1] - 0.34, center[2] + 0.04], relation="routes", description=f"Civic service plan {name} routes utilities.")
        add_child("staffing_plan", "staffing", {"staff_roles": values.get("staff_roles") or services}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="staffs", description=f"Civic service plan {name} staffs services.")
        add_child("world_metric", "service_metric", {"metric": "service_coverage", "metric_value": values.get("coverage_threshold") or 0.72}, [center[0] + 0.32, center[1] - 0.34, center[2] + 0.04], relation="reveals", description=f"Civic service plan {name} exposes service coverage.")

    elif construct == "service_coverage":
        add_child("service_network", "network", {"services": _city_services(values)}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="connects", description=f"Service coverage {name} creates service network.")
        add_child("resource_flow", "flow", {"resource_type": kind}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="feeds", description=f"Service coverage {name} has resource flow.")
        add_child("world_metric", "coverage_metric", {"metric": "coverage_radius", "metric_value": values.get("coverage_radius") or 0.8}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"Service coverage {name} exposes radius.")

    elif construct == "utility_corridor":
        add_child("service_network", "network", {"services": values.get("utilities") or _city_services(values)}, [center[0] - 0.34, center[1] + 0.36, center[2] + 0.04], relation="connects", description=f"Utility corridor {name} connects service network.")
        add_child("resource_flow", "flow", {"resource_type": kind}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="routes", description=f"Utility corridor {name} routes resource flow.")
        add_child("street_hierarchy", "access", {"street_levels": values.get("street_levels") or ["service_lane"]}, [center[0] + 0.34, center[1] + 0.36, center[2] + 0.04], relation="follows", description=f"Utility corridor {name} follows street hierarchy.")

    elif construct == "district_site_plan":
        compounds = _district_compounds(values)
        blocks = _city_blocks(values)
        crossings = _district_crossings(values)
        landscapes = _district_landscape_zones(values)
        traffic_routes = _district_traffic_routes(values)
        service_routes = _district_service_routes(values)
        for index, block in enumerate(blocks[:6]):
            add_child("block_plan", block, {"block": block, "parcels": _city_parcels(values)}, [center[0] + (index - (len(blocks[:6]) - 1) / 2.0) * 0.52, center[1] + 0.64, center[2] + 0.05], relation="blocks", description=f"District site plan {name} lays out block {block}.")
        for index, compound in enumerate(compounds[:8]):
            add_child("site_compound", compound, {"site_buildings": values.get("site_buildings") or [compound, "support"], "parking_bays": values.get("parking_bays") or 4, "utilities": values.get("utilities") or ["power", "water", "data"], "_site_compound_depth": 1}, [center[0] + (index - (len(compounds[:8]) - 1) / 2.0) * 0.44, center[1] + 0.08, center[2] + 0.06], relation="places", description=f"District site plan {name} places site compound {compound}.")
        add_child("street_hierarchy", "street_spine", {"street_levels": _city_streets(values)}, [center[0] - 0.72, center[1] - 0.42, center[2] + 0.05], relation="connects", description=f"District site plan {name} connects sites with street hierarchy.")
        for index, crossing in enumerate(crossings[:6]):
            add_child("street_crossing", crossing, {"crossing": crossing, "crosswalk_count": values.get("crosswalk_count") or 1}, [center[0] + (index - (len(crossings[:6]) - 1) / 2.0) * 0.36, center[1] - 0.42, center[2] + 0.05], relation="crosses", description=f"District site plan {name} places crossing {crossing}.")
        add_child("perimeter_plan", "perimeter", {"security_gates": _district_security_gates(values), "perimeter_count": values.get("perimeter_count") or max(4, len(_district_security_gates(values)) * 2)}, [center[0] + 0.72, center[1] - 0.42, center[2] + 0.05], relation="bounds", description=f"District site plan {name} shapes controlled perimeter.")
        for index, zone in enumerate(landscapes[:6]):
            add_child("landscape_zone", zone, {"landscape": zone}, [center[0] + (index - (len(landscapes[:6]) - 1) / 2.0) * 0.38, center[1] - 0.84, center[2] + 0.05], relation="softens", description=f"District site plan {name} shapes landscape zone {zone}.")
        for index, route in enumerate(traffic_routes[:4]):
            add_child("traffic_flow", route, {"traffic": route, "traffic_routes": [route]}, [center[0] - 0.44 + index * 0.28, center[1] - 1.20, center[2] + 0.05], relation="routes", description=f"District site plan {name} routes traffic flow {route}.")
        for index, route in enumerate(service_routes[:4]):
            add_child("service_flow", route, {"service": route, "service_routes": [route], "utilities": values.get("utilities") or ["power", "water", "data"]}, [center[0] + 0.44 - index * 0.28, center[1] - 1.20, center[2] + 0.05], relation="services", description=f"District site plan {name} routes service flow {route}.")
        add_child(
            "access_sequence",
            "entry_access",
            {
                "entry_points": values.get("entry_points") or crossings,
                "service_entry_points": values.get("service_entry_points") or service_routes,
                "checkpoint_nodes": values.get("checkpoint_nodes") or _district_security_gates(values),
                "loading_routes": values.get("loading_routes") or service_routes,
                "wayfinding_nodes": values.get("wayfinding_nodes") or compounds,
            },
            [center[0], center[1] - 1.52, center[2] + 0.05],
            relation="connects_inside",
            description=f"District site plan {name} connects exterior paths to entries and lobbies.",
        )

    elif construct == "street_crossing":
        add_child("road_intersection", "crossing_junction", {"junction_type": kind, "crosswalk_count": values.get("crosswalk_count") or values.get("crosswalks") or 2}, [center[0] - 0.24, center[1] + 0.34, center[2] + 0.04], relation="marks", description=f"Street crossing {name} marks road crossing.")
        add_child("pedestrian_path", "walk_path", {"path_type": kind}, [center[0] + 0.08, center[1] + 0.34, center[2] + 0.04], relation="opens", description=f"Street crossing {name} opens pedestrian path.")
        add_child("traffic_flow", "traffic_control", {"traffic": kind}, [center[0] + 0.36, center[1] + 0.34, center[2] + 0.04], relation="calms", description=f"Street crossing {name} calms traffic flow.")
        add_child("world_metric", "crossing_metric", {"metric": "crosswalk_count", "metric_value": values.get("crosswalk_count") or values.get("crosswalks") or 2}, [center[0], center[1] - 0.26, center[2] + 0.04], relation="counts", description=f"Street crossing {name} exposes crosswalk count.")

    elif construct == "perimeter_plan":
        gates = _district_security_gates(values)
        add_child("placement_footprint", "perimeter_footprint", {"fixture_type": "perimeter", "footprint_width": values.get("perimeter_width") or 1.7, "footprint_depth": values.get("perimeter_depth") or 0.18, "_footprint_packing_depth": 2}, [center[0] - 0.34, center[1] + 0.36, center[2] + 0.04], relation="reserves", description=f"Perimeter plan {name} reserves perimeter footprint.")
        for index, gate in enumerate(gates[:8]):
            add_child("security_gate", gate, {"gate": gate}, [center[0] + (index - (len(gates[:8]) - 1) / 2.0) * 0.26, center[1] + 0.36, center[2] + 0.05], relation="controls", description=f"Perimeter plan {name} places security gate {gate}.")
        add_child("maintenance_access", "patrol_access", {"access_type": "perimeter_patrol", "walkway_count": values.get("patrol_count") or 1}, [center[0] + 0.34, center[1] - 0.28, center[2] + 0.04], relation="opens", description=f"Perimeter plan {name} opens patrol access.")
        add_child("world_metric", "perimeter_metric", {"metric": "perimeter_count", "metric_value": values.get("perimeter_count") or max(4, len(gates) * 2)}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="counts", description=f"Perimeter plan {name} exposes perimeter segment count.")

    elif construct == "security_gate":
        add_child("traversal_gate", "access_gate", {"gate_type": kind, "requires": values.get("requires") or ["authorized_access"]}, [center[0] - 0.30, center[1] + 0.34, center[2] + 0.04], relation="controls", description=f"Security gate {name} creates traversal gate.")
        add_child("maintenance_access", "service_lane", {"access_type": "security_gate_service"}, [center[0], center[1] + 0.34, center[2] + 0.04], relation="opens", description=f"Security gate {name} opens service lane.")
        add_child("control_panel", "gate_panel", {"controls": ["open", "lock", "alert"], "services": ["power", "data"]}, [center[0] + 0.30, center[1] + 0.34, center[2] + 0.04], relation="operates", description=f"Security gate {name} exposes gate control panel.")
        add_child("alarm_grid", "alarm", {"alarm_type": "gate_security", "sensor_count": values.get("sensor_count") or 2}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="watches", description=f"Security gate {name} connects alarm grid.")

    elif construct == "landscape_zone":
        add_child("public_space_plan", "open_space", {"public_spaces": [kind]}, [center[0] - 0.32, center[1] + 0.34, center[2] + 0.04], relation="reserves", description=f"Landscape zone {name} reserves open space.")
        add_child("green_infrastructure", "green_infrastructure", {"green": kind, "canopy_cover": values.get("canopy_cover") or 0.35}, [center[0], center[1] + 0.34, center[2] + 0.04], relation="plants", description=f"Landscape zone {name} adds green infrastructure.")
        add_child("stormwater_system", "stormwater", {"stormwater_capacity": values.get("stormwater_capacity") or 0.4}, [center[0] + 0.32, center[1] + 0.34, center[2] + 0.04], relation="drains", description=f"Landscape zone {name} routes stormwater.")
        add_child("material_zone", "surface", {"zone": "landscape_surface", "material": values.get("material") or "planted_ground", "targets": [name]}, [center[0], center[1] - 0.26, center[2] + 0.04], relation="skins", description=f"Landscape zone {name} assigns planted ground surface.")

    elif construct == "traffic_flow":
        add_child("street_hierarchy", "street", {"street_levels": values.get("street_levels") or ["local", "service"]}, [center[0] - 0.30, center[1] + 0.34, center[2] + 0.04], relation="uses", description=f"Traffic flow {name} follows street hierarchy.")
        add_child("road_intersection", "control_point", {"junction_type": kind, "crosswalk_count": values.get("crosswalk_count") or 1}, [center[0], center[1] + 0.34, center[2] + 0.04], relation="controls", description=f"Traffic flow {name} places control point.")
        add_child("world_metric", "traffic_metric", {"metric": "traffic_capacity", "metric_value": values.get("capacity") or values.get("traffic_capacity") or 1.0}, [center[0] + 0.30, center[1] + 0.34, center[2] + 0.04], relation="measures", description=f"Traffic flow {name} exposes traffic capacity.")

    elif construct == "service_flow":
        services = _district_service_routes(values)
        add_child("utility_corridor", "utility_corridor", {"utilities": values.get("utilities") or services}, [center[0] - 0.34, center[1] + 0.34, center[2] + 0.04], relation="routes", description=f"Service flow {name} follows utility corridor.")
        for index, service in enumerate(services[:8]):
            add_child("service_connection", service, {"service_type": service}, [center[0] + (index - (len(services[:8]) - 1) / 2.0) * 0.22, center[1] + 0.34, center[2] + 0.04], relation="feeds", description=f"Service flow {name} creates {service} service connection.")
        add_child("maintenance_access", "service_access", {"access_type": "service_flow_access"}, [center[0] - 0.18, center[1] - 0.28, center[2] + 0.04], relation="opens", description=f"Service flow {name} opens maintenance access.")
        add_child("resource_flow", "resource_flow", {"resource_type": kind}, [center[0] + 0.18, center[1] - 0.28, center[2] + 0.04], relation="carries", description=f"Service flow {name} carries resource flow.")

    elif construct == "public_space_plan":
        add_child("district", "district", {"district_type": kind}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="reserves", description=f"Public space plan {name} reserves district area.")
        add_child("service_coverage", "coverage", {"service": "public_space"}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="serves", description=f"Public space plan {name} adds service coverage.")
        add_child("world_metric", "open_space_metric", {"metric": "open_space_ratio", "metric_value": values.get("open_space_ratio") or 0.18}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Public space plan {name} exposes open-space ratio.")

    elif construct == "growth_boundary":
        add_child("zoning_rule", "edge_rule", {"zoning": "growth_edge"}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="limits", description=f"Growth boundary {name} limits zoning.")
        add_child("settlement_pressure", "pressure", {"pressure_type": kind, "pressure_sources": values.get("pressure_sources") or ["growth"]}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="contains", description=f"Growth boundary {name} contains pressure.")
        add_child("world_metric", "growth_metric", {"metric": "growth_limit", "metric_value": values.get("growth_limit") or 1.0}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"Growth boundary {name} exposes growth limit.")

    elif construct == "district_dependency":
        add_child("service_coverage", "service", {"service": kind}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="requires", description=f"District dependency {name} requires service coverage.")
        add_child("resource_flow", "flow", {"resource_type": kind}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="depends_on", description=f"District dependency {name} depends on flow.")
        add_child("world_metric", "dependency_metric", {"metric": "dependency_strength", "metric_value": values.get("dependency_strength") or 0.6}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"District dependency {name} exposes dependency strength.")

    elif construct == "development_pressure":
        add_child("settlement_pressure", "settlement_pressure", {"pressure_type": kind, "pressure_sources": values.get("pressure_sources") or ["population"]}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="measures", description=f"Development pressure {name} measures settlement pressure.")
        add_child("build_permit", "permit", {"permit_state": values.get("permit_state") or "queued"}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="drives", description=f"Development pressure {name} drives permit demand.")
        add_child("world_metric", "pressure_metric", {"metric": "development_pressure", "metric_value": values.get("pressure_level") or 0.5}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"Development pressure {name} exposes pressure level.")

    return objects, relationships


_ACCESS_TRANSITION_CORE_SUFFIXES = {
    "access_sequence": "access_sequence_core",
    "public_entry": "public_entry_core",
    "service_entry": "service_entry_core",
    "threshold_transition": "threshold_transition_core",
    "entry_lobby": "entry_lobby_core",
    "access_checkpoint": "access_checkpoint_core",
    "loading_path": "loading_path_core",
    "wayfinding_node": "wayfinding_node_core",
}

_ACCESS_TRANSITION_ROLES = {
    "access_sequence": "navigation",
    "public_entry": "navigation",
    "service_entry": "navigation",
    "threshold_transition": "navigation",
    "entry_lobby": "environment_structure",
    "access_checkpoint": "interactive",
    "loading_path": "navigation",
    "wayfinding_node": "interactive",
}

_ACCESS_TRANSITION_KIND_KEYS = {
    "access_sequence": ("sequence", "access", "entry_system", "type"),
    "public_entry": ("entry", "entry_type", "public_entry", "type"),
    "service_entry": ("entry", "service_entry", "service", "type"),
    "threshold_transition": ("threshold", "transition", "type"),
    "entry_lobby": ("lobby", "lobby_type", "type"),
    "access_checkpoint": ("checkpoint", "security", "type"),
    "loading_path": ("loading", "route", "type"),
    "wayfinding_node": ("wayfinding", "signage", "type"),
}

_ACCESS_TRANSITION_KIND_DEFAULTS = {
    "access_sequence": "entry_access_sequence",
    "public_entry": "public_entry",
    "service_entry": "service_entry",
    "threshold_transition": "interior_exterior_threshold",
    "entry_lobby": "arrival_lobby",
    "access_checkpoint": "access_checkpoint",
    "loading_path": "loading_path",
    "wayfinding_node": "wayfinding_node",
}

_ACCESS_TRANSITION_ACTIONS = {
    "access_sequence": "connect_exterior_to_interior",
    "public_entry": "open_public_entry",
    "service_entry": "open_service_entry",
    "threshold_transition": "bridge_threshold",
    "entry_lobby": "arrange_entry_lobby",
    "access_checkpoint": "control_access_checkpoint",
    "loading_path": "route_loading_path",
    "wayfinding_node": "place_wayfinding_node",
}


def _access_transition_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _ACCESS_TRANSITION_KIND_DEFAULTS.get(construct, construct)
    for key in _ACCESS_TRANSITION_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _access_transition_core_name(name: str, construct: str) -> str:
    return f"{name}_{_ACCESS_TRANSITION_CORE_SUFFIXES.get(construct, 'access_transition_core')}"


def _access_transition_named_list(
    values: Mapping[str, Any],
    keys: Sequence[str],
    default: Sequence[str],
    count_keys: Sequence[str],
    *,
    limit: int = 16,
) -> list[str]:
    explicit = _gameplay_name_list(values, keys, default=[])
    if explicit:
        return explicit[:limit]
    count_source = None
    for key in count_keys:
        if key in values:
            count_source = values.get(key)
            break
    count = max(1, min(limit, _positive_int(count_source, default=len(default))))
    names = [_snake_id(item, "access") for item in default]
    while len(names) < count:
        names.append(f"{_snake_id(keys[0], 'access')}_{len(names) + 1:02d}")
    return names[:count]


def _access_entries(values: Mapping[str, Any]) -> list[str]:
    return _access_transition_named_list(values, ("entry_points", "public_entries", "entries", "doors"), ["main_entry"], ("public_entry_count", "entry_count", "entries"), limit=12)


def _service_entries(values: Mapping[str, Any]) -> list[str]:
    return _access_transition_named_list(values, ("service_entry_points", "service_entries", "service_doors"), ["service_entry"], ("service_entry_count", "service_entries"), limit=8)


def _access_thresholds(values: Mapping[str, Any]) -> list[str]:
    return _access_transition_named_list(values, ("thresholds", "threshold_transitions", "doors"), ["front_threshold"], ("threshold_transition_count", "threshold_count"), limit=16)


def _entry_lobbies(values: Mapping[str, Any]) -> list[str]:
    return _access_transition_named_list(values, ("lobby_zones", "lobbies", "arrival_zones"), ["main_lobby"], ("entry_lobby_count", "lobby_count"), limit=8)


def _access_checkpoints(values: Mapping[str, Any]) -> list[str]:
    return _access_transition_named_list(values, ("checkpoint_nodes", "checkpoints", "security_gates"), ["front_checkpoint"], ("access_checkpoint_count", "checkpoint_count"), limit=12)


def _loading_routes(values: Mapping[str, Any]) -> list[str]:
    return _access_transition_named_list(values, ("loading_routes", "loading_paths", "service_routes"), ["dock_route"], ("loading_path_count", "loading_count"), limit=12)


def _wayfinding_nodes(values: Mapping[str, Any]) -> list[str]:
    return _access_transition_named_list(values, ("wayfinding_nodes", "signage_nodes", "map_nodes"), ["arrival_map"], ("wayfinding_node_count", "signage_count"), limit=16)


def _access_transition_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    width = max(0.4, _number(values.get("width") or values.get("access_width"), default=1.2))
    depth = max(0.3, _number(values.get("depth") or values.get("access_depth"), default=0.8))
    if construct == "access_sequence":
        return [max(1.8, width * 1.6), max(1.2, depth * 1.8), 0.18]
    if construct in {"public_entry", "service_entry", "access_checkpoint"}:
        return [max(0.7, width), max(0.34, depth * 0.42), 0.36]
    if construct == "threshold_transition":
        return [max(0.44, width * 0.55), max(0.18, depth * 0.26), 0.18]
    if construct == "entry_lobby":
        return [max(1.2, width * 1.15), max(0.84, depth), 0.22]
    if construct == "loading_path":
        return [max(1.3, width * 1.3), max(0.42, depth * 0.50), 0.16]
    return [0.36, 0.18, 0.32]


def _access_transition_controls(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    entries = _access_entries(values)
    service_entries = _service_entries(values)
    thresholds = _access_thresholds(values)
    lobbies = _entry_lobbies(values)
    checkpoints = _access_checkpoints(values)
    loading_routes = _loading_routes(values)
    wayfinding = _wayfinding_nodes(values)
    entry_like = construct in {"access_sequence", "public_entry"}
    service_like = construct in {"access_sequence", "service_entry", "loading_path"}
    threshold_like = construct in {"access_sequence", "public_entry", "service_entry", "threshold_transition"}
    lobby_like = construct in {"access_sequence", "public_entry", "entry_lobby"}
    checkpoint_like = construct in {"access_sequence", "public_entry", "access_checkpoint"}
    loading_like = construct in {"access_sequence", "service_entry", "loading_path"}
    wayfinding_like = construct in {"access_sequence", "public_entry", "entry_lobby", "wayfinding_node"}
    return {
        "access_sequence_count": 1 if construct == "access_sequence" else 0,
        "public_entry_count": len(entries) if entry_like else 0,
        "service_entry_count": len(service_entries) if service_like else 0,
        "threshold_transition_count": len(thresholds) if threshold_like else 0,
        "entry_lobby_count": len(lobbies) if lobby_like else 0,
        "access_checkpoint_count": len(checkpoints) if checkpoint_like else 0,
        "loading_path_count": len(loading_routes) if loading_like else 0,
        "wayfinding_node_count": len(wayfinding) if wayfinding_like else 0,
        "entry_count": len(entries) if entry_like else 0,
        "service_door_count": len(service_entries) if service_like else 0,
        "door_opening_count": len(thresholds) if threshold_like else 0,
        "corridor_link_count": max(1, len(lobbies)) if lobby_like or threshold_like else 0,
        "room_program_count": len(lobbies) if lobby_like else 0,
        "traversal_gate_count": len(checkpoints) if checkpoint_like else 0,
        "security_gate_count": len(checkpoints) if checkpoint_like else 0,
        "loading_dock_count": len(loading_routes) if loading_like else 0,
        "loading_zone_count": len(loading_routes) if loading_like else 0,
        "service_connection_count": max(1, len(service_entries)) if service_like else 0,
        "maintenance_access_count": max(1, len(loading_routes)) if loading_like else 0,
        "signage_count": len(wayfinding) if wayfinding_like else 0,
        "map_marker_count": len(wayfinding) if wayfinding_like else 0,
        "interaction_prompt_count": max(1, len(entries)) if entry_like or wayfinding_like else 0,
        "control_panel_count": len(checkpoints) if checkpoint_like else 0,
        "alarm_grid_count": len(checkpoints) if checkpoint_like else 0,
        "material_zone_count": len(thresholds) if threshold_like else 0,
        "wear_pattern_count": len(thresholds) if threshold_like else 0,
    }


def _access_transition_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    entries = _access_entries(values)
    service_entries = _service_entries(values)
    thresholds = _access_thresholds(values)
    lobbies = _entry_lobbies(values)
    checkpoints = _access_checkpoints(values)
    loading_routes = _loading_routes(values)
    wayfinding = _wayfinding_nodes(values)
    controls = _access_transition_controls(values, construct)
    state: dict[str, Any] = {
        construct: name,
        "access_transition_construct": construct,
        "access_transition_kind": kind,
        "action": _snake_id(values.get("action") or _ACCESS_TRANSITION_ACTIONS.get(construct), "connect_access"),
        f"{construct}_count": 1,
        "access_transition_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "access_transition",
        "enabled": not _disabled(values.get("enabled", True)),
        "lathe_asset": "procedural_access",
        "source_family": "procedural_access",
        "access_type": kind,
        "traversal_type": kind,
        "access_style": _surface_marker_value(values, "access_style", "style", fallback="civic"),
        "from_zone": _surface_marker_value(values, "from_zone", "from", "exterior", fallback="exterior"),
        "to_zone": _surface_marker_value(values, "to_zone", "to", "interior", fallback="interior"),
        "entry_points": entries,
        "public_entries": entries,
        "service_entry_points": service_entries,
        "thresholds": thresholds,
        "lobby_zones": lobbies,
        "checkpoint_nodes": checkpoints,
        "loading_routes": loading_routes,
        "wayfinding_nodes": wayfinding,
        "access_transition_profile": kind,
        "access_transition_controls": controls,
        "opening_width": _number(values.get("opening_width") or values.get("door_width"), default=0.9),
        "threshold_depth": _number(values.get("threshold_depth"), default=0.18),
        "corridor_width": _number(values.get("corridor_width") or values.get("access_width"), default=1.2),
        "route_count": max(1, controls.get("public_entry_count", 0) + controls.get("service_entry_count", 0) + controls.get("loading_path_count", 0)),
        **controls,
    }
    if construct == "entry_lobby":
        state.update({"interior_count": 1, "room_count": max(1, len(lobbies)), "room_roles": ["entry", "lobby", "reception"]})
    if construct == "wayfinding_node":
        state.update({"interactive_count": 1, "marker_count": max(1, len(wayfinding)), "signage": wayfinding})
    if construct in {"access_checkpoint", "public_entry", "service_entry"}:
        state.update({"gate_count": max(1, controls.get("traversal_gate_count", 0)), "door_count": max(1, controls.get("door_opening_count", 0))})
    return state


def _access_transition_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {
        "action": _snake_id(values.get("action") or _ACCESS_TRANSITION_ACTIONS.get(construct), "connect_access"),
        "from_zone": _surface_marker_value(values, "from_zone", "from", "exterior", fallback="exterior"),
        "to_zone": _surface_marker_value(values, "to_zone", "to", "interior", fallback="interior"),
    }
    checkpoints = _access_checkpoints(values)
    if checkpoints:
        affordance["checkpoints"] = checkpoints
    return affordance


def _access_transition_child_core_name(name: str, construct: str) -> str:
    if construct in _ACCESS_TRANSITION_CORE_SUFFIXES:
        return _access_transition_core_name(name, construct)
    if construct in _CIRCULATION_EGRESS_CORE_SUFFIXES:
        return _circulation_core_name(name, construct)
    if construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
        return _building_envelope_core_name(name, construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _layout_resolution_core_name(name, construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _functional_interior_core_name(name, construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _city_plan_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct in _INTERACTION_CORE_SUFFIXES:
        return _interaction_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_access_transition_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _ACCESS_TRANSITION_CORE_SUFFIXES:
        return _expand_access_transition_macro(node, construct=construct)
    if construct in _CIRCULATION_EGRESS_CORE_SUFFIXES:
        return _expand_circulation_egress_macro(node, construct=construct)
    if construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
        return _expand_building_envelope_macro(node, construct=construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _expand_layout_resolution_macro(node, construct=construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _expand_functional_interior_macro(node, construct=construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _expand_city_planning_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in _INTERACTION_CORE_SUFFIXES:
        return _expand_interaction_ui_macro(node, construct=construct)
    if construct in _SURFACE_AUTHORING_MACROS:
        return _expand_surface_authoring_macro(node, construct)
    if construct in {"door_action", "gate_action"}:
        return _expand_door_or_gate_action_macro(node, construct=construct)
    if construct in {"resource_flow", "world_metric", "alarm_grid"}:
        return _expand_simulation_macro(node, construct=construct)
    if construct == "traversal_gate":
        return _expand_traversal_gate_macro(node)
    return _expand_service_network_macro(node)


def _expand_access_transition_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _access_transition_kind(values, construct)
    depth = max(0, int(_number(values.get("_access_transition_depth"), default=0.0)))
    core_name = _access_transition_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_access_transition_scale(values, construct),
        state=_access_transition_state(values, construct, name, kind),
        tags=[construct, kind, "access_transition", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_ACCESS_TRANSITION_ACTIONS.get(construct), "connect_access"): _access_transition_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_ACCESS_TRANSITION_ROLES.get(construct, "navigation"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "connects", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_access_transition_depth"] = depth + 1
        if child_construct in _CIRCULATION_EGRESS_CORE_SUFFIXES:
            child_values["_circulation_egress_depth"] = max(1, int(_number(child_values.get("_circulation_egress_depth"), default=0.0)))
        if child_construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
            child_values["_building_envelope_depth"] = max(1, int(_number(child_values.get("_building_envelope_depth"), default=0.0)))
        if child_construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
            child_values["_interior_composition_depth"] = max(1, int(_number(child_values.get("_interior_composition_depth"), default=0.0)))
        if child_construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
            child_values["_layout_resolution_depth"] = max(1, int(_number(child_values.get("_layout_resolution_depth"), default=0.0)))
        if child_construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
            child_values["_functional_interior_depth"] = max(1, int(_number(child_values.get("_functional_interior_depth"), default=0.0)))
        if child_construct in _BUILDING_SERVICE_CORE_SUFFIXES:
            child_values["_building_service_depth"] = max(1, int(_number(child_values.get("_building_service_depth"), default=0.0)))
        if child_construct in _CITY_PLAN_CORE_SUFFIXES:
            child_values["_city_plan_depth"] = max(2, int(_number(child_values.get("_city_plan_depth"), default=0.0)))
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(2, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        if child_construct in _INTERACTION_CORE_SUFFIXES:
            child_values["_interaction_depth"] = max(2, int(_number(child_values.get("_interaction_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _ACCESS_TRANSITION_ROLES.get(
            child_construct,
            _CIRCULATION_EGRESS_ROLES.get(
                child_construct,
                _BUILDING_ENVELOPE_ROLES.get(
                    child_construct,
                    _INTERIOR_COMPOSITION_ROLES.get(
                        child_construct,
                        _FUNCTIONAL_INTERIOR_ROLES.get(
                            child_construct,
                            _BUILDING_SERVICE_ROLES.get(
                                child_construct,
                                _INTERACTION_MACRO_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")),
                            ),
                        ),
                    ),
                ),
            ),
        )
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_access_transition_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _access_transition_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    entries = _access_entries(values)
    service_entries = _service_entries(values)
    thresholds = _access_thresholds(values)
    lobbies = _entry_lobbies(values)
    checkpoints = _access_checkpoints(values)
    loading_routes = _loading_routes(values)
    wayfinding = _wayfinding_nodes(values)

    if construct == "access_sequence":
        for index, entry in enumerate(entries[:8]):
            add_child("public_entry", entry, {"entry_points": [entry], "thresholds": thresholds[:1] or [entry]}, [center[0] + (index - (len(entries[:8]) - 1) / 2.0) * 0.34, center[1] + 0.58, center[2] + 0.05], relation="opens", description=f"Access sequence {name} opens public entry {entry}.")
        for index, service_entry in enumerate(service_entries[:6]):
            add_child("service_entry", service_entry, {"service_entry_points": [service_entry], "loading_routes": loading_routes[:1] or [service_entry]}, [center[0] + (index - (len(service_entries[:6]) - 1) / 2.0) * 0.34, center[1] + 0.20, center[2] + 0.05], relation="services", description=f"Access sequence {name} opens service entry {service_entry}.")
        for index, threshold in enumerate(thresholds[:8]):
            add_child("threshold_transition", threshold, {"thresholds": [threshold], "from_room": "exterior", "to_room": lobbies[0] if lobbies else "lobby"}, [center[0] + (index - (len(thresholds[:8]) - 1) / 2.0) * 0.28, center[1] - 0.10, center[2] + 0.05], relation="bridges", description=f"Access sequence {name} bridges threshold {threshold}.")
        for index, lobby in enumerate(lobbies[:4]):
            add_child("entry_lobby", lobby, {"lobby_zones": [lobby], "room_programs": ["entry", "lobby", "reception"]}, [center[0] + (index - (len(lobbies[:4]) - 1) / 2.0) * 0.40, center[1] - 0.46, center[2] + 0.05], relation="arrives_at", description=f"Access sequence {name} arranges lobby {lobby}.")
        for index, checkpoint in enumerate(checkpoints[:6]):
            add_child("access_checkpoint", checkpoint, {"checkpoint_nodes": [checkpoint]}, [center[0] + (index - (len(checkpoints[:6]) - 1) / 2.0) * 0.32, center[1] - 0.82, center[2] + 0.05], relation="controls", description=f"Access sequence {name} controls checkpoint {checkpoint}.")
        for index, route in enumerate(loading_routes[:6]):
            add_child("loading_path", route, {"loading_routes": [route], "service_entry_points": service_entries[:1] or [route]}, [center[0] + (index - (len(loading_routes[:6]) - 1) / 2.0) * 0.34, center[1] - 1.16, center[2] + 0.05], relation="routes_cargo", description=f"Access sequence {name} routes loading path {route}.")
        for index, node_name in enumerate(wayfinding[:8]):
            add_child("wayfinding_node", node_name, {"wayfinding_nodes": [node_name]}, [center[0] + (index - (len(wayfinding[:8]) - 1) / 2.0) * 0.24, center[1] - 1.48, center[2] + 0.05], relation="guides", description=f"Access sequence {name} places wayfinding node {node_name}.")

    elif construct == "public_entry":
        entry = entries[0]
        add_child("entrance_plan", "entrance", {"entries": len(entries), "entry_count": len(entries), "door_count": len(entries)}, [center[0] - 0.34, center[1] + 0.30, center[2] + 0.04], relation="places", description=f"Public entry {name} places entrance plan.")
        add_child("door_opening", "doorway", {"from_room": "exterior", "to_room": lobbies[0] if lobbies else "lobby", "opening_width": values.get("opening_width") or 0.9}, [center[0], center[1] + 0.30, center[2] + 0.04], relation="opens", description=f"Public entry {name} cuts doorway.")
        add_child("threshold_transition", "public_threshold", {"thresholds": thresholds[:1] or [entry]}, [center[0] + 0.34, center[1] + 0.30, center[2] + 0.04], relation="bridges", description=f"Public entry {name} bridges exterior and lobby.")
        add_child("wayfinding_node", "entry_sign", {"wayfinding_nodes": wayfinding[:1] or [entry]}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="labels", description=f"Public entry {name} places entry wayfinding.")

    elif construct == "service_entry":
        service_entry = service_entries[0]
        add_child("loading_path", "loading_path", {"loading_routes": loading_routes[:1] or [service_entry]}, [center[0] - 0.30, center[1] + 0.28, center[2] + 0.04], relation="routes_cargo", description=f"Service entry {name} routes loading path.")
        add_child("loading_dock", "dock", {"dock_bays": values.get("dock_bays") or 1}, [center[0], center[1] + 0.28, center[2] + 0.04], relation="serves", description=f"Service entry {name} places loading dock.")
        add_child("threshold_transition", "service_threshold", {"thresholds": thresholds[:1] or [service_entry], "from_room": "service_yard", "to_room": "back_of_house"}, [center[0] + 0.30, center[1] + 0.28, center[2] + 0.04], relation="bridges", description=f"Service entry {name} bridges service yard to interior.")
        add_child("maintenance_access", "service_access", {"access_type": "service_entry_access"}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="opens", description=f"Service entry {name} opens maintenance access.")

    elif construct == "threshold_transition":
        source_room = _surface_marker_value(values, "from_room", "from_zone", "from", fallback="exterior")
        target_room = _surface_marker_value(values, "to_room", "to_zone", "to", fallback="interior")
        add_child("door_opening", "opening", {"from_room": source_room, "to_room": target_room, "opening_width": values.get("opening_width") or 0.9}, [center[0] - 0.28, center[1] + 0.22, center[2] + 0.04], relation="cuts", description=f"Threshold transition {name} cuts entry opening.")
        add_child("corridor_link", "threshold_link", {"from_room": source_room, "to_room": target_room, "corridor_width": values.get("corridor_width") or 1.2}, [center[0], center[1] + 0.22, center[2] + 0.04], relation="routes", description=f"Threshold transition {name} routes threshold circulation.")
        add_child("material_zone", "threshold_surface", {"zone": "threshold_floor", "material": values.get("material") or "worn_stone", "targets": thresholds}, [center[0] + 0.28, center[1] + 0.22, center[2] + 0.04], relation="skins", description=f"Threshold transition {name} assigns threshold material.")
        add_child("wear_pattern", "threshold_wear", {"wear": values.get("wear") or "foot_traffic", "wear_intensity": values.get("wear_intensity") or 0.55}, [center[0], center[1] - 0.22, center[2] + 0.04], relation="wears", description=f"Threshold transition {name} adds foot-traffic wear.")

    elif construct == "entry_lobby":
        lobby = lobbies[0]
        add_child("room_program", "lobby_program", {"room_programs": ["entry", "lobby", "reception"], "rooms": ["entry", lobby, "reception"]}, [center[0] - 0.32, center[1] + 0.28, center[2] + 0.04], relation="programs", description=f"Entry lobby {name} programs arrival rooms.")
        add_child("room_connection", "entry_to_lobby", {"from_room": entries[0] if entries else "entry", "to_room": lobby}, [center[0], center[1] + 0.28, center[2] + 0.04], relation="connects", description=f"Entry lobby {name} connects entry to lobby.")
        add_child("wayfinding_node", "lobby_wayfinding", {"wayfinding_nodes": wayfinding[:1] or [lobby]}, [center[0] + 0.32, center[1] + 0.28, center[2] + 0.04], relation="guides", description=f"Entry lobby {name} places lobby wayfinding.")
        add_child("interaction_prompt", "reception_prompt", {"prompt": values.get("prompt") or "Check in", "action": "use_reception"}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="offers", description=f"Entry lobby {name} exposes reception interaction.")

    elif construct == "access_checkpoint":
        checkpoint = checkpoints[0]
        add_child("traversal_gate", "checkpoint_gate", {"gate_type": kind, "requires": values.get("requires") or ["authorized_access"]}, [center[0] - 0.30, center[1] + 0.28, center[2] + 0.04], relation="controls", description=f"Access checkpoint {name} creates traversal gate.")
        add_child("control_panel", "checkpoint_panel", {"controls": ["unlock", "alarm", "route"], "services": ["power", "data"]}, [center[0], center[1] + 0.28, center[2] + 0.04], relation="operates", description=f"Access checkpoint {name} places control panel.")
        add_child("alarm_grid", "checkpoint_alarm", {"alarm_type": checkpoint, "sensor_count": values.get("sensor_count") or 2}, [center[0] + 0.30, center[1] + 0.28, center[2] + 0.04], relation="watches", description=f"Access checkpoint {name} connects alarm grid.")
        add_child("door_lock", "credential_lock", {"lock_type": values.get("lock_type") or "credential"}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="locks", description=f"Access checkpoint {name} adds credential lock.")

    elif construct == "loading_path":
        route = loading_routes[0]
        add_child("loading_dock", "dock", {"dock_bays": values.get("dock_bays") or 1}, [center[0] - 0.34, center[1] + 0.24, center[2] + 0.04], relation="starts_at", description=f"Loading path {name} starts at loading dock.")
        add_child("service_flow", "service_flow", {"service_routes": [route], "utilities": values.get("utilities") or ["power", "data"]}, [center[0], center[1] + 0.24, center[2] + 0.04], relation="routes", description=f"Loading path {name} routes service flow.")
        add_child("maintenance_access", "maintenance_route", {"access_type": "loading_path"}, [center[0] + 0.34, center[1] + 0.24, center[2] + 0.04], relation="opens", description=f"Loading path {name} opens maintenance route.")
        add_child("resource_flow", "cargo_flow", {"resource_type": values.get("cargo") or "cargo", "flow_rate": values.get("throughput") or 1.0}, [center[0], center[1] - 0.22, center[2] + 0.04], relation="carries", description=f"Loading path {name} carries cargo flow.")

    elif construct == "wayfinding_node":
        node_name = wayfinding[0]
        add_child("signage", "sign", {"signage": node_name, "label": values.get("label") or node_name}, [center[0] - 0.24, center[1] + 0.22, center[2] + 0.04], relation="labels", description=f"Wayfinding node {name} places signage.")
        add_child("map_marker", "map_marker", {"marker": node_name, "target": values.get("target") or node_name}, [center[0], center[1] + 0.22, center[2] + 0.04], relation="marks", description=f"Wayfinding node {name} places map marker.")
        add_child("interaction_prompt", "prompt", {"prompt": values.get("prompt") or "View map", "action": "inspect_map"}, [center[0] + 0.24, center[1] + 0.22, center[2] + 0.04], relation="offers", description=f"Wayfinding node {name} offers map prompt.")

    return objects, relationships


