def _infra_network_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _INFRA_NETWORK_KIND_DEFAULTS.get(construct, construct)
    for key in _INFRA_NETWORK_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _infra_network_core_name(name: str, construct: str) -> str:
    return f"{name}_{_INFRA_NETWORK_CORE_SUFFIXES.get(construct, 'infrastructure_network_core')}"


def _infra_network_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct in {"power_grid", "water_network", "sewer_network", "data_network", "transit_line"}:
        return [max(2.4, _number(values.get("length") or values.get("width"), default=4.8)), 0.48, 0.18]
    if construct in {"power_line", "fiber_line", "service_connection", "maintenance_access"}:
        return [max(1.8, _number(values.get("length"), default=3.2)), 0.22, 0.12]
    if construct in {"substation", "treatment_plant", "transit_station"}:
        return [0.92, 0.62, 0.26]
    if construct in {"water_tower"}:
        return [0.48, 0.48, 0.86]
    return [0.62, 0.42, 0.20]


def _infra_network_services(values: Mapping[str, Any], construct: str) -> list[str]:
    services = _gameplay_name_list(values, ("services", "service_types", "utilities", "utility_types"), default=[])
    if not services:
        services = list(_INFRA_NETWORK_DEFAULT_SERVICES.get(construct, ["utility"]))
    return _dedupe([_snake_id(item, "utility") for item in services])[:8]


def _infra_network_nodes(values: Mapping[str, Any], construct: str) -> list[str]:
    nodes = _gameplay_name_list(values, ("network_nodes", "service_nodes", "nodes", "route_nodes"), default=[])
    if nodes:
        return nodes[:16]
    if construct in {"power_grid", "data_network", "water_network", "sewer_network"}:
        count = max(2, min(12, _positive_int(values.get("node_count") or values.get("junction_count"), default=4)))
        return [f"node_{index + 1:02d}" for index in range(count)]
    if construct == "transit_line":
        stops = _gameplay_name_list(values, ("stations", "stops"), default=[])
        if stops:
            return stops[:16]
        count = max(2, min(16, _positive_int(values.get("station_count") or values.get("stops"), default=3)))
        return [f"station_{index + 1:02d}" for index in range(count)]
    return ["source", "sink"]


def _infra_network_segments(values: Mapping[str, Any], construct: str, nodes: Sequence[str]) -> int:
    return max(1, min(64, _positive_int(values.get("line_segments") or values.get("segments") or values.get("connection_segment_count"), default=max(1, len(nodes) - 1 if nodes else 1))))


def _infra_network_counts(values: Mapping[str, Any], construct: str, services: Sequence[str], segment_count: int) -> dict[str, int]:
    density = max(1, min(8, _positive_int(values.get("density") or values.get("detail_density"), default=1)))
    counts = _service_network_counts(services, multiplier=density)
    counts.update(
        {
            "connection_segment_count": segment_count,
            "route_segment_count": segment_count,
            "network_segment_count": segment_count,
            "support_count": max(counts.get("support_count", 0), segment_count * 2),
            "junction_box_count": max(counts.get("junction_box_count", 0), segment_count + 1),
            "service_rail_count": max(counts.get("service_rail_count", 0), 1 if construct not in {"water_tower"} else 0),
        }
    )
    if construct == "power_grid":
        counts.update({"conduit_count": max(counts["conduit_count"], segment_count * 2), "transformer_count": max(counts["transformer_count"], 2), "cable_tray_count": max(counts["cable_tray_count"], 1), "power_line_count": segment_count, "substation_count": max(1, _positive_int(values.get("substations") or values.get("substation_count"), default=2)), "service_connection_count": max(1, segment_count)})
    elif construct == "substation":
        counts.update({"conduit_count": max(counts["conduit_count"], 2), "transformer_count": max(counts["transformer_count"], 3), "junction_box_count": max(counts["junction_box_count"], 2), "transformer_bank_count": 1, "power_line_count": 1, "service_connection_count": 1})
    elif construct == "transformer_bank":
        counts.update({"transformer_count": max(2, _positive_int(values.get("transformers") or values.get("transformer_count"), default=4)), "conduit_count": max(counts["conduit_count"], 2), "junction_box_count": max(counts["junction_box_count"], 2), "power_line_count": 1, "service_connection_count": 1})
    elif construct == "power_line":
        counts.update({"conduit_count": max(counts["conduit_count"], 2), "cable_tray_count": max(counts["cable_tray_count"], 1), "junction_box_count": max(counts["junction_box_count"], segment_count + 1), "service_connection_count": max(1, segment_count)})
    elif construct == "water_network":
        counts.update({"pipe_count": max(counts["pipe_count"], segment_count * 2), "valve_count": max(counts["valve_count"], segment_count), "hydrant_count": max(1, segment_count // 2), "pump_station_count": 1, "water_tower_count": 1, "service_connection_count": max(1, segment_count)})
    elif construct == "pump_station":
        counts.update({"pipe_count": max(counts["pipe_count"], 2), "valve_count": max(counts["valve_count"], 2), "junction_box_count": max(counts["junction_box_count"], 1), "service_connection_count": 1})
    elif construct == "water_tower":
        counts.update({"pipe_count": max(counts["pipe_count"], 1), "valve_count": max(counts["valve_count"], 2), "support_count": max(counts["support_count"], 4), "service_connection_count": 1})
    elif construct == "sewer_network":
        counts.update({"pipe_count": max(counts["pipe_count"], segment_count * 2), "drain_count": max(counts["drain_count"], segment_count), "manhole_count": max(counts["manhole_count"], segment_count), "treatment_plant_count": 1, "service_connection_count": max(1, segment_count)})
    elif construct == "treatment_plant":
        counts.update({"pipe_count": max(counts["pipe_count"], 3), "drain_count": max(counts["drain_count"], 2), "manhole_count": max(counts["manhole_count"], 1), "valve_count": max(counts["valve_count"], 2), "service_connection_count": 1})
    elif construct == "data_network":
        counts.update({"conduit_count": max(counts["conduit_count"], segment_count * 2), "cable_tray_count": max(counts["cable_tray_count"], 2), "junction_box_count": max(counts["junction_box_count"], segment_count + 1), "data_hub_count": 1, "fiber_line_count": segment_count, "service_connection_count": max(1, segment_count)})
    elif construct == "data_hub":
        counts.update({"conduit_count": max(counts["conduit_count"], 2), "cable_tray_count": max(counts["cable_tray_count"], 2), "junction_box_count": max(counts["junction_box_count"], 3), "fiber_line_count": 1, "service_connection_count": 1})
    elif construct == "fiber_line":
        counts.update({"conduit_count": max(counts["conduit_count"], 2), "cable_tray_count": max(counts["cable_tray_count"], 1), "junction_box_count": max(counts["junction_box_count"], segment_count + 1), "service_connection_count": max(1, segment_count)})
    elif construct == "transit_line":
        station_count = max(1, min(16, _positive_int(values.get("station_count") or values.get("stations") or values.get("stops"), default=max(2, segment_count + 1))))
        counts.update({"service_rail_count": max(counts["service_rail_count"], 2), "support_count": max(counts["support_count"], station_count * 2), "transit_station_count": station_count, "transit_node_count": station_count, "service_connection_count": max(1, station_count)})
    elif construct == "transit_station":
        counts.update({"service_rail_count": max(counts["service_rail_count"], 1), "junction_box_count": max(counts["junction_box_count"], 1), "service_coverage_count": 1, "transit_node_count": 1, "service_connection_count": 1})
    elif construct == "service_connection":
        counts.update({"pipe_count": max(counts["pipe_count"], 1 if any(service in {"water", "sewer", "storm", "fuel", "gas"} for service in services) else 0), "conduit_count": max(counts["conduit_count"], 1 if any(service in {"power", "data", "fiber", "signal", "utility"} for service in services) else 0), "junction_box_count": max(counts["junction_box_count"], 1), "valve_count": max(counts["valve_count"], 1 if any(service in {"water", "sewer", "storm", "fuel", "gas"} for service in services) else 0)})
    elif construct == "maintenance_access":
        counts.update({"walkway_count": max(1, segment_count), "catwalk_count": max(1, segment_count // 2), "guardrail_count": max(2, segment_count * 2), "safety_gate_count": 2})
    return counts


def _infra_network_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    services = _infra_network_services(values, construct)
    nodes = _infra_network_nodes(values, construct)
    segment_count = _infra_network_segments(values, construct, nodes)
    counts = _infra_network_counts(values, construct, services, segment_count)
    state: dict[str, Any] = {
        construct: name,
        "infrastructure_network_construct": construct,
        "infrastructure_network_kind": kind,
        "action": _snake_id(values.get("action") or _INFRA_NETWORK_ACTIONS.get(construct), "route_infrastructure_network"),
        f"{construct}_count": 1,
        "infrastructure_network_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "infrastructure_network",
        "enabled": not _disabled(values.get("enabled", True)),
        "services": services,
        "service_type": services[0] if services else kind,
        "network_type": kind,
        "utility_type": services[0] if services else kind,
        "network_nodes": nodes,
        "service_nodes": nodes,
        "line_segments": segment_count,
        "capacity": _number(values.get("capacity"), default=1.0),
        "redundancy": _number(values.get("redundancy"), default=0.25),
        "voltage": _number(values.get("voltage"), default=12.0),
        "pressure": _number(values.get("pressure"), default=1.0),
        "storage_capacity": _number(values.get("storage_capacity"), default=1.0),
        "pump_capacity": _number(values.get("pump_capacity"), default=1.0),
        "treatment_capacity": _number(values.get("treatment_capacity"), default=1.0),
        "station_spacing": _number(values.get("station_spacing"), default=0.8),
        "ridership": _number(values.get("ridership"), default=0.5),
        "maintenance_access_count": 0 if construct == "maintenance_access" or _disabled(values.get("maintenance_access")) else 1,
        "service_connection_count": counts.get("service_connection_count", 0),
        **counts,
    }
    if construct == "maintenance_access":
        state.update({"access_type": "maintenance_access", "traversal_type": "maintenance_corridor", "maintenance_access_type": kind, "service_type": "maintenance"})
    elif construct == "transit_line":
        state.update({"transit_modes": services, "stations": nodes, "stops": nodes, "station_count": counts.get("transit_station_count", len(nodes))})
    elif construct == "transit_station":
        state.update({"station_count": 1, "transit_modes": services, "coverage_radius": _number(values.get("coverage_radius"), default=0.8)})
    elif construct in {"power_grid", "substation", "transformer_bank", "power_line"}:
        state.update({"infrastructure_type": "power_grid" if construct == "power_grid" else "substation" if construct in {"substation", "transformer_bank"} else "utility_run"})
    elif construct in {"data_network", "data_hub", "fiber_line"}:
        state.update({"infrastructure_type": "data_trunk"})
    elif construct in {"water_network", "pump_station", "water_tower"}:
        state.update({"infrastructure_type": "waterworks"})
    elif construct in {"sewer_network", "treatment_plant"}:
        state.update({"infrastructure_type": "sewer"})
    else:
        state.update({"infrastructure_type": "utility_network"})
    return state


def _infra_network_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _INFRA_NETWORK_ACTIONS.get(construct), "route_infrastructure_network")}
    services = _infra_network_services(values, construct)
    if services:
        affordance["services"] = services
    target = _surface_marker_value(values, "target", "district", "service", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _infra_network_child_core_name(name: str, construct: str) -> str:
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct == "service_network":
        return f"{name}_service_core"
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _city_plan_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_infra_network_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct == "service_network":
        return _expand_service_network_macro(node)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _expand_city_planning_macro(node, construct=construct)
    if construct in {"resource_flow", "world_metric"}:
        return _expand_simulation_macro(node, construct=construct)
    if construct == "utility_corridor":
        return _expand_city_planning_macro(node, construct=construct)
    if construct == "access":
        return _expand_access_macro_from_values(node)
    return _expand_city_child_macro(node, construct)


def _expand_infrastructure_network_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _infra_network_kind(values, construct)
    depth = max(0, int(_number(values.get("_infra_network_depth"), default=0.0)))
    core_name = _infra_network_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_infra_network_scale(values, construct),
        state=_infra_network_state(values, construct, name, kind),
        tags=[construct, kind, "infrastructure_network", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_INFRA_NETWORK_ACTIONS.get(construct), "route_infrastructure_network"): _infra_network_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_INFRA_NETWORK_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "supports", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_infra_network_depth"] = depth + 1
        if child_construct in _CITY_PLAN_CORE_SUFFIXES:
            child_values["_city_plan_depth"] = max(2, int(_number(child_values.get("_city_plan_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _INFRA_NETWORK_ROLES.get(child_construct, _CITY_PLAN_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_infra_network_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _infra_network_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    services = _infra_network_services(values, construct)
    nodes = _infra_network_nodes(values, construct)
    segment_count = _infra_network_segments(values, construct, nodes)

    if construct == "power_grid":
        add_child("service_network", "service_spine", {"services": ["power"], "density": values.get("density") or 2}, [center[0], center[1] + 0.58, center[2] + 0.04], relation="routes", description=f"Power grid {name} routes a power service spine.")
        for index, node_name in enumerate(nodes[:6]):
            add_child("substation", node_name, {"service_nodes": [node_name], "substations": 1}, [center[0] + (index - (len(nodes[:6]) - 1) / 2.0) * 0.52, center[1], center[2] + 0.05], relation="feeds", description=f"Power grid {name} feeds substation {node_name}.")
        add_child("power_line", "distribution_line", {"line_segments": segment_count, "network_nodes": nodes}, [center[0], center[1] - 0.50, center[2] + 0.04], relation="spans", description=f"Power grid {name} spans distribution line.")
        add_child("world_metric", "load_metric", {"metric": "grid_capacity", "metric_value": values.get("capacity") or 1.0}, [center[0] + 0.72, center[1] - 0.50, center[2] + 0.04], relation="reveals", description=f"Power grid {name} exposes grid capacity.")

    elif construct == "substation":
        add_child("transformer_bank", "transformers", {"transformers": values.get("transformers") or 4}, [center[0] - 0.28, center[1] + 0.36, center[2] + 0.04], relation="steps", description=f"Substation {name} places transformer bank.")
        add_child("power_line", "outgoing_line", {"line_segments": segment_count}, [center[0] + 0.28, center[1] + 0.36, center[2] + 0.04], relation="feeds", description=f"Substation {name} feeds outgoing power line.")
        add_child("maintenance_access", "service_walkway", {"line_segments": 1}, [center[0], center[1] - 0.32, center[2] + 0.04], relation="maintained_by", description=f"Substation {name} creates maintenance access.")

    elif construct == "transformer_bank":
        add_child("power_line", "primary", {"line_segments": max(1, segment_count)}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="feeds", description=f"Transformer bank {name} feeds primary power line.")
        add_child("service_connection", "secondary_taps", {"services": ["power"], "service_taps": values.get("service_taps") or 2}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="taps", description=f"Transformer bank {name} creates secondary service taps.")
        add_child("world_metric", "load_metric", {"metric": "transformer_load", "metric_value": values.get("load") or 0.6}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="reveals", description=f"Transformer bank {name} exposes load.")

    elif construct == "power_line":
        for index, node_name in enumerate(nodes[:6]):
            add_child("service_connection", f"{node_name}_tap", {"services": ["power"], "service_node": node_name}, [center[0] + (index - (len(nodes[:6]) - 1) / 2.0) * 0.42, center[1] + 0.30, center[2] + 0.04], relation="taps", description=f"Power line {name} creates service tap {node_name}.")
        add_child("maintenance_access", "line_access", {"line_segments": segment_count}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="maintained_by", description=f"Power line {name} creates line maintenance access.")

    elif construct == "water_network":
        add_child("service_network", "water_spine", {"services": ["water"], "density": values.get("density") or 2}, [center[0], center[1] + 0.56, center[2] + 0.04], relation="routes", description=f"Water network {name} routes water service spine.")
        add_child("pump_station", "pump", {"pump_capacity": values.get("pump_capacity") or 1.0}, [center[0] - 0.46, center[1], center[2] + 0.04], relation="pressurizes", description=f"Water network {name} adds pump station.")
        add_child("water_tower", "storage", {"storage_capacity": values.get("storage_capacity") or 1.0}, [center[0] + 0.46, center[1], center[2] + 0.04], relation="stores", description=f"Water network {name} adds water tower.")
        add_child("resource_flow", "water_flow", {"resource_type": "water", "flow_rate": values.get("flow_rate") or 1.0}, [center[0], center[1] - 0.42, center[2] + 0.04], relation="carries", description=f"Water network {name} carries water flow.")

    elif construct == "pump_station":
        add_child("resource_flow", "pressure_flow", {"resource_type": "water", "flow_rate": values.get("pump_capacity") or 1.0}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="pressurizes", description=f"Pump station {name} pressurizes water flow.")
        add_child("service_connection", "water_taps", {"services": ["water"]}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="feeds", description=f"Pump station {name} feeds water taps.")
        add_child("maintenance_access", "pump_access", {"line_segments": 1}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="maintained_by", description=f"Pump station {name} adds service access.")

    elif construct == "water_tower":
        add_child("resource_flow", "storage_flow", {"resource_type": "water", "capacity": values.get("storage_capacity") or 1.0}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="stores", description=f"Water tower {name} stores water flow.")
        add_child("service_connection", "outlet", {"services": ["water"]}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="feeds", description=f"Water tower {name} feeds service outlet.")
        add_child("world_metric", "pressure_metric", {"metric": "water_pressure", "metric_value": values.get("pressure") or 1.0}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="reveals", description=f"Water tower {name} exposes pressure.")

    elif construct == "sewer_network":
        add_child("service_network", "sewer_spine", {"services": ["sewer"], "density": values.get("density") or 2}, [center[0], center[1] + 0.54, center[2] + 0.04], relation="routes", description=f"Sewer network {name} routes sewer spine.")
        add_child("treatment_plant", "treatment", {"treatment_capacity": values.get("treatment_capacity") or 1.0}, [center[0] - 0.36, center[1] - 0.02, center[2] + 0.04], relation="drains_to", description=f"Sewer network {name} drains to treatment plant.")
        add_child("resource_flow", "wastewater_flow", {"resource_type": "wastewater", "flow_rate": values.get("flow_rate") or 1.0}, [center[0] + 0.36, center[1] - 0.02, center[2] + 0.04], relation="carries", description=f"Sewer network {name} carries wastewater flow.")
        add_child("maintenance_access", "manhole_access", {"line_segments": segment_count}, [center[0], center[1] - 0.42, center[2] + 0.04], relation="maintained_by", description=f"Sewer network {name} creates manhole access.")

    elif construct == "treatment_plant":
        add_child("resource_flow", "inflow", {"resource_type": "wastewater", "capacity": values.get("treatment_capacity") or 1.0}, [center[0] - 0.28, center[1] + 0.32, center[2] + 0.04], relation="processes", description=f"Treatment plant {name} processes inflow.")
        add_child("resource_flow", "outflow", {"resource_type": "treated_water", "capacity": values.get("treatment_capacity") or 1.0}, [center[0] + 0.28, center[1] + 0.32, center[2] + 0.04], relation="outputs", description=f"Treatment plant {name} creates treated outflow.")
        add_child("maintenance_access", "plant_access", {"line_segments": 1}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="maintained_by", description=f"Treatment plant {name} adds maintenance access.")

    elif construct == "data_network":
        add_child("service_network", "data_spine", {"services": ["data", "fiber"], "density": values.get("density") or 2}, [center[0], center[1] + 0.54, center[2] + 0.04], relation="routes", description=f"Data network {name} routes data spine.")
        add_child("data_hub", "hub", {"service_nodes": nodes}, [center[0] - 0.36, center[1], center[2] + 0.04], relation="aggregates", description=f"Data network {name} places data hub.")
        add_child("fiber_line", "fiber", {"line_segments": segment_count, "network_nodes": nodes}, [center[0] + 0.36, center[1], center[2] + 0.04], relation="spans", description=f"Data network {name} spans fiber line.")
        add_child("maintenance_access", "data_access", {"line_segments": segment_count}, [center[0], center[1] - 0.40, center[2] + 0.04], relation="maintained_by", description=f"Data network {name} creates cable maintenance access.")

    elif construct == "data_hub":
        add_child("fiber_line", "uplink", {"line_segments": max(1, segment_count)}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="uplinks", description=f"Data hub {name} creates fiber uplink.")
        add_child("service_connection", "drops", {"services": ["data"], "service_taps": values.get("service_taps") or 3}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="drops", description=f"Data hub {name} creates data drops.")
        add_child("world_metric", "bandwidth_metric", {"metric": "bandwidth_capacity", "metric_value": values.get("capacity") or 1.0}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="reveals", description=f"Data hub {name} exposes bandwidth.")

    elif construct == "fiber_line":
        for index, node_name in enumerate(nodes[:6]):
            add_child("service_connection", f"{node_name}_drop", {"services": ["data"], "service_node": node_name}, [center[0] + (index - (len(nodes[:6]) - 1) / 2.0) * 0.42, center[1] + 0.30, center[2] + 0.04], relation="drops", description=f"Fiber line {name} creates data drop {node_name}.")
        add_child("maintenance_access", "fiber_access", {"line_segments": segment_count}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="maintained_by", description=f"Fiber line {name} creates access route.")

    elif construct == "transit_line":
        stations = nodes[:12]
        for index, station in enumerate(stations):
            add_child("transit_station", station, {"station": station, "transit": services[0] if services else "transit"}, [center[0] + (index - (len(stations) - 1) / 2.0) * 0.52, center[1] + 0.34, center[2] + 0.04], relation="stops_at", description=f"Transit line {name} places station {station}.")
        add_child("service_connection", "power_data", {"services": ["power", "data"]}, [center[0] - 0.30, center[1] - 0.36, center[2] + 0.04], relation="serviced_by", description=f"Transit line {name} receives power and data.")
        add_child("maintenance_access", "track_access", {"line_segments": segment_count}, [center[0] + 0.30, center[1] - 0.36, center[2] + 0.04], relation="maintained_by", description=f"Transit line {name} adds track access.")

    elif construct == "transit_station":
        add_child("transit_node", "node", {"transit": services[0] if services else "transit"}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="places", description=f"Transit station {name} places transit node.")
        add_child("service_coverage", "coverage", {"service": "transit", "coverage_radius": values.get("coverage_radius") or 0.8}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="covers", description=f"Transit station {name} creates service coverage.")
        add_child("service_connection", "station_services", {"services": ["power", "data", "water"]}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="served_by", description=f"Transit station {name} receives building services.")

    elif construct == "service_connection":
        for index, service in enumerate(services[:6]):
            add_child("resource_flow", service, {"resource_type": service, "flow_rate": values.get("flow_rate") or 1.0}, [center[0] + (index - (len(services[:6]) - 1) / 2.0) * 0.24, center[1] + 0.30, center[2] + 0.04], relation="taps", description=f"Service connection {name} taps {service} flow.")
        add_child("world_metric", "connection_metric", {"metric": "service_capacity", "metric_value": values.get("capacity") or 1.0}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="reveals", description=f"Service connection {name} exposes service capacity.")

    elif construct == "maintenance_access":
        add_child("service_connection", "service_points", {"services": ["maintenance"], "service_taps": values.get("service_taps") or 2}, [center[0] - 0.24, center[1] + 0.30, center[2] + 0.04], relation="reaches", description=f"Maintenance access {name} reaches service points.")
        add_child("world_metric", "access_metric", {"metric": "maintenance_reach", "metric_value": values.get("coverage") or 1.0}, [center[0] + 0.24, center[1] + 0.30, center[2] + 0.04], relation="reveals", description=f"Maintenance access {name} exposes reach.")

    return objects, relationships


