def _building_service_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _BUILDING_SERVICE_KIND_DEFAULTS.get(construct, construct)
    for key in _BUILDING_SERVICE_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _building_service_core_name(name: str, construct: str) -> str:
    return f"{name}_{_BUILDING_SERVICE_CORE_SUFFIXES.get(construct, 'building_service_core')}"


def _building_service_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    floors = max(1, min(80, _positive_int(values.get("floors") or values.get("floor_count") or values.get("served_floors"), default=3)))
    if construct in {"building_service_plan", "service_core"}:
        return [0.72, 0.54, max(0.42, floors * 0.20)]
    if construct in {"plumbing_stack", "ventilation_duct", "service_shaft", "elevator_core"}:
        return [0.36, 0.28, max(0.50, floors * 0.22)]
    if construct in {"loading_dock"}:
        return [1.20, 0.70, 0.18]
    if construct in {"utility_room", "mechanical_room"}:
        return [0.86, 0.62, 0.22]
    return [0.50, 0.34, 0.16]


def _building_service_services(values: Mapping[str, Any], construct: str) -> list[str]:
    services = _gameplay_name_list(values, ("services", "service_types", "utilities", "utility_types"), default=[])
    if services:
        return _dedupe([_snake_id(item, "utility") for item in services])[:8]
    defaults = {
        "building_service_plan": ["power", "water", "sewer", "air", "data"],
        "service_core": ["power", "water", "air", "data"],
        "utility_room": ["power", "water", "data"],
        "mechanical_room": ["power", "air", "water"],
        "electrical_panel": ["power"],
        "meter_bank": ["power", "water", "gas"],
        "plumbing_stack": ["water", "sewer"],
        "hvac_system": ["air", "power"],
        "ventilation_duct": ["air"],
        "elevator_core": ["power"],
        "service_elevator": ["power"],
        "service_shaft": ["power", "water", "air"],
        "fire_suppression": ["water"],
        "sprinkler_zone": ["water"],
        "waste_chute": ["waste"],
        "loading_dock": ["power", "data"],
    }
    return list(defaults.get(construct, ["utility"]))


def _building_service_zones(values: Mapping[str, Any]) -> list[str]:
    zones = _gameplay_name_list(values, ("service_zones", "zones", "rooms", "served_rooms"), default=[])
    if zones:
        return zones[:24]
    count = max(1, min(24, _positive_int(values.get("room_count") or values.get("rooms_served") or values.get("rooms"), default=4)))
    return [f"zone_{index + 1:02d}" for index in range(count)]


def _building_service_counts(values: Mapping[str, Any], construct: str, services: Sequence[str]) -> dict[str, int]:
    floors = max(1, min(80, _positive_int(values.get("floors") or values.get("floor_count") or values.get("served_floors"), default=3)))
    zones = _building_service_zones(values)
    density = max(1, min(8, _positive_int(values.get("density") or values.get("detail_density"), default=1)))
    counts = _service_network_counts(services, multiplier=density)
    counts.update(
        {
            "floor_count": floors,
            "served_floor_count": floors,
            "rooms_served": len(zones),
            "service_zone_count": len(zones),
            "service_connection_count": max(1, len(services)),
            "junction_box_count": max(counts.get("junction_box_count", 0), len(services)),
            "support_count": max(counts.get("support_count", 0), max(2, floors)),
        }
    )
    if construct == "building_service_plan":
        counts.update({"service_core_count": 1, "utility_room_count": 1, "mechanical_room_count": 1, "electrical_panel_count": 1, "plumbing_stack_count": 1, "hvac_system_count": 1, "elevator_core_count": 1 if floors > 1 else 0, "fire_suppression_count": 1, "loading_dock_count": 1 if not _disabled(values.get("loading_dock", True)) else 0})
    elif construct == "service_core":
        counts.update({"electrical_panel_count": 1, "plumbing_stack_count": 1, "hvac_system_count": 1, "elevator_core_count": 1 if floors > 1 else 0, "service_shaft_count": max(1, _positive_int(values.get("shafts") or values.get("shaft_count"), default=2)), "conduit_count": max(counts["conduit_count"], floors), "pipe_count": max(counts["pipe_count"], floors), "duct_count": max(counts["duct_count"], floors)})
    elif construct == "utility_room":
        counts.update({"meter_bank_count": 1, "electrical_panel_count": 1, "plumbing_stack_count": 1, "service_connection_count": max(1, len(services))})
    elif construct == "mechanical_room":
        counts.update({"hvac_system_count": 1, "ventilation_duct_count": max(1, floors), "electrical_panel_count": 1, "plumbing_stack_count": 1, "duct_count": max(counts["duct_count"], floors * 2)})
    elif construct == "electrical_panel":
        counts.update({"meter_bank_count": 1, "conduit_count": max(counts["conduit_count"], max(2, len(zones))), "circuit_count": max(1, _positive_int(values.get("circuits") or values.get("circuit_count"), default=max(4, len(zones))))})
    elif construct == "meter_bank":
        counts.update({"junction_box_count": max(counts["junction_box_count"], max(2, len(services))), "meter_count": max(1, _positive_int(values.get("meters") or values.get("meter_count"), default=max(1, len(services))))})
    elif construct == "plumbing_stack":
        counts.update({"pipe_count": max(counts["pipe_count"], floors * 2), "valve_count": max(counts["valve_count"], floors), "waste_chute_count": 1, "sprinkler_zone_count": 1})
    elif construct == "hvac_system":
        counts.update({"ventilation_duct_count": max(1, floors), "duct_count": max(counts["duct_count"], floors * 2), "hvac_count": max(1, _positive_int(values.get("hvac_count") or values.get("units"), default=1))})
    elif construct == "ventilation_duct":
        counts.update({"duct_count": max(counts["duct_count"], max(1, floors)), "vent_count": max(1, _positive_int(values.get("vents") or values.get("vent_count"), default=max(2, len(zones))))})
    elif construct == "elevator_core":
        counts.update({"service_elevator_count": max(1, _positive_int(values.get("cars") or values.get("car_count"), default=1)), "service_shaft_count": 1, "elevator_count": max(1, _positive_int(values.get("cars") or values.get("car_count"), default=1)), "platform_count": floors, "safety_gate_count": floors})
    elif construct == "service_elevator":
        counts.update({"elevator_count": 1, "platform_count": floors, "safety_gate_count": floors, "loading_dock_count": 1 if not _disabled(values.get("loading_dock", True)) else 0})
    elif construct == "service_shaft":
        counts.update({"shaft_count": max(1, _positive_int(values.get("shafts") or values.get("shaft_count"), default=1)), "pipe_count": max(counts["pipe_count"], floors), "conduit_count": max(counts["conduit_count"], floors), "duct_count": max(counts["duct_count"], floors)})
    elif construct == "fire_suppression":
        counts.update({"sprinkler_zone_count": max(1, len(zones)), "pipe_count": max(counts["pipe_count"], floors), "valve_count": max(counts["valve_count"], max(1, floors // 2)), "hazard_field_count": 1})
    elif construct == "sprinkler_zone":
        counts.update({"pipe_count": max(counts["pipe_count"], 1), "valve_count": max(counts["valve_count"], 1), "hazard_field_count": 1})
    elif construct == "waste_chute":
        counts.update({"pipe_count": max(counts["pipe_count"], floors), "manhole_count": max(counts["manhole_count"], 1), "maintenance_access_count": 1})
    elif construct == "loading_dock":
        dock_bays = max(1, min(16, _positive_int(values.get("dock_bays") or values.get("dock_bay_count") or values.get("bays"), default=2)))
        counts.update({"dock_bay_count": dock_bays, "platform_count": dock_bays, "walkway_count": dock_bays, "service_connection_count": max(1, len(services)), "maintenance_access_count": 1})
    return counts


def _building_service_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    services = _building_service_services(values, construct)
    zones = _building_service_zones(values)
    counts = _building_service_counts(values, construct, services)
    floors = counts["floor_count"]
    state: dict[str, Any] = {
        construct: name,
        "building_service_construct": construct,
        "building_service_kind": kind,
        "action": _snake_id(values.get("action") or _BUILDING_SERVICE_ACTIONS.get(construct), "wire_building_services"),
        f"{construct}_count": 1,
        "building_service_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "building_services",
        "enabled": not _disabled(values.get("enabled", True)),
        "services": services,
        "service_type": services[0] if services else kind,
        "utility_type": services[0] if services else kind,
        "service_zones": zones,
        "served_floors": floors,
        "floor_count": floors,
        "rooms_served": len(zones),
        "service_load": _number(values.get("service_load") or values.get("load"), default=0.65),
        "fire_rating": _number(values.get("fire_rating"), default=1.0),
        "sprinkler_density": _number(values.get("sprinkler_density"), default=0.7),
        "airflow": _number(values.get("airflow"), default=1.0),
        "waste_capacity": _number(values.get("waste_capacity"), default=1.0),
        **counts,
    }
    if construct in {"elevator_core", "service_elevator", "service_shaft", "loading_dock"}:
        state.update({"access_type": kind, "traversal_type": kind, "maintenance_access_type": kind})
    elif construct in {"utility_room", "mechanical_room"}:
        state.update({"infrastructure_type": kind, "network_type": "building_services"})
    elif construct in {"electrical_panel", "meter_bank"}:
        state.update({"infrastructure_type": "substation", "network_type": "building_power"})
    elif construct in {"plumbing_stack", "fire_suppression", "sprinkler_zone", "waste_chute"}:
        state.update({"infrastructure_type": "waterworks" if construct != "waste_chute" else "sewer", "network_type": "building_plumbing"})
    elif construct in {"hvac_system", "ventilation_duct"}:
        state.update({"infrastructure_type": "utility_network", "network_type": "building_air"})
    else:
        state.update({"infrastructure_type": "utility_network", "network_type": "building_services"})
    return state


def _building_service_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _BUILDING_SERVICE_ACTIONS.get(construct), "wire_building_services")}
    target = _surface_marker_value(values, "target", "building", "room", "district", fallback="")
    if target:
        affordance["target"] = target
    affordance["services"] = _building_service_services(values, construct)
    return affordance


def _building_service_child_core_name(name: str, construct: str) -> str:
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct == "service_network":
        return f"{name}_service_core"
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_building_service_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct == "service_network":
        return _expand_service_network_macro(node)
    if construct in {"resource_flow", "world_metric", "hazard_field"}:
        return _expand_simulation_macro(node, construct=construct)
    if construct == "maintenance_access":
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct == "service_connection":
        return _expand_infrastructure_network_macro(node, construct=construct)
    return _expand_infra_network_child_macro(node, construct)


def _expand_building_services_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _building_service_kind(values, construct)
    depth = max(0, int(_number(values.get("_building_service_depth"), default=0.0)))
    core_name = _building_service_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_building_service_scale(values, construct),
        state=_building_service_state(values, construct, name, kind),
        tags=[construct, kind, "building_services", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_BUILDING_SERVICE_ACTIONS.get(construct), "wire_building_services"): _building_service_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_BUILDING_SERVICE_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "supports", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_building_service_depth"] = depth + 1
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(2, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _BUILDING_SERVICE_ROLES.get(child_construct, _INFRA_NETWORK_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_building_service_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _building_service_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    services = _building_service_services(values, construct)
    zones = _building_service_zones(values)
    floors = max(1, min(80, _positive_int(values.get("floors") or values.get("floor_count") or values.get("served_floors"), default=3)))

    if construct == "building_service_plan":
        add_child("service_core", "core", {"services": services, "served_floors": floors}, [center[0], center[1] + 0.58, center[2] + 0.05], relation="stacks", description=f"Building service plan {name} stacks a service core.")
        add_child("utility_room", "utility_room", {"services": services}, [center[0] - 0.54, center[1] + 0.08, center[2] + 0.04], relation="places", description=f"Building service plan {name} places utility room.")
        add_child("mechanical_room", "mechanical_room", {"services": ["power", "air", "water"]}, [center[0] + 0.54, center[1] + 0.08, center[2] + 0.04], relation="places", description=f"Building service plan {name} places mechanical room.")
        add_child("fire_suppression", "fire_safety", {"service_zones": zones}, [center[0] - 0.36, center[1] - 0.50, center[2] + 0.04], relation="protects", description=f"Building service plan {name} protects service zones.")
        add_child("loading_dock", "dock", {"dock_bays": values.get("dock_bays") or 2}, [center[0] + 0.36, center[1] - 0.50, center[2] + 0.04], relation="services", description=f"Building service plan {name} arranges loading dock.")

    elif construct == "service_core":
        add_child("electrical_panel", "power", {"services": ["power"]}, [center[0] - 0.42, center[1] + 0.36, center[2] + 0.04], relation="routes", description=f"Service core {name} routes power.")
        add_child("plumbing_stack", "plumbing", {"services": ["water", "sewer"]}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="routes", description=f"Service core {name} routes plumbing.")
        add_child("hvac_system", "hvac", {"services": ["air", "power"]}, [center[0] + 0.42, center[1] + 0.36, center[2] + 0.04], relation="conditions", description=f"Service core {name} routes HVAC.")
        add_child("elevator_core", "elevator", {"served_floors": floors}, [center[0] - 0.24, center[1] - 0.34, center[2] + 0.04], relation="moves_between", description=f"Service core {name} adds elevator core.")
        add_child("service_shaft", "shaft", {"served_floors": floors, "services": services}, [center[0] + 0.24, center[1] - 0.34, center[2] + 0.04], relation="stacks", description=f"Service core {name} adds utility shaft.")

    elif construct == "utility_room":
        add_child("meter_bank", "meters", {"services": services}, [center[0] - 0.30, center[1] + 0.34, center[2] + 0.04], relation="meters", description=f"Utility room {name} meters services.")
        add_child("electrical_panel", "panel", {"services": ["power"]}, [center[0], center[1] + 0.34, center[2] + 0.04], relation="distributes", description=f"Utility room {name} distributes power.")
        add_child("plumbing_stack", "plumbing", {"services": ["water", "sewer"]}, [center[0] + 0.30, center[1] + 0.34, center[2] + 0.04], relation="feeds", description=f"Utility room {name} feeds plumbing.")
        add_child("service_connection", "service_taps", {"services": services}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="connects", description=f"Utility room {name} connects building service taps.")

    elif construct == "mechanical_room":
        add_child("hvac_system", "hvac", {"services": ["air", "power"]}, [center[0] - 0.30, center[1] + 0.34, center[2] + 0.04], relation="drives", description=f"Mechanical room {name} drives HVAC.")
        add_child("ventilation_duct", "ducts", {"service_zones": zones}, [center[0], center[1] + 0.34, center[2] + 0.04], relation="routes", description=f"Mechanical room {name} routes ventilation ducts.")
        add_child("electrical_panel", "control_panel", {"services": ["power"]}, [center[0] + 0.30, center[1] + 0.34, center[2] + 0.04], relation="powers", description=f"Mechanical room {name} powers equipment.")
        add_child("plumbing_stack", "condensate", {"services": ["water"]}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="drains", description=f"Mechanical room {name} drains condensate.")

    elif construct == "electrical_panel":
        add_child("meter_bank", "meter", {"services": ["power"]}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="metered_by", description=f"Electrical panel {name} is metered.")
        add_child("service_connection", "circuits", {"services": ["power"], "service_taps": values.get("circuits") or len(zones)}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="distributes", description=f"Electrical panel {name} distributes circuits.")
        add_child("world_metric", "load_metric", {"metric": "electrical_load", "metric_value": values.get("service_load") or 0.65}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="reveals", description=f"Electrical panel {name} exposes load.")

    elif construct == "meter_bank":
        add_child("service_connection", "utility_taps", {"services": services, "service_taps": values.get("meters") or len(services)}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="meters", description=f"Meter bank {name} creates metered utility taps.")
        add_child("world_metric", "usage_metric", {"metric": "metered_usage", "metric_value": values.get("service_load") or 0.5}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="reveals", description=f"Meter bank {name} exposes usage.")

    elif construct == "plumbing_stack":
        add_child("service_connection", "water_taps", {"services": ["water", "sewer"], "service_taps": len(zones)}, [center[0] - 0.34, center[1] + 0.34, center[2] + 0.04], relation="feeds", description=f"Plumbing stack {name} feeds wet service taps.")
        add_child("waste_chute", "waste", {"served_floors": floors}, [center[0], center[1] + 0.34, center[2] + 0.04], relation="drains", description=f"Plumbing stack {name} pairs with waste chute.")
        add_child("sprinkler_zone", "sprinklers", {"service_zones": zones}, [center[0] + 0.34, center[1] + 0.34, center[2] + 0.04], relation="supplies", description=f"Plumbing stack {name} supplies sprinklers.")
        add_child("resource_flow", "water_flow", {"resource_type": "water", "flow_rate": values.get("flow_rate") or 1.0}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="carries", description=f"Plumbing stack {name} carries water flow.")

    elif construct == "hvac_system":
        add_child("ventilation_duct", "supply", {"service_zones": zones, "duct": "supply"}, [center[0] - 0.30, center[1] + 0.34, center[2] + 0.04], relation="supplies", description=f"HVAC system {name} supplies air.")
        add_child("ventilation_duct", "return", {"service_zones": zones, "duct": "return"}, [center[0] + 0.30, center[1] + 0.34, center[2] + 0.04], relation="returns", description=f"HVAC system {name} returns air.")
        add_child("service_connection", "power", {"services": ["power"]}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="powered_by", description=f"HVAC system {name} receives power.")

    elif construct == "ventilation_duct":
        for index, zone in enumerate(zones[:8]):
            add_child("resource_flow", zone, {"resource_type": "air", "flow_rate": values.get("airflow") or 1.0}, [center[0] + (index - (len(zones[:8]) - 1) / 2.0) * 0.24, center[1] + 0.30, center[2] + 0.04], relation="vents_to", description=f"Ventilation duct {name} vents to {zone}.")
        add_child("service_shaft", "shaft", {"services": ["air"], "served_floors": floors}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="rises_through", description=f"Ventilation duct {name} rises through service shaft.")

    elif construct == "elevator_core":
        add_child("service_elevator", "car", {"served_floors": floors, "cars": values.get("cars") or 1}, [center[0] - 0.24, center[1] + 0.32, center[2] + 0.04], relation="contains", description=f"Elevator core {name} contains service elevator.")
        add_child("service_shaft", "shaft", {"served_floors": floors, "services": ["power"]}, [center[0] + 0.24, center[1] + 0.32, center[2] + 0.04], relation="uses", description=f"Elevator core {name} uses service shaft.")
        add_child("maintenance_access", "machine_access", {"line_segments": 1}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="maintained_by", description=f"Elevator core {name} adds machine access.")

    elif construct == "service_elevator":
        add_child("service_connection", "power", {"services": ["power"]}, [center[0] - 0.24, center[1] + 0.30, center[2] + 0.04], relation="powered_by", description=f"Service elevator {name} receives power.")
        add_child("loading_dock", "dock", {"dock_bays": values.get("dock_bays") or 1}, [center[0] + 0.24, center[1] + 0.30, center[2] + 0.04], relation="serves", description=f"Service elevator {name} serves loading dock.")
        add_child("maintenance_access", "access", {"line_segments": 1}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="maintained_by", description=f"Service elevator {name} adds maintenance access.")

    elif construct == "service_shaft":
        add_child("plumbing_stack", "plumbing", {"services": ["water", "sewer"], "served_floors": floors}, [center[0] - 0.30, center[1] + 0.32, center[2] + 0.04], relation="carries", description=f"Service shaft {name} carries plumbing.")
        add_child("ventilation_duct", "air", {"services": ["air"], "served_floors": floors}, [center[0], center[1] + 0.32, center[2] + 0.04], relation="carries", description=f"Service shaft {name} carries air.")
        add_child("electrical_panel", "power", {"services": ["power"], "served_floors": floors}, [center[0] + 0.30, center[1] + 0.32, center[2] + 0.04], relation="carries", description=f"Service shaft {name} carries power.")

    elif construct == "fire_suppression":
        for index, zone in enumerate(zones[:8]):
            add_child("sprinkler_zone", zone, {"service_zones": [zone]}, [center[0] + (index - (len(zones[:8]) - 1) / 2.0) * 0.26, center[1] + 0.34, center[2] + 0.04], relation="protects", description=f"Fire suppression {name} protects {zone}.")
        add_child("plumbing_stack", "water_supply", {"services": ["water"], "served_floors": floors}, [center[0] - 0.24, center[1] - 0.30, center[2] + 0.04], relation="supplied_by", description=f"Fire suppression {name} uses water supply.")
        add_child("hazard_field", "fire_hazard", {"hazard_type": "fire", "hazard_level": values.get("fire_rating") or 1.0}, [center[0] + 0.24, center[1] - 0.30, center[2] + 0.04], relation="mitigates", description=f"Fire suppression {name} mitigates fire hazard.")

    elif construct == "sprinkler_zone":
        add_child("service_connection", "water", {"services": ["water"], "service_taps": 1}, [center[0] - 0.22, center[1] + 0.30, center[2] + 0.04], relation="supplied_by", description=f"Sprinkler zone {name} receives water.")
        add_child("hazard_field", "coverage", {"hazard_type": "fire", "coverage": values.get("sprinkler_density") or 0.7}, [center[0] + 0.22, center[1] + 0.30, center[2] + 0.04], relation="covers", description=f"Sprinkler zone {name} covers fire hazard.")

    elif construct == "waste_chute":
        add_child("service_connection", "waste_outlet", {"services": ["sewer", "waste"], "service_taps": 1}, [center[0] - 0.24, center[1] + 0.30, center[2] + 0.04], relation="drains_to", description=f"Waste chute {name} drains to service outlet.")
        add_child("resource_flow", "waste_flow", {"resource_type": "waste", "capacity": values.get("waste_capacity") or 1.0}, [center[0] + 0.24, center[1] + 0.30, center[2] + 0.04], relation="carries", description=f"Waste chute {name} carries waste flow.")
        add_child("maintenance_access", "cleanout", {"line_segments": 1}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="maintained_by", description=f"Waste chute {name} adds cleanout access.")

    elif construct == "loading_dock":
        add_child("service_connection", "dock_services", {"services": services}, [center[0] - 0.30, center[1] + 0.30, center[2] + 0.04], relation="served_by", description=f"Loading dock {name} receives service connections.")
        add_child("maintenance_access", "dock_access", {"line_segments": max(1, _positive_int(values.get("dock_bays") or values.get("dock_bay_count"), default=2))}, [center[0], center[1] + 0.30, center[2] + 0.04], relation="routes_to", description=f"Loading dock {name} creates dock access.")
        add_child("resource_flow", "cargo_flow", {"resource_type": values.get("cargo") or "cargo", "flow_rate": values.get("throughput") or 1.0}, [center[0] + 0.30, center[1] + 0.30, center[2] + 0.04], relation="handles", description=f"Loading dock {name} handles cargo flow.")

    return objects, relationships


