def _functional_interior_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _FUNCTIONAL_INTERIOR_KIND_DEFAULTS.get(construct, construct)
    for key in _FUNCTIONAL_INTERIOR_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _functional_interior_core_name(name: str, construct: str) -> str:
    return f"{name}_{_FUNCTIONAL_INTERIOR_CORE_SUFFIXES.get(construct, 'functional_interior_core')}"


def _functional_interior_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    area = max(1, min(16, _positive_int(values.get("area") or values.get("room_area") or values.get("room_size"), default=4)))
    if construct == "room_program":
        return [1.24, 0.96, 0.18]
    if construct in _FUNCTIONAL_ROOM_CONSTRUCTS:
        return [0.58 + area * 0.035, 0.46 + area * 0.028, 0.18]
    if construct in {"cabinet_wall", "counter_run"}:
        return [0.64, 0.14, 0.26]
    if construct in {"workstation_cluster", "appliance_bank", "fixture_cluster"}:
        return [0.48, 0.34, 0.22]
    if construct in {"medical_bed", "lab_bench"}:
        return [0.48, 0.24, 0.20]
    if construct == "tool_rack":
        return [0.46, 0.12, 0.28]
    return [0.30, 0.22, 0.18]


def _functional_room_role(values: Mapping[str, Any], construct: str) -> str:
    role = _surface_marker_value(values, "room_role", "role", "room", fallback="")
    if role:
        return _snake_id(role, _FUNCTIONAL_INTERIOR_KIND_DEFAULTS.get(construct, construct))
    defaults = {
        "room_program": "room_program",
        "lab_room": "lab",
        "med_bay": "medical",
        "workshop_room": "workshop",
        "storage_room": "storage",
        "office_room": "office",
        "fixture_cluster": "room_kit",
        "appliance_bank": "kitchen",
        "workstation_cluster": "office",
        "cabinet_wall": "storage",
        "counter_run": "workshop",
        "sanitary_fixture": "bathroom",
        "lab_bench": "lab",
        "medical_bed": "medical",
        "tool_rack": "workshop",
    }
    return defaults.get(construct, _FUNCTIONAL_INTERIOR_KIND_DEFAULTS.get(construct, construct))


def _functional_interior_services(values: Mapping[str, Any], construct: str) -> list[str]:
    services = _gameplay_name_list(values, ("services", "service_types", "utilities", "utility_types"), default=[])
    if services:
        return _dedupe([_snake_id(item, "utility") for item in services])[:8]
    defaults = {
        "room_program": ["power", "water", "air", "data"],
        "bathroom": ["water", "sewer", "air"],
        "kitchen": ["power", "water", "sewer", "air"],
        "lab_room": ["power", "water", "air", "data"],
        "med_bay": ["power", "water", "air", "data"],
        "workshop_room": ["power", "air", "data"],
        "control_room": ["power", "data", "air"],
        "storage_room": ["power", "air"],
        "office_room": ["power", "data", "air"],
        "bedroom": ["power", "air"],
        "fixture_cluster": ["power"],
        "appliance_bank": ["power", "water"],
        "workstation_cluster": ["power", "data"],
        "cabinet_wall": ["power"],
        "counter_run": ["power", "water"],
        "sanitary_fixture": ["water", "sewer"],
        "lab_bench": ["power", "water", "air", "data"],
        "medical_bed": ["power", "data"],
        "tool_rack": ["power"],
    }
    return list(defaults.get(construct, ["power"]))


def _functional_room_programs(values: Mapping[str, Any]) -> list[str]:
    raw_programs = _gameplay_name_list(values, ("room_programs", "room_types", "room_roles", "rooms"), default=[])
    if not raw_programs:
        raw_programs = ["bathroom", "kitchen", "lab_room", "med_bay", "workshop_room", "control_room", "storage_room", "office_room", "bedroom"]
    aliases = {
        "bath": "bathroom",
        "washroom": "bathroom",
        "lavatory": "bathroom",
        "galley": "kitchen",
        "laboratory": "lab_room",
        "lab": "lab_room",
        "medical": "med_bay",
        "clinic": "med_bay",
        "infirmary": "med_bay",
        "workshop": "workshop_room",
        "control": "control_room",
        "operations": "control_room",
        "storage": "storage_room",
        "office": "office_room",
        "sleeping": "bedroom",
    }
    programs: list[str] = []
    for item in raw_programs:
        key = aliases.get(_snake_id(item, "room"), _snake_id(item, "room"))
        if key in _FUNCTIONAL_ROOM_CONSTRUCTS and key != "room_program":
            programs.append(key)
    return _dedupe(programs)[:18]


def _functional_fixture_counts(values: Mapping[str, Any], construct: str, room_role: str) -> dict[str, int]:
    furniture = _room_furniture_state(values, room_role)
    defaults = {
        "room_program": {"room_program_count": len(_functional_room_programs(values)), "fixture_cluster_count": 1},
        "bathroom": {"fixture_count": 3, "sanitary_fixture_count": 3, "sink_count": 1, "toilet_count": 1, "shower_count": 1, "counter_count": 1, "plumbing_stack_count": 1, "ventilation_duct_count": 1},
        "kitchen": {"fixture_count": 6, "appliance_bank_count": 1, "appliance_count": 3, "counter_run_count": 2, "counter_count": 3, "cabinet_wall_count": 1, "cabinet_count": 4, "service_connection_count": 2},
        "lab_room": {"lab_bench_count": 2, "counter_count": 2, "cabinet_wall_count": 1, "cabinet_count": 3, "workstation_cluster_count": 1, "workstation_count": 2, "service_connection_count": 2},
        "med_bay": {"medical_bed_count": 2, "bed_count": 2, "sanitary_fixture_count": 1, "sink_count": 1, "cabinet_wall_count": 1, "cabinet_count": 2, "service_connection_count": 2},
        "workshop_room": {"workstation_cluster_count": 1, "workstation_count": 3, "tool_rack_count": 2, "tool_count": 8, "counter_run_count": 1, "counter_count": 2, "service_connection_count": 1},
        "control_room": {"workstation_cluster_count": 1, "workstation_count": 4, "cabinet_wall_count": 1, "cabinet_count": 2, "control_panel_count": 1, "terminal_count": 2, "service_connection_count": 2},
        "storage_room": {"cabinet_wall_count": 2, "cabinet_count": 5, "tool_rack_count": 1, "rack_count": 3, "shelf_count": 5},
        "office_room": {"workstation_cluster_count": 1, "workstation_count": 4, "cabinet_wall_count": 1, "cabinet_count": 2, "table_count": 2, "chair_count": 4, "service_connection_count": 1},
        "bedroom": {"medical_bed_count": 0, "bed_count": 1, "fixture_cluster_count": 1, "cabinet_count": 1, "lamp_count": 2},
        "fixture_cluster": {"fixture_count": 3, "table_count": 1, "chair_count": 2, "cabinet_count": 1},
        "appliance_bank": {"appliance_bank_count": 1, "appliance_count": 3, "counter_count": 1, "service_connection_count": 1},
        "workstation_cluster": {"workstation_cluster_count": 1, "workstation_count": 4, "table_count": 2, "chair_count": 4, "terminal_count": 1, "service_connection_count": 1},
        "cabinet_wall": {"cabinet_wall_count": 1, "cabinet_count": 4, "shelf_count": 3, "storage_capacity": 1},
        "counter_run": {"counter_run_count": 1, "counter_count": 3, "work_surface_count": 3, "cabinet_count": 2},
        "sanitary_fixture": {"sanitary_fixture_count": 1, "fixture_count": 1, "sink_count": 1, "plumbing_stack_count": 1, "service_connection_count": 1},
        "lab_bench": {"lab_bench_count": 1, "counter_count": 1, "work_surface_count": 1, "appliance_count": 1, "service_connection_count": 2},
        "medical_bed": {"medical_bed_count": 1, "bed_count": 1, "lamp_count": 1, "service_connection_count": 1},
        "tool_rack": {"tool_rack_count": 1, "tool_count": 6, "rack_count": 1, "shelf_count": 2},
    }
    counts = {key: int(value) for key, value in furniture.items()}
    counts.update(defaults.get(construct, {}))
    overrides = {
        "fixture_count": ("fixture_count", "fixtures"),
        "appliance_count": ("appliance_count", "appliances"),
        "workstation_count": ("workstation_count", "workstations", "desks"),
        "counter_count": ("counter_count", "counters", "workbenches"),
        "cabinet_count": ("cabinet_count", "cabinets", "lockers"),
        "sink_count": ("sink_count", "sinks"),
        "toilet_count": ("toilet_count", "toilets"),
        "shower_count": ("shower_count", "showers"),
        "bed_count": ("bed_count", "beds"),
        "tool_count": ("tool_count", "tools"),
        "rack_count": ("rack_count", "racks"),
        "work_surface_count": ("work_surface_count", "work_surfaces"),
    }
    for count_key, source_keys in overrides.items():
        provided = next((values.get(key) for key in source_keys if key in values), None)
        if provided is not None:
            counts[count_key] = max(0, min(96, _positive_int(provided, default=counts.get(count_key, 0))))
    counts["fixture_count"] = max(counts.get("fixture_count", 0), counts.get("sanitary_fixture_count", 0) + counts.get("appliance_count", 0))
    if _functional_interior_services(values, construct):
        counts["service_connection_count"] = max(1, counts.get("service_connection_count", 0))
    return counts


def _functional_interior_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    room_role = _functional_room_role(values, construct)
    services = _functional_interior_services(values, construct)
    counts = _functional_fixture_counts(values, construct, room_role)
    state: dict[str, Any] = {
        construct: name,
        "functional_interior_construct": construct,
        "functional_interior_kind": kind,
        "action": _snake_id(values.get("action") or _FUNCTIONAL_INTERIOR_ACTIONS.get(construct), "arrange_room"),
        f"{construct}_count": 1,
        "functional_interior_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "functional_interiors",
        "enabled": not _disabled(values.get("enabled", True)),
        "room_role": room_role,
        "room_layout": room_role,
        "furniture_type": _surface_marker_value(values, "furniture_type", fallback=kind if construct in _FUNCTIONAL_FIXTURE_CONSTRUCTS else room_role),
        "services": services,
        "service_type": services[0] if services else "power",
        "service_zones": _gameplay_name_list(values, ("service_zones", "zones"), default=[room_role]),
        "cleanliness": _number(values.get("cleanliness"), default=0.7 if construct in {"bathroom", "kitchen", "lab_room", "med_bay"} else 0.45),
        "sterility": _number(values.get("sterility"), default=0.85 if construct in {"lab_room", "med_bay", "lab_bench", "medical_bed"} else 0.2),
        "privacy": _number(values.get("privacy"), default=0.8 if construct in {"bathroom", "bedroom", "med_bay"} else 0.25),
        **counts,
    }
    if construct in _FUNCTIONAL_ROOM_CONSTRUCTS:
        state.update({"lathe_asset": "procedural_interior", "source_family": "procedural_interior", "interior_count": 1, "room_count": max(1, counts.get("room_program_count", 1))})
    else:
        state.update({"lathe_asset": "procedural_furniture", "source_family": "procedural_furniture", "furniture_count": max(1, counts.get("fixture_count", 1))})
    if construct in {"control_room", "workstation_cluster", "tool_rack"}:
        state["interaction_count"] = max(1, state.get("control_panel_count", 0) + state.get("terminal_count", 0))
    return state


def _functional_interior_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _FUNCTIONAL_INTERIOR_ACTIONS.get(construct), "arrange_room")}
    target = _surface_marker_value(values, "target", "room", "building", fallback="")
    if target:
        affordance["target"] = target
    affordance["services"] = _functional_interior_services(values, construct)
    return affordance


def _functional_interior_child_core_name(name: str, construct: str) -> str:
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _functional_interior_core_name(name, construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct in _INTERACTION_CORE_SUFFIXES:
        return _interaction_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_functional_interior_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _expand_functional_interior_macro(node, construct=construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in {"terminal", "control_panel", "interaction_prompt", "affordance", "usable"}:
        return _expand_interaction_ui_macro(node, construct=construct)
    if construct in {"resource_flow", "world_metric", "hazard_field"}:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_building_service_child_macro(node, construct)


def _expand_functional_interior_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _functional_interior_kind(values, construct)
    depth = max(0, int(_number(values.get("_functional_interior_depth"), default=0.0)))
    core_name = _functional_interior_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_functional_interior_scale(values, construct),
        state=_functional_interior_state(values, construct, name, kind),
        tags=[construct, kind, "functional_interiors", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_FUNCTIONAL_INTERIOR_ACTIONS.get(construct), "arrange_room"): _functional_interior_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_FUNCTIONAL_INTERIOR_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "contains", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_functional_interior_depth"] = depth + 1
        if child_construct in _BUILDING_SERVICE_CORE_SUFFIXES:
            child_values["_building_service_depth"] = max(1, int(_number(child_values.get("_building_service_depth"), default=0.0)))
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(2, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _FUNCTIONAL_INTERIOR_ROLES.get(child_construct, _BUILDING_SERVICE_ROLES.get(child_construct, _INFRA_NETWORK_ROLES.get(child_construct, _INTERACTION_MACRO_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_functional_interior_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _functional_interior_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} contains {child_construct} {suffix}."))

    services = _functional_interior_services(values, construct)
    room_role = _functional_room_role(values, construct)
    zones = _gameplay_name_list(values, ("service_zones", "zones"), default=[room_role])

    if construct == "room_program":
        programs = _functional_room_programs(values)
        for index, room_construct in enumerate(programs):
            x = center[0] + (index - (len(programs) - 1) / 2.0) * 0.34
            y = center[1] + (0.34 if index % 2 == 0 else -0.34)
            add_child(room_construct, f"{room_construct}_{index + 1:02d}", {"services": services, "room_role": _functional_room_role(values, room_construct)}, [x, y, center[2] + 0.04], relation="programs", description=f"Room program {name} creates {room_construct}.")
        add_child("service_core", "shared_services", {"services": services, "service_zones": programs or zones}, [center[0], center[1], center[2] + 0.08], relation="feeds", description=f"Room program {name} feeds its rooms from a shared service core.")

    elif construct == "bathroom":
        add_child("sanitary_fixture", "sink", {"sink_count": 1, "fixture_type": "sink", "services": ["water", "sewer"]}, [center[0] - 0.28, center[1] + 0.24, center[2] + 0.04], relation="plumbs", description=f"Bathroom {name} adds a sink fixture.")
        add_child("sanitary_fixture", "toilet", {"toilet_count": 1, "fixture_type": "toilet", "services": ["water", "sewer"]}, [center[0], center[1] + 0.24, center[2] + 0.04], relation="plumbs", description=f"Bathroom {name} adds a toilet fixture.")
        add_child("sanitary_fixture", "shower", {"shower_count": 1, "fixture_type": "shower", "services": ["water", "sewer", "air"]}, [center[0] + 0.28, center[1] + 0.24, center[2] + 0.04], relation="plumbs", description=f"Bathroom {name} adds a shower fixture.")
        add_child("plumbing_stack", "wet_wall", {"services": ["water", "sewer"], "service_zones": zones}, [center[0] - 0.18, center[1] - 0.28, center[2] + 0.04], relation="feeds", description=f"Bathroom {name} connects wet wall plumbing.")
        add_child("ventilation_duct", "exhaust", {"services": ["air"], "service_zones": zones}, [center[0] + 0.18, center[1] - 0.28, center[2] + 0.04], relation="vents", description=f"Bathroom {name} creates exhaust ventilation.")

    elif construct == "kitchen":
        add_child("counter_run", "prep_counter", {"counter_count": values.get("counters") or 3, "services": ["power", "water"]}, [center[0] - 0.34, center[1] + 0.28, center[2] + 0.04], relation="supports", description=f"Kitchen {name} builds prep counters.")
        add_child("appliance_bank", "appliances", {"appliance_count": values.get("appliances") or 3, "services": ["power", "water"]}, [center[0], center[1] + 0.28, center[2] + 0.04], relation="installs", description=f"Kitchen {name} installs appliance bank.")
        add_child("cabinet_wall", "storage_wall", {"cabinet_count": values.get("cabinets") or 4}, [center[0] + 0.34, center[1] + 0.28, center[2] + 0.04], relation="stores", description=f"Kitchen {name} adds cabinet storage.")
        add_child("service_connection", "kitchen_services", {"services": ["power", "water", "sewer"], "service_taps": 3}, [center[0], center[1] - 0.28, center[2] + 0.04], relation="feeds", description=f"Kitchen {name} receives utility taps.")

    elif construct == "lab_room":
        add_child("lab_bench", "bench_a", {"services": ["power", "water", "air", "data"], "counter_count": 1}, [center[0] - 0.28, center[1] + 0.28, center[2] + 0.04], relation="equips", description=f"Lab room {name} installs first lab bench.")
        add_child("lab_bench", "bench_b", {"services": ["power", "water", "air", "data"], "counter_count": 1}, [center[0] + 0.28, center[1] + 0.28, center[2] + 0.04], relation="equips", description=f"Lab room {name} installs second lab bench.")
