_INTERIOR_COMPOSITION_CORE_SUFFIXES = {
    "room_adjacency": "room_adjacency_core",
    "room_connection": "room_connection_core",
    "door_opening": "door_opening_core",
    "corridor_link": "corridor_link_core",
    "wall_run": "wall_run_core",
    "room_socket": "room_socket_core",
    "fixture_socket": "fixture_socket_core",
}

_INTERIOR_COMPOSITION_ROLES = {
    "room_adjacency": "environment_structure",
    "room_connection": "navigation",
    "door_opening": "navigation",
    "corridor_link": "navigation",
    "wall_run": "environment_structure",
    "room_socket": "environment_structure",
    "fixture_socket": "environment_structure",
}

_INTERIOR_COMPOSITION_KIND_KEYS = {
    "room_adjacency": ("adjacency_type", "layout_type", "type"),
    "room_connection": ("connection_type", "link_type", "type"),
    "door_opening": ("door_type", "opening_type", "type"),
    "corridor_link": ("corridor_type", "link_type", "type"),
    "wall_run": ("wall_type", "run_type", "type"),
    "room_socket": ("socket_role", "socket_type", "type"),
    "fixture_socket": ("fixture_type", "socket_role", "type"),
}

_INTERIOR_COMPOSITION_KIND_DEFAULTS = {
    "room_adjacency": "adjacent_rooms",
    "room_connection": "room_connection",
    "door_opening": "door_opening",
    "corridor_link": "corridor",
    "wall_run": "interior_wall",
    "room_socket": "room_socket",
    "fixture_socket": "fixture_socket",
}

_INTERIOR_COMPOSITION_ACTIONS = {
    "room_adjacency": "arrange_room_adjacency",
    "room_connection": "connect_rooms",
    "door_opening": "cut_door_opening",
    "corridor_link": "route_corridor_link",
    "wall_run": "place_wall_run",
    "room_socket": "prepare_room_socket",
    "fixture_socket": "prepare_fixture_socket",
}


def _interior_composition_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _INTERIOR_COMPOSITION_KIND_DEFAULTS.get(construct, construct)
    for key in _INTERIOR_COMPOSITION_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _interior_composition_core_name(name: str, construct: str) -> str:
    return f"{name}_{_INTERIOR_COMPOSITION_CORE_SUFFIXES.get(construct, 'interior_composition_core')}"


def _interior_composition_rooms(values: Mapping[str, Any], name: str) -> tuple[str, str]:
    source_room = _surface_marker_value(values, "from_room", "source_room", "room_a", "from", fallback="")
    target_room = _surface_marker_value(values, "to_room", "target_room", "room_b", "to", fallback="")
    rooms = _gameplay_name_list(values, ("connected_rooms", "adjacent_rooms", "rooms", "room_pair"), default=[])
    if not source_room and rooms:
        source_room = _snake_id(rooms[0], f"{name}_room_a")
    if not target_room and len(rooms) > 1:
        target_room = _snake_id(rooms[1], f"{name}_room_b")
    return source_room or f"{name}_room_a", target_room or f"{name}_room_b"


def _interior_composition_pairs(values: Mapping[str, Any], name: str) -> list[tuple[str, str]]:
    rooms = _gameplay_name_list(values, ("room_pairs", "adjacent_rooms", "connected_rooms", "rooms"), default=[])
    if len(rooms) >= 2:
        return [(_snake_id(rooms[index], f"room_{index + 1}"), _snake_id(rooms[index + 1], f"room_{index + 2}")) for index in range(len(rooms) - 1)][:16]
    return [_interior_composition_rooms(values, name)]


def _interior_composition_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    length = max(0.2, min(12.0, _number(values.get("length") or values.get("wall_length") or values.get("corridor_length"), default=1.0)))
    width = max(0.1, min(4.0, _number(values.get("width") or values.get("corridor_width") or values.get("opening_width"), default=1.0)))
    if construct == "room_adjacency":
        return [0.86, 0.46, 0.10]
    if construct == "room_connection":
        return [0.42, 0.20, 0.12]
    if construct == "door_opening":
        return [max(0.22, width * 0.18), 0.08, 0.28]
    if construct == "corridor_link":
        return [max(0.28, width * 0.18), max(0.32, length * 0.24), 0.08]
    if construct == "wall_run":
        return [max(0.40, length * 0.22), 0.08, 0.30]
    return [0.18, 0.18, 0.10]


def _interior_composition_counts(values: Mapping[str, Any], construct: str, name: str) -> dict[str, int]:
    pair_count = len(_interior_composition_pairs(values, name))
    doorways = max(0, min(32, _positive_int(values.get("doorway_count") or values.get("door_openings") or values.get("doors"), default=1)))
    sockets = max(0, min(64, _positive_int(values.get("socket_count") or values.get("sockets"), default=2)))
    counts = {
        f"{construct}_count": 1,
        "interior_composition_count": 1,
        "adjacency_pair_count": pair_count,
        "room_connection_count": 0,
        "door_opening_count": 0,
        "corridor_link_count": 0,
        "wall_run_count": 0,
        "room_socket_count": 0,
        "fixture_socket_count": 0,
        "door_count": 0,
        "opening_count": 0,
        "corridor_count": 0,
        "wall_count": 0,
        "socket_count": 0,
    }
    if construct == "room_adjacency":
        counts.update({"room_adjacency_count": 1, "room_connection_count": pair_count, "door_opening_count": pair_count, "corridor_link_count": pair_count, "wall_run_count": pair_count, "room_socket_count": pair_count * 2, "door_count": pair_count, "corridor_count": pair_count, "wall_count": pair_count, "socket_count": pair_count * 2})
    elif construct == "room_connection":
        counts.update({"room_connection_count": 1, "door_opening_count": doorways, "corridor_link_count": 1, "wall_run_count": 1, "room_socket_count": 2, "door_count": doorways, "corridor_count": 1, "wall_count": 1, "socket_count": 2})
    elif construct == "door_opening":
        counts.update({"door_opening_count": 1, "door_count": 1, "opening_count": 1})
    elif construct == "corridor_link":
        counts.update({"corridor_link_count": 1, "corridor_count": 1, "route_count": 1, "access_count": 1, "room_socket_count": 2, "socket_count": 2})
    elif construct == "wall_run":
        counts.update({"wall_run_count": 1, "wall_count": 1, "partition_count": 1, "door_opening_count": doorways, "door_count": doorways, "fixture_socket_count": sockets, "socket_count": sockets})
    elif construct == "room_socket":
        counts.update({"room_socket_count": 1, "socket_count": 1, "attach_count": 1})
    elif construct == "fixture_socket":
        counts.update({"fixture_socket_count": 1, "socket_count": 1, "fixture_count": 1, "attach_count": 1})
    return counts


def _interior_composition_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    source_room, target_room = _interior_composition_rooms(values, name)
    counts = _interior_composition_counts(values, construct, name)
    sockets = _gameplay_name_list(values, ("composition_sockets", "sockets", "socket_tags"), default=[])
    anchors = _gameplay_name_list(values, ("composition_anchors", "anchors", "attach_tags"), default=[])
    if construct in {"room_socket", "fixture_socket"} and not sockets:
        sockets = [f"{name}_{kind}"]
    if not anchors and source_room:
        anchors = [source_room]
    state: dict[str, Any] = {
        construct: name,
        "interior_composition_construct": construct,
        "interior_composition_kind": kind,
        "action": _snake_id(values.get("action") or _INTERIOR_COMPOSITION_ACTIONS.get(construct), "compose_interior"),
        "object_archetype": construct,
        "setpiece_layout": "interior_composition",
        "enabled": not _disabled(values.get("enabled", True)),
        "from_room": source_room,
        "to_room": target_room,
        "source_room": source_room,
        "target_room": target_room,
        "connected_rooms": [source_room, target_room],
        "connection_type": _surface_marker_value(values, "connection_type", "type", fallback=kind),
        "wall_side": _surface_marker_value(values, "wall_side", "side", fallback="shared"),
        "opening_width": _number(values.get("opening_width") or values.get("door_width"), default=0.9),
        "corridor_width": _number(values.get("corridor_width") or values.get("width"), default=1.2),
        "corridor_length": _number(values.get("corridor_length") or values.get("length"), default=2.0),
        "threshold_depth": _number(values.get("threshold_depth"), default=0.16),
        "wall_length": _number(values.get("wall_length") or values.get("length"), default=2.4),
        "wall_thickness": _number(values.get("wall_thickness") or values.get("thickness"), default=0.12),
        "socket_role": _surface_marker_value(values, "socket_role", "role", fallback=kind),
        "socket_target": _surface_marker_value(values, "socket_target", "target", "fixture", fallback=target_room),
        "attach_family": _surface_marker_value(values, "attach_family", "family", fallback="interior_fixture"),
        "attach_tags": _gameplay_name_list(values, ("attach_tags", "tags"), default=[kind]),
        "composition_sockets": sockets,
        "composition_anchors": anchors,
        **counts,
    }
    if construct in {"room_adjacency", "wall_run", "room_socket"}:
        state.update({"lathe_asset": "procedural_interior", "source_family": "procedural_interior", "interior_count": 1})
    elif construct in {"fixture_socket"}:
        state.update({"lathe_asset": "procedural_furniture", "source_family": "procedural_furniture", "furniture_count": 1})
    else:
        state.update({"lathe_asset": "procedural_access", "source_family": "procedural_access", "access_type": kind, "traversal_type": kind})
    return state


def _interior_composition_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    source_room, target_room = _interior_composition_rooms(values, _snake_id(values.get("name"), construct))
    return {
        "action": _snake_id(values.get("action") or _INTERIOR_COMPOSITION_ACTIONS.get(construct), "compose_interior"),
        "from_room": source_room,
        "to_room": target_room,
    }


def _interior_composition_child_core_name(name: str, construct: str) -> str:
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _functional_interior_core_name(name, construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct in _INTERACTION_CORE_SUFFIXES:
        return _interaction_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    if construct in {"door_action", "gate_action"}:
        return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_interior_composition_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _expand_functional_interior_macro(node, construct=construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in {"terminal", "control_panel", "interaction_prompt", "affordance", "usable"}:
        return _expand_interaction_ui_macro(node, construct=construct)
    if construct in {"door_action", "gate_action"}:
        return _expand_door_or_gate_action_macro(node, construct=construct)
    if construct in {"resource_flow", "world_metric", "hazard_field"}:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_functional_interior_child_macro(node, construct)


def _expand_interior_composition_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _interior_composition_kind(values, construct)
    depth = max(0, int(_number(values.get("_interior_composition_depth"), default=0.0)))
    core_name = _interior_composition_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_interior_composition_scale(values, construct),
        state=_interior_composition_state(values, construct, name, kind),
        tags=[construct, kind, "interior_composition", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_INTERIOR_COMPOSITION_ACTIONS.get(construct), "compose_interior"): _interior_composition_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_INTERIOR_COMPOSITION_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "contains", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_interior_composition_depth"] = depth + 1
        if child_construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
            child_values["_functional_interior_depth"] = max(1, int(_number(child_values.get("_functional_interior_depth"), default=0.0)))
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(2, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _INTERIOR_COMPOSITION_ROLES.get(child_construct, _FUNCTIONAL_INTERIOR_ROLES.get(child_construct, _BUILDING_SERVICE_ROLES.get(child_construct, _INFRA_NETWORK_ROLES.get(child_construct, _INTERACTION_MACRO_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure"))))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_interior_composition_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _interior_composition_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    source_room, target_room = _interior_composition_rooms(values, name)

    if construct == "room_adjacency":
        pairs = _interior_composition_pairs(values, name)
        for index, (left_room, right_room) in enumerate(pairs):
            x = center[0] + (index - (len(pairs) - 1) / 2.0) * 0.36
            add_child("room_connection", f"{left_room}_to_{right_room}", {"from_room": left_room, "to_room": right_room, "connection_type": values.get("connection_type") or "doorway"}, [x, center[1] + 0.22, center[2] + 0.04], relation="connects", description=f"Room adjacency {name} connects {left_room} to {right_room}.")

    elif construct == "room_connection":
        add_child("wall_run", "shared_wall", {"from_room": source_room, "to_room": target_room, "wall_side": values.get("wall_side") or "shared"}, [center[0] - 0.24, center[1] + 0.24, center[2] + 0.04], relation="cuts_through", description=f"Room connection {name} defines shared wall.")
        add_child("door_opening", "doorway", {"from_room": source_room, "to_room": target_room, "opening_width": values.get("opening_width") or 0.9}, [center[0], center[1] + 0.24, center[2] + 0.04], relation="opens", description=f"Room connection {name} cuts a doorway.")
        add_child("corridor_link", "corridor", {"from_room": source_room, "to_room": target_room, "corridor_width": values.get("corridor_width") or 1.2}, [center[0] + 0.24, center[1] + 0.24, center[2] + 0.04], relation="routes", description=f"Room connection {name} routes circulation.")
        add_child("room_socket", "left_socket", {"socket_target": source_room, "socket_role": "room_endpoint"}, [center[0] - 0.18, center[1] - 0.22, center[2] + 0.04], relation="anchors", description=f"Room connection {name} anchors {source_room}.")
        add_child("room_socket", "right_socket", {"socket_target": target_room, "socket_role": "room_endpoint"}, [center[0] + 0.18, center[1] - 0.22, center[2] + 0.04], relation="anchors", description=f"Room connection {name} anchors {target_room}.")

    elif construct == "door_opening":
        add_child("door_action", "door_motion", {"target": f"{source_room}_to_{target_room}", "movement": values.get("movement") or "swing", "opening_width": values.get("opening_width") or 0.9}, [center[0] - 0.18, center[1] + 0.22, center[2] + 0.04], relation="animates", description=f"Door opening {name} creates door movement.")
        add_child("interaction_prompt", "use_prompt", {"prompt": values.get("prompt") or "Use door", "action": "open_door"}, [center[0] + 0.18, center[1] + 0.22, center[2] + 0.04], relation="offers", description=f"Door opening {name} offers a door interaction.")

    elif construct == "corridor_link":
        add_child("room_socket", "from_socket", {"socket_target": source_room, "socket_role": "corridor_endpoint"}, [center[0] - 0.22, center[1] + 0.22, center[2] + 0.04], relation="starts_at", description=f"Corridor link {name} starts at {source_room}.")
        add_child("room_socket", "to_socket", {"socket_target": target_room, "socket_role": "corridor_endpoint"}, [center[0] + 0.22, center[1] + 0.22, center[2] + 0.04], relation="ends_at", description=f"Corridor link {name} ends at {target_room}.")
        add_child("world_metric", "travel_metric", {"metric": "corridor_length", "metric_value": values.get("corridor_length") or 2.0}, [center[0], center[1] - 0.22, center[2] + 0.04], relation="measures", description=f"Corridor link {name} exposes travel length.")

    elif construct == "wall_run":
        doorway_total = max(0, min(8, _positive_int(values.get("doorway_count") or values.get("doors"), default=1)))
        socket_total = max(0, min(12, _positive_int(values.get("socket_count") or values.get("sockets"), default=2)))
        for index in range(doorway_total):
            add_child("door_opening", f"opening_{index + 1:02d}", {"from_room": source_room, "to_room": target_room, "opening_width": values.get("opening_width") or 0.9}, [center[0] + (index - (doorway_total - 1) / 2.0) * 0.22, center[1] + 0.24, center[2] + 0.04], relation="cuts", description=f"Wall run {name} cuts doorway {index + 1}.")
        for index in range(socket_total):
            add_child("fixture_socket", f"fixture_socket_{index + 1:02d}", {"socket_target": source_room if index % 2 == 0 else target_room, "socket_role": values.get("socket_role") or "wall_fixture"}, [center[0] + (index - (socket_total - 1) / 2.0) * 0.16, center[1] - 0.24, center[2] + 0.04], relation="prepares", description=f"Wall run {name} prepares fixture socket {index + 1}.")

    elif construct == "room_socket":
        add_child("fixture_socket", "fixture_anchor", {"socket_target": values.get("socket_target") or source_room, "socket_role": values.get("socket_role") or "fixture_anchor"}, [center[0], center[1] + 0.20, center[2] + 0.04], relation="accepts", description=f"Room socket {name} prepares a fixture anchor.")

    elif construct == "fixture_socket":
        add_child("world_metric", "attach_metric", {"metric": "socket_ready", "metric_value": values.get("attach_count") or 1}, [center[0], center[1] + 0.20, center[2] + 0.04], relation="prepares", description=f"Fixture socket {name} exposes attach-ready state.")

    return objects, relationships


_PLACEMENT_CONSTRAINT_CORE_SUFFIXES = {
    "socket_binding": "socket_binding_core",
    "fixture_placement": "fixture_placement_core",
    "furniture_placement": "furniture_placement_core",
    "service_placement": "service_placement_core",
    "wall_attachment": "wall_attachment_core",
    "anchor_rule": "anchor_rule_core",
    "placement_constraint": "placement_constraint_core",
}

_PLACEMENT_CONSTRAINT_ROLES = {
    "socket_binding": "environment_structure",
    "fixture_placement": "environment_structure",
    "furniture_placement": "environment_structure",
    "service_placement": "environment_structure",
    "wall_attachment": "environment_structure",
    "anchor_rule": "environment_structure",
    "placement_constraint": "environment_structure",
}

_PLACEMENT_CONSTRAINT_KIND_KEYS = {
    "socket_binding": ("binding_type", "placement_mode", "type"),
    "fixture_placement": ("fixture_type", "placement_mode", "type"),
    "furniture_placement": ("furniture_type", "placement_mode", "type"),
    "service_placement": ("service_type", "placement_mode", "type"),
    "wall_attachment": ("attachment_type", "fixture_type", "type"),
    "anchor_rule": ("anchor_type", "socket_role", "type"),
    "placement_constraint": ("constraint_type", "placement_rule", "type"),
}

_PLACEMENT_CONSTRAINT_KIND_DEFAULTS = {
    "socket_binding": "socket_binding",
    "fixture_placement": "fixture",
    "furniture_placement": "furniture",
    "service_placement": "service",
    "wall_attachment": "wall_attachment",
    "anchor_rule": "anchor_rule",
    "placement_constraint": "placement_constraint",
}

_PLACEMENT_CONSTRAINT_ACTIONS = {
    "socket_binding": "bind_to_socket",
    "fixture_placement": "place_fixture",
    "furniture_placement": "place_furniture",
    "service_placement": "place_service",
    "wall_attachment": "attach_to_wall",
    "anchor_rule": "prepare_anchor_rule",
    "placement_constraint": "enforce_placement_constraint",
}


def _placement_constraint_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _PLACEMENT_CONSTRAINT_KIND_DEFAULTS.get(construct, construct)
    for key in _PLACEMENT_CONSTRAINT_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _placement_constraint_core_name(name: str, construct: str) -> str:
    return f"{name}_{_PLACEMENT_CONSTRAINT_CORE_SUFFIXES.get(construct, 'placement_constraint_core')}"


def _placement_target(values: Mapping[str, Any], name: str) -> str:
    return _surface_marker_value(values, "target_socket", "socket_target", "placement_target", "target", fallback=f"{name}_socket")


def _placement_object(values: Mapping[str, Any], name: str) -> str:
    return _surface_marker_value(values, "placed_object", "source_object", "object", "fixture", fallback=f"{name}_placed_object")


def _placement_fixture_construct(values: Mapping[str, Any], construct: str) -> str:
    raw = _surface_marker_value(values, "fixture_type", "furniture_type", "placed_family", "family", fallback="")
    key = _snake_id(raw, "fixture") if raw else ""
    aliases = {
        "appliance": "appliance_bank",
        "appliances": "appliance_bank",
        "appliance_bank": "appliance_bank",
        "counter": "counter_run",
        "counters": "counter_run",
        "counter_run": "counter_run",
        "cabinet": "cabinet_wall",
        "cabinets": "cabinet_wall",
        "cabinet_wall": "cabinet_wall",
        "sanitary": "sanitary_fixture",
        "sink": "sanitary_fixture",
        "toilet": "sanitary_fixture",
        "shower": "sanitary_fixture",
        "lab": "lab_bench",
        "lab_bench": "lab_bench",
        "medical": "medical_bed",
        "bed": "medical_bed",
        "medical_bed": "medical_bed",
        "tool": "tool_rack",
        "tools": "tool_rack",
        "tool_rack": "tool_rack",
        "workstation": "workstation_cluster",
        "workstations": "workstation_cluster",
        "desk": "workstation_cluster",
        "furniture": "fixture_cluster",
    }
    if key in aliases:
        return aliases[key]
    if construct == "furniture_placement":
        return "fixture_cluster"
    if construct == "service_placement":
        return "service_connection"
    return "fixture_cluster"


def _placement_services(values: Mapping[str, Any], construct: str) -> list[str]:
    services = _gameplay_name_list(values, ("services", "service_types", "utilities", "utility_types"), default=[])
    if services:
        return _dedupe([_snake_id(item, "utility") for item in services])[:8]
    if construct == "service_placement":
        return ["power", "water", "data"]
    if construct in {"fixture_placement", "wall_attachment"}:
        fixture_construct = _placement_fixture_construct(values, construct)
        return _functional_interior_services(values, fixture_construct)
    return ["power"]


def _placement_constraint_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    clearance = max(0.05, min(4.0, _number(values.get("clearance") or values.get("clearance_radius"), default=0.4)))
    if construct == "wall_attachment":
        return [0.46, 0.08, 0.30]
    if construct in {"fixture_placement", "furniture_placement"}:
        return [0.36, 0.28, 0.16]
    if construct == "service_placement":
        return [0.30, 0.20, 0.14]
    if construct == "placement_constraint":
        return [clearance, clearance, 0.08]
    return [0.22, 0.18, 0.10]


def _placement_constraint_counts(values: Mapping[str, Any], construct: str) -> dict[str, int]:
    placement_count = max(1, min(96, _positive_int(values.get("placement_count") or values.get("count"), default=1)))
    attach_count = max(0, min(96, _positive_int(values.get("attach_count") or values.get("attachments"), default=placement_count)))
    counts = {
        f"{construct}_count": 1,
        "placement_count": placement_count,
        "placement_constraint_system_count": 1,
        "socket_binding_count": 0,
        "fixture_placement_count": 0,
        "furniture_placement_count": 0,
        "service_placement_count": 0,
        "wall_attachment_count": 0,
        "anchor_rule_count": 0,
        "placement_constraint_count": 0,
        "room_socket_count": 0,
        "fixture_socket_count": 0,
        "socket_count": 0,
        "attach_count": attach_count,
    }
    if construct == "socket_binding":
        counts.update({"socket_binding_count": 1, "room_socket_count": 1, "fixture_socket_count": 1, "socket_count": 2})
    elif construct == "fixture_placement":
        counts.update({"fixture_placement_count": 1, "socket_binding_count": 1, "fixture_socket_count": placement_count, "fixture_count": placement_count, "socket_count": placement_count})
    elif construct == "furniture_placement":
        counts.update({"furniture_placement_count": 1, "socket_binding_count": 1, "fixture_socket_count": placement_count, "furniture_count": placement_count, "fixture_count": placement_count, "socket_count": placement_count})
    elif construct == "service_placement":
        counts.update({"service_placement_count": 1, "socket_binding_count": 1, "fixture_socket_count": placement_count, "service_connection_count": placement_count, "socket_count": placement_count})
    elif construct == "wall_attachment":
        counts.update({"wall_attachment_count": 1, "wall_run_count": 1, "fixture_socket_count": placement_count, "fixture_count": placement_count, "socket_count": placement_count})
    elif construct == "anchor_rule":
        counts.update({"anchor_rule_count": 1, "room_socket_count": placement_count, "fixture_socket_count": placement_count, "socket_count": placement_count * 2})
    elif construct == "placement_constraint":
        counts.update({"placement_constraint_count": 1, "anchor_rule_count": 1, "room_socket_count": 1, "socket_count": 1})
    return counts


def _placement_constraint_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    target_socket = _placement_target(values, name)
    placed_object = _placement_object(values, name)
    fixture_construct = _placement_fixture_construct(values, construct)
    services = _placement_services(values, construct)
    counts = _placement_constraint_counts(values, construct)
    state: dict[str, Any] = {
        construct: name,
        "placement_construct": construct,
        "placement_kind": kind,
        "action": _snake_id(values.get("action") or _PLACEMENT_CONSTRAINT_ACTIONS.get(construct), "place"),
        "object_archetype": construct,
        "setpiece_layout": "placement_constraints",
        "enabled": not _disabled(values.get("enabled", True)),
        "placement_mode": _surface_marker_value(values, "placement_mode", "mode", fallback="snap"),
        "placement_rule": _surface_marker_value(values, "placement_rule", "rule", "constraint", fallback=kind),
        "placement_target": target_socket,
        "target_socket": target_socket,
        "socket_target": target_socket,
        "source_object": placed_object,
        "placed_object": placed_object,
        "placed_family": fixture_construct,
        "fixture_type": _surface_marker_value(values, "fixture_type", "furniture_type", fallback=fixture_construct),
        "room_role": _surface_marker_value(values, "room_role", "room", fallback="room"),
        "wall_side": _surface_marker_value(values, "wall_side", "side", fallback="shared"),
        "socket_role": _surface_marker_value(values, "socket_role", "role", fallback=kind),
        "attach_family": _surface_marker_value(values, "attach_family", "family", fallback=fixture_construct),
        "attach_tags": _gameplay_name_list(values, ("attach_tags", "tags"), default=[fixture_construct, kind]),
        "composition_sockets": _gameplay_name_list(values, ("composition_sockets", "sockets", "socket_tags"), default=[target_socket]),
        "composition_anchors": _gameplay_name_list(values, ("composition_anchors", "anchors", "anchor_tags"), default=[placed_object]),
        "services": services,
        "snap_mode": _surface_marker_value(values, "snap_mode", fallback="socket"),
        "snap_strength": _number(values.get("snap_strength"), default=1.0),
        "clearance": _number(values.get("clearance"), default=0.35),
        "clearance_radius": _number(values.get("clearance_radius") or values.get("clearance"), default=0.35),
        "orientation": _surface_marker_value(values, "orientation", "facing", fallback="socket_forward"),
        "offset": _vector3(values.get("offset"), [values.get("offset_x") or 0.0, values.get("offset_y") or 0.0, values.get("offset_z") or 0.0]),
        "offset_x": _number(values.get("offset_x"), default=0.0),
        "offset_y": _number(values.get("offset_y"), default=0.0),
        "offset_z": _number(values.get("offset_z"), default=0.0),
        "priority": _number(values.get("priority") or values.get("anchor_priority"), default=0.5),
        "anchor_priority": _number(values.get("anchor_priority") or values.get("priority"), default=0.5),
        "allow_rotation": not _disabled(values.get("allow_rotation", True)),
        "align_to_wall": not _disabled(values.get("align_to_wall", construct in {"wall_attachment", "fixture_placement"})),
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback="default"),
        **counts,
    }
    if construct in {"service_placement"}:
        state.update({"lathe_asset": "procedural_infrastructure", "source_family": "procedural_infrastructure", "infrastructure_type": "utility_network", "network_type": "placed_services"})
    elif construct in {"fixture_placement", "furniture_placement", "wall_attachment"}:
        state.update({"lathe_asset": "procedural_furniture", "source_family": "procedural_furniture", "furniture_type": fixture_construct})
    else:
        state.update({"lathe_asset": "procedural_interior", "source_family": "procedural_interior", "interior_count": 1})
    return state


def _placement_constraint_affordance(values: Mapping[str, Any], construct: str, name: str) -> dict[str, Any]:
    return {
        "action": _snake_id(values.get("action") or _PLACEMENT_CONSTRAINT_ACTIONS.get(construct), "place"),
        "target_socket": _placement_target(values, name),
        "placed_object": _placement_object(values, name),
    }


def _placement_constraint_child_core_name(name: str, construct: str) -> str:
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _auto_layout_core_name(name, construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _placement_constraint_core_name(name, construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _functional_interior_core_name(name, construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_placement_constraint_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _SURFACE_AUTHORING_MACROS:
        return _expand_surface_authoring_macro(node, construct)
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _expand_auto_layout_macro(node, construct=construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _expand_placement_constraint_macro(node, construct=construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _expand_functional_interior_macro(node, construct=construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in {"resource_flow", "world_metric", "hazard_field"}:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_interior_composition_child_macro(node, construct)


def _expand_placement_constraint_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _placement_constraint_kind(values, construct)
    depth = max(0, int(_number(values.get("_placement_constraint_depth"), default=0.0)))
    core_name = _placement_constraint_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_placement_constraint_scale(values, construct),
        state=_placement_constraint_state(values, construct, name, kind),
        tags=[construct, kind, "placement_constraints", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_PLACEMENT_CONSTRAINT_ACTIONS.get(construct), "place"): _placement_constraint_affordance(values, construct, name)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_PLACEMENT_CONSTRAINT_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "arranges", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_placement_constraint_depth"] = depth + 1
        if child_construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
            child_values["_interior_composition_depth"] = max(1, int(_number(child_values.get("_interior_composition_depth"), default=0.0)))
        if child_construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
            child_values["_functional_interior_depth"] = max(1, int(_number(child_values.get("_functional_interior_depth"), default=0.0)))
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(2, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _PLACEMENT_CONSTRAINT_ROLES.get(child_construct, _INTERIOR_COMPOSITION_ROLES.get(child_construct, _FUNCTIONAL_INTERIOR_ROLES.get(child_construct, _BUILDING_SERVICE_ROLES.get(child_construct, _INFRA_NETWORK_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure"))))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_placement_constraint_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _placement_constraint_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} arranges {child_construct} {suffix}."))

    target_socket = _placement_target(values, name)
    placed_object = _placement_object(values, name)
    fixture_construct = _placement_fixture_construct(values, construct)
    placement_count = max(1, min(16, _positive_int(values.get("placement_count") or values.get("count"), default=1)))

    if construct == "socket_binding":
        add_child("room_socket", "room_anchor", {"socket_target": target_socket, "socket_role": values.get("socket_role") or "placement_anchor"}, [center[0] - 0.18, center[1] + 0.20, center[2] + 0.04], relation="anchors", description=f"Socket binding {name} prepares room-side socket {target_socket}.")
        add_child("fixture_socket", "fixture_anchor", {"socket_target": placed_object, "socket_role": values.get("socket_role") or "placed_object_anchor"}, [center[0] + 0.18, center[1] + 0.20, center[2] + 0.04], relation="binds", description=f"Socket binding {name} prepares fixture-side socket {placed_object}.")
        add_child("world_metric", "snap_metric", {"metric": "snap_strength", "metric_value": values.get("snap_strength") or 1.0}, [center[0], center[1] - 0.20, center[2] + 0.04], relation="measures", description=f"Socket binding {name} exposes snap strength.")

    elif construct == "fixture_placement":
        for index in range(placement_count):
            offset = (index - (placement_count - 1) / 2.0) * 0.20
            add_child("fixture_socket", f"fixture_socket_{index + 1:02d}", {"socket_target": target_socket, "socket_role": kind}, [center[0] + offset, center[1] + 0.24, center[2] + 0.04], relation="targets", description=f"Fixture placement {name} prepares socket {index + 1}.")
            add_child(fixture_construct, f"{fixture_construct}_{index + 1:02d}", {"fixture_type": kind, "furniture_type": kind, "room_role": values.get("room_role") or "room"}, [center[0] + offset, center[1] - 0.24, center[2] + 0.04], relation="places", description=f"Fixture placement {name} places {fixture_construct} {index + 1}.")
        add_child("socket_binding", "binding", {"target_socket": target_socket, "placed_object": placed_object, "fixture_type": kind}, [center[0], center[1], center[2] + 0.08], relation="binds", description=f"Fixture placement {name} binds fixture to socket.")

    elif construct == "furniture_placement":
        for index in range(placement_count):
            offset = (index - (placement_count - 1) / 2.0) * 0.22
            add_child("fixture_cluster", f"furniture_{index + 1:02d}", {"furniture_type": kind, "room_role": values.get("room_role") or kind}, [center[0] + offset, center[1] + 0.24, center[2] + 0.04], relation="places", description=f"Furniture placement {name} places furniture {index + 1}.")
        add_child("socket_binding", "furniture_binding", {"target_socket": target_socket, "placed_object": placed_object, "fixture_type": kind}, [center[0], center[1] - 0.22, center[2] + 0.04], relation="binds", description=f"Furniture placement {name} binds furniture to socket.")

    elif construct == "service_placement":
        add_child("fixture_socket", "service_socket", {"socket_target": target_socket, "socket_role": "service_tap"}, [center[0] - 0.18, center[1] + 0.22, center[2] + 0.04], relation="targets", description=f"Service placement {name} prepares service socket.")
        add_child("service_connection", "service_tap", {"services": _placement_services(values, construct), "service_taps": placement_count}, [center[0] + 0.18, center[1] + 0.22, center[2] + 0.04], relation="places", description=f"Service placement {name} places service taps.")
        add_child("socket_binding", "service_binding", {"target_socket": target_socket, "placed_object": placed_object, "fixture_type": "service"}, [center[0], center[1] - 0.22, center[2] + 0.04], relation="binds", description=f"Service placement {name} binds service to socket.")

    elif construct == "wall_attachment":
        add_child("wall_run", "attachment_wall", {"wall_side": values.get("wall_side") or "shared", "socket_count": placement_count}, [center[0] - 0.22, center[1] + 0.22, center[2] + 0.04], relation="attaches_to", description=f"Wall attachment {name} prepares wall run.")
        add_child("fixture_socket", "wall_socket", {"socket_target": target_socket, "socket_role": kind}, [center[0], center[1] + 0.22, center[2] + 0.04], relation="anchors", description=f"Wall attachment {name} prepares wall socket.")
        add_child(fixture_construct, "attached_fixture", {"fixture_type": kind, "furniture_type": kind}, [center[0] + 0.22, center[1] + 0.22, center[2] + 0.04], relation="places", description=f"Wall attachment {name} places attached fixture.")

    elif construct == "anchor_rule":
        add_child("room_socket", "room_anchor", {"socket_target": target_socket, "socket_role": kind, "attach_tags": values.get("attach_tags") or [kind]}, [center[0] - 0.18, center[1] + 0.20, center[2] + 0.04], relation="prepares", description=f"Anchor rule {name} prepares room anchor.")
        add_child("fixture_socket", "fixture_anchor", {"socket_target": placed_object, "socket_role": kind, "attach_tags": values.get("attach_tags") or [kind]}, [center[0] + 0.18, center[1] + 0.20, center[2] + 0.04], relation="prepares", description=f"Anchor rule {name} prepares fixture anchor.")
        add_child("world_metric", "priority_metric", {"metric": "anchor_priority", "metric_value": values.get("anchor_priority") or values.get("priority") or 0.5}, [center[0], center[1] - 0.20, center[2] + 0.04], relation="ranks", description=f"Anchor rule {name} ranks anchor priority.")

    elif construct == "placement_constraint":
        add_child("anchor_rule", "anchor_rule", {"target_socket": target_socket, "placed_object": placed_object, "placement_rule": kind}, [center[0] - 0.20, center[1] + 0.20, center[2] + 0.04], relation="requires", description=f"Placement constraint {name} prepares anchor rule.")
        add_child("world_metric", "clearance_metric", {"metric": "clearance", "metric_value": values.get("clearance") or 0.35}, [center[0] + 0.20, center[1] + 0.20, center[2] + 0.04], relation="measures", description=f"Placement constraint {name} tracks clearance.")

    return objects, relationships


