def _auto_layout_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _AUTO_LAYOUT_KIND_DEFAULTS.get(construct, construct)
    for key in _AUTO_LAYOUT_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _auto_layout_core_name(name: str, construct: str) -> str:
    return f"{name}_{_AUTO_LAYOUT_CORE_SUFFIXES.get(construct, 'auto_layout_core')}"


def _auto_layout_room_role(values: Mapping[str, Any]) -> str:
    if "room_role" in values and not _disabled(values.get("room_role")):
        return _snake_id(values.get("room_role"), "room")
    roles = _gameplay_name_list(values, ("room_roles", "room_programs", "room_types", "rooms"), default=[])
    return _snake_id(roles[0], "room") if roles else "room"


def _auto_layout_zones(values: Mapping[str, Any], room_role: str) -> list[str]:
    zones = _gameplay_name_list(values, ("layout_zones", "zones", "room_roles", "room_programs", "rooms"), default=[])
    if zones:
        return _dedupe([_snake_id(zone, "zone") for zone in zones])[:16]
    return [room_role]


def _auto_layout_items(values: Mapping[str, Any], keys: Sequence[str], defaults: Mapping[str, Sequence[str]], room_role: str, fallback: Sequence[str]) -> list[str]:
    items = _gameplay_name_list(values, keys, default=[])
    if not items:
        items = list(defaults.get(room_role, fallback))
    return _dedupe([_snake_id(item, "item") for item in items])[:24]


def _auto_layout_fixture_types(values: Mapping[str, Any], room_role: str) -> list[str]:
    return _auto_layout_items(values, ("fixture_types", "fixtures", "fixture_families"), _AUTO_LAYOUT_FIXTURE_DEFAULTS, room_role, ["fixture", "cabinet", "counter"])


def _auto_layout_furniture_types(values: Mapping[str, Any], room_role: str) -> list[str]:
    return _auto_layout_items(values, ("furniture_types", "furniture", "furnishings"), _AUTO_LAYOUT_FURNITURE_DEFAULTS, room_role, ["workstation", "cabinet"])


def _auto_layout_service_types(values: Mapping[str, Any], room_role: str) -> list[str]:
    return _auto_layout_items(values, ("service_types", "services", "utilities"), _AUTO_LAYOUT_SERVICE_DEFAULTS, room_role, ["power"])


def _auto_layout_wall_fixture_types(values: Mapping[str, Any], room_role: str) -> list[str]:
    return _auto_layout_items(values, ("wall_fixture_types", "wall_fixtures", "wall_attachments"), _AUTO_LAYOUT_WALL_FIXTURE_DEFAULTS, room_role, ["cabinet", "fixture"])


def _auto_layout_policy_enabled(values: Mapping[str, Any], key: str, default: bool = True) -> bool:
    if key not in values:
        return default
    return not _disabled(values.get(key))


def _auto_layout_requested_count(values: Mapping[str, Any], keys: Sequence[str], default: int) -> int:
    for key in keys:
        if key not in values:
            continue
        raw = values.get(key)
        if isinstance(raw, Mapping):
            return len(raw)
        if isinstance(raw, Sequence) and not isinstance(raw, str | bytes | bytearray):
            return len([item for item in raw if item not in {None, ""}])
        count = _positive_int(raw, default=0)
        if count > 0:
            return count
    return default


def _auto_layout_counts(values: Mapping[str, Any], construct: str) -> dict[str, int]:
    room_role = _auto_layout_room_role(values)
    zones = _auto_layout_zones(values, room_role)
    fixture_types = _auto_layout_fixture_types(values, room_role)
    furniture_types = _auto_layout_furniture_types(values, room_role)
    service_types = _auto_layout_service_types(values, room_role)
    wall_fixture_types = _auto_layout_wall_fixture_types(values, room_role)
    density = max(0.1, min(4.0, _number(values.get("layout_density") or values.get("density"), default=1.0)))
    zone_count = max(1, min(32, len(zones)))
    default_slots = max(zone_count * 3, int(round((len(fixture_types) + len(furniture_types) + len(wall_fixture_types) + 2) * density)))
    layout_slots = max(1, min(256, _auto_layout_requested_count(values, ("layout_slots", "slots", "socket_count"), default_slots)))
    fixture_count = max(0, min(128, _auto_layout_requested_count(values, ("fixture_layout_count", "fixture_placement_count", "fixture_count", "fixtures"), max(1, int(round(len(fixture_types) * density))))))
    furniture_count = max(0, min(128, _auto_layout_requested_count(values, ("furniture_layout_count", "furniture_placement_count", "furniture_count", "furniture"), max(1, int(round(len(furniture_types) * density))))))
    service_count = max(0, min(128, _auto_layout_requested_count(values, ("service_layout_count", "service_placement_count", "service_count", "services"), max(1, len(service_types)))))
    wall_count = max(0, min(128, _auto_layout_requested_count(values, ("wall_fixture_layout_count", "wall_attachment_count", "wall_fixture_count", "wall_fixtures"), max(1, int(round(len(wall_fixture_types) * density))))))
    door_count = max(0, min(64, _auto_layout_requested_count(values, ("doorway_count", "door_opening_count", "door_count"), max(1, zone_count - 1))))
    auto_place = _auto_layout_policy_enabled(values, "auto_place", True)
    auto_fixtures = auto_place and _auto_layout_policy_enabled(values, "auto_place_fixtures", True)
    auto_furniture = auto_place and _auto_layout_policy_enabled(values, "auto_place_furniture", True)
    auto_services = auto_place and _auto_layout_policy_enabled(values, "auto_place_services", True)
    auto_doors = _auto_layout_policy_enabled(values, "auto_place_doors", True)
    auto_placed = (fixture_count if auto_fixtures else 0) + (furniture_count if auto_furniture else 0) + (service_count if auto_services else 0) + (wall_count if auto_fixtures else 0)
    counts = {
        f"{construct}_count": 1,
        "auto_layout_system_count": 1,
        "auto_layout_count": 0,
        "room_layout_plan_count": 0,
        "fixture_layout_count": 0,
        "furniture_layout_count": 0,
        "service_layout_count": 0,
        "wall_fixture_layout_count": 0,
        "layout_zone_count": zone_count,
        "layout_socket_count": layout_slots,
        "socket_count": layout_slots,
        "auto_placed_count": auto_placed,
        "room_socket_count": 0,
        "fixture_socket_count": 0,
        "door_opening_count": 0,
        "corridor_link_count": 0,
        "wall_run_count": 0,
        "room_adjacency_count": 0,
        "fixture_placement_count": 0,
        "furniture_placement_count": 0,
        "service_placement_count": 0,
        "wall_attachment_count": 0,
        "socket_binding_count": 0,
        "service_connection_count": 0,
        "placement_constraint_count": 0,
        "anchor_rule_count": 0,
    }
    if construct == "auto_layout":
        counts.update({
            "auto_layout_count": 1,
            "room_layout_plan_count": 1,
            "fixture_layout_count": 1 if auto_fixtures else 0,
            "furniture_layout_count": 1 if auto_furniture else 0,
            "service_layout_count": 1 if auto_services else 0,
            "wall_fixture_layout_count": 1 if auto_fixtures else 0,
            "room_socket_count": layout_slots,
            "fixture_socket_count": max(0, fixture_count + furniture_count + wall_count),
            "fixture_placement_count": fixture_count if auto_fixtures else 0,
            "furniture_placement_count": furniture_count if auto_furniture else 0,
            "service_placement_count": service_count if auto_services else 0,
            "wall_attachment_count": wall_count if auto_fixtures else 0,
            "service_connection_count": service_count if auto_services else 0,
            "door_opening_count": door_count if auto_doors else 0,
            "corridor_link_count": max(0, zone_count - 1) if auto_doors else 0,
            "wall_run_count": zone_count,
            "room_adjacency_count": 1 if zone_count > 1 else 0,
            "socket_binding_count": auto_placed,
            "placement_constraint_count": 1,
            "anchor_rule_count": 1,
        })
    elif construct == "room_layout_plan":
        counts.update({"room_layout_plan_count": 1, "room_socket_count": layout_slots, "fixture_socket_count": layout_slots, "door_opening_count": door_count if auto_doors else 0, "corridor_link_count": max(0, zone_count - 1) if auto_doors else 0, "wall_run_count": zone_count, "room_adjacency_count": 1 if zone_count > 1 else 0})
    elif construct == "fixture_layout":
        counts.update({"fixture_layout_count": 1, "fixture_placement_count": fixture_count, "fixture_socket_count": fixture_count, "socket_binding_count": fixture_count, "auto_placed_count": fixture_count})
    elif construct == "furniture_layout":
        counts.update({"furniture_layout_count": 1, "furniture_placement_count": furniture_count, "fixture_socket_count": furniture_count, "socket_binding_count": furniture_count, "auto_placed_count": furniture_count})
    elif construct == "service_layout":
        counts.update({"service_layout_count": 1, "service_placement_count": service_count, "service_connection_count": service_count, "fixture_socket_count": service_count, "socket_binding_count": service_count, "auto_placed_count": service_count})
    elif construct == "wall_fixture_layout":
        counts.update({"wall_fixture_layout_count": 1, "wall_attachment_count": wall_count, "wall_run_count": zone_count, "fixture_socket_count": wall_count, "auto_placed_count": wall_count})
    return counts


def _auto_layout_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    counts = _auto_layout_counts(values, construct)
    width = max(0.44, min(4.0, counts["layout_socket_count"] * 0.08))
    depth = max(0.30, min(3.0, counts["layout_zone_count"] * 0.16))
    if construct == "room_layout_plan":
        return [width, depth, 0.10]
    if construct == "service_layout":
        return [max(0.30, width * 0.55), 0.22, 0.14]
    if construct == "wall_fixture_layout":
        return [max(0.36, width * 0.75), 0.08, 0.30]
    if construct in {"fixture_layout", "furniture_layout"}:
        return [max(0.36, width * 0.65), 0.26, 0.16]
    return [width, depth, 0.12]


def _auto_layout_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    room_role = _auto_layout_room_role(values)
    zones = _auto_layout_zones(values, room_role)
    fixture_types = _auto_layout_fixture_types(values, room_role)
    furniture_types = _auto_layout_furniture_types(values, room_role)
    service_types = _auto_layout_service_types(values, room_role)
    wall_fixture_types = _auto_layout_wall_fixture_types(values, room_role)
    density = max(0.1, min(4.0, _number(values.get("layout_density") or values.get("density"), default=1.0)))
    counts = _auto_layout_counts(values, construct)
    state: dict[str, Any] = {
        construct: name,
        "layout_construct": construct,
        "layout_kind": kind,
        "action": _snake_id(values.get("action") or _AUTO_LAYOUT_ACTIONS.get(construct), "auto_layout"),
        "object_archetype": construct,
        "setpiece_layout": "auto_layout",
        "enabled": not _disabled(values.get("enabled", True)),
        "room_role": room_role,
        "room_roles": zones,
        "rooms": zones,
        "layout_strategy": _surface_marker_value(values, "layout_strategy", "strategy", fallback=kind),
        "layout_density": density,
        "layout_zones": zones,
        "layout_slots": counts["layout_socket_count"],
        "auto_place": _auto_layout_policy_enabled(values, "auto_place", True),
        "auto_place_doors": _auto_layout_policy_enabled(values, "auto_place_doors", True),
        "auto_place_services": _auto_layout_policy_enabled(values, "auto_place_services", True),
        "auto_place_fixtures": _auto_layout_policy_enabled(values, "auto_place_fixtures", True),
        "auto_place_furniture": _auto_layout_policy_enabled(values, "auto_place_furniture", True),
        "fixture_types": fixture_types,
        "furniture_types": furniture_types,
        "wall_fixture_types": wall_fixture_types,
        "service_types": service_types,
        "services": service_types,
        "door_policy": _surface_marker_value(values, "door_policy", fallback="connect_adjacent_zones"),
        "socket_policy": _surface_marker_value(values, "socket_policy", fallback="wall_and_service_sockets"),
        "anchor_policy": _surface_marker_value(values, "anchor_policy", fallback="snap_to_prepared_sockets"),
        "placement_rules": _gameplay_name_list(values, ("placement_rules", "rules"), default=["clearance", "wall_alignment", "service_reach"]),
        "placement_constraints": _gameplay_name_list(values, ("placement_constraints", "constraints"), default=["clearance", "socket_reach"]),
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
        **counts,
    }
    if construct == "service_layout":
        state.update({"lathe_asset": "procedural_infrastructure", "source_family": "procedural_infrastructure", "infrastructure_type": "service_layout", "network_type": "room_services"})
    elif construct in {"fixture_layout", "furniture_layout", "wall_fixture_layout"}:
        state.update({"lathe_asset": "procedural_furniture", "source_family": "procedural_furniture", "furniture_type": construct})
    else:
        state.update({"lathe_asset": "procedural_interior", "source_family": "procedural_interior", "interior_count": 1})
    return state


def _auto_layout_affordance(values: Mapping[str, Any], construct: str, name: str) -> dict[str, Any]:
    room_role = _auto_layout_room_role(values)
    return {
        "action": _snake_id(values.get("action") or _AUTO_LAYOUT_ACTIONS.get(construct), "auto_layout"),
        "room_role": room_role,
        "layout_strategy": _auto_layout_kind(values, construct),
        "produces": ["room_sockets", "fixture_placements", "service_taps", "wall_attachments"],
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
    }


def _auto_layout_child_core_name(name: str, construct: str) -> str:
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _footprint_packing_core_name(name, construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _layout_resolution_core_name(name, construct)
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _auto_layout_core_name(name, construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _placement_constraint_core_name(name, construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _functional_interior_core_name(name, construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_auto_layout_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _SURFACE_AUTHORING_MACROS:
        return _expand_surface_authoring_macro(node, construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _expand_footprint_packing_macro(node, construct=construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _expand_layout_resolution_macro(node, construct=construct)
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _expand_auto_layout_macro(node, construct=construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _expand_placement_constraint_macro(node, construct=construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _expand_functional_interior_macro(node, construct=construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in {"resource_flow", "world_metric"}:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_placement_constraint_child_macro(node, construct)


def _expand_auto_layout_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _auto_layout_kind(values, construct)
    depth = max(0, int(_number(values.get("_auto_layout_depth"), default=0.0)))
    core_name = _auto_layout_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_auto_layout_scale(values, construct),
        state=_auto_layout_state(values, construct, name, kind),
        tags=[construct, kind, "auto_layout", "layout_automation", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_AUTO_LAYOUT_ACTIONS.get(construct), "auto_layout"): _auto_layout_affordance(values, construct, name)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_AUTO_LAYOUT_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "arranges", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        if child_construct in _AUTO_LAYOUT_CORE_SUFFIXES:
            child_values["_auto_layout_depth"] = depth + 1
        if child_construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
            child_values["_placement_constraint_depth"] = int(_number(child_values.get("_placement_constraint_depth"), default=0.0))
        if child_construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
            child_values["_interior_composition_depth"] = max(1, int(_number(child_values.get("_interior_composition_depth"), default=0.0)))
        if child_construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
            child_values["_functional_interior_depth"] = max(1, int(_number(child_values.get("_functional_interior_depth"), default=0.0)))
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(1, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _AUTO_LAYOUT_ROLES.get(child_construct, _PLACEMENT_CONSTRAINT_ROLES.get(child_construct, _INTERIOR_COMPOSITION_ROLES.get(child_construct, _FUNCTIONAL_INTERIOR_ROLES.get(child_construct, _BUILDING_SERVICE_ROLES.get(child_construct, _INFRA_NETWORK_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_auto_layout_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _auto_layout_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} arranges {child_construct} {suffix}."))

    room_role = _auto_layout_room_role(values)
    zones = _auto_layout_zones(values, room_role)
    fixture_types = _auto_layout_fixture_types(values, room_role)
    furniture_types = _auto_layout_furniture_types(values, room_role)
    service_types = _auto_layout_service_types(values, room_role)
    wall_fixture_types = _auto_layout_wall_fixture_types(values, room_role)
    counts = _auto_layout_counts(values, construct)
    auto_place = _auto_layout_policy_enabled(values, "auto_place", True)
    auto_fixtures = auto_place and _auto_layout_policy_enabled(values, "auto_place_fixtures", True)
    auto_furniture = auto_place and _auto_layout_policy_enabled(values, "auto_place_furniture", True)
    auto_services = auto_place and _auto_layout_policy_enabled(values, "auto_place_services", True)
    auto_doors = _auto_layout_policy_enabled(values, "auto_place_doors", True)

    if construct == "auto_layout":
        add_child("room_layout_plan", "room_plan", {"room_role": room_role, "room_roles": zones, "rooms": zones, "layout_zones": zones, "layout_slots": counts["layout_socket_count"]}, [center[0] - 0.28, center[1] + 0.26, center[2] + 0.04], relation="plans", description=f"Auto layout {name} prepares room sockets and circulation.")
        if auto_fixtures:
            add_child("fixture_layout", "fixtures", {"room_role": room_role, "fixture_types": fixture_types, "placement_count": counts["fixture_placement_count"], "fixture_count": counts["fixture_placement_count"]}, [center[0] + 0.28, center[1] + 0.26, center[2] + 0.04], relation="places", description=f"Auto layout {name} places fixtures onto prepared sockets.")
            add_child("wall_fixture_layout", "wall_fixtures", {"room_role": room_role, "wall_fixture_types": wall_fixture_types, "placement_count": counts["wall_attachment_count"], "wall_attachment_count": counts["wall_attachment_count"]}, [center[0] - 0.28, center[1] - 0.26, center[2] + 0.04], relation="mounts", description=f"Auto layout {name} mounts wall fixtures along room wall runs.")
        if auto_furniture:
            add_child("furniture_layout", "furniture", {"room_role": room_role, "furniture_types": furniture_types, "placement_count": counts["furniture_placement_count"], "furniture_count": counts["furniture_placement_count"]}, [center[0] + 0.28, center[1] - 0.26, center[2] + 0.04], relation="furnishes", description=f"Auto layout {name} places room furniture.")
        if auto_services:
            add_child("service_layout", "services", {"room_role": room_role, "service_types": service_types, "services": service_types, "placement_count": counts["service_placement_count"], "service_count": counts["service_placement_count"]}, [center[0], center[1] - 0.34, center[2] + 0.06], relation="feeds", description=f"Auto layout {name} places service taps near fixtures.")
        add_child("placement_constraint", "clearance_rules", {"constraint_type": "clearance", "placement_rule": values.get("placement_rule") or "clearance", "placement_constraints": values.get("placement_constraints") or ["clearance", "service_reach"], "room_role": room_role, "clearance": values.get("clearance") or 0.35}, [center[0], center[1], center[2] + 0.08], relation="constrains", description=f"Auto layout {name} preserves clearance and reach constraints.")

    elif construct == "room_layout_plan":
        for index, zone in enumerate(zones[:8]):
            offset = (index - (min(len(zones), 8) - 1) / 2.0) * 0.26
            add_child("room_socket", f"{zone}_entry_socket", {"room_role": zone, "socket_target": zone, "socket_role": "entry_anchor", "attach_tags": [zone, "entry"]}, [center[0] + offset, center[1] + 0.24, center[2] + 0.04], relation="prepares", description=f"Room layout {name} prepares entry socket for {zone}.")
            add_child("wall_run", f"{zone}_fixture_wall", {"room_role": zone, "wall_side": "primary", "socket_count": max(1, counts["layout_socket_count"] // max(1, len(zones)))}, [center[0] + offset, center[1] - 0.20, center[2] + 0.04], relation="prepares", description=f"Room layout {name} prepares fixture wall for {zone}.")
        if len(zones) > 1:
            add_child("room_adjacency", "adjacency_chain", {"rooms": zones, "adjacent_rooms": zones, "connection_type": "planned_adjacency"}, [center[0], center[1], center[2] + 0.08], relation="connects", description=f"Room layout {name} connects planned zones.")
        if auto_doors:
            for index in range(max(1, min(len(zones) - 1, counts["door_opening_count"]))):
                source_room = zones[index % len(zones)]
                target_room = zones[(index + 1) % len(zones)]
                offset = (index - (max(1, counts["door_opening_count"]) - 1) / 2.0) * 0.24
                add_child("door_opening", f"{source_room}_to_{target_room}_door", {"from_room": source_room, "to_room": target_room, "door_type": values.get("door_policy") or "standard"}, [center[0] + offset, center[1] + 0.04, center[2] + 0.10], relation="cuts", description=f"Room layout {name} cuts door from {source_room} to {target_room}.")
                add_child("corridor_link", f"{source_room}_to_{target_room}_corridor", {"from_room": source_room, "to_room": target_room, "connection_type": "corridor"}, [center[0] + offset, center[1] - 0.08, center[2] + 0.10], relation="routes", description=f"Room layout {name} routes corridor from {source_room} to {target_room}.")

    elif construct == "fixture_layout":
        placement_total = max(1, counts["fixture_placement_count"])
        for index in range(placement_total):
            fixture_type = fixture_types[index % len(fixture_types)]
            offset = (index - (placement_total - 1) / 2.0) * 0.20
            add_child("fixture_placement", f"{fixture_type}_{index + 1:02d}", {"fixture_type": fixture_type, "room_role": room_role, "target_socket": f"{room_role}_{fixture_type}_socket", "placed_object": f"{name}_{fixture_type}_{index + 1:02d}", "placement_group": name, "placement_count": 1}, [center[0] + offset, center[1] + 0.22, center[2] + 0.04], relation="places", description=f"Fixture layout {name} places {fixture_type} on a socket.")

    elif construct == "furniture_layout":
        placement_total = max(1, counts["furniture_placement_count"])
        for index in range(placement_total):
            furniture_type = furniture_types[index % len(furniture_types)]
            offset = (index - (placement_total - 1) / 2.0) * 0.22
            add_child("furniture_placement", f"{furniture_type}_{index + 1:02d}", {"furniture_type": furniture_type, "room_role": room_role, "target_socket": f"{room_role}_{furniture_type}_socket", "placed_object": f"{name}_{furniture_type}_{index + 1:02d}", "placement_group": name, "placement_count": 1}, [center[0] + offset, center[1] + 0.22, center[2] + 0.04], relation="places", description=f"Furniture layout {name} places {furniture_type}.")

    elif construct == "service_layout":
        placement_total = max(1, counts["service_placement_count"])
        for index in range(placement_total):
            service_type = service_types[index % len(service_types)]
            offset = (index - (placement_total - 1) / 2.0) * 0.20
            add_child("service_placement", f"{service_type}_tap_{index + 1:02d}", {"service_type": service_type, "services": [service_type], "room_role": room_role, "target_socket": f"{room_role}_{service_type}_tap", "placed_object": f"{name}_{service_type}_tap_{index + 1:02d}", "placement_group": name, "placement_count": 1}, [center[0] + offset, center[1] + 0.22, center[2] + 0.04], relation="feeds", description=f"Service layout {name} places {service_type} tap.")

    elif construct == "wall_fixture_layout":
        placement_total = max(1, counts["wall_attachment_count"])
        for index in range(placement_total):
            fixture_type = wall_fixture_types[index % len(wall_fixture_types)]
            offset = (index - (placement_total - 1) / 2.0) * 0.20
            add_child("wall_attachment", f"{fixture_type}_{index + 1:02d}", {"fixture_type": fixture_type, "attachment_type": fixture_type, "room_role": room_role, "wall_side": values.get("wall_side") or "primary", "target_socket": f"{room_role}_{fixture_type}_wall_socket", "placed_object": f"{name}_{fixture_type}_{index + 1:02d}", "placement_group": name, "placement_count": 1}, [center[0] + offset, center[1] + 0.22, center[2] + 0.04], relation="mounts", description=f"Wall fixture layout {name} mounts {fixture_type}.")

    return objects, relationships


_LAYOUT_RESOLUTION_CORE_SUFFIXES = {
    "layout_solver": "layout_solver_core",
    "room_bounds": "room_bounds_core",
    "wall_side_rule": "wall_side_rule_core",
    "socket_priority": "socket_priority_core",
    "clearance_zone": "clearance_zone_core",
    "layout_slot": "layout_slot_core",
}

_LAYOUT_RESOLUTION_ROLES = {
    "layout_solver": "environment_structure",
    "room_bounds": "environment_structure",
    "wall_side_rule": "environment_structure",
    "socket_priority": "environment_structure",
    "clearance_zone": "environment_structure",
    "layout_slot": "environment_structure",
}

_LAYOUT_RESOLUTION_KIND_KEYS = {
    "layout_solver": ("layout_strategy", "solver", "type"),
    "room_bounds": ("bounds_type", "room_shape", "type"),
    "wall_side_rule": ("wall_rule", "side_rule", "type"),
    "socket_priority": ("priority_rule", "socket_rule", "type"),
    "clearance_zone": ("clearance_policy", "zone_type", "type"),
    "layout_slot": ("slot_kind", "slot_type", "type"),
}

_LAYOUT_RESOLUTION_KIND_DEFAULTS = {
    "layout_solver": "room_fit",
    "room_bounds": "rectangular_room",
    "wall_side_rule": "best_wall_side",
    "socket_priority": "weighted_socket",
    "clearance_zone": "clearance_buffer",
    "layout_slot": "placement_slot",
}

_LAYOUT_RESOLUTION_ACTIONS = {
    "layout_solver": "resolve_room_layout",
    "room_bounds": "define_room_bounds",
    "wall_side_rule": "choose_wall_side",
    "socket_priority": "rank_socket",
    "clearance_zone": "reserve_clearance",
    "layout_slot": "prepare_layout_slot",
}


def _layout_resolution_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _LAYOUT_RESOLUTION_KIND_DEFAULTS.get(construct, construct)
    for key in _LAYOUT_RESOLUTION_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _layout_resolution_core_name(name: str, construct: str) -> str:
    return f"{name}_{_LAYOUT_RESOLUTION_CORE_SUFFIXES.get(construct, 'layout_resolution_core')}"


def _layout_resolution_bounds(values: Mapping[str, Any]) -> tuple[float, float, float]:
    bounds = values.get("bounds") if isinstance(values.get("bounds"), Mapping) else {}
    size = _vector3(bounds.get("size") if isinstance(bounds, Mapping) else values.get("size"), [0.0, 0.0, 0.0])
    width = _number(values.get("room_width") or values.get("width") or (size[0] if size[0] > 0 else None), default=4.0)
    depth = _number(values.get("room_depth") or values.get("depth") or (size[1] if size[1] > 0 else None), default=3.2)
    height = _number(values.get("room_height") or values.get("height") or (size[2] if size[2] > 0 else None), default=2.7)
    return max(0.5, min(64.0, width)), max(0.5, min(64.0, depth)), max(0.5, min(16.0, height))


def _layout_resolution_walls(values: Mapping[str, Any]) -> list[str]:
    walls = _gameplay_name_list(values, ("wall_sides", "walls", "preferred_walls"), default=["north", "east", "south", "west"])
    blocked = set(_gameplay_name_list(values, ("blocked_walls", "avoid_walls"), default=[]))
    available = [_snake_id(wall, "wall") for wall in walls if _snake_id(wall, "wall") not in blocked]
    if available:
        return _dedupe(available)[:8]
    return ["north", "east", "south", "west"]


def _layout_resolution_chosen_wall(values: Mapping[str, Any]) -> str:
    explicit = _surface_marker_value(values, "chosen_wall_side", "wall_side", "preferred_wall", fallback="")
    walls = _layout_resolution_walls(values)
    if explicit and explicit in walls:
        return explicit
    weights = values.get("wall_side_weights")
    if isinstance(weights, Mapping):
        weighted = sorted(((wall, _number(weights.get(wall), default=0.0)) for wall in walls), key=lambda item: item[1], reverse=True)
        if weighted:
            return weighted[0][0]
    return walls[0]


def _layout_resolution_slot_total(values: Mapping[str, Any]) -> int:
    width, depth, _ = _layout_resolution_bounds(values)
    spacing = max(0.25, min(8.0, _number(values.get("slot_spacing") or values.get("spacing"), default=1.0)))
    density = max(0.1, min(4.0, _number(values.get("layout_density") or values.get("density"), default=1.0)))
    perimeter_slots = max(1, int(round(((width + depth) * 2.0 / spacing) * density)))
    for key in ("layout_slot_count", "layout_slots", "slot_count", "slots", "socket_count"):
        if key in values:
            raw = values.get(key)
            if isinstance(raw, Mapping):
                return max(1, min(256, len(raw)))
            if isinstance(raw, Sequence) and not isinstance(raw, str | bytes | bytearray):
                return max(1, min(256, len([item for item in raw if item not in {None, ""}])))
            return max(1, min(256, _positive_int(raw, default=perimeter_slots)))
    return max(1, min(256, perimeter_slots))


def _layout_resolution_blocked_slots(values: Mapping[str, Any], slot_total: int) -> int:
    blocked = _gameplay_name_list(values, ("blocked_slots", "blocked_slot_ids"), default=[])
    if blocked:
        return min(slot_total, len(blocked))
    targets = _gameplay_name_list(values, ("clearance_targets", "clearance_zones"), default=[])
    return min(slot_total, len(targets))


def _layout_resolution_slot_positions(values: Mapping[str, Any], center: Sequence[float], limit: int | None = None) -> list[tuple[str, str, list[float]]]:
    width, depth, _ = _layout_resolution_bounds(values)
    walls = _layout_resolution_walls(values)
    total = _layout_resolution_slot_total(values)
    if limit is not None:
        total = min(total, max(0, limit))
    positions: list[tuple[str, str, list[float]]] = []
    for index in range(total):
        wall = walls[index % len(walls)]
        wall_index = index // len(walls)
        wall_slots = max(1, math.ceil(total / len(walls)))
        t = (wall_index + 0.5) / wall_slots - 0.5
        if wall in {"north", "south"}:
            local_x = t * width
            local_y = depth * 0.5 if wall == "north" else -depth * 0.5
        elif wall in {"east", "right"}:
            local_x = width * 0.5
            local_y = t * depth
        elif wall in {"west", "left"}:
            local_x = -width * 0.5
            local_y = t * depth
        else:
            local_x = t * width
            local_y = 0.0
        positions.append((f"slot_{index + 1:02d}", wall, [center[0] + local_x, center[1] + local_y, center[2] + 0.04]))
    return positions


def _layout_resolution_counts(values: Mapping[str, Any], construct: str) -> dict[str, int]:
    walls = _layout_resolution_walls(values)
    slot_total = _layout_resolution_slot_total(values)
    blocked_slots = _layout_resolution_blocked_slots(values, slot_total)
    resolved_slots = max(0, slot_total - blocked_slots)
    priority_sockets = max(1, min(resolved_slots or slot_total, _positive_int(values.get("priority_socket_count") or values.get("socket_priority_count"), default=min(8, resolved_slots or slot_total))))
    clearance_count = max(1, min(64, _positive_int(values.get("clearance_zone_count") or values.get("clearance_count"), default=max(1, blocked_slots or 1))))
    counts = {
        f"{construct}_count": 1,
        "layout_resolution_count": 1,
        "layout_solver_count": 0,
        "room_bounds_count": 0,
        "wall_side_rule_count": 0,
        "socket_priority_count": 0,
        "clearance_zone_count": 0,
        "layout_slot_count": slot_total,
        "resolved_slot_count": resolved_slots,
        "blocked_slot_count": blocked_slots,
        "wall_side_count": len(walls),
        "priority_socket_count": priority_sockets,
        "room_socket_count": 0,
        "fixture_socket_count": 0,
        "wall_run_count": 0,
        "placement_constraint_count": 0,
        "socket_binding_count": 0,
        "auto_layout_count": 0,
        "layout_socket_count": slot_total,
        "auto_placed_count": resolved_slots,
    }
    if construct == "layout_solver":
        counts.update({"layout_solver_count": 1, "room_bounds_count": 1, "wall_side_rule_count": 1, "socket_priority_count": 1, "clearance_zone_count": clearance_count, "room_socket_count": resolved_slots, "fixture_socket_count": resolved_slots, "wall_run_count": len(walls), "placement_constraint_count": clearance_count, "socket_binding_count": resolved_slots, "auto_layout_count": 1})
    elif construct == "room_bounds":
        counts.update({"room_bounds_count": 1, "wall_run_count": len(walls), "layout_zone_count": 1})
    elif construct == "wall_side_rule":
        counts.update({"wall_side_rule_count": 1, "wall_run_count": len(walls)})
    elif construct == "socket_priority":
        counts.update({"socket_priority_count": 1, "room_socket_count": priority_sockets, "world_metric_count": 1})
    elif construct == "clearance_zone":
        counts.update({"clearance_zone_count": clearance_count, "placement_constraint_count": clearance_count, "world_metric_count": 1})
    elif construct == "layout_slot":
        blocked = _disabled(values.get("slot_enabled", True)) or _disabled(values.get("enabled", True))
        counts.update({"layout_slot_count": 1, "resolved_slot_count": 0 if blocked else 1, "blocked_slot_count": 1 if blocked else 0, "room_socket_count": 1, "fixture_socket_count": 1, "socket_binding_count": 1})
    return counts


def _layout_resolution_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    width, depth, height = _layout_resolution_bounds(values)
    walls = _layout_resolution_walls(values)
    chosen_wall = _layout_resolution_chosen_wall(values)
    slot_total = _layout_resolution_slot_total(values)
    counts = _layout_resolution_counts(values, construct)
    floor_area = width * depth
    usable_area = max(0.0, floor_area - counts["blocked_slot_count"] * max(0.1, _number(values.get("clearance_radius") or values.get("clearance"), default=0.45)))
    state: dict[str, Any] = {
        construct: name,
        "layout_resolution_construct": construct,
        "layout_kind": kind,
        "action": _snake_id(values.get("action") or _LAYOUT_RESOLUTION_ACTIONS.get(construct), "resolve_layout"),
        "object_archetype": construct,
        "setpiece_layout": "layout_resolution",
        "enabled": not _disabled(values.get("enabled", True)),
        "room_role": _auto_layout_room_role(values),
        "room_width": width,
        "room_depth": depth,
        "room_height": height,
        "floor_area": round(floor_area, 4),
        "usable_area": round(usable_area, 4),
        "wall_sides": walls,
        "preferred_walls": _gameplay_name_list(values, ("preferred_walls", "wall_sides"), default=walls),
        "blocked_walls": _gameplay_name_list(values, ("blocked_walls", "avoid_walls"), default=[]),
        "chosen_wall_side": chosen_wall,
        "wall_side_weights": values.get("wall_side_weights") if isinstance(values.get("wall_side_weights"), Mapping) else {wall: 1.0 if wall == chosen_wall else 0.5 for wall in walls},
        "socket_priority": _number(values.get("socket_priority") or values.get("priority"), default=1.0),
        "socket_weights": values.get("socket_weights") if isinstance(values.get("socket_weights"), Mapping) else {f"slot_{index + 1:02d}": round(1.0 - index * 0.05, 3) for index in range(min(8, slot_total))},
        "priority_rules": _gameplay_name_list(values, ("priority_rules", "placement_rules"), default=["near_services", "avoid_doors", "prefer_wall"]),
        "clearance_radius": _number(values.get("clearance_radius") or values.get("clearance"), default=0.45),
        "clearance_policy": _surface_marker_value(values, "clearance_policy", fallback="reserve_walkable_buffer"),
        "clearance_targets": _gameplay_name_list(values, ("clearance_targets",), default=["door_swing", "walk_path"]),
        "clearance_zones": _gameplay_name_list(values, ("clearance_zones",), default=[]),
        "layout_axis": _surface_marker_value(values, "layout_axis", "axis", fallback="wall_perimeter"),
        "slot_spacing": max(0.25, min(8.0, _number(values.get("slot_spacing") or values.get("spacing"), default=1.0))),
        "slot_capacity": _positive_int(values.get("slot_capacity") or values.get("capacity"), default=slot_total),
        "slot_index": _positive_int(values.get("slot_index") or values.get("index"), default=1),
        "slot_kind": _surface_marker_value(values, "slot_kind", "slot_type", fallback="placement_slot"),
        "resolved_slots": _gameplay_name_list(values, ("resolved_slots",), default=[f"slot_{index + 1:02d}" for index in range(min(16, counts["resolved_slot_count"]))]),
        "blocked_slots": _gameplay_name_list(values, ("blocked_slots",), default=[]),
        "layout_slots": slot_total,
        "layout_strategy": _surface_marker_value(values, "layout_strategy", "strategy", fallback=kind),
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
        **counts,
    }
    state.update({"lathe_asset": "procedural_interior", "source_family": "procedural_interior", "interior_count": 1})
    return state


def _layout_resolution_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    width, depth, height = _layout_resolution_bounds(values)
    if construct == "room_bounds":
        return [max(0.4, min(4.0, width * 0.12)), max(0.4, min(4.0, depth * 0.12)), 0.06]
    if construct == "wall_side_rule":
        return [max(0.28, min(2.0, width * 0.08)), 0.08, 0.24]
    if construct == "clearance_zone":
        radius = _number(values.get("clearance_radius") or values.get("clearance"), default=0.45)
        return [max(0.12, radius * 0.5), max(0.12, radius * 0.5), 0.06]
    if construct == "layout_slot":
        return [0.18, 0.14, 0.08]
    if construct == "socket_priority":
        return [0.20, 0.16, 0.10]
    return [max(0.4, min(4.0, width * 0.10)), max(0.3, min(3.0, depth * 0.10)), max(0.08, min(0.5, height * 0.03))]


def _layout_resolution_affordance(values: Mapping[str, Any], construct: str, name: str) -> dict[str, Any]:
    return {
        "action": _snake_id(values.get("action") or _LAYOUT_RESOLUTION_ACTIONS.get(construct), "resolve_layout"),
        "room_role": _auto_layout_room_role(values),
        "chosen_wall_side": _layout_resolution_chosen_wall(values),
        "slot_count": _layout_resolution_slot_total(values),
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
    }


def _layout_resolution_child_core_name(name: str, construct: str) -> str:
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _footprint_packing_core_name(name, construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _layout_resolution_core_name(name, construct)
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _auto_layout_core_name(name, construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _placement_constraint_core_name(name, construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_layout_resolution_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _SURFACE_AUTHORING_MACROS:
        return _expand_surface_authoring_macro(node, construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _expand_footprint_packing_macro(node, construct=construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _expand_layout_resolution_macro(node, construct=construct)
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _expand_auto_layout_macro(node, construct=construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _expand_placement_constraint_macro(node, construct=construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _FUNCTIONAL_INTERIOR_CORE_SUFFIXES:
        return _expand_functional_interior_macro(node, construct=construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_auto_layout_child_macro(node, construct)


def _expand_layout_resolution_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _layout_resolution_kind(values, construct)
    depth = max(0, int(_number(values.get("_layout_resolution_depth"), default=0.0)))
    core_name = _layout_resolution_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_layout_resolution_scale(values, construct),
        state=_layout_resolution_state(values, construct, name, kind),
        tags=[construct, kind, "layout_resolution", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_LAYOUT_RESOLUTION_ACTIONS.get(construct), "resolve_layout"): _layout_resolution_affordance(values, construct, name)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_LAYOUT_RESOLUTION_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "arranges", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        if child_construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
            child_values["_layout_resolution_depth"] = depth + 1
        if child_construct in _AUTO_LAYOUT_CORE_SUFFIXES:
            child_values["_auto_layout_depth"] = max(1, int(_number(child_values.get("_auto_layout_depth"), default=0.0)))
        if child_construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
            child_values["_placement_constraint_depth"] = max(1, int(_number(child_values.get("_placement_constraint_depth"), default=0.0)))
        if child_construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
            child_values["_interior_composition_depth"] = max(1, int(_number(child_values.get("_interior_composition_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _LAYOUT_RESOLUTION_ROLES.get(child_construct, _AUTO_LAYOUT_ROLES.get(child_construct, _PLACEMENT_CONSTRAINT_ROLES.get(child_construct, _INTERIOR_COMPOSITION_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_layout_resolution_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _layout_resolution_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} resolves {child_construct} {suffix}."))

    width, depth_size, _height = _layout_resolution_bounds(values)
    walls = _layout_resolution_walls(values)
    chosen_wall = _layout_resolution_chosen_wall(values)
    counts = _layout_resolution_counts(values, construct)
    room_role = _auto_layout_room_role(values)
    slots = _layout_resolution_slot_positions(values, center, limit=32)

    if construct == "layout_solver":
        add_child("room_bounds", "bounds", {"room_role": room_role, "wall_sides": walls}, [center[0], center[1], center[2] + 0.04], relation="bounds", description=f"Layout solver {name} defines room bounds before placing objects.")
        add_child("wall_side_rule", "wall_choice", {"room_role": room_role, "wall_sides": walls, "chosen_wall_side": chosen_wall, "preferred_walls": values.get("preferred_walls") or walls}, [center[0] - width * 0.20, center[1], center[2] + 0.08], relation="chooses", description=f"Layout solver {name} chooses wall side {chosen_wall}.")
        add_child("socket_priority", "priority", {"room_role": room_role, "chosen_wall_side": chosen_wall, "priority_socket_count": counts["priority_socket_count"]}, [center[0] + width * 0.20, center[1], center[2] + 0.08], relation="ranks", description=f"Layout solver {name} ranks sockets by wall and service reach.")
        add_child("clearance_zone", "clearance", {"room_role": room_role, "clearance_zone_count": counts["clearance_zone_count"], "clearance_targets": values.get("clearance_targets") or ["door_swing", "walk_path"]}, [center[0], center[1] - depth_size * 0.20, center[2] + 0.08], relation="reserves", description=f"Layout solver {name} reserves clearance zones before slots are consumed.")
        for index, (slot_name, wall, position) in enumerate(slots):
            blocked = index < counts["blocked_slot_count"]
            add_child("layout_slot", slot_name, {"slot_index": index + 1, "slot_kind": "blocked_slot" if blocked else "placement_slot", "chosen_wall_side": wall, "wall_side": wall, "slot_enabled": not blocked, "target_socket": f"{room_role}_{slot_name}", "socket_priority": max(0.1, 1.0 - index * 0.04)}, position, relation="prepares", description=f"Layout solver {name} prepares {slot_name} on {wall} wall.")
        add_child("auto_layout", "resolved_auto_layout", {"room_role": room_role, "layout_strategy": kind, "layout_slots": counts["resolved_slot_count"], "layout_slot_count": counts["resolved_slot_count"], "chosen_wall_side": chosen_wall, "wall_sides": walls, "room_width": width, "room_depth": depth_size, "room_height": _height, "_auto_layout_depth": 2}, [center[0], center[1] + depth_size * 0.20, center[2] + 0.10], relation="drives", description=f"Layout solver {name} drives auto layout with resolved slots.")

    elif construct == "room_bounds":
        wall_lengths = {"north": width, "south": width, "east": depth_size, "west": depth_size, "left": depth_size, "right": depth_size}
        for wall in walls[:8]:
            position = [center[0], center[1] + (depth_size * 0.5 if wall == "north" else -depth_size * 0.5 if wall == "south" else 0.0), center[2] + 0.04]
            if wall in {"east", "right"}:
                position = [center[0] + width * 0.5, center[1], center[2] + 0.04]
            elif wall in {"west", "left"}:
                position = [center[0] - width * 0.5, center[1], center[2] + 0.04]
            add_child("wall_run", f"{wall}_bounds", {"wall_side": wall, "wall_length": wall_lengths.get(wall, width), "socket_count": max(1, counts["layout_slot_count"] // max(1, len(walls)))}, position, relation="bounds", description=f"Room bounds {name} creates {wall} wall surface.")
        add_child("world_metric", "floor_area", {"metric": "floor_area", "metric_value": round(width * depth_size, 4)}, [center[0], center[1], center[2] + 0.10], relation="measures", description=f"Room bounds {name} exposes floor area.")

    elif construct == "wall_side_rule":
        for index, wall in enumerate(walls[:8]):
            offset = (index - (min(len(walls), 8) - 1) / 2.0) * 0.18
            add_child("wall_run", f"{wall}_candidate", {"wall_side": wall, "wall_length": width if wall in {"north", "south"} else depth_size, "socket_count": max(1, counts["layout_slot_count"] // max(1, len(walls)))}, [center[0] + offset, center[1] + 0.18, center[2] + 0.04], relation="scores", description=f"Wall-side rule {name} scores {wall} wall.")
        add_child("world_metric", "chosen_wall", {"metric": "chosen_wall_side", "metric_value": chosen_wall}, [center[0], center[1] - 0.18, center[2] + 0.04], relation="selects", description=f"Wall-side rule {name} selects {chosen_wall}.")

    elif construct == "socket_priority":
        priority_total = max(1, counts["priority_socket_count"])
        for index, (slot_name, wall, position) in enumerate(slots[:priority_total]):
            add_child("room_socket", slot_name, {"socket_target": f"{room_role}_{slot_name}", "socket_role": "priority_slot", "socket_priority": max(0.1, 1.0 - index * 0.08), "wall_side": wall}, position, relation="ranks", description=f"Socket priority {name} ranks {slot_name}.")
        add_child("world_metric", "priority_metric", {"metric": "socket_priority", "metric_value": values.get("socket_priority") or 1.0}, [center[0], center[1] - 0.20, center[2] + 0.04], relation="measures", description=f"Socket priority {name} exposes socket weighting.")

    elif construct == "clearance_zone":
        clearance_total = max(1, counts["clearance_zone_count"])
        targets = _gameplay_name_list(values, ("clearance_targets",), default=["door_swing", "walk_path"])
        for index in range(clearance_total):
            target = targets[index % len(targets)]
            offset = (index - (clearance_total - 1) / 2.0) * 0.18
            add_child("placement_constraint", f"{target}_clearance_{index + 1:02d}", {"constraint_type": "clearance", "placement_rule": "avoid_overlap", "clearance_radius": values.get("clearance_radius") or values.get("clearance") or 0.45, "target_socket": target}, [center[0] + offset, center[1] + 0.20, center[2] + 0.04], relation="blocks", description=f"Clearance zone {name} reserves space around {target}.")
        add_child("world_metric", "clearance_metric", {"metric": "clearance_radius", "metric_value": values.get("clearance_radius") or values.get("clearance") or 0.45}, [center[0], center[1] - 0.20, center[2] + 0.04], relation="measures", description=f"Clearance zone {name} exposes clearance radius.")

    elif construct == "layout_slot":
        slot_id = _surface_marker_value(values, "slot_id", "target_socket", "socket_target", fallback=f"{name}_slot")
        wall = _surface_marker_value(values, "chosen_wall_side", "wall_side", fallback=chosen_wall)
        blocked = _disabled(values.get("slot_enabled", True)) or _disabled(values.get("enabled", True))
        add_child("room_socket", "room_socket", {"socket_target": slot_id, "socket_role": "layout_slot", "wall_side": wall, "socket_priority": values.get("socket_priority") or 1.0}, [center[0] - 0.12, center[1] + 0.16, center[2] + 0.04], relation="prepares", description=f"Layout slot {name} prepares room socket {slot_id}.")
        add_child("fixture_socket", "fixture_socket", {"socket_target": slot_id, "socket_role": "fixture_slot", "wall_side": wall}, [center[0] + 0.12, center[1] + 0.16, center[2] + 0.04], relation="accepts", description=f"Layout slot {name} prepares fixture socket {slot_id}.")
        if blocked:
            add_child("placement_constraint", "blocked_slot", {"constraint_type": "blocked_slot", "placement_rule": "avoid_slot", "target_socket": slot_id}, [center[0], center[1] - 0.16, center[2] + 0.04], relation="blocks", description=f"Layout slot {name} marks {slot_id} unavailable.")
        else:
            add_child("socket_binding", "slot_binding", {"target_socket": slot_id, "placed_object": values.get("placed_object") or f"{slot_id}_occupant", "fixture_type": values.get("fixture_type") or values.get("slot_kind") or "fixture"}, [center[0], center[1] - 0.16, center[2] + 0.04], relation="binds", description=f"Layout slot {name} binds slot {slot_id}.")

    return objects, relationships


