_FOOTPRINT_DEFAULT_SIZES = {
    "counter": (1.2, 0.55, 0.9),
    "cabinet": (0.9, 0.45, 2.0),
    "appliance": (0.8, 0.7, 1.3),
    "sink": (0.65, 0.55, 0.9),
    "toilet": (0.55, 0.8, 0.9),
    "shower": (0.9, 0.9, 2.1),
    "lab_bench": (1.6, 0.7, 0.95),
    "medical_bed": (2.1, 0.9, 0.8),
    "workstation": (1.2, 0.8, 0.75),
    "tool_rack": (1.0, 0.35, 1.8),
    "bed": (2.0, 1.3, 0.65),
    "rack": (1.0, 0.45, 1.8),
}


def _footprint_packing_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _FOOTPRINT_PACKING_KIND_DEFAULTS.get(construct, construct)
    for key in _FOOTPRINT_PACKING_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _footprint_packing_core_name(name: str, construct: str) -> str:
    return f"{name}_{_FOOTPRINT_PACKING_CORE_SUFFIXES.get(construct, 'footprint_packing_core')}"


def _footprint_items(values: Mapping[str, Any]) -> list[str]:
    items = _gameplay_name_list(values, ("packed_items", "items", "fixture_types", "furniture_types", "footprints"), default=[])
    if items:
        return _dedupe([_snake_id(item, "item") for item in items])[:32]
    room_role = _auto_layout_room_role(values)
    return _dedupe([*_auto_layout_fixture_types(values, room_role), *_auto_layout_furniture_types(values, room_role)])[:12]


def _footprint_dimensions(values: Mapping[str, Any], item: str | None = None) -> tuple[float, float, float]:
    key = _snake_id(item or values.get("fixture_type") or values.get("furniture_type") or values.get("item_type"), "fixture")
    default_width, default_depth, default_height = _FOOTPRINT_DEFAULT_SIZES.get(key, (0.8, 0.6, 0.8))
    width = _number(values.get("footprint_width") or values.get("width"), default=default_width)
    depth = _number(values.get("footprint_depth") or values.get("depth"), default=default_depth)
    height = _number(values.get("footprint_height") or values.get("height"), default=default_height)
    return max(0.05, min(12.0, width)), max(0.05, min(12.0, depth)), max(0.05, min(8.0, height))


def _footprint_grid(values: Mapping[str, Any]) -> tuple[int, int, float]:
    room_width, room_depth, _ = _layout_resolution_bounds(values)
    cell_size = max(0.1, min(4.0, _number(values.get("cell_size") or values.get("slot_spacing"), default=0.5)))
    rows = _positive_int(values.get("grid_rows") or values.get("rows"), default=max(1, math.ceil(room_depth / cell_size)))
    columns = _positive_int(values.get("grid_columns") or values.get("columns"), default=max(1, math.ceil(room_width / cell_size)))
    return min(64, rows), min(64, columns), cell_size


def _footprint_cell_lists(values: Mapping[str, Any]) -> tuple[list[str], list[str]]:
    occupied = _gameplay_name_list(values, ("occupied_cells", "blocked_cells"), default=[])
    free = _gameplay_name_list(values, ("free_cells", "available_cells"), default=[])
    return occupied[:256], free[:256]


def _packing_vector3(value: Any, fallback: Sequence[float]) -> list[float]:
    if isinstance(value, Mapping):
        nested = value.get("position") or value.get("center") or value.get("translation")
        if nested is not None:
            return _packing_vector3(nested, fallback)
        return [
            _number(value.get("x"), default=float(fallback[0])),
            _number(value.get("y"), default=float(fallback[1])),
            _number(value.get("z"), default=float(fallback[2])),
        ]
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        raw = list(value)
        if len(raw) >= 3:
            return [_number(raw[0], default=float(fallback[0])), _number(raw[1], default=float(fallback[1])), _number(raw[2], default=float(fallback[2]))]
        if len(raw) >= 2:
            return [_number(raw[0], default=float(fallback[0])), _number(raw[1], default=float(fallback[1])), float(fallback[2])]
    return [float(fallback[0]), float(fallback[1]), float(fallback[2])]


def _footprint_pack_positions(values: Mapping[str, Any], center: Sequence[float], *, limit: int | None = None) -> list[dict[str, Any]]:
    items = _footprint_items(values) or ["item"]
    services = _gameplay_name_list(values, ("service_anchors", "required_services", "services", "service_types"), default=_auto_layout_service_types(values, _auto_layout_room_role(values))) or ["service"]
    requested = _positive_int(
        values.get("packed_transform_count") or values.get("resolved_transform_count") or values.get("packed_item_count") or values.get("packing_slot_count"),
        default=len(items),
    )
    total = max(1, min(limit or 64, requested))
    explicit_positions = values.get("packed_positions") or values.get("slot_positions")
    explicit_slots = values.get("packing_slots")
    axis = _surface_marker_value(values, "packing_axis", "layout_axis", "axis", fallback="row")
    rows, columns, cell_size = _footprint_grid(values)
    spacing = max(0.12, min(8.0, _number(values.get("packing_spacing") or values.get("slot_spacing"), default=cell_size)))
    origin = _packing_vector3(values.get("packing_origin") or values.get("origin"), center)
    column_count = max(1, min(columns, math.ceil(math.sqrt(total)) if axis not in {"line", "row"} else total))
    row_count = max(1, math.ceil(total / column_count))
    slots: list[dict[str, Any]] = []
    for index in range(total):
        item = items[index % len(items)]
        if isinstance(explicit_positions, Sequence) and not isinstance(explicit_positions, str | bytes | bytearray) and index < len(explicit_positions):
            position = _packing_vector3(list(explicit_positions)[index], origin)
        elif isinstance(explicit_slots, Sequence) and not isinstance(explicit_slots, str | bytes | bytearray) and index < len(explicit_slots):
            slot_raw = list(explicit_slots)[index]
            position = _packing_vector3(slot_raw, origin)
            if isinstance(slot_raw, Mapping):
                item = _snake_id(slot_raw.get("item") or slot_raw.get("packed_item") or item, item)
        else:
            row = index // column_count
            column = index % column_count
            x = origin[0] + (column - (column_count - 1) / 2.0) * spacing
            y = origin[1] + (row - (row_count - 1) / 2.0) * spacing
            if axis in {"column", "vertical"}:
                x = origin[0] + (row - (row_count - 1) / 2.0) * spacing
                y = origin[1] + (column - (column_count - 1) / 2.0) * spacing
            position = [x, y, origin[2]]
        rotation_z = _number(values.get("footprint_rotation") or values.get("rotation_degrees"), default=90.0 if axis in {"column", "vertical"} and index % 2 else 0.0)
        slot_id = f"slot_{index + 1:02d}"
        slots.append(
            {
                "slot_id": slot_id,
                "item": item,
                "position": [round(float(position[0]), 4), round(float(position[1]), 4), round(float(position[2]), 4)],
                "rotation": [0.0, 0.0, round(rotation_z, 4)],
                "service_anchor": services[index % len(services)],
                "cell": f"cell_{(index // max(1, columns)) + 1:02d}_{(index % max(1, columns)) + 1:02d}",
            }
        )
    return slots


def _footprint_pack_slot_map(slots: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    return {
        str(slot["slot_id"]): {
            "item": str(slot["item"]),
            "position": list(slot["position"]),
            "service_anchor": str(slot["service_anchor"]),
        }
        for slot in slots
        if "slot_id" in slot
    }


def _footprint_pack_transform_map(slots: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    return {
        str(slot["slot_id"]): {
            "item": str(slot["item"]),
            "position": list(slot["position"]),
            "rotation": list(slot["rotation"]),
        }
        for slot in slots
        if "slot_id" in slot
    }


_FIXTURE_CONTENT_ITEMS = {"sink", "toilet", "shower", "appliance", "terminal", "medical_bed", "lab_bench"}
_FURNITURE_CONTENT_ITEMS = {"counter", "cabinet", "workstation", "tool_rack", "rack", "bed", "lamp", "desk", "shelf", "chair", "table"}


def _content_asset_item(values: Mapping[str, Any], fallback: str = "item") -> str:
    return _snake_id(
        values.get("packed_item") or values.get("item_type") or values.get("fixture_type") or values.get("furniture_type") or fallback,
        fallback,
    )


def _content_family_for_item(item: str, values: Mapping[str, Any]) -> str:
    explicit = _surface_marker_value(values, "content_family", "source_family", "lathe_asset", fallback="")
    if explicit:
        return explicit
    if item in _FIXTURE_CONTENT_ITEMS | _FURNITURE_CONTENT_ITEMS:
        return "procedural_furniture"
    return "procedural_furniture"


def _content_asset_controls(item: str) -> dict[str, Any]:
    controls: dict[str, Any] = {"packed_item": item, "item_type": item, "furniture_type": item, "fixture_type": item}
    if item in {"counter", "workbench", "lab_bench"}:
        controls.update({"counter_count": 1, "work_surface_count": 1})
    if item in {"cabinet", "locker"}:
        controls.update({"cabinet_count": 1, "drawer_count": 2})
    if item in {"sink", "toilet", "shower", "appliance"}:
        controls.update({"appliance_count": 1, "service_anchor_count": 1})
    if item in {"workstation", "desk", "terminal"}:
        controls.update({"table_count": 1, "lamp_count": 1})
    if item in {"medical_bed", "bed"}:
        controls.update({"bed_count": 1, "cushion_count": 2})
    if item in {"tool_rack", "rack", "shelf"}:
        controls.update({"shelf_count": 1})
    if item == "lamp":
        controls.update({"lamp_count": 1})
    surface = _content_surface_profile(item, {})
    controls.update(
        {
            "surface_layer_count": max(1, len(surface["layers"])),
            "material_zone_count": max(1, len(surface["zones"])),
            "decal_count": max(1, len(surface["markings"])),
            "wear_pattern_count": max(1, len(surface["wear"])),
            "content_surface_plan_count": 1,
            "content_surface_zone_count": max(1, len(surface["zones"])),
            "content_decal_count": max(1, len(surface["markings"])),
        }
    )
    return controls


