def _content_surface_authoring(item: str, values: Mapping[str, Any]) -> dict[str, Any]:
    profile = _content_surface_profile(item, values)
    surface = {
        "materials": _dedupe([*profile["layers"], *[str(material) for material in profile["zones"].values()]]),
        "material_layers": profile["layers"],
        "zones": profile["zones"],
        "story_decals": profile["markings"],
        "decals": profile["markings"],
        "patterns": profile["wear"],
        "wear_story": _surface_marker_value(values, "wear_story", "wear", fallback=profile["wear"][0] if profile["wear"] else "field_scuff"),
        "wear_level": _number(values.get("wear_level") or values.get("usage_level"), default=0.35),
        "surface_layer_count": max(1, len(profile["layers"])),
        "material_zone_count": max(1, len(profile["zones"])),
        "decal_count": max(1, len(profile["markings"])),
        "wear_pattern_count": max(1, len(profile["wear"])),
    }
    raw = values.get("surface_overrides")
    if isinstance(raw, Mapping):
        _merge_surface_overrides(surface, raw)
    return surface


def _footprint_counts(values: Mapping[str, Any], construct: str) -> dict[str, int]:
    items = _footprint_items(values)
    rows, columns, _ = _footprint_grid(values)
    occupied_cells, free_cells = _footprint_cell_lists(values)
    total_cells = rows * columns
    occupied_count = len(occupied_cells) if occupied_cells else min(total_cells, _positive_int(values.get("occupied_cell_count"), default=max(0, len(items))))
    free_count = len(free_cells) if free_cells else max(0, total_cells - occupied_count)
    footprint_count = max(1, min(128, _positive_int(values.get("footprint_count") or values.get("placement_footprint_count"), default=max(1, len(items)))))
    packed_count = max(0, min(128, _positive_int(values.get("packed_item_count"), default=min(footprint_count, free_count or footprint_count))))
    collision_pairs = max(0, min(128, _positive_int(values.get("collision_pair_count"), default=max(0, footprint_count - packed_count))))
    service_count = max(0, min(64, _positive_int(values.get("service_reach_count") or values.get("service_count"), default=len(_auto_layout_service_types(values, _auto_layout_room_role(values))))))
    packing_slots = max(1, min(256, _positive_int(values.get("packing_slot_count") or values.get("layout_slot_count"), default=max(packed_count, len(items), 1))))
    packed_transforms = max(1, min(128, _positive_int(values.get("packed_transform_count") or values.get("resolved_transform_count"), default=max(packed_count, len(items), 1))))
    clearances = _gameplay_name_list(values, ("clearance_reservations", "clearance_targets", "clearance_zones"), default=[])
    clearance_reservations = max(1, min(128, _positive_int(values.get("clearance_reservation_count") or values.get("clearance_count"), default=max(len(clearances), collision_pairs, 1))))
    service_anchors = max(1, min(64, _positive_int(values.get("service_anchor_count") or values.get("service_count"), default=max(service_count, len(_gameplay_name_list(values, ("service_anchors",), default=[])), 1))))
    fixture_total = sum(1 for item in items if item in _FIXTURE_CONTENT_ITEMS)
    furniture_total = max(0, len(items) - fixture_total)
    counts = {
        f"{construct}_count": 1,
        "footprint_packing_count": 1,
        "footprint_packer_count": 0,
        "placement_footprint_count": 0,
        "occupancy_grid_count": 0,
        "fit_profile_count": 0,
        "collision_rule_count": 0,
        "service_reach_count": 0,
        "room_packing_solver_count": 0,
        "packing_slot_count": 0,
        "packed_transform_count": 0,
        "clearance_reservation_count": 0,
        "service_anchor_map_count": 0,
        "resolved_transform_count": 0,
        "blocked_transform_count": 0,
        "service_anchor_count": 0,
        "room_content_plan_count": 0,
        "content_family_binding_count": 0,
        "furniture_asset_count": 0,
        "fixture_asset_count": 0,
        "packed_child_asset_count": 0,
        "generated_child_asset_count": 0,
        "content_family_count": 0,
        "content_surface_plan_count": 0,
        "content_material_zone_count": 0,
        "content_finish_preset_count": 0,
        "content_wear_profile_count": 0,
        "content_marking_set_count": 0,
        "content_surface_zone_count": 0,
        "content_decal_count": 0,
        "footprint_count": footprint_count,
        "packed_item_count": packed_count,
        "occupied_cell_count": occupied_count,
        "free_cell_count": free_count,
        "collision_pair_count": collision_pairs,
        "layout_slot_count": max(1, min(256, free_count or packed_count or footprint_count)),
        "resolved_slot_count": packed_count,
        "blocked_slot_count": occupied_count,
        "layout_socket_count": max(1, min(256, free_count or packed_count or footprint_count)),
        "room_socket_count": 0,
        "fixture_socket_count": 0,
        "socket_binding_count": 0,
        "placement_constraint_count": 0,
        "clearance_zone_count": 0,
        "service_placement_count": 0,
    }
    if construct == "footprint_packer":
        counts.update({"footprint_packer_count": 1, "placement_footprint_count": footprint_count, "occupancy_grid_count": 1, "fit_profile_count": 1, "collision_rule_count": 1 if collision_pairs or not _disabled(values.get("collision_rule", True)) else 0, "service_reach_count": service_count, "room_packing_solver_count": 1, "packing_slot_count": packing_slots, "packed_transform_count": packed_transforms, "clearance_reservation_count": clearance_reservations, "service_anchor_map_count": 1 if service_count else 0, "resolved_transform_count": packed_transforms, "service_anchor_count": service_anchors if service_count else 0, "room_socket_count": packed_count, "fixture_socket_count": packed_count, "socket_binding_count": packed_count, "placement_constraint_count": max(1, collision_pairs), "clearance_zone_count": max(1, collision_pairs)})
    elif construct == "placement_footprint":
        counts.update({"placement_footprint_count": 1, "footprint_count": 1, "layout_slot_count": 1, "resolved_slot_count": 1, "room_socket_count": 1, "fixture_socket_count": 1, "socket_binding_count": 1, "clearance_zone_count": 1})
    elif construct == "occupancy_grid":
        counts.update({"occupancy_grid_count": 1, "layout_slot_count": max(1, min(256, free_count)), "resolved_slot_count": free_count, "blocked_slot_count": occupied_count})
    elif construct == "fit_profile":
        counts.update({"fit_profile_count": 1, "layout_slot_count": 1, "socket_priority_count": 1, "placement_constraint_count": 1})
    elif construct == "collision_rule":
        counts.update({"collision_rule_count": 1, "collision_pair_count": max(1, collision_pairs), "placement_constraint_count": max(1, collision_pairs), "clearance_zone_count": max(1, collision_pairs)})
    elif construct == "service_reach":
        counts.update({"service_reach_count": max(1, service_count), "service_placement_count": max(1, service_count), "socket_priority_count": max(1, service_count), "world_metric_count": 1})
    elif construct == "room_packing_solver":
        counts.update({"room_packing_solver_count": 1, "packing_slot_count": packing_slots, "packed_transform_count": packed_transforms, "clearance_reservation_count": clearance_reservations, "service_anchor_map_count": 1, "resolved_transform_count": packed_transforms, "service_anchor_count": service_anchors, "placement_footprint_count": footprint_count, "occupancy_grid_count": 1, "fit_profile_count": 1, "layout_slot_count": packing_slots, "socket_binding_count": packed_transforms})
    elif construct == "packing_slot":
        counts.update({"packing_slot_count": 1, "layout_slot_count": 1, "resolved_slot_count": 1, "room_socket_count": 1})
    elif construct == "packed_transform":
        counts.update({"packed_transform_count": 1, "resolved_transform_count": 1, "packing_slot_count": 1, "placement_footprint_count": 1, "socket_binding_count": 1})
    elif construct == "clearance_reservation":
        counts.update({"clearance_reservation_count": 1, "clearance_zone_count": 1, "placement_constraint_count": 1})
    elif construct == "service_anchor_map":
        counts.update({"service_anchor_map_count": 1, "service_anchor_count": service_anchors, "service_reach_count": service_anchors, "service_placement_count": service_anchors})
    elif construct == "room_content_plan":
        counts.update({"room_content_plan_count": 1, "content_family_binding_count": max(1, len(set(items))), "furniture_asset_count": furniture_total, "fixture_asset_count": fixture_total, "packed_child_asset_count": max(1, len(items)), "generated_child_asset_count": max(1, len(items)), "packed_transform_count": max(1, len(items)), "room_packing_solver_count": 1, "content_family_count": max(1, len(set(_content_family_for_item(item, values) for item in items or ['item'])))})
    elif construct == "content_family_binding":
        counts.update({"content_family_binding_count": 1, "content_family_count": 1})
    elif construct == "furniture_asset":
        counts.update({"furniture_asset_count": 1, "packed_child_asset_count": 1, "generated_child_asset_count": 1, "packed_transform_count": 1})
    elif construct == "fixture_asset":
        counts.update({"fixture_asset_count": 1, "packed_child_asset_count": 1, "generated_child_asset_count": 1, "packed_transform_count": 1, "service_anchor_map_count": 1, "service_anchor_count": service_anchors})
    elif construct == "packed_child_asset":
        counts.update({"packed_child_asset_count": 1, "generated_child_asset_count": 1, "packed_transform_count": 1})
    elif construct == "content_surface_plan":
        profile = _content_surface_profile(_content_asset_item(values, items[0] if items else "item"), values)
        counts.update({"content_surface_plan_count": 1, "content_material_zone_count": max(1, len(profile["zones"])), "content_finish_preset_count": 1, "content_wear_profile_count": 1, "content_marking_set_count": 1, "content_surface_zone_count": max(1, len(profile["zones"])), "content_decal_count": max(1, len(profile["markings"])), "surface_layer_count": max(1, len(profile["layers"])), "material_zone_count": max(1, len(profile["zones"])), "wear_pattern_count": max(1, len(profile["wear"])), "decal_count": max(1, len(profile["markings"]))})
    elif construct == "content_material_zone":
        counts.update({"content_material_zone_count": 1, "content_surface_zone_count": 1, "material_zone_count": 1})
    elif construct == "content_finish_preset":
        profile = _content_surface_profile(_content_asset_item(values, items[0] if items else "item"), values)
        counts.update({"content_finish_preset_count": 1, "surface_layer_count": max(1, len(profile["layers"])), "material_zone_count": max(1, len(profile["zones"]))})
    elif construct == "content_wear_profile":
        profile = _content_surface_profile(_content_asset_item(values, items[0] if items else "item"), values)
        counts.update({"content_wear_profile_count": 1, "wear_pattern_count": max(1, len(profile["wear"])), "damage_surface_count": _positive_int(values.get("damage_surface_count"), default=0)})
    elif construct == "content_marking_set":
        profile = _content_surface_profile(_content_asset_item(values, items[0] if items else "item"), values)
        counts.update({"content_marking_set_count": 1, "content_decal_count": max(1, len(profile["markings"])), "decal_count": max(1, len(profile["markings"]))})
    return counts


def _footprint_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    width, depth, height = _footprint_dimensions(values)
    rows, columns, cell_size = _footprint_grid(values)
    items = _footprint_items(values)
    occupied_cells, free_cells = _footprint_cell_lists(values)
    counts = _footprint_counts(values, construct)
    services = _auto_layout_service_types(values, _auto_layout_room_role(values))
    area = width * depth
    fit_score = _number(values.get("fit_score"), default=max(0.05, min(1.0, counts["packed_item_count"] / max(1, counts["footprint_count"]))))
    pack_positions = _footprint_pack_positions(values, _packing_vector3(values.get("position"), [0.0, 0.0, 0.0]), limit=min(64, max(1, counts.get("packed_transform_count", counts["packed_item_count"] or 1))))
    service_anchors = _gameplay_name_list(values, ("service_anchors", "required_services", "services", "service_types"), default=services)
    anchor_map = values.get("service_anchor_map") if isinstance(values.get("service_anchor_map"), Mapping) else {anchor: [slot["slot_id"] for slot in pack_positions if slot["service_anchor"] == anchor] for anchor in service_anchors}
    content_item = _content_asset_item(values, items[0] if items else "item")
    content_family = _content_family_for_item(content_item, values)
    content_controls = _content_asset_controls(content_item)
    content_surface = _content_surface_profile(content_item, values)
    state: dict[str, Any] = {
        construct: name,
        "footprint_construct": construct,
        "footprint_kind": kind,
        "action": _snake_id(values.get("action") or _FOOTPRINT_PACKING_ACTIONS.get(construct), "pack_footprints"),
        "object_archetype": construct,
        "setpiece_layout": "footprint_packing",
        "enabled": not _disabled(values.get("enabled", True)),
        "room_role": _auto_layout_room_role(values),
        "packed_items": items,
        "footprint_width": width,
        "footprint_depth": depth,
        "footprint_height": height,
        "footprint_area": round(area, 4),
        "footprint_shape": _surface_marker_value(values, "footprint_shape", "shape", fallback=kind if construct == "placement_footprint" else "rectangular"),
        "footprint_padding": _number(values.get("footprint_padding") or values.get("padding"), default=0.1),
        "footprint_rotation": _number(values.get("footprint_rotation") or values.get("rotation_degrees"), default=0.0),
        "grid_rows": rows,
        "grid_columns": columns,
        "cell_size": cell_size,
        "occupied_cells": occupied_cells,
        "free_cells": free_cells,
        "fit_score": fit_score,
        "fit_policy": _surface_marker_value(values, "fit_policy", fallback="best_fit"),
        "can_rotate": not _disabled(values.get("can_rotate", True)),
        "allow_overlap": not _disabled(values.get("allow_overlap", False)),
        "collision_policy": _surface_marker_value(values, "collision_policy", fallback="avoid_overlap"),
        "collision_pairs": _gameplay_name_list(values, ("collision_pairs",), default=[]),
        "service_radius": _number(values.get("service_radius") or values.get("max_service_distance"), default=2.5),
        "required_services": _gameplay_name_list(values, ("required_services", "services", "service_types"), default=services),
        "service_targets": _gameplay_name_list(values, ("service_targets", "service_taps"), default=[]),
        "max_service_distance": _number(values.get("max_service_distance") or values.get("service_radius"), default=2.5),
        "reach_score": _number(values.get("reach_score"), default=1.0 if services else 0.0),
        "packing_axis": _surface_marker_value(values, "packing_axis", "layout_axis", "axis", fallback="row"),
        "packing_origin": _packing_vector3(values.get("packing_origin") or values.get("origin"), [0.0, 0.0, 0.0]),
        "packing_spacing": max(0.12, min(8.0, _number(values.get("packing_spacing") or values.get("slot_spacing"), default=cell_size))),
        "packing_slots": _footprint_pack_slot_map(pack_positions),
        "slot_positions": {slot["slot_id"]: slot["position"] for slot in pack_positions},
        "packed_positions": {slot["slot_id"]: slot["position"] for slot in pack_positions},
        "packed_transforms": _footprint_pack_transform_map(pack_positions),
        "resolved_transforms": _footprint_pack_transform_map(pack_positions),
        "transform_policy": _surface_marker_value(values, "transform_policy", "packing_strategy", fallback="grid_fit"),
        "clearance_reservations": _gameplay_name_list(values, ("clearance_reservations", "clearance_targets", "clearance_zones"), default=[]),
        "service_anchor_map": anchor_map,
        "service_anchors": service_anchors,
        "parent_object": _surface_marker_value(values, "parent_object", "parent", fallback=_auto_layout_room_role(values)),
        "child_objects": _gameplay_name_list(values, ("child_objects", "packed_items", "items"), default=items),
        "packed_item": _surface_marker_value(values, "packed_item", "item_type", "fixture_type", "furniture_type", fallback=items[0] if items else "item"),
        "slot_id": _surface_marker_value(values, "slot_id", "target_socket", fallback=pack_positions[0]["slot_id"] if pack_positions else "slot_01"),
        "resolved_position": _packing_vector3(values.get("resolved_position") or values.get("position"), pack_positions[0]["position"] if pack_positions else [0.0, 0.0, 0.0]),
        "resolved_rotation": _packing_vector3(values.get("resolved_rotation") or values.get("rotation"), pack_positions[0]["rotation"] if pack_positions else [0.0, 0.0, 0.0]),
        "room_packing_result": {"slot_count": counts.get("packing_slot_count", 0), "packed_transform_count": counts.get("packed_transform_count", 0), "clearance_reservation_count": counts.get("clearance_reservation_count", 0), "service_anchor_count": counts.get("service_anchor_count", 0)},
        "room_content_plan": name if construct == "room_content_plan" else _surface_marker_value(values, "room_content_plan", fallback=""),
        "content_family_binding": name if construct == "content_family_binding" else _surface_marker_value(values, "content_family_binding", fallback=""),
        "content_family": content_family,
        "content_asset_type": content_item,
        "content_surface_plan": name if construct == "content_surface_plan" else _surface_marker_value(values, "content_surface_plan", fallback=""),
        "content_surface_profile": _surface_marker_value(values, "content_surface_profile", "surface_profile", fallback=content_item),
        "content_surface_zones": content_surface["zones"],
        "content_finish_layers": content_surface["layers"],
        "content_markings": content_surface["markings"],
        "content_wear": content_surface["wear"],
        "content_material_profile": _surface_marker_value(values, "content_material_profile", "material_profile", fallback=content_item),
        "generated_child_asset": name if construct in {"furniture_asset", "fixture_asset", "packed_child_asset"} else _surface_marker_value(values, "generated_child_asset", fallback=""),
        "generated_child_assets": _gameplay_name_list(values, ("generated_child_assets", "packed_items", "items"), default=items),
        "content_asset_controls": content_controls,
        **content_controls,
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
        **counts,
    }
    if construct in {"service_reach", "service_anchor_map"}:
        state.update({"lathe_asset": "procedural_infrastructure", "source_family": "procedural_infrastructure", "network_type": "service_reach"})
    elif construct in {"placement_footprint", "packed_transform", "furniture_asset", "fixture_asset", "packed_child_asset", "content_surface_plan", "content_material_zone", "content_finish_preset", "content_wear_profile", "content_marking_set"}:
        state.update({"lathe_asset": content_family, "source_family": content_family, "furniture_type": content_item, "fixture_type": content_item})
    else:
        state.update({"lathe_asset": "procedural_interior", "source_family": "procedural_interior", "interior_count": 1})
    return state


def _footprint_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    width, depth, height = _footprint_dimensions(values)
    rows, columns, cell_size = _footprint_grid(values)
    if construct == "occupancy_grid":
        return [max(0.2, min(4.0, columns * cell_size * 0.10)), max(0.2, min(4.0, rows * cell_size * 0.10)), 0.04]
    if construct == "service_reach":
        radius = _number(values.get("service_radius") or values.get("max_service_distance"), default=2.5)
        return [max(0.20, min(3.0, radius * 0.18)), max(0.20, min(3.0, radius * 0.18)), 0.08]
    if construct == "room_packing_solver":
        positions = _footprint_pack_positions(values, [0.0, 0.0, 0.0], limit=64)
        return [max(0.30, min(4.0, len(positions) * 0.12)), max(0.24, min(3.0, len(positions) * 0.08)), 0.10]
    if construct == "packing_slot":
        return [max(0.12, width * 0.12), max(0.12, depth * 0.12), 0.06]
    if construct == "packed_transform":
        return [max(0.10, width * 0.16), max(0.10, depth * 0.16), max(0.06, height * 0.08)]
    if construct == "clearance_reservation":
        radius = _number(values.get("required_clearance") or values.get("clearance_radius") or values.get("clearance"), default=0.45)
        return [max(0.12, radius * 0.5), max(0.12, radius * 0.5), 0.04]
    if construct == "service_anchor_map":
        anchor_count = max(1, len(_gameplay_name_list(values, ("service_anchors", "required_services", "services", "service_types"), default=[])))
        return [max(0.18, anchor_count * 0.12), max(0.18, anchor_count * 0.08), 0.08]
    if construct == "collision_rule":
        return [max(0.18, width * 0.16), max(0.18, depth * 0.16), 0.06]
    if construct == "fit_profile":
        return [max(0.18, width * 0.14), max(0.18, depth * 0.14), 0.08]
    if construct == "placement_footprint":
        return [max(0.10, width * 0.18), max(0.10, depth * 0.18), max(0.06, height * 0.08)]
    return [max(0.3, min(4.0, width * 0.22)), max(0.3, min(4.0, depth * 0.22)), max(0.08, min(0.6, height * 0.08))]


def _footprint_affordance(values: Mapping[str, Any], construct: str, name: str) -> dict[str, Any]:
    width, depth, height = _footprint_dimensions(values)
    slots = _footprint_pack_positions(values, [0.0, 0.0, 0.0], limit=16)
    return {
        "action": _snake_id(values.get("action") or _FOOTPRINT_PACKING_ACTIONS.get(construct), "pack_footprints"),
        "footprint": [width, depth, height],
        "packed_items": _footprint_items(values),
        "packed_transform_slots": [slot["slot_id"] for slot in slots],
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
    }


def _footprint_child_core_name(name: str, construct: str) -> str:
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _footprint_packing_core_name(name, construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _layout_resolution_core_name(name, construct)
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _auto_layout_core_name(name, construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _placement_constraint_core_name(name, construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct in _SIMULATION_CORE_SUFFIXES:
        return _simulation_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_footprint_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _SURFACE_AUTHORING_MACROS:
        return _expand_surface_authoring_macro(node, construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _expand_footprint_packing_macro(node, construct=construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _expand_layout_resolution_macro(node, construct=construct)
    if construct in _AUTO_LAYOUT_CORE_SUFFIXES:
        return _expand_auto_layout_macro(node, construct=construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _expand_placement_constraint_macro(node, construct=construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in {"world_metric", "resource_flow"}:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_layout_resolution_child_macro(node, construct)


def _expand_footprint_packing_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _footprint_packing_kind(values, construct)
    depth_level = max(0, int(_number(values.get("_footprint_packing_depth"), default=0.0)))
    core_name = _footprint_packing_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_footprint_scale(values, construct),
        state=_footprint_state(values, construct, name, kind),
        tags=[construct, kind, "footprint_packing", "macro_generated"],
    )
    if construct in {"content_surface_plan", "content_material_zone", "content_finish_preset", "content_wear_profile", "content_marking_set", "furniture_asset", "fixture_asset", "packed_child_asset"}:
        item = _content_asset_item(values, _footprint_items(values)[0] if _footprint_items(values) else "item")
        surface_overrides = dict(core_values.get("surface_overrides") if isinstance(core_values.get("surface_overrides"), Mapping) else {})
        _merge_surface_overrides(surface_overrides, _content_surface_authoring(item, values))
        core_values["surface_overrides"] = surface_overrides
    core_values["affordances"] = {_snake_id(_FOOTPRINT_PACKING_ACTIONS.get(construct), "pack_footprints"): _footprint_affordance(values, construct, name)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_FOOTPRINT_PACKING_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth_level >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "arranges", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        if child_construct == "room_packing_solver":
            child_values["_footprint_packing_depth"] = max(1, int(_number(child_values.get("_footprint_packing_depth"), default=0.0)))
        elif child_construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
            child_values["_footprint_packing_depth"] = max(depth_level + 1, int(_number(child_values.get("_footprint_packing_depth"), default=0.0)))
        if child_construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
            child_values["_layout_resolution_depth"] = max(1, int(_number(child_values.get("_layout_resolution_depth"), default=0.0)))
        if child_construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
            child_values["_placement_constraint_depth"] = max(1, int(_number(child_values.get("_placement_constraint_depth"), default=0.0)))
        if child_construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
            child_values["_interior_composition_depth"] = max(1, int(_number(child_values.get("_interior_composition_depth"), default=0.0)))
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(1, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _FOOTPRINT_PACKING_ROLES.get(child_construct, _LAYOUT_RESOLUTION_ROLES.get(child_construct, _PLACEMENT_CONSTRAINT_ROLES.get(child_construct, _INTERIOR_COMPOSITION_ROLES.get(child_construct, _INFRA_NETWORK_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure"))))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_footprint_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _footprint_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} packs {child_construct} {suffix}."))

    items = _footprint_items(values)
    counts = _footprint_counts(values, construct)
    rows, columns, cell_size = _footprint_grid(values)
    services = _auto_layout_service_types(values, _auto_layout_room_role(values))
    width, depth_size, height = _footprint_dimensions(values)
    if construct == "footprint_packer":
        add_child("occupancy_grid", "occupancy", {"grid_rows": rows, "grid_columns": columns, "cell_size": cell_size, "packed_items": items}, [center[0] - 0.28, center[1] + 0.24, center[2] + 0.04], relation="maps", description=f"Footprint packer {name} maps usable occupancy cells.")
        add_child("layout_solver", "slots", {"layout_slots": counts["layout_slot_count"], "room_width": values.get("room_width") or values.get("width") or 4.0, "room_depth": values.get("room_depth") or values.get("depth") or 3.2, "blocked_slots": values.get("blocked_slots") or values.get("occupied_cells") or []}, [center[0] + 0.28, center[1] + 0.24, center[2] + 0.04], relation="feeds", description=f"Footprint packer {name} feeds resolved slots.")
        for index, item in enumerate(items[:16] or ["fixture"]):
            item_width, item_depth, item_height = _footprint_dimensions(values, item)
            offset = (index - (min(len(items) or 1, 16) - 1) / 2.0) * 0.16
            add_child("placement_footprint", f"{item}_{index + 1:02d}", {"fixture_type": item, "furniture_type": item, "footprint_width": item_width, "footprint_depth": item_depth, "footprint_height": item_height, "slot_index": index + 1, "target_socket": f"{name}_slot_{index + 1:02d}", "_footprint_packing_depth": 2}, [center[0] + offset, center[1] - 0.06, center[2] + 0.06], relation="packs", description=f"Footprint packer {name} packs {item} footprint.")
        add_child("room_packing_solver", "transform_solver", {"packed_items": items, "required_services": values.get("required_services") or values.get("services") or services, "clearance_reservations": values.get("clearance_reservations") or values.get("clearance_targets") or [], "packed_transform_count": counts["packed_transform_count"], "packing_slot_count": counts["packing_slot_count"], "packing_strategy": kind, "packing_axis": values.get("packing_axis") or values.get("layout_axis") or "grid"}, [center[0], center[1] + 0.02, center[2] + 0.10], relation="resolves", description=f"Footprint packer {name} resolves packed item transforms.")
        add_child("fit_profile", "fit", {"fit_score": values.get("fit_score") or (counts["packed_item_count"] / max(1, counts["footprint_count"])), "footprint_count": counts["footprint_count"], "packed_item_count": counts["packed_item_count"]}, [center[0] - 0.22, center[1] - 0.28, center[2] + 0.04], relation="scores", description=f"Footprint packer {name} scores slot fit.")
        add_child("collision_rule", "collisions", {"collision_pair_count": counts["collision_pair_count"], "collision_policy": values.get("collision_policy") or "avoid_overlap"}, [center[0], center[1] - 0.30, center[2] + 0.04], relation="blocks", description=f"Footprint packer {name} blocks overlapping footprints.")
        if services:
            add_child("service_reach", "services", {"required_services": services, "service_types": services, "service_radius": values.get("service_radius") or 2.5}, [center[0] + 0.22, center[1] - 0.28, center[2] + 0.04], relation="reaches", description=f"Footprint packer {name} links packed items to services.")

    elif construct == "room_packing_solver":
        slots = _footprint_pack_positions(values, center, limit=min(32, counts["packed_transform_count"]))
        clearance_targets = _gameplay_name_list(values, ("clearance_reservations", "clearance_targets", "clearance_zones"), default=["walk_path"])
        service_targets = _gameplay_name_list(values, ("service_anchors", "required_services", "services", "service_types"), default=services)
        add_child("occupancy_grid", "resolved_grid", {"grid_rows": rows, "grid_columns": columns, "cell_size": cell_size, "packing_slot_count": len(slots), "_footprint_packing_depth": 2}, [center[0] - 0.24, center[1] + 0.24, center[2] + 0.04], relation="maps", description=f"Room packing solver {name} maps resolved slots.")
        for index, slot in enumerate(slots):
            slot_position = slot["position"]
            item = slot["item"]
            add_child("packing_slot", f"{slot['slot_id']}_{item}", {"slot_id": slot["slot_id"], "packed_item": item, "target_socket": f"{name}_{slot['slot_id']}", "resolved_position": slot_position, "resolved_rotation": slot["rotation"], "service_anchor": slot["service_anchor"], "slot_index": index + 1}, slot_position, relation="allocates", description=f"Room packing solver {name} allocates {slot['slot_id']} for {item}.")
            add_child("packed_transform", f"{item}_{index + 1:02d}", {"slot_id": slot["slot_id"], "packed_item": item, "fixture_type": item, "furniture_type": item, "target_socket": f"{name}_{slot['slot_id']}", "resolved_position": slot_position, "resolved_rotation": slot["rotation"], "parent_object": values.get("parent_object") or name, "service_anchor": slot["service_anchor"]}, [slot_position[0], slot_position[1], slot_position[2] + 0.08], relation="places", description=f"Room packing solver {name} places {item} transform.")
        for index, clearance in enumerate(clearance_targets[:12]):
            offset = (index - (min(len(clearance_targets), 12) - 1) / 2.0) * 0.16
            add_child("clearance_reservation", f"{clearance}_{index + 1:02d}", {"clearance_targets": [clearance], "clearance_radius": values.get("required_clearance") or values.get("clearance_radius") or 0.45}, [center[0] + offset, center[1] - 0.26, center[2] + 0.04], relation="reserves", description=f"Room packing solver {name} reserves {clearance}.")
        if service_targets:
            add_child("service_anchor_map", "service_anchors", {"service_anchors": service_targets, "required_services": service_targets, "packed_transforms": [slot["slot_id"] for slot in slots]}, [center[0] + 0.24, center[1] + 0.24, center[2] + 0.04], relation="feeds", description=f"Room packing solver {name} maps service anchors.")
        add_child("world_metric", "resolved_transform_count", {"metric": "resolved_transform_count", "metric_value": len(slots)}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="counts", description=f"Room packing solver {name} exposes resolved transform count.")

    elif construct == "room_content_plan":
        slots = _footprint_pack_positions(values, center, limit=min(32, max(1, len(items))))
        add_child("room_packing_solver", "packing", {"packed_items": items, "required_services": values.get("required_services") or values.get("services") or services, "clearance_reservations": values.get("clearance_reservations") or values.get("clearance_targets") or [], "packed_transform_count": len(slots), "packing_slot_count": len(slots), "_footprint_packing_depth": 1}, [center[0], center[1] + 0.26, center[2] + 0.06], relation="resolves", description=f"Room content plan {name} resolves content transforms.")
        for item in _dedupe(items)[:16]:
            add_child("content_family_binding", f"{item}_family", {"packed_item": item, "content_family": _content_family_for_item(item, values), **_content_asset_controls(item)}, [center[0] - 0.28, center[1], center[2] + 0.04], relation="binds", description=f"Room content plan {name} binds {item} to a generated family.")
        for index, slot in enumerate(slots):
            item = slot["item"]
            child_construct = "fixture_asset" if item in _FIXTURE_CONTENT_ITEMS else "furniture_asset"
            add_child(child_construct, f"{item}_{index + 1:02d}", {"packed_item": item, "fixture_type": item, "furniture_type": item, "slot_id": slot["slot_id"], "resolved_position": slot["position"], "resolved_rotation": slot["rotation"], "parent_object": values.get("parent_object") or name, "target_socket": f"{name}_{slot['slot_id']}", **_content_asset_controls(item)}, [slot["position"][0], slot["position"][1], slot["position"][2] + 0.10], relation="generates", description=f"Room content plan {name} generates {item} child asset.")

    elif construct == "content_family_binding":
        item = _content_asset_item(values)
        family = _content_family_for_item(item, values)
        add_child("world_metric", "family_binding", {"metric": "content_family_binding", "metric_value": family}, [center[0] - 0.12, center[1] + 0.12, center[2] + 0.04], relation="records", description=f"Content family binding {name} records {item} family {family}.")
        add_child("packed_child_asset", f"{item}_child", {"packed_item": item, "content_family": family, **_content_asset_controls(item)}, [center[0] + 0.12, center[1] + 0.12, center[2] + 0.04], relation="prepares", description=f"Content family binding {name} prepares generated {item} child asset.")

    elif construct in {"furniture_asset", "fixture_asset", "packed_child_asset"}:
        item = _content_asset_item(values)
        slot_id = _surface_marker_value(values, "slot_id", "target_socket", fallback=f"{name}_slot")
        resolved_position = _packing_vector3(values.get("resolved_position") or values.get("position"), center)
        controls_for_item = _content_asset_controls(item)
        add_child("packed_transform", "transform", {"packed_item": item, "fixture_type": item, "furniture_type": item, "slot_id": slot_id, "target_socket": slot_id, "resolved_position": resolved_position, "resolved_rotation": values.get("resolved_rotation") or values.get("rotation") or [0.0, 0.0, 0.0], **controls_for_item}, [resolved_position[0], resolved_position[1], resolved_position[2] + 0.06], relation="places", description=f"{construct} {name} places generated {item} asset.")
        add_child("content_surface_plan", "surface", {"packed_item": item, "fixture_type": item, "furniture_type": item, "target_socket": slot_id, **controls_for_item}, [resolved_position[0], resolved_position[1] + 0.14, resolved_position[2] + 0.08], relation="finishes", description=f"{construct} {name} applies surface zones to {item}.")
        if construct == "fixture_asset" or item in _FIXTURE_CONTENT_ITEMS:
            add_child("service_anchor_map", "service_anchors", {"packed_item": item, "fixture_type": item, "service_anchors": values.get("service_anchors") or values.get("required_services") or ["power"], "_footprint_packing_depth": 2}, [resolved_position[0] + 0.12, resolved_position[1], resolved_position[2] + 0.08], relation="feeds", description=f"{construct} {name} maps service anchors for {item}.")

    elif construct == "content_surface_plan":
        item = _content_asset_item(values, items[0] if items else "item")
        profile = _content_surface_profile(item, values)
        for index, (zone, material) in enumerate(list(profile["zones"].items())[:16]):
            offset = (index - (min(len(profile["zones"]), 16) - 1) / 2.0) * 0.16
            add_child("content_material_zone", f"{zone}_{material}", {"packed_item": item, "zone": zone, "material": material, "target_socket": values.get("target_socket") or values.get("slot_id") or f"{name}_{zone}"}, [center[0] + offset, center[1] + 0.18, center[2] + 0.04], relation="zones", description=f"Content surface plan {name} assigns {material} to {zone}.")
        add_child("content_finish_preset", "finish", {"packed_item": item, "content_finish_layers": profile["layers"], "content_surface_zones": profile["zones"]}, [center[0] - 0.18, center[1] - 0.18, center[2] + 0.04], relation="layers", description=f"Content surface plan {name} applies finish layers for {item}.")
        add_child("content_wear_profile", "wear", {"packed_item": item, "content_wear": profile["wear"], "content_markings": profile["markings"]}, [center[0], center[1] - 0.22, center[2] + 0.04], relation="weathers", description=f"Content surface plan {name} applies wear profile for {item}.")
        add_child("content_marking_set", "markings", {"packed_item": item, "content_markings": profile["markings"], "content_wear": profile["wear"]}, [center[0] + 0.18, center[1] - 0.18, center[2] + 0.04], relation="marks", description=f"Content surface plan {name} applies markings for {item}.")

    elif construct == "content_material_zone":
        item = _content_asset_item(values, items[0] if items else "item")
        zone = _surface_marker_value(values, "zone", "part", "slot", fallback=f"{item}_surface")
        material = _surface_marker_value(values, "material", "to_material", fallback=_content_surface_profile(item, values)["zones"].get(zone, "painted_surface"))
        add_child("material_zone", "zone", {"zone": zone, "material": material, "targets": [item], "material_zone_count": 1}, [center[0], center[1] + 0.14, center[2] + 0.04], relation="assigns", description=f"Content material zone {name} assigns {material} to {zone}.")

    elif construct == "content_finish_preset":
        item = _content_asset_item(values, items[0] if items else "item")
        profile = _content_surface_profile(item, values)
        add_child("surface_layer", "layers", {"packed_item": item, "layers": profile["layers"], "material_layers": profile["layers"], "material_zone_count": max(1, len(profile["zones"]))}, [center[0], center[1] + 0.16, center[2] + 0.04], relation="layers", description=f"Content finish preset {name} stacks finish layers for {item}.")

    elif construct == "content_wear_profile":
        item = _content_asset_item(values, items[0] if items else "item")
        profile = _content_surface_profile(item, values)
        add_child("wear_pattern", "wear", {"packed_item": item, "wear": profile["wear"], "patterns": profile["wear"], "story_decals": profile["markings"], "wear_pattern_count": max(1, len(profile["wear"]))}, [center[0], center[1] + 0.16, center[2] + 0.04], relation="weathers", description=f"Content wear profile {name} creates wear for {item}.")

    elif construct == "content_marking_set":
        item = _content_asset_item(values, items[0] if items else "item")
        profile = _content_surface_profile(item, values)
        add_child("decal", "markings", {"packed_item": item, "decals": profile["markings"], "story_decals": profile["markings"], "markings": profile["markings"], "decal_count": max(1, len(profile["markings"]))}, [center[0], center[1] + 0.16, center[2] + 0.04], relation="marks", description=f"Content marking set {name} places decals for {item}.")

    elif construct == "placement_footprint":
        slot_id = _surface_marker_value(values, "target_socket", "slot_id", fallback=f"{name}_slot")
        add_child("layout_slot", "fit_slot", {"target_socket": slot_id, "slot_kind": values.get("slot_kind") or "footprint_slot", "footprint_width": width, "footprint_depth": depth_size, "footprint_height": height, "slot_capacity": 1}, [center[0] - 0.16, center[1] + 0.16, center[2] + 0.04], relation="occupies", description=f"Placement footprint {name} occupies layout slot {slot_id}.")
        add_child("clearance_zone", "footprint_clearance", {"clearance_radius": values.get("footprint_padding") or values.get("clearance") or 0.15, "clearance_targets": [slot_id], "_layout_resolution_depth": 2}, [center[0] + 0.16, center[1] + 0.16, center[2] + 0.04], relation="reserves", description=f"Placement footprint {name} reserves padding around {slot_id}.")
        add_child("world_metric", "footprint_area", {"metric": "footprint_area", "metric_value": round(width * depth_size, 4)}, [center[0], center[1] - 0.16, center[2] + 0.04], relation="measures", description=f"Placement footprint {name} exposes occupied area.")

    elif construct == "packing_slot":
        slot_id = _surface_marker_value(values, "slot_id", "target_socket", fallback=f"{name}_slot")
        resolved_position = _packing_vector3(values.get("resolved_position") or values.get("position"), center)
        packed_item = _surface_marker_value(values, "packed_item", "fixture_type", "furniture_type", fallback="item")
        add_child("layout_slot", "layout_slot", {"target_socket": slot_id, "slot_kind": values.get("slot_kind") or "packing_slot", "slot_index": values.get("slot_index") or 1, "resolved_position": resolved_position, "_layout_resolution_depth": 2}, [resolved_position[0], resolved_position[1], resolved_position[2] + 0.04], relation="prepares", description=f"Packing slot {name} prepares transform slot {slot_id}.")
        add_child("room_socket", "slot_socket", {"socket_target": slot_id, "socket_role": "packing_slot", "socket_priority": values.get("socket_priority") or 1.0}, [resolved_position[0], resolved_position[1], resolved_position[2] + 0.08], relation="anchors", description=f"Packing slot {name} exposes socket for {packed_item}.")

    elif construct == "packed_transform":
        slot_id = _surface_marker_value(values, "slot_id", "target_socket", fallback=f"{name}_slot")
        packed_item = _surface_marker_value(values, "packed_item", "fixture_type", "furniture_type", fallback="item")
        resolved_position = _packing_vector3(values.get("resolved_position") or values.get("position"), center)
        resolved_rotation = _packing_vector3(values.get("resolved_rotation") or values.get("rotation"), [0.0, 0.0, 0.0])
        item_width, item_depth, item_height = _footprint_dimensions(values, packed_item)
        add_child("placement_footprint", "footprint", {"fixture_type": packed_item, "furniture_type": packed_item, "footprint_width": item_width, "footprint_depth": item_depth, "footprint_height": item_height, "target_socket": slot_id, "resolved_position": resolved_position, "_footprint_packing_depth": 2}, [resolved_position[0], resolved_position[1], resolved_position[2] + 0.04], relation="occupies", description=f"Packed transform {name} assigns footprint to {slot_id}.")
        add_child("socket_binding", "binding", {"target_socket": slot_id, "placed_object": packed_item, "fixture_type": packed_item, "resolved_position": resolved_position, "resolved_rotation": resolved_rotation, "_placement_constraint_depth": 2}, [resolved_position[0], resolved_position[1], resolved_position[2] + 0.10], relation="binds", description=f"Packed transform {name} binds {packed_item} to slot {slot_id}.")

    elif construct == "occupancy_grid":
        free_total = max(1, min(24, counts["layout_slot_count"]))
        for index in range(free_total):
            row = index // max(1, columns)
            column = index % max(1, columns)
            offset_x = (column - (min(columns, free_total) - 1) / 2.0) * 0.12
            offset_y = (row - (max(1, math.ceil(free_total / max(1, columns))) - 1) / 2.0) * 0.12
            add_child("layout_slot", f"cell_{row + 1:02d}_{column + 1:02d}", {"slot_index": index + 1, "slot_kind": "grid_cell", "target_socket": f"{name}_cell_{row + 1:02d}_{column + 1:02d}", "cell_size": cell_size}, [center[0] + offset_x, center[1] + offset_y, center[2] + 0.04], relation="prepares", description=f"Occupancy grid {name} exposes free cell {row + 1},{column + 1}.")
        if counts["occupied_cell_count"]:
            add_child("clearance_zone", "occupied_cells", {"clearance_zone_count": min(8, counts["occupied_cell_count"]), "clearance_targets": values.get("occupied_cells") or ["occupied_cell"], "_layout_resolution_depth": 2}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="blocks", description=f"Occupancy grid {name} blocks occupied cells.")

    elif construct == "fit_profile":
        add_child("socket_priority", "fit_priority", {"socket_priority": values.get("fit_score") or 1.0, "priority_rules": values.get("priority_rules") or ["fits_footprint", "nearest_service"]}, [center[0] - 0.14, center[1] + 0.16, center[2] + 0.04], relation="ranks", description=f"Fit profile {name} ranks fitting sockets.")
        add_child("placement_constraint", "fit_constraint", {"constraint_type": "fit_profile", "placement_rule": values.get("fit_policy") or "must_fit", "clearance": values.get("footprint_padding") or 0.1}, [center[0] + 0.14, center[1] + 0.16, center[2] + 0.04], relation="requires", description=f"Fit profile {name} constrains slot selection.")
        add_child("world_metric", "fit_score", {"metric": "fit_score", "metric_value": values.get("fit_score") or 1.0}, [center[0], center[1] - 0.16, center[2] + 0.04], relation="scores", description=f"Fit profile {name} exposes fit score.")

    elif construct == "collision_rule":
        collision_total = max(1, min(16, counts["collision_pair_count"]))
        for index in range(collision_total):
            offset = (index - (collision_total - 1) / 2.0) * 0.16
            add_child("placement_constraint", f"collision_{index + 1:02d}", {"constraint_type": "collision", "placement_rule": values.get("collision_policy") or "avoid_overlap", "target_socket": f"{name}_collision_{index + 1:02d}"}, [center[0] + offset, center[1] + 0.16, center[2] + 0.04], relation="blocks", description=f"Collision rule {name} blocks collision pair {index + 1}.")
        add_child("clearance_zone", "collision_keepout", {"clearance_zone_count": collision_total, "clearance_targets": values.get("collision_pairs") or ["footprint_pair"], "_layout_resolution_depth": 2}, [center[0], center[1] - 0.16, center[2] + 0.04], relation="reserves", description=f"Collision rule {name} reserves keepout around collisions.")

    elif construct == "service_reach":
        required = _gameplay_name_list(values, ("required_services", "services", "service_types"), default=services)
        for index, service in enumerate(required[:8] or ["power"]):
            offset = (index - (min(len(required) or 1, 8) - 1) / 2.0) * 0.16
            add_child("service_placement", f"{service}_reach", {"service_type": service, "services": [service], "target_socket": values.get("target_socket") or f"{name}_{service}_socket", "placement_count": 1}, [center[0] + offset, center[1] + 0.16, center[2] + 0.04], relation="feeds", description=f"Service reach {name} places reachable {service} tap.")
            add_child("socket_priority", f"{service}_priority", {"socket_priority": values.get("reach_score") or 1.0, "priority_rules": ["within_service_radius", service]}, [center[0] + offset, center[1] - 0.10, center[2] + 0.04], relation="ranks", description=f"Service reach {name} ranks sockets near {service}.")
        add_child("world_metric", "reach_score", {"metric": "reach_score", "metric_value": values.get("reach_score") or 1.0}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="measures", description=f"Service reach {name} exposes service reach score.")

    elif construct == "clearance_reservation":
        targets = _gameplay_name_list(values, ("clearance_targets", "clearance_reservations"), default=["packed_transform"])
        for index, target in enumerate(targets[:8]):
            offset = (index - (min(len(targets), 8) - 1) / 2.0) * 0.14
            add_child("clearance_zone", f"{target}_{index + 1:02d}", {"clearance_targets": [target], "clearance_radius": values.get("required_clearance") or values.get("clearance_radius") or 0.45, "_layout_resolution_depth": 2}, [center[0] + offset, center[1] + 0.16, center[2] + 0.04], relation="reserves", description=f"Clearance reservation {name} reserves {target}.")
        add_child("placement_constraint", "clearance_rule", {"constraint_type": "clearance_reservation", "placement_rule": values.get("clearance_policy") or "avoid_reserved_space", "clearance": values.get("required_clearance") or values.get("clearance_radius") or 0.45, "_placement_constraint_depth": 2}, [center[0], center[1] - 0.16, center[2] + 0.04], relation="blocks", description=f"Clearance reservation {name} blocks occupied clearance.")

    elif construct == "service_anchor_map":
        anchors = _gameplay_name_list(values, ("service_anchors", "required_services", "services", "service_types"), default=services) or ["power"]
        for index, anchor in enumerate(anchors[:12]):
            offset = (index - (min(len(anchors), 12) - 1) / 2.0) * 0.16
            add_child("service_reach", f"{anchor}_reach", {"required_services": [anchor], "service_types": [anchor], "service_radius": values.get("service_radius") or 2.5, "_footprint_packing_depth": 2}, [center[0] + offset, center[1] + 0.18, center[2] + 0.04], relation="feeds", description=f"Service anchor map {name} exposes {anchor} reach.")
            add_child("service_placement", f"{anchor}_anchor", {"service_type": anchor, "services": [anchor], "target_socket": f"{name}_{anchor}_anchor", "placement_count": 1, "_placement_constraint_depth": 2}, [center[0] + offset, center[1] - 0.12, center[2] + 0.04], relation="anchors", description=f"Service anchor map {name} places {anchor} anchor.")
        add_child("world_metric", "service_anchor_count", {"metric": "service_anchor_count", "metric_value": len(anchors)}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="counts", description=f"Service anchor map {name} counts service anchors.")

    return objects, relationships


