def _role_pack_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _ROLE_PACK_PRESET_KIND_DEFAULTS.get(construct, construct)
    for key in _ROLE_PACK_PRESET_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _role_pack_core_name(name: str, construct: str) -> str:
    return f"{name}_{_ROLE_PACK_PRESET_CORE_SUFFIXES.get(construct, 'role_pack_preset_core')}"


def _role_pack_room_role(values: Mapping[str, Any]) -> str:
    role = _surface_marker_value(values, "preset_role", "room_role", "role", fallback="")
    if role:
        return role
    return _auto_layout_room_role(values)


def _role_pack_preset(values: Mapping[str, Any]) -> dict[str, Any]:
    role = _role_pack_room_role(values)
    aliases = {
        "lab": "lab_room",
        "medical": "med_bay",
        "workshop": "workshop_room",
        "control": "control_room",
        "storage": "storage_room",
        "office": "office_room",
    }
    key = aliases.get(role, role)
    preset = dict(_ROOM_PACK_PRESETS.get(key, _ROOM_PACK_PRESETS["office_room"]))
    preset["role"] = key
    return preset


def _role_pack_items(values: Mapping[str, Any]) -> list[str]:
    preset = _role_pack_preset(values)
    items = _gameplay_name_list(values, ("preset_items", "packed_items", "items", "fixture_types", "furniture_types"), default=preset["items"])
    return _dedupe([_snake_id(item, "item") for item in items])[:32]


def _role_pack_services(values: Mapping[str, Any]) -> list[str]:
    preset = _role_pack_preset(values)
    services = _gameplay_name_list(values, ("role_services", "required_services", "services", "service_types"), default=preset["services"])
    return _dedupe([_snake_id(service, "service") for service in services])[:16]


def _role_pack_clearances(values: Mapping[str, Any]) -> list[str]:
    preset = _role_pack_preset(values)
    clearances = _gameplay_name_list(values, ("role_clearances", "clearance_targets", "clearance_zones"), default=preset["clearance"])
    return _dedupe([_snake_id(clearance, "clearance") for clearance in clearances])[:16]


def _role_pack_item_dimensions(values: Mapping[str, Any], item: str) -> tuple[float, float, float]:
    footprints = values.get("item_footprints") or values.get("default_footprints") or values.get("role_footprints")
    if isinstance(footprints, Mapping):
        raw = footprints.get(item)
        if isinstance(raw, Mapping):
            return _footprint_dimensions({"footprint_width": raw.get("width"), "footprint_depth": raw.get("depth"), "footprint_height": raw.get("height")}, item)
        if isinstance(raw, Sequence) and not isinstance(raw, str | bytes | bytearray):
            dims = list(raw)
            if len(dims) >= 3:
                return _footprint_dimensions({"footprint_width": dims[0], "footprint_depth": dims[1], "footprint_height": dims[2]}, item)
    return _footprint_dimensions(values, item)


def _role_pack_counts(values: Mapping[str, Any], construct: str) -> dict[str, int]:
    items = _role_pack_items(values)
    services = _role_pack_services(values)
    clearances = _role_pack_clearances(values)
    preset = _role_pack_preset(values)
    footprint_count = max(1, min(128, _positive_int(values.get("footprint_count") or values.get("preset_item_count"), default=len(items))))
    policy_count = max(1, min(32, _positive_int(values.get("policy_rule_count"), default=max(1, len(clearances)))))
    service_count = max(1, min(32, _positive_int(values.get("service_reach_count") or values.get("service_count"), default=max(1, len(services)))))
    counts = {
        f"{construct}_count": 1,
        "role_preset_count": 1,
        "room_pack_preset_count": 0,
        "footprint_size_preset_count": 0,
        "packing_policy_preset_count": 0,
        "clearance_preset_count": 0,
        "service_reach_preset_count": 0,
        "role_item_set_count": 0,
        "preset_item_count": len(items),
        "policy_rule_count": policy_count,
        "footprint_count": footprint_count,
        "placement_footprint_count": 0,
        "footprint_packer_count": 0,
        "occupancy_grid_count": 0,
        "fit_profile_count": 0,
        "collision_rule_count": 0,
        "clearance_zone_count": 0,
        "service_reach_count": 0,
        "room_packing_solver_count": 0,
        "packing_slot_count": 0,
        "packed_transform_count": 0,
        "clearance_reservation_count": 0,
        "service_anchor_map_count": 0,
        "resolved_transform_count": 0,
        "service_anchor_count": 0,
        "room_content_plan_count": 0,
        "furniture_asset_count": 0,
        "fixture_asset_count": 0,
        "packed_child_asset_count": 0,
        "generated_child_asset_count": 0,
        "content_surface_plan_count": 0,
        "content_material_zone_count": 0,
        "content_finish_preset_count": 0,
        "content_wear_profile_count": 0,
        "content_marking_set_count": 0,
        "content_surface_zone_count": 0,
        "content_decal_count": 0,
        "packed_item_count": max(1, min(128, _positive_int(values.get("packed_item_count"), default=len(items)))),
        "layout_slot_count": max(1, min(256, _positive_int(values.get("layout_slot_count") or values.get("layout_slots"), default=max(4, len(items) * 2)))),
    }
    if construct == "room_pack_preset":
        surface_zone_total = sum(len(_content_surface_profile(item, values)["zones"]) for item in items)
        marking_total = sum(len(_content_surface_profile(item, values)["markings"]) for item in items)
        counts.update({"room_pack_preset_count": 1, "footprint_size_preset_count": 1, "packing_policy_preset_count": 1, "clearance_preset_count": 1, "service_reach_preset_count": 1, "role_item_set_count": 1, "placement_footprint_count": footprint_count, "footprint_packer_count": 1, "occupancy_grid_count": 1, "fit_profile_count": 1, "collision_rule_count": 1, "clearance_zone_count": max(1, len(clearances)), "service_reach_count": service_count, "room_packing_solver_count": 1, "packing_slot_count": max(1, len(items)), "packed_transform_count": max(1, len(items)), "clearance_reservation_count": max(1, len(clearances)), "service_anchor_map_count": 1, "resolved_transform_count": max(1, len(items)), "service_anchor_count": service_count, "room_content_plan_count": 1, "furniture_asset_count": max(0, len([item for item in items if item not in _FIXTURE_CONTENT_ITEMS])), "fixture_asset_count": len([item for item in items if item in _FIXTURE_CONTENT_ITEMS]), "packed_child_asset_count": max(1, len(items)), "generated_child_asset_count": max(1, len(items)), "content_surface_plan_count": max(1, len(items)), "content_material_zone_count": max(1, surface_zone_total), "content_finish_preset_count": max(1, len(items)), "content_wear_profile_count": max(1, len(items)), "content_marking_set_count": max(1, len(items)), "content_surface_zone_count": max(1, surface_zone_total), "content_decal_count": max(1, marking_total)})
    elif construct == "footprint_size_preset":
        counts.update({"footprint_size_preset_count": 1, "placement_footprint_count": footprint_count, "footprint_count": footprint_count})
    elif construct == "packing_policy_preset":
        counts.update({"packing_policy_preset_count": 1, "occupancy_grid_count": 1, "fit_profile_count": 1, "collision_rule_count": 1, "footprint_packer_count": 1})
    elif construct == "clearance_preset":
        counts.update({"clearance_preset_count": 1, "clearance_zone_count": max(1, len(clearances)), "placement_constraint_count": max(1, len(clearances)), "collision_rule_count": 1})
    elif construct == "service_reach_preset":
        counts.update({"service_reach_preset_count": 1, "service_reach_count": service_count, "service_placement_count": service_count})
    elif construct == "role_item_set":
        counts.update({"role_item_set_count": 1, "placement_footprint_count": footprint_count, "room_packing_solver_count": 1, "packed_transform_count": max(1, len(items)), "packing_slot_count": max(1, len(items)), "resolved_transform_count": max(1, len(items))})
    counts["packing_density"] = _number(values.get("packing_density") or values.get("layout_density"), default=float(preset.get("density", 0.7)))
    return counts


def _role_pack_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    preset = _role_pack_preset(values)
    items = _role_pack_items(values)
    services = _role_pack_services(values)
    clearances = _role_pack_clearances(values)
    counts = _role_pack_counts(values, construct)
    state: dict[str, Any] = {
        construct: name,
        "role_pack_construct": construct,
        "role_pack_kind": kind,
        "action": _snake_id(values.get("action") or _ROLE_PACK_PRESET_ACTIONS.get(construct), "apply_role_preset"),
        "object_archetype": construct,
        "setpiece_layout": "role_pack_preset",
        "enabled": not _disabled(values.get("enabled", True)),
        "preset_role": preset["role"],
        "role_preset": preset["role"],
        "room_role": preset["role"],
        "preset_items": items,
        "packed_items": items,
        "preferred_item_order": _gameplay_name_list(values, ("preferred_item_order",), default=items),
        "packed_transforms": _footprint_pack_transform_map(_footprint_pack_positions({**values, "packed_items": items}, [0.0, 0.0, 0.0], limit=min(32, max(1, len(items))))),
        "transform_policy": _surface_marker_value(values, "transform_policy", "packing_strategy", fallback="role_pack_grid"),
        "parent_object": _surface_marker_value(values, "parent_object", "parent", fallback=name),
        "child_objects": items,
        "room_content_plan": f"{name}_content",
        "generated_child_assets": items,
        "content_family": "procedural_furniture",
        "role_services": services,
        "required_services": services,
        "role_clearances": clearances,
        "clearance_targets": clearances,
        "packing_policy": _surface_marker_value(values, "packing_policy", "packing_strategy", fallback=str(preset.get("policy", "best_fit"))),
        "packing_density": counts["packing_density"],
        "cell_size": _number(values.get("cell_size"), default=float(preset.get("cell", 0.5))),
        "clearance_profile": _surface_marker_value(values, "clearance_profile", "clearance_policy", fallback="role_clearance"),
        "service_profile": _surface_marker_value(values, "service_profile", "service_type", fallback="role_services"),
        "role_packing_rules": _gameplay_name_list(values, ("role_packing_rules", "priority_rules"), default=["fit_footprint", "avoid_collision", "reach_service"]),
        "required_clearance": _number(values.get("required_clearance") or values.get("clearance_radius"), default=0.45),
        "item_footprints": values.get("item_footprints") if isinstance(values.get("item_footprints"), Mapping) else {},
        **counts,
    }
    if construct == "service_reach_preset":
        state.update({"lathe_asset": "procedural_infrastructure", "source_family": "procedural_infrastructure", "network_type": "role_service_preset"})
    elif construct == "footprint_size_preset":
        state.update({"lathe_asset": "procedural_furniture", "source_family": "procedural_furniture", "furniture_type": "role_footprint_preset"})
    else:
        state.update({"lathe_asset": "procedural_interior", "source_family": "procedural_interior", "interior_count": 1})
    return state


def _role_pack_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    counts = _role_pack_counts(values, construct)
    width = max(0.30, min(4.0, counts["preset_item_count"] * 0.12))
    depth = max(0.24, min(3.0, counts["layout_slot_count"] * 0.04))
    if construct == "footprint_size_preset":
        return [width, 0.18, 0.12]
    if construct == "service_reach_preset":
        return [max(0.24, counts["service_reach_count"] * 0.10), 0.20, 0.10]
    if construct == "clearance_preset":
        return [max(0.24, counts["clearance_zone_count"] * 0.10), 0.18, 0.06]
    if construct == "role_item_set":
        return [width, 0.16, 0.08]
    return [width, depth, 0.12]


def _role_pack_affordance(values: Mapping[str, Any], construct: str, name: str) -> dict[str, Any]:
    return {
        "action": _snake_id(values.get("action") or _ROLE_PACK_PRESET_ACTIONS.get(construct), "apply_role_preset"),
        "room_role": _role_pack_preset(values)["role"],
        "preset_items": _role_pack_items(values),
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
    }


def _role_pack_child_core_name(name: str, construct: str) -> str:
    if construct in _ROLE_PACK_PRESET_CORE_SUFFIXES:
        return _role_pack_core_name(name, construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _footprint_packing_core_name(name, construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _layout_resolution_core_name(name, construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _placement_constraint_core_name(name, construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_role_pack_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _ROLE_PACK_PRESET_CORE_SUFFIXES:
        return _expand_role_pack_preset_macro(node, construct=construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _expand_footprint_packing_macro(node, construct=construct)
    if construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
        return _expand_layout_resolution_macro(node, construct=construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _expand_placement_constraint_macro(node, construct=construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in {"world_metric", "service_placement", "resource_flow"}:
        return _expand_footprint_child_macro(node, construct)
    return _expand_footprint_child_macro(node, construct)


def _expand_role_pack_preset_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _role_pack_kind(values, construct)
    depth = max(0, int(_number(values.get("_role_pack_depth"), default=0.0)))
    core_name = _role_pack_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_role_pack_scale(values, construct),
        state=_role_pack_state(values, construct, name, kind),
        tags=[construct, kind, "role_pack_preset", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_ROLE_PACK_PRESET_ACTIONS.get(construct), "apply_role_preset"): _role_pack_affordance(values, construct, name)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_ROLE_PACK_PRESET_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "arranges", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        if child_construct in _ROLE_PACK_PRESET_CORE_SUFFIXES:
            child_values["_role_pack_depth"] = max(depth + 1, int(_number(child_values.get("_role_pack_depth"), default=0.0)))
        if child_construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
            child_values["_footprint_packing_depth"] = max(1, int(_number(child_values.get("_footprint_packing_depth"), default=0.0)))
        if child_construct in _LAYOUT_RESOLUTION_CORE_SUFFIXES:
            child_values["_layout_resolution_depth"] = max(1, int(_number(child_values.get("_layout_resolution_depth"), default=0.0)))
        if child_construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
            child_values["_placement_constraint_depth"] = max(1, int(_number(child_values.get("_placement_constraint_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _ROLE_PACK_PRESET_ROLES.get(child_construct, _FOOTPRINT_PACKING_ROLES.get(child_construct, _LAYOUT_RESOLUTION_ROLES.get(child_construct, _PLACEMENT_CONSTRAINT_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_role_pack_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _role_pack_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} applies {child_construct} {suffix}."))

    preset = _role_pack_preset(values)
    role = preset["role"]
    items = _role_pack_items(values)
    services = _role_pack_services(values)
    clearances = _role_pack_clearances(values)
    counts = _role_pack_counts(values, construct)

    if construct == "room_pack_preset":
        add_child("role_item_set", "items", {"preset_role": role, "preset_items": items}, [center[0] - 0.28, center[1] + 0.24, center[2] + 0.04], relation="prepares", description=f"Room pack preset {name} prepares {role} item set.")
        add_child("footprint_size_preset", "footprints", {"preset_role": role, "preset_items": items}, [center[0] + 0.28, center[1] + 0.24, center[2] + 0.04], relation="sizes", description=f"Room pack preset {name} assigns {role} footprint sizes.")
        add_child("packing_policy_preset", "policy", {"preset_role": role, "packing_policy": values.get("packing_policy") or preset.get("policy"), "packing_density": counts["packing_density"], "preset_items": items}, [center[0] - 0.28, center[1] - 0.20, center[2] + 0.04], relation="packs", description=f"Room pack preset {name} applies {role} packing policy.")
        add_child("clearance_preset", "clearance", {"preset_role": role, "role_clearances": clearances, "clearance_targets": clearances}, [center[0], center[1] - 0.24, center[2] + 0.04], relation="reserves", description=f"Room pack preset {name} reserves {role} clearances.")
        add_child("service_reach_preset", "services", {"preset_role": role, "role_services": services, "required_services": services}, [center[0] + 0.28, center[1] - 0.20, center[2] + 0.04], relation="feeds", description=f"Room pack preset {name} applies {role} service reach.")
        add_child("footprint_packer", "packer", {"packed_items": items, "required_services": services, "clearance_targets": clearances, "packing_strategy": values.get("packing_policy") or preset.get("policy"), "packing_density": counts["packing_density"], "cell_size": preset.get("cell")}, [center[0], center[1], center[2] + 0.08], relation="drives", description=f"Room pack preset {name} drives footprint packing.")
        add_child("room_packing_solver", "transform_solver", {"packed_items": items, "required_services": services, "clearance_reservations": clearances, "packing_strategy": values.get("packing_policy") or preset.get("policy"), "packing_density": counts["packing_density"], "packed_transform_count": len(items), "packing_slot_count": max(1, len(items)), "parent_object": name}, [center[0], center[1] + 0.30, center[2] + 0.08], relation="places", description=f"Room pack preset {name} resolves role items into transforms.")
        add_child("room_content_plan", "content", {"packed_items": items, "required_services": services, "clearance_reservations": clearances, "packing_strategy": values.get("packing_policy") or preset.get("policy"), "packing_density": counts["packing_density"], "parent_object": name}, [center[0], center[1] + 0.42, center[2] + 0.10], relation="generates", description=f"Room pack preset {name} materializes role items as child assets.")

    elif construct == "footprint_size_preset":
        for index, item in enumerate(items[:16]):
            width, depth_size, height = _role_pack_item_dimensions(values, item)
            offset = (index - (min(len(items), 16) - 1) / 2.0) * 0.16
            add_child("placement_footprint", f"{item}_{index + 1:02d}", {"fixture_type": item, "furniture_type": item, "footprint_width": width, "footprint_depth": depth_size, "footprint_height": height, "_footprint_packing_depth": 2}, [center[0] + offset, center[1] + 0.18, center[2] + 0.04], relation="sizes", description=f"Footprint size preset {name} sizes {item}.")
        add_child("world_metric", "footprint_count", {"metric": "footprint_count", "metric_value": len(items)}, [center[0], center[1] - 0.18, center[2] + 0.04], relation="counts", description=f"Footprint size preset {name} exposes footprint count.")

    elif construct == "packing_policy_preset":
        add_child("occupancy_grid", "grid", {"packed_items": items, "cell_size": preset.get("cell"), "packing_density": counts["packing_density"]}, [center[0] - 0.20, center[1] + 0.18, center[2] + 0.04], relation="maps", description=f"Packing policy preset {name} prepares occupancy grid.")
        add_child("fit_profile", "fit", {"fit_policy": values.get("fit_policy") or preset.get("policy"), "fit_score": values.get("fit_score") or counts["packing_density"]}, [center[0], center[1] + 0.18, center[2] + 0.04], relation="scores", description=f"Packing policy preset {name} scores fit.")
        add_child("collision_rule", "collision", {"collision_policy": values.get("collision_policy") or "avoid_overlap", "collision_pair_count": max(1, len(items) - 1)}, [center[0] + 0.20, center[1] + 0.18, center[2] + 0.04], relation="blocks", description=f"Packing policy preset {name} blocks collisions.")
        add_child("footprint_packer", "packer", {"packed_items": items, "packing_strategy": values.get("packing_policy") or preset.get("policy"), "packing_density": counts["packing_density"]}, [center[0], center[1] - 0.18, center[2] + 0.04], relation="drives", description=f"Packing policy preset {name} drives packer.")

    elif construct == "clearance_preset":
        for index, clearance in enumerate(clearances[:12]):
            offset = (index - (min(len(clearances), 12) - 1) / 2.0) * 0.16
            add_child("clearance_zone", f"{clearance}_{index + 1:02d}", {"clearance_targets": [clearance], "clearance_radius": values.get("required_clearance") or values.get("clearance_radius") or 0.45}, [center[0] + offset, center[1] + 0.18, center[2] + 0.04], relation="reserves", description=f"Clearance preset {name} reserves {clearance}.")
        add_child("collision_rule", "clearance_collision", {"collision_policy": "avoid_clearance", "collision_pair_count": max(1, len(clearances))}, [center[0], center[1] - 0.18, center[2] + 0.04], relation="blocks", description=f"Clearance preset {name} converts clearances into collision keepouts.")

    elif construct == "service_reach_preset":
        for index, service in enumerate(services[:12]):
            offset = (index - (min(len(services), 12) - 1) / 2.0) * 0.16
            add_child("service_reach", f"{service}_{index + 1:02d}", {"required_services": [service], "service_types": [service], "service_radius": values.get("service_radius") or 2.5}, [center[0] + offset, center[1] + 0.18, center[2] + 0.04], relation="feeds", description=f"Service reach preset {name} links {service}.")
        add_child("world_metric", "service_count", {"metric": "service_reach_count", "metric_value": len(services)}, [center[0], center[1] - 0.18, center[2] + 0.04], relation="counts", description=f"Service reach preset {name} exposes service count.")

    elif construct == "role_item_set":
        for index, item in enumerate(items[:16]):
            width, depth_size, height = _role_pack_item_dimensions(values, item)
            offset = (index - (min(len(items), 16) - 1) / 2.0) * 0.14
            add_child("placement_footprint", f"{item}_{index + 1:02d}", {"fixture_type": item, "furniture_type": item, "footprint_width": width, "footprint_depth": depth_size, "footprint_height": height, "_footprint_packing_depth": 2}, [center[0] + offset, center[1] + 0.18, center[2] + 0.04], relation="prepares", description=f"Role item set {name} prepares {item}.")
        add_child("footprint_packer", "packer", {"packed_items": items, "packing_strategy": values.get("packing_policy") or preset.get("policy"), "packing_density": counts["packing_density"]}, [center[0], center[1] - 0.18, center[2] + 0.04], relation="drives", description=f"Role item set {name} feeds the footprint packer.")
        add_child("room_packing_solver", "transform_solver", {"packed_items": items, "packing_strategy": values.get("packing_policy") or preset.get("policy"), "packing_density": counts["packing_density"], "packed_transform_count": len(items), "parent_object": name}, [center[0], center[1] - 0.30, center[2] + 0.06], relation="places", description=f"Role item set {name} resolves items into transforms.")

    return objects, relationships


_BUILDING_ENVELOPE_CORE_SUFFIXES = {
    "building_envelope": "building_envelope_core",
    "floor_stack": "floor_stack_core",
    "facade_grid": "facade_grid_core",
    "facade_bay": "facade_bay_core",
    "roof_profile": "roof_profile_core",
    "vertical_core": "vertical_core_core",
    "entrance_plan": "entrance_plan_core",
}

_BUILDING_ENVELOPE_ROLES = {
    "building_envelope": "architecture",
    "floor_stack": "architecture",
    "facade_grid": "architecture",
    "facade_bay": "architecture",
    "roof_profile": "architecture",
    "vertical_core": "architecture",
    "entrance_plan": "architecture",
}

_BUILDING_ENVELOPE_KIND_KEYS = {
    "building_envelope": ("building_type", "envelope_type", "type"),
    "floor_stack": ("stack_type", "floor_type", "type"),
    "facade_grid": ("facade_style", "facade_pattern", "style", "type"),
    "facade_bay": ("bay_type", "opening_type", "type"),
    "roof_profile": ("roof_style", "roof", "type"),
    "vertical_core": ("core_type", "vertical_core_type", "type"),
    "entrance_plan": ("entry_type", "entrance_type", "type"),
}

_BUILDING_ENVELOPE_KIND_DEFAULTS = {
    "building_envelope": "building_envelope",
    "floor_stack": "floor_stack",
    "facade_grid": "facade_grid",
    "facade_bay": "window_bay",
    "roof_profile": "flat_roof",
    "vertical_core": "service_core",
    "entrance_plan": "main_entry",
}

_BUILDING_ENVELOPE_ACTIONS = {
    "building_envelope": "generate_building_envelope",
    "floor_stack": "stack_floors",
    "facade_grid": "lay_out_facade_grid",
    "facade_bay": "place_facade_bay",
    "roof_profile": "shape_roof_profile",
    "vertical_core": "route_vertical_core",
    "entrance_plan": "place_entrances",
}


def _building_envelope_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _BUILDING_ENVELOPE_KIND_DEFAULTS.get(construct, construct)
    for key in _BUILDING_ENVELOPE_KIND_KEYS.get(construct, ("type",)):
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _building_envelope_core_name(name: str, construct: str) -> str:
    return f"{name}_{_BUILDING_ENVELOPE_CORE_SUFFIXES.get(construct, 'building_envelope_core')}"


def _building_dimensions(values: Mapping[str, Any]) -> tuple[float, float, float]:
    width = _number(values.get("building_width") or values.get("width") or values.get("width_scale"), default=1.25)
    depth = _number(values.get("building_depth") or values.get("depth") or values.get("depth_scale"), default=0.88)
    floor_height = _number(values.get("floor_height") or values.get("floor_height_scale"), default=0.32)
    return max(0.35, min(8.0, width)), max(0.30, min(8.0, depth)), max(0.12, min(2.0, floor_height))


def _building_floor_count(values: Mapping[str, Any]) -> int:
    return max(1, min(24, _positive_int(values.get("floors") or values.get("floor_count") or values.get("building_floors"), default=3)))


def _building_bay_count(values: Mapping[str, Any]) -> int:
    return max(1, min(24, _positive_int(values.get("bays") or values.get("facade_bays") or values.get("window_bays") or values.get("building_bays"), default=4)))


def _building_entry_count(values: Mapping[str, Any]) -> int:
    return max(1, min(12, _positive_int(values.get("entries") or values.get("entry_count") or values.get("door_count"), default=1)))


def _building_facade_sides(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("facade_sides", "wall_sides", "sides"), default=["front", "left", "right", "rear"])[:8]


def _building_floor_roles(values: Mapping[str, Any]) -> list[str]:
    roles = _gameplay_name_list(values, ("floor_roles", "room_roles", "program_roles", "room_programs"), default=[])
    if roles:
        return [_snake_id(role, "room") for role in roles][:24]
    building_type = _surface_marker_value(values, "building_type", "envelope_type", "type", fallback="mixed_use")
    defaults = {
        "residential": ["lobby", "office_room", "bedroom"],
        "industrial": ["workshop_room", "storage_room", "control_room"],
        "lab": ["lobby", "lab_room", "storage_room"],
        "medical": ["lobby", "med_bay", "storage_room"],
        "commercial": ["shopfront", "office_room", "storage_room"],
        "mixed_use": ["lobby", "office_room", "storage_room"],
    }
    return defaults.get(_snake_id(building_type, "mixed_use"), defaults["mixed_use"])


def _building_floor_plan(values: Mapping[str, Any]) -> dict[str, str]:
    floors = _building_floor_count(values)
    roles = _building_floor_roles(values)
    return {f"floor_{index + 1:02d}": roles[index % len(roles)] for index in range(floors)}


def _building_facade_bay_map(values: Mapping[str, Any], *, limit: int = 96) -> dict[str, dict[str, Any]]:
    floors = _building_floor_count(values)
    bays = _building_bay_count(values)
    sides = _building_facade_sides(values)
    result: dict[str, dict[str, Any]] = {}
    for side in sides:
        for floor in range(floors):
            for bay in range(bays):
                if len(result) >= limit:
                    return result
                key = f"{side}_floor_{floor + 1:02d}_bay_{bay + 1:02d}"
                result[key] = {"side": side, "floor": floor + 1, "bay": bay + 1, "opening": "door" if side == "front" and floor == 0 and bay == bays // 2 else "window"}
    return result


def _building_envelope_counts(values: Mapping[str, Any], construct: str) -> dict[str, int]:
    floors = _building_floor_count(values)
    bays = _building_bay_count(values)
    sides = _building_facade_sides(values)
    entries = _building_entry_count(values)
    vertical_cores = max(1, min(8, _positive_int(values.get("vertical_core_count") or values.get("core_count"), default=1)))
    roof_equipment = max(0, min(24, _positive_int(values.get("roof_equipment_count") or values.get("hvac_count"), default=1 if floors >= 3 else 0)))
    facade_bay_total = max(1, floors * bays * max(1, len(sides)))
    counts = {
        "building_envelope_count": 0,
        "floor_stack_count": 0,
        "facade_grid_count": 0,
        "facade_bay_count": 0,
        "roof_profile_count": 0,
        "vertical_core_count": 0,
        "entrance_plan_count": 0,
        "floor_plate_count": 0,
        "room_stack_count": 0,
        "facade_side_count": len(sides),
        "window_bay_count": 0,
        "entry_count": entries,
        "door_count": entries,
        "roof_equipment_count": roof_equipment,
        "service_core_count": 0,
        "elevator_core_count": 0,
        "service_shaft_count": 0,
        "room_pack_preset_count": 0,
        "room_content_plan_count": 0,
    }
    if construct == "building_envelope":
        counts.update({"building_envelope_count": 1, "floor_stack_count": 1, "facade_grid_count": 1, "facade_bay_count": facade_bay_total, "roof_profile_count": 1, "vertical_core_count": vertical_cores, "entrance_plan_count": 1, "floor_plate_count": floors, "room_stack_count": floors, "window_bay_count": floors * bays, "service_core_count": vertical_cores, "elevator_core_count": vertical_cores, "service_shaft_count": vertical_cores, "room_pack_preset_count": floors, "room_content_plan_count": floors})
    elif construct == "floor_stack":
        counts.update({"floor_stack_count": 1, "floor_plate_count": floors, "room_stack_count": floors, "room_pack_preset_count": floors, "room_content_plan_count": floors})
    elif construct == "facade_grid":
        counts.update({"facade_grid_count": 1, "facade_bay_count": facade_bay_total, "window_bay_count": floors * bays})
    elif construct == "facade_bay":
        counts.update({"facade_bay_count": 1, "window_bay_count": 1, "wall_attachment_count": 1, "fixture_socket_count": 1})
    elif construct == "roof_profile":
        counts.update({"roof_profile_count": 1, "roof_equipment_count": roof_equipment})
    elif construct == "vertical_core":
        counts.update({"vertical_core_count": vertical_cores, "service_core_count": vertical_cores, "elevator_core_count": vertical_cores, "service_shaft_count": vertical_cores})
    elif construct == "entrance_plan":
        counts.update({"entrance_plan_count": 1, "entry_count": entries, "door_count": entries, "door_opening_count": entries, "fixture_socket_count": entries, "placement_constraint_count": entries})
    return counts


def _building_envelope_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    width, depth, floor_height = _building_dimensions(values)
    floors = _building_floor_count(values)
    bays = _building_bay_count(values)
    entries = _building_entry_count(values)
    sides = _building_facade_sides(values)
    roles = _building_floor_roles(values)
    floor_plan = _building_floor_plan(values)
    bay_map = _building_facade_bay_map(values)
    roof_style = _surface_marker_value(values, "roof_style", "roof", fallback="flat")
    facade_style = _surface_marker_value(values, "facade_style", "architecture_style", "style", fallback="grid")
    counts = _building_envelope_counts(values, construct)
    controls = {
        "building_width": width,
        "building_depth": depth,
        "width_scale": width,
        "depth_scale": depth,
        "floor_height": floor_height,
        "floor_height_scale": floor_height,
        "floors": floors,
        "floor_count": floors,
        "building_floors": floors,
        "bays": bays,
        "window_bays": bays,
        "building_bays": bays,
        "entries": entries,
        "entry_count": entries,
        "door_count": entries,
        "roof_style": roof_style,
        "facade_style": facade_style,
        "architecture_style": facade_style,
        "side_window_bays": max(1, bays // 2),
        "rear_window_bays": max(1, bays // 2),
        "roof_equipment_count": counts["roof_equipment_count"],
        "service_door_count": max(1, entries // 2) if floors >= 2 else 0,
    }
    state: dict[str, Any] = {
        construct: name,
        "building_envelope": name if construct == "building_envelope" else _surface_marker_value(values, "building_envelope", fallback=""),
        "floor_stack": name if construct == "floor_stack" else _surface_marker_value(values, "floor_stack", fallback=""),
        "facade_grid": name if construct == "facade_grid" else _surface_marker_value(values, "facade_grid", fallback=""),
        "facade_bay": name if construct == "facade_bay" else _surface_marker_value(values, "facade_bay", fallback=""),
        "roof_profile": name if construct == "roof_profile" else _surface_marker_value(values, "roof_profile", fallback=roof_style),
        "vertical_core": name if construct == "vertical_core" else _surface_marker_value(values, "vertical_core", fallback=""),
        "entrance_plan": name if construct == "entrance_plan" else _surface_marker_value(values, "entrance_plan", fallback=""),
        "building_envelope_profile": kind,
        "building_type": _surface_marker_value(values, "building_type", "envelope_type", "type", fallback=kind),
        "envelope_type": kind,
        "building_program": _surface_marker_value(values, "building_program", "program", fallback="mixed_use"),
        "floor_roles": roles,
        "floor_plan": floor_plan,
        "floor_heights": {floor: round((index + 1) * floor_height, 6) for index, floor in enumerate(floor_plan)},
        "facade_sides": sides,
        "facade_bays": bay_map,
        "facade_pattern": _surface_marker_value(values, "facade_pattern", fallback=facade_style),
        "roof_pitch": _number(values.get("roof_pitch") or values.get("pitch"), default=0.0 if roof_style in {"flat", "terrace"} else 0.35),
        "vertical_core_types": _gameplay_name_list(values, ("vertical_core_types", "core_types"), default=["stairs", "elevator", "service_shaft"]),
        "entrance_locations": _gameplay_name_list(values, ("entrance_locations", "entries"), default=["front"]),
        "building_envelope_controls": controls,
        "action": _snake_id(values.get("action") or _BUILDING_ENVELOPE_ACTIONS.get(construct), "generate_building_envelope"),
        "object_archetype": construct,
        "setpiece_layout": "building_envelope",
        "lathe_asset": "procedural_building",
        "source_family": "procedural_building",
        "procedural_family": "procedural_building",
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
        **controls,
        **counts,
    }
    return state


def _building_envelope_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    width, depth, floor_height = _building_dimensions(values)
    floors = _building_floor_count(values)
    total_height = floors * floor_height
    if construct == "floor_stack":
        return [width, max(0.12, total_height), depth * 0.18]
    if construct == "facade_grid":
        return [width, max(0.12, total_height), 0.08]
    if construct == "facade_bay":
        return [max(0.08, width / max(1, _building_bay_count(values))), max(0.08, floor_height * 0.7), 0.05]
    if construct == "roof_profile":
        return [width * 1.08, max(0.08, floor_height * 0.24), depth * 1.10]
    if construct == "vertical_core":
        return [max(0.12, width * 0.16), max(0.12, total_height), max(0.12, depth * 0.16)]
    if construct == "entrance_plan":
        return [max(0.18, width * 0.32), max(0.10, floor_height * 0.8), max(0.08, depth * 0.20)]
    return [width, max(0.16, total_height), depth]


def _building_envelope_affordance(values: Mapping[str, Any], construct: str, name: str) -> dict[str, Any]:
    return {
        "action": _snake_id(values.get("action") or _BUILDING_ENVELOPE_ACTIONS.get(construct), "generate_building_envelope"),
        "floors": _building_floor_count(values),
        "facade_bays": _building_bay_count(values),
        "roof_style": _surface_marker_value(values, "roof_style", "roof", fallback="flat"),
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
    }


def _building_envelope_child_core_name(name: str, construct: str) -> str:
    if construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
        return _building_envelope_core_name(name, construct)
    if construct in _ROLE_PACK_PRESET_CORE_SUFFIXES:
        return _role_pack_core_name(name, construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _footprint_packing_core_name(name, construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _interior_composition_core_name(name, construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _placement_constraint_core_name(name, construct)
    if construct in _SURFACE_AUTHORING_MACROS:
        return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_building_envelope_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
        return _expand_building_envelope_macro(node, construct=construct)
    if construct in _ROLE_PACK_PRESET_CORE_SUFFIXES:
        return _expand_role_pack_preset_macro(node, construct=construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _expand_footprint_packing_macro(node, construct=construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
        return _expand_interior_composition_macro(node, construct=construct)
    if construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
        return _expand_placement_constraint_macro(node, construct=construct)
    if construct in _SURFACE_AUTHORING_MACROS:
        return _expand_surface_authoring_macro(node, construct)
    if construct in {"world_metric"}:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_role_pack_child_macro(node, construct)


def _expand_building_envelope_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _building_envelope_kind(values, construct)
    depth_level = max(0, int(_number(values.get("_building_envelope_depth"), default=0.0)))
    core_name = _building_envelope_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_building_envelope_scale(values, construct),
        state=_building_envelope_state(values, construct, name, kind),
        tags=[construct, kind, "building_envelope", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_BUILDING_ENVELOPE_ACTIONS.get(construct), "generate_building_envelope"): _building_envelope_affordance(values, construct, name)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_BUILDING_ENVELOPE_ROLES.get(construct, "architecture"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth_level >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "arranges", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        if child_construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
            child_values["_building_envelope_depth"] = max(depth_level + 1, int(_number(child_values.get("_building_envelope_depth"), default=0.0)))
        if child_construct in _ROLE_PACK_PRESET_CORE_SUFFIXES:
            child_values["_role_pack_depth"] = max(1, int(_number(child_values.get("_role_pack_depth"), default=0.0)))
        if child_construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
            child_values["_footprint_packing_depth"] = max(1, int(_number(child_values.get("_footprint_packing_depth"), default=0.0)))
        if child_construct in _BUILDING_SERVICE_CORE_SUFFIXES:
            child_values["_building_service_depth"] = max(1, int(_number(child_values.get("_building_service_depth"), default=0.0)))
        if child_construct in _INTERIOR_COMPOSITION_CORE_SUFFIXES:
            child_values["_interior_composition_depth"] = max(1, int(_number(child_values.get("_interior_composition_depth"), default=0.0)))
        if child_construct in _PLACEMENT_CONSTRAINT_CORE_SUFFIXES:
            child_values["_placement_constraint_depth"] = max(1, int(_number(child_values.get("_placement_constraint_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _BUILDING_ENVELOPE_ROLES.get(child_construct, _ROLE_PACK_PRESET_ROLES.get(child_construct, _BUILDING_SERVICE_ROLES.get(child_construct, _INTERIOR_COMPOSITION_ROLES.get(child_construct, _PLACEMENT_CONSTRAINT_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "architecture"))))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_building_envelope_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _building_envelope_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} arranges {child_construct} {suffix}."))

    width, depth_size, floor_height = _building_dimensions(values)
    floors = _building_floor_count(values)
    bays = _building_bay_count(values)
    entries = _building_entry_count(values)
    sides = _building_facade_sides(values)
    roles = _building_floor_roles(values)
    roof_style = _surface_marker_value(values, "roof_style", "roof", fallback="flat")
    facade_style = _surface_marker_value(values, "facade_style", "architecture_style", "style", fallback="grid")
    counts = _building_envelope_counts(values, construct)

    if construct == "building_envelope":
        add_child("floor_stack", "floors", {"floors": floors, "floor_roles": roles, "floor_height": floor_height}, [center[0], center[1] - depth_size * 0.12, center[2] + floor_height * 0.08], relation="stacks", description=f"Building envelope {name} stacks {floors} floors.")
        add_child("facade_grid", "facade", {"floors": floors, "bays": bays, "facade_sides": sides, "facade_style": facade_style}, [center[0], center[1] + depth_size * 0.52, center[2] + floor_height * 0.12], relation="skins", description=f"Building envelope {name} lays out facade bays.")
        add_child("roof_profile", "roof", {"roof_style": roof_style, "roof_equipment_count": counts["roof_equipment_count"]}, [center[0], center[1], center[2] + floors * floor_height + floor_height * 0.12], relation="caps", description=f"Building envelope {name} shapes roof profile {roof_style}.")
        add_child("vertical_core", "vertical_core", {"vertical_core_count": counts["vertical_core_count"], "floors": floors}, [center[0] - width * 0.22, center[1], center[2] + floors * floor_height * 0.45], relation="routes", description=f"Building envelope {name} routes vertical circulation and service shafts.")
        add_child("entrance_plan", "entries", {"entries": entries, "entry_count": entries, "door_count": entries}, [center[0], center[1] + depth_size * 0.66, center[2] + floor_height * 0.20], relation="opens", description=f"Building envelope {name} places entrances.")

    elif construct == "floor_stack":
        for index in range(min(floors, 16)):
            role = roles[index % len(roles)]
            y = center[1] + (index - (floors - 1) / 2.0) * max(0.12, floor_height * 0.60)
            add_child("room_pack_preset", f"floor_{index + 1:02d}_{role}", {"preset_role": role, "room_role": role, "parent_object": name, "floor_index": index + 1, "floors": floors, "room_width": width, "room_depth": depth_size}, [center[0], y, center[2] + floor_height * 0.06], relation="programs", description=f"Floor stack {name} turns floor {index + 1} into {role} room contents.")
        add_child("world_metric", "floor_area", {"metric": "building_floor_area", "metric_value": round(width * depth_size * floors, 4)}, [center[0], center[1] - depth_size * 0.24, center[2] + 0.04], relation="measures", description=f"Floor stack {name} exposes total floor area.")

    elif construct == "facade_grid":
        bay_map = list(_building_facade_bay_map(values, limit=48).items())
        for index, (bay_id, bay) in enumerate(bay_map):
            side = str(bay["side"])
            col = (int(bay["bay"]) - 1) - (bays - 1) / 2.0
            floor = int(bay["floor"]) - 1
            x = center[0] + col * width * 0.70 / max(1, bays - 1)
            z = center[2] + floor * floor_height * 0.34
            add_child("facade_bay", bay_id, {"facade_side": side, "floor_index": floor + 1, "bay_index": int(bay["bay"]), "opening_type": bay["opening"], "facade_style": facade_style}, [x, center[1] + depth_size * 0.10, z + floor_height * 0.12], relation="places", description=f"Facade grid {name} places {bay_id}.")
        add_child("material_zone", "facade_material", {"zone": "facade", "material": values.get("facade_material") or "painted_masonry", "targets": [name]}, [center[0], center[1] - depth_size * 0.14, center[2] + floor_height * 0.08], relation="skins", description=f"Facade grid {name} assigns facade material.")

    elif construct == "facade_bay":
        side = _surface_marker_value(values, "facade_side", "wall_side", fallback="front")
        opening = _surface_marker_value(values, "opening_type", "bay_type", fallback="window")
        socket_id = f"{name}_{side}_{opening}"
        add_child("fixture_socket", "opening_socket", {"socket_target": socket_id, "socket_role": opening, "wall_side": side}, [center[0] - 0.08, center[1] + 0.10, center[2] + 0.02], relation="prepares", description=f"Facade bay {name} prepares socket for {opening}.")
        add_child("wall_attachment", opening, {"target_socket": socket_id, "placed_object": f"{name}_{opening}", "fixture_type": opening, "wall_side": side}, [center[0] + 0.08, center[1] + 0.10, center[2] + 0.02], relation="attaches", description=f"Facade bay {name} attaches {opening}.")

    elif construct == "roof_profile":
        add_child("material_zone", "roof_material", {"zone": "roof", "material": values.get("roof_material") or "dark_roofing", "targets": [name]}, [center[0] - width * 0.14, center[1], center[2] + 0.04], relation="skins", description=f"Roof profile {name} assigns roof material.")
        if counts["roof_equipment_count"]:
            add_child("service_anchor_map", "roof_equipment", {"service_anchors": ["power", "exhaust"], "required_services": ["power", "exhaust"], "roof_equipment_count": counts["roof_equipment_count"], "_footprint_packing_depth": 2}, [center[0] + width * 0.14, center[1], center[2] + 0.04], relation="feeds", description=f"Roof profile {name} prepares rooftop equipment anchors.")
        add_child("world_metric", "roof_pitch", {"metric": "roof_pitch", "metric_value": _number(values.get("roof_pitch") or values.get("pitch"), default=0.0 if roof_style in {"flat", "terrace"} else 0.35)}, [center[0], center[1] - depth_size * 0.12, center[2] + 0.04], relation="measures", description=f"Roof profile {name} exposes roof pitch.")

    elif construct == "vertical_core":
        for index in range(max(1, counts["vertical_core_count"])):
            offset = (index - (counts["vertical_core_count"] - 1) / 2.0) * width * 0.18
            add_child("service_core", f"service_core_{index + 1:02d}", {"floors": floors, "service_core_count": 1}, [center[0] + offset, center[1], center[2] + 0.04], relation="routes", description=f"Vertical core {name} routes service core {index + 1}.")
            add_child("elevator_core", f"elevator_{index + 1:02d}", {"floors": floors, "elevator_core_count": 1}, [center[0] + offset + width * 0.06, center[1], center[2] + 0.04], relation="moves", description=f"Vertical core {name} places elevator core {index + 1}.")
            add_child("service_shaft", f"shaft_{index + 1:02d}", {"floors": floors, "service_shaft_count": 1}, [center[0] + offset - width * 0.06, center[1], center[2] + 0.04], relation="routes", description=f"Vertical core {name} places service shaft {index + 1}.")

    elif construct == "entrance_plan":
        for index in range(entries):
            offset = (index - (entries - 1) / 2.0) * width * 0.22
            socket_id = f"{name}_entry_{index + 1:02d}"
            add_child("door_opening", f"entry_{index + 1:02d}", {"door_width": values.get("door_width") or 0.9, "target_socket": socket_id, "wall_side": "front"}, [center[0] + offset, center[1], center[2] + 0.04], relation="opens", description=f"Entrance plan {name} opens entry {index + 1}.")
            add_child("fixture_socket", f"entry_socket_{index + 1:02d}", {"socket_target": socket_id, "socket_role": "entry", "wall_side": "front"}, [center[0] + offset, center[1] + 0.12, center[2] + 0.04], relation="prepares", description=f"Entrance plan {name} prepares entry socket {index + 1}.")
            add_child("placement_constraint", f"entry_clearance_{index + 1:02d}", {"constraint_type": "entry_clearance", "placement_rule": "keep_entry_clear", "target_socket": socket_id, "clearance_radius": values.get("entry_clearance") or 0.75}, [center[0] + offset, center[1] - 0.12, center[2] + 0.04], relation="reserves", description=f"Entrance plan {name} reserves entry clearance {index + 1}.")

    return objects, relationships


_SITE_COMPOUND_CORE_SUFFIXES = {
    "site_compound": "site_compound_core",
    "building_lot": "building_lot_core",
    "courtyard_plan": "courtyard_plan_core",
    "pedestrian_path": "pedestrian_path_core",
    "service_alley": "service_alley_core",
    "parking_zone": "parking_zone_core",
    "loading_zone": "loading_zone_core",
    "exterior_utility": "exterior_utility_core",
}

_SITE_COMPOUND_ROLES = {
    "site_compound": "environment_structure",
    "building_lot": "environment_structure",
    "courtyard_plan": "environment_structure",
    "pedestrian_path": "navigation",
    "service_alley": "navigation",
    "parking_zone": "environment_structure",
    "loading_zone": "environment_structure",
    "exterior_utility": "environment_structure",
}

_SITE_COMPOUND_KIND_KEYS = {
    "site_compound": ("site_type", "compound_type", "type"),
    "building_lot": ("building_type", "lot_type", "type"),
    "courtyard_plan": ("courtyard_type", "public_space", "type"),
    "pedestrian_path": ("path_type", "route_type", "type"),
    "service_alley": ("alley_type", "service_type", "type"),
    "parking_zone": ("parking_type", "vehicle_type", "type"),
    "loading_zone": ("loading_type", "dock_type", "type"),
    "exterior_utility": ("utility_type", "service_type", "type"),
}

_SITE_COMPOUND_KIND_DEFAULTS = {
    "site_compound": "site_compound",
    "building_lot": "building_lot",
    "courtyard_plan": "courtyard",
    "pedestrian_path": "walkway",
    "service_alley": "service_alley",
    "parking_zone": "parking",
    "loading_zone": "loading",
    "exterior_utility": "utility_spine",
}

_SITE_COMPOUND_ACTIONS = {
    "site_compound": "compose_site_compound",
    "building_lot": "place_building_lot",
    "courtyard_plan": "reserve_courtyard",
    "pedestrian_path": "route_pedestrian_path",
    "service_alley": "route_service_alley",
    "parking_zone": "arrange_parking_zone",
    "loading_zone": "arrange_loading_zone",
    "exterior_utility": "route_exterior_utility",
}


def _site_compound_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _SITE_COMPOUND_KIND_DEFAULTS.get(construct, construct)
    for key in _SITE_COMPOUND_KIND_KEYS.get(construct, ("type",)):
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _site_compound_core_name(name: str, construct: str) -> str:
    return f"{name}_{_SITE_COMPOUND_CORE_SUFFIXES.get(construct, 'site_compound_core')}"


def _site_buildings(values: Mapping[str, Any]) -> list[str]:
    buildings = _gameplay_name_list(values, ("site_buildings", "buildings", "building_types"), default=[])
    if buildings:
        return [_snake_id(item, "building") for item in buildings][:16]
    building_count = max(1, min(16, _positive_int(values.get("site_building_count") or values.get("building_count"), default=3)))
    defaults = ["primary", "secondary", "support", "utility", "storage", "clinic", "workshop", "office"]
    return defaults[:building_count]


def _site_courtyards(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("courtyards", "courtyard_program", "public_spaces"), default=["central_court"])


def _site_paths(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("pedestrian_paths", "paths", "walkways"), default=["front_walk", "crosswalk"])


def _site_service_alleys(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("service_alleys", "alleys", "service_routes"), default=["rear_service"])


def _site_parking_zones(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("parking_zones", "parking", "vehicle_zones"), default=["visitor_parking"])


def _site_loading_zones(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("loading_zones", "loading", "dock_zones"), default=["loading_bay"])


def _site_utilities(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("exterior_utilities", "utilities", "services"), default=["power", "water", "data"])


def _site_dimensions(values: Mapping[str, Any]) -> tuple[float, float]:
    width = _number(values.get("site_width") or values.get("width") or values.get("setpiece_width"), default=2.8)
    depth = _number(values.get("site_depth") or values.get("depth") or values.get("setpiece_depth"), default=2.1)
    return max(0.6, min(12.0, width)), max(0.6, min(12.0, depth))


def _site_counts(values: Mapping[str, Any], construct: str) -> dict[str, int]:
    buildings = _site_buildings(values)
    courtyards = _site_courtyards(values)
    paths = _site_paths(values)
    alleys = _site_service_alleys(values)
    parking = _site_parking_zones(values)
    loading = _site_loading_zones(values)
    utilities = _site_utilities(values)
    parking_bays = max(1, min(96, _positive_int(values.get("parking_bay_count") or values.get("parking_bays"), default=max(2, len(buildings) * 2))))
    counts = {
        "site_compound_count": 0,
        "building_lot_count": 0,
        "courtyard_plan_count": 0,
        "pedestrian_path_count": 0,
        "service_alley_count": 0,
        "parking_zone_count": 0,
        "loading_zone_count": 0,
        "exterior_utility_count": 0,
        "site_building_count": len(buildings),
        "site_route_count": len(paths) + len(alleys),
        "building_envelope_count": 0,
        "courtyard_count": 0,
        "public_space_plan_count": 0,
        "maintenance_access_count": 0,
        "loading_dock_count": 0,
        "utility_corridor_count": 0,
        "service_connection_count": 0,
        "parking_bay_count": 0,
    }
    if construct == "site_compound":
        counts.update({"site_compound_count": 1, "building_lot_count": len(buildings), "courtyard_plan_count": len(courtyards), "pedestrian_path_count": len(paths), "service_alley_count": len(alleys), "parking_zone_count": len(parking), "loading_zone_count": len(loading), "exterior_utility_count": len(utilities), "building_envelope_count": len(buildings), "courtyard_count": len(courtyards), "public_space_plan_count": len(courtyards), "maintenance_access_count": len(paths) + len(alleys), "loading_dock_count": len(loading), "utility_corridor_count": 1, "service_connection_count": len(utilities), "parking_bay_count": parking_bays})
    elif construct == "building_lot":
        counts.update({"building_lot_count": 1, "building_envelope_count": 1, "placement_footprint_count": 1})
    elif construct == "courtyard_plan":
        counts.update({"courtyard_plan_count": 1, "courtyard_count": 1, "public_space_plan_count": 1, "pedestrian_path_count": max(1, len(paths))})
    elif construct == "pedestrian_path":
        counts.update({"pedestrian_path_count": 1, "maintenance_access_count": 1, "site_route_count": 1})
    elif construct == "service_alley":
        counts.update({"service_alley_count": 1, "maintenance_access_count": 1, "service_connection_count": len(utilities), "site_route_count": 1})
    elif construct == "parking_zone":
        counts.update({"parking_zone_count": 1, "parking_bay_count": parking_bays, "placement_footprint_count": parking_bays})
    elif construct == "loading_zone":
        counts.update({"loading_zone_count": 1, "loading_dock_count": max(1, len(loading)), "service_connection_count": len(utilities)})
    elif construct == "exterior_utility":
        counts.update({"exterior_utility_count": 1, "utility_corridor_count": 1, "service_connection_count": len(utilities)})
    return counts


def _site_compound_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    width, depth = _site_dimensions(values)
    buildings = _site_buildings(values)
    courtyards = _site_courtyards(values)
    paths = _site_paths(values)
    alleys = _site_service_alleys(values)
    parking = _site_parking_zones(values)
    loading = _site_loading_zones(values)
    utilities = _site_utilities(values)
    counts = _site_counts(values, construct)
    utility_map = {utility: [f"{building}_service" for building in buildings] for utility in utilities}
    controls = {
        "setpiece_width": width,
        "setpiece_depth": depth,
        "width_scale": width,
        "depth_scale": depth,
        "site_compound_count": counts["site_compound_count"],
        "building_lot_count": counts["building_lot_count"],
        "courtyard_plan_count": counts["courtyard_plan_count"],
        "pedestrian_path_count": counts["pedestrian_path_count"],
        "service_alley_count": counts["service_alley_count"],
        "parking_zone_count": counts["parking_zone_count"],
        "loading_zone_count": counts["loading_zone_count"],
        "exterior_utility_count": counts["exterior_utility_count"],
        "parking_bay_count": counts["parking_bay_count"],
        "loading_dock_count": counts["loading_dock_count"],
        "utility_corridor_count": counts["utility_corridor_count"],
        "service_connection_count": counts["service_connection_count"],
        "courtyard_count": counts["courtyard_count"],
    }
    state: dict[str, Any] = {
        construct: name,
        "site_compound": name if construct == "site_compound" else _surface_marker_value(values, "site_compound", fallback=""),
        "building_lot": name if construct == "building_lot" else _surface_marker_value(values, "building_lot", fallback=""),
        "courtyard_plan": name if construct == "courtyard_plan" else _surface_marker_value(values, "courtyard_plan", fallback=""),
        "pedestrian_path": name if construct == "pedestrian_path" else _surface_marker_value(values, "pedestrian_path", fallback=""),
        "service_alley": name if construct == "service_alley" else _surface_marker_value(values, "service_alley", fallback=""),
        "parking_zone": name if construct == "parking_zone" else _surface_marker_value(values, "parking_zone", fallback=""),
        "loading_zone": name if construct == "loading_zone" else _surface_marker_value(values, "loading_zone", fallback=""),
        "exterior_utility": name if construct == "exterior_utility" else _surface_marker_value(values, "exterior_utility", fallback=""),
        "site_layout_profile": kind,
        "site_buildings": buildings,
        "building_lots": [f"{building}_lot" for building in buildings],
        "courtyard_program": courtyards,
        "pedestrian_paths": paths,
        "service_alleys": alleys,
        "parking_zones": parking,
        "loading_zones": loading,
        "exterior_utilities": utilities,
        "site_access_points": _gameplay_name_list(values, ("site_access_points", "entries", "access_points"), default=["front_gate", "service_gate"]),
        "site_utility_map": utility_map,
        "site_compound_controls": controls,
        "action": _snake_id(values.get("action") or _SITE_COMPOUND_ACTIONS.get(construct), "compose_site_compound"),
        "object_archetype": construct,
        "setpiece_layout": "site_compound",
        "lathe_asset": "procedural_setpiece",
        "source_family": "procedural_setpiece",
        "procedural_family": "procedural_setpiece",
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
        **controls,
        **counts,
    }
    return state


def _site_compound_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    width, depth = _site_dimensions(values)
    if construct == "building_lot":
        return [width * 0.22, depth * 0.22, 0.08]
    if construct == "courtyard_plan":
        return [width * 0.36, depth * 0.28, 0.05]
    if construct in {"pedestrian_path", "service_alley"}:
        return [width * 0.52, depth * 0.08, 0.04]
    if construct == "parking_zone":
        return [width * 0.34, depth * 0.22, 0.04]
    if construct == "loading_zone":
        return [width * 0.26, depth * 0.18, 0.05]
    if construct == "exterior_utility":
        return [width * 0.42, depth * 0.06, 0.06]
    return [width, depth, 0.10]


def _site_compound_affordance(values: Mapping[str, Any], construct: str, name: str) -> dict[str, Any]:
    return {
        "action": _snake_id(values.get("action") or _SITE_COMPOUND_ACTIONS.get(construct), "compose_site_compound"),
        "site_buildings": _site_buildings(values),
        "routes": [*_site_paths(values), *_site_service_alleys(values)],
        "utilities": _site_utilities(values),
        "placement_group": _surface_marker_value(values, "placement_group", "group", fallback=name),
    }


def _site_child_core_name(name: str, construct: str) -> str:
    if construct in _SITE_COMPOUND_CORE_SUFFIXES:
        return _site_compound_core_name(name, construct)
    if construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
        return _building_envelope_core_name(name, construct)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _city_plan_core_name(name, construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _building_service_core_name(name, construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _infra_network_core_name(name, construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _footprint_packing_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_site_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _SITE_COMPOUND_CORE_SUFFIXES:
        return _expand_site_compound_macro(node, construct=construct)
    if construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
        return _expand_building_envelope_macro(node, construct=construct)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _expand_city_planning_macro(node, construct=construct)
    if construct in _BUILDING_SERVICE_CORE_SUFFIXES:
        return _expand_building_services_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
        return _expand_footprint_packing_macro(node, construct=construct)
    if construct in {"world_metric"}:
        return _expand_simulation_macro(node, construct=construct)
    return _expand_building_envelope_child_macro(node, construct)


def _expand_site_compound_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _site_compound_kind(values, construct)
    depth_level = max(0, int(_number(values.get("_site_compound_depth"), default=0.0)))
    core_name = _site_compound_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_site_compound_scale(values, construct),
        state=_site_compound_state(values, construct, name, kind),
        tags=[construct, kind, "site_compound", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_SITE_COMPOUND_ACTIONS.get(construct), "compose_site_compound"): _site_compound_affordance(values, construct, name)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_SITE_COMPOUND_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth_level >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "arranges", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        if child_construct in _SITE_COMPOUND_CORE_SUFFIXES:
            child_values["_site_compound_depth"] = max(depth_level + 1, int(_number(child_values.get("_site_compound_depth"), default=0.0)))
        if child_construct in _BUILDING_ENVELOPE_CORE_SUFFIXES:
            child_values["_building_envelope_depth"] = max(1, int(_number(child_values.get("_building_envelope_depth"), default=0.0)))
        if child_construct in _BUILDING_SERVICE_CORE_SUFFIXES:
            child_values["_building_service_depth"] = max(1, int(_number(child_values.get("_building_service_depth"), default=0.0)))
        if child_construct in _INFRA_NETWORK_CORE_SUFFIXES:
            child_values["_infra_network_depth"] = max(1, int(_number(child_values.get("_infra_network_depth"), default=0.0)))
        if child_construct in _FOOTPRINT_PACKING_CORE_SUFFIXES:
            child_values["_footprint_packing_depth"] = max(1, int(_number(child_values.get("_footprint_packing_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _SITE_COMPOUND_ROLES.get(child_construct, _BUILDING_ENVELOPE_ROLES.get(child_construct, _BUILDING_SERVICE_ROLES.get(child_construct, _INFRA_NETWORK_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_site_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _site_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} arranges {child_construct} {suffix}."))

    width, depth_size = _site_dimensions(values)
    buildings = _site_buildings(values)
    courtyards = _site_courtyards(values)
    paths = _site_paths(values)
    alleys = _site_service_alleys(values)
    parking = _site_parking_zones(values)
    loading = _site_loading_zones(values)
    utilities = _site_utilities(values)
    counts = _site_counts(values, construct)

    if construct == "site_compound":
        for index, building in enumerate(buildings[:8]):
            offset = (index - (min(len(buildings), 8) - 1) / 2.0) * width * 0.20
            add_child("building_lot", f"{building}_lot", {"building_type": building, "lot_index": index + 1}, [center[0] + offset, center[1] + depth_size * 0.04, center[2] + 0.06], relation="places", description=f"Site compound {name} places {building} building lot.")
        for index, courtyard in enumerate(courtyards[:4]):
            add_child("courtyard_plan", courtyard, {"courtyard_program": [courtyard], "public_spaces": [courtyard]}, [center[0], center[1] - depth_size * (0.10 + index * 0.08), center[2] + 0.04], relation="reserves", description=f"Site compound {name} reserves courtyard {courtyard}.")
        for index, path in enumerate(paths[:8]):
            add_child("pedestrian_path", path, {"path_type": path, "routes": [path]}, [center[0] - width * 0.24 + index * width * 0.06, center[1] + depth_size * 0.38, center[2] + 0.04], relation="routes_to", description=f"Site compound {name} routes pedestrian path {path}.")
        for index, alley in enumerate(alleys[:6]):
            add_child("service_alley", alley, {"alley_type": alley, "service_routes": [alley], "utilities": utilities}, [center[0] + width * 0.24 - index * width * 0.06, center[1] - depth_size * 0.38, center[2] + 0.04], relation="services", description=f"Site compound {name} routes service alley {alley}.")
        for index, zone in enumerate(parking[:4]):
            add_child("parking_zone", zone, {"parking_type": zone, "parking_bay_count": counts["parking_bay_count"]}, [center[0] - width * 0.34, center[1] - depth_size * 0.12 + index * depth_size * 0.10, center[2] + 0.04], relation="parks", description=f"Site compound {name} arranges parking zone {zone}.")
        for index, zone in enumerate(loading[:4]):
            add_child("loading_zone", zone, {"loading_type": zone, "utilities": utilities}, [center[0] + width * 0.34, center[1] - depth_size * 0.12 + index * depth_size * 0.10, center[2] + 0.04], relation="loads", description=f"Site compound {name} arranges loading zone {zone}.")
        add_child("exterior_utility", "utility_spine", {"utilities": utilities, "service_targets": buildings}, [center[0], center[1] - depth_size * 0.50, center[2] + 0.05], relation="feeds", description=f"Site compound {name} routes exterior utilities.")

    elif construct == "building_lot":
        building_type = _surface_marker_value(values, "building_type", "lot_type", fallback="building")
        add_child("placement_footprint", "pad", {"footprint_width": values.get("lot_width") or width * 0.24, "footprint_depth": values.get("lot_depth") or depth_size * 0.24, "footprint_height": 0.08, "fixture_type": building_type}, [center[0], center[1], center[2] + 0.04], relation="reserves", description=f"Building lot {name} reserves pad for {building_type}.")
        add_child("building_envelope", "building", {"building_type": building_type, "floors": values.get("floors") or 3, "bays": values.get("bays") or 4, "roof_style": values.get("roof_style") or "flat"}, [center[0], center[1], center[2] + 0.12], relation="builds", description=f"Building lot {name} generates {building_type} envelope.")

    elif construct == "courtyard_plan":
        courtyard = _surface_marker_value(values, "courtyard_type", "public_space", fallback=kind)
        add_child("public_space_plan", "public_space", {"public_spaces": [courtyard], "courtyard_count": 1}, [center[0], center[1], center[2] + 0.04], relation="reserves", description=f"Courtyard plan {name} reserves public space {courtyard}.")
        add_child("pedestrian_path", "loop_path", {"path_type": "courtyard_loop", "routes": ["courtyard_loop"]}, [center[0], center[1] + depth_size * 0.12, center[2] + 0.04], relation="circulates", description=f"Courtyard plan {name} adds pedestrian loop.")

    elif construct == "pedestrian_path":
        path = _surface_marker_value(values, "path_type", "route_type", fallback=kind)
        add_child("maintenance_access", "walkway", {"access_type": path, "walkway_count": 1}, [center[0], center[1], center[2] + 0.04], relation="opens", description=f"Pedestrian path {name} creates walkway access.")
        add_child("fixture_socket", "entry_socket", {"socket_target": f"{name}_path_socket", "socket_role": "pedestrian_entry"}, [center[0], center[1] + depth_size * 0.08, center[2] + 0.04], relation="anchors", description=f"Pedestrian path {name} exposes entry socket.")

    elif construct == "service_alley":
        add_child("maintenance_access", "service_lane", {"access_type": "service_alley", "walkway_count": 1}, [center[0], center[1], center[2] + 0.04], relation="opens", description=f"Service alley {name} creates service access.")
        add_child("exterior_utility", "utility_run", {"utilities": utilities}, [center[0], center[1] - depth_size * 0.08, center[2] + 0.05], relation="feeds", description=f"Service alley {name} carries exterior utilities.")

    elif construct == "parking_zone":
        bays = max(1, counts["parking_bay_count"])
        for index in range(min(bays, 24)):
            offset = (index - (min(bays, 24) - 1) / 2.0) * width * 0.05
            add_child("placement_footprint", f"parking_bay_{index + 1:02d}", {"fixture_type": "vehicle_parking", "footprint_width": 0.28, "footprint_depth": 0.52, "footprint_height": 0.04, "_footprint_packing_depth": 2}, [center[0] + offset, center[1], center[2] + 0.03], relation="parks", description=f"Parking zone {name} reserves parking bay {index + 1}.")
        add_child("world_metric", "parking_capacity", {"metric": "parking_bay_count", "metric_value": bays}, [center[0], center[1] - depth_size * 0.12, center[2] + 0.04], relation="measures", description=f"Parking zone {name} exposes parking capacity.")

    elif construct == "loading_zone":
        add_child("loading_dock", "dock", {"loading_dock_count": 1, "service_targets": buildings}, [center[0], center[1], center[2] + 0.05], relation="loads", description=f"Loading zone {name} creates loading dock.")
        add_child("service_alley", "truck_access", {"alley_type": "truck_access", "utilities": utilities}, [center[0], center[1] - depth_size * 0.10, center[2] + 0.04], relation="routes_to", description=f"Loading zone {name} routes truck access.")

    elif construct == "exterior_utility":
        add_child("utility_corridor", "corridor", {"utilities": utilities, "service_targets": values.get("service_targets") or buildings}, [center[0], center[1], center[2] + 0.04], relation="routes", description=f"Exterior utility {name} routes utility corridor.")
        for index, utility in enumerate(utilities[:12]):
            offset = (index - (min(len(utilities), 12) - 1) / 2.0) * width * 0.06
            add_child("service_connection", utility, {"service_type": utility, "service_targets": values.get("service_targets") or buildings}, [center[0] + offset, center[1] + depth_size * 0.08, center[2] + 0.04], relation="feeds", description=f"Exterior utility {name} creates {utility} service connection.")

    return objects, relationships


