def _resilience_kind(values: Mapping[str, Any], construct: str) -> str:
    fallback = _RESILIENCE_KIND_DEFAULTS.get(construct, construct)
    for key in _RESILIENCE_KIND_KEYS.get(construct, ("type",)):
        if key not in values:
            continue
        raw = values.get(key)
        if raw is None or _disabled(raw) or isinstance(raw, Mapping | Sequence) and not isinstance(raw, str):
            continue
        if isinstance(raw, str) and not raw.strip():
            continue
        return _snake_id(raw, fallback)
    return fallback


def _resilience_core_name(name: str, construct: str) -> str:
    return f"{name}_{_RESILIENCE_CORE_SUFFIXES.get(construct, 'resilience_core')}"


def _resilience_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "resilience_plan":
        return [max(3.6, _number(values.get("width"), default=6.8)), max(2.6, _number(values.get("depth"), default=4.8)), 0.22]
    if construct in {"climate_zone", "climate_risk_map", "green_infrastructure", "protected_land"}:
        return [1.48, 0.92, 0.16]
    if construct in {"evacuation_route", "cooling_corridor"}:
        return [1.46, 0.20, 0.10]
    return [0.54, 0.34, 0.12]


def _resilience_climate_zones(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("climate_zones", "zones", "biomes"), default=["river_lowland", "urban_core"])


def _resilience_hazards(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("hazards", "risk_types", "risks"), default=["flood", "fire", "heat"])


def _resilience_measures(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("adaptation_measures", "mitigation_actions", "measures"), default=["shade", "stormwater", "shelter"])


def _resilience_routes(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("evacuation_routes", "routes"), default=["primary_escape"])


def _resilience_shelters(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("shelters", "emergency_shelters"), default=["civic_shelter"])


def _resilience_resources(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("resource_limits", "resources", "constraints"), default=["water", "power"])


def _resilience_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    zones = _resilience_climate_zones(values)
    hazards = _resilience_hazards(values)
    measures = _resilience_measures(values)
    routes = _resilience_routes(values)
    shelters = _resilience_shelters(values)
    resources = _resilience_resources(values)
    flood_level = _number(values.get("flood_level"), default=0.35)
    fire_level = _number(values.get("fire_level"), default=0.25)
    heat_level = _number(values.get("heat_level"), default=0.45)
    resilience_score = _number(values.get("resilience_score"), default=0.55)
    state: dict[str, Any] = {
        construct: name,
        "resilience_construct": construct,
        "resilience_kind": kind,
        "action": _snake_id(values.get("action") or _RESILIENCE_ACTIONS.get(construct), "compose_resilience"),
        f"{construct}_count": 1,
        "resilience_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "climate_resilience",
        "enabled": not _disabled(values.get("enabled", True)),
        "climate_zones": zones,
        "hazards": hazards,
        "risk_types": hazards,
        "flood_level": flood_level,
        "fire_level": fire_level,
        "heat_level": heat_level,
        "stormwater_capacity": _number(values.get("stormwater_capacity"), default=0.7),
        "canopy_cover": _number(values.get("canopy_cover"), default=0.32),
        "resilience_score": resilience_score,
        "adaptation_measures": measures,
        "mitigation_actions": measures,
        "evacuation_routes": routes,
        "shelters": shelters,
        "protected_areas": _gameplay_name_list(values, ("protected_areas", "protected_land"), default=["riparian_buffer"]),
        "resource_limits": resources,
        "transit_growth": _surface_marker_value(values, "transit_growth", "growth", fallback="compact_nodes"),
    }
    if construct == "resilience_plan":
        state.update({
            "climate_zone_count": len(zones),
            "climate_risk_map_count": 1,
            "resource_constraint_count": len(resources),
            "protected_land_count": 1,
            "green_infrastructure_count": 1,
            "evacuation_route_count": len(routes),
            "emergency_shelter_count": len(shelters),
            "climate_adaptation_count": 1,
            "transit_oriented_growth_count": 1,
            "risk_mitigation_count": len(hazards),
        })
    elif construct == "climate_zone":
        state.update({"biome_system_count": 1, "weather_system_count": 1, "world_metric_count": 1})
    elif construct == "climate_risk_map":
        state.update({"flood_risk_count": 1 if "flood" in hazards else 0, "fire_risk_count": 1 if "fire" in hazards else 0, "heat_risk_count": 1 if "heat" in hazards else 0, "risk_mitigation_count": len(hazards)})
    elif construct == "flood_risk":
        state.update({"stormwater_system_count": 1, "evacuation_route_count": 1, "hazard_field_count": 1, "world_metric_count": 1})
    elif construct == "fire_risk":
        state.update({"protected_land_count": 1, "evacuation_route_count": 1, "hazard_field_count": 1, "world_metric_count": 1})
    elif construct == "heat_risk":
        state.update({"cooling_corridor_count": 1, "green_infrastructure_count": 1, "hazard_field_count": 1, "world_metric_count": 1})
    elif construct == "resource_constraint":
        state.update({"scarcity_loop_count": 1, "resource_claim_count": 1, "world_metric_count": 1})
    elif construct == "protected_land":
        state.update({"conservation_zone_count": 1, "zoning_rule_count": 1, "world_metric_count": 1})
    elif construct == "green_infrastructure":
        state.update({"protected_land_count": 1, "stormwater_system_count": 1, "cooling_corridor_count": 1})
    elif construct == "stormwater_system":
        state.update({"service_network_count": 1, "resource_flow_count": 1, "flood_risk_count": 1})
    elif construct == "cooling_corridor":
        state.update({"street_hierarchy_count": 1, "heat_risk_count": 1, "public_space_plan_count": 1})
    elif construct == "evacuation_route":
        state.update({"street_hierarchy_count": 1, "transit_node_count": 1, "emergency_shelter_count": 1})
    elif construct == "emergency_shelter":
        state.update({"occupancy_plan_count": 1, "service_coverage_count": 1, "resource_flow_count": 1})
    elif construct == "climate_adaptation":
        state.update({"green_infrastructure_count": 1, "stormwater_system_count": 1, "cooling_corridor_count": 1, "risk_mitigation_count": 1})
    elif construct == "transit_oriented_growth":
        state.update({"transit_node_count": 1, "zoning_district_count": 1, "development_pressure_count": 1, "growth_boundary_count": 1})
    elif construct == "risk_mitigation":
        state.update({"policy_rule_count": 1, "world_metric_count": 1, "climate_adaptation_count": 1})
    return state


def _resilience_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    affordance: dict[str, Any] = {"action": _snake_id(values.get("action") or _RESILIENCE_ACTIONS.get(construct), "compose_resilience")}
    target = _surface_marker_value(values, "target", "hazard", "zone", "service", fallback="")
    if target:
        affordance["target"] = target
    return affordance


def _resilience_child_core_name(name: str, construct: str) -> str:
    if construct in _RESILIENCE_CORE_SUFFIXES:
        return _resilience_core_name(name, construct)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _city_child_core_name(name, construct)
    return _macro_core_name_for_node({"name": name, "values": {"_construct": construct}})


def _expand_resilience_child_macro(node: Mapping[str, Any], construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if construct in _RESILIENCE_CORE_SUFFIXES:
        return _expand_resilience_macro(node, construct=construct)
    if construct in _INFRA_NETWORK_CORE_SUFFIXES:
        return _expand_infrastructure_network_macro(node, construct=construct)
    if construct in _CITY_PLAN_CORE_SUFFIXES:
        return _expand_city_planning_macro(node, construct=construct)
    if construct in _EVOLUTION_CORE_SUFFIXES:
        return _expand_settlement_evolution_macro(node, construct=construct)
    if construct in _OPERATIONAL_CORE_SUFFIXES:
        return _expand_operational_execution_macro(node, construct=construct)
    if construct == "biome_system":
        return _expand_ecology_macro(node, construct=construct)
    if construct == "weather_system":
        return _expand_weather_system_macro(node)
    if construct in {"hazard_field", "world_metric", "resource_flow", "heat_field"}:
        return _expand_simulation_macro(node, construct=construct)
    if construct == "conservation_zone":
        values = deepcopy(dict(_values(node)))
        name = _snake_id(node.get("name"), construct)
        kind = _civil_ecology_kind(values, construct)
        core_values = _macro_child_values(
            values,
            construct=construct,
            position=_macro_center(values),
            scale=_civil_ecology_scale(values, construct),
            state=_civil_ecology_state(values, construct, name, kind),
            tags=[construct, kind, "civilization", "ecology", "macro_generated"],
        )
        core_values["affordances"] = {_snake_id(_CIVIL_ECOLOGY_ACTIONS.get(construct), "run_civil_ecology"): _civil_ecology_affordance(values, construct)}
        return [_macro_scene_object(_civil_ecology_core_name(name, construct), construct, core_values, role=_CIVIL_ECOLOGY_ROLES.get(construct, "environment_structure"), source=node.get("from"))], []
    if construct in {"scarcity_loop", "resource_claim"}:
        return _expand_civil_ecology_macro(node, construct=construct)
    if construct in {"policy_rule", "population_group", "labor_system"}:
        return _expand_culture_macro(node, construct=construct)
    if construct in {"supply_chain", "stockpile"}:
        return _expand_logistics_macro(node, construct=construct)
    return _expand_city_child_macro(node, construct)


def _expand_resilience_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _resilience_kind(values, construct)
    depth = max(0, int(_number(values.get("_resilience_depth"), default=0.0)))
    core_name = _resilience_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_resilience_scale(values, construct),
        state=_resilience_state(values, construct, name, kind),
        tags=[construct, kind, "climate_resilience", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_RESILIENCE_ACTIONS.get(construct), "compose_resilience"): _resilience_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_RESILIENCE_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []
    if depth >= 2:
        return objects, relationships

    def add_child(child_construct: str, suffix: str, updates: Mapping[str, Any], position: Sequence[float], *, relation: str = "supports", description: str | None = None) -> None:
        child_name = f"{name}_{_snake_id(suffix, child_construct)}"
        child_values = deepcopy(values)
        child_values.update(dict(updates))
        child_values["_resilience_depth"] = depth + 1
        if child_construct in _CITY_PLAN_CORE_SUFFIXES:
            child_values["_city_plan_depth"] = max(2, int(_number(child_values.get("_city_plan_depth"), default=0.0)))
        if child_construct in _EVOLUTION_CORE_SUFFIXES:
            child_values["_evolution_depth"] = max(2, int(_number(child_values.get("_evolution_depth"), default=0.0)))
        if child_construct in _OPERATIONAL_CORE_SUFFIXES:
            child_values["_operational_depth"] = max(2, int(_number(child_values.get("_operational_depth"), default=0.0)))
        child_values["position"] = list(position)
        child_role = _RESILIENCE_ROLES.get(child_construct, _CITY_PLAN_ROLES.get(child_construct, _WORLD_PIECE_CONSTRUCTS.get(child_construct, {}).get("role", "environment_structure")))
        child_node = {"node_type": "scene_object", "name": child_name, "role": child_role, "from": node.get("from"), "values": child_values}
        child_objects, child_relationships = _expand_resilience_child_macro(child_node, child_construct)
        objects.extend(child_objects)
        relationships.extend(child_relationships)
        relationships.append(_macro_relationship(name, core_name, _resilience_child_core_name(child_name, child_construct), relation, description or f"{construct} {name} includes {child_construct} {suffix}."))

    if construct == "resilience_plan":
        zones = _resilience_climate_zones(values)
        hazards = _resilience_hazards(values)
        for index, zone in enumerate(zones[:6]):
            add_child("climate_zone", zone, {"climate": zone}, [center[0] + (index - (len(zones) - 1) / 2.0) * 0.50, center[1] + 1.00, center[2] + 0.05], relation="classifies", description=f"Resilience plan {name} classifies climate zone {zone}.")
        add_child("climate_risk_map", "risk_map", {"hazards": hazards}, [center[0] - 0.64, center[1] + 0.36, center[2] + 0.05], relation="maps", description=f"Resilience plan {name} maps climate risks.")
        add_child("green_infrastructure", "green_infrastructure", {"adaptation_measures": _resilience_measures(values)}, [center[0], center[1] + 0.36, center[2] + 0.05], relation="adapts", description=f"Resilience plan {name} adds green infrastructure.")
        add_child("climate_adaptation", "adaptation", {"adaptation_measures": _resilience_measures(values)}, [center[0] + 0.64, center[1] + 0.36, center[2] + 0.05], relation="adapts", description=f"Resilience plan {name} defines adaptation measures.")
        for index, route in enumerate(_resilience_routes(values)[:6]):
            add_child("evacuation_route", route, {"evacuation": route}, [center[0] + (index - 2.5) * 0.34, center[1] - 0.28, center[2] + 0.05], relation="evacuates", description=f"Resilience plan {name} includes evacuation route {route}.")
        for index, shelter in enumerate(_resilience_shelters(values)[:6]):
            add_child("emergency_shelter", shelter, {"shelter": shelter}, [center[0] + (index - 2.5) * 0.34, center[1] - 0.70, center[2] + 0.05], relation="shelters", description=f"Resilience plan {name} includes emergency shelter {shelter}.")
        for index, resource in enumerate(_resilience_resources(values)[:6]):
            add_child("resource_constraint", resource, {"resource": resource}, [center[0] + (index - 2.5) * 0.34, center[1] - 1.08, center[2] + 0.05], relation="constrains", description=f"Resilience plan {name} constrains resource {resource}.")
        add_child("protected_land", "protected_land", {"protected_areas": values.get("protected_areas") or ["riparian_buffer"]}, [center[0] - 0.64, center[1] - 1.46, center[2] + 0.05], relation="protects", description=f"Resilience plan {name} reserves protected land.")
        add_child("transit_oriented_growth", "transit_growth", {"transit_growth": values.get("transit_growth") or "compact_nodes"}, [center[0], center[1] - 1.46, center[2] + 0.05], relation="shapes_growth", description=f"Resilience plan {name} shapes transit-oriented growth.")
        add_child("risk_mitigation", "mitigation", {"hazards": hazards}, [center[0] + 0.64, center[1] - 1.46, center[2] + 0.05], relation="mitigates", description=f"Resilience plan {name} defines mitigation.")

    elif construct == "climate_zone":
        add_child("biome_system", "biome", {"biome_type": kind, "habitats": False, "species": False, "resources": False, "food_web": False, "weather_system": False}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="contains", description=f"Climate zone {name} links biome system.")
        add_child("weather_system", "weather", {"weather_type": values.get("weather_type") or kind}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="drives", description=f"Climate zone {name} drives weather.")
        add_child("world_metric", "climate_metric", {"metric": "climate_stress", "metric_value": values.get("climate_stress") or 0.45}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Climate zone {name} exposes climate stress.")

    elif construct == "climate_risk_map":
        hazards = set(_resilience_hazards(values))
        if "flood" in hazards:
            add_child("flood_risk", "flood", {"flood_level": values.get("flood_level") or 0.35}, [center[0] - 0.36, center[1] + 0.40, center[2] + 0.04], relation="maps", description=f"Climate risk map {name} maps flood risk.")
        if "fire" in hazards:
            add_child("fire_risk", "fire", {"fire_level": values.get("fire_level") or 0.25}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="maps", description=f"Climate risk map {name} maps fire risk.")
        if "heat" in hazards:
            add_child("heat_risk", "heat", {"heat_level": values.get("heat_level") or 0.45}, [center[0] + 0.36, center[1] + 0.40, center[2] + 0.04], relation="maps", description=f"Climate risk map {name} maps heat risk.")
        add_child("risk_mitigation", "mitigation", {"hazards": list(hazards)}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="drives", description=f"Climate risk map {name} drives mitigation.")

    elif construct == "flood_risk":
        add_child("stormwater_system", "stormwater", {"stormwater_capacity": values.get("stormwater_capacity") or 0.7}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="mitigated_by", description=f"Flood risk {name} is mitigated by stormwater.")
        add_child("evacuation_route", "evacuation", {"evacuation": "flood_escape"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="evacuates", description=f"Flood risk {name} creates evacuation route.")
        add_child("hazard_field", "hazard", {"hazard_type": "flood", "intensity": values.get("flood_level") or 0.35}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="marks", description=f"Flood risk {name} marks hazard field.")
        add_child("world_metric", "flood_metric", {"metric": "flood_level", "metric_value": values.get("flood_level") or 0.35}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="reveals", description=f"Flood risk {name} exposes flood level.")

    elif construct == "fire_risk":
        add_child("protected_land", "buffer", {"protection": "firebreak"}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="buffers", description=f"Fire risk {name} creates firebreak land.")
        add_child("evacuation_route", "evacuation", {"evacuation": "fire_escape"}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="evacuates", description=f"Fire risk {name} creates evacuation route.")
        add_child("hazard_field", "hazard", {"hazard_type": "fire", "intensity": values.get("fire_level") or 0.25}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="marks", description=f"Fire risk {name} marks hazard field.")
        add_child("world_metric", "fire_metric", {"metric": "fire_level", "metric_value": values.get("fire_level") or 0.25}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="reveals", description=f"Fire risk {name} exposes fire level.")

    elif construct == "heat_risk":
        add_child("cooling_corridor", "cooling", {"cooling": "shade"}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="cooled_by", description=f"Heat risk {name} creates cooling corridor.")
        add_child("green_infrastructure", "green", {"canopy_cover": values.get("canopy_cover") or 0.32}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="cooled_by", description=f"Heat risk {name} uses green infrastructure.")
        add_child("hazard_field", "hazard", {"hazard_type": "heat", "intensity": values.get("heat_level") or 0.45}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="marks", description=f"Heat risk {name} marks hazard field.")
        add_child("world_metric", "heat_metric", {"metric": "heat_level", "metric_value": values.get("heat_level") or 0.45}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="reveals", description=f"Heat risk {name} exposes heat level.")

    elif construct == "resource_constraint":
        add_child("scarcity_loop", "scarcity", {"resource_type": kind, "demand": values.get("demand") or 1.0, "supply": values.get("supply") or 0.6}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="causes", description=f"Resource constraint {name} creates scarcity.")
        add_child("resource_claim", "claim", {"resource_type": kind}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="claims", description=f"Resource constraint {name} creates resource claim.")
        add_child("world_metric", "constraint_metric", {"metric": "resource_limit", "metric_value": values.get("constraint_level") or 0.55}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Resource constraint {name} exposes limit.")

    elif construct == "protected_land":
        add_child("conservation_zone", "conservation", {"protection_type": kind}, [center[0] - 0.30, center[1] + 0.38, center[2] + 0.04], relation="protects", description=f"Protected land {name} creates conservation zone.")
        add_child("zoning_rule", "zoning", {"zoning": "protected"}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="codifies", description=f"Protected land {name} codifies protection.")
        add_child("world_metric", "protection_metric", {"metric": "protected_area_ratio", "metric_value": values.get("protected_ratio") or 0.18}, [center[0] + 0.30, center[1] + 0.38, center[2] + 0.04], relation="reveals", description=f"Protected land {name} exposes protected ratio.")

    elif construct == "green_infrastructure":
        add_child("protected_land", "protected", {"protected_areas": values.get("protected_areas") or ["greenway"]}, [center[0] - 0.34, center[1] + 0.40, center[2] + 0.04], relation="protects", description=f"Green infrastructure {name} protects greenway.")
        add_child("stormwater_system", "stormwater", {"stormwater_capacity": values.get("stormwater_capacity") or 0.7}, [center[0], center[1] + 0.40, center[2] + 0.04], relation="absorbs", description=f"Green infrastructure {name} absorbs stormwater.")
        add_child("cooling_corridor", "cooling", {"canopy_cover": values.get("canopy_cover") or 0.32}, [center[0] + 0.34, center[1] + 0.40, center[2] + 0.04], relation="cools", description=f"Green infrastructure {name} creates cooling corridor.")

    elif construct == "stormwater_system":
        add_child("service_network", "network", {"services": ["stormwater"]}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="connects", description=f"Stormwater system {name} connects service network.")
        add_child("resource_flow", "water_flow", {"resource_type": "stormwater"}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="routes", description=f"Stormwater system {name} routes water.")
        add_child("flood_risk", "flood", {"flood_level": values.get("flood_level") or 0.25}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="reduces", description=f"Stormwater system {name} reduces flood risk.")

    elif construct == "cooling_corridor":
        add_child("street_hierarchy", "street", {"street_levels": values.get("street_levels") or ["greenway"]}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="follows", description=f"Cooling corridor {name} follows street hierarchy.")
        add_child("heat_risk", "heat", {"heat_level": values.get("heat_level") or 0.35}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="reduces", description=f"Cooling corridor {name} reduces heat risk.")
        add_child("public_space_plan", "public_space", {"public_spaces": values.get("public_spaces") or ["shade_park"]}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="connects", description=f"Cooling corridor {name} connects public spaces.")

    elif construct == "evacuation_route":
        add_child("street_hierarchy", "street", {"street_levels": values.get("street_levels") or ["evacuation_spine"]}, [center[0] - 0.34, center[1] + 0.36, center[2] + 0.04], relation="uses", description=f"Evacuation route {name} uses street hierarchy.")
        add_child("transit_node", "transit", {"transit": values.get("transit") or "evacuation_stop"}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="serves", description=f"Evacuation route {name} serves transit node.")
        add_child("emergency_shelter", "shelter", {"shelter": values.get("shelter") or "safe_hub"}, [center[0] + 0.34, center[1] + 0.36, center[2] + 0.04], relation="leads_to", description=f"Evacuation route {name} leads to shelter.")

    elif construct == "emergency_shelter":
        add_child("occupancy_plan", "occupancy", {"capacity": values.get("capacity") or 120, "occupants": values.get("occupants") or ["evacuees"]}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="houses", description=f"Emergency shelter {name} houses evacuees.")
        add_child("service_coverage", "coverage", {"services": values.get("services") or ["water", "power", "medical"]}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="serves", description=f"Emergency shelter {name} has service coverage.")
        add_child("resource_flow", "supplies", {"resource_type": "shelter_supplies", "goods": values.get("supplies") or ["water", "food", "medical"]}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="supplied_by", description=f"Emergency shelter {name} receives emergency supplies.")

    elif construct == "climate_adaptation":
        add_child("green_infrastructure", "green", {"adaptation_measures": _resilience_measures(values)}, [center[0] - 0.40, center[1] + 0.40, center[2] + 0.04], relation="implements", description=f"Climate adaptation {name} implements green infrastructure.")
        add_child("stormwater_system", "stormwater", {"stormwater_capacity": values.get("stormwater_capacity") or 0.7}, [center[0] - 0.13, center[1] + 0.40, center[2] + 0.04], relation="implements", description=f"Climate adaptation {name} implements stormwater.")
        add_child("cooling_corridor", "cooling", {"canopy_cover": values.get("canopy_cover") or 0.32}, [center[0] + 0.13, center[1] + 0.40, center[2] + 0.04], relation="implements", description=f"Climate adaptation {name} implements cooling corridor.")
        add_child("risk_mitigation", "mitigation", {"mitigation_actions": _resilience_measures(values)}, [center[0] + 0.40, center[1] + 0.40, center[2] + 0.04], relation="mitigates", description=f"Climate adaptation {name} implements mitigation.")

    elif construct == "transit_oriented_growth":
        add_child("transit_node", "transit", {"transit": values.get("transit") or "growth_station"}, [center[0] - 0.34, center[1] + 0.38, center[2] + 0.04], relation="anchors", description=f"Transit-oriented growth {name} anchors transit.")
        add_child("zoning_district", "zoning", {"zoning": values.get("zoning") or "compact_mixed_use"}, [center[0], center[1] + 0.38, center[2] + 0.04], relation="zones", description=f"Transit-oriented growth {name} zones compact district.")
        add_child("development_pressure", "pressure", {"pressure_level": values.get("pressure_level") or 0.6}, [center[0] + 0.34, center[1] + 0.38, center[2] + 0.04], relation="absorbs", description=f"Transit-oriented growth {name} absorbs pressure.")
        add_child("growth_boundary", "boundary", {"boundary_type": "compact_growth"}, [center[0], center[1] - 0.34, center[2] + 0.04], relation="contains", description=f"Transit-oriented growth {name} contains growth.")

    elif construct == "risk_mitigation":
        add_child("policy_rule", "policy", {"policy": kind}, [center[0] - 0.30, center[1] + 0.36, center[2] + 0.04], relation="codifies", description=f"Risk mitigation {name} codifies policy.")
        add_child("world_metric", "mitigation_metric", {"metric": "resilience_score", "metric_value": values.get("resilience_score") or 0.55}, [center[0], center[1] + 0.36, center[2] + 0.04], relation="reveals", description=f"Risk mitigation {name} exposes resilience score.")
        add_child("climate_adaptation", "adaptation", {"adaptation_measures": _resilience_measures(values)}, [center[0] + 0.30, center[1] + 0.36, center[2] + 0.04], relation="implements", description=f"Risk mitigation {name} drives adaptation.")

    return objects, relationships


def _expand_faction_behavior_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "faction_behavior")
    center = _macro_center(values)
    faction = _snake_id(values.get("faction") or values.get("faction_name") or _nested(values, "state", "faction"), name)
    doctrine = _snake_id(values.get("doctrine") or values.get("behavior") or values.get("strategy"), "hold_territory")
    goals = _gameplay_name_list(values, ("goals", "objectives", "priorities"), default=["patrol", "defend", "trade"])
    patrol_count = 0 if _any_disabled(values, "patrols", "routes") else max(0, min(12, _positive_int(values.get("patrols") or values.get("routes"), default=2)))
    squad_count = 0 if _any_disabled(values, "squads", "agents") else max(0, min(12, _positive_int(values.get("squads") or values.get("agent_groups"), default=1)))
    zone_count = 0 if _any_disabled(values, "zones", "control_zones") else max(0, min(8, _positive_int(values.get("zones") or values.get("control_zones"), default=1)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_faction_behavior_core"
    core_values = _macro_child_values(
        values,
        construct="faction_behavior",
        position=center,
        scale=[max(2.0, _number(values.get("width"), default=8.0)), max(2.0, _number(values.get("depth"), default=6.0)), 0.30],
        state={
            "faction_behavior": name,
            "faction": faction,
            "doctrine": doctrine,
            "goals": goals,
            "goal_count": len(goals),
            "patrol_count": patrol_count,
            "squad_count": squad_count,
            "control_zone_count": zone_count,
            "hostility": _snake_id(values.get("hostility") or values.get("stance"), "neutral"),
            "allies": _gameplay_name_list(values, ("allies", "friendly_to"), default=[]),
            "rivals": _gameplay_name_list(values, ("rivals", "hostile_to", "enemies"), default=[]),
            "object_archetype": "faction_behavior",
            "setpiece_layout": "behavior_system",
            "structure_count": 1,
            "road_segment_count": max(1, patrol_count),
            "prop_count": max(1, len(goals)),
        },
        tags=["faction_behavior", faction, doctrine, "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "faction_behavior", core_values, role="environment_structure", source=node.get("from")))

    for index, goal in enumerate(goals):
        objective_values = deepcopy(values)
        objective_values["position"] = [center[0] + (index - (len(goals) - 1) / 2.0) * 1.8, center[1] + 1.8, center[2] + 0.04]
        objective_values["objective_type"] = goal
        objective_values["targets"] = 1
        objective_values["markers"] = False
        objective_node = {"node_type": "scene_object", "name": f"{name}_{goal}_doctrine", "role": "interactive", "from": node.get("from"), "values": objective_values}
        objective_objects, objective_relationships = _expand_objective_macro(objective_node)
        objects.extend(objective_objects)
        relationships.extend(objective_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{goal}_doctrine_objective_core", "contains", f"Faction behavior {name} includes goal {goal}."))

    for index in range(zone_count):
        zone_values = deepcopy(values)
        zone_values["position"] = [center[0] - 3.0 + index * 2.4, center[1] - 1.8, center[2] + 0.04]
        zone_values["faction"] = faction
        zone_values["control_points"] = _positive_int(values.get("control_points"), default=2)
        zone_values["patrols"] = False
        zone_node = {"node_type": "scene_object", "name": f"{name}_zone_{index + 1:02d}", "role": "environment_structure", "from": node.get("from"), "values": zone_values}
        zone_objects, zone_relationships = _expand_control_zone_macro(zone_node)
        objects.extend(zone_objects)
        relationships.extend(zone_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_zone_{index + 1:02d}_control_core", "contains", f"Faction behavior {name} controls zone {index + 1}."))

    for index in range(patrol_count):
        patrol_values = deepcopy(values)
        patrol_values["position"] = [center[0], center[1] + 3.0 + index * 0.9, center[2] + 0.03]
        patrol_values["faction"] = faction
        patrol_values["waypoints"] = _positive_int(values.get("waypoints") or values.get("patrol_points"), default=4)
        patrol_node = {"node_type": "scene_object", "name": f"{name}_patrol_{index + 1:02d}", "role": "navigation", "from": node.get("from"), "values": patrol_values}
        patrol_objects, patrol_relationships = _expand_patrol_route_macro(patrol_node)
        objects.extend(patrol_objects)
        relationships.extend(patrol_relationships)
        relationships.append(_macro_relationship(name, f"{name}_patrol_{index + 1:02d}_patrol_core", core_name, "supports", f"Faction patrol supports behavior {name}."))

    for index in range(squad_count):
        crowd_values = deepcopy(values)
        crowd_values["position"] = [center[0] + 3.0, center[1] - 1.6 + index * 1.6, center[2] + 0.05]
        crowd_values["faction"] = faction
        crowd_values["crowd_type"] = "squad"
        crowd_values["agents"] = _positive_int(values.get("agents_per_squad") or values.get("squad_size"), default=4)
        crowd_values["roles"] = _gameplay_name_list(values, ("squad_roles", "roles"), default=["guard", "scout", "soldier"])
        crowd_values["schedule"] = False
        crowd_node = {"node_type": "scene_object", "name": f"{name}_squad_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": crowd_values}
        crowd_objects, crowd_relationships = _expand_crowd_macro(crowd_node)
        objects.extend(crowd_objects)
        relationships.extend(crowd_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_squad_{index + 1:02d}_crowd_core", "contains", f"Faction behavior {name} includes squad {index + 1}."))

    return objects, relationships


def _expand_behavior_graph_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "behavior_graph")
    center = _macro_center(values)
    graph_kind = _snake_id(values.get("graph_type") or values.get("simulation") or values.get("type"), "world_behavior")
    factions = _gameplay_name_list(values, ("factions", "faction_names"), default=["neutral"])
    agent_count = 0 if _any_disabled(values, "agents", "crowds") else max(0, min(96, _positive_int(values.get("agents") or values.get("npc_count"), default=6)))
    ecology_count = 0 if _any_disabled(values, "ecologies", "spawn_ecologies") else max(0, min(8, _positive_int(values.get("ecologies") or values.get("spawn_ecologies"), default=1)))
    loops = _gameplay_name_list(values, ("loops", "systems", "simulation_loops"), default=["daily_routine", "alert_response", "resource_tick"])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_behavior_graph_core"
    core_values = _macro_child_values(
        values,
        construct="behavior_graph",
        position=center,
        scale=[max(4.0, _number(values.get("width"), default=14.0)), max(4.0, _number(values.get("depth"), default=10.0)), 0.32],
        state={
            "behavior_graph": name,
            "graph_type": graph_kind,
            "factions": factions,
            "faction_count": len(factions),
            "agent_count": agent_count,
            "ecology_count": ecology_count,
            "loops": loops,
            "loop_count": len(loops),
            "tick_rate": _number(values.get("tick_rate") or values.get("simulation_rate"), default=1.0),
            "object_archetype": "behavior_graph",
            "setpiece_layout": "world_simulation",
            "structure_count": max(1, len(factions)),
            "road_segment_count": max(1, len(loops)),
            "prop_count": max(1, agent_count),
        },
        tags=["behavior_graph", graph_kind, "world_simulation", "behavior", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "behavior_graph", core_values, role="environment_structure", source=node.get("from")))

    for index, faction in enumerate(factions):
        faction_values = deepcopy(values)
        faction_values["position"] = [center[0] - 4.0 + index * 3.0, center[1] + 2.6, center[2] + 0.05]
        faction_values["faction"] = faction
        faction_values["patrols"] = _positive_int(values.get("patrols_per_faction") or values.get("patrols"), default=1)
        faction_values["squads"] = _positive_int(values.get("squads_per_faction") or values.get("squads"), default=1)
        faction_node = {"node_type": "scene_object", "name": f"{name}_{faction}_behavior", "role": "environment_structure", "from": node.get("from"), "values": faction_values}
        faction_objects, faction_relationships = _expand_faction_behavior_macro(faction_node)
        objects.extend(faction_objects)
        relationships.extend(faction_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{faction}_behavior_faction_behavior_core", "contains", f"Behavior graph {name} contains faction behavior {faction}."))

    if agent_count:
        crowd_values = deepcopy(values)
        crowd_values["position"] = [center[0], center[1] - 2.2, center[2] + 0.05]
        crowd_values["crowd_type"] = "simulation_agents"
        crowd_values["agents"] = agent_count
        crowd_values["roles"] = _gameplay_name_list(values, ("agent_roles", "roles"), default=["civilian", "worker", "guard"])
        crowd_node = {"node_type": "scene_object", "name": f"{name}_agents", "role": "interactive", "from": node.get("from"), "values": crowd_values}
        crowd_objects, crowd_relationships = _expand_crowd_macro(crowd_node)
        objects.extend(crowd_objects)
        relationships.extend(crowd_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_agents_crowd_core", "contains", f"Behavior graph {name} contains simulated agents."))

    for index in range(ecology_count):
        ecology_values = deepcopy(values)
        ecology_values["position"] = [center[0] + 4.0, center[1] - 2.2 + index * 1.8, center[2] + 0.04]
        ecology_values["species"] = _gameplay_name_list(values, ("species", "ecology_species"), default=["wildlife"])
        ecology_node = {"node_type": "scene_object", "name": f"{name}_ecology_{index + 1:02d}", "role": "environment_structure", "from": node.get("from"), "values": ecology_values}
        ecology_objects, ecology_relationships = _expand_spawn_ecology_macro(ecology_node)
        objects.extend(ecology_objects)
        relationships.extend(ecology_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_ecology_{index + 1:02d}_ecology_core", "contains", f"Behavior graph {name} contains spawn ecology {index + 1}."))

    for index, loop in enumerate(loops):
        schedule_values = deepcopy(values)
        schedule_values["position"] = [center[0] + (index - (len(loops) - 1) / 2.0) * 1.6, center[1], center[2] + 0.05]
        schedule_values["activities"] = [loop]
        schedule_values["actor"] = core_name
        schedule_node = {"node_type": "scene_object", "name": f"{name}_{loop}_loop", "role": "narrative_clue", "from": node.get("from"), "values": schedule_values}
        schedule_objects, schedule_relationships = _expand_schedule_macro(schedule_node)
        objects.extend(schedule_objects)
        relationships.extend(schedule_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_{loop}_loop_schedule_core", "supports", f"Behavior graph {name} runs loop {loop}."))

    return objects, relationships


