def _mission_rule_kind(values: Mapping[str, Any], construct: str) -> str:
    return _surface_marker_value(values, *_MISSION_RULE_KIND_KEYS.get(construct, ("type",)), fallback=_MISSION_RULE_KIND_DEFAULTS.get(construct, construct))


def _mission_rule_core_name(name: str, construct: str) -> str:
    return f"{name}_{_MISSION_RULE_CORE_SUFFIXES.get(construct, 'rule_core')}"


def _mission_rule_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct in {"mission", "objective_chain", "progression_track"}:
        return [max(1.0, _number(values.get("width"), default=2.4)), max(0.8, _number(values.get("depth"), default=1.4)), 0.22]
    if construct in {"reward_table", "loot_table", "shop", "vendor", "crafting_station"}:
        return [max(0.8, _number(values.get("width"), default=1.6)), max(0.5, _number(values.get("depth"), default=1.0)), 0.26]
    if construct in {"success_condition", "failure_condition", "gameplay_rule", "unlock_rule", "reputation_rule"}:
        return [0.70, 0.30, 0.12]
    if construct == "recipe":
        return [0.55, 0.24, 0.10]
    if construct in {"inventory_slot", "currency"}:
        return [0.34, 0.22, 0.14]
    return [0.50, 0.30, 0.14]


def _mission_steps(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("objectives", "objective_steps", "steps", "tasks"), default=["discover", "complete", "return"])


def _mission_rewards(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("rewards", "reward_items", "outputs"), default=["xp", "credits"])


def _mission_items(values: Mapping[str, Any], *, default: Sequence[str]) -> list[str]:
    return _gameplay_name_list(values, ("items", "stock", "loot", "entries"), default=default)


def _mission_rule_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    action = _MISSION_RULE_ACTIONS.get(construct, "apply_gameplay_rule")
    state: dict[str, Any] = {
        construct: name,
        "gameplay_rule_construct": construct,
        "gameplay_rule_kind": kind,
        "action": _snake_id(values.get("action") or action, action),
        f"{construct}_count": 1,
        "gameplay_rule_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "mission_rule_system",
        "requires": _string(values.get("requires"), default=""),
        "enabled": not _disabled(values.get("enabled", True)),
    }
    if construct == "mission":
        steps = _mission_steps(values)
        rewards = _mission_rewards(values)
        state.update(
            {
                "mission_type": kind,
                "objective_count": len(steps),
                "objective_chain_count": 1,
                "reward_count": len(rewards),
                "reward_table_count": 1 if rewards else 0,
                "success_condition_count": 1,
                "failure_condition_count": 0 if _any_disabled(values, "failure", "failure_condition") else 1,
                "repeatable": not _disabled(values.get("repeatable", False)),
                "tracked": not _disabled(values.get("tracked", True)),
                "level": _positive_int(values.get("level"), default=1),
                "xp": _number(values.get("xp"), default=max(25.0, len(steps) * 25.0)),
            }
        )
    elif construct == "objective_chain":
        steps = _mission_steps(values)
        state.update(
            {
                "chain_type": kind,
                "objective_count": len(steps),
                "steps": steps,
                "ordered": not _disabled(values.get("ordered", True)),
                "parallel": not _disabled(values.get("parallel", False)),
            }
        )
    elif construct in {"success_condition", "failure_condition"}:
        conditions = _gameplay_name_list(values, ("conditions", "checks", "requires"), default=["complete_objectives"] if construct == "success_condition" else ["timer_expired"])
        state.update(
            {
                "condition_type": kind,
                "conditions": conditions,
                "required_count": max(1, min(len(conditions), _positive_int(values.get("required_count") or values.get("required"), default=len(conditions)))),
                "threshold": _number(values.get("threshold"), default=1.0),
                "timer_seconds": _number(values.get("timer") or values.get("timer_seconds"), default=0.0),
                "emits": _gameplay_name_list(values, ("emits", "events"), default=[]),
            }
        )
    elif construct == "reward_table":
        rewards = _mission_rewards(values)
        state.update(
            {
                "reward_type": kind,
                "rewards": rewards,
                "reward_count": len(rewards),
                "loot_table_count": 0 if _any_disabled(values, "loot", "loot_table") else 1,
                "currency_type": _surface_marker_value(values, "currency_type", "currency", fallback="credits"),
                "amount": _number(values.get("amount") or values.get("currency_amount"), default=100.0),
                "xp": _number(values.get("xp"), default=50.0),
                "reputation": _surface_marker_value(values, "reputation", "faction", fallback=""),
                "delta": _number(values.get("delta") or values.get("reputation_delta"), default=0.0),
            }
        )
    elif construct == "loot_table":
        items = _mission_items(values, default=["common_loot", "rare_loot"])
        state.update(
            {
                "loot_type": kind,
                "items": items,
                "loot_count": len(items),
                "rolls": max(1, min(32, _positive_int(values.get("rolls") or values.get("roll_count"), default=1))),
                "rarity": _surface_marker_value(values, "rarity", fallback="common"),
                "weights": _string_list(values.get("weights")),
            }
        )
    elif construct == "inventory_slot":
        state.update(
            {
                "slot_type": kind,
                "item": _surface_marker_value(values, "item", "item_type", fallback=kind),
                "capacity": max(1, min(999, _positive_int(values.get("capacity") or values.get("stack"), default=1))),
                "equipped": not _disabled(values.get("equipped", False)),
                "stackable": not _disabled(values.get("stackable", True)),
            }
        )
    elif construct == "crafting_station":
        recipes = _gameplay_name_list(values, ("recipes", "recipe_list"), default=["basic_recipe"])
        state.update(
            {
                "station_type": kind,
                "recipes": recipes,
                "recipe_count": len(recipes),
                "input_slots": max(1, min(16, _positive_int(values.get("input_slots") or values.get("inputs"), default=2))),
                "output_slots": max(1, min(8, _positive_int(values.get("output_slots") or values.get("outputs"), default=1))),
                "craft_time": _number(values.get("craft_time") or values.get("duration"), default=2.0),
            }
        )
    elif construct == "recipe":
        inputs = _gameplay_name_list(values, ("inputs", "ingredients"), default=["material"])
        outputs = _gameplay_name_list(values, ("outputs", "products", "items"), default=[kind])
        state.update(
            {
                "recipe_type": kind,
                "inputs": inputs,
                "outputs": outputs,
                "input_count": len(inputs),
                "output_count": len(outputs),
                "station": _snake_id(values.get("station") or values.get("crafting_station"), ""),
                "craft_time": _number(values.get("craft_time") or values.get("duration"), default=2.0),
                "currency_cost": _number(values.get("cost") or values.get("currency_cost"), default=0.0),
            }
        )
    elif construct in {"shop", "vendor"}:
        stock = _mission_items(values, default=["supply", "upgrade", "consumable"])
        state.update(
            {
                f"{construct}_type": kind,
                "stock": stock,
                "stock_count": len(stock),
                "currency_type": _surface_marker_value(values, "currency_type", "currency", fallback="credits"),
                "prices": _string_list(values.get("prices")),
                "discount": _number(values.get("discount"), default=0.0),
                "faction": _snake_id(values.get("faction"), ""),
                "reputation_required": _number(values.get("reputation_required"), default=0.0),
            }
        )
    elif construct == "currency":
        state.update(
            {
                "currency_type": kind,
                "amount": _number(values.get("amount"), default=1.0),
                "wallet_cap": _number(values.get("wallet_cap") or values.get("cap"), default=0.0),
                "exchange_rate": _number(values.get("exchange_rate"), default=1.0),
            }
        )
    elif construct == "reputation_rule":
        state.update(
            {
                "reputation_type": kind,
                "faction": _snake_id(values.get("faction") or values.get("group"), "neutral"),
                "delta": _number(values.get("delta") or values.get("amount"), default=1.0),
                "threshold": _number(values.get("threshold"), default=0.0),
                "event": _surface_marker_value(values, "event", "trigger", fallback="mission_event"),
                "unlocks": _gameplay_name_list(values, ("unlocks", "rewards"), default=[]),
            }
        )
    elif construct == "unlock_rule":
        requirements = _gameplay_name_list(values, ("requirements", "requires", "conditions"), default=["requirement"])
        unlocks = _gameplay_name_list(values, ("unlocks", "targets", "rewards"), default=["unlock"])
        state.update(
            {
                "unlock_type": kind,
                "requirements": requirements,
                "requirement_count": len(requirements),
                "unlocks": unlocks,
                "unlock_count": len(unlocks),
                "consumes": not _disabled(values.get("consumes", False)),
                "condition": _surface_marker_value(values, "condition", fallback="all"),
            }
        )
    elif construct == "progression_track":
        levels = _gameplay_name_list(values, ("levels", "tiers", "ranks"), default=["level_1", "level_2", "level_3"])
        state.update(
            {
                "track_type": kind,
                "levels": levels,
                "level_count": len(levels),
                "xp": _number(values.get("xp"), default=0.0),
                "thresholds": _string_list(values.get("thresholds")),
                "unlocks": _gameplay_name_list(values, ("unlocks", "rewards"), default=[]),
            }
        )
    elif construct == "gameplay_rule":
        state.update(
            {
                "rule_type": kind,
                "rule": _string(values.get("rule"), default=name),
                "trigger": _surface_marker_value(values, "trigger", fallback="manual"),
                "condition": _string(values.get("condition"), default=""),
                "effect": _string(values.get("effect"), default=""),
                "priority": _number(values.get("priority"), default=1.0),
            }
        )
    return state


def _mission_rule_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    action = _snake_id(values.get("action") or _MISSION_RULE_ACTIONS.get(construct), "apply_gameplay_rule")
    affordance: dict[str, Any] = {"action": action}
    if values.get("requires"):
        affordance["requires"] = _string(values.get("requires"))
    return affordance


def _expand_mission_rule_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _mission_rule_kind(values, construct)
    role = _MISSION_RULE_ROLES.get(construct, "narrative_clue")
    core_name = _mission_rule_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_mission_rule_scale(values, construct),
        state=_mission_rule_state(values, construct, name, kind),
        tags=[construct, kind, "gameplay", "rule_system", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_MISSION_RULE_ACTIONS.get(construct), "apply_rule"): _mission_rule_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=role, source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    if construct == "mission":
        if not _any_disabled(values, "objectives", "objective_chain"):
            chain_values = deepcopy(values)
            chain_values["position"] = [center[0], center[1] + 1.4, center[2] + 0.04]
            chain_node = {"node_type": "scene_object", "name": f"{name}_objectives", "role": "narrative_clue", "from": node.get("from"), "values": chain_values}
            chain_objects, chain_relationships = _expand_mission_rule_macro(chain_node, construct="objective_chain")
            objects.extend(chain_objects)
            relationships.extend(chain_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_objectives_objective_chain_core", "contains", f"Mission {name} contains objective chain."))
        if not _any_disabled(values, "reward", "rewards", "reward_table"):
            reward_values = deepcopy(values)
            reward_values["position"] = [center[0] + 1.4, center[1] - 1.0, center[2] + 0.04]
            reward_node = {"node_type": "scene_object", "name": f"{name}_rewards", "role": "interactive", "from": node.get("from"), "values": reward_values}
            reward_objects, reward_relationships = _expand_mission_rule_macro(reward_node, construct="reward_table")
            objects.extend(reward_objects)
            relationships.extend(reward_relationships)
            relationships.append(_macro_relationship(name, f"{name}_rewards_reward_table_core", core_name, "depends_on", f"Mission rewards depend on mission {name}."))
        for condition_construct, offset_x in (("success_condition", -1.2), ("failure_condition", 1.2)):
            if _any_disabled(values, "failure", "failure_condition") and condition_construct == "failure_condition":
                continue
            condition_values = deepcopy(values)
            condition_values["position"] = [center[0] + offset_x, center[1] - 1.2, center[2] + 0.04]
            condition_node = {"node_type": "scene_object", "name": f"{name}_{condition_construct}", "role": "narrative_clue", "from": node.get("from"), "values": condition_values}
            condition_objects, condition_relationships = _expand_mission_rule_macro(condition_node, construct=condition_construct)
            objects.extend(condition_objects)
            relationships.extend(condition_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{condition_construct}_{condition_construct}_core", "depends_on", f"Mission {name} evaluates {condition_construct}."))

    elif construct == "objective_chain":
        steps = _mission_steps(values)
        previous = ""
        for index, step in enumerate(steps[:32]):
            objective_values = deepcopy(values)
            objective_values["position"] = [center[0] + (index - (len(steps) - 1) / 2.0) * 1.4, center[1] + 0.8, center[2] + 0.04]
            objective_values["objective_type"] = step
            objective_values["order"] = index + 1
            objective_values["rewards"] = False
            objective_node = {"node_type": "scene_object", "name": f"{name}_{index + 1:02d}_{step}", "role": "interactive", "from": node.get("from"), "values": objective_values}
            objective_objects, objective_relationships = _expand_objective_macro(objective_node)
            objects.extend(objective_objects)
            relationships.extend(objective_relationships)
            objective_core = f"{name}_{index + 1:02d}_{step}_objective_core"
            relationships.append(_macro_relationship(name, core_name, objective_core, "contains", f"Objective chain {name} contains {step}."))
            if previous:
                relationships.append(_macro_relationship(name, objective_core, previous, "depends_on", f"Objective {step} depends on previous objective."))
                relationships.append(_macro_relationship(name, previous, objective_core, "routes_to", f"Objective chain {name} advances to {step}."))
            previous = objective_core

    elif construct == "reward_table":
        if not _any_disabled(values, "currency", "currency_reward"):
            currency_values = deepcopy(values)
            currency_values["position"] = [center[0] - 0.55, center[1] + 0.65, center[2] + 0.04]
            currency_node = {"node_type": "scene_object", "name": f"{name}_currency", "role": "interactive", "from": node.get("from"), "values": currency_values}
            currency_objects, currency_relationships = _expand_mission_rule_macro(currency_node, construct="currency")
            objects.extend(currency_objects)
            relationships.extend(currency_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_currency_currency_core", "contains", f"Reward table {name} contains currency reward."))
        if not _any_disabled(values, "loot", "loot_table"):
            loot_values = deepcopy(values)
            loot_values["position"] = [center[0] + 0.55, center[1] + 0.65, center[2] + 0.04]
            loot_node = {"node_type": "scene_object", "name": f"{name}_loot", "role": "interactive", "from": node.get("from"), "values": loot_values}
            loot_objects, loot_relationships = _expand_mission_rule_macro(loot_node, construct="loot_table")
            objects.extend(loot_objects)
            relationships.extend(loot_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_loot_loot_table_core", "contains", f"Reward table {name} contains loot table."))
        if values.get("reputation") or values.get("faction"):
            rep_values = deepcopy(values)
            rep_values["position"] = [center[0], center[1] - 0.65, center[2] + 0.04]
            rep_node = {"node_type": "scene_object", "name": f"{name}_reputation", "role": "narrative_clue", "from": node.get("from"), "values": rep_values}
            rep_objects, rep_relationships = _expand_mission_rule_macro(rep_node, construct="reputation_rule")
            objects.extend(rep_objects)
            relationships.extend(rep_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_reputation_reputation_rule_core", "supports", f"Reward table {name} modifies reputation."))

    elif construct == "loot_table":
        items = _mission_items(values, default=["common_loot", "rare_loot"])
        for index, item in enumerate(items[:24]):
            slot_values = deepcopy(values)
            slot_values["position"] = [center[0] + (index - (len(items) - 1) / 2.0) * 0.5, center[1] + 0.6, center[2] + 0.04]
            slot_values["item"] = item
            slot_values["slot_type"] = "loot"
            slot_node = {"node_type": "scene_object", "name": f"{name}_{item}_slot", "role": "interactive", "from": node.get("from"), "values": slot_values}
            slot_objects, slot_relationships = _expand_mission_rule_macro(slot_node, construct="inventory_slot")
            objects.extend(slot_objects)
            relationships.extend(slot_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{item}_slot_inventory_slot_core", "contains", f"Loot table {name} can yield {item}."))

    elif construct == "crafting_station":
        recipes = _gameplay_name_list(values, ("recipes", "recipe_list"), default=["basic_recipe"])
        for index, recipe in enumerate(recipes[:16]):
            recipe_values = deepcopy(values)
            recipe_values["position"] = [center[0] + (index - (len(recipes) - 1) / 2.0) * 0.65, center[1] + 0.7, center[2] + 0.04]
            recipe_values["recipe_type"] = recipe
            recipe_values["station"] = core_name
            recipe_node = {"node_type": "scene_object", "name": f"{name}_{recipe}", "role": "interactive", "from": node.get("from"), "values": recipe_values}
            recipe_objects, recipe_relationships = _expand_mission_rule_macro(recipe_node, construct="recipe")
            objects.extend(recipe_objects)
            relationships.extend(recipe_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{recipe}_recipe_core", "contains", f"Crafting station {name} contains recipe {recipe}."))
        if not _any_disabled(values, "panel", "control_panel"):
            panel_values = deepcopy(values)
            panel_values["position"] = [center[0], center[1] - 0.75, center[2] + 0.04]
            panel_values["controls"] = recipes[:6]
            panel_values["target"] = core_name
            panel_node = {"node_type": "scene_object", "name": f"{name}_panel", "role": "interactive", "from": node.get("from"), "values": panel_values}
            panel_objects, panel_relationships = _expand_interaction_ui_macro(panel_node, construct="control_panel")
            objects.extend(panel_objects)
            relationships.extend(panel_relationships)
            relationships.append(_macro_relationship(name, f"{name}_panel_control_panel_core", core_name, "supports", f"Crafting station {name} exposes a control panel."))

    elif construct in {"shop", "vendor"}:
        stock = _mission_items(values, default=["supply", "upgrade", "consumable"])
        if construct == "vendor" and not _any_disabled(values, "shop", "stock"):
            shop_values = deepcopy(values)
            shop_values["position"] = [center[0] + 0.9, center[1], center[2] + 0.04]
            shop_node = {"node_type": "scene_object", "name": f"{name}_shop", "role": "interactive", "from": node.get("from"), "values": shop_values}
            shop_objects, shop_relationships = _expand_mission_rule_macro(shop_node, construct="shop")
            objects.extend(shop_objects)
            relationships.extend(shop_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_shop_shop_core", "contains", f"Vendor {name} owns shop stock."))
        elif construct == "shop":
            for index, item in enumerate(stock[:24]):
                slot_values = deepcopy(values)
                slot_values["position"] = [center[0] + (index - (len(stock) - 1) / 2.0) * 0.45, center[1] + 0.65, center[2] + 0.04]
                slot_values["item"] = item
                slot_values["slot_type"] = "shop_stock"
                slot_node = {"node_type": "scene_object", "name": f"{name}_{item}_stock", "role": "interactive", "from": node.get("from"), "values": slot_values}
                slot_objects, slot_relationships = _expand_mission_rule_macro(slot_node, construct="inventory_slot")
                objects.extend(slot_objects)
                relationships.extend(slot_relationships)
                relationships.append(_macro_relationship(name, core_name, f"{name}_{item}_stock_inventory_slot_core", "contains", f"Shop {name} stocks {item}."))

    elif construct == "progression_track":
        unlocks = _gameplay_name_list(values, ("unlocks", "rewards"), default=["rank_reward"])
        for index, unlock in enumerate(unlocks[:24]):
            unlock_values = deepcopy(values)
            unlock_values["position"] = [center[0] + (index - (len(unlocks) - 1) / 2.0) * 0.65, center[1] + 0.75, center[2] + 0.04]
            unlock_values["unlocks"] = [unlock]
            unlock_values["requirements"] = [f"level_{index + 1}"]
            unlock_node = {"node_type": "scene_object", "name": f"{name}_{unlock}_unlock", "role": "interactive", "from": node.get("from"), "values": unlock_values}
            unlock_objects, unlock_relationships = _expand_mission_rule_macro(unlock_node, construct="unlock_rule")
            objects.extend(unlock_objects)
            relationships.extend(unlock_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{unlock}_unlock_unlock_rule_core", "contains", f"Progression track {name} unlocks {unlock}."))

    elif construct == "unlock_rule" and not _any_disabled(values, "success_condition", "condition_node"):
        condition_values = deepcopy(values)
        condition_values["position"] = [center[0], center[1] - 0.55, center[2] + 0.04]
        condition_values["conditions"] = _gameplay_name_list(values, ("requirements", "requires", "conditions"), default=["requirement"])
        condition_node = {"node_type": "scene_object", "name": f"{name}_condition", "role": "narrative_clue", "from": node.get("from"), "values": condition_values}
        condition_objects, condition_relationships = _expand_mission_rule_macro(condition_node, construct="success_condition")
        objects.extend(condition_objects)
        relationships.extend(condition_relationships)
        relationships.append(_macro_relationship(name, f"{name}_condition_success_condition_core", core_name, "depends_on", f"Unlock rule {name} waits for requirements."))

    elif construct == "recipe" and not _any_disabled(values, "outputs", "output_slots"):
        outputs = _gameplay_name_list(values, ("outputs", "products", "items"), default=[kind])
        for index, output in enumerate(outputs[:8]):
            slot_values = deepcopy(values)
            slot_values["position"] = [center[0] + (index - (len(outputs) - 1) / 2.0) * 0.45, center[1] + 0.5, center[2] + 0.04]
            slot_values["item"] = output
            slot_values["slot_type"] = "crafted_output"
            slot_node = {"node_type": "scene_object", "name": f"{name}_{output}_output", "role": "interactive", "from": node.get("from"), "values": slot_values}
            slot_objects, slot_relationships = _expand_mission_rule_macro(slot_node, construct="inventory_slot")
            objects.extend(slot_objects)
            relationships.extend(slot_relationships)
            relationships.append(_macro_relationship(name, core_name, f"{name}_{output}_output_inventory_slot_core", "reveals", f"Recipe {name} outputs {output}."))

    return objects, relationships


