def _director_kind(values: Mapping[str, Any], construct: str) -> str:
    return _surface_marker_value(values, *_DIRECTOR_KIND_KEYS.get(construct, ("type",)), fallback=_DIRECTOR_KIND_DEFAULTS.get(construct, construct))


def _director_core_name(name: str, construct: str) -> str:
    return f"{name}_{_DIRECTOR_CORE_SUFFIXES.get(construct, 'director_core')}"


def _director_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct in {"director", "encounter_director"}:
        return [max(1.2, _number(values.get("width"), default=2.6)), max(0.8, _number(values.get("depth"), default=1.6)), 0.24]
    if construct in {"pacing_curve", "threat_budget", "adaptive_difficulty"}:
        return [0.95, 0.32, 0.12]
    if construct in {"spawn_wave", "combat_phase", "stealth_phase", "threat_zone"}:
        return [max(0.8, _number(values.get("width") or values.get("radius"), default=1.5)), max(0.6, _number(values.get("depth") or values.get("radius"), default=1.1)), 0.18]
    if construct == "reinforcement_route":
        return [max(1.2, _number(values.get("length") or values.get("width"), default=3.0)), 0.16, 0.10]
    return [0.50, 0.26, 0.12]


def _director_intents(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("director_intents", "intents", "intent"), default=["pressure", "relief", "surprise"])


def _director_waves(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("spawn_waves", "waves", "wave_types"), default=["probe", "assault", "reinforce"])


def _director_phases(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("phases", "combat_phases", "stealth_phases"), default=["stealth", "contact", "combat"])


def _director_beats(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("beats", "encounter_beats", "pacing_beats"), default=["setup", "pressure", "release"])


def _director_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    state: dict[str, Any] = {
        construct: name,
        "director_construct": construct,
        "director_kind": kind,
        "action": _snake_id(values.get("action") or _DIRECTOR_ACTIONS.get(construct), "run_director"),
        f"{construct}_count": 1,
        "director_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "encounter_director_system",
        "enabled": not _disabled(values.get("enabled", True)),
        "priority": _number(values.get("priority"), default=1.0),
    }
    if construct in {"director", "encounter_director"}:
        intents = _director_intents(values)
        waves = _director_waves(values)
        phases = _director_phases(values)
        state.update(
            {
                "director_type": kind,
                "intents": intents,
                "director_intent_count": len(intents),
                "pacing_curve_count": 1,
                "threat_budget_count": 1,
                "spawn_wave_count": len(waves),
                "wave_count": len(waves),
                "phase_count": len(phases),
                "combat_phase_count": sum(1 for phase in phases if "combat" in phase or phase in {"contact", "assault", "engage"}),
                "stealth_phase_count": sum(1 for phase in phases if "stealth" in phase or phase in {"infiltrate", "sneak"}),
                "escalation_rule_count": 1,
                "adaptive_difficulty_count": 1,
                "encounter_beat_count": len(_director_beats(values)),
                "director_signal_count": max(1, len(intents)),
                "threat_zone_count": max(1, _positive_int(values.get("threat_zones") or values.get("threat_zone_count"), default=1)),
                "difficulty": _number(values.get("difficulty"), default=1.0),
                "tension_min": _number(values.get("tension_min"), default=0.2),
                "tension_max": _number(values.get("tension_max"), default=1.0),
                "max_active": _positive_int(values.get("max_active"), default=8),
            }
        )
    elif construct == "director_intent":
        state.update(
            {
                "intent": kind,
                "goal": _surface_marker_value(values, "goal", fallback=kind),
                "target": _snake_id(values.get("target") or values.get("focus"), ""),
                "pressure": _number(values.get("pressure"), default=0.5),
                "relief": _number(values.get("relief"), default=0.0),
                "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=20.0),
            }
        )
    elif construct == "pacing_curve":
        beats = _director_beats(values)
        state.update(
            {
                "pacing": kind,
                "beats": beats,
                "beat_count": len(beats),
                "tension_min": _number(values.get("tension_min"), default=0.15),
                "tension_max": _number(values.get("tension_max"), default=1.0),
                "relief": _number(values.get("relief"), default=0.25),
                "pressure": _number(values.get("pressure"), default=0.65),
                "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=max(30.0, len(beats) * 12.0)),
            }
        )
    elif construct in {"threat_budget", "spawn_budget"}:
        enemies = _gameplay_name_list(values, ("enemy_types", "actors", "spawns"), default=["grunt", "elite"])
        state.update(
            {
                "budget_type": kind,
                "budget": _number(values.get("budget") or values.get("threat_budget"), default=10.0),
                "max_active": _positive_int(values.get("max_active"), default=6),
                "reserve": _number(values.get("reserve"), default=0.25),
                "enemy_types": enemies,
                "enemy_type_count": len(enemies),
                "spawn_budget_count": 1 if construct == "threat_budget" else 0,
            }
        )
    elif construct == "spawn_wave":
        enemies = _gameplay_name_list(values, ("enemy_types", "actors", "spawns"), default=["grunt"])
        state.update(
            {
                "wave_type": kind,
                "wave_index": _positive_int(values.get("wave_index") or values.get("order"), default=1),
                "spawn_count": max(1, min(96, _positive_int(values.get("spawn_count") or values.get("count"), default=4))),
                "enemy_types": enemies,
                "trigger": _surface_marker_value(values, "trigger", fallback="director_signal"),
                "budget": _number(values.get("budget") or values.get("threat_budget"), default=max(1.0, len(enemies) * 2.0)),
                "cooldown_seconds": _number(values.get("cooldown") or values.get("cooldown_seconds"), default=5.0),
            }
        )
    elif construct in {"combat_phase", "stealth_phase"}:
        state.update(
            {
                "phase": kind,
                "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=45.0),
                "entry_signal": _surface_marker_value(values, "entry_signal", "trigger", fallback=f"enter_{construct}"),
                "exit_signal": _surface_marker_value(values, "exit_signal", fallback=f"exit_{construct}"),
                "pressure": _number(values.get("pressure"), default=0.8 if construct == "combat_phase" else 0.35),
                "awareness": _number(values.get("awareness"), default=1.0 if construct == "combat_phase" else 0.25),
            }
        )
    elif construct == "escalation_rule":
        state.update(
            {
                "escalation": kind,
                "trigger": _surface_marker_value(values, "trigger", fallback="pressure_high"),
                "threshold": _number(values.get("threshold"), default=0.75),
                "cooldown_seconds": _number(values.get("cooldown") or values.get("cooldown_seconds"), default=20.0),
                "adds_wave": _surface_marker_value(values, "adds_wave", "wave", fallback="reinforce"),
                "adds_threat": _number(values.get("adds_threat") or values.get("threat"), default=2.0),
            }
        )
    elif construct == "adaptive_difficulty":
        state.update(
            {
                "difficulty": kind,
                "min_difficulty": _number(values.get("min_difficulty") or values.get("min"), default=0.5),
                "max_difficulty": _number(values.get("max_difficulty") or values.get("max"), default=2.0),
                "target_pressure": _number(values.get("target_pressure") or values.get("pressure"), default=0.65),
                "adjustment_rate": _number(values.get("adjustment_rate") or values.get("rate"), default=0.1),
                "metrics": _gameplay_name_list(values, ("metrics", "signals"), default=["damage_taken", "time_since_hit", "resources"]),
            }
        )
    elif construct == "encounter_beat":
        state.update(
            {
                "beat": kind,
                "order": _positive_int(values.get("order"), default=1),
                "duration_seconds": _number(values.get("duration") or values.get("duration_seconds"), default=12.0),
                "signal": _surface_marker_value(values, "signal", fallback=kind),
                "pressure": _number(values.get("pressure"), default=0.5),
            }
        )
    elif construct == "director_signal":
        state.update(
            {
                "signal": kind,
                "channel": _surface_marker_value(values, "channel", fallback="director"),
                "payload": _string(values.get("payload"), default=""),
                "cooldown_seconds": _number(values.get("cooldown") or values.get("cooldown_seconds"), default=0.0),
                "event_count": 1,
            }
        )
    elif construct == "threat_zone":
        state.update(
            {
                "threat": kind,
                "radius": _number(values.get("radius"), default=6.0),
                "threat_budget": _number(values.get("threat_budget") or values.get("budget"), default=5.0),
                "cover_count": _positive_int(values.get("cover_count") or values.get("cover"), default=2),
                "spawn_point_count": _positive_int(values.get("spawn_points") or values.get("spawn_point_count"), default=2),
            }
        )
    elif construct == "reinforcement_route":
        state.update(
            {
                "route_type": kind,
                "route_length": _number(values.get("length") or values.get("route_length"), default=12.0),
                "spawn_wave": _snake_id(values.get("spawn_wave") or values.get("wave"), ""),
                "lane_count": _positive_int(values.get("lanes") or values.get("lane_count"), default=1),
                "reinforcement_route_count": 1,
            }
        )
    return state


def _director_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    action = _snake_id(values.get("action") or _DIRECTOR_ACTIONS.get(construct), "run_director")
    affordance: dict[str, Any] = {"action": action}
    if values.get("requires"):
        affordance["requires"] = _string(values.get("requires"))
    return affordance


def _expand_director_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _director_kind(values, construct)
    core_name = _director_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_director_scale(values, construct),
        state=_director_state(values, construct, name, kind),
        tags=[construct, kind, "director", "encounter", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_DIRECTOR_ACTIONS.get(construct), "run_director"): _director_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_DIRECTOR_ROLES.get(construct, "narrative_clue"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    if construct in {"director", "encounter_director"}:
        child_specs = [
            ("pacing_curve", f"{name}_pacing", [center[0] - 1.2, center[1] + 1.0, center[2] + 0.04]),
            ("threat_budget", f"{name}_threat", [center[0], center[1] + 1.0, center[2] + 0.04]),
            ("adaptive_difficulty", f"{name}_adaptive", [center[0] + 1.2, center[1] + 1.0, center[2] + 0.04]),
            ("escalation_rule", f"{name}_escalation", [center[0], center[1] - 1.0, center[2] + 0.04]),
        ]
        for child_construct, child_name, child_position in child_specs:
            if _any_disabled(values, child_construct, child_construct.removesuffix("_rule")):
                continue
            child_values = deepcopy(values)
            child_values["position"] = child_position
            child_node = {"node_type": "scene_object", "name": child_name, "role": _DIRECTOR_ROLES.get(child_construct, "narrative_clue"), "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_director_macro(child_node, construct=child_construct)
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, core_name, _director_core_name(child_name, child_construct), "contains", f"Director {name} contains {child_construct}."))

        intents = _director_intents(values)[:12]
        for index, intent in enumerate(intents):
            intent_values = deepcopy(values)
            intent_values["intent"] = intent
            intent_values["position"] = [center[0] + (index - (len(intents) - 1) / 2.0) * 0.55, center[1] + 1.8, center[2] + 0.04]
            intent_node = {"node_type": "scene_object", "name": f"{name}_{intent}_intent", "role": "narrative_clue", "from": node.get("from"), "values": intent_values}
            intent_objects, intent_relationships = _expand_director_macro(intent_node, construct="director_intent")
            objects.extend(intent_objects)
            relationships.extend(intent_relationships)
            relationships.append(_macro_relationship(name, core_name, _director_core_name(f"{name}_{intent}_intent", "director_intent"), "supports", f"Director {name} can pursue intent {intent}."))

        waves = _director_waves(values)[:16]
        previous_wave = ""
        for index, wave in enumerate(waves):
            wave_values = deepcopy(values)
            wave_values["wave_type"] = wave
            wave_values["wave_index"] = index + 1
            wave_values["position"] = [center[0] + (index - (len(waves) - 1) / 2.0) * 0.85, center[1] - 1.85, center[2] + 0.04]
            wave_node = {"node_type": "scene_object", "name": f"{name}_{index + 1:02d}_{wave}_wave", "role": "interactive", "from": node.get("from"), "values": wave_values}
            wave_objects, wave_relationships = _expand_director_macro(wave_node, construct="spawn_wave")
            objects.extend(wave_objects)
            relationships.extend(wave_relationships)
            wave_core = _director_core_name(f"{name}_{index + 1:02d}_{wave}_wave", "spawn_wave")
            relationships.append(_macro_relationship(name, core_name, wave_core, "contains", f"Director {name} owns spawn wave {wave}."))
            if previous_wave:
                relationships.append(_macro_relationship(name, previous_wave, wave_core, "routes_to", f"Director {name} advances to wave {wave}."))
            previous_wave = wave_core

        phases = _director_phases(values)[:12]
        for index, phase in enumerate(phases):
            phase_construct = "stealth_phase" if "stealth" in phase or phase in {"infiltrate", "sneak"} else "combat_phase"
            phase_values = deepcopy(values)
            phase_values["phase"] = phase
            phase_values["position"] = [center[0] + (index - (len(phases) - 1) / 2.0) * 0.72, center[1] - 2.7, center[2] + 0.04]
            phase_node = {"node_type": "scene_object", "name": f"{name}_{phase}_phase", "role": "interactive", "from": node.get("from"), "values": phase_values}
            phase_objects, phase_relationships = _expand_director_macro(phase_node, construct=phase_construct)
            objects.extend(phase_objects)
            relationships.extend(phase_relationships)
            relationships.append(_macro_relationship(name, core_name, _director_core_name(f"{name}_{phase}_phase", phase_construct), "supports", f"Director {name} supports phase {phase}."))

        if not _any_disabled(values, "threat_zone", "threat_zones"):
            zone_count = max(1, min(12, _positive_int(values.get("threat_zones") or values.get("threat_zone_count"), default=1)))
            for index in range(zone_count):
                zone_values = deepcopy(values)
                zone_values["position"] = [center[0] + (index - (zone_count - 1) / 2.0) * 1.3, center[1], center[2] + 0.04]
                zone_node = {"node_type": "scene_object", "name": f"{name}_threat_zone_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": zone_values}
                zone_objects, zone_relationships = _expand_director_macro(zone_node, construct="threat_zone")
                objects.extend(zone_objects)
                relationships.extend(zone_relationships)
                relationships.append(_macro_relationship(name, core_name, _director_core_name(f"{name}_threat_zone_{index + 1:02d}", "threat_zone"), "points_toward", f"Director {name} watches threat zone {index + 1}."))

    elif construct == "pacing_curve":
        previous = ""
        beats = _director_beats(values)[:16]
        for index, beat in enumerate(beats):
            beat_values = deepcopy(values)
            beat_values["beat"] = beat
            beat_values["order"] = index + 1
            beat_values["position"] = [center[0] + (index - (len(beats) - 1) / 2.0) * 0.45, center[1] + 0.55, center[2] + 0.04]
            beat_node = {"node_type": "scene_object", "name": f"{name}_{index + 1:02d}_{beat}", "role": "narrative_clue", "from": node.get("from"), "values": beat_values}
            beat_objects, beat_relationships = _expand_director_macro(beat_node, construct="encounter_beat")
            objects.extend(beat_objects)
            relationships.extend(beat_relationships)
            beat_core = _director_core_name(f"{name}_{index + 1:02d}_{beat}", "encounter_beat")
            relationships.append(_macro_relationship(name, core_name, beat_core, "contains", f"Pacing curve {name} contains beat {beat}."))
            if previous:
                relationships.append(_macro_relationship(name, previous, beat_core, "routes_to", f"Pacing curve {name} advances to beat {beat}."))
            previous = beat_core

    elif construct == "threat_budget" and not _any_disabled(values, "spawn_budget", "budgets"):
        budget_values = deepcopy(values)
        budget_values["position"] = [center[0], center[1] - 0.55, center[2] + 0.04]
        budget_node = {"node_type": "scene_object", "name": f"{name}_spawn_budget", "role": "narrative_clue", "from": node.get("from"), "values": budget_values}
        budget_objects, budget_relationships = _expand_director_macro(budget_node, construct="spawn_budget")
        objects.extend(budget_objects)
        relationships.extend(budget_relationships)
        relationships.append(_macro_relationship(name, core_name, f"{name}_spawn_budget_spawn_budget_core", "contains", f"Threat budget {name} allocates spawn budget."))

    elif construct == "spawn_wave":
        spawn_count = max(1, min(24, _positive_int(values.get("spawn_points") or values.get("spawn_point_count") or values.get("spawn_count"), default=3)))
        enemies = _gameplay_name_list(values, ("enemy_types", "actors", "spawns"), default=["grunt"])
        for index in range(spawn_count):
            spawn_values = _macro_child_values(
                values,
                construct="interactable",
                position=[center[0] + (index - (spawn_count - 1) / 2.0) * 0.5, center[1] + 0.75, center[2] + 0.04],
                scale=[0.34, 0.34, 0.14],
                state={"spawn_wave": name, "spawn_index": index + 1, "actor_type": enemies[index % len(enemies)], "interaction_type": "spawn_actor", "spawn_state": "queued"},
                tags=["spawn_wave", "spawn_point", enemies[index % len(enemies)], "director", "macro_generated"],
            )
            spawn_values["affordances"] = {"spawn": {"action": "spawn_actor", "requires": _string(values.get("requires"), default="")}}
            spawn_name = f"{name}_spawn_{index + 1:02d}"
            objects.append(_macro_scene_object(spawn_name, "interactable", spawn_values, role="interactive", source=node.get("from")))
            relationships.append(_macro_relationship(name, core_name, spawn_name, "contains", f"Spawn wave {name} contains spawn point {index + 1}."))
        if not _any_disabled(values, "reinforcement_route", "route"):
            route_values = deepcopy(values)
            route_values["position"] = [center[0], center[1] - 0.75, center[2] + 0.04]
            route_values["spawn_wave"] = core_name
            route_node = {"node_type": "scene_object", "name": f"{name}_reinforcements", "role": "navigation", "from": node.get("from"), "values": route_values}
            route_objects, route_relationships = _expand_director_macro(route_node, construct="reinforcement_route")
            objects.extend(route_objects)
            relationships.extend(route_relationships)
            relationships.append(_macro_relationship(name, f"{name}_reinforcements_reinforcement_route_core", core_name, "routes_to", f"Reinforcement route feeds spawn wave {name}."))

    elif construct in {"combat_phase", "stealth_phase"} and not _any_disabled(values, "signal", "director_signal"):
        signal_values = deepcopy(values)
        signal_values["position"] = [center[0], center[1] + 0.55, center[2] + 0.04]
        signal_values["signal"] = f"enter_{kind}"
        signal_node = {"node_type": "scene_object", "name": f"{name}_signal", "role": "interactive", "from": node.get("from"), "values": signal_values}
        signal_objects, signal_relationships = _expand_director_macro(signal_node, construct="director_signal")
        objects.extend(signal_objects)
        relationships.extend(signal_relationships)
        relationships.append(_macro_relationship(name, f"{name}_signal_director_signal_core", core_name, "reveals", f"{construct} {name} is entered by a director signal."))

    elif construct == "threat_zone" and not _any_disabled(values, "cover", "spawn_points"):
        spawn_count = max(1, min(12, _positive_int(values.get("spawn_points") or values.get("spawn_point_count"), default=2)))
        for index in range(spawn_count):
            point_values = _macro_child_values(
                values,
                construct="interactable",
                position=[center[0] + (index - (spawn_count - 1) / 2.0) * 0.65, center[1], center[2] + 0.04],
                scale=[0.28, 0.28, 0.10],
                state={"threat_zone": name, "spawn_index": index + 1, "interaction_type": "spawn_actor"},
                tags=["threat_zone", "spawn_anchor", "director", "macro_generated"],
            )
            point_values["affordances"] = {"spawn": {"action": "spawn_actor"}}
            point_name = f"{name}_anchor_{index + 1:02d}"
            objects.append(_macro_scene_object(point_name, "interactable", point_values, role="interactive", source=node.get("from")))
            relationships.append(_macro_relationship(name, core_name, point_name, "contains", f"Threat zone {name} contains spawn anchor {index + 1}."))

    return objects, relationships


