def _simulation_kind(values: Mapping[str, Any], construct: str) -> str:
    return _surface_marker_value(values, *_SIMULATION_KIND_KEYS.get(construct, ("type",)), fallback=_SIMULATION_KIND_DEFAULTS.get(construct, construct))


def _simulation_core_name(name: str, construct: str) -> str:
    return f"{name}_{_SIMULATION_CORE_SUFFIXES.get(construct, 'simulation_core')}"


def _simulation_scale(values: Mapping[str, Any], construct: str) -> list[float]:
    if construct == "simulation_layer":
        return [max(2.0, _number(values.get("width"), default=3.6)), max(1.2, _number(values.get("depth"), default=2.2)), 0.18]
    if construct in {"resource_flow", "patrol_density"}:
        return [max(1.5, _number(values.get("length") or values.get("width"), default=3.2)), 0.18, 0.12]
    if construct in {"alarm_grid", "sensor_grid", "cover_map"}:
        return [max(1.0, _number(values.get("width"), default=1.6)), max(0.8, _number(values.get("depth"), default=1.2)), 0.12]
    if construct in {"heat_field", "noise_field", "visibility_field", "hazard_field"}:
        radius = max(0.5, _number(values.get("radius"), default=1.4))
        return [radius, radius, 0.10]
    if construct == "flow_gate":
        return [0.42, 0.24, 0.16]
    return [0.42, 0.22, 0.12]


def _simulation_fields(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("fields", "field_types", "simulation_fields", "layers"), default=["heat", "noise", "visibility", "hazard", "cover"])


def _simulation_metrics(values: Mapping[str, Any]) -> list[str]:
    return _gameplay_name_list(values, ("metrics", "world_metrics", "metric"), default=["danger", "resources", "visibility"])


def _simulation_field_construct(field: str) -> str:
    return _SIMULATION_FIELD_CONSTRUCTS.get(_snake_id(field, "field"), "world_metric")


def _simulation_probe_count(values: Mapping[str, Any], *, default: int) -> int:
    return max(0, min(256, _positive_int(values.get("probes") or values.get("probe_count") or values.get("sample_count") or values.get("samples"), default=default)))


def _simulation_state(values: Mapping[str, Any], construct: str, name: str, kind: str) -> dict[str, Any]:
    state: dict[str, Any] = {
        construct: name,
        "simulation_construct": construct,
        "simulation_kind": kind,
        "action": _snake_id(values.get("action") or _SIMULATION_ACTIONS.get(construct), "query_simulation"),
        f"{construct}_count": 1,
        "simulation_count": 1,
        "object_archetype": construct,
        "setpiece_layout": "world_simulation_system",
        "enabled": not _disabled(values.get("enabled", True)),
        "priority": _number(values.get("priority"), default=1.0),
    }
    if construct == "simulation_layer":
        fields = _simulation_fields(values)
        field_constructs = [_simulation_field_construct(field) for field in fields]
        metrics = _simulation_metrics(values)
        state.update(
            {
                "simulation_type": kind,
                "fields": fields,
                "field_count": len(fields),
                "resolution": _positive_int(values.get("resolution"), default=64),
                "tick_rate": _number(values.get("tick_rate") or values.get("tick"), default=0.25),
                "sample_count": _simulation_probe_count(values, default=max(1, len(fields))),
                "metric_count": len(metrics),
                "world_metric_count": len(metrics),
                "heat_field_count": field_constructs.count("heat_field"),
                "noise_field_count": field_constructs.count("noise_field"),
                "visibility_field_count": field_constructs.count("visibility_field"),
                "resource_flow_count": field_constructs.count("resource_flow"),
                "faction_pressure_count": field_constructs.count("faction_pressure"),
                "territory_influence_count": field_constructs.count("territory_influence"),
                "alarm_grid_count": field_constructs.count("alarm_grid"),
                "patrol_density_count": field_constructs.count("patrol_density"),
                "hazard_field_count": field_constructs.count("hazard_field"),
                "sensor_grid_count": field_constructs.count("sensor_grid"),
                "cover_map_count": field_constructs.count("cover_map"),
                "simulation_probe_count": _simulation_probe_count(values, default=max(1, len(fields))),
                "metrics": metrics,
            }
        )
    elif construct in {"heat_field", "noise_field", "visibility_field", "hazard_field"}:
        state.update(
            {
                "field_type": kind,
                "field_count": 1,
                "sample_count": _simulation_probe_count(values, default=3),
                "radius": _number(values.get("radius"), default=4.0),
                "intensity": _number(values.get("intensity"), default=0.5),
                "decay": _number(values.get("decay"), default=0.25),
                "diffusion": _number(values.get("diffusion"), default=0.35),
                "gradient": _surface_marker_value(values, "gradient", fallback="radial"),
                "falloff": _surface_marker_value(values, "falloff", fallback="smooth"),
                "coverage": _number(values.get("coverage"), default=0.5),
                "occlusion": _number(values.get("occlusion"), default=0.0),
            }
        )
        if construct == "hazard_field":
            state["hazard_type"] = kind
            state["hazard_level"] = _number(values.get("hazard_level") or values.get("level"), default=state["intensity"])
    elif construct == "resource_flow":
        sources = _gameplay_name_list(values, ("source_nodes", "sources", "from_nodes"), default=["source"])
        sinks = _gameplay_name_list(values, ("sink_nodes", "sinks", "to_nodes"), default=["sink"])
        gate_count = max(1, min(64, _positive_int(values.get("flow_gate_count") or values.get("gates"), default=min(4, max(len(sources), len(sinks))))))
        state.update(
            {
                "resource_type": kind,
                "source_nodes": sources,
                "sink_nodes": sinks,
                "source_count": len(sources),
                "sink_count": len(sinks),
                "flow_rate": _number(values.get("flow_rate") or values.get("rate"), default=1.0),
                "capacity": _number(values.get("capacity"), default=10.0),
                "flow_gate_count": gate_count,
            }
        )
    elif construct in {"faction_pressure", "territory_influence"}:
        state.update(
            {
                "faction": _surface_marker_value(values, "faction", fallback=kind if construct == "faction_pressure" else "neutral"),
                "territory": _surface_marker_value(values, "territory", "zone", fallback=kind if construct == "territory_influence" else "contested"),
                "pressure": _number(values.get("pressure"), default=0.5),
                "influence": _number(values.get("influence"), default=0.5),
                "decay": _number(values.get("decay"), default=0.05),
                "world_metric_count": 1,
            }
        )
    elif construct == "alarm_grid":
        sensor_count = max(1, min(64, _positive_int(values.get("sensors") or values.get("sensor_count") or values.get("sample_count"), default=4)))
        state.update(
            {
                "alarm_state": kind,
                "sensor_type": _surface_marker_value(values, "sensor_type", fallback="motion"),
                "sensor_grid_count": sensor_count,
                "coverage": _number(values.get("coverage"), default=0.65),
                "alarm_level": _number(values.get("alarm_level") or values.get("intensity"), default=0.5),
                "channels": _gameplay_name_list(values, ("channels", "signals"), default=["security"]),
                "director_signal_count": 1,
            }
        )
    elif construct == "patrol_density":
        route_count = max(1, min(24, _positive_int(values.get("routes") or values.get("route_count") or values.get("reinforcement_route_count"), default=2)))
        state.update(
            {
                "patrol_type": kind,
                "patrol_rate": _number(values.get("patrol_rate") or values.get("rate"), default=0.5),
                "density": _number(values.get("density"), default=0.5),
                "faction": _surface_marker_value(values, "faction", fallback="neutral"),
                "reinforcement_route_count": route_count,
                "route_count": route_count,
            }
        )
    elif construct == "sensor_grid":
        state.update(
            {
                "sensor_type": kind,
                "sensor_grid_count": 1,
                "sample_count": _simulation_probe_count(values, default=3),
                "coverage": _number(values.get("coverage"), default=0.75),
                "occlusion": _number(values.get("occlusion"), default=0.25),
                "resolution": _positive_int(values.get("resolution"), default=32),
            }
        )
    elif construct == "cover_map":
        state.update(
            {
                "cover_type": kind,
                "cover_map_count": 1,
                "cover_score": _number(values.get("cover_score") or values.get("score"), default=0.5),
                "occlusion": _number(values.get("occlusion"), default=0.45),
                "sample_count": _simulation_probe_count(values, default=4),
            }
        )
    elif construct == "flow_gate":
        state.update(
            {
                "resource_type": kind,
                "flow_gate_count": 1,
                "flow_rate": _number(values.get("flow_rate") or values.get("rate"), default=1.0),
                "gate_state": _surface_marker_value(values, "gate_state", "state", fallback="open"),
                "open_ratio": _number(values.get("open_ratio"), default=1.0),
                "source_node": _surface_marker_value(values, "source_node", fallback=""),
                "sink_node": _surface_marker_value(values, "sink_node", fallback=""),
            }
        )
    elif construct == "world_metric":
        state.update(
            {
                "metric": kind,
                "metric_value": _number(values.get("metric_value") or values.get("value"), default=0.5),
                "threshold": _number(values.get("threshold"), default=0.5),
                "world_metric_count": 1,
            }
        )
    elif construct == "simulation_probe":
        state.update(
            {
                "probe_type": kind,
                "query": _surface_marker_value(values, "query", "metric", fallback=kind),
                "sample_index": _positive_int(values.get("sample_index") or values.get("index"), default=1),
                "sample_count": 1,
                "simulation_probe_count": 1,
            }
        )
    return state


def _simulation_affordance(values: Mapping[str, Any], construct: str) -> dict[str, Any]:
    action = _snake_id(values.get("action") or _SIMULATION_ACTIONS.get(construct), "query_simulation")
    affordance: dict[str, Any] = {"action": action}
    query = _surface_marker_value(values, "query", "metric", "field_type", fallback="")
    if query:
        affordance["query"] = query
    if values.get("requires"):
        affordance["requires"] = _string(values.get("requires"))
    return affordance


def _expand_simulation_macro(node: Mapping[str, Any], *, construct: str) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), construct)
    center = _macro_center(values)
    kind = _simulation_kind(values, construct)
    core_name = _simulation_core_name(name, construct)
    core_values = _macro_child_values(
        values,
        construct=construct,
        position=center,
        scale=_simulation_scale(values, construct),
        state=_simulation_state(values, construct, name, kind),
        tags=[construct, kind, "systemic", "simulation", "macro_generated"],
    )
    core_values["affordances"] = {_snake_id(_SIMULATION_ACTIONS.get(construct), "query_simulation"): _simulation_affordance(values, construct)}
    objects: list[Mapping[str, Any]] = [_macro_scene_object(core_name, construct, core_values, role=_SIMULATION_ROLES.get(construct, "environment_structure"), source=node.get("from"))]
    relationships: list[Mapping[str, Any]] = []

    if construct == "simulation_layer":
        fields = _simulation_fields(values)[:16]
        for index, field in enumerate(fields):
            child_construct = _simulation_field_construct(field)
            if _any_disabled(values, child_construct, field):
                continue
            child_values = deepcopy(values)
            child_values["field_type"] = field
            child_values["metric"] = field
            child_values["position"] = [center[0] + (index - (len(fields) - 1) / 2.0) * 0.72, center[1] + 0.9, center[2] + 0.04]
            child_node = {"node_type": "scene_object", "name": f"{name}_{field}", "role": _SIMULATION_ROLES.get(child_construct, "environment_structure"), "from": node.get("from"), "values": child_values}
            child_objects, child_relationships = _expand_simulation_macro(child_node, construct=child_construct)
            objects.extend(child_objects)
            relationships.extend(child_relationships)
            relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_{field}", child_construct), "contains", f"Simulation layer {name} contains {field}."))

        metrics = _simulation_metrics(values)[:16]
        for index, metric in enumerate(metrics):
            if _any_disabled(values, "world_metric", metric):
                continue
            metric_values = deepcopy(values)
            metric_values["metric"] = metric
            metric_values["position"] = [center[0] + (index - (len(metrics) - 1) / 2.0) * 0.55, center[1] - 0.85, center[2] + 0.04]
            metric_node = {"node_type": "scene_object", "name": f"{name}_{metric}_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
            metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
            objects.extend(metric_objects)
            relationships.extend(metric_relationships)
            relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_{metric}_metric", "world_metric"), "reveals", f"Simulation layer {name} exposes metric {metric}."))

        probe_count = _simulation_probe_count(values, default=max(1, len(fields)))
        if probe_count and not _any_disabled(values, "simulation_probe", "probes"):
            queries = fields or metrics or ["world_state"]
            for index in range(probe_count):
                query = queries[index % len(queries)]
                probe_values = deepcopy(values)
                probe_values["probe_type"] = "layer_sample"
                probe_values["query"] = query
                probe_values["sample_index"] = index + 1
                probe_values["position"] = [center[0] + (index - (probe_count - 1) / 2.0) * 0.36, center[1], center[2] + 0.08]
                probe_node = {"node_type": "scene_object", "name": f"{name}_probe_{index + 1:02d}", "role": "narrative_clue", "from": node.get("from"), "values": probe_values}
                probe_objects, probe_relationships = _expand_simulation_macro(probe_node, construct="simulation_probe")
                objects.extend(probe_objects)
                relationships.extend(probe_relationships)
                relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_probe_{index + 1:02d}", "simulation_probe"), "supports", f"Simulation layer {name} samples {query}."))

    elif construct in {"heat_field", "noise_field", "visibility_field", "hazard_field", "sensor_grid", "cover_map"}:
        probe_count = _simulation_probe_count(values, default=3 if construct != "cover_map" else 4)
        if probe_count and not _any_disabled(values, "simulation_probe", "probes"):
            for index in range(probe_count):
                probe_values = deepcopy(values)
                probe_values["probe_type"] = kind
                probe_values["query"] = kind
                probe_values["sample_index"] = index + 1
                probe_values["position"] = [center[0] + (index - (probe_count - 1) / 2.0) * 0.32, center[1] + 0.48, center[2] + 0.04]
                probe_node = {"node_type": "scene_object", "name": f"{name}_sample_{index + 1:02d}", "role": "narrative_clue", "from": node.get("from"), "values": probe_values}
                probe_objects, probe_relationships = _expand_simulation_macro(probe_node, construct="simulation_probe")
                objects.extend(probe_objects)
                relationships.extend(probe_relationships)
                relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_sample_{index + 1:02d}", "simulation_probe"), "reveals", f"{construct} {name} has sample probe {index + 1}."))

    elif construct == "resource_flow" and not _any_disabled(values, "flow_gate", "gates"):
        sources = _gameplay_name_list(values, ("source_nodes", "sources", "from_nodes"), default=["source"])
        sinks = _gameplay_name_list(values, ("sink_nodes", "sinks", "to_nodes"), default=["sink"])
        gate_count = max(1, min(64, _positive_int(values.get("flow_gate_count") or values.get("gates"), default=min(4, max(len(sources), len(sinks))))))
        for index in range(gate_count):
            gate_values = deepcopy(values)
            gate_values["resource_type"] = kind
            gate_values["source_node"] = sources[index % len(sources)]
            gate_values["sink_node"] = sinks[index % len(sinks)]
            gate_values["position"] = [center[0] + (index - (gate_count - 1) / 2.0) * 0.48, center[1] + 0.45, center[2] + 0.04]
            gate_node = {"node_type": "scene_object", "name": f"{name}_gate_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": gate_values}
            gate_objects, gate_relationships = _expand_simulation_macro(gate_node, construct="flow_gate")
            objects.extend(gate_objects)
            relationships.extend(gate_relationships)
            relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_gate_{index + 1:02d}", "flow_gate"), "routes_to", f"Resource flow {name} routes through gate {index + 1}."))

    elif construct in {"faction_pressure", "territory_influence"} and not _any_disabled(values, "world_metric", "metric"):
        metric_values = deepcopy(values)
        metric_values["metric"] = "pressure" if construct == "faction_pressure" else "influence"
        metric_values["metric_value"] = values.get("pressure") if construct == "faction_pressure" else values.get("influence")
        metric_values["position"] = [center[0], center[1] + 0.55, center[2] + 0.04]
        metric_node = {"node_type": "scene_object", "name": f"{name}_metric", "role": "narrative_clue", "from": node.get("from"), "values": metric_values}
        metric_objects, metric_relationships = _expand_simulation_macro(metric_node, construct="world_metric")
        objects.extend(metric_objects)
        relationships.extend(metric_relationships)
        relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_metric", "world_metric"), "reveals", f"{construct} {name} exposes a world metric."))

    elif construct == "alarm_grid":
        sensor_count = max(1, min(64, _positive_int(values.get("sensors") or values.get("sensor_count") or values.get("sample_count"), default=4)))
        for index in range(sensor_count):
            sensor_values = deepcopy(values)
            sensor_values["sensor_type"] = _surface_marker_value(values, "sensor_type", fallback="motion")
            sensor_values["position"] = [center[0] + (index - (sensor_count - 1) / 2.0) * 0.34, center[1] + 0.55, center[2] + 0.04]
            sensor_node = {"node_type": "scene_object", "name": f"{name}_sensor_{index + 1:02d}", "role": "environment_structure", "from": node.get("from"), "values": sensor_values}
            sensor_objects, sensor_relationships = _expand_simulation_macro(sensor_node, construct="sensor_grid")
            objects.extend(sensor_objects)
            relationships.extend(sensor_relationships)
            relationships.append(_macro_relationship(name, core_name, _simulation_core_name(f"{name}_sensor_{index + 1:02d}", "sensor_grid"), "contains", f"Alarm grid {name} contains sensor {index + 1}."))
        if not _any_disabled(values, "director_signal", "signal"):
            signal_values = deepcopy(values)
            signal_values["signal"] = _surface_marker_value(values, "signal", fallback=f"{name}_alarm")
            signal_values["position"] = [center[0], center[1] - 0.55, center[2] + 0.04]
            signal_node = {"node_type": "scene_object", "name": f"{name}_alarm_signal", "role": "interactive", "from": node.get("from"), "values": signal_values}
            signal_objects, signal_relationships = _expand_director_macro(signal_node, construct="director_signal")
            objects.extend(signal_objects)
            relationships.extend(signal_relationships)
            relationships.append(_macro_relationship(name, _director_core_name(f"{name}_alarm_signal", "director_signal"), core_name, "reveals", f"Alarm grid {name} emits a director signal."))

    elif construct == "patrol_density" and not _any_disabled(values, "reinforcement_route", "routes"):
        route_count = max(1, min(24, _positive_int(values.get("routes") or values.get("route_count") or values.get("reinforcement_route_count"), default=2)))
        for index in range(route_count):
            route_values = deepcopy(values)
            route_values["route_type"] = "patrol"
            route_values["position"] = [center[0] + (index - (route_count - 1) / 2.0) * 0.72, center[1] + 0.42, center[2] + 0.04]
            route_node = {"node_type": "scene_object", "name": f"{name}_route_{index + 1:02d}", "role": "navigation", "from": node.get("from"), "values": route_values}
            route_objects, route_relationships = _expand_director_macro(route_node, construct="reinforcement_route")
            objects.extend(route_objects)
            relationships.extend(route_relationships)
            relationships.append(_macro_relationship(name, core_name, _director_core_name(f"{name}_route_{index + 1:02d}", "reinforcement_route"), "routes_to", f"Patrol density {name} routes patrol lane {index + 1}."))

    return objects, relationships


def _expand_quest_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "quest")
    center = _macro_center(values)
    quest_kind = _snake_id(values.get("quest_type") or values.get("type") or values.get("arc"), "multi_step")
    steps = _gameplay_name_list(values, ("objectives", "steps", "tasks"), default=["discover", "activate", "return"])
    giver_enabled = not _any_disabled(values, "giver", "quest_giver")
    rewards_enabled = not _any_disabled(values, "reward", "rewards")
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []

    core_name = f"{name}_quest_core"
    core_values = _macro_child_values(
        values,
        construct="quest",
        position=center,
        scale=[
            max(1.0, _number(values.get("quest_width") or values.get("width"), default=3.0)),
            max(1.0, _number(values.get("quest_depth") or values.get("depth"), default=2.0)),
            0.35,
        ],
        state={
            "quest": name,
            "quest_type": quest_kind,
            "quest_state": _snake_id(values.get("state") or values.get("quest_state"), "available"),
            "objective_count": len(steps),
            "reward_count": max(1, len(_gameplay_name_list(values, ("rewards", "reward_items"), default=["reward"])) if rewards_enabled else 0),
            "giver_enabled": giver_enabled,
            "repeatable": bool(values.get("repeatable", False)),
            "failure_state": _snake_id(values.get("failure") or values.get("failure_state"), "none"),
        },
        tags=["quest", quest_kind, "gameplay", "macro_generated"],
    )
    core_values["affordances"] = {"track": {"action": "track", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "quest", core_values, role="narrative_clue", source=node.get("from")))

    previous_objective = ""
    objective_names: list[str] = []
    for index, step in enumerate(steps):
        objective_name = f"{name}_objective_{index + 1:02d}_{step}"[:56].rstrip("_")
        objective_values = deepcopy(values)
        objective_values["position"] = [center[0] + (index - (len(steps) - 1) / 2.0) * 2.6, center[1] + 2.2, center[2] + 0.05]
        objective_values["objective_type"] = step
        objective_values["quest"] = name
        objective_values["order"] = index + 1
        objective_values["requires"] = previous_objective
        objective_values["rewards"] = False
        objective_node = {"node_type": "scene_object", "name": objective_name, "role": "interactive", "from": node.get("from"), "values": objective_values}
        objective_objects, objective_relationships = _expand_objective_macro(objective_node)
        objects.extend(objective_objects)
        relationships.extend(objective_relationships)
        objective_core = f"{objective_name}_objective_core"
        objective_names.append(objective_core)
        relationships.append(_macro_relationship(name, core_name, objective_core, "contains", f"Quest {name} contains objective {objective_name}."))
        if previous_objective:
            relationships.append(_macro_relationship(name, objective_core, previous_objective, "depends_on", f"Objective {objective_name} depends on previous quest step."))
        previous_objective = objective_core

    if giver_enabled:
        giver_values = deepcopy(values)
        giver_values["position"] = [center[0] - 2.6, center[1] - 1.8, center[2] + 0.04]
        giver_values["interaction"] = "accept_quest"
        giver_values["reveals"] = objective_names[0] if objective_names else core_name
        giver_values["requires"] = _string(values.get("giver_requires"), default="")
        giver_node = {"node_type": "scene_object", "name": f"{name}_quest_giver", "role": "interactive", "from": node.get("from"), "values": giver_values}
        giver_objects, giver_relationships = _expand_interactable_macro(giver_node)
        objects.extend(giver_objects)
        relationships.extend(giver_relationships)
        relationships.append(_macro_relationship(name, f"{name}_quest_giver_interactable", core_name, "reveals", f"Quest giver reveals quest {name}."))

    if rewards_enabled:
        reward_values = deepcopy(values)
        reward_values["position"] = [center[0] + 2.6, center[1] - 1.8, center[2] + 0.04]
        reward_values["interaction"] = "claim_reward"
        reward_values["requires"] = objective_names[-1] if objective_names else core_name
        reward_values["rewards"] = _gameplay_name_list(values, ("rewards", "reward_items"), default=["reward"])
        reward_node = {"node_type": "scene_object", "name": f"{name}_reward_cache", "role": "interactive", "from": node.get("from"), "values": reward_values}
        reward_objects, reward_relationships = _expand_interactable_macro(reward_node)
        objects.extend(reward_objects)
        relationships.extend(reward_relationships)
        relationships.append(_macro_relationship(name, f"{name}_reward_cache_interactable", core_name, "depends_on", f"Quest reward depends on quest completion."))

    return objects, relationships


def _expand_objective_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "objective")
    center = _macro_center(values)
    objective_kind = _snake_id(values.get("objective_type") or values.get("goal") or values.get("type"), "interact")
    target_count = max(0, min(16, _positive_int(values.get("targets") or values.get("target_count"), default=1)))
    marker_count = 0 if _any_disabled(values, "markers", "targets") else target_count
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_objective_core"
    core_values = _macro_child_values(
        values,
        construct="objective",
        position=center,
        scale=[max(0.8, _number(values.get("width"), default=1.6)), max(0.8, _number(values.get("depth"), default=1.2)), 0.30],
        state={
            "objective": name,
            "objective_type": objective_kind,
            "quest": _snake_id(values.get("quest"), ""),
            "order": _positive_int(values.get("order"), default=1),
            "target_count": marker_count,
            "required_count": max(1, min(max(1, marker_count), _positive_int(values.get("required") or values.get("required_count"), default=max(1, marker_count)))),
            "completed": bool(values.get("completed", False)),
            "optional": bool(values.get("optional", False)),
            "timer_seconds": _number(values.get("timer") or values.get("timer_seconds"), default=0.0),
        },
        tags=["objective", objective_kind, "gameplay", "macro_generated"],
    )
    core_values["affordances"] = {"track": {"action": "track_objective", "requires": _string(values.get("requires"), default="")}}
    objects.append(_macro_scene_object(core_name, "objective", core_values, role="interactive", source=node.get("from")))

    target_names = _gameplay_label_list(values, ("target_names", "target_refs", "target_labels"))
    for index in range(marker_count):
        target_label = target_names[index % len(target_names)] if target_names else f"target_{index + 1:02d}"
        target_name = f"{name}_{target_label}_marker"[:60].rstrip("_")
        target_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (marker_count - 1) / 2.0) * 1.8, center[1] + 1.8, center[2] + 0.04],
            scale=[0.6, 0.6, 0.24],
            state={
                "objective": name,
                "objective_target": target_label,
                "objective_type": objective_kind,
                "interaction_type": _objective_action(objective_kind),
                "progress_value": 1,
            },
            tags=["objective_marker", objective_kind, "interactable", "macro_generated"],
        )
        target_values["affordances"] = {"progress": {"action": _objective_action(objective_kind), "requires": _string(values.get("requires"), default="")}}
        objects.append(_macro_scene_object(target_name, "interactable", target_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, target_name, "points_toward", f"Objective {name} points to target {target_name}."))
        relationships.append(_macro_relationship(name, target_name, core_name, "reveals", f"Target {target_name} can progress objective {name}."))

    requires = _string(values.get("requires") or values.get("depends_on"))
    if requires:
        relationships.append(_macro_relationship(name, core_name, requires, "depends_on", f"Objective {name} depends on {requires}."))
    return objects, relationships


def _expand_interactable_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "interactable")
    center = _macro_center(values)
    interaction = _snake_id(values.get("interaction") or values.get("action") or values.get("interaction_type") or values.get("type"), "interact")
    core_name = f"{name}_interactable"
    core_values = _macro_child_values(
        values,
        construct="interactable",
        position=center,
        scale=[
            max(0.25, _number(values.get("width") or values.get("radius"), default=0.9)),
            max(0.25, _number(values.get("depth") or values.get("radius"), default=0.9)),
            max(0.15, _number(values.get("height"), default=0.42)),
        ],
        state={
            "interactable": name,
            "interaction_type": interaction,
            "action": interaction,
            "requires": _string(values.get("requires"), default=""),
            "reveals": _string(values.get("reveals"), default=""),
            "cooldown_seconds": _number(values.get("cooldown") or values.get("cooldown_seconds"), default=0.0),
            "charges": _positive_int(values.get("charges") or values.get("uses"), default=1),
            "reward_items": _gameplay_name_list(values, ("rewards", "reward_items", "items"), default=[]),
        },
        tags=["interactable", interaction, "gameplay", "macro_generated"],
    )
    affordance: dict[str, Any] = {"action": interaction}
    if values.get("reveals"):
        affordance["reveals"] = _string(values.get("reveals"))
    if values.get("requires"):
        affordance["requires"] = _string(values.get("requires"))
    core_values["affordances"] = {_snake_id(values.get("affordance") or interaction, "interact"): affordance}
    return [_macro_scene_object(core_name, "interactable", core_values, role="interactive", source=node.get("from"))], []


def _expand_encounter_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "encounter")
    center = _macro_center(values)
    encounter_kind = _snake_id(values.get("encounter_type") or values.get("type"), "combat")
    spawn_count = max(0, min(32, _positive_int(values.get("spawns") or values.get("spawn_count") or values.get("actors"), default=3)))
    cover_count = max(0, min(24, _positive_int(values.get("cover") or values.get("cover_count"), default=3 if encounter_kind in {"combat", "ambush"} else 1)))
    reward_count = 0 if _any_disabled(values, "loot", "rewards") else max(0, min(8, _positive_int(values.get("loot") or values.get("rewards") or values.get("reward_count"), default=1)))
    patrol_count = 0 if _any_disabled(values, "patrols", "routes") else max(0, min(8, _positive_int(values.get("patrols") or values.get("routes"), default=1 if encounter_kind in {"patrol", "ambush", "combat"} else 0)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_encounter_core"
    core_values = _macro_child_values(
        values,
        construct="encounter",
        position=center,
        scale=[max(2.0, _number(values.get("width"), default=8.0)), max(2.0, _number(values.get("depth"), default=6.0)), 0.35],
        state={
            "encounter": name,
            "encounter_type": encounter_kind,
            "difficulty": _snake_id(values.get("difficulty"), "normal"),
            "spawn_count": spawn_count,
            "cover_count": cover_count,
            "reward_count": reward_count,
            "patrol_count": patrol_count,
            "faction": _snake_id(values.get("faction") or _nested(values, "state", "faction"), ""),
            "trigger": _snake_id(values.get("trigger"), "proximity"),
        },
        tags=["encounter", encounter_kind, "gameplay", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "encounter", core_values, role="interactive", source=node.get("from")))

    actor_types = _gameplay_name_list(values, ("actor_types", "actors", "enemies", "npc_types"), default=["npc"])
    for index in range(spawn_count):
        spawn_name = f"{name}_spawn_{index + 1:02d}"
        spawn_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + (index - (spawn_count - 1) / 2.0) * 1.5, center[1] + 1.8, center[2] + 0.04],
            scale=[0.55, 0.55, 0.22],
            state={"encounter": name, "spawn_index": index, "actor_type": actor_types[index % len(actor_types)], "spawn_state": "ready", "interaction_type": "spawn"},
            tags=["encounter_spawn", actor_types[index % len(actor_types)], "macro_generated"],
        )
        spawn_values["affordances"] = {"spawn": {"action": "spawn_actor", "requires": _string(values.get("requires"), default="")}}
        objects.append(_macro_scene_object(spawn_name, "interactable", spawn_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, spawn_name, "contains", f"Encounter {name} contains spawn {spawn_name}."))

    for index in range(cover_count):
        cover_name = f"{name}_cover_{index + 1:02d}"
        cover_values = _macro_child_values(
            values,
            construct="infrastructure",
            position=[center[0] + (index - (cover_count - 1) / 2.0) * 1.7, center[1] - 1.6, center[2] + 0.05],
            scale=[0.9, 0.42, 0.42],
            state={"encounter": name, "cover_index": index, "cover_type": "half_cover", "support_count": 1, "barrier_count": 1},
            tags=["encounter_cover", "cover", "gameplay", "macro_generated"],
        )
        objects.append(_macro_scene_object(cover_name, "infrastructure", cover_values, role="environment_structure", source=node.get("from")))
        relationships.append(_macro_relationship(name, cover_name, core_name, "supports", f"Cover {cover_name} supports encounter {name}."))

    for index in range(patrol_count):
        route_values = deepcopy(values)
        route_values["position"] = [center[0], center[1] - 2.8 - index * 1.0, center[2] + 0.02]
        route_values["corridor_type"] = "patrol"
        route_values["modes"] = ["road"]
        route_values["segments"] = _positive_int(values.get("patrol_segments") or values.get("segments"), default=3)
        route_values["depots"] = 0
        route_values["service_runs"] = False
        route_values["corridor_length"] = max(4.0, _number(values.get("width"), default=8.0))
        route_values["corridor_width"] = 0.8
        route_node = {"node_type": "scene_object", "name": f"{name}_patrol_{index + 1:02d}", "role": "navigation", "from": node.get("from"), "values": route_values}
        route_objects, route_relationships = _expand_transport_corridor_macro(route_node)
        objects.extend(route_objects)
        relationships.extend(route_relationships)
        relationships.append(_macro_relationship(name, f"{name}_patrol_{index + 1:02d}_corridor_core", core_name, "routes_to", f"Patrol route feeds encounter {name}."))

    for index in range(reward_count):
        loot_values = deepcopy(values)
        loot_values["position"] = [center[0] + 2.4 + index * 0.8, center[1], center[2] + 0.04]
        loot_values["interaction"] = "loot"
        loot_values["requires"] = core_name
        loot_values["items"] = _gameplay_name_list(values, ("loot_items", "rewards"), default=["loot"])
        loot_node = {"node_type": "scene_object", "name": f"{name}_loot_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": loot_values}
        loot_objects, loot_relationships = _expand_interactable_macro(loot_node)
        objects.extend(loot_objects)
        relationships.extend(loot_relationships)
        relationships.append(_macro_relationship(name, f"{name}_loot_{index + 1:02d}_interactable", core_name, "depends_on", f"Loot depends on encounter {name}."))

    return objects, relationships


def _expand_traversal_gate_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "traversal_gate")
    center = _macro_center(values)
    gate_kind = _snake_id(values.get("gate_type") or values.get("traversal_type") or values.get("type"), "locked_gate")
    requirements = _gameplay_name_list(values, ("requires", "requirements", "keys"), default=["key"])
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    gate_name = f"{name}_gate"
    gate_values = _macro_child_values(
        values,
        construct="traversal_gate",
        position=center,
        scale=[max(1.2, _number(values.get("width"), default=2.2)), max(0.6, _number(values.get("depth"), default=0.8)), max(0.25, _number(values.get("height"), default=0.34))],
        state={
            "traversal_gate": name,
            "gate_type": gate_kind,
            "traversal_type": gate_kind,
            "requirements": requirements,
            "requirement_count": len(requirements),
            "blocks_until_complete": True,
            "safety_gate_count": 1,
            "walkway_count": 1,
            "guardrail_count": 2,
        },
        tags=["traversal_gate", gate_kind, "gameplay", "macro_generated"],
    )
    gate_values["affordances"] = {"unlock": {"action": "unlock", "requires": ",".join(requirements)}}
    objects.append(_macro_scene_object(gate_name, "traversal_gate", gate_values, role="navigation", source=node.get("from")))

    for index, requirement in enumerate(requirements):
        lock_values = deepcopy(values)
        lock_values["position"] = [center[0] + (index - (len(requirements) - 1) / 2.0) * 0.9, center[1] - 0.9, center[2] + 0.05]
        lock_values["interaction"] = "provide_requirement"
        lock_values["requires"] = requirement
        lock_values["reveals"] = gate_name
        lock_node = {"node_type": "scene_object", "name": f"{name}_{requirement}_lock", "role": "interactive", "from": node.get("from"), "values": lock_values}
        lock_objects, lock_relationships = _expand_interactable_macro(lock_node)
        objects.extend(lock_objects)
        relationships.extend(lock_relationships)
        relationships.append(_macro_relationship(name, gate_name, f"{name}_{requirement}_lock_interactable", "depends_on", f"Gate {name} depends on requirement {requirement}."))

    if not _any_disabled(values, "bypass", "alternate_route"):
        bypass_values = deepcopy(values)
        bypass_values["position"] = [center[0], center[1] + 1.4, center[2] + 0.02]
        bypass_values["access_type"] = "alternate_route"
        bypass_values["traversal_type"] = "bypass"
        bypass_values["walkway_count"] = 1
        bypass_node = {"node_type": "scene_object", "name": f"{name}_bypass", "role": "navigation", "from": node.get("from"), "values": bypass_values}
        bypass_objects, bypass_relationships = _expand_access_macro_from_values(bypass_node)
        objects.extend(bypass_objects)
        relationships.extend(bypass_relationships)
        relationships.append(_macro_relationship(name, f"{name}_bypass_access", gate_name, "routes_to", f"Bypass route offers alternate traversal around {name}."))

    return objects, relationships


def _expand_resource_economy_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "resource_economy")
    center = _macro_center(values)
    economy_kind = _snake_id(values.get("economy_type") or values.get("network_type") or values.get("type"), "local")
    goods = _gameplay_name_list(values, ("goods", "resources", "commodities"), default=["food", "fuel", "parts"])
    producer_count = max(0, min(16, _positive_int(values.get("producers") or values.get("producer_count"), default=max(1, len(goods)))))
    storage_count = max(0, min(12, _positive_int(values.get("storage") or values.get("storage_count") or values.get("depots"), default=1)))
    consumer_count = max(0, min(16, _positive_int(values.get("consumers") or values.get("consumer_count"), default=2)))
    route_count = 0 if _any_disabled(values, "routes", "trade_routes") else max(0, min(8, _positive_int(values.get("routes") or values.get("trade_routes"), default=1)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_economy_core"
    core_values = _macro_child_values(
        values,
        construct="resource_economy",
        position=center,
        scale=[max(2.0, _number(values.get("width"), default=8.0)), max(2.0, _number(values.get("depth"), default=6.0)), 0.34],
        state={
            "resource_economy": name,
            "economy_type": economy_kind,
            "goods": goods,
            "goods_count": len(goods),
            "producer_count": producer_count,
            "storage_count": storage_count,
            "consumer_count": consumer_count,
            "route_count": route_count,
            "scarcity": _number(values.get("scarcity"), default=0.0),
        },
        tags=["resource_economy", economy_kind, "gameplay", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "resource_economy", core_values, role="environment_structure", source=node.get("from")))

    producer_names: list[str] = []
    for index in range(producer_count):
        good = goods[index % len(goods)]
        producer_name = f"{name}_{good}_producer_{index + 1:02d}"[:60].rstrip("_")
        producer_values = _macro_child_values(
            values,
            construct="resource_region",
            position=[center[0] - 3.0, center[1] + (index - (producer_count - 1) / 2.0) * 1.4, center[2] + 0.03],
            scale=[1.6, 1.2, 0.28],
            state={"resource_economy": name, "resource_type": good, "production_rate": _number(values.get("production_rate"), default=1.0), "resource_count": 1},
            tags=["economy_producer", good, "resource_region", "macro_generated"],
        )
        objects.append(_macro_scene_object(producer_name, "resource_region", producer_values, role="environment_structure", source=node.get("from")))
        producer_names.append(producer_name)
        relationships.append(_macro_relationship(name, producer_name, core_name, "supports", f"Producer {producer_name} supports economy {name}."))

    storage_names: list[str] = []
    for index in range(storage_count):
        storage_name = f"{name}_storage_{index + 1:02d}"
        storage_values = _macro_child_values(
            values,
            construct="infrastructure",
            position=[center[0], center[1] + (index - (storage_count - 1) / 2.0) * 1.4, center[2] + 0.04],
            scale=[1.8, 1.2, 0.30],
            state={"resource_economy": name, "infrastructure_type": "economy_storage", "storage_count": len(goods), "goods": goods, "loading_zone_count": 1},
            tags=["economy_storage", "depot", "macro_generated"],
        )
        objects.append(_macro_scene_object(storage_name, "infrastructure", storage_values, role="environment_structure", source=node.get("from")))
        storage_names.append(storage_name)
        relationships.append(_macro_relationship(name, storage_name, core_name, "contains", f"Economy {name} contains storage {storage_name}."))

    for index in range(consumer_count):
        consumer_name = f"{name}_consumer_{index + 1:02d}"
        consumer_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + 3.0, center[1] + (index - (consumer_count - 1) / 2.0) * 1.4, center[2] + 0.04],
            scale=[1.0, 0.8, 0.26],
            state={"resource_economy": name, "consumer_index": index, "demand": goods[index % len(goods)], "interaction_type": "deliver_resource"},
            tags=["economy_consumer", goods[index % len(goods)], "interactable", "macro_generated"],
        )
        consumer_values["affordances"] = {"deliver": {"action": "deliver_resource", "requires": goods[index % len(goods)]}}
        objects.append(_macro_scene_object(consumer_name, "interactable", consumer_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, consumer_name, "routes_to", f"Economy {name} delivers goods to consumer {consumer_name}."))
        if storage_names:
            relationships.append(_macro_relationship(name, storage_names[index % len(storage_names)], consumer_name, "routes_to", f"Storage feeds consumer {consumer_name}."))

    for producer_name in producer_names:
        if storage_names:
            relationships.append(_macro_relationship(name, producer_name, storage_names[producer_names.index(producer_name) % len(storage_names)], "routes_to", f"Producer feeds economy storage."))

    for index in range(route_count):
        route_values = deepcopy(values)
        route_values["position"] = [center[0], center[1] - 3.0 - index * 0.9, center[2] + 0.02]
        route_values["corridor_type"] = "trade"
        route_values["modes"] = ["road"]
        route_values["segments"] = _positive_int(values.get("segments"), default=3)
        route_values["depots"] = 0
        route_values["service_runs"] = False
        route_values["corridor_length"] = max(5.0, _number(values.get("width"), default=8.0))
        route_values["corridor_width"] = 0.9
        route_node = {"node_type": "scene_object", "name": f"{name}_trade_route_{index + 1:02d}", "role": "navigation", "from": node.get("from"), "values": route_values}
        route_objects, route_relationships = _expand_transport_corridor_macro(route_node)
        objects.extend(route_objects)
        relationships.extend(route_relationships)
        relationships.append(_macro_relationship(name, f"{name}_trade_route_{index + 1:02d}_corridor_core", core_name, "routes_to", f"Trade route moves resources through economy {name}."))

    return objects, relationships


def _expand_control_zone_macro(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "control_zone")
    center = _macro_center(values)
    faction = _snake_id(values.get("faction") or _nested(values, "state", "faction"), "neutral")
    zone_kind = _snake_id(values.get("zone_type") or values.get("control_type") or values.get("type"), "territory")
    point_count = max(0, min(16, _positive_int(values.get("control_points") or values.get("points") or values.get("point_count"), default=3)))
    defense_count = 0 if _any_disabled(values, "defenses") else max(0, min(16, _positive_int(values.get("defenses") or values.get("defense_count"), default=2)))
    patrol_count = 0 if _any_disabled(values, "patrols", "encounters") else max(0, min(8, _positive_int(values.get("patrols") or values.get("encounters"), default=1)))
    objects: list[Mapping[str, Any]] = []
    relationships: list[Mapping[str, Any]] = []
    core_name = f"{name}_control_core"
    core_values = _macro_child_values(
        values,
        construct="control_zone",
        position=center,
        scale=[max(2.0, _number(values.get("width"), default=10.0)), max(2.0, _number(values.get("depth"), default=8.0)), 0.24],
        state={
            "control_zone": name,
            "zone_type": zone_kind,
            "faction": faction,
            "control_value": _number(values.get("control") or values.get("control_value"), default=0.5),
            "control_point_count": point_count,
            "defense_count": defense_count,
            "patrol_count": patrol_count,
            "capture_rule": _snake_id(values.get("capture_rule") or values.get("rule"), "hold_points"),
        },
        tags=["control_zone", faction, zone_kind, "gameplay", "macro_generated"],
    )
    objects.append(_macro_scene_object(core_name, "control_zone", core_values, role="environment_structure", source=node.get("from")))

    boundary_name = f"{name}_boundary"
    boundary_values = _macro_child_values(
        values,
        construct="terrain",
        position=[center[0], center[1], center[2] - 0.04],
        scale=[max(2.0, _number(values.get("width"), default=10.0)), max(2.0, _number(values.get("depth"), default=8.0)), 0.08],
        state={"control_zone": name, "faction": faction, "landform": "control_boundary", "platform_count": 1, "path_count": max(1, point_count)},
        tags=["control_boundary", faction, "terrain", "macro_generated"],
    )
    objects.append(_macro_scene_object(boundary_name, "terrain", boundary_values, role="environment_structure", source=node.get("from")))
    relationships.append(_macro_relationship(name, core_name, boundary_name, "contains", f"Control zone {name} contains boundary {boundary_name}."))

    for index in range(point_count):
        angle = math.tau * index / max(1, point_count)
        point_name = f"{name}_control_point_{index + 1:02d}"
        point_values = _macro_child_values(
            values,
            construct="interactable",
            position=[center[0] + math.cos(angle) * 3.0, center[1] + math.sin(angle) * 2.4, center[2] + 0.04],
            scale=[0.9, 0.9, 0.28],
            state={"control_zone": name, "faction": faction, "control_point_index": index, "interaction_type": "capture", "capture_value": 1},
            tags=["control_point", faction, "interactable", "macro_generated"],
        )
        point_values["affordances"] = {"capture": {"action": "capture_control_point", "requires": _string(values.get("requires"), default="")}}
        objects.append(_macro_scene_object(point_name, "interactable", point_values, role="interactive", source=node.get("from")))
        relationships.append(_macro_relationship(name, core_name, point_name, "contains", f"Control zone {name} contains control point {point_name}."))

    for index in range(defense_count):
        defense_name = f"{name}_defense_{index + 1:02d}"
        defense_values = _macro_child_values(
            values,
            construct="infrastructure",
            position=[center[0] + (index - (defense_count - 1) / 2.0) * 2.0, center[1] - 3.0, center[2] + 0.05],
            scale=[1.0, 0.55, 0.35],
            state={"control_zone": name, "faction": faction, "infrastructure_type": "zone_defense", "tower_count": 1, "barrier_count": 2, "support_count": 2},
            tags=["control_zone_defense", faction, "defense", "macro_generated"],
        )
        objects.append(_macro_scene_object(defense_name, "infrastructure", defense_values, role="environment_structure", source=node.get("from")))
        relationships.append(_macro_relationship(name, defense_name, core_name, "supports", f"Defense {defense_name} supports control zone {name}."))

    for index in range(patrol_count):
        encounter_values = deepcopy(values)
        encounter_values["position"] = [center[0], center[1] + 3.2 + index * 1.0, center[2] + 0.04]
        encounter_values["encounter_type"] = "patrol"
        encounter_values["spawns"] = _positive_int(values.get("patrol_spawns") or values.get("spawns"), default=2)
        encounter_values["cover"] = 1
        encounter_values["loot"] = False
        encounter_node = {"node_type": "scene_object", "name": f"{name}_patrol_{index + 1:02d}", "role": "interactive", "from": node.get("from"), "values": encounter_values}
        encounter_objects, encounter_relationships = _expand_encounter_macro(encounter_node)
        objects.extend(encounter_objects)
        relationships.extend(encounter_relationships)
        relationships.append(_macro_relationship(name, f"{name}_patrol_{index + 1:02d}_encounter_core", core_name, "supports", f"Patrol encounter supports control zone {name}."))

    return objects, relationships


def _expand_access_macro_from_values(node: Mapping[str, Any]) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    values = deepcopy(dict(_values(node)))
    name = _snake_id(node.get("name"), "access")
    center = _macro_center(values)
    access_values = _macro_child_values(
        values,
        construct="access",
        position=center,
        scale=[max(1.0, _number(values.get("width"), default=3.0)), max(0.5, _number(values.get("depth"), default=0.8)), 0.18],
        state={
            "access": name,
            "access_type": _snake_id(values.get("access_type") or values.get("traversal_type"), "access"),
            "traversal_type": _snake_id(values.get("traversal_type") or values.get("access_type"), "access"),
            "walkway_count": _positive_int(values.get("walkway_count") or values.get("walkways"), default=1),
            "platform_count": _positive_int(values.get("platform_count") or values.get("platforms"), default=1),
            "guardrail_count": _positive_int(values.get("guardrail_count") or values.get("guardrails"), default=2),
        },
        tags=["access", "traversal", "macro_generated"],
    )
    return [_macro_scene_object(f"{name}_access", "access", access_values, role="navigation", source=node.get("from"))], []


