def _macro_scene_object(
    name: str,
    construct: str,
    values: Mapping[str, Any],
    *,
    role: str,
    source: Any,
) -> dict[str, Any]:
    return {
        "node_type": "scene_object",
        "name": name,
        "role": role,
        "from": source or "",
        "values": dict(values),
    }


def _macro_relationship(
    macro_name: str,
    source: str,
    target: str,
    relation: str,
    description: str,
) -> dict[str, Any]:
    return {
        "node_type": "scene_relationship",
        "name": f"{macro_name}_{source}_{relation}_{target}"[:72].rstrip("_"),
        "type": relation,
        "values": {
            "from": source,
            "to": target,
            "type": relation,
            "description": description,
        },
    }


def _room_role(values: Mapping[str, Any], index: int) -> str:
    roles = _string_list(values.get("room_roles") or values.get("roles"))
    if roles:
        return _snake_id(roles[index % len(roles)], "room")
    defaults = ("entry", "workshop", "storage", "living", "control_room", "utility")
    return defaults[index % len(defaults)]


def _room_furniture_state(values: Mapping[str, Any], room_role: str) -> dict[str, int]:
    defaults_by_role = {
        "entry": {"table_count": 0, "chair_count": 1, "cabinet_count": 1, "lamp_count": 1},
        "living": {"table_count": 1, "chair_count": 3, "shelf_count": 1, "lamp_count": 2},
        "lounge": {"table_count": 1, "chair_count": 4, "shelf_count": 1, "lamp_count": 2},
        "office": {"table_count": 2, "chair_count": 3, "shelf_count": 2, "cabinet_count": 1, "lamp_count": 1},
        "workshop": {"table_count": 1, "chair_count": 1, "shelf_count": 2, "cabinet_count": 1, "counter_count": 1, "lamp_count": 1},
        "storage": {"table_count": 0, "chair_count": 0, "shelf_count": 4, "cabinet_count": 2, "lamp_count": 1},
        "control_room": {"table_count": 2, "chair_count": 4, "cabinet_count": 2, "counter_count": 2, "lamp_count": 1},
        "utility": {"table_count": 0, "chair_count": 0, "shelf_count": 1, "cabinet_count": 2, "counter_count": 1, "lamp_count": 1},
        "bedroom": {"bed_count": 1, "table_count": 1, "chair_count": 1, "cabinet_count": 1, "lamp_count": 2},
        "barracks": {"bed_count": 4, "cabinet_count": 4, "lamp_count": 2},
        "kitchen": {"table_count": 1, "chair_count": 2, "cabinet_count": 3, "counter_count": 2, "lamp_count": 1},
        "lab": {"table_count": 2, "chair_count": 2, "shelf_count": 2, "cabinet_count": 2, "counter_count": 2, "lamp_count": 2},
    }
    defaults = defaults_by_role.get(room_role, {"table_count": 1, "chair_count": 2, "lamp_count": 1})
    aliases = {
        "table_count": ("table_count", "tables", "desk_count"),
        "chair_count": ("chair_count", "chairs", "seat_count"),
        "bed_count": ("bed_count", "beds", "bunk_count"),
        "shelf_count": ("shelf_count", "shelves", "rack_count"),
        "cabinet_count": ("cabinet_count", "cabinets", "locker_count"),
        "counter_count": ("counter_count", "counters", "workbench_count"),
        "lamp_count": ("lamp_count", "lamps", "floor_lamp_count"),
    }
    state: dict[str, int] = {}
    for target, names in aliases.items():
        default = int(defaults.get(target, 0))
        for name in names:
            if name in values:
                state[target] = _positive_int(values.get(name), default=default)
                break
        else:
            state[target] = default
    return state


def _scene_anchor_positions(
    regions: Sequence[Mapping[str, Any]],
    object_nodes: Sequence[Mapping[str, Any]],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
) -> dict[str, list[float]]:
    positions: dict[str, list[float]] = {}
    for region in regions:
        region_id = _string(region.get("region_id"))
        center = _vector3(_nested(region, "bounds", "center"), [0.0, 0.0, 0.0])
        source_name = _string(region.get("_source_name"))
        if region_id:
            positions[region_id] = center
        if source_name:
            positions[source_name] = center
    for source_name, region_id in region_id_by_name.items():
        if region_id in positions:
            positions[source_name] = list(positions[region_id])
    for node in object_nodes:
        values = _values(node)
        position = _authored_position(values)
        if position is None:
            continue
        source_name = _string(node.get("name"))
        object_id = object_id_by_name.get(source_name) if source_name else None
        if source_name:
            positions[source_name] = position
        if object_id:
            positions[object_id] = position
    return positions


def _lower_object(
    node: Mapping[str, Any],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
    default_region: str,
    member_tags: Mapping[str, list[str]],
    anchor_positions: Mapping[str, Sequence[float]],
    composition_state: Mapping[str, Any],
) -> tuple[dict[str, Any], list[dict[str, str]]]:
    values = _values(node)
    object_id = object_id_by_name.get(str(node.get("name")), _prefixed_id("obj", node.get("name"), "object"))
    construct = _string(values.get("_construct"), default="object")
    construct_spec = _WORLD_PIECE_CONSTRUCTS.get(construct, {})
    role = _scene_role(_string(node.get("role")) or values.get("role"), construct=construct)
    source = (
        _string(node.get("from"))
        or values.get("lathe_asset")
        or values.get("source_asset")
        or values.get("asset")
        or construct_spec.get("lathe_asset")
    )
    lathe_asset = _snake_id(source or construct or node.get("name"), "asset")
    region = _scene_ref(values.get("region"), region_id_by_name, object_id_by_name, default=default_region, prefix="region")
    transform = _transform(values)
    connector_state: dict[str, str | int | float | bool | None] = {}
    if construct in _CONNECTOR_CONSTRUCTS:
        transform, connector_state = _connector_transform(
            values,
            construct,
            transform,
            region_id_by_name,
            object_id_by_name,
            anchor_positions,
        )
    bindings = _material_bindings(values)
    raw_role = _string(node.get("role")) or _string(values.get("role"))
    tags = _string_list(values.get("semantic_tags") or values.get("tags"))
    tags.extend(member_tags.get(str(node.get("name")), []))
    tags.extend(str(tag) for tag in construct_spec.get("tags", []))
    if raw_role and raw_role not in _SCENE_ROLES:
        tags.append(raw_role)
    if construct != "object":
        tags.append(construct)
    state = _state(values.get("state"))
    state.update(_world_piece_state(construct, values, connector_state))
    state.update(_direct_world_piece_state(values))
    state.update(_child_module_state(values))
    gameplay = values.get("gameplay") if isinstance(values.get("gameplay"), Mapping) else {}
    if isinstance(gameplay, Mapping):
        state.update(_state(gameplay.get("state")))
        state.update(_child_module_state(gameplay))
    state.update(_state(composition_state))
    obj: dict[str, Any] = {
        "object_id": object_id,
        "name": _string(values.get("name"), default=_display_name(object_id)),
        "role": role,
        "region": region,
        "lathe_asset": lathe_asset,
        "transform": transform,
        "material_bindings": bindings,
        "semantic_tags": _dedupe(tags),
        "state": state,
    }
    for source_field, target_field in (("source_family", "source_family"), ("source_kit", "source_kit"), ("variant", "variant")):
        default_value = construct_spec.get(source_field) if source_field == "source_family" else None
        value = _optional_snake_id(values.get(source_field) or default_value)
        if value:
            obj[target_field] = value
    surface_overrides = _surface_overrides(values, construct=construct)
    if surface_overrides:
        obj["surface_overrides"] = surface_overrides
    affordances = _affordances(values)
    if affordances:
        obj["affordances"] = affordances
    return obj, bindings


def _authored_position(values: Mapping[str, Any]) -> list[float] | None:
    transform = values.get("transform") if isinstance(values.get("transform"), Mapping) else {}
    if isinstance(transform, Mapping) and "position" in transform:
        return _vector3(transform.get("position"), [0.0, 0.0, 0.0])
    if "position" in values:
        return _vector3(values.get("position"), [0.0, 0.0, 0.0])
    return None


def _has_transform_field(values: Mapping[str, Any], field: str) -> bool:
    transform = values.get("transform") if isinstance(values.get("transform"), Mapping) else {}
    return field in values or (isinstance(transform, Mapping) and field in transform)


def _connection_ref(values: Mapping[str, Any], *keys: str) -> Any:
    for key in keys:
        if key in values:
            return values.get(key)
    connection = values.get("connection") if isinstance(values.get("connection"), Mapping) else {}
    connect = values.get("connect") if isinstance(values.get("connect"), Mapping) else {}
    for key in keys:
        if isinstance(connection, Mapping) and key in connection:
            return connection.get(key)
        if isinstance(connect, Mapping) and key in connect:
            return connect.get(key)
    return None


def _anchor_position(
    value: Any,
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
    anchor_positions: Mapping[str, Sequence[float]],
) -> list[float] | None:
    raw = _string(value)
    if not raw:
        return None
    candidates = [
        raw,
        region_id_by_name.get(raw, ""),
        object_id_by_name.get(raw, ""),
        _scene_ref(raw, region_id_by_name, object_id_by_name, default=""),
    ]
    for candidate in candidates:
        if candidate and candidate in anchor_positions:
            return [float(item) for item in anchor_positions[candidate]]
    return None


def _connector_transform(
    values: Mapping[str, Any],
    construct: str,
    transform: Mapping[str, Sequence[float]],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
    anchor_positions: Mapping[str, Sequence[float]],
) -> tuple[dict[str, list[float]], dict[str, str | int | float | bool | None]]:
    start_ref = _connection_ref(values, "from", "start", "a")
    end_ref = _connection_ref(values, "to", "end", "b")
    start = _anchor_position(start_ref, region_id_by_name, object_id_by_name, anchor_positions)
    end = _anchor_position(end_ref, region_id_by_name, object_id_by_name, anchor_positions)
    out = {
        "position": list(transform.get("position", [0.0, 0.0, 0.0])),
        "rotation": list(transform.get("rotation", [0.0, 0.0, 0.0])),
        "scale": list(transform.get("scale", [1.0, 1.0, 1.0])),
    }
    if start is None or end is None:
        return out, {}

    dx = float(end[0]) - float(start[0])
    dy = float(end[1]) - float(start[1])
    dz = float(end[2]) - float(start[2])
    length = max((dx * dx + dy * dy + dz * dz) ** 0.5, 0.1)
    width_default = 2.4 if construct == "bridge" else 1.6
    height_default = 0.5 if construct == "bridge" else 0.1
    width = _number(values.get("width") or _nested(values, "shape", "width"), width_default)
    height = _number(values.get("height") or _nested(values, "shape", "height"), height_default)
    if not _has_transform_field(values, "position"):
        out["position"] = [
            round((float(start[0]) + float(end[0])) / 2.0, 6),
            round((float(start[1]) + float(end[1])) / 2.0, 6),
            round((float(start[2]) + float(end[2])) / 2.0, 6),
        ]
    if not _has_transform_field(values, "rotation"):
        yaw_degrees = round(math.degrees(math.atan2(dy, dx)), 6)
        out["rotation"] = [0.0, 0.0, yaw_degrees]
    else:
        yaw_degrees = float(out["rotation"][2])
    if not _has_transform_field(values, "scale"):
        out["scale"] = [round(width, 6), round(length, 6), round(max(height, 0.05), 6)]
    return out, {
        "connection_from": _scene_ref(start_ref, region_id_by_name, object_id_by_name, default=_string(start_ref)),
        "connection_to": _scene_ref(end_ref, region_id_by_name, object_id_by_name, default=_string(end_ref)),
        "connection_length": round(length, 6),
        "connection_yaw_degrees": yaw_degrees,
        "derived_connector_transform": True,
    }


def _composition_state_by_object(
    sockets: Sequence[Mapping[str, Any]],
    attachments: Sequence[Mapping[str, Any]],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
) -> dict[str, dict[str, Any]]:
    state_by_object: dict[str, dict[str, Any]] = {}
    for index, socket in enumerate(sockets):
        values = _values(socket)
        target_ref = _composition_target(values, "on", "object", "target", "to", "parent")
        target_id = _scene_ref(target_ref, region_id_by_name, object_id_by_name, default="")
        if not target_id:
            continue
        socket_name = _snake_id(values.get("id") or socket.get("name"), f"socket_{index}")
        socket_kind = _snake_id(
            values.get("kind") or values.get("socket_type") or socket.get("type") or values.get("type"),
            "attach",
        )
        socket_type = _snake_id(values.get("socket_type") or socket_kind, "attach")
        socket_label = _snake_id(values.get("interface") or f"{socket_name}_{socket_kind}", "socket")
        state = state_by_object.setdefault(target_id, {})
        _append_state_items(state, "composition_sockets", [socket_label])
        state[f"socket_{socket_name}_kind"] = socket_kind
        state[f"socket_{socket_name}_type"] = socket_type
        if "side" in values:
            state[f"socket_{socket_name}_side"] = _snake_id(values.get("side"), "side")
        accepts = _string_list(values.get("accepts") or values.get("accept"))
        if accepts:
            state[f"socket_{socket_name}_accepts"] = [_snake_id(item, "item") for item in accepts]
        if "position" in values or isinstance(values.get("transform"), Mapping):
            raw_position = values.get("position") or _nested(values, "transform", "position")
            state[f"socket_{socket_name}_position"] = _vector3(raw_position, [0.0, 0.0, 0.0])
        if "normal" in values or "axis" in values:
            state[f"socket_{socket_name}_normal"] = _vector3(values.get("normal") or values.get("axis"), [1.0, 0.0, 0.0])

    for index, attachment in enumerate(attachments):
        values = _values(attachment)
        source_ref = _composition_target(values, "from", "source", "child", "object")
        source_id = _scene_ref(source_ref, region_id_by_name, object_id_by_name, default="")
        if not source_id:
            continue
        target_ref = _composition_target(values, "to", "target", "parent", "on")
        target_id = _scene_ref(target_ref, region_id_by_name, object_id_by_name, default=_string(target_ref))
        attach_name = _snake_id(values.get("id") or attachment.get("name"), f"attach_{index}")
        socket_name = _snake_id(values.get("socket") or values.get("target_socket") or values.get("slot"), "socket")
        mode = _snake_id(values.get("mode") or attachment.get("type") or values.get("type"), "attach")
        anchor_label = _snake_id(values.get("anchor") or f"{attach_name}_{socket_name}", "anchor")
        state = state_by_object.setdefault(source_id, {})
        _append_state_items(state, "composition_anchors", [anchor_label])
        state[f"attach_{attach_name}_target"] = target_id
        state[f"attach_{attach_name}_socket"] = socket_name
        state[f"attach_{attach_name}_mode"] = mode
        if "offset" in values:
            state[f"attach_{attach_name}_offset"] = _vector3(values.get("offset"), [0.0, 0.0, 0.0])
        if "align" in values:
            state[f"attach_{attach_name}_align"] = _snake_id(values.get("align"), "align")
    return state_by_object


def _composition_target(values: Mapping[str, Any], *keys: str) -> Any:
    for key in keys:
        if key in values:
            return values[key]
    for namespace in ("attach", "connection", "connect", "socket"):
        nested = values.get(namespace)
        if not isinstance(nested, Mapping):
            continue
        for key in keys:
            if key in nested:
                return nested[key]
    return None


def _append_state_items(state: dict[str, Any], key: str, values: Sequence[str]) -> None:
    current = state.get(key)
    items = _string_list(current)
    items.extend(str(value) for value in values if value)
    state[key] = _dedupe(items)


def _world_piece_state(
    construct: str,
    values: Mapping[str, Any],
    connector_state: Mapping[str, str | int | float | bool | None],
) -> dict[str, Any]:
    if construct not in _WORLD_PIECE_CONSTRUCTS:
        return dict(connector_state)
    state: dict[str, Any] = {
        "scene_construct": construct,
        "procedural_family": str(_WORLD_PIECE_CONSTRUCTS[construct]["source_family"]),
    }
    for key in (
        "lanes",
        "lane_count",
        "spans",
        "span_count",
        "floors",
        "floor_count",
        "lots",
        "lot_count",
        "bays",
        "bay_count",
        "terraces",
        "terrace_count",
    ):
        if key in values and isinstance(values[key], str | int | float | bool):
            state[key] = values[key]
    state.update(_direct_world_piece_state(values))
    state.update(connector_state)
    return state


def _direct_world_piece_state(values: Mapping[str, Any]) -> dict[str, Any]:
    state: dict[str, Any] = {}
    for key, value in values.items():
        if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
            continue
        if key.startswith("_") or key in _WORLD_STATE_RESERVED_KEYS or key in _SURFACE_OVERRIDE_KEYS:
            continue
        normalized = _surface_value(value)
        if isinstance(normalized, str | int | float | bool | list) or normalized is None:
            state[key] = normalized
    return state


def _lower_implicit_composition_relationships(
    object_nodes: Sequence[Mapping[str, Any]],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
) -> list[dict[str, Any]]:
    relationships: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for node in object_nodes:
        values = _values(node)
        construct = _string(values.get("_construct"), default="object")
        if construct not in _CONNECTOR_CONSTRUCTS:
            continue
        name = _string(node.get("name"))
        connector_id = object_id_by_name.get(name, _prefixed_id("obj", name, "object"))
        for edge_name, ref_value in (("from", _connection_ref(values, "from", "start", "a")), ("to", _connection_ref(values, "to", "end", "b"))):
            target = _scene_ref(ref_value, region_id_by_name, object_id_by_name, default="")
            if not target:
                continue
            key = (connector_id, target, edge_name)
            if key in seen:
                continue
            seen.add(key)
            relationships.append(
                {
                    "relationship_id": _prefixed_id("rel", f"{name}_{edge_name}_{target}", f"{name}_{edge_name}"),
                    "from": connector_id,
                    "to": target,
                    "type": "routes_to" if construct == "route" else "connects_to",
                    "description": f"{construct} {name} connects its {edge_name} endpoint to {target}.",
                }
            )
    return relationships


def _group_tags_by_member(scene: Mapping[str, Any]) -> dict[str, list[str]]:
    tags_by_member: dict[str, list[str]] = {}
    for group in _mapping_list(scene.get("groups")):
        values = _values(group)
        group_name = str(group.get("name") or "")
        group_tags = [f"group:{group_name}", *_string_list(values.get("semantic_tags") or values.get("tags"))]
        members = _string_list(values.get("members") or values.get("objects") or values.get("contains"))
        for member in members:
            tags_by_member.setdefault(member, []).extend(group_tags)
    return {name: _dedupe(tags) for name, tags in tags_by_member.items()}


def _lower_materials(
    program: Mapping[str, Any],
    material_bindings_by_object: Sequence[Sequence[Mapping[str, str]]],
) -> list[dict[str, Any]]:
    material_by_id: dict[str, dict[str, Any]] = {}
    for material in _mapping_list(program.get("materials")):
        values = _values(material)
        material_id = _prefixed_id("mat", material.get("name"), "material")
        record: dict[str, Any] = {
            "material_id": material_id,
            "name": _string(values.get("name"), default=_display_name(material_id)),
            "role": _string(values.get("role"), default="surface"),
        }
        if isinstance(values.get("pbr"), Mapping):
            record["pbr"] = dict(values["pbr"])
        material_by_id[material_id] = record
    for bindings in material_bindings_by_object:
        for binding in bindings:
            material_id = binding.get("material")
            if material_id and material_id not in material_by_id:
                material_by_id[material_id] = {
                    "material_id": material_id,
                    "name": _display_name(material_id),
                    "role": "surface",
                }
    return [material_by_id[key] for key in sorted(material_by_id)]


def _lower_relationships(
    relationships_in: Sequence[Mapping[str, Any]],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
) -> list[dict[str, Any]]:
    relationships: list[dict[str, Any]] = []
    for index, relationship in enumerate(relationships_in):
        values = _values(relationship)
        relationships.append(
            {
                "relationship_id": _prefixed_id("rel", relationship.get("name"), f"relationship_{index}"),
                "from": _scene_ref(values.get("from"), region_id_by_name, object_id_by_name, default="region_main"),
                "to": _scene_ref(values.get("to"), region_id_by_name, object_id_by_name, default="region_main"),
                "type": _enum(_string(relationship.get("type")) or values.get("type"), _RELATIONSHIP_TYPES, default="custom"),
                "description": _string(values.get("description"), default=""),
            }
        )
    return relationships


def _lower_attachment_relationships(
    attachments: Sequence[Mapping[str, Any]],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
) -> list[dict[str, Any]]:
    relationships: list[dict[str, Any]] = []
    for index, attachment in enumerate(attachments):
        values = _values(attachment)
        source_ref = _composition_target(values, "from", "source", "child", "object")
        target_ref = _composition_target(values, "to", "target", "parent", "on")
        source = _scene_ref(source_ref, region_id_by_name, object_id_by_name, default="")
        target = _scene_ref(target_ref, region_id_by_name, object_id_by_name, default="")
        if not source or not target:
            continue
        relationship_type = _attachment_relationship_type(values, _string(attachment.get("type")))
        socket_name = _string(values.get("socket") or values.get("target_socket") or values.get("slot"))
        description = _string(values.get("description"))
        if not description:
            description = f"{attachment.get('name') or f'attachment_{index}'} {relationship_type.replace('_', ' ')} {target}"
            if socket_name:
                description = f"{description} through socket {socket_name}"
        relationships.append(
            {
                "relationship_id": _prefixed_id("rel", attachment.get("name"), f"attachment_{index}"),
                "from": source,
                "to": target,
                "type": relationship_type,
                "description": description,
            }
        )
    return relationships


def _attachment_relationship_type(values: Mapping[str, Any], declared_type: str) -> str:
    mode = _snake_id(values.get("mode") or declared_type or values.get("type"), "attach")
    if mode in {"snap", "snaps", "snaps_to", "socket", "socket_snap", "dock", "docks"}:
        return "snaps_to"
    if mode in {"support", "supports", "rests_on"}:
        return "supports"
    if mode in {"connect", "connects", "connects_to", "route", "routes_to"}:
        return "connects_to"
    return "attached_to"


def _lower_cameras(
    scene: Mapping[str, Any],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
    objects: Sequence[Mapping[str, Any]],
    regions: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    default_target = _default_scene_target(objects, regions)
    cameras: list[dict[str, Any]] = []
    for index, camera in enumerate(_mapping_list(scene.get("cameras"))):
        values = _values(camera)
        record: dict[str, Any] = {
            "camera_id": _prefixed_id("camera", camera.get("name"), f"camera_{index}"),
            "target": _scene_ref(values.get("target"), region_id_by_name, object_id_by_name, default=default_target),
            "framing": _enum(_string(camera.get("framing")) or values.get("framing"), _CAMERA_FRAMINGS, default="inspection"),
            "purpose": _string(values.get("purpose"), default="inspect authored scene"),
        }
        if "transform" in values or "position" in values:
            record["transform"] = _transform(values)
        if "fov_degrees" in values:
            record["fov_degrees"] = _number(values.get("fov_degrees"), default=55.0)
        cameras.append(record)
    cameras.extend(_derived_cinematic_cameras(objects, region_id_by_name, object_id_by_name, default_target, existing_count=len(cameras)))
    if not cameras:
        cameras.append(
            {
                "camera_id": "camera_main",
                "target": default_target,
                "framing": "inspection",
                "purpose": "inspect authored scene",
                "transform": {"position": [8.0, 6.0, 10.0], "rotation": [0.0, 35.0, 0.0], "scale": [1.0, 1.0, 1.0]},
                "fov_degrees": 55.0,
            }
        )
    return cameras


def _derived_cinematic_cameras(
    objects: Sequence[Mapping[str, Any]],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
    default_target: str,
    *,
    existing_count: int,
) -> list[dict[str, Any]]:
    cameras: list[dict[str, Any]] = []
    for index, obj in enumerate(objects):
        state = obj.get("state") if isinstance(obj.get("state"), Mapping) else {}
        if not isinstance(state, Mapping):
            continue
        construct = _string(state.get("scene_construct") or state.get("camera_mode"))
        if state.get("camera_record") is not True and construct not in {"shot", "orbit_camera", "inspection_camera"}:
            continue
        object_id = _string(obj.get("object_id"), default=f"camera_source_{existing_count + index}")
        camera_id = _prefixed_id("camera", object_id, f"cinematic_{existing_count + index}")
        target = _scene_ref(state.get("target") or state.get("look_at"), region_id_by_name, object_id_by_name, default=default_target)
        record: dict[str, Any] = {
            "camera_id": camera_id,
            "target": target,
            "framing": _enum(_string(state.get("framing")), _CAMERA_FRAMINGS, default="inspection"),
            "purpose": _string(state.get("purpose"), default=f"cinematic camera from {construct or object_id}"),
        }
        transform = obj.get("transform")
        if isinstance(transform, Mapping):
            record["transform"] = deepcopy(dict(transform))
        if "fov_degrees" in state:
            record["fov_degrees"] = _number(state.get("fov_degrees"), default=55.0)
        cameras.append(record)
    return cameras


def _lower_lights(
    scene: Mapping[str, Any],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
    objects: Sequence[Mapping[str, Any]],
    regions: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    default_target = _default_scene_target(objects, regions)
    lights: list[dict[str, Any]] = []
    for index, light in enumerate(_mapping_list(scene.get("lights"))):
        values = _values(light)
        lights.append(
            {
                "light_id": _prefixed_id("light", light.get("name"), f"light_{index}"),
                "type": _enum(_string(light.get("type")) or values.get("type"), _LIGHT_TYPES, default="point"),
                "target": _scene_ref(values.get("target"), region_id_by_name, object_id_by_name, default=default_target),
                "color": _string(values.get("color"), default="#ffffff"),
                "intensity": _number(values.get("intensity"), default=1.0),
                "purpose": _string(values.get("purpose"), default="light authored scene"),
            }
        )
    return lights


def _lower_curiosity_anchors(scene: Mapping[str, Any], object_id_by_name: Mapping[str, str]) -> list[dict[str, Any]]:
    anchors: list[dict[str, Any]] = []
    for index, anchor in enumerate(_mapping_list(scene.get("curiosity_anchors"))):
        values = _values(anchor)
        attached_to = object_id_by_name.get(str(values.get("attached_to")), _prefixed_id("obj", values.get("attached_to"), "object"))
        anchors.append(
            {
                "anchor_id": _prefixed_id("curiosity", anchor.get("name"), f"anchor_{index}"),
                "visible_clue": _string(values.get("visible_clue"), default="authored clue"),
                "hidden_fact": _string(values.get("hidden_fact"), default="authored hidden fact"),
                "attached_to": attached_to,
                "suggested_user_actions": _string_list(values.get("suggested_user_actions")) or ["inspect"],
                "expansion_options": _expansion_options(values.get("expansion_options"), attached_to),
            }
        )
    return anchors


def _lower_hidden_state(scene: Mapping[str, Any], object_id_by_name: Mapping[str, str]) -> list[dict[str, Any]]:
    hidden: list[dict[str, Any]] = []
    for index, state in enumerate(_mapping_list(scene.get("hidden_state"))):
        values = _values(state)
        attached_to = object_id_by_name.get(str(values.get("attached_to")), _prefixed_id("obj", values.get("attached_to"), "object"))
        hidden.append(
            {
                "hidden_id": _prefixed_id("hidden", state.get("name"), f"state_{index}"),
                "attached_to": attached_to,
                "fact": _string(values.get("fact"), default="authored hidden state"),
                "reveal_condition": _string(values.get("reveal_condition"), default="inspect"),
                "visible": bool(values.get("visible", False)),
            }
        )
    return hidden


def _lower_exports(scene: Mapping[str, Any]) -> list[dict[str, Any]]:
    exports: list[dict[str, Any]] = []
    for export in _mapping_list(scene.get("exports")):
        values = _values(export)
        exports.append(
            {
                "target": _enum(_string(export.get("name")) or values.get("target"), {"lathe_source", "scene_graph", "scene_package", "blend", "glb", "usd", "fbx", "roblox_manifest", "godot_manifest", "unity_manifest", "unreal_manifest"}, default="scene_graph"),
                "format": _snake_id(values.get("format"), "json"),
                "path": _string(values.get("path"), default=f"{_snake_id(export.get('name'), 'scene_graph')}.json"),
            }
        )
    return exports


def _lower_style_bible(scene: Mapping[str, Any]) -> dict[str, list[str]]:
    style = next(iter(_mapping_list(scene.get("styles"))), {})
    values = _values(style)
    scene_values = _values(scene)
    return {
        "mood": _string_list(values.get("mood") or scene_values.get("mood")) or ["authored"],
        "palette": _string_list(values.get("palette") or scene_values.get("palette")) or ["neutral"],
        "materials": _string_list(values.get("materials") or scene_values.get("materials")) or ["authored"],
        "forms": _string_list(values.get("forms") or scene_values.get("forms")) or ["code_native"],
        "lighting": _string_list(values.get("lighting") or scene_values.get("lighting")) or ["readable"],
        "avoid": _string_list(values.get("avoid")),
    }


def _lower_layout(
    values: Mapping[str, Any],
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
) -> dict[str, Any] | None:
    layout = values.get("layout") if isinstance(values.get("layout"), Mapping) else values
    if not isinstance(layout, Mapping):
        return None
    payload: dict[str, Any] = {}
    if "room_size" in layout:
        payload["room_size"] = _vector3(layout.get("room_size"), [24.0, 8.0, 24.0])
    density = _string(layout.get("density"))
    if density in {"sparse", "medium", "dense"}:
        payload["density"] = density
    if "avoid_intersections" in layout:
        payload["avoid_intersections"] = bool(layout.get("avoid_intersections"))
    focal_point = layout.get("focal_point")
    if focal_point is not None:
        payload["focal_point"] = _scene_ref(focal_point, region_id_by_name, object_id_by_name, default="")
    main_path = layout.get("main_path")
    if isinstance(main_path, Mapping):
        payload["main_path"] = {
            "from": _scene_ref(main_path.get("from"), region_id_by_name, object_id_by_name, default=""),
            "to": _scene_ref(main_path.get("to"), region_id_by_name, object_id_by_name, default=""),
            "width": max(0.1, _number(main_path.get("width"), default=2.0)),
        }
    return payload or None


def _values(item: Mapping[str, Any]) -> Mapping[str, Any]:
    values = item.get("values")
    return values if isinstance(values, Mapping) else {}


def _mapping_list(value: Any) -> list[Mapping[str, Any]]:
    if not isinstance(value, list):
        return []
    return [item for item in value if isinstance(item, Mapping)]


def _nested(value: Mapping[str, Any], *path: str) -> Any:
    cursor: Any = value
    for part in path:
        if not isinstance(cursor, Mapping):
            return None
        cursor = cursor.get(part)
    return cursor


def _slug(value: Any, fallback: str) -> str:
    raw = str(value or fallback).split(".")[-1].lower()
    slug = re.sub(r"[^a-z0-9_]+", "_", raw).strip("_")
    if not slug:
        slug = fallback or "item"
    if not slug[0].isalpha():
        slug = f"x_{slug}"
    if len(slug) < 3:
        slug = f"{slug}_id"
    return slug[:80].rstrip("_") or fallback


def _snake_id(value: Any, fallback: str) -> str:
    return _slug(value, fallback)


def _optional_snake_id(value: Any) -> str | None:
    if value in {None, ""}:
        return None
    return _snake_id(value, "item")


def _prefixed_id(prefix: str, value: Any, fallback: str) -> str:
    raw = str(value or fallback)
    if raw.startswith(f"{prefix}_") and _IDENTIFIER_RE.match(raw):
        return raw[:80].rstrip("_")
    slug = _slug(raw, fallback)
    if slug.startswith(f"{prefix}_"):
        return slug[:80].rstrip("_")
    return f"{prefix}_{slug}"[:80].rstrip("_")


def _display_name(value: str) -> str:
    raw = re.sub(r"^(obj|region|rel|mat|light|camera|curiosity|hidden)_", "", value)
    return raw.replace("_", " ").strip().title() or value


def _string(value: Any, default: str = "") -> str:
    if isinstance(value, str):
        return value
    if value is None:
        return default
    return str(value)


def _number(value: Any, default: float = 0.0) -> float:
    if isinstance(value, int | float):
        return float(value)
    if isinstance(value, Mapping) and value.get("type") == "unit" and isinstance(value.get("value"), int | float):
        unit = value.get("unit")
        amount = float(value["value"])
        if unit == "m":
            return amount
        if unit == "cm":
            return amount / 100.0
        if unit == "mm":
            return amount / 1000.0
        return amount
    try:
        return float(str(value))
    except (TypeError, ValueError):
        return default


def _positive_int(value: Any, default: int) -> int:
    if isinstance(value, bool):
        return default
    try:
        result = int(value)
    except (TypeError, ValueError):
        return default
    return result if result > 0 else default


def _vector3(value: Any, default: Sequence[float]) -> list[float]:
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        values = list(value)
        if len(values) >= 3:
            return [_number(values[0], float(default[0])), _number(values[1], float(default[1])), _number(values[2], float(default[2]))]
    return [float(default[0]), float(default[1]), float(default[2])]


def _bounds(values: Mapping[str, Any], *, default_center: Sequence[float]) -> dict[str, list[float]]:
    bounds = values.get("bounds") if isinstance(values.get("bounds"), Mapping) else {}
    center = _vector3(
        bounds.get("center") if isinstance(bounds, Mapping) else values.get("center"),
        default_center,
    )
    size = _vector3(
        bounds.get("size") if isinstance(bounds, Mapping) else values.get("size"),
        [24.0, 8.0, 24.0],
    )
    return {"center": center, "size": [max(0.1, item) for item in size]}


def _transform(values: Mapping[str, Any]) -> dict[str, list[float]]:
    transform = values.get("transform") if isinstance(values.get("transform"), Mapping) else {}
    return {
        "position": _vector3(transform.get("position") if isinstance(transform, Mapping) else values.get("position"), [0.0, 0.0, 0.0]),
        "rotation": _vector3(transform.get("rotation") if isinstance(transform, Mapping) else values.get("rotation"), [0.0, 0.0, 0.0]),
        "scale": _vector3(transform.get("scale") if isinstance(transform, Mapping) else values.get("scale"), [1.0, 1.0, 1.0]),
    }


def _string_list(value: Any) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        return [str(item) for item in value if item not in {None, ""}]
    return []


def _dedupe(values: Sequence[str]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for value in values:
        if value and value not in seen:
            seen.add(value)
            out.append(value)
    return out


def _enum(value: Any, allowed: set[str], *, default: str) -> str:
    text = _snake_id(value, default)
    return text if text in allowed else default


def _scene_role(value: Any, *, construct: str) -> str:
    text = _snake_id(value, "")
    construct_spec = _WORLD_PIECE_CONSTRUCTS.get(construct)
    if construct_spec and not text:
        return str(construct_spec["role"])
    if construct == "terrain":
        return "environment_structure"
    if text in _SCENE_ROLES:
        return text
    tokens = set(text.split("_"))
    if tokens & {"building", "room", "interior", "wall", "floor", "door", "window", "bridge", "tower", "architecture"}:
        return "architecture"
    if tokens & {"road", "path", "street", "stairs", "ladder", "navigation"}:
        return "navigation"
    if tokens & {"light", "lamp", "torch", "fixture"}:
        return "light_fixture"
    if tokens & {"hero", "weapon", "vehicle", "boat", "car", "drone", "machine"}:
        return "hero_prop"
    if tokens & {"button", "lever", "terminal", "interactive"}:
        return "interactive"
    if tokens & {"clue", "story", "narrative"}:
        return "narrative_clue"
    if tokens & {"terrain", "environment", "prop", "set", "city", "world"}:
        return "environment_structure"
    return "dressing_prop"


def _scene_ref(
    value: Any,
    region_id_by_name: Mapping[str, str],
    object_id_by_name: Mapping[str, str],
    *,
    default: str,
    prefix: str | None = None,
) -> str:
    text = _string(value)
    if not text:
        return default
    if text in region_id_by_name:
        return region_id_by_name[text]
    if text in object_id_by_name:
        return object_id_by_name[text]
    if re.match(r"^(obj|region|camera|light|curiosity|hidden)_[a-z0-9_]{3,80}$", text):
        return text
    if prefix == "region":
        return _prefixed_id("region", text, "region")
    return _prefixed_id("obj", text, "object")


def _default_scene_target(objects: Sequence[Mapping[str, Any]], regions: Sequence[Mapping[str, Any]]) -> str:
    if objects:
        return _string(objects[0].get("object_id"), default="obj_scene_anchor")
    if regions:
        return _string(regions[0].get("region_id"), default="region_main")
    return "region_main"


def _material_bindings(values: Mapping[str, Any]) -> list[dict[str, str]]:
    bindings: list[dict[str, str]] = []
    raw = values.get("material_bindings")
    if isinstance(raw, Mapping):
        for slot, material in sorted(raw.items(), key=lambda item: str(item[0])):
            bindings.append({"slot": _snake_id(slot, "slot"), "material": _prefixed_id("mat", material, "material")})
    elif isinstance(raw, list):
        for item in raw:
            if isinstance(item, Mapping):
                bindings.append(
                    {
                        "slot": _snake_id(item.get("slot"), "slot"),
                        "material": _prefixed_id("mat", item.get("material"), "material"),
                    }
                )
    if "material" in values:
        bindings.append({"slot": "default", "material": _prefixed_id("mat", values.get("material"), "material")})
    return bindings


def _state(value: Any) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        return {}
    out: dict[str, Any] = {}
    for key, item in value.items():
        if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
            continue
        normalized = _surface_value(item)
        if isinstance(normalized, str | int | float | bool | list | dict) or normalized is None:
            out[key] = normalized
    return out


def _child_module_state(values: Mapping[str, Any]) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for key, value in values.items():
        if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
            continue
        if not _is_child_module_state_key(key, value):
            continue
        normalized = _surface_value(value)
        if isinstance(normalized, str | int | float | bool | list | dict) or normalized is None:
            out[key] = normalized
    return out


def _is_child_module_state_key(key: str, value: Any) -> bool:
    if key in _CHILD_MODULE_MAPPING_KEYS or key in _CHILD_MODULE_DIRECT_KEYS:
        return True
    if key in {"modules", "module"}:
        return False
    for kind in _CHILD_MODULE_KINDS:
        if key in {
            f"{kind}_module",
            f"{kind}_modules",
            f"{kind}_template",
            f"{kind}_templates",
            f"{kind}_module_templates",
            f"{kind}_archetype",
            f"{kind}_slot_count",
        }:
            return True
        if key.startswith(f"{kind}_") and "_module_" in key:
            return True
        if key.startswith(f"{kind}_slot_") and key.endswith(("_module", "_template", "_archetype")):
            return True
        if key.startswith(f"{kind}_") and key.endswith(("_position", "_facing", "_facing_degrees", "_clearance")):
            return True
    return key.startswith("child_module_") and isinstance(value, str | int | float | bool | list | dict)


def _surface_value(value: Any) -> str | int | float | bool | None | list[Any] | dict[str, Any]:
    if isinstance(value, str | int | float | bool) or value is None:
        return value
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        return [item for item in (_surface_value(item) for item in value) if not isinstance(item, dict)]
    if isinstance(value, Mapping):
        out: dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
                continue
            normalized = _surface_value(item)
            if isinstance(normalized, str | int | float | bool | list | dict) or normalized is None:
                out[key] = normalized
        return out
    return str(value)


def _merge_surface_overrides(target: dict[str, Any], source: Mapping[str, Any]) -> None:
    for key, value in source.items():
        if not isinstance(key, str) or not _IDENTIFIER_RE.match(key):
            continue
        normalized = _surface_value(value)
        if isinstance(normalized, dict) and isinstance(target.get(key), dict):
            merged = dict(target[key])
            merged.update(normalized)
            target[key] = merged
        elif isinstance(normalized, list) and isinstance(target.get(key), list):
            target[key] = _dedupe([str(item) for item in [*target[key], *normalized]])
        else:
            target[key] = normalized


def _surface_overrides(values: Mapping[str, Any], *, construct: str) -> dict[str, Any]:
    overrides: dict[str, Any] = {}
    defaults = _CONSTRUCT_SURFACE_DEFAULTS.get(construct)
    if isinstance(defaults, Mapping):
        _merge_surface_overrides(overrides, defaults)
    raw = values.get("surface_overrides")
    if isinstance(raw, Mapping):
        _merge_surface_overrides(overrides, raw)
    surface = values.get("surface")
    if isinstance(surface, Mapping):
        _merge_surface_overrides(overrides, surface)
    for key in sorted(_SURFACE_OVERRIDE_KEYS):
        if key not in values:
            continue
        target_key = "material_layers" if key == "surface_layers" else "wear_story" if key == "wear" else key
        _merge_surface_overrides(overrides, {target_key: values[key]})
    return overrides


def _affordances(values: Mapping[str, Any]) -> list[dict[str, Any]]:
    raw = values.get("affordances")
    gameplay = values.get("gameplay") if isinstance(values.get("gameplay"), Mapping) else {}
    if raw is None and isinstance(gameplay, Mapping):
        raw = gameplay.get("affordances")
    records: list[dict[str, Any]] = []
    if isinstance(raw, Mapping):
        iterable = raw.items()
    elif isinstance(raw, list):
        iterable = [(item.get("id") if isinstance(item, Mapping) else None, item) for item in raw]
    else:
        iterable = []
    for name, item in iterable:
        if not isinstance(item, Mapping):
            continue
        record: dict[str, Any] = {
            "id": _snake_id(item.get("id") or name, "affordance"),
            "action": _string(item.get("action"), default="interact"),
        }
        if item.get("reveals"):
            record["reveals"] = _prefixed_id("obj", item.get("reveals"), "object")
        if item.get("requires"):
            record["requires"] = _string(item.get("requires"))
        records.append(record)
    return records


def _expansion_options(value: Any, attached_to: str) -> list[dict[str, Any]]:
    options: list[dict[str, Any]] = []
    if isinstance(value, Mapping):
        iterable = value.items()
    elif isinstance(value, list):
        iterable = [(item.get("id") if isinstance(item, Mapping) else None, item) for item in value]
    else:
        iterable = []
    for name, item in iterable:
        if not isinstance(item, Mapping):
            continue
        options.append(
            {
                "id": _snake_id(item.get("id") or name, "option"),
                "label": _string(item.get("label"), default="Expand"),
                "target_scope": _string(item.get("target_scope"), default=attached_to),
                "required_assets": _string_list(item.get("required_assets")),
                "continuity_constraints": _string_list(item.get("continuity_constraints")),
            }
        )
    return options or [{"id": "inspect_more", "label": "Inspect more", "target_scope": attached_to}]


def extract_scene_graph_payload(source_text: str) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Extract the embedded Scene Graph JSON payload from generated source."""
    lines = source_text.splitlines()
    begin_indices = [index for index, line in enumerate(lines) if line.strip() == SCENE_GRAPH_PAYLOAD_BEGIN]
    end_indices = [index for index, line in enumerate(lines) if line.strip() == SCENE_GRAPH_PAYLOAD_END]

    if not begin_indices and not end_indices:
        return {}, [_missing_payload_diagnostic(source_text)]
    if len(begin_indices) != 1 or len(end_indices) != 1:
        return {}, [
            source_diagnostic(
                "SS1003",
                "malformed_scene_graph_payload_fence",
                "/payload",
                (
                    "Scene source must contain exactly one Scene Graph payload "
                    f"fence pair: {SCENE_GRAPH_PAYLOAD_BEGIN} and {SCENE_GRAPH_PAYLOAD_END}."
                ),
                details={"begin_count": len(begin_indices), "end_count": len(end_indices)},
            )
        ]

    begin_index = begin_indices[0]
    end_index = end_indices[0]
    if end_index <= begin_index:
        return {}, [
            source_diagnostic(
                "SS1003",
                "malformed_scene_graph_payload_fence",
                "/payload",
                "Scene Graph payload end fence must appear after the begin fence.",
                details={"begin_line": begin_index + 1, "end_line": end_index + 1},
            )
        ]

    json_text = "\n".join(_payload_json_line(line) for line in lines[begin_index + 1 : end_index])
    if not json_text.strip():
        return {}, [
            source_diagnostic(
                "SS1004",
                "empty_scene_graph_payload_json",
                "/payload",
                "Embedded Scene Graph payload is empty.",
                details={"begin_line": begin_index + 1, "end_line": end_index + 1},
            )
        ]

    try:
        raw = json.loads(json_text)
    except json.JSONDecodeError as exc:
        return {}, [
            source_diagnostic(
                "SS1004",
                "invalid_scene_graph_payload_json",
                "/payload",
                f"Embedded Scene Graph payload is invalid JSON: {exc.msg} at line {exc.lineno}, column {exc.colno}.",
                details={
                    "payload_line": exc.lineno,
                    "payload_column": exc.colno,
                    "source_line": begin_index + exc.lineno + 1,
                },
                source_span={
                    "line": begin_index + exc.lineno + 1,
                    "column": exc.colno,
                    "end_line": begin_index + exc.lineno + 1,
                    "end_column": exc.colno + 1,
                },
                repair_hint="Fix the embedded Scene Graph JSON syntax, then rerun source conversion.",
            )
        ]
    if not isinstance(raw, dict):
        return {}, [
            source_diagnostic(
                "SS1005",
                "scene_graph_payload_root_not_object",
                "/payload",
                f"Embedded Scene Graph payload root must be a JSON object, got {type(raw).__name__}.",
            )
        ]
    return raw, []


def _payload_comment_line(line: str) -> str:
    return f"// {line}" if line else "//"


def _payload_json_line(line: str) -> str:
    stripped = line.lstrip()
    if not stripped.startswith("//"):
        return line
    payload = stripped[2:]
    if payload.startswith(" "):
        payload = payload[1:]
    return payload


def _missing_payload_diagnostic(source_text: str) -> dict[str, Any]:
    generated_bridge_source = SCENE_SOURCE_BRIDGE_VERSION in source_text
    if _looks_like_hand_authored_scene_source(source_text) and not generated_bridge_source:
        return source_diagnostic(
            "SS1002",
            "unsupported_hand_authored_scene_source",
            "/",
            (
                "This Phase 7 bridge only accepts generated scene source with an "
                "embedded Scene Graph JSON payload. Full hand-authored scene "
                "syntax parsing is deferred to the later parser implementation."
            ),
            details={"required_begin_fence": SCENE_GRAPH_PAYLOAD_BEGIN},
            repair_hint=(
                "Use generated scene source from lathe scene scene-graph-to-source, or provide Scene Graph JSON directly."
            ),
        )
    return source_diagnostic(
        "SS1001",
        "missing_scene_graph_payload",
        "/",
        (
            "Scene source does not contain an embedded Scene Graph JSON payload. "
            f"Expected a {SCENE_GRAPH_PAYLOAD_BEGIN} block."
        ),
        details={"required_begin_fence": SCENE_GRAPH_PAYLOAD_BEGIN},
        repair_hint="Add one embedded Scene Graph JSON payload block, then rerun source conversion.",
    )


def _looks_like_hand_authored_scene_source(source_text: str) -> bool:
    for line in source_text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("//"):
            continue
        if _HAND_AUTHORED_SCENE_RE.match(stripped) or _BUILDER_MODE_HAND_AUTHORED_SCENE_RE.match(stripped):
            return True
    return False


def _source_header(scene_graph: Mapping[str, Any]) -> list[str]:
    scene_id = _identifier_or_fallback(scene_graph.get("scene_id"), "scene")
    return [
        f"// Generated by Lathe {SCENE_SOURCE_BRIDGE_VERSION}.",
        "// This is a JSON-first source bridge, not the core .lth scene parser.",
        "// The scene-shaped text is for review; the embedded JSON block preserves all v1 fields.",
        f"module wonder.generated.{scene_id}",
    ]


def _scene_preview(scene_graph: Mapping[str, Any]) -> list[str]:
    scene_id = _identifier_or_fallback(scene_graph.get("scene_id"), "scene")
    lines = [f"scene {scene_id} {{"]
    _append_assignment(lines, 1, "version", scene_graph.get("version"))
    if isinstance(scene_graph.get("brief_id"), str):
        _append_assignment(lines, 1, "brief", scene_graph["brief_id"])
    _append_assignment(lines, 1, "prompt", scene_graph.get("prompt"), force_string=True)
    lines.append("")

    style_bible = scene_graph.get("style_bible")
    if isinstance(style_bible, Mapping):
        lines.extend(_style_preview(style_bible))
        lines.append("")

    for region in _mapping_items(scene_graph, "regions"):
        lines.extend(_region_preview(region))
        lines.append("")

    for obj in _mapping_items(scene_graph, "objects"):
        lines.extend(_object_preview(obj))
        lines.append("")

    for relationship in _mapping_items(scene_graph, "relationships"):
        lines.extend(_relationship_preview(relationship))
        lines.append("")

    for light in _mapping_items(scene_graph, "lights"):
        lines.extend(_light_preview(light))
        lines.append("")

    for camera in _mapping_items(scene_graph, "cameras"):
        lines.extend(_camera_preview(camera))
        lines.append("")

    for anchor in _mapping_items(scene_graph, "curiosity_anchors"):
        lines.extend(_curiosity_anchor_preview(anchor))
        lines.append("")

    for hidden in _mapping_items(scene_graph, "hidden_state"):
        lines.extend(_hidden_state_preview(hidden))
        lines.append("")

    for export in _mapping_items(scene_graph, "exports"):
        lines.extend(_export_preview(export))
        lines.append("")

    lines.extend(_json_only_summary(scene_graph))
    lines.append("}")
    return lines


def _style_preview(style_bible: Mapping[str, Any]) -> list[str]:
    lines = ["  style scene_style {"]
    for field in ("mood", "palette", "materials", "forms", "lighting", "avoid"):
        if field in style_bible:
            _append_assignment(lines, 2, field, style_bible[field])
    lines.append("  }")
    return lines


def _region_preview(region: Mapping[str, Any]) -> list[str]:
    region_id = _identifier_or_fallback(region.get("region_id"), "region")
    region_type = _identifier_or_fallback(region.get("type"), "region_type")
    lines = [f"  region {region_id}: {region_type} {{"]
    for field in ("name", "purpose", "mood"):
        _append_assignment(lines, 2, field, region.get(field), force_string=True)
    bounds = region.get("bounds")
    if isinstance(bounds, Mapping):
        _append_assignment(lines, 2, "bounds.center", bounds.get("center"))
        _append_assignment(lines, 2, "bounds.size", bounds.get("size"))
    _append_assignment(lines, 2, "semantic_tags", region.get("semantic_tags"))
    lines.append("  }")
    return lines


def _object_preview(obj: Mapping[str, Any]) -> list[str]:
    object_id = _identifier_or_fallback(obj.get("object_id"), "obj")
    role = _identifier_or_fallback(obj.get("role"), "scene_role")
    lathe_asset = _identifier_or_fallback(obj.get("lathe_asset"), "asset")
    lines = [f"  object {object_id}: {role} from {lathe_asset} {{"]
    _append_assignment(lines, 2, "name", obj.get("name"), force_string=True)
    for field in ("region", "source_family", "source_kit", "variant"):
        if field in obj:
            _append_assignment(lines, 2, field, obj[field])
    transform = obj.get("transform")
    if isinstance(transform, Mapping):
        for field in ("position", "rotation", "scale"):
            _append_assignment(lines, 2, f"transform.{field}", transform.get(field))
    for binding in _nested_mapping_items(obj, "material_bindings"):
        slot = binding.get("slot")
        material = binding.get("material")
        if isinstance(slot, str) and _IDENTIFIER_RE.match(slot):
            _append_assignment(lines, 2, f"material_bindings.{slot}", material)
    _append_assignment(lines, 2, "semantic_tags", obj.get("semantic_tags"))
    lines.extend(_object_gameplay_preview(obj))
    state = obj.get("state")
    if isinstance(state, Mapping):
        for key, value in state.items():
            if isinstance(key, str) and _IDENTIFIER_RE.match(key):
                if isinstance(value, Mapping):
                    for nested_key, nested_value in value.items():
                        if isinstance(nested_key, str) and _IDENTIFIER_RE.match(nested_key):
                            _append_assignment(lines, 2, f"state.{key}.{nested_key}", nested_value)
                else:
                    _append_assignment(lines, 2, f"state.{key}", value)
    surface_overrides = obj.get("surface_overrides")
    if isinstance(surface_overrides, Mapping):
        for key, value in surface_overrides.items():
            if isinstance(key, str) and _IDENTIFIER_RE.match(key):
                if isinstance(value, Mapping):
                    for nested_key, nested_value in value.items():
                        if isinstance(nested_key, str) and _IDENTIFIER_RE.match(nested_key):
                            _append_assignment(lines, 2, f"surface_overrides.{key}.{nested_key}", nested_value)
                else:
                    _append_assignment(lines, 2, f"surface_overrides.{key}", value)
    lines.append("  }")
    return lines


def _object_gameplay_preview(obj: Mapping[str, Any]) -> list[str]:
    direct_gameplay = obj.get("gameplay")
    affordances = _nested_mapping_items(obj, "affordances")
    if not isinstance(direct_gameplay, Mapping) and not affordances:
        return []

    lines = ["    gameplay {"]
    if isinstance(direct_gameplay, Mapping):
        for key, value in direct_gameplay.items():
            if isinstance(key, str) and _IDENTIFIER_RE.match(key):
                _append_assignment(lines, 3, key, value)
    for affordance in affordances:
        affordance_id = _identifier_or_fallback(affordance.get("id"), "affordance")
        for field in ("action", "reveals", "requires"):
            _append_assignment(lines, 3, f"affordances.{affordance_id}.{field}", affordance.get(field))
    lines.append("    }")
    return lines


def _relationship_preview(relationship: Mapping[str, Any]) -> list[str]:
    relationship_id = _identifier_or_fallback(relationship.get("relationship_id"), "rel")
    relationship_type = _identifier_or_fallback(relationship.get("type"), "relationship_type")
    lines = [f"  relationship {relationship_id}: {relationship_type} {{"]
    for field in ("from", "to"):
        _append_assignment(lines, 2, field, relationship.get(field))
    if "description" in relationship:
        _append_assignment(lines, 2, "description", relationship["description"], force_string=True)
    lines.append("  }")
    return lines


def _light_preview(light: Mapping[str, Any]) -> list[str]:
    light_id = _identifier_or_fallback(light.get("light_id"), "light")
    light_type = _identifier_or_fallback(light.get("type"), "light_type")
    lines = [f"  lighting_plan {light_id}: {light_type} {{"]
    if "target" in light:
        _append_assignment(lines, 2, "target", light["target"])
    _append_assignment(lines, 2, "color", light.get("color"), force_string=True)
    _append_assignment(lines, 2, "intensity", light.get("intensity"))
    _append_assignment(lines, 2, "purpose", light.get("purpose"), force_string=True)
    lines.append("  }")
    return lines


def _camera_preview(camera: Mapping[str, Any]) -> list[str]:
    camera_id = _identifier_or_fallback(camera.get("camera_id"), "camera")
    framing = _identifier_or_fallback(camera.get("framing"), "framing")
    lines = [f"  camera_intent {camera_id}: {framing} {{"]
    _append_assignment(lines, 2, "target", camera.get("target"))
    _append_assignment(lines, 2, "purpose", camera.get("purpose"), force_string=True)
    transform = camera.get("transform")
    if isinstance(transform, Mapping):
        for field in ("position", "rotation", "scale"):
            _append_assignment(lines, 2, f"transform.{field}", transform.get(field))
    if "fov_degrees" in camera:
        _append_assignment(lines, 2, "fov_degrees", camera["fov_degrees"])
    lines.append("  }")
    return lines


def _curiosity_anchor_preview(anchor: Mapping[str, Any]) -> list[str]:
    anchor_id = _identifier_or_fallback(anchor.get("anchor_id"), "curiosity_anchor")
    lines = [f"  curiosity_anchor {anchor_id} {{"]
    for field in ("attached_to", "visible_clue", "hidden_fact", "suggested_user_actions"):
        _append_assignment(lines, 2, field, anchor.get(field), force_string=field in {"visible_clue", "hidden_fact"})
    for option in _nested_mapping_items(anchor, "expansion_options"):
        option_id = _identifier_or_fallback(option.get("id"), "option")
        for field in ("label", "target_scope", "required_assets", "continuity_constraints"):
            _append_assignment(
                lines,
                2,
                f"expansion_options.{option_id}.{field}",
                option.get(field),
                force_string=field == "label",
            )
    lines.append("  }")
    return lines


def _hidden_state_preview(hidden: Mapping[str, Any]) -> list[str]:
    hidden_id = _identifier_or_fallback(hidden.get("hidden_id"), "hidden_state")
    lines = [f"  hidden_state {hidden_id} {{"]
    _append_assignment(lines, 2, "attached_to", hidden.get("attached_to"))
    _append_assignment(lines, 2, "fact", hidden.get("fact"), force_string=True)
    _append_assignment(lines, 2, "reveal_condition", hidden.get("reveal_condition"), force_string=True)
    _append_assignment(lines, 2, "visible", hidden.get("visible"))
    lines.append("  }")
    return lines


def _export_preview(export: Mapping[str, Any]) -> list[str]:
    target = _identifier_or_fallback(export.get("target"), "export_target")
    lines = [f"  export {target} {{"]
    _append_assignment(lines, 2, "format", export.get("format"))
    _append_assignment(lines, 2, "path", export.get("path"), force_string=True)
    lines.append("  }")
    return lines


def _json_only_summary(scene_graph: Mapping[str, Any]) -> list[str]:
    json_only_counts = {
        "layout": 1 if isinstance(scene_graph.get("layout"), Mapping) else 0,
        "materials": len(scene_graph.get("materials", [])) if isinstance(scene_graph.get("materials"), list) else 0,
        "build_artifacts": len(scene_graph.get("build_artifacts", []))
        if isinstance(scene_graph.get("build_artifacts"), list)
        else 0,
        "memory_events": len(scene_graph.get("memory_events", []))
        if isinstance(scene_graph.get("memory_events"), list)
        else 0,
    }
    summary = ", ".join(f"{name}={count}" for name, count in json_only_counts.items())
    return [
        "  // JSON-only v1 data is preserved below, including object provenance, export",
        "  // metadata, material definitions, build artifacts, and memory.",
        f"  // Embedded payload summary: {summary}.",
    ]


def _json_only_preview_paths(scene_graph: Mapping[str, Any]) -> list[str]:
    paths: list[str] = []
    for collection in (
        "layout",
        "materials",
        "build_artifacts",
        "memory_events",
    ):
        value = scene_graph.get(collection)
        if isinstance(value, Mapping) or (isinstance(value, list) and value):
            paths.append(f"/{collection}")

    for index, obj in enumerate(_mapping_items(scene_graph, "objects")):
        if isinstance(obj.get("provenance"), Mapping):
            paths.append(f"/objects/{index}/provenance")

    for index, export in enumerate(_mapping_items(scene_graph, "exports")):
        if isinstance(export.get("metadata"), Mapping):
            paths.append(f"/exports/{index}/metadata")
    return paths


def _append_assignment(
    lines: list[str],
    indent: int,
    path: str,
    value: Any,
    *,
    force_string: bool = False,
) -> None:
    if value is None:
        return
    lines.append(f"{'  ' * indent}{path} = {_source_value(value, force_string=force_string)}")


def _source_value(value: Any, *, force_string: bool = False) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int | float):
        return json.dumps(value, allow_nan=False)
    if isinstance(value, str):
        if not force_string and _IDENTIFIER_RE.match(value):
            return value
        return json.dumps(value, ensure_ascii=True)
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        return "[" + ", ".join(_source_value(item) for item in value) + "]"
    return json.dumps(value, ensure_ascii=True, sort_keys=False, allow_nan=False)


def _mapping_items(scene_graph: Mapping[str, Any], collection: str) -> list[Mapping[str, Any]]:
    raw = scene_graph.get(collection, [])
    if not isinstance(raw, list):
        return []
    return [item for item in raw if isinstance(item, Mapping)]


def _nested_mapping_items(item: Mapping[str, Any], collection: str) -> list[Mapping[str, Any]]:
    raw = item.get(collection, [])
    if not isinstance(raw, list):
        return []
    return [child for child in raw if isinstance(child, Mapping)]


def _identifier_or_fallback(value: Any, fallback: str) -> str:
    if isinstance(value, str) and _IDENTIFIER_RE.match(value):
        return value
    return fallback


